let tiles = [];
let groutEdges = [];
let ledgeAngle = -13;
let cosA, sinA;

// Transform from ledge-local (u, v) to canvas (x, y)
// v is foreshortened (0.82) to create the tilted overhead perspective view
function toScreen(u, v) {
  let vx = v * 0.82;
  let cx = 600 + u * cosA - vx * sinA;
  let cy = 500 + u * sinA + vx * cosA;
  return [cx, cy];
}

// Deterministic hand-cut wobble for zellige vertices
function wobblePt(x, y, amp = 2.2) {
  let nx = (noise(x * 0.018, y * 0.018, 1.7) - 0.5) * 2 * amp;
  let ny = (noise(x * 0.018, y * 0.018, 9.3) - 0.5) * 2 * amp;
  return [x + nx, y + ny];
}

// Shrink a polygon toward its centroid by `insetPx` and add hand-chiseled irregularity
function insetAndWobble(pts, insetPx = 3.6, wobbleAmp = 2.0) {
  let cx = 0, cy = 0;
  for (let p of pts) {
    cx += p[0];
    cy += p[1];
  }
  cx /= pts.length;
  cy /= pts.length;

  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let dx = pts[i][0] - cx;
    let dy = pts[i][1] - cy;
    let d = Math.hypot(dx, dy) || 1;
    let shrink = Math.min(insetPx, d * 0.35);
    let px = pts[i][0] - (dx / d) * shrink;
    let py = pts[i][1] - (dy / d) * shrink;
    let w = wobblePt(px, py, wobbleAmp);
    // Subdivide long edges slightly for organic hand-cut terracotta feel
    out.push(w);
    let next = pts[(i + 1) % pts.length];
    let ndx = next[0] - cx;
    let ndy = next[1] - cy;
    let nd = Math.hypot(ndx, ndy) || 1;
    let nShrink = Math.min(insetPx, nd * 0.35);
    let npx = next[0] - (ndx / nd) * nShrink;
    let npy = next[1] - (ndy / nd) * nShrink;
    let edgeLen = Math.hypot(npx - px, npy - py);
    if (edgeLen > 42) {
      let mx = (px + npx) * 0.5;
      let my = (py + npy) * 0.5;
      out.push(wobblePt(mx, my, wobbleAmp * 0.85));
    }
  }
  return { pts: out, cx, cy };
}

function scalePoly(pts, cx, cy, s, shiftX = 0, shiftY = 0) {
  return pts.map(p => [
    cx + (p[0] - cx) * s + shiftX,
    cy + (p[1] - cy) * s + shiftY
  ]);
}

function drawBrushPoly(pts, curvature = 0.08) {
  brush.beginShape(curvature);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(8819);

  cosA = cos(ledgeAngle);
  sinA = sin(ledgeAngle);

  // Soft custom brushes for steam haze, glossy highlights, and soap foam
  brush.add("steamHaze", {
    type: "spray",
    weight: 38,
    scatter: 3.8,
    opacity: 9,
    spacing: 0.9,
    pressure: [0.4, 1.2, 0.4],
    rotate: "random"
  });

  brush.add("glossNib", {
    type: "default",
    weight: 2.2,
    scatter: 0.05,
    sharpness: 0.85,
    grain: 4,
    opacity: 210,
    spacing: 0.18,
    pressure: [0.2, 1.3, 0.2],
    rotate: "natural",
    noise: 0.25
  });

  brush.add("groutMarker", {
    type: "marker",
    weight: 3.4,
    scatter: 0.12,
    opacity: 145,
    spacing: 0.25,
    pressure: [0.85, 1.0, 0.85],
    rotate: "natural",
    markerTip: false,
    noise: 0.4
  });

  buildZelligeGeometry();
}

function buildZelligeGeometry() {
  let D = 260; // Grid period in ledge-local units
  let Rtip = 0.335;
  let rval = 0.248;

  function starTip(i, j, k) {
    let ang = k * 45;
    let u = (i + Rtip * cos(ang)) * D;
    let v = (j + Rtip * sin(ang)) * D;
    return toScreen(u, v);
  }

  function starVal(i, j, k) {
    let ang = (k + 0.5) * 45;
    let u = (i + rval * cos(ang)) * D;
    let v = (j + rval * sin(ang)) * D;
    return toScreen(u, v);
  }

  function gridPt(uNorm, vNorm) {
    return toScreen(uNorm * D, vNorm * D);
  }

  function addChip(rawPts, role, i, j, subIndex = 0) {
    // Check if chip is within visible ledge top (vNorm <= 1.75) and canvas bounds
    let sx = 0, sy = 0;
    for (let p of rawPts) {
      sx += p[0];
      sy += p[1];
    }
    sx /= rawPts.length;
    sy /= rawPts.length;
    if (sx < -130 || sx > 1330 || sy < -130 || sy > 1180) return;

    // Record raw edges for marker grout lines
    for (let k = 0; k < rawPts.length; k++) {
      let p1 = rawPts[k];
      let p2 = rawPts[(k + 1) % rawPts.length];
      groutEdges.push([p1, p2]);
    }

    let wobbled = insetAndWobble(rawPts, 3.8, 1.9);
    let pooled = scalePoly(
      wobbled.pts,
      wobbled.cx,
      wobbled.cy,
      0.66,
      random(-2.5, 2.5),
      random(1.0, 3.5)
    );

    tiles.push({
      pts: wobbled.pts,
      pooledPts: pooled,
      cx: wobbled.cx,
      cy: wobbled.cy,
      role,
      i,
      j,
      subIndex,
      seed: random(1000)
    });
  }

  // Generate interlocking 8-point star tessellation across the ledge top
  // Ledge lip is at vNorm = 1.85
  for (let j = -3; j <= 1; j++) {
    for (let i = -3; i <= 3; i++) {
      // 1. Main 8-Point Star at (i, j)
      if (j <= 1) {
        let starPts = [];
        for (let k = 0; k < 8; k++) {
          starPts.push(starTip(i, j, k));
          starPts.push(starVal(i, j, k));
        }
        let starColor = ((i + j) & 1) === 0 ? "emerald" : "turquoise";
        addChip(starPts, starColor, i, j, 0);
      }

      // 2. Horizontal Saft (pointed hexagonal connector) between (i, j) and (i+1, j)
      if (j <= 1) {
        let hSaft = [
          starTip(i, j, 0),
          starVal(i, j, 0),
          gridPt(i + 0.5, j + 0.142),
          starVal(i + 1, j, 3),
          starTip(i + 1, j, 4),
          starVal(i + 1, j, 4),
          gridPt(i + 0.5, j - 0.142),
          starVal(i, j, 7)
        ];
        addChip(hSaft, "manganese", i, j, 1);
      }

      // 3. Vertical Saft between (i, j) and (i, j+1)
      if (j <= 0) {
        let vSaft = [
          starTip(i, j, 2),
          starVal(i, j, 1),
          gridPt(i + 0.142, j + 0.5),
          starVal(i, j + 1, 6),
          starTip(i, j + 1, 6),
          starVal(i, j + 1, 5),
          gridPt(i - 0.142, j + 0.5),
          starVal(i, j, 2)
        ];
        addChip(vSaft, "manganese", i, j, 2);
      }

      // 4. Interlocking Cross Petals (Cream) + Center Jewel at (i+0.5, j+0.5)
      if (j <= 0) {
        let qNW = gridPt(i + 0.405, j + 0.405);
        let qN  = gridPt(i + 0.500, j + 0.375);
        let qNE = gridPt(i + 0.595, j + 0.405);
        let qE  = gridPt(i + 0.625, j + 0.500);
        let qSE = gridPt(i + 0.595, j + 0.595);
        let qS  = gridPt(i + 0.500, j + 0.625);
        let qSW = gridPt(i + 0.405, j + 0.595);
        let qW  = gridPt(i + 0.375, j + 0.500);

        // Central octagonal jewel
        let jewel = [qNW, qN, qNE, qE, qSE, qS, qSW, qW];
        let jewelColor = ((i + j) & 1) === 0 ? "turquoise" : "emerald";
        addChip(jewel, jewelColor, i, j, 3);

        // 4 Cream Petals forming the luminous star-cross around the jewel
        let petalN = [
          qNW,
          starTip(i, j, 1),
          starVal(i, j, 0),
          gridPt(i + 0.5, j + 0.142),
          starVal(i + 1, j, 3),
          starTip(i + 1, j, 3),
          qNE,
          qN
        ];
        let petalE = [
          qNE,
          starTip(i + 1, j, 3),
          starVal(i + 1, j, 2),
          gridPt(i + 0.858, j + 0.5),
          starVal(i + 1, j + 1, 5),
          starTip(i + 1, j + 1, 5),
          qSE,
          qE
        ];
        let petalS = [
          qSE,
          starTip(i + 1, j + 1, 5),
          starVal(i + 1, j + 1, 4),
          gridPt(i + 0.5, j + 0.858),
          starVal(i, j + 1, 7),
          starTip(i, j + 1, 7),
          qSW,
          qS
        ];
        let petalW = [
          qSW,
          starTip(i, j + 1, 7),
          starVal(i, j + 1, 6),
          gridPt(i + 0.142, j + 0.5),
          starVal(i, j, 1),
          starTip(i, j, 1),
          qNW,
          qW
        ];
        addChip(petalN, "cream", i, j, 4);
        addChip(petalE, "cream", i, j, 5);
        addChip(petalS, "cream", i, j, 6);
        addChip(petalW, "cream", i, j, 7);
      }
    }
  }

  // Partial border strip along the front edge of the ledge (between vNorm = 1.0 and 1.42)
  for (let i = -3; i <= 3; i++) {
    let j = 1;
    let qNW = gridPt(i + 0.405, j + 0.405);
    let qN  = gridPt(i + 0.500, j + 0.375);
    let qNE = gridPt(i + 0.595, j + 0.405);
    let petalN = [
      qNW,
      starTip(i, j, 1),
      starVal(i, j, 0),
      gridPt(i + 0.5, j + 0.142),
      starVal(i + 1, j, 3),
      starTip(i + 1, j, 3),
      qNE,
      qN
    ];
    addChip(petalN, "cream", i, j, 8);

    // Front chamfered bullnose edge tiles along the hammam ledge lip (vNorm = 1.40 to 1.72)
    let roles = ["emerald", "cream", "turquoise", "manganese"];
    for (let s = 0; s < 4; s++) {
      let u0 = i + s * 0.25;
      let u1 = u0 + 0.25;
      let lipTile = [
        gridPt(u0, 1.38),
        gridPt(u1, 1.38),
        gridPt(u1, 1.66),
        gridPt(u0, 1.66)
      ];
      addChip(lipTile, roles[(i * 4 + s + 16) % 4], i, 2, s);
    }

    // Vertical front face of the ledge (foreshortened drop-off, vNorm = 1.68 to 2.02)
    for (let s = 0; s < 2; s++) {
      let u0 = i + s * 0.5;
      let u1 = u0 + 0.5;
      let frontFaceTile = [
        gridPt(u0, 1.68),
        gridPt(u1, 1.68),
        gridPt(u1, 2.04),
        gridPt(u0, 2.04)
      ];
      addChip(frontFaceTile, roles[(i * 2 + s + 9) % 4], i, 3, s);
    }
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm parchment-plaster base of the hammam mortar bed
  background("#dfd2c0");

  // 1. Mortar bed washes & lower shadowed wall under the ledge
  drawMortarBedAndLedgeWall();

  // 2. Marker-drawn grout lines & recessed tile shadows
  drawMarkerGroutWork();

  // 3. Batched watercolor fills for the 4 pastel zellige glazes + pooled centers
  drawZelligeWatercolors();

  // 4. Glaze pinholes, terracotta craters, and hand-cut bevel glints
  drawGlazePinholesAndBevels();

  // 5. Sheet of standing water + blurred reflection of the brass hammam tap
  drawStandingWaterAndBrassTap();

  // 6. Half-melted, glossy olive-green Savon Beldi soap bar & melted trails
  drawSavonBeldiSoap();

  // 7. Hyperreal soap suds, iridescent bubbles, curly hairs, and water droplets
  drawSudsHairsAndDroplets();

  // 8. Warm, steamy, sensual atmospheric veil
  drawHammamSteam();

  noLoop();
}

function drawMortarBedAndLedgeWall() {
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.3);

  // Warm lime-putty & tadelakt mortar variations under the tiles
  brush.fill("#d4c3ae", 110);
  brush.rect(0, 0, 1200, 1200, "corner");

  brush.fill("#c7b299", 95);
  drawBrushPoly([
    toScreen(-900, -400),
    toScreen(900, -400),
    toScreen(900, 440),
    toScreen(-900, 440)
  ]);

  // Shadowed recess below the tiled ledge lip (bottom strip of the tilted view)
  brush.fill("#6e584f", 165);
  drawBrushPoly([
    toScreen(-950, 435),
    toScreen(950, 435),
    toScreen(950, 950),
    toScreen(-950, 950)
  ]);

  brush.fill("#4d3b35", 170);
  drawBrushPoly([
    toScreen(-950, 520),
    toScreen(950, 520),
    toScreen(950, 950),
    toScreen(-950, 950)
  ]);
}

function drawMarkerGroutWork() {
  brush.noFill();
  brush.noHatch();

  // Marker-drawn grout lines across all tile joints
  let groutColors = ["#c4b29d", "#b5a08a", "#cfc0ad", "#a6907b"];
  for (let idx = 0; idx < groutEdges.length; idx++) {
    let e = groutEdges[idx];
    let col = groutColors[idx % groutColors.length];
    brush.set("groutMarker", col, random(0.85, 1.35));
    brush.line(e[0][0], e[0][1], e[1][0], e[1][1]);
  }

  // Subtle dark mortar shadow along the lower-right underside of each chip
  brush.set("2B", "#7d6b5d", 0.75);
  for (let t of tiles) {
    let n = t.pts.length;
    for (let k = 0; k < n; k++) {
      let p1 = t.pts[k];
      let p2 = t.pts[(k + 1) % n];
      let mx = (p1[0] + p2[0]) * 0.5;
      let my = (p1[1] + p2[1]) * 0.5;
      // If edge faces lower-right, accent its mortar shadow
      if (mx - t.cx + (my - t.cy) > 0) {
        brush.line(p1[0] + 1.2, p1[1] + 1.4, p2[0] + 1.2, p2[1] + 1.4);
      }
    }
  }
}

function drawZelligeWatercolors() {
  brush.noStroke();

  // Soft pastel glaze palette with pooled centers
  const palette = {
    emerald: {
      base: ["#78b097", "#6ea68d", "#83b8a0"],
      pool: ["#4b856c", "#3f7860", "#558f76"],
      rim: "#b8e0cd"
    },
    turquoise: {
      base: ["#86c2c7", "#7ab8bd", "#92cacf"],
      pool: ["#52949c", "#478890", "#5da0a8"],
      rim: "#c5ebed"
    },
    cream: {
      base: ["#f2e8d7", "#ede1cc", "#f6efe0"],
      pool: ["#d9c7ac", "#cfb99b", "#e0d0b8"],
      rim: "#fcf9f2"
    },
    manganese: {
      base: ["#9c7c77", "#91706b", "#a68681"],
      pool: ["#6e4e4a", "#61423e", "#7a5854"],
      rim: "#c7aba6"
    }
  };

  // Batch by role and shade for optimal p5.brush watercolor fill caching
  for (let role of ["cream", "turquoise", "emerald", "manganese"]) {
    let group = tiles.filter(t => t.role === role);
    let pal = palette[role];

    // Pass 1: Outer hand-cut chip watercolor wash
    brush.fillBleed(0.16, "in");
    brush.fillTexture(0.48, 0.38);
    for (let b = 0; b < 3; b++) {
      brush.fill(pal.base[b], role === "cream" ? 195 : 185);
      for (let idx = 0; idx < group.length; idx++) {
        if (idx % 3 !== b) continue;
        let t = group[idx];
        drawBrushPoly(t.pts, 0.08);
      }
    }

    // Pass 2: Pooled thicker glaze in the slight concavity of each chip
    brush.fillBleed(0.26, "out");
    brush.fillTexture(0.55, 0.25);
    for (let b = 0; b < 3; b++) {
      brush.fill(pal.pool[b], role === "cream" ? 135 : 150);
      for (let idx = 0; idx < group.length; idx++) {
        if (idx % 3 !== b) continue;
        let t = group[idx];
        drawBrushPoly(t.pooledPts, 0.18);
      }
    }
  }

  // Pass 3: Darken the vertical front face of the ledge (j === 3) to show 3D drop-off
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.35, 0.2);
  brush.fill("#4a3b37", 110);
  for (let t of tiles) {
    if (t.j === 3) {
      drawBrushPoly(t.pts, 0.05);
    }
  }
}

function drawGlazePinholesAndBevels() {
  // Hand-cut glaze bevel highlights along upper-left edges of chips
  for (let t of tiles) {
    let n = t.pts.length;
    let rimCol =
      t.role === "cream"
        ? "#ffffff"
        : t.role === "emerald"
        ? "#ccebd9"
        : t.role === "turquoise"
        ? "#d5f5f7"
        : "#dec7c3";

    brush.set("cpencil", rimCol, 0.9);
    for (let k = 0; k < n; k++) {
      let p1 = t.pts[k];
      let p2 = t.pts[(k + 1) % n];
      let mx = (p1[0] + p2[0]) * 0.5;
      let my = (p1[1] + p2[1]) * 0.5;
      if (mx - t.cx + (my - t.cy) < -4 && random() < 0.75) {
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // Authentic zellige glaze pinholes (tiny burst bubbles exposing dark terracotta)
    let numPinholes = floor(random(1, 4.2));
    for (let p = 0; p < numPinholes; p++) {
      let ang = random(360);
      let rad = random(4, 24);
      let px = t.cx + cos(ang) * rad;
      let py = t.cy + sin(ang) * rad;
      let pr = random(0.9, 2.3);

      // Tiny pale glaze crater rim
      brush.set("pen", "#f5ede0", 0.7);
      brush.circle(px + 0.6, py + 0.6, pr + 0.7, 0.2);

      // Dark terracotta pinhole pit
      brush.set("rotring", "#3d2922", random(0.9, 1.45));
      brush.circle(px, py, pr * 0.65, 0.15);
      brush.line(px - 0.5, py - 0.4, px + 0.5, py + 0.4);
    }
  }

  // Highlight along the bullnose ridge of the ledge lip (j === 2)
  brush.set("marker", "#f7EFE2", 0.95);
  let lipStart = toScreen(-850, 360);
  let lipEnd = toScreen(850, 360);
  brush.line(lipStart[0], lipStart[1], lipEnd[0], lipEnd[1]);
}

// Helper to test if a point is inside the standing water sheet
function inWaterSheet(x, y) {
  let dx = (x - 835) / 360;
  let dy = (y - 430) / 330;
  let ang = atan2(dy, dx);
  let rMod =
    1.0 +
    0.14 * sin(ang * 3 + 25) +
    0.09 * cos(ang * 5 - 40) +
    0.05 * sin(ang * 8 + 10);
  return dx * dx + dy * dy < rMod * rMod;
}

function getWaterContour(scaleM = 1.0, offsetX = 0, offsetY = 0) {
  let pts = [];
  let steps = 64;
  for (let s = 0; s < steps; s++) {
    let ang = (s / steps) * 360;
    let rMod =
      1.0 +
      0.14 * sin(ang * 3 + 25) +
      0.09 * cos(ang * 5 - 40) +
      0.05 * sin(ang * 8 + 10);
    let rx = 360 * rMod * scaleM;
    let ry = 330 * rMod * scaleM;
    let x = 835 + offsetX + cos(ang) * rx;
    let y = 430 + offsetY + sin(ang) * ry;
    pts.push([x, y]);
  }
  return pts;
}

function drawStandingWaterAndBrassTap() {
  let waterPoly = getWaterContour(1.0);

  // 1. Subtle milky sky/steam sheen across the sheet of standing water
  brush.noStroke();
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.3, 0.15);
  brush.fill("#dfecea", 52);
  drawBrushPoly(waterPoly, 0.25);

  brush.fill("#f2e8d8", 38);
  drawBrushPoly(getWaterContour(0.88, 12, -10), 0.25);

  // 2. Blurred reflection of an ornate Moroccan brass tap mirrored in the water sheet
  // The tap extends down from the upper-right wall into the water puddle reflection
  brush.noStroke();
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.45, 0.12);

  // Ambient warm brass halo in the water
  brush.fill("#d9b268", 68);
  brush.circle(865, 215, 92, 0.35); // Wall escutcheon plate halo
  drawBrushPoly(
    [
      [840, 190],
      [895, 195],
      [880, 390],
      [835, 510],
      [785, 505],
      [805, 375]
    ],
    0.35
  );

  // Octagonal scalloped brass wall plate (escutcheon) reflection
  let escPts = [];
  for (let k = 0; k < 8; k++) {
    let a = k * 45 + 12;
    escPts.push([868 + cos(a) * 74, 210 + sin(a) * 60]);
  }
  brush.fill("#b88635", 95);
  drawBrushPoly(escPts, 0.2);

  // Deeper antique bronze core of wall plate & collar
  brush.fill("#7d5418", 105);
  brush.circle(865, 222, 42, 0.25);

  // Curved swan-neck brass tap body & flared bell nozzle
  brush.fill("#c7933e", 110);
  drawBrushPoly(
    [
      [846, 225],
      [884, 230],
      [872, 365],
      [842, 465],
      [848, 505],
      [792, 498],
      [802, 455],
      [828, 355]
    ],
    0.32
  );

  // Cross-handle T-valve at the top of the tap
  brush.fill("#d4a44e", 115);
  drawBrushPoly(
    [
      [765, 298],
      [940, 322],
      [935, 354],
      [760, 330]
    ],
    0.25
  );
  // Valve finials (left and right knobs)
  brush.circle(762, 314, 22, 0.25);
  brush.circle(938, 338, 22, 0.25);
  // Central valve stem
  brush.fill("#8c5e1c", 115);
  brush.circle(850, 325, 28, 0.2);

  // Dark bronze core shadows inside the blurred reflection
  brush.fill("#5e3c10", 95);
  drawBrushPoly(
    [
      [852, 245],
      [874, 250],
      [860, 375],
      [834, 488],
      [812, 485],
      [835, 365]
    ],
    0.3
  );
  // Dark opening of the brass spout mouth
  brush.fill("#362108", 130);
  drawBrushPoly(
    [
      [794, 494],
      [844, 500],
      [838, 514],
      [798, 509]
    ],
    0.25
  );

  // Rippled golden-pastel highlights & water distortion streaks across the tap reflection
  for (let r = 0; r < 42; r++) {
    let ry = map(r, 0, 41, 155, 535);
    let rx = map(r, 0, 41, 868, 818) + sin(r * 37) * 18;
    let wSpan = map( sin(r * 22), -1, 1, 24, 68 );
    if (abs(ry - 325) < 24) wSpan += 45; // wider at the cross-handle
    if (ry < 250) wSpan += 28; // wider at the wall plate

    let p1 = [rx - wSpan * 0.5, ry - wSpan * 0.1];
    let p2 = [rx + wSpan * 0.5, ry + wSpan * 0.1];

    if (r % 3 === 0) {
      brush.set("marker", "#f2d68d", random(0.7, 1.3));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    } else if (r % 3 === 1) {
      brush.set("cpencil", "#9e6f25", random(0.9, 1.5));
      brush.line(p1[0] + 6, p1[1] + 2, p2[0] - 4, p2[1] + 2);
    } else {
      brush.set("glossNib", "#fff6d6", random(0.6, 1.1));
      brush.line(
        rx - wSpan * 0.3,
        ry - 2,
        rx + wSpan * 0.25,
        ry + 3
      );
    }
  }

  // Reflected drop hanging from the brass spout + concentric water ripples below it
  brush.noFill();
  for (let ring = 1; ring <= 4; ring++) {
    let rw = ring * 26;
    let rh = ring * 16;
    brush.set("cpencil", ring % 2 === 0 ? "#ffffff" : "#9ab8b5", 0.85);
    let rPts = [];
    for (let a = 0; a < 16; a++) {
      let th = a * 22.5;
      rPts.push([816 + cos(th) * rw, 536 + sin(th) * rh]);
    }
    brush.spline(rPts, 0.5);
  }

  // 3. Crisp wet meniscus around the sheet of standing water
  // Outer dark refractive edge
  brush.set("cpencil", "#49635e", 1.15);
  brush.spline([...waterPoly, waterPoly[0]], 0.35);

  // Inner bright glossy water rim highlight (broken naturally around the contour)
  for (let i = 0; i < waterPoly.length; i++) {
    let p1 = waterPoly[i];
    let p2 = waterPoly[(i + 1) % waterPoly.length];
    let nVal = noise(p1[0] * 0.01, p1[1] * 0.01);
    if (nVal > 0.32) {
      brush.set("glossNib", "#ffffff", map(nVal, 0.32, 1, 0.5, 1.45));
      brush.line(p1[0] - 1.5, p1[1] - 1.5, p2[0] - 1.5, p2[1] - 1.5);
    } else {
      brush.set("pen", "#d9ebe8", 0.75);
      brush.line(p1[0] - 1, p1[1] - 1, p2[0] - 1, p2[1] - 1);
    }
  }

  // Broad soft sky-window reflection streak across the standing water
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fill("#ffffff", 48);
  drawBrushPoly(
    [
      [680, 220],
      [760, 205],
      [690, 420],
      [615, 405]
    ],
    0.3
  );
}

function drawSavonBeldiSoap() {
  // Center of the wet olive-green Savon Beldi soap bar at (455, 555), tilted at -24 deg
  let sx = 455;
  let sy = 555;
  let sAng = -24;
  let cS = cos(sAng);
  let sS = sin(sAng);

  function soapPt(u, v) {
    return [sx + u * cS - v * sS, sy + u * sS + v * cS];
  }

  brush.noStroke();

  // 1. Melted, emulsified olive-pastel soap puddle spreading into the wet tile & grout
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.5, 0.25);

  let meltHaloOuter = [];
  for (let k = 0; k < 28; k++) {
    let a = (k / 28) * 360;
    // Bulges outward on the right/lower-right where it meets the water sheet
    let stretch = a > -45 && a < 110 ? 1.28 : 1.0;
    let rU = (215 + 24 * sin(a * 3 + 15) + 14 * cos(a * 5)) * stretch;
    let rV = (148 + 18 * cos(a * 2 - 20) + 12 * sin(a * 4)) * stretch;
    meltHaloOuter.push(soapPt(cos(a) * rU, sin(a) * rV));
  }
  brush.fill("#c7d6a5", 115);
  drawBrushPoly(meltHaloOuter, 0.35);

  // Runny melted soap tendrils following the tile grout channels
  let tendrils = [
    [soapPt(150, 40), soapPt(245, 72), soapPt(305, 95), soapPt(235, 112), soapPt(135, 85)],
    [soapPt(-40, 110), soapPt(-65, 185), soapPt(-35, 200), soapPt(-5, 125)],
    [soapPt(85, -95), soapPt(165, -145), soapPt(190, -125), soapPt(115, -75)]
  ];
  brush.fill("#b4c78d", 130);
  for (let td of tendrils) {
    drawBrushPoly(td, 0.3);
  }

  // Mid-tone melted olive-sage jelly base
  let meltBase = [];
  for (let k = 0; k < 24; k++) {
    let a = (k / 24) * 360;
    let slumping = cos(a - 25) > 0 ? 1.16 : 0.96;
    let rU = (182 + 15 * sin(a * 3 + 40)) * slumping;
    let rV = (122 + 12 * cos(a * 3 - 10)) * slumping;
    meltBase.push(soapPt(cos(a) * rU, sin(a) * rV));
  }
  brush.fill("#8ea362", 160);
  drawBrushPoly(meltBase, 0.32);

  // 2. Deep ambient occlusion & wet contact shadow under the lower-right edge of the bar
  let shadowPoly = [];
  for (let k = 0; k < 24; k++) {
    let a = (k / 24) * 360;
    let rU = 162 + 12 * sin(a * 2 + 10);
    let rV = 106 + 10 * cos(a * 3);
    shadowPoly.push(soapPt(cos(a) * rU + 14, sin(a) * rV + 18));
  }
  brush.fillBleed(0.22, "out");
  brush.fill("#283316", 175);
  drawBrushPoly(shadowPoly, 0.25);

  // 3. Main body of the wet, half-melted Savon Beldi bar (layered translucent olive-green)
  function makeBarContour(uRad, vRad, shiftU, shiftV, slumpedRight = 1.0) {
    let pts = [];
    let steps = 28;
    for (let k = 0; k < steps; k++) {
      let a = (k / steps) * 360;
      // Soft pillowy rectangular-oval bar, half-melted and slumped on the right side
      let c = cos(a);
      let s = sin(a);
      let sq = 0.84; // superellipse softness
      let u = Math.sign(c) * Math.pow(Math.abs(c), sq) * uRad;
      let v = Math.sign(s) * Math.pow(Math.abs(s), sq) * vRad;
      // Organic melt deformation
      if (c > 0) {
        u *= slumpedRight + 0.08 * sin(a * 3);
        v *= 0.94 + 0.07 * cos(a * 2);
      }
      u += 6 * sin(a * 4 + 20) + shiftU;
      v += 5 * cos(a * 3 - 35) + shiftV;
      pts.push(soapPt(u, v));
    }
    return pts;
  }

  // Outer translucent olive-green body
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.45, 0.3);
  let barOuter = makeBarContour(158, 102, 0, 0, 1.06);
  brush.fill("#586e2e", 215);
  drawBrushPoly(barOuter, 0.25);

  // Rich mid-dark olive core
  let barMid = makeBarContour(142, 90, -4, -2, 1.02);
  brush.fill("#445720", 210);
  drawBrushPoly(barMid, 0.25);

  // Deep translucent dark olive-amber heart of the savon beldi
  let barCore = makeBarContour(118, 72, -10, -4, 0.95);
  brush.fill("#2f3e14", 205);
  drawBrushPoly(barCore, 0.25);

  // Inner darkest amber-olive density in the thickest part of the bar
  let barDeep = makeBarContour(82, 48, -22, -6, 0.9);
  brush.fill("#212b0d", 185);
  drawBrushPoly(barDeep, 0.28);

  // 4. Translucent subsurface glow on the upper-left crown & melted right shoulder
  brush.fillBleed(0.28, "out");
  let glowCrown = makeBarContour(105, 58, -16, -18, 0.95);
  brush.fill("#7a9444", 110);
  drawBrushPoly(glowCrown, 0.3);

  // Slumped, melted concavity on the right half of the soap bar (warm olive-gold translucency)
  let meltHollow = [
    soapPt(15, -45),
    soapPt(115, -52),
    soapPt(148, -10),
    soapPt(138, 48),
    soapPt(62, 65),
    soapPt(5, 25)
  ];
  brush.fill("#9bb362", 125);
  drawBrushPoly(meltHollow, 0.35);

  // Soft dry-media / pastel-like contour modeling on the slumped ridges
  brush.noFill();
  for (let m = 0; m < 18; m++) {
    let t = m / 17;
    let pA = soapPt(-115 + t * 210, -58 + sin(t * 180) * 14);
    let pB = soapPt(-95 + t * 210, 52 + cos(t * 180) * 16);
    brush.set(
      "cpencil",
      m % 2 === 0 ? "#6b8238" : "#354518",
      random(0.8, 1.4)
    );
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // 5. Hyperreal glossy wet specular reflections on the slick soap surface
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.15, 0.1);

  // Soft milky sheen halo under the main specular reflections
  brush.fill("#dce8be", 135);
  drawBrushPoly(
    [
      soapPt(-122, -55),
      soapPt(-25, -72),
      soapPt(55, -58),
      soapPt(35, -35),
      soapPt(-45, -42),
      soapPt(-115, -28)
    ],
    0.35
  );

  // Razor-sharp wet white specular ribbons following the slumped 3D ridges of the soap
  brush.fill("#fbffef", 235);
  drawBrushPoly(
    [
      soapPt(-114, -48),
      soapPt(-35, -64),
      soapPt(38, -52),
      soapPt(22, -41),
      soapPt(-42, -50),
      soapPt(-108, -36)
    ],
    0.32
  );

  // Second curved glossy reflection on the slumped right melt pool of the soap
  brush.fill("#ffffff", 230);
  drawBrushPoly(
    [
      soapPt(48, -32),
      soapPt(112, -26),
      soapPt(132, 8),
      soapPt(118, 22),
      soapPt(96, -8),
      soapPt(42, -18)
    ],
    0.35
  );

  // Lower wet lip highlight along the rounded bottom-left shoulder of the soap
  brush.noFill();
  brush.set("glossNib", "#f4fae4", 1.35);
  brush.spline(
    [
      soapPt(-142, -10),
      soapPt(-135, 38),
      soapPt(-88, 68),
      soapPt(-15, 76),
      soapPt(58, 66)
    ],
    0.45
  );

  // Crisp pinpoint specular glints & tiny water beads on the soap crown
  brush.set("glossNib", "#ffffff", 1.6);
  let soapGlints = [
    [-65, -54, -42, -56],
    [-12, -52, 18, -46],
    [72, -20, 104, -8],
    [82, 32, 108, 24],
    [-95, 18, -68, 30]
  ];
  for (let g of soapGlints) {
    let p1 = soapPt(g[0], g[1]);
    let p2 = soapPt(g[2], g[3]);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawBubble(x, y, r, tintCol = "#e3f5f2") {
  // Contact shadow under bubble
  brush.set("cpencil", "#4a594c", 0.65);
  brush.arc(x + r * 0.18, y + r * 0.22, r, 15, 155);

  // Thin iridescent soap film rim
  brush.set("pen", tintCol, map(r, 3, 24, 0.55, 1.0));
  brush.circle(x, y, r, 0.08);

  if (r > 6) {
    // Secondary pastel iridescence (pink / mint / cream)
    let irid = r % 2 > 1 ? "#f7d4de" : "#c8f2eb";
    brush.set("cpencil", irid, 0.75);
    brush.arc(x, y, r * 0.88, 120, 260);

    // Lower-right internal reflection arc
    brush.set("pen", "#eff7f2", 0.65);
    brush.arc(x, y, r * 0.78, 20, 85);
  }

  // Crisp upper-left specular crescent highlight
  brush.set("glossNib", "#ffffff", map(r, 3, 24, 0.55, 1.35));
  brush.arc(x, y, r * 0.76, 195, 290);
}

function drawWaterDroplet(x, y, r) {
  // 1. Cast shadow on lower-right of droplet
  brush.noStroke();
  brush.fillBleed(0.15, "out");
  brush.fill("#364540", 125);
  let shPts = [];
  for (let k = 0; k < 10; k++) {
    let a = k * 36;
    shPts.push([
      x + r * 0.32 + cos(a) * r * 0.95,
      y + r * 0.36 + sin(a) * r * 0.78
    ]);
  }
  drawBrushPoly(shPts, 0.3);

  // 2. Refracted bright lens glow inside lower-right of the water droplet
  brush.fill("#f5faf6", 145);
  let lensPts = [];
  for (let k = 0; k < 8; k++) {
    let a = k * 45;
    lensPts.push([
      x + r * 0.18 + cos(a) * r * 0.55,
      y + r * 0.18 + sin(a) * r * 0.45
    ]);
  }
  drawBrushPoly(lensPts, 0.3);

  // 3. Dark upper-left refractive edge where light bends into the dome
  brush.noFill();
  brush.set("cpencil", "#3f544e", 0.85);
  brush.arc(x, y, r, 165, 330);

  // 4. Razor-sharp white specular highlight dot on upper-left dome
  brush.set("glossNib", "#ffffff", map(r, 3.5, 15, 0.7, 1.5));
  brush.arc(x - r * 0.1, y - r * 0.1, r * 0.52, 200, 275);
}

function drawCurlyHair(pts) {
  // Wet water meniscus highlight hugging the hair strand
  let menuPts = pts.map(p => [p[0] - 1.3, p[1] - 1.3]);
  brush.set("glossNib", "#ffffff", 0.65);
  brush.spline(menuPts, 0.65);

  // Soft shadow on the glaze right below the hair
  let shadPts = pts.map(p => [p[0] + 1.4, p[1] + 1.6]);
  brush.set("cpencil", "#594942", 0.65);
  brush.spline(shadPts, 0.65);

  // Crisp dark espresso-black wet hair strand
  brush.set("rotring", "#1f1512", 0.82);
  brush.spline(pts, 0.65);
}

