function ptPolar(r, deg) {
  let rad = deg * DEG2RAD;
  return [CX + r * Math.cos(rad), CY + r * Math.sin(rad)];
}

function modeFill(col, alpha, bleed = 0.16, tex = 0.55, border = 0.65) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "in");
  brush.fillTexture(tex, border);
}

function modeWash(col, alpha) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, alpha);
}

function modeStroke(name, col, weight) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

function drawPoly(pts, curvature = 0.08) {
  if (!pts || pts.length < 3) return;
  let clean = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let prev = clean.length > 0 ? clean[clean.length - 1] : pts[pts.length - 1];
    let dx = p[0] - prev[0];
    let dy = p[1] - prev[1];
    if (dx * dx + dy * dy > 0.3) {
      clean.push(p);
    }
  }
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(true);
}

// Generate a wavy convoluted ribbon with rounded hairpin turns at both ends
function buildWaveRibbonPts(rMid, halfSpan, degCenter, h0, opts, scaleU = 1, scaleS = 1, steps = 40) {
  let pts = [];
  let arch = opts.arch || 0;
  let w1 = opts.w1 || 0;
  let f1 = opts.f1 || 2;
  let w2 = opts.w2 || 0;
  let f2 = opts.f2 || 3;
  let skew = opts.skew || 0;
  let swell = opts.swell || 0.2;

  for (let i = 0; i < steps; i++) {
    let th = (i / steps) * Math.PI * 2;
    let u = Math.sin(th) * scaleU;
    let s = Math.cos(th) * scaleS;

    let rCenter = rMid
      + arch * (1 - u * u)
      + w1 * Math.cos(f1 * Math.PI * u)
      + w2 * Math.cos(f2 * Math.PI * u)
      + skew * Math.sin(2 * Math.PI * u);

    let thick = h0 * (1 + swell * Math.cos(2 * Math.PI * u));
    let r = rCenter + s * thick;
    let deg = degCenter + u * halfSpan;
    pts.push(ptPolar(r, deg));
  }
  return pts;
}

function addWaveRibbon8(rMid, halfSpan, degOffset, h0, tier, isPrimary, opts = {}, mirrored = false) {
  let modes = mirrored ? [-1, 1] : [1];
  for (let m of modes) {
    let localOpts = Object.assign({}, opts);
    if (m === -1 && localOpts.skew) localOpts.skew = -localOpts.skew;

    for (let s = 0; s < 8; s++) {
      let degCenter = s * 45 + m * degOffset;
      let ptsOuter = buildWaveRibbonPts(rMid, halfSpan, degCenter, h0, localOpts, 1.0, 1.0, 42);
      let ptsMid   = buildWaveRibbonPts(rMid, halfSpan, degCenter, h0, localOpts, 0.92, 0.66, 36);
      let ptsCore  = buildWaveRibbonPts(rMid, halfSpan, degCenter, h0, localOpts, 0.80, 0.34, 30);

      let ptsSpine = [];
      for (let k = -8; k <= 8; k++) {
        let u = (k / 8) * 0.84;
        let rC = rMid
          + (localOpts.arch || 0) * (1 - u * u)
          + (localOpts.w1 || 0) * Math.cos((localOpts.f1 || 2) * Math.PI * u)
          + (localOpts.w2 || 0) * Math.cos((localOpts.f2 || 3) * Math.PI * u)
          + (localOpts.skew || 0) * Math.sin(2 * Math.PI * u);
        ptsSpine.push(ptPolar(rC, degCenter + u * halfSpan));
      }

      cells.push({
        tier,
        isPrimary,
        ptsOuter,
        ptsMid,
        ptsCore,
        ptsSpine
      });
    }
  }
}

// Generate an Omega / Horseshoe folded cabbage leaf ribbon inside a polar bay
function buildOmegaRibbonPts(rBot, rTop, halfSpan, degCenter, rho0, h0, opts, scaleA = 1, scaleS = 1, steps = 48) {
  let pts = [];
  let alphaMax = (opts.alphaMax || 0.78 * Math.PI) * scaleA;
  let w2 = opts.w2 || 0.04;
  let w3 = opts.w3 || 0.05;
  let w5 = opts.w5 || 0.0;
  let pinch = opts.pinch || 0.12;
  let invert = opts.invert ? -1 : 1;

  let rMid = 0.5 * (rBot + rTop);
  let rHalf = 0.5 * (rTop - rBot);

  for (let i = 0; i < steps; i++) {
    let th = (i / steps) * Math.PI * 2;
    let alpha = Math.sin(th) * alphaMax;
    let s = Math.cos(th) * scaleS;

    let rhoBase = rho0
      + w2 * Math.cos(2 * alpha)
      + w3 * Math.cos(3 * alpha)
      + w5 * Math.cos(5 * alpha);

    let rho = rhoBase + s * h0 * (1 + 0.22 * Math.cos(3 * alpha));
    let U = rho * Math.sin(alpha) * (1 - pinch * Math.pow(Math.sin(alpha * 0.5), 2));
    let V = invert * rho * Math.cos(alpha);

    let r = rMid + V * rHalf;
    let deg = degCenter + U * halfSpan;
    pts.push(ptPolar(r, deg));
  }
  return pts;
}

function addOmegaRibbon8(rBot, rTop, halfSpan, degOffset, rho0, h0, tier, isPrimary, opts = {}, mirrored = false) {
  let modes = mirrored ? [-1, 1] : [1];
  for (let m of modes) {
    for (let s = 0; s < 8; s++) {
      let degCenter = s * 45 + m * degOffset;
      let ptsOuter = buildOmegaRibbonPts(rBot, rTop, halfSpan, degCenter, rho0, h0, opts, 1.0, 1.0, 48);
      let ptsMid   = buildOmegaRibbonPts(rBot, rTop, halfSpan, degCenter, rho0, h0, opts, 0.93, 0.65, 40);
      let ptsCore  = buildOmegaRibbonPts(rBot, rTop, halfSpan, degCenter, rho0, h0, opts, 0.84, 0.34, 32);

      let ptsSpine = [];
      let alphaMax = (opts.alphaMax || 0.78 * Math.PI) * 0.86;
      let rMid = 0.5 * (rBot + rTop);
      let rHalf = 0.5 * (rTop - rBot);
      let invert = opts.invert ? -1 : 1;
      let pinch = opts.pinch || 0.12;
      for (let k = -10; k <= 10; k++) {
        let alpha = (k / 10) * alphaMax;
        let rhoBase = rho0
          + (opts.w2 || 0.04) * Math.cos(2 * alpha)
          + (opts.w3 || 0.05) * Math.cos(3 * alpha)
          + (opts.w5 || 0.0) * Math.cos(5 * alpha);
        let U = rhoBase * Math.sin(alpha) * (1 - pinch * Math.pow(Math.sin(alpha * 0.5), 2));
        let V = invert * rhoBase * Math.cos(alpha);
        ptsSpine.push(ptPolar(rMid + V * rHalf, degCenter + U * halfSpan));
      }

      cells.push({
        tier,
        isPrimary,
        ptsOuter,
        ptsMid,
        ptsCore,
        ptsSpine
      });
    }
  }
}

// Generate a Gothic Foil / Teardrop / Heart pocket
function buildFoilPocketPts(rBot, rTop, halfSpan, degCenter, opts, scale = 1, steps = 36) {
  let pts = [];
  let c1 = opts.c1 || 0.12;
  let c2 = opts.c2 || -0.08;
  let c3 = opts.c3 || 0.10;
  let c4 = opts.c4 || 0.0;

  let rMid = 0.5 * (rBot + rTop);
  let rHalf = 0.5 * (rTop - rBot);

  for (let i = 0; i < steps; i++) {
    let th = (i / steps) * Math.PI * 2;
    let rho = scale * (0.82 + c1 * Math.cos(th) + c2 * Math.cos(2 * th) + c3 * Math.cos(3 * th) + c4 * Math.cos(4 * th));
    let U = rho * Math.sin(th);
    let V = rho * Math.cos(th);
    pts.push(ptPolar(rMid + V * rHalf, degCenter + U * halfSpan));
  }
  return pts;
}

function addFoilPocket8(rBot, rTop, halfSpan, degOffset, tier, isPrimary, opts = {}, mirrored = false) {
  let modes = mirrored ? [-1, 1] : [1];
  for (let m of modes) {
    for (let s = 0; s < 8; s++) {
      let degCenter = s * 45 + m * degOffset;
      let ptsOuter = buildFoilPocketPts(rBot, rTop, halfSpan, degCenter, opts, 1.0, 36);
      let ptsMid   = buildFoilPocketPts(rBot, rTop, halfSpan, degCenter, opts, 0.70, 30);
      let ptsCore  = buildFoilPocketPts(rBot, rTop, halfSpan, degCenter, opts, 0.40, 24);

      let rMid = 0.5 * (rBot + rTop);
      let rHalf = 0.5 * (rTop - rBot);
      let ptsSpine = [
        ptPolar(rMid - 0.55 * rHalf, degCenter),
        ptPolar(rMid, degCenter),
        ptPolar(rMid + 0.55 * rHalf, degCenter)
      ];

      cells.push({
        tier,
        isPrimary,
        ptsOuter,
        ptsMid,
        ptsCore,
        ptsSpine
      });
    }
  }
}

// Build a sculpted white stone-mullion / cabbage midrib polygon from a centerline
function buildRibbonFromSpine(spinePts, halfWidths) {
  let left = [];
  let right = [];
  let n = spinePts.length;
  for (let i = 0; i < n; i++) {
    let pPrev = spinePts[Math.max(0, i - 1)];
    let pNext = spinePts[Math.min(n - 1, i + 1)];
    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    let len = Math.hypot(tx, ty) || 1;
    let nx = -ty / len;
    let ny = tx / len;
    let hw = halfWidths[i];
    left.push([spinePts[i][0] + nx * hw, spinePts[i][1] + ny * hw]);
    right.push([spinePts[i][0] - nx * hw, spinePts[i][1] - ny * hw]);
  }
  right.reverse();
  return left.concat(right);
}

function addArchedMidrib8(rMid, halfSpan, degOffset, maxHalfW, minHalfW, archCurve, hasVascular = true) {
  for (let s = 0; s < 8; s++) {
    let degCenter = s * 45 + degOffset;
    let spine = [];
    let hwOuter = [];
    let hwInner = [];
    let steps = 22;
    for (let i = 0; i <= steps; i++) {
      let u = -1 + (2 * i) / steps;
      let env = Math.pow(Math.max(0, 1 - u * u), 0.55);
      let r = rMid + archCurve * (1 - u * u) + 1.5 * Math.cos(3 * Math.PI * u);
      let deg = degCenter + u * halfSpan;
      spine.push(ptPolar(r, deg));
      let w = minHalfW + (maxHalfW - minHalfW) * env;
      hwOuter.push(w);
      hwInner.push(w * 0.62);
    }
    mullions.push({
      spine,
      polyOuter: buildRibbonFromSpine(spine, hwOuter),
      polyInner: buildRibbonFromSpine(spine, hwInner),
      hasVascular,
      leadWeight: 1.25
    });
  }
}

function addRadialMullion8(r1, r2, degOffset, w1, wMid, w2, mirrored = false) {
  let modes = mirrored ? [-1, 1] : [1];
  for (let m of modes) {
    for (let s = 0; s < 8; s++) {
      let deg = s * 45 + m * degOffset;
      let spine = [];
      let hwOuter = [];
      let hwInner = [];
      let steps = 14;
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let r = r1 + (r2 - r1) * t;
        spine.push(ptPolar(r, deg));
        let w = (1 - t) * (1 - t) * w1 + 2 * (1 - t) * t * wMid + t * t * w2;
        hwOuter.push(w);
        hwInner.push(w * 0.60);
      }
      mullions.push({
        spine,
        polyOuter: buildRibbonFromSpine(spine, hwOuter),
        polyInner: buildRibbonFromSpine(spine, hwInner),
        hasVascular: false,
        leadWeight: 1.05
      });
    }
  }
}

function addYTraceryFork8(rStart, rEnd, degBase, degSpread, wStart, wEnd, mirroredBase = false) {
  let baseModes = mirroredBase ? [-1, 1] : [1];
  for (let bm of baseModes) {
    for (let s = 0; s < 8; s++) {
      let centerDeg = s * 45 + bm * degBase;
      for (let branch of [-1, 1]) {
        let spine = [];
        let hwOuter = [];
        let hwInner = [];
        let steps = 12;
        for (let i = 0; i <= steps; i++) {
          let t = i / steps;
          let ease = t * t * (3 - 2 * t);
          let r = rStart + (rEnd - rStart) * t;
          let deg = centerDeg + branch * degSpread * ease;
          spine.push(ptPolar(r, deg));
          let w = wStart + (wEnd - wStart) * t;
          hwOuter.push(w);
          hwInner.push(w * 0.58);
        }
        mullions.push({
          spine,
          polyOuter: buildRibbonFromSpine(spine, hwOuter),
          polyInner: buildRibbonFromSpine(spine, hwInner),
          hasVascular: false,
          leadWeight: 0.95
        });
      }
    }
  }
}

