// Render deep abyssal black void and subtle backlit outer aura
function drawBackgroundAndDiskBase() {
  // Subtle dark violet aura just outside the cabbage rim (r = 505..555)
  modeStroke("spray", "#180328", 1.2);
  brush.circle(CX, CY, 526, 0.15);
  modeStroke("spray", "#0d0118", 1.4);
  brush.circle(CX, CY, 542, 0.2);

  // Scalloped outer contour of the entire cabbage disk (r ~ 510)
  let diskPts = [];
  let steps = 160;
  for (let i = 0; i < steps; i++) {
    let deg = (i / steps) * 360;
    let r = 508 + 4.5 * Math.cos(8 * deg * DEG2RAD) + 3.0 * Math.cos(16 * deg * DEG2RAD);
    diskPts.push(ptPolar(r, deg));
  }

  // Luminous backlit pale lilac-ivory ground for the cabbage cross-section
  // This reserved light ground makes the veins read as glowing stone mullions
  // and allows the translucent watercolor layers to glow as if lit from behind.
  modeWash("#f5e8ff", 252);
  drawPoly(diskPts, 0.05);

  // Inner warmer backlit core luminosity
  modeWash("#fff5fc", 220);
  brush.circle(CX, CY, 360, 0.05);
  modeWash("#ffffff", 240);
  brush.circle(CX, CY, 165, 0.04);

  // Overarching wet-in-wet watercolor glazes across concentric zones
  modeFill("#e8b8ff", 65, 0.3, 0.45, 0.35);
  brush.circle(CX, CY, 445, 0.08);
  modeFill("#ff94d6", 55, 0.3, 0.45, 0.35);
  brush.circle(CX, CY, 265, 0.08);
}

// Render all 400+ convoluted leaf cells in color-batched passes
function drawConvolutedLeafCells() {
  // PASS 1A: Fast saturated base wash for all outer cells, batched by tier
  for (let t = 0; t < PALETTE.length; t++) {
    modeWash(PALETTE[t].edgeFill, 230);
    for (let c of cells) {
      if (c.tier === t) {
        drawPoly(c.ptsOuter, 0.08);
      }
    }
  }

  // PASS 1B: Translucent watercolor fills with bleed & granulation for primary cells
  for (let t = 0; t < PALETTE.length; t++) {
    modeFill(PALETTE[t].midWash, 155, 0.18, 0.58, 0.68);
    for (let c of cells) {
      if (c.tier === t && c.isPrimary) {
        drawPoly(c.ptsOuter, 0.08);
      }
    }
  }

  // PASS 2: Vivid middle layer washes (ptsMid), batched by tier
  for (let t = 0; t < PALETTE.length; t++) {
    modeWash(PALETTE[t].midWash, 215);
    for (let c of cells) {
      if (c.tier === t) {
        drawPoly(c.ptsMid, 0.08);
      }
    }
  }

  // PASS 3: Luminous backlit core glows (ptsCore), batched by tier
  for (let t = 0; t < PALETTE.length; t++) {
    modeWash(PALETTE[t].coreGlow, 235);
    for (let c of cells) {
      if (c.tier === t) {
        drawPoly(c.ptsCore, 0.08);
      }
    }
  }

  // PASS 4: Incandescent center slits & microscopic transverse plant-cell venation
  for (let t = 0; t < PALETTE.length; t++) {
    // Hot center spine glow
    modeStroke("marker", PALETTE[t].hotSlit, 0.42);
    for (let c of cells) {
      if (c.tier === t && c.ptsSpine && c.ptsSpine.length >= 2) {
        brush.spline(c.ptsSpine, 0.25);
      }
    }

    // Fine internal cellular cross-fibers bridging outer edge to luminous core
    modeStroke("2H", PALETTE[t].veinCol, 0.28);
    for (let c of cells) {
      if (c.tier === t) {
        let len = Math.min(c.ptsOuter.length, c.ptsCore.length);
        let step = c.isPrimary ? 3 : 5;
        for (let i = 0; i < len; i += step) {
          let p1 = c.ptsOuter[i];
          let p2 = c.ptsCore[i];
          brush.line(p1[0], p1[1], p2[0], p2[1]);
        }
      }
    }
  }
}

// Render the central white stem pith boss and all sculpted stone-mullion ribs
function drawWhiteRibsAndMullions() {
  // 1. Central White Pith Core Ring (r = 27..66)
  let pithOuter = [];
  let pithInner = [];
  let steps = 96;
  for (let i = 0; i < steps; i++) {
    let deg = (i / steps) * 360;
    let rad = deg * DEG2RAD;
    let rOut = 60 + 7.5 * Math.cos(8 * rad) + 2.5 * Math.cos(16 * rad);
    let rIn  = 27 + 2.5 * Math.cos(8 * rad);
    pithOuter.push(ptPolar(rOut, deg));
    pithInner.push(ptPolar(rIn, deg));
  }

  // Draw 8 radial segments of the white pith ring around the cleft jewels
  for (let s = 0; s < 8; s++) {
    let segPts = [];
    for (let a = -18; a <= 18; a += 3) {
      let deg = s * 45 + 22.5 + a;
      let rOut = 61 + 6.5 * Math.cos(8 * deg * DEG2RAD);
      segPts.push(ptPolar(rOut, deg));
    }
    for (let a = 18; a >= -18; a -= 3) {
      let deg = s * 45 + 22.5 + a;
      let rIn = 27 + 2.0 * Math.cos(8 * deg * DEG2RAD);
      segPts.push(ptPolar(rIn, deg));
    }
    modeWash("#e3caf7", 210);
    drawPoly(segPts, 0.06);
  }

  // Re-Pop the 8 cleft jewels inside the pith ring so they stay crisp
  for (let c of cells.slice(8, 16)) {
    modeWash(PALETTE[c.tier].edgeFill, 235);
    drawPoly(c.ptsOuter, 0.08);
    modeWash(PALETTE[c.tier].midWash, 225);
    drawPoly(c.ptsMid, 0.08);
    modeWash(PALETTE[c.tier].coreGlow, 240);
    drawPoly(c.ptsCore, 0.08);
  }

  // 2. Sculpted White Mullions & Arched Midribs
  // Outer cool-lilac 3D bevel pass
  modeWash("#dfc4f7", 225);
  for (let m of mullions) {
    drawPoly(m.polyOuter, 0.05);
  }

  // Inner luminous backlit ivory-white core pass
  modeWash("#fffaff", 248);
  for (let m of mullions) {
    drawPoly(m.polyInner, 0.05);
  }

  // 3. Botanical Parenchyma Striations & Vascular Bundle Dots inside White Ribs
  modeStroke("2H", "#b891de", 0.30);
  for (let m of mullions) {
    let n = m.polyOuter.length;
    let half = Math.floor(n / 2);
    for (let i = 2; i < half - 2; i += 2) {
      let p1 = m.polyOuter[i];
      let p2 = m.polyOuter[n - 1 - i];
      brush.line(
        p1[0] * 0.8 + p2[0] * 0.2,
        p1[1] * 0.8 + p2[1] * 0.2,
        p1[0] * 0.2 + p2[0] * 0.8,
        p1[1] * 0.2 + p2[1] * 0.8
      );
    }
  }

  // Vascular bundle dots along the midline of the thick arched midribs & central pith
  modeWash("#9c78b8", 210);
  for (let m of mullions) {
    if (m.hasVascular) {
      for (let i = 3; i < m.spine.length - 3; i += 2) {
        let p = m.spine[i];
        brush.circle(p[0], p[1], 2.2, 0.1);
      }
    }
  }
  modeWash("#c4b27a", 190);
  for (let s = 0; s < 24; s++) {
    let deg = s * 15 + 7.5;
    let r = 43 + 4 * Math.cos(8 * deg * DEG2RAD);
    let p = ptPolar(r, deg);
    brush.circle(p[0], p[1], 2.0, 0.1);
  }

  // Central embryonic star boss at dead center (r = 0..11)
  let starPts = [];
  for (let i = 0; i < 16; i++) {
    let deg = i * 22.5;
    let r = (i % 2 === 0) ? 11.5 : 6.0;
    starPts.push(ptPolar(r, deg));
  }
  modeWash("#fff7ff", 250);
  drawPoly(starPts, 0.05);
  modeWash("#ff1e8a", 235);
  brush.circle(CX, CY, 4.5, 0.05);
}

// Outline every leaf layer, pale vein, and white midrib with thick dark ink leading
function drawInkLeading() {
  // 1. Deep purple-black inner shadow bevel around all leaf cells
  modeStroke("cpencil", "#220236", 0.72);
  for (let c of cells) {
    drawPoly(c.ptsOuter, 0.08);
  }

  // 2. Crisp dark ink leading around every convoluted leaf cell
  modeStroke("rotring", "#0c0114", 0.78);
  for (let c of cells) {
    drawPoly(c.ptsOuter, 0.08);
  }

  // 3. Heavy structural ink leading around primary cells & sculpted white stone mullions
  modeStroke("pen", "#07000d", 1.05);
  for (let c of cells) {
    if (c.isPrimary) {
      drawPoly(c.ptsOuter, 0.08);
    }
  }

  modeStroke("rotring", "#08000f", 1.15);
  for (let m of mullions) {
    drawPoly(m.polyOuter, 0.05);
  }

  // 4. Concentric Ring Mullion Leading Cames (Gothic Rose Window Iron Armature Rings)
  const ringRadii = [27, 66, 144, 176, 278, 312, 424, 456];
  modeStroke("pen", "#090012", 1.10);
  for (let rBase of ringRadii) {
    let ringPts = [];
    let steps = 128;
    for (let i = 0; i < steps; i++) {
      let deg = (i / steps) * 360;
      let wave = (rBase < 100 ? 2.5 : 3.5) * Math.cos(8 * deg * DEG2RAD)
               + 1.8 * Math.cos(16 * deg * DEG2RAD);
      ringPts.push(ptPolar(rBase + wave, deg));
    }
    drawPoly(ringPts, 0.05);
  }

  // 5. Outer Cathedral Rim Leading (Scalloped perimeter against pitch black)
  for (let pass = 0; pass < 3; pass++) {
    let rOff = pass * 2.2;
    let rimPts = [];
    let steps = 160;
    for (let i = 0; i < steps; i++) {
      let deg = (i / steps) * 360;
      let r = 507 + rOff + 4.5 * Math.cos(8 * deg * DEG2RAD) + 3.0 * Math.cos(16 * deg * DEG2RAD);
      rimPts.push(ptPolar(r, deg));
    }
    modeStroke("pen", pass === 1 ? "#2b0542" : "#05000a", pass === 0 ? 1.55 : 1.25);
    drawPoly(rimPts, 0.05);
  }
}

// Render faint, ruler-straight hyperreal knife drag marks across the equatorial cut face
function drawKnifeDragMarks() {
  // Symmetric pairs of vertical shear lines left by the chef's knife blade slicing top-to-bottom
  const offsets = [
    6, 19, 34, 52, 71, 88, 109, 128, 146, 168, 189, 212,
    234, 258, 281, 306, 332, 358, 384, 412, 440, 468
  ];

  for (let idx = 0; idx < offsets.length; idx++) {
    let dx = offsets[idx];
    let maxChordY = Math.sqrt(Math.max(0, 502 * 502 - dx * dx));
    let isMajor = (idx % 3 === 0);

    for (let side of [-1, 1]) {
      let x = CX + side * dx;

      // Faint purple-magenta anthocyanin sap smear dragged onto the white ribs
      modeStroke("2H", idx % 2 === 0 ? "#c81d77" : "#7e16b8", isMajor ? 0.28 : 0.20);
      let segs = 9;
      for (let k = 0; k < segs; k++) {
        let f1 = -0.92 + (1.84 * k) / segs;
        let f2 = f1 + 0.11;
        let y1 = CY + f1 * maxChordY;
        let y2 = CY + f2 * maxChordY;
        brush.line(x, y1, x, y2);
      }

      // Razor-fine specular micro-scratch glinting across the cut surface
      modeStroke("2H", "#fbe8ff", isMajor ? 0.26 : 0.18);
      for (let k = 0; k < segs; k++) {
        let f1 = -0.86 + (1.84 * k) / segs;
        let f2 = f1 + 0.08;
        if (f2 <= 0.92) {
          let y1 = CY + f1 * maxChordY;
          let y2 = CY + f2 * maxChordY;
          brush.line(x + side * 0.8, y1, x + side * 0.8, y2);
        }
      }
    }
  }

  // Subtle horizontal blade-advance chatter arcs (strictly symmetrical)
  const chatterY = [-380, -295, -155, -62, 62, 155, 295, 380];
  modeStroke("2H", "#f5d4ff", 0.22);
  for (let dy of chatterY) {
    let halfW = Math.sqrt(Math.max(0, 485 * 485 - dy * dy)) * 0.75;
    let y = CY + dy;
    brush.line(CX - halfW, y, CX - halfW * 0.35, y);
    brush.line(CX + halfW * 0.35, y, CX + halfW, y);
  }
}

// Render 3D refractive moisture beads clinging to the cut veins and leaf chambers
function drawSingleBead(x, y, rad, isTinted) {
  // Direction from center for radial/top-lit optical consistency
  let vx = x - CX;
  let vy = y - CY;
  let dist = Math.hypot(vx, vy) || 1;
  let ux = vx / dist;
  let uy = (vy / dist) * 0.6 + 0.4; // Blend radial backlight with top-down studio light
  let uLen = Math.hypot(ux, uy) || 1;
  ux /= uLen;
  uy /= uLen;

  // 1. Cast contact shadow on the outer/lower side
  modeWash("#0c0117", 185);
  brush.circle(x + ux * rad * 0.38, y + uy * rad * 0.38, rad * 0.95, 0.08);

  // 2. Translucent droplet body wash
  modeWash(isTinted ? "#f294d4" : "#ebd4ff", 135);
  brush.circle(x, y, rad, 0.06);

  // 3. Lower-outer internal caustic lens focus
  modeWash("#fff2fc", 215);
  brush.circle(x + ux * rad * 0.28, y + uy * rad * 0.28, rad * 0.56, 0.05);

  // 4. Crisp dark refractive rim around the droplet
  modeStroke("rotring", "#1a022b", 0.45);
  brush.circle(x, y, rad, 0.06);

  // 5. Piercing pure white primary specular highlight on the upper-inner side
  let hx = x - ux * rad * 0.36;
  let hy = y - uy * rad * 0.36;
  modeWash("#ffffff", 255);
  brush.circle(hx, hy, Math.max(1.4, rad * 0.32), 0.02);

  modeStroke("rotring", "#ffffff", 0.65);
  brush.line(hx - rad * 0.12, hy, hx + rad * 0.12, hy);
}

function drawMoistureBeads() {
  // Strictly symmetrical pairs of moisture beads distributed across the white ribs & purple leaves
  const beadSpecs = [
    // [r, degOffsetFromSector, radius, isTinted, mirrorInSector]
    [48,  0,    4.2, false, false],
    [62,  22.5, 5.5, false, false],
    [92,  8.5,  3.8, true,  true],
    [122, 0,    4.8, true,  false],
    [156, 0,    7.8, false, false],
    [158, 10.5, 4.5, false, true],
    [172, 22.5, 5.2, false, false],
    [212, 11.2, 6.2, true,  true],
    [242, 14.5, 3.6, true,  true],
    [262, 0,    5.0, false, false],
    [292, 22.5, 8.5, false, false],
    [294, 13.0, 4.8, false, true],
    [328, 0,    5.8, false, false],
    [352, 16.0, 5.2, true,  true],
    [374, 5.5,  4.0, true,  true],
    [402, 22.5, 6.4, false, false],
    [436, 0,    7.2, false, false],
    [438, 9.0,  4.2, false, true],
    [468, 11.2, 5.0, true,  true],
    [488, 22.5, 4.4, true,  false]
  ];

  for (let spec of beadSpecs) {
    let [r, degOff, rad, isTinted, mirror] = spec;
    let modes = mirror ? [-1, 1] : [1];
    for (let m of modes) {
      for (let s = 0; s < 8; s++) {
        let deg = s * 45 + m * degOff;
        let p = ptPolar(r, deg);
        drawSingleBead(p[0], p[1], rad, isTinted);
      }
    }
  }
}

