// Evaluates how "wiped clear" a point (x, y) is inside the central pane.
// Returns 0.0 in fogged glass, 1.0 in the clear center of the hand-wiped streak,
// with organic finger-streak transitions along the boundary.
function getWipeFactor(x, y) {
  // Central pane bounds: x in [303, 857], y in [176, 1023]
  if (x < 312 || x > 848 || y < 190 || y > 960) return 0;

  // Hand wipe composed of 3 overlapping diagonal-curved palm/finger sweeps
  let best = 0;
  const sweeps = [
    { x1: 425, y1: 300, x2: 715, y2: 375, r: 155 },
    { x1: 395, y1: 440, x2: 735, y2: 530, r: 185 },
    { x1: 430, y1: 620, x2: 690, y2: 725, r: 165 },
    { x1: 545, y1: 320, x2: 575, y2: 790, r: 195 }
  ];

  for (let i = 0; i < sweeps.length; i++) {
    let s = sweeps[i];
    let dx = s.x2 - s.x1;
    let dy = s.y2 - s.y1;
    let len2 = dx * dx + dy * dy;
    let t = constrain(((x - s.x1) * dx + (y - s.y1) * dy) / len2, 0, 1);
    let px = s.x1 + t * dx;
    let py = s.y1 + t * dy;
    // Slight arc offset
    py -= sin(t * 180) * 24;
    let d = dist(x, y, px, py);

    // Finger-ridge modulation along angle
    let ang = atan2(y - py, x - px);
    let fingerGrooves =
      sin(ang * 14 + i * 40) * 10 +
      (noise(x * 0.018, y * 0.018, i * 3) - 0.5) * 38;
    let effR = s.r + fingerGrooves;

    let val = constrain(map(d, effR * 0.68, effR, 1, 0), 0, 1);
    best = max(best, val);
  }
  return best;
}

function drawBlobShape(cx, cy, rx, ry, pts, irregularity, rotDeg = 0) {
  brush.beginShape(0.45);
  for (let i = 0; i < pts; i++) {
    let a = (i / pts) * 360;
    let n = noise(cx * 0.01 + cos(a) * 1.3, cy * 0.01 + sin(a) * 1.3);
    let rMod = 1 + (n - 0.5) * irregularity;
    let lx = cos(a) * rx * rMod;
    let ly = sin(a) * ry * rMod;
    let gx = cx + lx * cos(rotDeg) - ly * sin(rotDeg);
    let gy = cy + lx * sin(rotDeg) + ly * cos(rotDeg);
    brush.vertex(gx, gy);
  }
  brush.endShape(true);
}

// =========================================================================
// 1. HUMID MILKY GROUND & WET-IN-WET BLURRED BOTANICALS (FOGGED PANES)
// =========================================================================
function drawFoggedGlasshouseBackground() {
  // Base milky celadon-earth tone
  background("#d7dcd1");
  brush.set("HB", "#c5cbc0", 1);

  // Broad atmospheric washes across the entire canvas (grouped by color for caching)
  brush.noStroke();
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.22);

  // Pearly grey-green and warm putty base clouds
  const mistClouds = [
    { c: "#ccd3c6", op: 95, blobs: [[180, 320, 220, 310], [990, 400, 230, 340], [580, 110, 420, 120], [580, 1100, 450, 110]] },
    { c: "#bfc7b8", op: 85, blobs: [[150, 740, 210, 290], [1020, 790, 220, 280], [450, 220, 260, 160], [760, 920, 260, 180]] },
    { c: "#d4cfc2", op: 75, blobs: [[220, 520, 190, 240], [940, 240, 200, 210], [620, 960, 310, 140], [140, 110, 200, 110]] },
    { c: "#e6eae0", op: 90, blobs: [[570, 200, 320, 140], [160, 260, 160, 190], [1010, 310, 180, 220], [830, 560, 170, 240]] }
  ];

  for (let group of mistClouds) {
    brush.fill(group.c, group.op);
    for (let b of group.blobs) {
      drawBlobShape(b[0], b[1], b[2], b[3], 14, 0.35, random(-20, 20));
    }
  }

  // Wet-in-wet blurred palms and ferns behind the fogged glass
  brush.fillBleed(0.58, "out");
  brush.fillTexture(0.65, 0.3);

  // Helper to paint an out-of-focus palm or fern frond as soft wet watercolour lobes
  function paintBlurredFrond(sx, sy, dirDeg, len, spread, leafletCount, col, op) {
    brush.fill(col, op);
    for (let i = 0; i < leafletCount; i++) {
      let t = i / (leafletCount - 1);
      let spineX = sx + cos(dirDeg) * len * t;
      let spineY = sy + sin(dirDeg) * len * t + t * t * 38;
      let side = i % 2 === 0 ? 1 : -1;
      let lAng = dirDeg + side * (32 + t * 28);
      let lLen = spread * sin(t * 170 + 10) * (0.75 + 0.35 * noise(i, sx * 0.01));
      let cx = spineX + cos(lAng) * lLen * 0.55;
      let cy = spineY + sin(lAng) * lLen * 0.55;
      drawBlobShape(cx, cy, lLen * 0.62, 18 + (1 - t) * 14, 10, 0.4, lAng);
    }
  }

  // Deep muted moss & olive fronds (left pane, right pane, top & bottom panes, and edges of center pane)
  paintBlurredFrond(40, 680, -48, 460, 125, 14, "#4b5944", 72);
  paintBlurredFrond(240, 890, -112, 420, 110, 13, "#3e4d39", 68);
  paintBlurredFrond(1160, 640, -135, 480, 135, 15, "#465440", 74);
  paintBlurredFrond(920, 920, -72, 430, 115, 13, "#596850", 65);
  paintBlurredFrond(340, 240, 22, 340, 95, 11, "#52614a", 55);
  paintBlurredFrond(840, 290, 158, 330, 95, 11, "#44523d", 58);

  // Warm earth / dried fern / terracotta pot shapes in the lower glasshouse haze
  brush.fill("#785e47", 64);
  drawBlobShape(155, 950, 95, 115, 12, 0.3, 5);
  drawBlobShape(1035, 965, 110, 120, 12, 0.3, -4);
  drawBlobShape(380, 960, 85, 95, 12, 0.35, 8);

  brush.fill("#634d3a", 58);
  paintBlurredFrond(180, 830, -82, 290, 85, 10, "#6b5742", 52);
  paintBlurredFrond(1000, 810, -98, 310, 90, 10, "#756049", 50);
  paintBlurredFrond(790, 870, -118, 260, 80, 9, "#5c674f", 54);

  // Secondary pale celadon & milky condensation wash over the botanicals to push them into fog
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.42, 0.16);
  brush.fill("#d8ddd2", 82);
  drawBlobShape(150, 560, 150, 420, 16, 0.25, 0);
  drawBlobShape(1030, 560, 160, 420, 16, 0.25, 0);
  drawBlobShape(600, 90, 540, 80, 16, 0.2, 0);
