// =========================================================================
// 2. WIPED STREAK INTERIOR DEPTH & SHARP BOTANICAL BACKDROP
// =========================================================================
function drawWipedInteriorBackdrop() {
  // Deep humid glasshouse shadow behind the gardener's head inside the wiped zone
  brush.noStroke();
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.45, 0.2);

  // Dark olive-umber interior cavity following the hand-wiped silhouette
  const interiorLayers = [
    { c: "#2b3328", op: 165, scale: 0.96 },
    { c: "#22291f", op: 155, scale: 0.86 },
    { c: "#332a22", op: 115, scale: 0.76 }
  ];

  for (let layer of interiorLayers) {
    brush.fill(layer.c, layer.op);
    brush.beginShape(0.42);
    const cx = 572, cy = 545;
    const pts = 32;
    for (let i = 0; i < pts; i++) {
      let a = (i / pts) * 360;
      // Search outward from center for the wipe boundary
      let r = 60;
      for (let testR = 60; testR < 370; testR += 12) {
        let tx = cx + cos(a) * testR * 0.78;
        let ty = cy + sin(a) * testR * 1.05;
        if (getWipeFactor(tx, ty) > 0.32) r = testR;
      }
      r *= layer.scale;
      brush.vertex(cx + cos(a) * r * 0.78, cy + sin(a) * r * 1.05);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // Sharp, dark-olive fern leaflets glimpsed in the deep background upper-left & upper-right of the wipe
  const bgLeafCols = ["#3e4d37", "#4f6146", "#2e3b29", "#655543"];
  for (let side of [-1, 1]) {
    let baseX = side === -1 ? 395 : 755;
    let baseY = side === -1 ? 390 : 410;
    for (let k = 0; k < 14; k++) {
      let ly = baseY + k * 18 - 90;
      let lx = baseX + side * (k * 4 - 25);
      if (getWipeFactor(lx, ly) < 0.35) continue;
      brush.set("cpencil", random(bgLeafCols), random(0.45, 0.85));
      let tipX = lx - side * random(35, 65);
      let tipY = ly + random(-14, 18);
      brush.spline([[lx, ly, 0.8], [(lx + tipX) * 0.5, (ly + tipY) * 0.5 - 6, 1.0], [tipX, tipY, 0.2]], 0.4);
    }
  }
}

