      brush.line(px, py, px + 1.1, py + 0.8);

      // Adjacent humid skin micro-highlight on 55% of pores
      if (random() < 0.55) {
        let hiCol = random(["#e8d2bd", "#f4e6d8", "#d6b89e"]);
        brush.set("micro", hiCol, random(0.4, 0.75));
        brush.line(px - 0.9, py - 1.1, px + 0.2, py - 0.8);
      }
    }
  }

  // ---- G. EYES & EYEBROWS (HYPERREAL ANATOMY) ----
  function drawHyperrealEye(cx, cy, rx, ry, isRight) {
    let dir = isRight ? 1 : -1;

    // Upper & lower eyelid folds (warm shadow + crease)
    brush.noStroke();
    brush.fillBleed(0.08, "in");
    brush.fill("#694736", 150);
    drawBlobShape(cx, cy - 6, rx * 1.18, ry * 1.35, 14, 0.08, dir * -2);

    // Sclera (moist off-white with warm corner shading)
    brush.fill("#d4d6ce", 225);
    brush.beginShape(0.35);
    brush.vertex(cx - rx, cy + dir * 2);
    brush.vertex(cx - rx * 0.45, cy - ry);
    brush.vertex(cx + rx * 0.45, cy - ry * 0.92);
    brush.vertex(cx + rx, cy - dir * 1);
    brush.vertex(cx + rx * 0.45, cy + ry * 0.88);
    brush.vertex(cx - rx * 0.45, cy + ry * 0.92);
    brush.endShape(true);

    // Pinkish lacrimal caruncle at inner corner
    let innerX = isRight ? cx - rx * 0.86 : cx + rx * 0.86;
    brush.fill("#9e5c4e", 210);
    brush.circle(innerX, cy + 2, 5.5, 0.15);

    // Iris (deep hazel-earth outer ring, warm amber-ochre stroma)
    let ix = cx - dir * 2;
    let iy = cy - 1;
    let ir = ry * 0.92;
    brush.fill("#282118", 240);
    brush.circle(ix, iy, ir, 0.05);
    brush.fill("#5c4429", 215);
    brush.circle(ix, iy, ir * 0.84, 0.06);
    brush.noFill();

    // Radial iris fibers
    for (let a = 0; a < 360; a += 7) {
      let col = a % 14 === 0 ? "#8f6d43" : (a % 21 === 0 ? "#b08a58" : "#382919");
      brush.set("micro", col, 0.65);
      let r1 = ir * 0.34;
      let r2 = ir * random(0.78, 0.94);
      brush.line(ix + cos(a) * r1, iy + sin(a) * r1, ix + cos(a) * r2, iy + sin(a) * r2);
    }

    // Pupil
    brush.noStroke();
    brush.fill("#110e0b", 250);
    brush.circle(ix, iy, ir * 0.36, 0.03);
    brush.noFill();

    // Upper eyelid cast shadow across top of iris & sclera
    for (let s = 0; s < 8; s++) {
      brush.set("2H", "#2e2018", 0.55);
      let sy = cy - ry + s * 1.4;
      brush.line(cx - rx * 0.82, sy + 2, cx + rx * 0.82, sy + 1);
    }

    // Crisp upper palpebral crease & lid margin
    brush.set("micro", "#331f15", 1.35);
    brush.spline([
      [cx - rx * 1.05, cy + 3, 0.4],
      [cx - rx * 0.45, cy - ry * 0.98, 1.0],
      [cx + rx * 0.45, cy - ry * 0.92, 1.0],
      [cx + rx * 1.05, cy + 1, 0.4]
    ], 0.42);

    // Supraorbital fold above lid
    brush.set("micro", "#472c1f", 1.1);
    brush.spline([
      [cx - rx * 1.12, cy - 6, 0.3],
      [cx - rx * 0.45, cy - ry * 1.58, 1.0],
      [cx + rx * 0.48, cy - ry * 1.52, 1.0],
      [cx + rx * 1.15, cy - 8, 0.3]
    ], 0.42);

    // Lower wet waterline (mucocutaneous junction)
    brush.set("micro", "#e8d2c3", 0.95);
    brush.spline([
      [cx - rx * 0.88, cy + 4, 0.4],
      [cx, cy + ry * 0.92, 1.0],
      [cx + rx * 0.88, cy + 2, 0.4]
    ], 0.4);

    // Lower eye bag & crow's feet creases
    brush.set("micro", "#664635", 0.85);
    brush.spline([
      [cx - rx * 0.95, cy + 12, 0.3],
      [cx, cy + ry * 1.55, 0.9],
      [cx + rx * 0.98, cy + 10, 0.3]
    ], 0.4);

    let outerX = isRight ? cx + rx * 1.05 : cx - rx * 1.05;
    for (let c = -2; c <= 2; c++) {
      let ang = isRight ? c * 11 - 5 : 180 - c * 11 + 5;
      brush.set("micro", "#5c3d2d", 0.75);
      brush.line(outerX, cy + c * 3, outerX + cos(ang) * 26, cy + c * 3 + sin(ang) * 26);
    }

    // Individual curved eyelashes (upper & lower)
    for (let k = 0; k < 28; k++) {
      let t = k / 27;
      let lx = lerp(cx - rx * 0.92, cx + rx * 0.92, t);
      let archY = cy - sin(t * 180) * ry * 0.96;
      let lashAng = map(t, 0, 1, isRight ? -115 : -65, isRight ? -55 : -125);
      let lashLen = sin(t * 180) * 11 + 4;
      brush.set("strand", "#1f1611", 0.95);
      brush.spline([
        [lx, archY, 1.0],
        [lx + cos(lashAng) * lashLen * 0.5, archY + sin(lashAng) * lashLen * 0.5, 0.7],
        [lx + cos(lashAng - dir * 14) * lashLen, archY + sin(lashAng - dir * 14) * lashLen, 0.1]
      ], 0.4);
    }
    for (let k = 0; k < 18; k++) {
      let t = k / 17;
      let lx = lerp(cx - rx * 0.82, cx + rx * 0.82, t);
      let archY = cy + sin(t * 180) * ry * 0.92 + 2;
      let lashAng = map(t, 0, 1, 110, 70);
      let lashLen = sin(t * 180) * 6 + 2.5;
      brush.set("strand", "#36271e", 0.7);
      brush.line(lx, archY, lx + cos(lashAng) * lashLen, archY + sin(lashAng) * lashLen);
    }

    // Razor-sharp glasshouse window reflection in cornea
    brush.set("micro", "#ffffff", 1.3);
    brush.line(ix - 5, iy - 6, ix - 1, iy - 7);
    brush.line(ix - 5, iy - 4, ix - 1, iy - 5);
    brush.set("micro", "#e4ece0", 0.9);
    brush.line(ix + 5, iy + 5, ix + 7, iy + 4);
  }

  drawHyperrealEye(492, 518, 38, 19, false);
  drawHyperrealEye(650, 514, 40, 20, true);

  // Bushy, weathered eyebrows (dark umber mixed with coarse silver-ochre hairs)
  function drawEyebrow(xStart, xEnd, yPeak, isRight) {
    let dir = isRight ? 1 : -1;
    for (let i = 0; i < 165; i++) {
      let t = random();
      let bx = lerp(xStart, xEnd, t);
      let arch = sin(t * 180) * 14;
      let by = yPeak - arch + random(-7, 7);
      let hAng = isRight
        ? map(t, 0, 1, -55, 18) + random(-10, 10)
        : map(t, 0, 1, -125, -198) + random(-10, 10);
      let hLen = random(14, 26) * (0.65 + 0.5 * sin(t * 180));
      let col = random() < 0.22
        ? random(["#c7c0b2", "#9e9484"]) // Silver-grey brow hairs
        : random(["#241b15", "#362920", "#4a382c"]);
      brush.set("strand", col, random(0.7, 1.15));
      brush.spline([
        [bx, by, 0.9],
        [bx + cos(hAng) * hLen * 0.55, by + sin(hAng) * hLen * 0.55, 0.8],
        [bx + cos(hAng + dir * 12) * hLen, by + sin(hAng + dir * 12) * hLen, 0.1]
      ], 0.35);
    }
  }
  drawEyebrow(544, 428, 468, false);
  drawEyebrow(596, 718, 464, true);

  // ---- H. PHILTRUM, MOUTH & WEATHERED STUBBLE ----
  // Philtrum columns
  brush.set("micro", "#593b2b", 0.9);
  brush.spline([[555, 636, 0.4], [552, 662, 0.9], [548, 686, 0.5]], 0.35);
  brush.spline([[580, 636, 0.4], [583, 662, 0.9], [587, 686, 0.5]], 0.35);
  brush.set("micro", "#dec4ad", 0.8);
  brush.spline([[551, 638, 0.3], [548, 662, 0.9], [544, 684, 0.4]], 0.35);
  brush.spline([[584, 638, 0.3], [587, 662, 0.9], [591, 684, 0.4]], 0.35);

  // Upper & lower lips
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  // Upper lip in shaded earth-rose
  brush.fill("#6e4839", 210);
  brush.beginShape(0.3);
  brush.vertex(504, 701);
  brush.vertex(546, 684);
  brush.vertex(568, 691);
  brush.vertex(590, 684);
  brush.vertex(634, 699);
  brush.vertex(568, 703);
  brush.endShape(true);

  // Lower lip catching humid top light
  brush.fill("#9e6b58", 195);
  brush.beginShape(0.35);
  brush.vertex(508, 702);
  brush.vertex(568, 703);
  brush.vertex(630, 700);
  brush.vertex(604, 724);
  brush.vertex(568, 728);
  brush.vertex(532, 724);
  brush.endShape(true);
  brush.noFill();

  // Lip parting line (oral fissure)
  brush.set("micro", "#2b1810", 1.35);
  brush.spline([
    [502, 701, 0.5],
    [536, 698, 0.95],
    [568, 703, 1.0],
    [600, 697, 0.95],
    [636, 699, 0.5]
  ], 0.4);

  // Vertical lip creases & damp specular highlights on lower lip
  for (let lx = 522; lx <= 616; lx += 4.5) {
    let distC = abs(lx - 568);
    let botY = map(distC, 0, 48, 726, 708);
    brush.set("micro", "#573629", 0.65);
    brush.spline([[lx, 702, 0.4], [lx + (lx - 568) * 0.06, (702 + botY) * 0.5, 0.9], [lx, botY, 0.3]], 0.35);
    if (distC < 34) {
      brush.set("micro", "#ebcfc0", 0.75);
      brush.line(lx + 1.2, 707, lx + 1.4, 715);
    }
  }

  // Fine weathered stubble (short individual hairs across upper lip, chin, and jaw)
  for (let i = 0; i < 420; i++) {
    let sx = random(450, 690);
    let sy = random(642, 798);
    // Skip the lips themselves
    if (sx > 504 && sx < 634 && sy > 683 && sy < 727) continue;
    let dC = abs(sx - 568);
    if (sy > 720 && dC > map(sy, 720, 798, 115, 48)) continue;
    if (sy < 685 && dC > 62) continue;
    if (getWipeFactor(sx, sy) < 0.42) continue;

    let ang = 90 + (sx - 568) * 0.28 + random(-12, 12);
    let len = random(2.5, 5.5);
    let col = random() < 0.32
      ? random(["#d4cec2", "#aba293"]) // Salt/silver stubble
      : random(["#33261d", "#47362a", "#5c4738"]);
    brush.set("micro", col, random(0.55, 0.9));
    brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }

  // ---- I. DAMP CURL OF HAIR FALLING ACROSS THE FOREHEAD ----
  // Upper hair mass at top of wiped streak
  for (let i = 0; i < 240; i++) {
    let hx = random(405, 735);
    let hy = random(245, 345);
    if (getWipeFactor(hx, hy) < 0.32) continue;
    let ang = map(hx, 405, 735, 135, 45) + random(-18, 18);
    let len = random(28, 62);
    let col = random(["#1a1410", "#29201a", "#382c23", "#4f4034", "#8c8579"]);
    brush.set("strand", col, random(0.85, 1.4));
    brush.spline([
      [hx, hy, 0.8],
      [hx + cos(ang) * len * 0.5, hy + sin(ang) * len * 0.5, 1.0],
      [hx + cos(ang + 15) * len, hy + sin(ang + 15) * len, 0.2]
    ], 0.45);
  }

  // The signature damp curl of hair spiraling down onto the center-right forehead
  // First: soft warm cast shadow of the curl onto the damp forehead skin
  for (let s = 0; s < 18; s++) {
    let off = (s - 9) * 0.9;
    brush.set("2H", "#4d3223", 0.45);
    brush.spline([
      [582 + off, 278, 0.6],
      [564 + off, 332, 1.0],
      [594 + off, 378, 1.0],
      [576 + off, 424, 0.9],
      [548 + off, 434, 0.7],
      [542 + off, 412, 0.3]
    ], 0.55);
  }

  // Hundreds of fine wet strands forming the clumped S-curl and stray damp filaments
  for (let k = 0; k < 110; k++) {
    let spread = map(k, 0, 109, -14, 14);
    let taper = 1 - abs(spread) / 16;
    let n1 = (noise(k * 0.15, 1) - 0.5) * 8;
    let n2 = (noise(k * 0.15, 2) - 0.5) * 8;

    let pts = [
      [584 + spread * 1.3, 268, 0.9],
      [558 + spread * 0.95 + n1, 326, 1.0],
      [590 + spread * 0.75 + n2, 374, 1.0],
      [572 + spread * 0.45, 420, 0.85],
      [545 + spread * 0.25, 430 + spread * 0.2, 0.6],
      [538 + spread * 0.12, 408 + spread * 0.15, 0.15]
    ];

    let isHighlight = k > 42 && k < 64 && k % 2 === 0;
    let isSilver = k % 13 === 0;
    let col = isHighlight
      ? random(["#9ea89b", "#c5cfc1", "#78695a"]) // Humid wet sheen on curl turn
      : isSilver
        ? "#a8a195"
        : random(["#140f0c", "#211914", "#2e231c", "#3d2f25"]);

    brush.set("strand", col, isHighlight ? 0.75 : random(0.85, 1.3) * taper + 0.3);
    brush.spline(pts, 0.58);
  }

  // Delicate stray wet baby-hairs clinging to forehead skin beside the main curl
  for (let s = 0; s < 14; s++) {
    let sx = 562 + random(-28, 32);
    let sy = 310 + s * 8;
    brush.set("micro", "#261c16", 0.65);
    brush.spline([
      [sx, sy, 0.8],
      [sx + random(-18, 18), sy + 22, 0.6],
      [sx + random(-24, 24), sy + 42, 0.1]
    ], 0.5);
  }

  // ---- J. SPECTACLES & STEAM ON THE LENSES ----
  const leftLens = { cx: 490, cy: 520, rx: 62, ry: 47, rot: 2 };
  const rightLens = { cx: 652, cy: 516, rx: 64, ry: 48, rot: -2 };

  // 1. Steam clouds condensed on the spectacle lenses (veiling parts of the eye/cheek while keeping upper-outer iris clear)
  brush.noStroke();
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.42, 0.15);

  // Milky steam washes on lower-inner and upper-inner portions of both lenses
  brush.fill("#dce0d6", 135);
  drawBlobShape(512, 540, 36, 24, 12, 0.25, -10);
  drawBlobShape(462, 495, 28, 18, 12, 0.25, 15);
  drawBlobShape(624, 536, 38, 25, 12, 0.25, 12);
  drawBlobShape(682, 492, 30, 19, 12, 0.25, -14);

  brush.fill("#eff2ea", 110);
  drawBlobShape(518, 544, 24, 16, 10, 0.2, -8);
  drawBlobShape(618, 540, 26, 17, 10, 0.2, 10);
  brush.noFill();

  // Micro-condensation stippling & diagonal glass reflection across spectacle lenses
  for (let lens of [leftLens, rightLens]) {
    for (let i = 0; i < 130; i++) {
      let a = random(360);
      let r = sqrt(random()) * 0.94;
      let lx = cos(a) * lens.rx * r;
      let ly = sin(a) * lens.ry * r;
      // Leave a clearer window right over the pupil/iris center
      if (dist(lx, ly, -4, -4) < 22 && random() < 0.78) continue;
      let px = lens.cx + lx;
      let py = lens.cy + ly;
      let col = random(["#e3e8dd", "#f2f5ee", "#c2c9bc"]);
      brush.set("micro", col, random(0.4, 0.85));
      brush.line(px, py, px + 1.2, py + 0.8);
    }

    // Crisp diagonal glasshouse skylight reflection on lens surface
    for (let k = 0; k < 9; k++) {
      let off = k * 2.2;
      brush.set("micro", "#f4f7f0", 0.75);
      brush.line(lens.cx - 38 + off, lens.cy - 28, lens.cx - 14 + off, lens.cy - 8);
    }
  }

  // 2. Cast shadow of the wire frames onto the cheek and nasal bridge
  for (let lens of [leftLens, rightLens]) {
    brush.set("2H", "#472e20", 0.85);
    brush.beginShape(0.42);
    for (let a = 15; a <= 175; a += 12) {
      let gx = lens.cx + cos(a) * lens.rx;
      let gy = lens.cy + sin(a) * lens.ry + 6;
      brush.vertex(gx, gy);
    }
    brush.endShape(false);
  }

  // 3. Antiqued brass / oxidized wire spectacle frames
  function drawLensRim(lens) {
    // Dark bronze core rim
    for (let pass = 0; pass < 3; pass++) {
      let col = pass === 0 ? "#241b13" : (pass === 1 ? "#4a3826" : "#6e563c");
      let w = pass === 0 ? 1.55 : (pass === 1 ? 1.05 : 0.55);
      let dy = pass === 2 ? -1.0 : 0;
      brush.set("micro", col, w);
      brush.beginShape(0.42);
      for (let a = 0; a < 360; a += 10) {
        let lx = cos(a) * lens.rx;
        let ly = sin(a) * lens.ry;
        let gx = lens.cx + lx * cos(lens.rot) - ly * sin(lens.rot);
        let gy = lens.cy + lx * sin(lens.rot) + ly * cos(lens.rot) + dy;
        brush.vertex(gx, gy);
      }
      brush.endShape(true);
    }

    // Specular brass glints along upper rim
    brush.set("micro", "#f0e4ce", 1.15);
    brush.beginShape(0.4);
    for (let a = 215; a <= 315; a += 10) {
      brush.vertex(lens.cx + cos(a) * lens.rx, lens.cy + sin(a) * lens.ry - 1.2);
    }
    brush.endShape(false);
  }

  drawLensRim(leftLens);
  drawLensRim(rightLens);

  // Arched saddle bridge over the nose + nose pads + side temple arms
  brush.set("micro", "#261c14", 1.6);
  brush.spline([[552, 514, 1.0], [571, 498, 1.0], [588, 513, 1.0]], 0.45);
  brush.set("micro", "#8c7051", 0.95);
  brush.spline([[552, 512.5, 0.9], [571, 496.5, 1.0], [588, 511.5, 0.9]], 0.45);
  brush.set("micro", "#f2e7d3", 0.8);
  brush.spline([[560, 502, 0.6], [571, 496, 1.0], [581, 501, 0.6]], 0.4);

  // Temple arms receding toward ears
  brush.set("micro", "#2b2017", 1.35);
  brush.line(428, 516, 405, 498);
  brush.line(716, 512, 742, 494);
  brush.set("micro", "#c9b393", 0.75);
  brush.line(428, 514.5, 405, 496.5);
  brush.line(716, 510.5, 742, 492.5);
}

// =========================================================================
// 4. HAND-WIPED STREAK SMEARS, CONDENSATION VEIL & REFRACTED DRIPS
// =========================================================================
function drawGlassSurfaceAndDrips() {
  // ---- A. HAND-WIPED STREAK BOUNDARY & FINGER SMEAR TRACKS ----
  // Where getWipeFactor transitions between 0.05 and 0.65, moisture piles up in streaky ridges
  const fingerPaths = [
    [[375, 295], [485, 268], [615, 275], [735, 330]],
    [[355, 385], [495, 345], [635, 360], [765, 435]],
    [[360, 560], [505, 625], [645, 645], [755, 585]],
    [[395, 755], [515, 825], [635, 830], [725, 760]],
    [[365, 340], [348, 490], [365, 645], [410, 780]],
    [[745, 355], [772, 505], [755, 660], [710, 785]]
  ];

  for (let path of fingerPaths) {
    for (let s = 0; s < 14; s++) {
      let offX = random(-16, 16);
      let offY = random(-16, 16);
      let pts = path.map(p => [p[0] + offX + random(-6, 6), p[1] + offY + random(-6, 6), random(0.4, 1.0)]);
      let col = s % 3 === 0 ? "#eef2ea" : (s % 2 === 0 ? "#cfd6c8" : "#aeb8a8");
      brush.set("smear", col, random(0.6, 1.3));
      brush.spline(pts, 0.45);
    }
  }

  // Feathered condensation encroaching onto the edges of the portrait
  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.48, 0.2);
  brush.fill("#d5dbd0", 95);

  const edgePuffs = [
    [390, 310, 48, 55], [748, 330, 52, 62],
    [365, 470, 42, 75], [772, 495, 45, 78],
    [380, 680, 48, 72], [758, 690, 48, 72],
    [435, 835, 65, 48], [695, 835, 65, 48],
    [568, 868, 95, 38], [568, 242, 110, 36]
  ];
  for (let p of edgePuffs) {
    drawBlobShape(p[0], p[1], p[2], p[3], 12, 0.35, random(-25, 25));
  }
  brush.noFill();

  // ---- B. FINE CONDENSATION BEADS ACROSS FOGGED PANES & WIPE RIM ----
  for (let i = 0; i < 680; i++) {
    let bx = random(32, 1168);
    let by = random(28, 1168);
    let wf = getWipeFactor(bx, by);

    // Dense along the wipe boundary ridge, sparse inside the clear wipe, abundant on fogged panes
    if (wf > 0.55 && random() < 0.92) continue;
    let isRidge = wf > 0.12 && wf <= 0.55;
    let r = isRidge ? random(1.8, 4.5) : random(1.0, 3.2);

    // Upper crescent shadow of micro-bead
    brush.set("micro", "#5f6b5b", 0.7);
    brush.line(bx - r * 0.6, by - r * 0.5, bx + r * 0.6, by - r * 0.5);

    // Lower refracted glow & top-left pinpoint highlight
    brush.set("micro", "#f4f7f0", 0.9);
    brush.line(bx - r * 0.35, by - r * 0.25, bx + 0.4, by - r * 0.25);
    brush.set("micro", "#e1e7dc", 0.65);
    brush.line(bx - r * 0.4, by + r * 0.55, bx + r * 0.4, by + r * 0.55);
  }

  // ---- C. SINGLE HYPERREAL DRIPS WITH RIVULET TRAILS & REFRACTED HIGHLIGHTS ----
  function drawHyperrealDrip(xStart, yStart, yEnd, dropRadius, overFace = false) {
    let steps = floor((yEnd - yStart) / 14);
    let trailPts = [];
    let curX = xStart;

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let py = lerp(yStart, yEnd, t);
      // Natural surface-tension meander
      curX += (noise(xStart * 0.05, py * 0.015) - 0.495) * 4.8;
      trailPts.push([curX, py]);
    }

    let headX = trailPts[trailPts.length - 1][0];
    let headY = trailPts[trailPts.length - 1][1];

    // 1. Swept rivulet track above the drop (cuts a clearer channel through the condensation)
    for (let i = 0; i < trailPts.length - 1; i++) {
      let p1 = trailPts[i];
      let p2 = trailPts[i + 1];
      let t = i / trailPts.length;
      let w = lerp(dropRadius * 0.25, dropRadius * 0.68, t);

      // Slightly darker interior channel where fog was wiped away by the falling drop
      let trackCol = overFace ? "#7d5b46" : "#74826e";
      brush.set("2H", trackCol, w * 0.28);
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      // Left & right meniscus water rims along the rivulet track
      brush.set("micro", "#4e5c4a", 0.6);
      brush.line(p1[0] - w, p1[1], p2[0] - w, p2[1]);
      brush.set("micro", "#f2f6ee", 0.85);
      brush.line(p1[0] - w * 0.55, p1[1], p2[0] - w * 0.55, p2[1]);
      brush.set("micro", "#d8e0d2", 0.65);
      brush.line(p1[0] + w * 0.8, p1[1], p2[0] + w * 0.8, p2[1]);

      // Occasional tiny satellite bead left behind in the track
      if (i % 4 === 2 && i < trailPts.length - 3) {
        brush.set("micro", "#ffffff", 0.95);
        brush.line(p1[0] - 0.8, p1[1], p1[0] + 0.5, p1[1]);
      }
    }

    // 2. Caustic light glow cast immediately below the heavy droplet
    brush.noStroke();
    brush.fillBleed(0.12, "out");
    brush.fill("#eff4ea", 135);
    drawBlobShape(headX + 1, headY + dropRadius * 1.18, dropRadius * 0.82, dropRadius * 0.45, 10, 0.1, 0);

    // 3. Droplet body (inverted refraction: dark top crescent, luminous lower belly)
    let topShade = overFace ? "#2b1c14" : "#28362a";
    let midRefract = overFace ? "#966d54" : "#6f8069";
    let bellyGlow = overFace ? "#e8d2be" : "#dce4d5";

    brush.fillBleed(0.04, "in");
    // Base teardrop lens
    brush.fill(midRefract, 195);
    brush.beginShape(0.42);
    brush.vertex(headX, headY - dropRadius * 1.35);
    brush.vertex(headX + dropRadius * 0.92, headY - dropRadius * 0.15);
    brush.vertex(headX + dropRadius * 0.98, headY + dropRadius * 0.55);
    brush.vertex(headX, headY + dropRadius * 1.02);
    brush.vertex(headX - dropRadius * 0.98, headY + dropRadius * 0.55);
    brush.vertex(headX - dropRadius * 0.92, headY - dropRadius * 0.15);
    brush.endShape(true);

    // Dark internal refraction at top of droplet
    brush.fill(topShade, 215);
    drawBlobShape(headX, headY - dropRadius * 0.38, dropRadius * 0.72, dropRadius * 0.52, 10, 0.08, 0);

    // Luminous refracted belly at bottom of droplet
    brush.fill(bellyGlow, 210);
    drawBlobShape(headX + 0.8, headY + dropRadius * 0.42, dropRadius * 0.68, dropRadius * 0.42, 10, 0.08, 0);
    brush.noFill();

    // Crisp dark surface-tension outline around droplet perimeter
    brush.set("micro", topShade, 0.95);
    brush.beginShape(0.42);
    brush.vertex(headX, headY - dropRadius * 1.35);
    brush.vertex(headX + dropRadius * 0.94, headY - dropRadius * 0.12);
    brush.vertex(headX + dropRadius * 0.98, headY + dropRadius * 0.56);
    brush.vertex(headX, headY + dropRadius * 1.02);
    brush.vertex(headX - dropRadius * 0.98, headY + dropRadius * 0.56);
    brush.vertex(headX - dropRadius * 0.94, headY - dropRadius * 0.12);
    brush.endShape(true);

    // 4. Razor-sharp primary specular highlight (curved window reflection on upper-left)
    brush.set("micro", "#ffffff", 1.45);
    brush.spline([
      [headX - dropRadius * 0.52, headY - dropRadius * 0.55, 0.8],
      [headX - dropRadius * 0.62, headY - dropRadius * 0.12, 1.0],
      [headX - dropRadius * 0.42, headY + dropRadius * 0.22, 0.7]
    ], 0.45);
    brush.set("micro", "#ffffff", 1.25);
    brush.line(headX - dropRadius * 0.32, headY - dropRadius * 0.68, headX - dropRadius * 0.22, headY - dropRadius * 0.52);

    // Secondary rim reflection along bottom-right crescent
    brush.set("micro", "#f7faf4", 1.05);
    brush.spline([
      [headX - dropRadius * 0.25, headY + dropRadius * 0.82, 0.5],
      [headX + dropRadius * 0.38, headY + dropRadius * 0.76, 1.0],
      [headX + dropRadius * 0.74, headY + dropRadius * 0.35, 0.5]
    ], 0.45);
  }

  // Drips across the fogged panes and right across the wiped glass over the gardener's face!
  const drips = [
    // Left tall pane drips
    { x: 95, y1: 195, y2: 610, r: 7.5, face: false },
    { x: 178, y1: 240, y2: 845, r: 9.0, face: false },
    { x: 232, y1: 420, y2: 735, r: 6.5, face: false },
    // Center tall pane drips (including tracks cutting across the wiped portrait!)
    { x: 348, y1: 190, y2: 595, r: 8.2, face: false },
    { x: 446, y1: 215, y2: 665, r: 8.8, face: true },   // Runs down across left brow, spectacle rim & cheek!
    { x: 608, y1: 185, y2: 472, r: 7.8, face: true },   // Runs down forehead beside the damp curl!
    { x: 702, y1: 280, y2: 785, r: 9.4, face: true },   // Long drip past right spectacle edge & jaw!
    { x: 805, y1: 220, y2: 910, r: 8.5, face: false },
    // Right tall pane drips
    { x: 942, y1: 195, y2: 680, r: 8.8, face: false },
    { x: 1038, y1: 310, y2: 895, r: 9.2, face: false },
    { x: 1118, y1: 210, y2: 560, r: 7.0, face: false },
    // Upper & lower pane drips
    { x: 465, y1: 32, y2: 142, r: 6.8, face: false },
    { x: 740, y1: 28, y2: 138, r: 6.2, face: false },
    { x: 530, y1: 1055, y2: 1162, r: 7.2, face: false }
  ];

  for (let d of drips) {
    drawHyperrealDrip(d.x, d.y1, d.y2, d.r, d.face);
  }
}

// =========================================================================
// 5. CAST-IRON MULLION GRID IN DARK VERDIGRIS & WEATHERED PUTTY
// =========================================================================
function drawCastIronMullions() {
  const vBars = [
    { x: 14, w: 28 },
    { x: 290, w: 28 },
    { x: 870, w: 28 },
    { x: 1186, w: 28 }
  ];
  const hBars = [
    { y: 12, h: 24 },
    { y: 165, h: 24 },
    { y: 1035, h: 26 },
    { y: 1188, h: 24 }
  ];

  // 1. Glazing putty bevels & moisture stains along pane perimeters
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.3);
  brush.fill("#4a4538", 150);

  for (let vb of vBars) {
    brush.rect(vb.x, 600, vb.w + 14, 1200, "center");
  }
  for (let hb of hBars) {
    brush.rect(600, hb.y, 1200, hb.h + 14, "center");
  }

  // 2. Solid dark cast-iron core
  brush.noFill();
  brush.wash("#192420", 245);
  for (let vb of vBars) {
    brush.rect(vb.x, 600, vb.w, 1200, "center");
  }
  for (let hb of hBars) {
    brush.rect(600, hb.y, 1200, hb.h, "center");
  }

  // Cast-iron corner gusset brackets at the 4 main structural intersections
  const intersections = [
    [290, 165], [870, 165],
    [290, 1035], [870, 1035]
  ];
  for (let pt of intersections) {
    brush.rect(pt[0], pt[1], 56, 56, "center");
  }
  brush.noWash();

  // 3. Dry pigment verdigris patina & raw umber rust encrustations
  for (let vb of vBars) {
    for (let i = 0; i < 48; i++) {
      let py = random(20, 1180);
      let px = vb.x + random(-vb.w * 0.42, vb.w * 0.42);
      let isRust = random() < 0.28;
      let col = isRust
        ? random(["#593d29", "#6e4c34", "#452f20"])
        : random(["#2f4d43", "#3f6659", "#527d6e", "#6b9686", "#84ab9c"]);
      brush.set("charcoal", col, random(0.6, 1.45));
      brush.line(px, py - random(8, 28), px + random(-3, 3), py + random(8, 28));
    }
    // Wet highlight ridge along left molded edge of vertical mullion
    brush.set("micro", "#9ab5a9", 0.9);
    brush.line(vb.x - vb.w * 0.36, 0, vb.x - vb.w * 0.36, 1200);
    // Deep shadow groove down center-right of mullion
    brush.set("micro", "#0d1412", 1.2);
    brush.line(vb.x + vb.w * 0.25, 0, vb.x + vb.w * 0.25, 1200);
  }

  for (let hb of hBars) {
    for (let i = 0; i < 48; i++) {
      let px = random(20, 1180);
      let py = hb.y + random(-hb.h * 0.42, hb.h * 0.42);
      let isRust = random() < 0.3;
      let col = isRust
        ? random(["#593d29", "#704e36", "#452f20"])
        : random(["#314f45", "#42695c", "#568273", "#709c8c"]);
      brush.set("charcoal", col, random(0.6, 1.4));
      brush.line(px - random(10, 32), py, px + random(10, 32), py + random(-2, 2));
    }

    // Pooled condensation water glistening along the top ledge of horizontal transoms
    for (let k = 0; k < 42; k++) {
      let wx = random(35, 1165);
      let wy = hb.y - hb.h * 0.48;
      brush.set("micro", "#e8efe4", random(0.8, 1.35));
      brush.line(wx, wy, wx + random(8, 26), wy);
    }
  }

  // Rivet/bolt heads on the 4 intersection gusset plates
  for (let pt of intersections) {
    const offsets = [[-18, -18], [18, -18], [-18, 18], [18, 18]];
    for (let o of offsets) {
      let bx = pt[0] + o[0];
      let by = pt[1] + o[1];
      brush.set("micro", "#0e1513", 1.1);
      brush.circle(bx, by, 4.5, 0.1);
      brush.set("micro", "#88ab9d", 0.9);
      brush.arc(bx, by, 4.2, 200, 330);
    }
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // Layer 1: Humid milky light & wet-in-wet blurred palms and ferns
  drawFoggedGlasshouseBackground();

  // Layer 2: Deep interior glasshouse space inside the hand-wiped streak
  drawWipedInteriorBackdrop();

  // Layer 3: Sharp hyperreal gardener's face (pores, damp curl of hair, steamed spectacles)
  drawGardenerPortrait();

  // Layer 4: Hand-wiped streak smears, micro-condensation & hyperreal refracted water drips
  drawGlassSurfaceAndDrips();

  // Layer 5: Dark verdigris cast-iron mullion grid cutting the view into tall rectangles
  drawCastIronMullions();

  noLoop();
}

// Hyperrealist Graphite & Faint Wash Study:
// Nested Shopping Trolleys in an Overcast Car Park

const W = 1200;
const H = 1200;

// Perspective projection parameters (long telephoto side-on view)
const VX = 600;
const VY = 340;
const KX = 0.058;
const KY = 0.044;

function proj(x, y, z) {
  return [
    x + (VX - x) * z * KX + 15 * z,
    y + (VY - y) * z * KY - 9 * z
  ];
}

function resetBrushState() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

async function setup() {
  createCanvas(W, H, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4092);
  noiseSeed(4092);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Base cool-warm overcast paper ground
  background("#dad8d1");

  // 1. Overcast sky & banal car park background
  drawOvercastSkyAndBackground();

  // 2. Damp, dull tarmac foreground & subtle reflections
  drawDampTarmacForeground();

  // 3. Far-side corral barrier structure (behind trolleys)
  drawCorralStructure(1.18, true);

  // 4. Generate exact mechanical layout for nested trolleys
  const trolleys = buildTrolleyArray();

  // 5. Atmospheric graphite density across overlapping wire basket zone
  drawBasketDensityWash(trolleys);

  // 6. Trolleys Pass 1: Far-side wheels, chassis & wire lattice (z = 1.0)
  for (let i = 0; i < trolleys.length; i++) {
    drawTrolleyFarSide(trolleys[i]);
  }

  // 7. Trolleys Pass 2: Transverse floor mesh, front noses & lifted rear gates
  for (let i = 0; i < trolleys.length; i++) {
    drawTrolleyInterior(trolleys[i], i === 0);
  }

  // 8. Trolleys Pass 3: Faded red plastic washes on handles + handle graphite detail
  for (let i = 0; i < trolleys.length; i++) {
    drawTrolleyHandle(trolleys[i]);
  }

  // 9. Trolleys Pass 4: Near-side wheels, tubular chassis, wire lattice, welds & stickers (z = 0.0)
  for (let i = 0; i < trolleys.length; i++) {
    drawTrolleyNearSide(trolleys[i]);
  }

  // 10. Foreground corral barrier rails, welds, scuffs & sticker residue
  drawCorralStructure(-0.14, false);

  // 11. Final surface unification: micro-scratches, graphite dust & damp grit
  drawFinalSurfaceDetails();

  noLoop();
}

