// ============================================================================
// 3. TROLLEY ARRAY & GEOMETRY DEFINITION
// ============================================================================
function buildTrolleyArray() {
  const list = [];
  // 17 nested trolleys from left to right (pitch = 51px)
  // Basket length ~378px -> ~7 baskets overlap at any cross-section
  const stepX = 51;
  const startIdx = -3;
  const endIdx = 14;

  const redPalette = [
    "#9e463e", "#8f3f38", "#a84f46", "#94423b", "#873b34", "#ad554c"
  ];

  for (let idx = startIdx; idx <= endIdx; idx++) {
    let ox = 72 + idx * stepX + random(-1.2, 1.2);
    let oy = 982 + random(-1.8, 1.8) + sin(idx * 0.7) * 1.5;

    list.push({
      idx: idx,
      ox: ox,
      oy: oy,
      handleRed: random(redPalette),
      rearSwivel: random(-38, 42),
      frontSwivel: random(-48, 52),
      rearFarSwivel: random(-40, 40),
      frontFarSwivel: random(-45, 45),
      hasHandleSticker: random() < 0.45,
      hasFrameSticker: random() < 0.55,
      gateLiftJitter: random(-3, 4),
      scuffSeed: floor(random(1000, 9999))
    });
  }
  return list;
}

// Helper to compute key points on Trolley `t` in local (X, Y) coordinates
function getTrolleyGeom(t) {
  const ox = t.ox;
  const oy = t.oy;

  return {
    // Handle center
    hx: ox - 22,
    hy: oy - 762,
    // Rear upright top (hinge area)
    rxTop: ox + 26,
    ryTop: oy - 728,
    // Basket 4 corners
    bTopRear: [ox + 26, oy - 726],
    bTopFront: [ox + 404, oy - 678],
    bBotFront: [ox + 382, oy - 384],
    bBotRear: [ox + 64, oy - 318],
    // Chassis & wheel points
    rearWheel: [ox + 42, oy - 44],
    frontWheel: [ox + 344, oy - 44],
    wheelR: 43,
    chassisRear: [ox + 46, oy - 88],
    chassisFrontLow: [ox + 392, oy - 104],
    chassisNoseTip: [ox + 408, oy - 122],
    chassisFrontHigh: [ox + 394, oy - 142],
    chassisBasketJoin: [ox + 118, oy - 332]
  };
}

// ============================================================================
// 4. ATMOSPHERIC DENSITY WASH IN OVERLAPPING BASKET LATTICE
// ============================================================================
function drawBasketDensityWash(trolleys) {
  resetBrushState();
