  // Subtle cool graphite-slate tonal buildup where 6-7 wire layers overlap
  brush.fill("#7d8084", 55);
  brush.beginShape(0.05);
  brush.vertex(-10, 245);
  brush.vertex(1155, 290);
  brush.vertex(1135, 605);
  brush.vertex(-10, 665);
  brush.endShape(true);

  brush.fill("#6a6d72", 45);
  brush.beginShape(0.05);
  brush.vertex(-10, 295);
  brush.vertex(1090, 325);
  brush.vertex(1070, 575);
  brush.vertex(-10, 625);
  brush.endShape(true);

  resetBrushState();
}

// ============================================================================
// 5. TROLLEY PASS 1: FAR SIDE (z = 1.0)
// ============================================================================
function drawTrolleyFarSide(t) {
  resetBrushState();
  const g = getTrolleyGeom(t);
  const z = 1.0;

  // Far-side damp shadow on tarmac under wheels
  let [rwX, rwY] = proj(g.rearWheel[0], g.rearWheel[1] + g.wheelR, z);
  let [fwX, fwY] = proj(g.frontWheel[0], g.frontWheel[1] + g.wheelR, z);
  brush.set("2B", "#33322f", 0.35);
  brush.line(rwX - 18, rwY, rwX + 18, rwY);
  brush.line(fwX - 18, fwY, fwX + 18, fwY);

  // Far-side caster wheels
  drawCasterWheel(rwX, rwY - g.wheelR * 0.94, g.wheelR * 0.94, t.rearFarSwivel, true);
  drawCasterWheel(fwX, fwY - g.wheelR * 0.94, g.wheelR * 0.94, t.frontFarSwivel, true);

  // Far-side tubular chassis
  let pChRear = proj(g.chassisRear[0], g.chassisRear[1], z);
  let pChFLow = proj(g.chassisFrontLow[0], g.chassisFrontLow[1], z);
  let pChNose = proj(g.chassisNoseTip[0], g.chassisNoseTip[1], z);
  let pChFHigh = proj(g.chassisFrontHigh[0], g.chassisFrontHigh[1], z);
  let pChJoin = proj(g.chassisBasketJoin[0], g.chassisBasketJoin[1], z);
  let pTopRear = proj(g.rxTop, g.ryTop, z);
  let pBotRear = proj(g.bBotRear[0], g.bBotRear[1], z);
  let pHandle = proj(g.hx, g.hy, z);

  brush.set("2H", "#585b61", 0.48);
  brush.line(pChRear[0], pChRear[1], pChFLow[0], pChFLow[1]);
  brush.line(pChFLow[0], pChFLow[1], pChNose[0], pChNose[1]);
  brush.line(pChNose[0], pChNose[1], pChFHigh[0], pChFHigh[1]);
  brush.line(pChFHigh[0], pChFHigh[1], pChJoin[0], pChJoin[1]);
  brush.line(pChRear[0], pChRear[1], pBotRear[0], pBotRear[1]);
  brush.line(pBotRear[0], pBotRear[1], pTopRear[0], pTopRear[1]);
  brush.line(pTopRear[0], pTopRear[1], pHandle[0], pHandle[1]);

  // Far-side wire basket lattice
  let pTR = proj(g.bTopRear[0], g.bTopRear[1], z);
  let pTF = proj(g.bTopFront[0], g.bTopFront[1], z);
  let pBF = proj(g.bBotFront[0], g.bBotFront[1], z);
  let pBR = proj(g.bBotRear[0], g.bBotRear[1], z);

  // Far top & bottom rims
  brush.set("HB", "#5e6268", 0.36);
  brush.line(pTR[0], pTR[1], pTF[0], pTF[1]);
  brush.line(pBR[0], pBR[1], pBF[0], pBF[1]);
  brush.line(pTF[0], pTF[1], pBF[0], pBF[1]);

  // Far longitudinal wires (13 wires)
  const numLong = 13;
  for (let j = 1; j < numLong; j++) {
    let v = j / numLong;
    let sx = lerp(pTR[0], pBR[0], v);
    let sy = lerp(pTR[1], pBR[1], v);
    let ex = lerp(pTF[0], pBF[0], v);
    let ey = lerp(pTF[1], pBF[1], v);

    let isRib = (j === 4 || j === 9);
    brush.set("2H", isRib ? "#55595e" : "#70747a", isRib ? 0.28 : 0.18);
    brush.line(sx, sy, ex, ey);
  }

  // Far vertical cross-wires (16 wires)
  const numVert = 16;
  for (let k = 1; k < numVert; k++) {
    let u = k / numVert;
    let tx = lerp(pTR[0], pTF[0], u);
    let ty = lerp(pTR[1], pTF[1], u);
    let bx = lerp(pBR[0], pBF[0], u);
    let by = lerp(pBR[1], pBF[1], u);
    brush.set("2H", "#6d7178", 0.18);
    brush.line(tx, ty, bx, by);
  }
}

// ============================================================================
// 6. TROLLEY PASS 2: TRANSVERSE FLOOR, FRONT NOSE & LIFTED REAR GATE
// ============================================================================
function drawTrolleyInterior(t, isFirstVisible) {
  resetBrushState();
  const g = getTrolleyGeom(t);

  // Rear axle tube connecting near & far rear wheel brackets
  let pAx0 = proj(g.chassisRear[0], g.chassisRear[1], 0);
  let pAx1 = proj(g.chassisRear[0], g.chassisRear[1], 1);
  brush.set("HB", "#45484d", 0.45);
  brush.line(pAx0[0], pAx0[1], pAx1[0], pAx1[1]);

  // Lower chassis nose bar connecting near & far front bumper
  let pNs0 = proj(g.chassisNoseTip[0], g.chassisNoseTip[1], 0);
  let pNs1 = proj(g.chassisNoseTip[0], g.chassisNoseTip[1], 1);
  brush.set("HB", "#4b4e54", 0.42);
  brush.line(pNs0[0], pNs0[1], pNs1[0], pNs1[1]);

  // Transverse wires across the basket floor (z = 0 to z = 1)
  for (let k = 0; k <= 12; k++) {
    let u = k / 12;
    let fx = lerp(g.bBotRear[0], g.bBotFront[0], u);
    let fy = lerp(g.bBotRear[1], g.bBotFront[1], u);
    let p0 = proj(fx, fy, 0);
    let p1 = proj(fx, fy, 1);
    brush.set("2H", "#64686e", 0.2);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Transverse wires across the front nose wall of the basket
  for (let j = 0; j <= 10; j++) {
    let v = j / 10;
    let nx = lerp(g.bTopFront[0], g.bBotFront[0], v);
    let ny = lerp(g.bTopFront[1], g.bBotFront[1], v);
    let p0 = proj(nx, ny, 0);
    let p1 = proj(nx, ny, 1);
    brush.set("2H", "#5d6167", (j === 0 || j === 10) ? 0.35 : 0.2);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Hinged Rear Gate & Child Seat inside the basket
  // Because trolleys are nested, the trolley behind pushes the rear gate upwards at an angle
  let hingeX = g.bTopRear[0] + 6;
  let hingeY = g.bTopRear[1] + 8;

  let gateBotX, gateBotY;
  let seatBotX, seatBotY;

  if (isFirstVisible && t.ox > 0) {
    // Un-nested rear gate hanging nearly vertical
    gateBotX = g.bBotRear[0] + 4;
    gateBotY = g.bBotRear[1] - 6;
    seatBotX = hingeX + 58;
    seatBotY = hingeY + 215;
  } else {
    // Lifted inside the basket by the nested nose of the trolley behind it
    gateBotX = hingeX + 245;
    gateBotY = hingeY + 148 + t.gateLiftJitter;
    seatBotX = hingeX + 135;
    seatBotY = hingeY + 165 + t.gateLiftJitter;
  }

  // Draw gate wires across depth z = 0.08 to z = 0.92
  let pH0 = proj(hingeX, hingeY, 0.06);
  let pH1 = proj(hingeX, hingeY, 0.94);
  let pG0 = proj(gateBotX, gateBotY, 0.06);
  let pG1 = proj(gateBotX, gateBotY, 0.94);
  let pS0 = proj(seatBotX, seatBotY, 0.12);
  let pS1 = proj(seatBotX, seatBotY, 0.88);

  brush.set("HB", "#4f5359", 0.34);
  brush.line(pH0[0], pH0[1], pG0[0], pG0[1]);
  brush.line(pH1[0], pH1[1], pG1[0], pG1[1]);
  brush.line(pG0[0], pG0[1], pG1[0], pG1[1]);

  // Child seat fold-out frame inside gate
  brush.set("2H", "#5a5e63", 0.26);
  brush.line(pH0[0] + 8, pH0[1] + 24, pS0[0], pS0[1]);
  brush.line(pS0[0], pS0[1], pS1[0], pS1[1]);

  // Internal gate wire bars
  for (let m = 1; m <= 5; m++) {
    let mu = m / 6;
    let gx0 = lerp(pH0[0], pH1[0], mu);
    let gy0 = lerp(pH0[1], pH1[1], mu);
    let gx1 = lerp(pG0[0], pG1[0], mu);
    let gy1 = lerp(pG0[1], pG1[1], mu);
    brush.set("2H", "#676b70", 0.18);
    brush.line(gx0, gy0, gx1, gy1);
  }
}

// ============================================================================
// 7. TROLLEY PASS 3: FADED RED PLASTIC WASHES ON HANDLES
// ============================================================================
function drawTrolleyHandle(t) {
  resetBrushState();
  const g = getTrolleyGeom(t);

  // Handle spans from z = 1.0 (far) to z = 0.0 (near)
  let pFar = proj(g.hx, g.hy, 1.0);
  let pNear = proj(g.hx, g.hy, 0.0);
  let pMountFar = proj(g.rxTop, g.ryTop, 1.0);
  let pMountNear = proj(g.rxTop, g.ryTop, 0.0);

  // Far handle bracket arm
  brush.set("HB", "#585b61", 0.42);
  brush.line(pMountFar[0], pMountFar[1], pFar[0], pFar[1]);

  // Faded red watercolor wash on cylindrical plastic handle bar & end-cap
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.45, 0.3);

  // Main cylindrical handle tube wash
  brush.fill(t.handleRed, 115);
  brush.beginShape(0.1);
  brush.vertex(pFar[0] - 5, pFar[1] - 6);
  brush.vertex(pNear[0] - 5, pNear[1] - 7);
  brush.vertex(pNear[0] + 7, pNear[1] + 6);
  brush.vertex(pFar[0] + 5, pFar[1] + 5);
  brush.endShape(true);

  // Moulded plastic handle end-cap / horn grip on near side (slight faded red wash)
  brush.fill(t.handleRed, 135);
  brush.beginShape(0.12);
  brush.vertex(pNear[0] - 8, pNear[1] - 7);
  brush.vertex(pNear[0] + 16, pNear[1] + 4);
  brush.vertex(pNear[0] + 13, pNear[1] + 12);
  brush.vertex(pNear[0] - 9, pNear[1] + 6);
  brush.endShape(true);

  // Second subtle wash layer for sun-bleached blotchiness
  brush.fill("#b86b62", 65);
  brush.circle(lerp(pFar[0], pNear[0], 0.5), lerp(pFar[1], pNear[1], 0.5), 7, 0.2);

  resetBrushState();

  // Crisp graphite contour & shading on the plastic handle
  brush.set("HB", "#3b3534", 0.32);
  brush.line(pFar[0] - 5, pFar[1] - 6, pNear[0] - 5, pNear[1] - 7);
  brush.set("2B", "#262222", 0.36);
  brush.line(pFar[0] + 4, pFar[1] + 5, pNear[0] + 6, pNear[1] + 6);

  // Elliptical end cap profile at z = 0
  brush.set("HB", "#2e2a29", 0.34);
  brush.circle(pNear[0] - 2, pNear[1], 6.5, 0.15);
  brush.set("2H", "#6e4844", 0.22);
  brush.circle(pNear[0] - 2, pNear[1], 3.2, 0.1);

  // Sun-bleached scuffs & pale scratches on the red handle
  brush.set("cpencil", "#e3dfd8", 0.28);
  brush.line(pFar[0] - 2, pFar[1] - 4, pNear[0] - 2, pNear[1] - 5);
  brush.line(pNear[0] + 1, pNear[1] - 2, pNear[0] + 9, pNear[1] + 3);

  // Optional sticker residue wrapped on the handle tube
  if (t.hasHandleSticker && pNear[0] > 20 && pNear[0] < W - 20) {
    let sx = lerp(pFar[0], pNear[0], 0.45);
    let sy = lerp(pFar[1], pNear[1], 0.45);
    drawStickerResidue(sx, sy, 8, 6, -55);
  }
}

// ============================================================================
// 8. TROLLEY PASS 4: NEAR SIDE (z = 0.0) CHASSIS, WHEELS, LATTICE & WELDS
// ============================================================================
function drawTrolleyNearSide(t) {
  resetBrushState();
  const g = getTrolleyGeom(t);
  const z = 0.0;

  let [rwX, rwY] = proj(g.rearWheel[0], g.rearWheel[1], z);
  let [fwX, fwY] = proj(g.frontWheel[0], g.frontWheel[1], z);

  // Damp contact shadow & dark reflection directly beneath near wheels
  brush.noStroke();
  brush.fill("#21201e", 130);
  brush.rect(rwX, rwY + g.wheelR + 2, 38, 6, "center");
  brush.rect(fwX, fwY + g.wheelR + 2, 38, 6, "center");
  brush.fill("#33312e", 75);
  brush.rect(rwX, rwY + g.wheelR + 22, 28, 32, "center");
  brush.rect(fwX, fwY + g.wheelR + 22, 28, 32, "center");
  resetBrushState();

  // Near-side caster wheels
  drawCasterWheel(rwX, rwY, g.wheelR, t.rearSwivel, false);
  drawCasterWheel(fwX, fwY, g.wheelR, t.frontSwivel, false);

  // Near-side tubular steel chassis (rendered as 3D shaded metal tubes)
  let pChRear = proj(g.chassisRear[0], g.chassisRear[1], z);
  let pChFLow = proj(g.chassisFrontLow[0], g.chassisFrontLow[1], z);
  let pChNose = proj(g.chassisNoseTip[0], g.chassisNoseTip[1], z);
  let pChFHigh = proj(g.chassisFrontHigh[0], g.chassisFrontHigh[1], z);
  let pChJoin = proj(g.chassisBasketJoin[0], g.chassisBasketJoin[1], z);
  let pTopRear = proj(g.rxTop, g.ryTop, z);
  let pBotRear = proj(g.bBotRear[0], g.bBotRear[1], z);
  let pHandle = proj(g.hx, g.hy, z);

  // Draw shaded steel tubing segments
  drawShadedTube(pChRear[0], pChRear[1], pChFLow[0], pChFLow[1], 11);
  drawShadedTube(pChFLow[0], pChFLow[1], pChNose[0], pChNose[1], 10);
  drawShadedTube(pChNose[0], pChNose[1], pChFHigh[0], pChFHigh[1], 10);
  drawShadedTube(pChFHigh[0], pChFHigh[1], pChJoin[0], pChJoin[1], 10);
  drawShadedTube(pChRear[0], pChRear[1], pBotRear[0], pBotRear[1], 11);
  drawShadedTube(pBotRear[0], pBotRear[1], pTopRear[0], pTopRear[1], 10);
  drawShadedTube(pTopRear[0], pTopRear[1], pHandle[0] + 6, pHandle[1] + 5, 8);

  // Fillet welds & earth-toned oxidation at chassis joints
  drawWeldFillet(pChRear[0], pChRear[1], 6);
  drawWeldFillet(pBotRear[0], pBotRear[1], 6);
  drawWeldFillet(pChJoin[0], pChJoin[1], 6);
  drawWeldFillet(fwX, pChFLow[1] + 2, 6);

  // Scuffed grey plastic bumper cap on lower chassis nose
  brush.noStroke();
  brush.fill("#5c5a55", 160);
  brush.circle(pChNose[0] + 2, pChNose[1], 8, 0.2);
  resetBrushState();
  brush.set("2B", "#262523", 0.32);
  brush.arc(pChNose[0] + 2, pChNose[1], 8, -70, 95);
  brush.set("cpencil", "#d8d5ce", 0.25);
  brush.line(pChNose[0], pChNose[1] - 3, pChNose[0] + 6, pChNose[1] + 1);

  // Sticker residue on rear upright strut collar
  if (t.hasFrameSticker && pTopRear[0] > 15 && pTopRear[0] < W - 15) {
    let sx = lerp(pTopRear[0], pBotRear[0], 0.22);
    let sy = lerp(pTopRear[1], pBotRear[1], 0.22);
    drawStickerResidue(sx, sy, 10, 18, 6);
  }

  // --------------------------------------------------------------------------
  // NEAR-SIDE WIRE BASKET LATTICE
  // --------------------------------------------------------------------------
  let pTR = proj(g.bTopRear[0], g.bTopRear[1], z);
  let pTF = proj(g.bTopFront[0], g.bTopFront[1], z);
  let pBF = proj(g.bBotFront[0], g.bBotFront[1], z);
  let pBR = proj(g.bBotRear[0], g.bBotRear[1], z);

  // Precompute longitudinal wire endpoints (15 wires)
  const numLong = 15;
  const longWires = [];
  for (let j = 0; j <= numLong; j++) {
    let v = j / numLong;
    longWires.push({
      sx: lerp(pTR[0], pBR[0], v),
      sy: lerp(pTR[1], pBR[1], v),
      ex: lerp(pTF[0], pBF[0], v),
      ey: lerp(pTF[1], pBF[1], v),
      isRib: (j === 4 || j === 10),
      isRim: (j === 0 || j === numLong)
    });
  }

  // Draw vertical/fanned cross-wires first (18 wires)
  const numVert = 18;
  const vertUs = [];
  for (let k = 0; k <= numVert; k++) {
    let u = k / numVert;
    vertUs.push(u);
    let tx = lerp(pTR[0], pTF[0], u);
    let ty = lerp(pTR[1], pTF[1], u);
    let bx = lerp(pBR[0], pBF[0], u);
    let by = lerp(pBR[1], pBF[1], u);

    // Slight loop extension beneath the basket floor wire
    let extX = bx + (bx - tx) * 0.022;
    let extY = by + 6;

    // Bright edge highlight + dark graphite wire core
    brush.set("cpencil", "#e2e0d8", 0.2);
    brush.line(tx - 0.8, ty, bx - 0.8, by);

    brush.set("HB", (k === 0 || k === numVert) ? "#2b2d30" : "#3f4247", (k === 0 || k === numVert) ? 0.42 : 0.26);
    brush.line(tx, ty, extX, extY);
  }

  // Draw longitudinal wires & double-wire reinforcement channels
  for (let j = 0; j <= numLong; j++) {
    let lw = longWires[j];

    if (lw.isRim) {
      // Heavy rolled top/bottom rim wire
      brush.set("cpencil", "#e8e6de", 0.32);
      brush.line(lw.sx, lw.sy - 1.5, lw.ex, lw.ey - 1.5);
      brush.set("HB", "#4a4e54", 0.48);
      brush.line(lw.sx, lw.sy, lw.ex, lw.ey);
      brush.set("2B", "#1f2124", 0.35);
      brush.line(lw.sx, lw.sy + 1.8, lw.ex, lw.ey + 1.8);
    } else if (lw.isRib) {
      // Double-wire horizontal stiffening channel with spot-welded truss spacers
      brush.set("cpencil", "#e4e2da", 0.24);
      brush.line(lw.sx, lw.sy - 3.5, lw.ex, lw.ey - 3.5);
      brush.set("HB", "#313438", 0.34);
      brush.line(lw.sx, lw.sy - 2.5, lw.ex, lw.ey - 2.5);
      brush.line(lw.sx, lw.sy + 3.5, lw.ex, lw.ey + 3.5);

      // Short vertical/diagonal stiffener links inside the channel
      brush.set("2B", "#26282b", 0.24);
      for (let s = 0.04; s < 0.98; s += 0.055) {
        let cx1 = lerp(lw.sx, lw.ex, s);
        let cy1 = lerp(lw.sy, lw.ey, s) - 2.5;
        let cx2 = lerp(lw.sx, lw.ex, s + 0.02);
        let cy2 = lerp(lw.sy, lw.ey, s + 0.02) + 3.5;
        brush.line(cx1, cy1, cx2, cy2);
      }
    } else {
      // Standard longitudinal basket wire
      brush.set("cpencil", "#dfddd5", 0.18);
      brush.line(lw.sx, lw.sy - 0.8, lw.ex, lw.ey - 0.8);
      brush.set("HB", "#45494f", 0.25);
      brush.line(lw.sx, lw.sy, lw.ex, lw.ey);
    }

    // Spot-weld points at wire intersections along rims & reinforcement channels
    if (lw.isRim || lw.isRib) {
      for (let k = 0; k <= numVert; k++) {
        let u = vertUs[k];
        let wx = lerp(lw.sx, lw.ex, u);
        let wy = lerp(lw.sy, lw.ey, u);
        if (wx > -5 && wx < W + 5) {
          // Tiny dark resistance-weld node + occasional rust-earth oxidation speck
          brush.set("2B", (k % 4 === 0) ? "#3b2f28" : "#181a1c", 0.36);
          brush.line(wx - 1.2, wy - 1.2, wx + 1.2, wy + 1.2);
          if (lw.isRib) {
            brush.line(wx - 1.2, wy + 3.2, wx + 1.2, wy + 4.2);
          }
        }
      }
    }
  }

  // Moulded plastic/rubber corner bumper at top-front nose of basket
  brush.noStroke();
  brush.fill("#595752", 165);
  brush.rect(pTF[0], pTF[1] + 2, 11, 14, "center");
  resetBrushState();
  brush.set("2B", "#222325", 0.32);
  brush.rect(pTF[0], pTF[1] + 2, 11, 14, "center");
  brush.set("cpencil", "#dedcd4", 0.24);
  brush.line(pTF[0] - 4, pTF[1] - 4, pTF[0] + 4, pTF[1] + 4);
}

// ============================================================================
// 9. CASTER WHEEL RENDERER (EXACT MECHANICAL DETAIL)
// ============================================================================
function drawCasterWheel(cx, cy, r, swivelDeg, isFar) {
  if (cx < -60 || cx > W + 60) return;
  resetBrushState();

  // Foreshortening factor from caster swivel angle
  let cosA = max(0.38, abs(cos(swivelDeg)));
  let dir = swivelDeg >= 0 ? 1 : -1;
  let treadShift = dir * r * 0.22 * (1 - cosA + 0.25);

  let darkCol = isFar ? "#3d4045" : "#222326";
  let midCol = isFar ? "#5c6066" : "#43464b";
  let hubCol = isFar ? "#7c8085" : "#6c7075";

  // 1. Rubber tire fill
  brush.noStroke();
  brush.fill(isFar ? "#4a4c50" : "#2e3033", isFar ? 140 : 185);
  brush.circle(cx + treadShift * 0.5, cy, r * 0.92, 0.12);

  // Inner plastic wheel hub fill
  brush.fill(hubCol, isFar ? 120 : 165);
  brush.circle(cx, cy, r * 0.54, 0.1);
  resetBrushState();

  // 2. Tire tread thickness & side walls (offset circles to show 3D cylinder)
  brush.set(isFar ? "2H" : "2B", darkCol, isFar ? 0.32 : 0.44);
  brush.circle(cx + treadShift, cy, r * 0.95, 0.08);
  brush.circle(cx, cy, r * 0.95, 0.08);

  // Dusty tarmac grey road-contact ring on rubber tread
  brush.set("2H", "#8a867e", 0.24);
  brush.arc(cx + treadShift * 0.5, cy, r * 0.88, -60, 120);

  // 3. Moulded plastic rim & 5 recessed cavities around hub
  brush.set("HB", midCol, 0.3);
  brush.circle(cx, cy, r * 0.56, 0.08);
  if (!isFar) {
    for (let a = 0; a < 360; a += 72) {
      let hx = cx + cos(a + swivelDeg) * r * 0.34;
      let hy = cy + sin(a + swivelDeg) * r * 0.34;
      brush.set("2B", "#26282b", 0.26);
      brush.circle(hx, hy, 3.2, 0.1);
    }
  }

  // 4. Pressed-steel triangular caster fork straddling the wheel
  let forkTopX = cx - dir * 10;
  let forkTopY = cy - r - 5;

  if (!isFar) {
    brush.noStroke();
    brush.fill("#8c9096", 150);
    brush.beginShape(0.05);
    brush.vertex(forkTopX - 11, forkTopY);
    brush.vertex(forkTopX + 11, forkTopY);
    brush.vertex(cx + 7, cy + 4);
    brush.vertex(cx - 7, cy + 4);
    brush.endShape(true);
    resetBrushState();
  }

  // Fork edges, stamped depression & highlight
  brush.set(isFar ? "2H" : "HB", darkCol, isFar ? 0.28 : 0.36);
  brush.line(forkTopX - 11, forkTopY, cx - 7, cy + 3);
  brush.line(forkTopX + 11, forkTopY, cx + 7, cy + 3);
  brush.line(cx - 7, cy + 3, cx + 7, cy + 3);

  if (!isFar) {
    brush.set("cpencil", "#e4e2da", 0.28);
    brush.line(forkTopX - 8, forkTopY + 2, cx - 4, cy);
    // Stamped stiffening flute inside caster fork
    brush.set("2B", "#2d3034", 0.25);
    brush.line(forkTopX, forkTopY + 5, cx, cy - 5);
  }

  // 5. Swivel ball-bearing race collar at top of fork
  brush.set(isFar ? "2H" : "2B", darkCol, 0.38);
  brush.line(forkTopX - 14, forkTopY, forkTopX + 14, forkTopY);
  brush.line(forkTopX - 13, forkTopY - 4, forkTopX + 13, forkTopY - 4);
  if (!isFar) {
    brush.set("cpencil", "#e8e6de", 0.28);
    brush.line(forkTopX - 10, forkTopY - 2, forkTopX + 8, forkTopY - 2);
  }

  // 6. Central hex axle bolt & washer
  brush.set("2B", "#191a1c", 0.38);
  brush.circle(cx, cy, 4.5, 0.1);
  if (!isFar) {
    brush.set("cpencil", "#eceae2", 0.26);
    brush.circle(cx - 1, cy - 1, 2.0, 0.1);
  }
}

// ============================================================================
// 10. SHADED TUBULAR STEEL, WELDS & STICKER RESIDUE HELPERS
// ============================================================================
function drawShadedTube(x1, y1, x2, y2, diam) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  if (len < 1) return;

  let nx = -dy / len;
  let ny = dx / len;
  // Ensure normal points upwards/leftwards toward overcast sky
  if (ny > 0) {
    nx = -nx;
    ny = -ny;
  }

  let r = diam * 0.5;

  // Base galvanized grey wash inside tube
  brush.noStroke();
  brush.fill("#8c9096", 135);
  brush.beginShape(0);
  brush.vertex(x1 + nx * r, y1 + ny * r);
  brush.vertex(x2 + nx * r, y2 + ny * r);
  brush.vertex(x2 - nx * r, y2 - ny * r);
  brush.vertex(x1 - nx * r, y1 - ny * r);
  brush.endShape(true);
  resetBrushState();

  // Top edge contour
  brush.set("HB", "#3a3d42", 0.32);
  brush.line(x1 + nx * r, y1 + ny * r, x2 + nx * r, y2 + ny * r);

  // Specular sky reflection strip along upper third
  brush.set("cpencil", "#e6e4dc", 0.34);
  brush.line(x1 + nx * (r * 0.48), y1 + ny * (r * 0.48), x2 + nx * (r * 0.48), y2 + ny * (r * 0.48));

  // Mid-tone graphite grain
  brush.set("2H", "#63676d", 0.26);
  brush.line(x1, y1, x2, y2);

  // Core shadow & bottom contour
  brush.set("2B", "#242629", 0.38);
  brush.line(x1 - nx * (r * 0.65), y1 - ny * (r * 0.65), x2 - nx * (r * 0.65), y2 - ny * (r * 0.65));
  brush.set("HB", "#35383d", 0.32);
  brush.line(x1 - nx * r, y1 - ny * r, x2 - nx * r, y2 - ny * r);
}

function drawWeldFillet(x, y, rad) {
  if (x < -20 || x > W + 20) return;
  resetBrushState();
  // Earth-toned weld oxidation halo
  brush.noStroke();
  brush.fill("#665346", 85);
  brush.circle(x, y, rad * 1.4, 0.25);
  resetBrushState();

  // Stacked weld bead crescents
  brush.set("2B", "#242220", 0.34);
  for (let i = -2; i <= 2; i++) {
    brush.arc(x + i * 1.6, y + i * 0.8, rad * 0.7, 20, 190);
  }
  brush.set("cpencil", "#dfddd5", 0.22);
  brush.arc(x - 1, y - 1, rad * 0.6, 200, 330);
}

function drawStickerResidue(x, y, w, h, angleDeg) {
  if (x < -20 || x > W + 20) return;
  resetBrushState();
  push();
  translate(x, y);
  rotate(angleDeg);

  // 1. Dark sticky adhesive dust border (original rectangle footprint)
  brush.noStroke();
  brush.fill("#3b3833", 115);
  brush.rect(0, 0, w + 3, h + 3, "center");

  // 2. Ragged torn paper remnant (missing a corner)
  brush.fill("#dfd9cb", 195);
  brush.beginShape(0.08);
  brush.vertex(-w * 0.48, -h * 0.46);
  brush.vertex(w * 0.45, -h * 0.42);
  brush.vertex(w * 0.48, h * 0.12);
  brush.vertex(w * 0.08, h * 0.46);
  brush.vertex(-w * 0.46, h * 0.42);
  brush.endShape(true);
  resetBrushState();

  // 3. Torn paper edge & diagonal fingernail scrape marks
  brush.set("HB", "#524e47", 0.24);
  brush.line(-w * 0.46, -h * 0.44, w * 0.44, -h * 0.4);
  brush.line(w * 0.46, h * 0.1, w * 0.06, h * 0.44);
  brush.line(-w * 0.35, -h * 0.15, w * 0.25, h * 0.2);

  // 4. Faint barcode ticks or faded red-brown price stripe on the paper remnant
  brush.set("2B", "#2e2c29", 0.2);
  for (let bx = -w * 0.32; bx < w * 0.28; bx += 2.4) {
    brush.line(bx, -h * 0.25, bx, h * 0.08);
  }
  pop();
}

// ============================================================================
// 11. CORRAL BARRIER STRUCTURE (FAR & NEAR GALVANIZED RAILS)
// ============================================================================
function drawCorralStructure(zVal, isFar) {
  resetBrushState();

  const postXs = [64, 595, 1148];
  const topRailY = 512;
  const botRailY = 736;
  const postTopY = 468;
  const postBotY = 986;
  const tubeDiam = isFar ? 14 : 19;

  // 1. Horizontal galvanized barrier rails spanning across the corral
  let pTopL = proj(-20, topRailY, zVal);
  let pTopR = proj(1152, topRailY, zVal);
  let pBotL = proj(-20, botRailY, zVal);
  let pBotR = proj(1152, botRailY, zVal);

  if (isFar) {
    brush.set("2H", "#63676d", 0.55);
    brush.line(pTopL[0], pTopL[1], pTopR[0], pTopR[1]);
    brush.line(pBotL[0], pBotL[1], pBotR[0], pBotR[1]);
  } else {
    drawShadedTube(pTopL[0], pTopL[1], pTopR[0], pTopR[1], tubeDiam);
    drawShadedTube(pBotL[0], pBotL[1], pBotR[0], pBotR[1], tubeDiam);

    // Heavy rubber scuffs, trolley impact scratches & sticker residue on foreground rails
    for (let sx = 40; sx < 1120; sx += random(28, 55)) {
      let ry1 = lerp(pTopL[1], pTopR[1], sx / 1152);
      let ry2 = lerp(pBotL[1], pBotR[1], sx / 1152);

      // Dark rubber bumper transfer marks along lower rail
      brush.set("2B", "#1e1f21", random(0.28, 0.45));
      brush.line(sx, ry2 - 4, sx + random(14, 38), ry2 + 5);

      // Bright metal scrape marks along upper rail
      brush.set("cpencil", "#eceae2", 0.28);
      brush.line(sx, ry1 - 2, sx + random(10, 26), ry1 + 3);
    }

    // Exact sticker residue patches on the foreground corral rails
    drawStickerResidue(215, lerp(pTopL[1], pTopR[1], 215 / 1152), 26, 13, 2);
    drawStickerResidue(448, lerp(pTopL[1], pTopR[1], 448 / 1152) + 1, 19, 14, -4);
    drawStickerResidue(782, lerp(pTopL[1], pTopR[1], 782 / 1152), 32, 12, 1);
    drawStickerResidue(960, lerp(pBotL[1], pBotR[1], 960 / 1152), 24, 13, -2);
    drawStickerResidue(330, lerp(pBotL[1], pBotR[1], 330 / 1152), 22, 12, 3);
  }

  // 2. Vertical corral support posts & bolted tarmac base-plates
  for (let px of postXs) {
    let pTop = proj(px, postTopY, zVal);
    let pBot = proj(px, postBotY, zVal);
    let pJoin1 = proj(px, topRailY, zVal);
    let pJoin2 = proj(px, botRailY, zVal);

    if (isFar) {
      brush.set("2H", "#5d6167", 0.55);
      brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
    } else {
      // Wet silt & rust-earth stain ring on tarmac around base plate
      brush.noStroke();
      brush.fill("#3a352f", 125);
      brush.rect(pBot[0], pBot[1] + 3, 56, 14, "center");
      brush.fill("#6e6a63", 180);
      brush.rect(pBot[0], pBot[1], 44, 10, "center");
      resetBrushState();

      // Base plate outline & 4 hex anchor bolts
      brush.set("2B", "#202124", 0.36);
      brush.rect(pBot[0], pBot[1], 44, 10, "center");
      for (let bx of [-15, -6, 6, 15]) {
        brush.set("2B", "#18191b", 0.38);
        brush.circle(pBot[0] + bx, pBot[1] - 2, 3.2, 0.1);
        brush.set("cpencil", "#e4e2da", 0.24);
        brush.point ? null : brush.line(pBot[0] + bx - 1, pBot[1] - 3, pBot[0] + bx + 1, pBot[1] - 3);
      }

      // Vertical galvanized post tube
      drawShadedTube(pTop[0], pTop[1], pBot[0], pBot[1], tubeDiam + 2);

      // Domed steel cap on top of post
      brush.set("HB", "#35383d", 0.36);
      brush.arc(pTop[0], pTop[1], (tubeDiam + 2) * 0.5, 180, 360);
      brush.set("cpencil", "#e8e6de", 0.3);
      brush.arc(pTop[0], pTop[1] + 1, (tubeDiam - 2) * 0.5, 200, 340);

      // Welded saddle joints where horizontal rails meet the vertical post
      drawWeldFillet(pJoin1[0] - 9, pJoin1[1], 8);
      drawWeldFillet(pJoin1[0] + 9, pJoin1[1], 8);
      drawWeldFillet(pJoin2[0] - 9, pJoin2[1], 8);
      drawWeldFillet(pJoin2[0] + 9, pJoin2[1], 8);

      // Rust-earth water drip stain below weld joints
      brush.set("2H", "#6b5748", 0.26);
      brush.line(pJoin1[0] - 4, pJoin1[1] + 9, pJoin1[0] - 4, pJoin1[1] + 42);
      brush.line(pJoin2[0] + 3, pJoin2[1] + 9, pJoin2[0] + 3, pJoin2[1] + 55);

      // Half-peeled maintenance/barcode sticker on central post
      if (px === 595) {
        drawStickerResidue(pJoin1[0], pJoin1[1] + 68, 15, 28, 88);
      }
    }
  }
}

