// False-Colour Infrared Municipal Tennis Court — Hyperreal p5.brush Painting

const CAM = {
  cx: 600,
  cy: 758,
  focal: 1100,
  camY: 2.15,
  x0: 0.35,
  z0: 20.8,
  cosA: Math.cos(11 * Math.PI / 180),
  sinA: Math.sin(11 * Math.PI / 180)
};

// Transform court-space (u: length, h: height, v: width) to world (X, Y, Z)
function toWorld(u, h, v) {
  return {
    x: CAM.x0 + v * CAM.cosA - u * CAM.sinA,
    y: h,
    z: CAM.z0 + v * CAM.sinA + u * CAM.cosA
  };
}

// Project court-space (u, h, v) to 2D canvas coordinates [sx, sy]
function proj(u, h, v) {
  const w = toWorld(u, h, v);
  const z = Math.max(0.4, w.z);
  return [
    CAM.cx + (w.x / z) * CAM.focal,
    CAM.cy - ((w.y - CAM.camY) / z) * CAM.focal,
    z
  ];
}

// Interpolate along a 3D segment and project
function projLineSubdiv(u1, h1, v1, u2, h2, v2, steps = 1) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    pts.push(proj(
      u1 + (u2 - u1) * t,
      h1 + (h2 - h1) * t,
      v1 + (v2 - v1) * t
    ));
  }
  return pts;
}

// Draw a closed shape from 2D points using beginShape/vertex
function drawPoly2D(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Draw a 3D quad projected to 2D
function drawQuad3D(u1, h1, v1, u2, h2, v2, u3, h3, v3, u4, h4, v4, curvature = 0) {
  const p1 = proj(u1, h1, v1);
  const p2 = proj(u2, h2, v2);
  const p3 = proj(u3, h3, v3);
  const p4 = proj(u4, h4, v4);
  drawPoly2D([p1, p2, p3, p4], curvature);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
