}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm infrared cotton-rag paper ground
  background("#f6e7dc");

  // 1. Dense Indigo-Violet Sky Washes & Grain
  renderSky();

  // 2. Distant Horizon Parkland & Infrared Under-Foliage
  renderHorizonParkland();

  // 3. Surrounding Elms in Snow-White & Faint Coral-Pink (Built Leaf by Leaf)
  renderInfraredElms();

  // 4. Municipal Tennis Court Surface (Dusty Magenta Washes, Grain, Shadows, Cracks)
  renderCourtSurface();

  // 5. Crisp Painted Court Lines (Perspective Quads + Shadow Modulation)
  renderCourtLines();

  // 6. Back & Right Chain-Link Fence (Posts, Rails, Every Mesh Diamond in Hard Graphite)
  renderChainLinkFenceBackAndRight();

  // 7. Overhanging Elm Foliage Clusters Spilling Over Far Fence
  renderOverhangingFoliage();

  // 8. Sagging Municipal Net & Weathered Posts
  renderSaggingNet();

  // 9. Foreground Left Chain-Link Fence (Close-up Mesh Diamonds & Selvage Twists)
  renderChainLinkFenceLeft();

  // 10. Single Forgotten Pale-Lemon Tennis Ball & Fallen Infrared Leaves
  renderForgottenBallAndDetails();

  // 11. Final Wash Grain & Uncanny Stillness Atmospheric Unification
  renderFinalGrain();

  noLoop();
}

