  for (const b of baseBands) {
    brush.wash(b.col, b.op);
    brush.rect(-20, b.y, 1240, b.h, "corner");
  }
  brush.noWash();

  // Textured watercolour washes batched by colour for organic bleed & granulation
  const washBatches = [
    {
      col: "#090613", op: 155, bleed: 0.28, tex: 0.85, border: 0.55,
      rects: [
        [-30, -30, 1260, 220],
        [-30, 90, 750, 190],
        [420, 60, 810, 210]
      ]
    },
    {
      col: "#160e29", op: 140, bleed: 0.32, tex: 0.82, border: 0.5,
      rects: [
        [-30, 170, 1260, 230],
        [120, 280, 980, 180],
        [-20, 320, 620, 170]
      ]
    },
    {
      col: "#26163c", op: 125, bleed: 0.35, tex: 0.78, border: 0.48,
      rects: [
        [-30, 390, 1260, 200],
        [240, 470, 980, 160]
      ]
    },
    {
      col: "#3d204b", op: 115, bleed: 0.32, tex: 0.75, border: 0.45,
      rects: [
        [-30, 540, 1260, 175],
        [-20, 620, 1240, 145]
      ]
    },
    {
      col: "#5e2e56", op: 95, bleed: 0.28, tex: 0.7, border: 0.4,
      rects: [
        [-20, 680, 1240, 90]
      ]
    }
  ];

  for (const batch of washBatches) {
    brush.fill(batch.col, batch.op);
    brush.fillBleed(batch.bleed, "out");
