  }
  brush.noFill();

  // Subtle horizontal watercolour paper grain & pigment settling in the dark sky
  brush.hatchStyle("2B", "#080511", 0.65);
  brush.hatch(7, 1, { rand: 0.12, gradient: 0.35 });
  brush.rect(0, 0, 1200, 520, "corner");
  brush.noHatch();

  // Fine infrared granulation across the indigo sky
  const skyGrainColors = ["#2a1940", "#432654", "#07040e", "#633663", "#8c4f70"];
  for (let c = 0; c < skyGrainColors.length; c++) {
    brush.set("infrared_grain", skyGrainColors[c], 1.1);
    const count = c < 3 ? 55 : 28;
    for (let i = 0; i < count; i++) {
      const y = pow(random(), 1.15) * 740;
      const x = random(20, 1180);
      const len = random(45, 160);
      brush.line(x, y, x + len, y + random(-6, 6));
    }
  }
}

