  }

  // Helper to build organic scalloped foliage polygon
  function makeFoliagePoly(cx, cy, rx, ry, ptsCount, seedOff) {
    const pts = [];
    for (let i = 0; i < ptsCount; i++) {
      const ang = (i / ptsCount) * 360;
      const n = noise(cx * 0.01 + cos(ang) * 0.8 + seedOff, cy * 0.01 + sin(ang) * 0.8);
      const rMod = 0.68 + n * 0.52;
      pts.push([
        cx + cos(ang) * rx * rMod,
        cy + sin(ang) * ry * rMod
      ]);
    }
    return pts;
  }

