        // Drooping peripheral elm leaf gesture
        const droopAngle = ang > 90 && ang < 270 ? random(110, 165) : random(15, 75);
        const strokeLen = random(6, 17);
        brush.line(
          lx,
          ly,
          lx + cos(droopAngle) * strokeLen,
          ly + sin(droopAngle) * strokeLen
