        brush.line(lx, ly, lx + cos(twigAng) * twigLen, ly + sin(twigAng) * twigLen);
      }
    }
  }

  // Lower shrubberies and infrared saplings along the park fence line (y = 660..810)
  const bushColors = ["#8f3e57", "#d9827f", "#f7bfb6", "#fff8f2"];
  for (let b = 0; b < bushColors.length; b++) {
    brush.set("gouache_stipple", bushColors[b], 0.68 - b * 0.08);
    for (let x = 15; x < 1185; x += 9) {
      const baseH = 742 - noise(x * 0.015, b) * 65 - b * 6;
      const lx = x + random(-6, 6);
      const ly = baseH + random(-14, 18);
      brush.line(lx, ly, lx + random(-8, 8), ly + random(-6, 8));
    }
  }
}

// Helper: Draw a single mature American Elm trunk, primary vase limbs, and exposed twigs
function drawElmSkeleton(tree) {
  const bx = tree.baseX;
  const by = tree.baseY;
  const forkY = by - tree.height * 0.34;
  const forkX = bx + tree.lean * 1.4;

  // Main trunk polygon in deep warm aubergine-black
  brush.noStroke();
  brush.wash("#1c0f1f", 240);
  const tw = tree.trunkW * 0.5;
  drawPoly2D([
    [bx - tw * 1.35, by],
    [bx + tw * 1.35, by],
    [forkX + tw * 0.9, forkY],
    [forkX - tw * 0.9, forkY]
  ], 0.1);
  brush.noWash();

  // Bark fissure texture on trunk
  brush.set("charcoal", "#120816", 0.95);
  for (let i = -3; i <= 3; i++) {
    const t = i / 3.5;
    brush.spline([
      [bx + t * tw * 1.2, by, 1.1],
      [bx + tree.lean * 0.6 + t * tw, (by + forkY) * 0.5, 0.9],
      [forkX + t * tw * 0.85, forkY, 0.8]
    ], 0.35);
  }

  // Warm infrared rim-light on right side of trunk
  brush.set("cpencil", "#d98a88", 0.65);
  brush.spline([
    [bx + tw * 1.15, by - 10, 0.9],
    [bx + tree.lean * 0.6 + tw * 0.9, (by + forkY) * 0.5, 0.8],
    [forkX + tw * 0.8, forkY, 0.6]
  ], 0.35);

  // Vase-like primary limbs radiating into each crown cluster
  for (let i = 0; i < tree.clusters.length; i++) {
    const c = tree.clusters[i];
    const midX = lerp(forkX, c.cx, 0.48) + random(-22, 22);
    const midY = lerp(forkY, c.cy, 0.55) - random(10, 32);

    brush.set("charcoal", "#1f1124", 1.15);
    brush.spline([
      [forkX + random(-6, 6), forkY, 1.3],
      [midX, midY, 0.9],
      [c.cx, c.cy + 15, 0.45]
    ], 0.45);

    // Sunlit coral-ivory bark edge on upper limb
    brush.set("cpencil", "#f2b6ad", 0.48);
    brush.spline([
      [forkX + 3, forkY - 2, 0.8],
      [midX + 3, midY - 2, 0.6],
      [c.cx + 2, c.cy + 13, 0.3]
    ], 0.45);

    // Secondary & tertiary winter-fine twigs peeking through the canopy
    for (let k = 0; k < 7; k++) {
      const ang = random(-160, 20);
      const len1 = random(28, 68);
      const tx1 = c.cx + cos(ang) * len1 * 0.5;
      const ty1 = c.cy + sin(ang) * len1 * 0.5;
      const tx2 = c.cx + cos(ang + random(-25, 25)) * len1 * 1.15;
      const ty2 = c.cy + sin(ang + random(-25, 25)) * len1 * 1.15;

      brush.set("rotring", "#2b162e", 0.55);
      brush.spline([
        [c.cx, c.cy + 10, 0.8],
        [tx1, ty1, 0.5],
        [tx2, ty2, 0.25]
      ], 0.4);
    }
  }
}

// =============================================================================
// 4. COURT SURFACE: STRANGE DUSTY MAGENTA, WASH GRAIN, SHADOWS, & CRACKS
// =============================================================================
function renderCourtSurface() {
  brush.noStroke();

  // 4A. Outer municipal court apron (u: -18..+16.2, v: -11..+11) in dusty mauve-magenta
  brush.wash("#8f3f5d", 242);
  drawQuad3D(-18.5, 0, -12.5,  16.2, 0, -12.5,  16.2, 0, 12.5,  -18.5, 0, 12.5);
  brush.noWash();

  // Watercolour wash patches across outer apron for infrared tonal variation & grain
  const apronPatches = [
    { u1: -17.5, v1: -10.5, u2: 2.0,  v2: -10.5, u3: 2.0,  v3: 10.5, u4: -17.5, v4: 10.5, col: "#9e4b68", op: 115 },
    { u1: -2.0,  v1: -10.5, u2: 16.0, v2: -10.5, u3: 16.0, v3: 10.5, u4: -2.0,  v4: 10.5, col: "#7d314f", op: 120 },
    { u1: -16.0, v1: -9.5,  u2: 14.0, v2: -9.5,  u3: 14.0, v3: -3.5, u4: -16.0, v4: -3.5, col: "#b05c75", op: 95 },
    { u1: -15.0, v1: 2.5,   u2: 15.5, v2: 2.5,   u3: 15.5, v3: 9.8,  u4: -15.0, v4: 9.8,  col: "#6b2644", op: 105 }
  ];

  for (const p of apronPatches) {
    brush.fill(p.col, p.op);
    brush.fillBleed(0.28, "in");
    brush.fillTexture(0.82, 0.48);
    drawQuad3D(p.u1, 0, p.v1, p.u2, 0, p.v2, p.u3, 0, p.v3, p.u4, 0, p.v4);
  }
  brush.noFill();

  // 4B. Inner Playing Court (u: -11.885..+11.885, v: -5.485..+5.485) in Strange Dusty Magenta
  brush.wash("#752949", 230);
  drawQuad3D(-11.885, 0, -5.485,  11.885, 0, -5.485,  11.885, 0, 5.485,  -11.885, 0, 5.485);
  brush.noWash();

  const innerWashes = [
    // Sunlit dusty coral-magenta center & service courts
    { u1: -11.885, v1: -5.485, u2: 0.0,    v2: -5.485, u3: 0.0,    v3: 5.485, u4: -11.885, v4: 5.485, col: "#8f385a", op: 125 },
    { u1: -6.40,   v1: -4.115, u2: 6.40,   v2: -4.115, u3: 6.40,   v3: 4.115, u4: -6.40,   v4: 4.115, col: "#a64b6b", op: 110 },
    // Slightly worn acrylic baseline zones (warm dusty rose-ochre wear where players stand)
    { u1: -13.2,   v1: -3.2,   u2: -9.8,   v2: -3.2,   u3: -9.8,   v3: 3.2,   u4: -13.2,   v4: 3.2,   col: "#bf6b7d", op: 95 },
    { u1: 9.8,     v1: -3.0,   u2: 13.0,   v2: -3.0,   u3: 13.0,   v3: 3.0,   u4: 9.8,     v4: 3.0,   col: "#b86276", op: 90 },
    // Deeper mulberry-magenta wash on far court
    { u1: 0.0,     v1: -5.485, u2: 11.885, v2: -5.485, u3: 11.885, v3: 5.485, u4: 0.0,     v4: 5.485, col: "#66203f", op: 105 }
  ];

  for (const w of innerWashes) {
    brush.fill(w.col, w.op);
    brush.fillBleed(0.26, "in");
    brush.fillTexture(0.84, 0.52);
    drawQuad3D(w.u1, 0, w.v1, w.u2, 0, w.v2, w.u3, 0, w.v3, w.u4, 0, w.v4);
  }
  brush.noFill();

  // 4C. Fine Court Surface Grain & Acrylic Brush-Coat Texture
  // Perspective-following surface scuff lines across the court
  for (let i = 0; i < 160; i++) {
    const u = random(-15.5, 15.5);
    const v = random(-9.2, 9.2);
    const lenV = random(0.6, 2.4);
    const p1 = proj(u, 0, v);
    const p2 = proj(u + random(-0.15, 0.15), 0, v + lenV);
    const isLight = random() < 0.45;
    brush.set("2H", isLight ? "#bd6c82" : "#541a35", random(0.32, 0.58));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Infrared wash grain over the court
  const courtGrains = ["#591c38", "#b55d75", "#d98996", "#3d1026"];
  for (let c = 0; c < courtGrains.length; c++) {
    brush.set("infrared_grain", courtGrains[c], 1.15);
    for (let i = 0; i < 42; i++) {
      const u = random(-15.0, 15.5);
      const v = random(-9.0, 9.0);
      const p1 = proj(u, 0, v);
      const p2 = proj(u, 0, v + random(1.2, 3.2));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // 4D. Cast Shadows on the Dusty Magenta Court (Sunlight from Upper-Left)
  // Shadow vector: per 1m of height h, shadow shifts by du = +0.32m, dv = +1.18m
  const sU = 0.32;
  const sV = 1.18;

  brush.noStroke();
  // Dappled elm canopy shadow along the left and far-left court apron
  brush.fill("#42132b", 130);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.75, 0.45);
  drawQuad3D(-16.0, 0, -9.5,  16.0, 0, -9.5,  16.0, 0, -5.2,  -16.0, 0, -4.6);

  // Sagging net shadow band across the middle of the court
  const netShadowPts = [];
  for (let v = -6.4; v <= 6.4; v += 0.8) {
    const hTop = 0.86 + 0.21 * Math.pow(v / 6.4, 2);
    netShadowPts.push(proj(hTop * sU, 0, v + hTop * sV));
  }
  for (let v = 6.4; v >= -6.4; v -= 0.8) {
    const hBot = 0.08;
    netShadowPts.push(proj(hBot * sU, 0, v + hBot * sV));
  }
  brush.fill("#3d1128", 145);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.68, 0.55);
  drawPoly2D(netShadowPts, 0.1);
  brush.noFill();

  // Sharp cast shadows of the left chain-link fence posts & top rail across the left apron
  brush.set("charcoal", "#360e23", 0.9);
  const topRailS1 = proj(-15.0 + 3.6 * sU, 0, -9.5 + 3.6 * sV);
  const topRailS2 = proj(16.0 + 3.6 * sU, 0, -9.5 + 3.6 * sV);
  brush.line(topRailS1[0], topRailS1[1], topRailS2[0], topRailS2[1]);

  const midRailS1 = proj(-15.0 + 1.8 * sU, 0, -9.5 + 1.8 * sV);
  const midRailS2 = proj(16.0 + 1.8 * sU, 0, -9.5 + 1.8 * sV);
  brush.set("charcoal", "#360e23", 0.65);
  brush.line(midRailS1[0], midRailS1[1], midRailS2[0], midRailS2[1]);

  for (let u = -12.8; u <= 16.0; u += 3.2) {
    const pb = proj(u, 0, -9.5);
    const pt = proj(u + 3.65 * sU, 0, -9.5 + 3.65 * sV);
    brush.set("charcoal", "#330c20", 0.85);
    brush.line(pb[0], pb[1], pt[0], pt[1]);
  }

  // Cast shadows of the two net posts
  for (const vPost of [-6.40, 6.40]) {
    const pb = proj(0, 0, vPost);
    const pt = proj(1.07 * sU, 0, vPost + 1.07 * sV);
    brush.set("charcoal", "#2e0a1d", 1.25);
    brush.line(pb[0], pb[1], pt[0], pt[1]);
  }

  // 4E. Weathered Municipal Asphalt Cracks & Tiny Infrared Weed Tufts
  const cracks = [
    [[-13.8, -4.8], [-12.6, -4.1], [-11.5, -3.7], [-10.4, -3.1], [-9.5, -2.9]],
    [[7.2, 4.2], [8.5, 4.7], [9.9, 5.4], [11.2, 6.1]],
    [[-5.2, -7.8], [-3.8, -7.2], [-2.1, -6.9], [-0.8, -6.4]]
  ];
  for (const cr of cracks) {
    const ptsDark = cr.map(p => [...proj(p[0], 0, p[1]), random(0.5, 1.0)]);
    const ptsLight = cr.map(p => {
      const pr = proj(p[0], 0, p[1]);
      return [pr[0] + 1.2, pr[1] + 0.8, random(0.4, 0.8)];
    });
    brush.set("rotring", "#2b091a", 0.62);
    brush.spline(ptsDark, 0.35);
    brush.set("2H", "#c97b8e", 0.42);
    brush.spline(ptsLight, 0.35);

    // Tiny white & coral-pink infrared weeds sprouting in outer apron cracks
    for (let i = 0; i < cr.length; i += 2) {
      const wp = proj(cr[i][0], 0, cr[i][1]);
      brush.set("gouache_stipple", "#fff8f0", 0.42);
      brush.line(wp[0], wp[1], wp[0] + random(-4, 4), wp[1] - random(3, 7));
      brush.set("cpencil", "#f29b94", 0.45);
      brush.line(wp[0] - 2, wp[1], wp[0] + 2, wp[1] - 4);
    }
  }

  // Concrete perimeter curb along the base of the left, back, and right fences
  brush.noStroke();
  brush.wash("#b88996", 200);
  drawQuad3D(-16.0, 0, -9.62,  16.0, 0, -9.62,  16.0, 0.08, -9.45,  -16.0, 0.08, -9.45);
  drawQuad3D(15.92, 0, -9.55,  15.92, 0, 9.55,  16.08, 0.08, 9.55,  16.08, 0.08, -9.55);
  drawQuad3D(-16.0, 0, 9.45,   16.0, 0, 9.45,   16.0, 0.08, 9.62,   -16.0, 0.08, 9.62);
  brush.noWash();
}

// =============================================================================
// 5. CRISP PAINTED COURT LINES (PERSPECTIVE QUADS WITH SHADOW MODULATION)
// =============================================================================
function renderCourtLines() {
  // Helper: Draw a painted court line segment of physical width w (meters)
  // Splits automatically if it crosses the shadow band or left fence shadow
  function paintCourtStrip(u1, v1, u2, v2, widthM = 0.055) {
    const segs = 12;
    for (let i = 0; i < segs; i++) {
      const t0 = i / segs;
      const t1 = (i + 1) / segs;
      const ua = lerp(u1, u2, t0);
      const va = lerp(v1, v2, t0);
      const ub = lerp(u1, u2, t1);
      const vb = lerp(v1, v2, t1);
      const uMid = (ua + ub) * 0.5;
      const vMid = (va + vb) * 0.5;

      // Determine if this segment lies in the net shadow or left fence shadow
      const inFenceShadow = vMid < -5.22;
      const inNetShadow = uMid > 0.02 && uMid < 0.36 && Math.abs(vMid) < 7.2;
      const isShadowed = inFenceShadow || inNetShadow;

      const fillCol = isShadowed ? "#b58296" : "#fdf2e6";
      const edgeCol = isShadowed ? "#8c586e" : "#fffdf9";

      // Perpendicular offset in (u, v) space
      const du = ub - ua;
      const dv = vb - va;
      const len = Math.max(0.0001, Math.hypot(du, dv));
      const nu = (-dv / len) * (widthM * 0.5);
      const nv = (du / len) * (widthM * 0.5);

      const p1 = proj(ua - nu, 0, va - nv);
      const p2 = proj(ub - nu, 0, vb - nv);
      const p3 = proj(ub + nu, 0, vb + nv);
      const p4 = proj(ua + nu, 0, va + nv);

      brush.noStroke();
      brush.wash(fillCol, 238);
      drawPoly2D([p1, p2, p3, p4], 0);
      brush.noWash();

      // Crisp hard-edged painted line boundary
      brush.set("2H", edgeCol, 0.42);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.line(p4[0], p4[1], p3[0], p3[1]);
    }
  }

  // Baselines (wider 0.09m regulation baseline)
  paintCourtStrip(-11.885, -5.485, -11.885, 5.485, 0.09);
  paintCourtStrip(11.885, -5.485, 11.885, 5.485, 0.09);

  // Doubles sidelines
  paintCourtStrip(-11.885, -5.485, 11.885, -5.485, 0.055);
  paintCourtStrip(-11.885, 5.485, 11.885, 5.485, 0.055);

  // Singles sidelines
  paintCourtStrip(-11.885, -4.115, 11.885, -4.115, 0.055);
  paintCourtStrip(-11.885, 4.115, 11.885, 4.115, 0.055);

  // Near and far service lines
  paintCourtStrip(-6.40, -4.115, -6.40, 4.115, 0.055);
  paintCourtStrip(6.40, -4.115, 6.40, 4.115, 0.055);

  // Center service line
  paintCourtStrip(-6.40, 0.0, 6.40, 0.0, 0.055);

  // Baseline center marks
  paintCourtStrip(-11.885, 0.0, -11.55, 0.0, 0.055);
  paintCourtStrip(11.885, 0.0, 11.55, 0.0, 0.055);
}

// =============================================================================
// 6 & 9. CHAIN-LINK FENCE: EVERY MESH DIAMOND DRAWN WITH HARD GRAPHITE PEN
// =============================================================================
function renderFenceWall(uStart, vStart, uEnd, vEnd, bayCount, hFence, meshStepM, isForeground = false) {
  const totalLen = Math.hypot(uEnd - uStart, vEnd - vStart);
  const dirU = (uEnd - uStart) / totalLen;
  const dirV = (vEnd - vStart) / totalLen;

  function fencePt(s, h) {
    return proj(uStart + dirU * s, h, vStart + dirV * s);
  }

  // 1. Draw the diamond chain-link mesh across each bay
  // Intersecting diagonal wire families:
  // Family A: h = (s - s0) * slope   (rising diagonals)
  // Family B: h = hFence - (s - s0) * slope (falling diagonals)
  const slope = 1.22; // diamond aspect ratio (taller than wide, authentic chain-link)
  const bayLen = totalLen / bayCount;

  for (let b = 0; b < bayCount; b++) {
    const sMin = b * bayLen;
    const sMax = (b + 1) * bayLen;

    // Leave a narrow open maintenance gate entrance on the far-left corner bay if desired
    const hBot = 0.06;
    const hTop = hFence;
    const H = hTop - hBot;

    // Family A (+slope) and Family B (-slope)
    const offsetStart = -H / slope;
    const offsetEnd = bayLen;

    for (let ds = offsetStart; ds <= offsetEnd; ds += meshStepM) {
      // --- Rising wire (Family A): h - hBot = (s - (sMin + ds)) * slope ---
      let sA1 = sMin + Math.max(0, ds);
      let hA1 = hBot + (sA1 - (sMin + ds)) * slope;
      let sA2 = sMin + Math.min(bayLen, ds + H / slope);
      let hA2 = hBot + (sA2 - (sMin + ds)) * slope;

      if (sA2 > sA1 + 0.01 && hA2 > hA1 + 0.01) {
        const p1 = fencePt(sA1, hA1);
        const p2 = fencePt(sA2, hA2);
        if ((p1[0] > -80 && p1[0] < 1280) || (p2[0] > -80 && p2[0] < 1280)) {
          // Alternate subtle light-catching silver-graphite vs dark hard graphite
          const isGlint = ((Math.round(ds / meshStepM) + b) % 3 === 0);
          const colA = isGlint ? "#d9c5d0" : "#302436";
          const wA = isForeground ? (isGlint ? 0.56 : 0.48) : (isGlint ? 0.44 : 0.38);
          brush.set("graphite_wire", colA, wA);
          brush.line(p1[0], p1[1], p2[0], p2[1]);
        }
      }

      // --- Falling wire (Family B): hTop - h = (s - (sMin + ds)) * slope ---
      let sB1 = sMin + Math.max(0, ds);
      let hB1 = hTop - (sB1 - (sMin + ds)) * slope;
      let sB2 = sMin + Math.min(bayLen, ds + H / slope);
      let hB2 = hTop - (sB2 - (sMin + ds)) * slope;

      if (sB2 > sB1 + 0.01 && hB1 > hB2 + 0.01) {
        const p1 = fencePt(sB1, hB1);
        const p2 = fencePt(sB2, hB2);
        if ((p1[0] > -80 && p1[0] < 1280) || (p2[0] > -80 && p2[0] < 1280)) {
          const isGlint = ((Math.round(ds / meshStepM) + b * 2) % 4 === 0);
          const colB = isGlint ? "#ebdce3" : "#241a29";
          const wB = isForeground ? (isGlint ? 0.52 : 0.46) : (isGlint ? 0.42 : 0.36);
          brush.set("2H", colB, wB);
          brush.line(p1[0], p1[1], p2[0], p2[1]);
        }
      }
    }

    // Twisted wire selvage barbs along the top of the mesh
    for (let s = sMin + meshStepM * 0.5; s < sMax; s += meshStepM) {
      const pBase = fencePt(s, hTop);
      const pTip1 = fencePt(s - 0.02, hTop + 0.055);
      const pTip2 = fencePt(s + 0.02, hTop + 0.055);
      if (pBase[0] > -40 && pBase[0] < 1240) {
        brush.set("rotring", "#dfd0d8", isForeground ? 0.45 : 0.34);
        brush.line(pBase[0], pBase[1], pTip1[0], pTip1[1]);
        brush.line(pBase[0], pBase[1], pTip2[0], pTip2[1]);
      }
    }
  }

  // 2. Horizontal Tubular Steel Rails (Top Rail, Middle Tension Rail, Bottom Tension Wire)
  const railHeights = [
    { h: hFence, w: isForeground ? 1.15 : 0.85, colDark: "#241929", colLight: "#e8d5de" },
    { h: hFence * 0.50, w: isForeground ? 0.92 : 0.68, colDark: "#2a1e30", colLight: "#d4bfc9" },
    { h: 0.07, w: isForeground ? 0.65 : 0.48, colDark: "#36253b", colLight: "#b89ca9" }
  ];

  for (const r of railHeights) {
    const pts = projLineSubdiv(uStart, r.h, vStart, uEnd, r.h, vEnd, bayCount * 2);
    for (let i = 0; i < pts.length - 1; i++) {
      brush.set("rotring", r.colDark, r.w);
      brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
      // Specular metallic highlight along top edge of rail pipe
      brush.set("2H", r.colLight, r.w * 0.55);
      brush.line(pts[i][0], pts[i][1] - 1.3, pts[i + 1][0], pts[i + 1][1] - 1.3);
    }
  }

  // 3. Vertical Galvanized Fence Posts, Post Caps, & Corner Diagonal Brace Struts
  for (let b = 0; b <= bayCount; b++) {
    const s = b * bayLen;
    const pBot = fencePt(s, 0.0);
    const pTop = fencePt(s, hFence + 0.08);
    if (pBot[0] < -100 || pBot[0] > 1300) continue;

    const isCorner = (b === 0 || b === bayCount);
    const wPost = (isForeground ? 1.35 : 0.98) * (isCorner ? 1.25 : 1.0);

    // Shadow side of post
    brush.set("rotring", "#1d1322", wPost);
    brush.line(pBot[0], pBot[1], pTop[0], pTop[1]);

    // Sunlit metallic rim of post
    brush.set("2H", "#ebdce3", wPost * 0.55);
    brush.line(pBot[0] - 1.4, pBot[1], pTop[0] - 1.4, pTop[1]);

    // Domed post cap finial
    brush.set("rotring", "#f5e6ed", wPost * 0.8);
    brush.line(pTop[0] - 2.2, pTop[1], pTop[0] + 2.2, pTop[1]);

    // Corner diagonal brace strut on terminal bays
    if (b === 0 && bayCount >= 3) {
      const pMidPost = fencePt(0, hFence * 0.65);
      const pNextBot = fencePt(bayLen, 0.08);
      brush.set("rotring", "#291c2e", wPost * 0.65);
      brush.line(pMidPost[0], pMidPost[1], pNextBot[0], pNextBot[1]);
    }
    if (b === bayCount && bayCount >= 3) {
      const pMidPost = fencePt(totalLen, hFence * 0.65);
      const pPrevBot = fencePt(totalLen - bayLen, 0.08);
      brush.set("rotring", "#291c2e", wPost * 0.65);
      brush.line(pMidPost[0], pMidPost[1], pPrevBot[0], pPrevBot[1]);
    }
  }
}

