// =============================================================================
// 8. SAGGING MUNICIPAL NET & WEATHERED POSTS
// =============================================================================
function renderSaggingNet() {
  // Catenary sag curve for the top of the net (1.07m at posts, sagging to 0.855m near center)
  function netTopH(v) {
    const norm = v / 6.40;
    return 0.855 + 0.215 * (norm * norm) + 0.012 * Math.sin(v * 0.85);
  }

  function netBotH(v) {
    const norm = v / 6.40;
    return 0.035 + 0.025 * (norm * norm);
  }

  // 8A. Woven Dark Cord Net Mesh (Every Vertical & Horizontal Cord in Perspective)
  // Vertical cords spaced every 0.068m across v = -6.32..+6.32
  for (let v = -6.32; v <= 6.32; v += 0.068) {
    const pTop = proj(0, netTopH(v) - 0.05, v);
    const pBot = proj(0, netBotH(v), v);
    const isLit = (Math.round(v * 15) % 3 === 0);
    brush.set("2H", isLit ? "#5e384d" : "#261221", 0.36);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }

  // Horizontal sagging cords (15 rows from bottom to top headband)
  const hRows = 15;
  for (let r = 0; r <= hRows; r++) {
    const frac = r / hRows;
    const pts = [];
    for (let v = -6.34; v <= 6.34; v += 0.45) {
      const h = lerp(netBotH(v), netTopH(v) - 0.05, frac);
      pts.push(proj(0, h, v));
    }
    const isBottomTape = (r === 0);
    brush.set(
      isBottomTape ? "rotring" : "2H",
      isBottomTape ? "#1d0c19" : (r % 2 === 0 ? "#2e1526" : "#4d283d"),
      isBottomTape ? 0.65 : 0.35
    );
    for (let i = 0; i < pts.length - 1; i++) {
      brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    }
  }

  // Dark reinforced side-bands at both ends of the net (v = ±6.34)
  for (const vEnd of [-6.34, 6.34]) {
    const p1 = proj(0, netBotH(vEnd), vEnd);
    const p2 = proj(0, netTopH(vEnd), vEnd);
    brush.set("rotring", "#1f0d1b", 1.1);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 8B. White Canvas Center Strap & Metal Anchor Buckle at (u = 0, v = 0)
  const csTop1 = proj(0, netTopH(-0.03), -0.03);
  const csTop2 = proj(0, netTopH(0.03), 0.03);
  const csBot2 = proj(0, 0.0, 0.03);
  const csBot1 = proj(0, 0.0, -0.03);
  brush.noStroke();
  brush.wash("#f7e8dc", 240);
  drawPoly2D([csTop1, csTop2, csBot2, csBot1], 0);
  brush.noWash();
  brush.set("rotring", "#6e4256", 0.42);
  brush.line(csTop1[0], csTop1[1], csBot1[0], csBot1[1]);
  brush.line(csTop2[0], csTop2[1], csBot2[0], csBot2[1]);

  // 8C. Sagging White Canvas Top Headband (with Exposed Steel Cable at Post Ends)
  // Steel tension cable running from posts into the headband
  for (const vSign of [-1, 1]) {
    const pPostTop = proj(0, 1.07, vSign * 6.40);
    const pNetCorner = proj(0, netTopH(vSign * 6.32), vSign * 6.32);
    brush.set("rotring", "#d4c2cb", 0.65);
    brush.line(pPostTop[0], pPostTop[1], pNetCorner[0], pNetCorner[1]);
  }

  // Build polygon for the sagging white canvas headband (thickness 0.065m)
  const tapeUpper = [];
  const tapeLower = [];
  for (let v = -6.34; v <= 6.34; v += 0.32) {
    const hU = netTopH(v);
    const hL = hU - 0.065;
    tapeUpper.push(proj(0, hU, v));
    tapeLower.unshift(proj(0, hL, v));
  }

  brush.noStroke();
  brush.wash("#fff9f0", 248);
  drawPoly2D([...tapeUpper, ...tapeLower], 0.1);
  brush.noWash();

  // Subtle warm rose-grey shadow along lower crease of canvas headband & crisp upper edge
  for (let i = 0; i < tapeUpper.length - 1; i++) {
    brush.set("2H", "#ffffff", 0.58);
    brush.line(tapeUpper[i][0], tapeUpper[i][1], tapeUpper[i + 1][0], tapeUpper[i + 1][1]);
  }
  for (let i = 0; i < tapeLower.length - 1; i++) {
    brush.set("rotring", "#8c5b6f", 0.48);
    brush.line(tapeLower[i][0], tapeLower[i][1], tapeLower[i + 1][0], tapeLower[i + 1][1]);
  }

  // 8D. Left & Right Steel Net Posts (u = 0, v = ±6.40, h = 0..1.08m) + Winder Crank
  for (const vPost of [-6.40, 6.40]) {
    const wHalf = 0.055;
    const pBL = proj(0, 0, vPost - wHalf);
    const pBR = proj(0, 0, vPost + wHalf);
    const pTR = proj(0, 1.08, vPost + wHalf);
    const pTL = proj(0, 1.08, vPost - wHalf);

    brush.noStroke();
    brush.wash("#241121", 245);
    drawPoly2D([pBL, pBR, pTR, pTL], 0);
    brush.noWash();

    // Sunlit left edge highlight on cylindrical post
    brush.set("cpencil", "#e6c8d3", 0.7);
    brush.line(pBL[0] + 1, pBL[1], pTL[0] + 1, pTL[1]);

    // Post cap & pulley wheel
    brush.set("rotring", "#f2dfe6", 0.85);
    brush.line(pTL[0] - 1, pTL[1], pTR[0] + 1, pTR[1]);
  }

  // Brass/steel ratchet winder wheel & crank handle on the right net post (v = +6.40, h = 0.72m)
  const pCrank = proj(0, 0.72, 6.46);
  brush.set("rotring", "#2b1324", 0.85);
  brush.circle(pCrank[0], pCrank[1], 4.5, 0.1);
  brush.set("rotring", "#e8c89b", 0.65);
  brush.line(pCrank[0], pCrank[1], pCrank[0] + 6, pCrank[1] + 5);
  brush.line(pCrank[0] + 6, pCrank[1] + 5, pCrank[0] + 9, pCrank[1] + 4);
}

