function renderForgottenBallAndDetails() {
  // 10A. Scattered fallen snow-white & coral-pink elm leaves on the dusty magenta court apron
  const leafZones = [
    { uMin: -14.5, uMax: 15.0, vMin: -9.3, vMax: -5.8, count: 55 },
    { uMin: 11.5,  uMax: 15.6, vMin: -5.5, vMax: 9.0,  count: 48 },
    { uMin: -12.0, uMax: 14.0, vMin: 5.8,  vMax: 9.2,  count: 42 }
  ];

  for (const z of leafZones) {
    for (let i = 0; i < z.count; i++) {
      const u = random(z.uMin, z.uMax);
      const v = random(z.vMin, z.vMax);
      const p = proj(u, 0.005, v);
      if (p[0] < 10 || p[0] > 1190 || p[1] > 1190) continue;

      // Tiny dark contact shadow under fallen leaf
      brush.set("2H", "#380d22", 0.45);
      brush.line(p[0] + 1, p[1] + 1, p[0] + 4, p[1] + 1.5);

      // Snow-white or coral-pink fallen leaf
      const isWhite = random() < 0.62;
      brush.set("gouache_stipple", isWhite ? "#fffaf2" : "#f29d94", 0.42);
      brush.line(p[0], p[1], p[0] + random(2.5, 5.5), p[1] + random(-1.5, 1.5));
    }
  }

  // 10B. The Single Forgotten Yellow Tennis Ball (Reads as Pale Lemon)
  // Positioned in the near right-center court (u = -9.85m, v = +0.75m)
  const uBall = -9.85;
  const vBall = 0.75;
  const rWorld = 0.036;
  const pCenter = proj(uBall, rWorld, vBall);
  const pRim = proj(uBall, rWorld * 2.0, vBall);
  const bx = pCenter[0];
  const by = pCenter[1];
  const rPx = Math.max(9.5, Math.abs(pCenter[1] - pRim[1]) * 1.35);

  // 1. Elliptical cast shadow on the dusty magenta court (cast to the right-back)
  brush.noStroke();
  brush.wash("#2e091c", 215);
  const shPts = [];
  for (let a = 0; a < 360; a += 20) {
    shPts.push([
      bx + rPx * 0.95 + cos(a) * rPx * 1.35,
      by + rPx * 0.52 + sin(a) * rPx * 0.48
    ]);
  }
  drawPoly2D(shPts, 0.25);

  // Contact occlusion core directly under the ball
  brush.wash("#1a040f", 245);
  const occPts = [];
  for (let a = 0; a < 360; a += 30) {
    occPts.push([
      bx + rPx * 0.15 + cos(a) * rPx * 0.75,
      by + rPx * 0.72 + sin(a) * rPx * 0.28
    ]);
  }
  drawPoly2D(occPts, 0.2);

  // 2. Base sphere of the tennis ball in pale lemon
  const ballCircle = (cx, cy, rad) => {
    const pts = [];
    for (let a = 0; a < 360; a += 18) {
      pts.push([cx + cos(a) * rad, cy + sin(a) * rad]);
    }
    return pts;
  };

  // Warm lemon-ochre shadow hemisphere with dusty magenta bounce light from the court
  brush.wash("#d9b468", 245);
  drawPoly2D(ballCircle(bx, by, rPx), 0.25);

  // Dusty rose-ochre reflected bounce light on bottom-right crescent
  brush.wash("#c97e75", 165);
  drawPoly2D(ballCircle(bx + rPx * 0.22, by + rPx * 0.28, rPx * 0.70), 0.25);

  // Main pale-lemon lit body (#fcf297)
  brush.wash("#fcf297", 245);
  drawPoly2D(ballCircle(bx - rPx * 0.10, by - rPx * 0.12, rPx * 0.86), 0.25);

  // Luminous pale-lemon upper-left crown (#fffbd1)
  brush.wash("#fffbd1", 245);
  drawPoly2D(ballCircle(bx - rPx * 0.24, by - rPx * 0.26, rPx * 0.56), 0.25);

  // Snow-white specular felt highlight (#ffffff)
  brush.wash("#ffffff", 230);
  drawPoly2D(ballCircle(bx - rPx * 0.34, by - rPx * 0.34, rPx * 0.26), 0.2);
  brush.noWash();

  // 3. Characteristic curved white rubber seam of the tennis ball
  brush.set("rotring", "#b89b64", 0.52);
  brush.spline([
    [bx - rPx * 0.82, by + rPx * 0.18, 0.6],
    [bx - rPx * 0.15, by - rPx * 0.22, 0.9],
    [bx + rPx * 0.32, by + rPx * 0.58, 0.6]
  ], 0.45);
  brush.set("cpencil", "#fffef5", 0.62);
  brush.spline([
    [bx - rPx * 0.82, by + rPx * 0.12, 0.7],
    [bx - rPx * 0.15, by - rPx * 0.28, 1.0],
    [bx + rPx * 0.36, by + rPx * 0.54, 0.7]
  ], 0.45);

  // 4. Hyperreal fuzzy felt nap halo around the pale-lemon ball
  brush.set("2H", "#fffce0", 0.38);
  for (let a = 0; a < 360; a += 14) {
    const r1 = rPx * 0.92;
    const r2 = rPx * random(1.06, 1.18);
    brush.line(
      bx + cos(a) * r1,
      by + sin(a) * r1,
      bx + cos(a + random(-6, 6)) * r2,
      by + sin(a + random(-6, 6)) * r2
    );
  }
}

