// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 0.25) {
      clean.push(pts[i]);
    }
  }
  if (clean.length < 2) return;
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else {
    brush.spline(clean, curvature);
  }
}

function makeBlob(cx, cy, rx, ry, n = 16, irr = 0.12, rotDeg = 0) {
  let pts = [];
  let c = cos(rotDeg), s = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let ang = (i / n) * 360;
    let nVal = noise(cx * 0.01 + cos(ang) * 1.2, cy * 0.01 + sin(ang) * 1.2);
    let rScale = 1 + map(nVal, 0, 1, -irr, irr);
    let lx = cos(ang) * rx * rScale;
    let ly = sin(ang) * ry * rScale;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

// ============================================================================
// 1. PAPER AGING & FOXING
// ============================================================================

function drawPaperAgingAndFoxing() {
  brush.noStroke();

  // Batch 1: Warm parchment edge toning
  brush.fill(PAL.paperWarm, 55);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.6, 0.3);
  drawPoly([[0, 0], [1200, 0], [1200, 150], [0, 110]], 0.1);
  drawPoly([[0, 1060], [1200, 1020], [1200, 1200], [0, 1200]], 0.1);
  drawPoly([[0, 0], [140, 0], [100, 1200], [0, 1200]], 0.1);
  drawPoly([[1070, 0], [1200, 0], [1200, 1200], [1040, 1200]], 0.1);

  // Batch 2: Pale foxing stains near corners and margins
  brush.fill(PAL.foxing1, 28);
  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.75, 0.45);
  let stains = [
    [95, 85, 75, 50], [1110, 115, 65, 80], [75, 620, 45, 95],
    [1125, 780, 55, 70], [140, 1110, 85, 45], [1030, 1090, 70, 50],
    [580, 55, 90, 35], [340, 1140, 60, 30]
  ];
  for (let s of stains) {
    drawPoly(makeBlob(s[0], s[1], s[2], s[3], 12, 0.35, random(360)), 0.35);
  }

  brush.noFill();
}

function drawMarginFoxingSpots() {
  // Subtle dry stipple and tiny foxing specks on the antique border
  brush.noFill();
  let foxClusters = [
    [65, 95], [1135, 85], [52, 430], [1148, 520],
    [72, 920], [1128, 1040], [220, 48], [890, 52],
    [180, 1150], [960, 1145], [480, 1125], [1055, 976]
  ];
  for (let fc of foxClusters) {
    brush.set("spray", PAL.foxing2, 0.45);
    brush.circle(fc[0], fc[1], random(8, 22), 0.3);
    brush.set("rotring", PAL.inkLight, 0.25);
    for (let k = 0; k < 5; k++) {
      let a = random(360), d = random(2, 26);
      let px = fc[0] + cos(a) * d, py = fc[1] + sin(a) * d;
      brush.line(px, py, px + random(-1.5, 1.5), py + random(-1.5, 1.5));
    }
  }
}

