// ============================================================================
// 4. GNARLED TREE TRUNK, ROOTS & HIDDEN FACES (ARTHUR RACKHAM STYLE)
// ============================================================================

function drawGnarledTrunkAndHiddenFaces() {
  // Flowing bark lines and gnarly root forms with hidden woodland faces
  // --- 4A. Left & Center Massive Gnarled Trunk ---
  brush.set("quill_bold", PAL.inkSepia, 0.9);

  // Outer left trunk silhouette & primary flutes
  let leftTrunkEdges = [
    [[145, 94], [158, 210], [148, 340], [132, 480], [115, 610]],
    [[185, 94], [198, 195], [188, 320], [176, 445], [152, 575]],
    [[445, 94], [432, 185], [442, 290], [468, 375], [525, 422]],
    [[482, 94], [472, 190], [488, 285], [525, 365], [610, 430]]
  ];
  for (let crv of leftTrunkEdges) safeSpline(crv, 0.45);

  // Vertical flowing bark grain across upper trunk (avoiding the Elder Face zone x:215..365, y:210..390)
  for (let x = 135; x <= 495; x += 9) {
    let segs = 12;
    let pts = [];
    for (let s = 0; s <= segs; s++) {
      let y = map(s, 0, segs, 96, 445);
      // Bend grain around the Elder Face at (285, 295)
      let dxFace = x - 285;
      let dyFace = y - 295;
      let distFace = sqrt(dxFace * dxFace + dyFace * dyFace);
      let push = 0;
      if (distFace < 115) {
        push = (dxFace >= 0 ? 1 : -1) * pow(map(distFace, 0, 115, 1, 0), 1.6) * 34;
      }
      let wobble = map(noise(x * 0.03, y * 0.015), 0, 1, -12, 12);
      let px = x + push + wobble;
      // Skip interior of the Elder Face so we can draw the face features cleanly
      if (px > 222 && px < 352 && y > 222 && y < 375) {
        if (pts.length >= 2) {
          brush.set("quill", (x % 18 === 0) ? PAL.inkSepia : PAL.inkMid, random(0.45, 0.8));
          safeSpline(pts, 0.45);
        }
        pts = [];
      } else {
        pts.push([px, y]);
      }
    }
    if (pts.length >= 2) {
      brush.set("quill", (x % 18 === 0) ? PAL.inkSepia : PAL.inkMid, random(0.45, 0.8));
      safeSpline(pts, 0.45);
    }
  }

  // --- HIDDEN FACE 1: THE WOODLAND ELDER IN THE UPPER-LEFT TRUNK (cx: 285, cy: 295) ---
  drawHiddenElderFace(285, 295);

  // --- 4B. Hollow Tree Cavern & Center Twisting Boughs (x: 490..780, y: 94..445) ---
  // Deep cross-hatched sepia gloom inside the hollow between trunks
  brush.hatchStyle("quill", PAL.inkDark, 0.55);
  brush.hatch(7, 28, { rand: 0.08 });
  brush.noStroke();
  drawPoly([[505, 96], [735, 96], [765, 415], [535, 405]], 0.2);
  brush.hatch(9, -35, { rand: 0.08 });
  drawPoly([[525, 120], [720, 120], [745, 395], [555, 390]], 0.2);
  brush.noHatch();

  // Spidery hanging rootlets and creeping ivy vines across the upper hollow
  brush.set("quill", PAL.inkSepia, 0.55);
  for (let i = 0; i < 18; i++) {
    let rx = map(i, 0, 17, 500, 755);
    let len = random(90, 260);
    let rPts = [];
    for (let k = 0; k <= 8; k++) {
      let ry = 95 + (k / 8) * len;
      let rw = sin(k * 38 + i * 25) * 10 + map(noise(i, k * 0.3), 0, 1, -8, 8);
      rPts.push([rx + rw, ry]);
    }
    safeSpline(rPts, 0.5);
  }

  // --- 4C. Right-Side Twisting Bough & HIDDEN FACE 2: SLY DRYAD / GOBLIN PROFILE ---
  drawRightBoughAndGoblinProfile();

  // --- 4D. Sweeping Gnarled Roots Cradling the Boot & HIDDEN FACE 3: ROOT-GNOME ---
  drawCradlingRootsAndGnomeFace();
}

