  safeSpline([[cx + 14, cy + 12], [cx + 8, cy + 9], [cx + 5, cy + 16]], 0.4);
  for (let r = 4; r <= 12; r += 4) {
    brush.arc(cx + 1, cy + 6, r, 190, 350);
  }

  // Sweeping bark-grain moustache & pursed woodland mouth
  brush.set("quill_bold", PAL.inkDark, 0.85);
