  safeSpline([[cx - 32, cy + 46], [cx - 10, cy + 49], [cx + 12, cy + 48], [cx + 34, cy + 45]], 0.4);
  brush.set("quill", PAL.inkSepia, 0.65);
  safeSpline([[cx - 22, cy + 54], [cx, cy + 58], [cx + 24, cy + 53]], 0.4);

  // Fluted beard of bark ridges flowing into the lower trunk
  for (let b = -65; b <= 65; b += 8) {
