function drawCradlingRootsAndGnomeFace() {
  // Great sinuous roots snaking from the left trunk under and behind the boot
  let roots = [
    // Root 1: Upper cradling root behind the boot opening
    {
      top: [[120, 520], [235, 445], [355, 405], [475, 412], [585, 438]],
      bot: [[120, 595], [245, 515], [360, 478], [465, 480], [575, 495]]
    },
    // Root 2: Foreground left root with the Sleeping Root-Gnome knee at (232, 695)
    {
      top: [[110, 650], [185, 628], [245, 635], [315, 685], [375, 745], [465, 795]],
      bot: [[110, 755], [185, 765], [255, 772], [325, 795], [415, 835], [495, 855]]
    },
    // Root 3: Right side twisted root emerging behind the boot toe
    {
      top: [[835, 485], [915, 465], [995, 482], [1090, 525]],
      bot: [[865, 545], [935, 535], [1005, 558], [1090, 605]]
    }
  ];

  for (let r of roots) {
    // Interpolate longitudinal bark lines between top and bot
    for (let t = 0; t <= 1.0; t += 0.14) {
      let rLine = [];
      for (let i = 0; i < r.top.length; i++) {
        let px = lerp(r.top[i][0], r.bot[i][0], t);
        let py = lerp(r.top[i][1], r.bot[i][1], t) + sin(i * 45 + t * 180) * 4;
        // Leave breathing room around the Root-Gnome face at (232, 695)
        if (dist(px, py, 232, 698) > 46 || t === 0 || t > 0.85) {
          rLine.push([px, py]);
        }
      }
      brush.set(t === 0 || t > 0.85 ? "quill_bold" : "quill", t > 0.6 ? PAL.inkDark : PAL.inkSepia, t === 0 || t > 0.85 ? 0.95 : 0.55);
      safeSpline(rLine, 0.45);
    }
    // Cross-contour root rings
    for (let k = 0; k < r.top.length - 1; k++) {
      for (let sub = 0.2; sub < 0.9; sub += 0.35) {
        let tx = lerp(r.top[k][0], r.top[k + 1][0], sub);
        let ty = lerp(r.top[k][1], r.top[k + 1][1], sub);
        let bx = lerp(r.bot[k][0], r.bot[k + 1][0], sub);
        let by = lerp(r.bot[k][1], r.bot[k + 1][1], sub);
        let mx = (tx + bx) * 0.5 + 10, my = (ty + by) * 0.5;
        if (dist(mx, my, 232, 698) > 52) {
          brush.set("quill", PAL.inkMid, 0.45);
          safeSpline([[tx, ty], [mx, my], [bx, by]], 0.5);
        }
      }
    }
  }

  // --- HIDDEN FACE 3: SLEEPING ROOT-GNOME AT (232, 698) ---
  let gx = 232, gy = 698;
  brush.set("skin_glaze", PAL.russetSoft, 1.1);
  brush.circle(gx, gy - 2, 16, 0.2); // warm bulbous root-nose
  brush.set("quill_bold", PAL.inkDark, 0.8);
  // Furrowed root-brow
  safeSpline([[gx - 48, gy - 32], [gx - 22, gy - 38], [gx, gy - 28], [gx + 24, gy - 38], [gx + 48, gy - 28]], 0.45);
  // Closed sleeping crescent eyes
  safeSpline([[gx - 42, gy - 18], [gx - 26, gy - 10], [gx - 12, gy - 18]], 0.5);
  safeSpline([[gx + 12, gy - 18], [gx + 26, gy - 10], [gx + 42, gy - 18]], 0.5);
  // Round button-burl nose
  safeSpline([[gx - 8, gy - 16], [gx - 18, gy - 2], [gx - 10, gy + 12], [gx + 10, gy + 12], [gx + 18, gy - 2], [gx + 8, gy - 16]], 0.5);
  // Plump root-cheeks & contentedly sleeping smile under root-tendril whiskers
  brush.set("quill", PAL.inkSepia, 0.65);
  safeSpline([[gx - 46, gy - 6], [gx - 54, gy + 12], [gx - 36, gy + 26]], 0.5);
  safeSpline([[gx + 46, gy - 6], [gx + 54, gy + 12], [gx + 36, gy + 26]], 0.5);
  safeSpline([[gx - 24, gy + 22], [gx, gy + 30], [gx + 24, gy + 22]], 0.45);
}

function drawBackgroundFoliageAndMushrooms() {
  // Shelf / bracket fungi on the left trunk around (165, 575)
  let shelves = [
    { x: 162, y: 562, rx: 38, ry: 15 },
    { x: 185, y: 582, rx: 46, ry: 18 },
    { x: 155, y: 602, rx: 32, ry: 13 }
  ];
  for (let sh of shelves) {
    brush.set("skin_glaze", PAL.ochrePale, 1.1);
    safeSpline([[sh.x - sh.rx, sh.y], [sh.x, sh.y - sh.ry * 0.7], [sh.x + sh.rx, sh.y]], 0.5);
    brush.set("quill_bold", PAL.inkDark, 0.75);
    safeSpline([[sh.x - sh.rx, sh.y], [sh.x, sh.y - sh.ry], [sh.x + sh.rx, sh.y]], 0.5);
    safeSpline([[sh.x - sh.rx, sh.y], [sh.x, sh.y + sh.ry * 0.45], [sh.x + sh.rx, sh.y]], 0.45);
    // Gill striations underneath
    brush.set("quill", PAL.inkMid, 0.4);
    for (let g = -0.8; g <= 0.8; g += 0.2) {
      brush.line(sh.x + g * sh.rx * 0.5, sh.y + 3, sh.x + g * sh.rx * 0.95, sh.y - 1);
    }
  }

  // Delicate fern fronds on the right bank (x: 910..1075, y: 360..510)
  let fronds = [
    { sx: 940, sy: 475, ex: 1065, ey: 365, bend: -25 },
    { sx: 955, sy: 490, ex: 1080, ey: 425, bend: -15 },
    { sx: 920, sy: 465, ex: 995, ey: 345, bend: 20 }
  ];
  for (let f of fronds) {
    let mx = (f.sx + f.ex) * 0.5 + f.bend;
    let my = (f.sy + f.ey) * 0.5 - 15;
    brush.set("quill", PAL.inkSepia, 0.6);
    safeSpline([[f.sx, f.sy], [mx, my], [f.ex, f.ey]], 0.5);
    // Pinnae (leaflets)
    for (let t = 0.12; t <= 0.92; t += 0.08) {
      let px = lerp(lerp(f.sx, mx, t), lerp(mx, f.ex, t), t);
      let py = lerp(lerp(f.sy, my, t), lerp(my, f.ey, t), t);
      let pLen = (1 - abs(t - 0.45)) * 22;
      brush.set("quill", PAL.oliveDark, 0.5);
      brush.line(px, py, px - pLen, py - pLen * 0.4);
      brush.line(px, py, px + pLen * 0.8, py + pLen * 0.5);
    }
  }
}

