// Smooth 3D surface normal estimator for the toad's anatomy so every wart is lit with photographic accuracy
function getToadSurfaceNormal(x, y) {
  // Union of anatomical ellipsoids: [cx, cy, rx, ry, weight]
  let vols = [
    [475, 628, 118, 98, 1.0],  // Main squat torso
    [398, 542, 86, 62, 1.1],   // Head & cranium
    [388, 618, 72, 54, 1.25],  // Moist inflated throat sac (gular pouch)
    [504, 542, 48, 25, 1.35],  // Swollen near parotoid gland
    [422, 520, 34, 28, 1.4],   // Near supraorbital eye boss
    [350, 504, 22, 18, 1.2],   // Far eye boss
    [495, 712, 36, 62, 1.1],   // Near foreleg
    [338, 705, 30, 56, 1.05],  // Far foreleg
    [552, 685, 48, 52, 0.95]   // Tucked hind leg
  ];

  let gx = 0, gy = 0, maxH = 0.05;
  for (let v of vols) {
    let dx = (x - v[0]) / v[2];
    let dy = (y - v[1]) / v[3];
    let d2 = dx * dx + dy * dy;
    if (d2 < 1.35) {
      let w = v[4] * exp(-d2 * 1.6);
      gx += (dx / v[2]) * w * 65;
      gy += (dy / v[3]) * w * 65;
      let h = sqrt(max(0.01, 1.35 - d2)) * v[4];
      if (h > maxH) maxH = h;
    }
  }
  let nz = 0.75;
  let len = sqrt(gx * gx + gy * gy + nz * nz) || 1;
  return { nx: gx / len, ny: gy / len, nz: nz / len };
}

