function drawMoistThroatPulse() {
  // The inflated vocal/gular sac at (390, 618, rx: 72, ry: 52)
  // 1. Concentric translucent rose, lilac-grey, and warm cream glazes for spherical tension
  let cx = 388, cy = 616;
  for (let r = 1.0; r >= 0.15; r -= 0.12) {
    let col = r > 0.72 ? PAL.throatLilac : (r > 0.42 ? PAL.throatRose : PAL.throatCream);
    brush.set("skin_glaze", col, 2.4);
    let pts = [];
    for (let a = -15; a <= 195; a += 18) {
      let px = cx - 6 * (1 - r) + cos(a) * 70 * r;
      let py = cy - 8 * (1 - r) + sin(a) * 50 * r;
      pts.push([px, py]);
    }
    safeSpline(pts, 0.5);
  }

  // Bright creamy-white core of the inflated throat pulse
  for (let k = 0; k < 8; k++) {
    brush.set("skin_glaze", PAL.specular, 1.8);
    let oy = map(k, 0, 7, 582, 628);
    safeSpline([[342, oy], [378, oy + 6], [418, oy - 2]], 0.5);
  }

  // 2. Delicate elastic stretch striae & faint subcutaneous capillaries on the pulsing throat
  brush.set("quill", PAL.roseMid, 0.28);
  for (let s = -4; s <= 4; s++) {
    let sx1 = cx + s * 11, sy1 = 574 + abs(s) * 2;
    let sx2 = cx + s * 14, sy2 = 618 + (4 - abs(s)) * 4;
    let sx3 = cx + s * 9, sy3 = 658 - abs(s) * 2;
    safeSpline([[sx1, sy1], [sx2, sy2], [sx3, sy3]], 0.5);
