function drawHyperrealWartTopography() {
  // Generate ~290 non-overlapping, size-graded warts across the toad's dorsal, flank, cranial, and limb zones
  // Light vector from upper-left-front: L = (-0.58, -0.64, 0.50)
  let lx = -0.58, ly = -0.64, lz = 0.50;
  let warts = [];

  // Candidate generator with spatial rejection for natural organic packing
  for (let attempt = 0; attempt < 1800; attempt++) {
    let x = random(312, 590);
    let y = random(482, 758);

    // Exclude eyes & tympanum
    let dNearEye = sq((x - 422) / 34) + sq((y - 520) / 26);
    let dFarEye = sq((x - 350) / 22) + sq((y - 504) / 18);
    let dTymp = sq((x - 466) / 16) + sq((y - 568) / 17);
    if (dNearEye < 1.08 || dFarEye < 1.05 || dTymp < 1.05) continue;

    // Exclude center of near parotoid gland (already has its own smooth pitted skin)
    let gpX = (x - 504) * cos(-22) - (y - 542) * sin(-22);
    let gpY = (x - 504) * sin(-22) + (y - 542) * cos(-22);
    if (sq(gpX / 44) + sq(gpY / 17) < 0.88) continue;

    // Check if inside toad silhouette regions
    let inTorso = sq((x - 482) / 108) + sq((y - 622) / 88) < 1.0;
    let inHead = sq((x - 395) / 80) + sq((y - 540) / 52) < 1.0;
    let inThroat = sq((x - 388) / 68) + sq((y - 616) / 48) < 1.0;
    let inNearArm = sq((x - 492) / 30) + sq((y - 705) / 56) < 1.0;
    let inFarArm = sq((x - 338) / 24) + sq((y - 702) / 50) < 1.0;
    let inHindLeg = sq((x - 555) / 38) + sq((y - 690) / 48) < 1.0;

    if (!(inTorso || inHead || inThroat || inNearArm || inFarArm || inHindLeg)) continue;

    // Determine wart radius based on anatomical region
    let r;
    if (inThroat && y > 574) {
      // Throat has only tiny, sparse translucent granules around the periphery
      let dThroatCenter = sq((x - 384) / 52) + sq((y - 608) / 36);
      if (dThroatCenter < 0.75) continue;
      r = random(1.6, 3.2);
    } else if (inTorso && y < 665 && x > 435) {
      // Large prominent dorsal & dorso-lateral warts!
      r = attempt < 350 ? random(6.5, 12.5) : random(3.2, 6.8);
    } else if (inNearArm || inFarArm || inHindLeg) {
      // Spiky medium tubercles on forearms and shins
      r = random(2.8, 6.2);
    } else {
      // Cranial, snout, and lower flank warts
      r = random(2.2, 5.8);
    }

    // Check collision against existing warts
    let ok = true;
    for (let w of warts) {
      let minDist = (r + w.r) * 0.92 + 0.8;
      if (sq(x - w.x) + sq(y - w.y) < minDist * minDist) {
        ok = false;
        break;
      }
    }
    if (ok) {
      warts.push({
        x, y, r,
        inThroat: inThroat && y > 574,
        hueType: random() // mixes olive, russet-terracotta, and dusty-rose warts
      });
      if (warts.length >= 295) break;
    }
  }

  // Sort warts back-to-front by Y so overlapping domes layer naturally
  warts.sort((a, b) => a.y - b.y);

  // Render each wart with full 3D normal-mapped lighting, shadow crevice, keratin peak, and wet highlight!
  for (let w of warts) {
    let norm = getToadSurfaceNormal(w.x, w.y);
    let illum = constrain(norm.nx * lx + norm.ny * ly + norm.nz * lz, -0.6, 1.0);
    drawSingleHyperrealWart(w, norm, illum);
  }
}

function drawSingleHyperrealWart(w, norm, illum) {
  let { x, y, r, inThroat, hueType } = w;

  if (inThroat) {
    // Subtle pearlescent rose/cream granule on throat periphery
    brush.set("wart_sculpt", PAL.roseMid, 0.45);
    brush.arc(x, y, r, 10, 175);
    brush.set("specular_glint", PAL.throatCream, 0.65);
    brush.circle(x - r * 0.25, y - r * 0.25, r * 0.6, 0.1);
    return;
  }

  // Choose local pigment palette based on illumination and natural Bufo wart variation
  let shadowCol = illum < -0.1 ? PAL.inkDark : PAL.inkSepia;
  let midCol, litCol;
  if (hueType < 0.42) {
    // Brick-russet / terracotta wart
    midCol = illum > 0.1 ? PAL.russetSoft : PAL.russetMid;
    litCol = illum > 0.25 ? PAL.russetPale : PAL.ochreSoft;
  } else if (hueType < 0.76) {
    // Mossy olive-ochre wart
    midCol = illum > 0.1 ? PAL.oliveSoft : PAL.oliveMid;
    litCol = illum > 0.25 ? PAL.olivePale : PAL.ochreSoft;
  } else {
    // Dusty-rose / mauve-brown wart
    midCol = illum > 0.1 ? PAL.roseSoft : PAL.roseMid;
    litCol = illum > 0.25 ? PAL.rosePale : PAL.throatRose;
  }

  // 1. Basal skin crevice shadow on the lower-right side of the wart
  brush.set("quill", shadowCol, constrain(r * 0.11, 0.35, 0.95));
  brush.arc(x + r * 0.08, y + r * 0.12, r * 1.05, 340, 175);

  // 2. Shaded lower-right slope of the wart dome
  brush.set("wart_sculpt", midCol, constrain(r * 0.16, 0.45, 1.45));
  brush.circle(x + r * 0.06, y + r * 0.06, r * 0.78, 0.18);

  // 3. Illuminated upper-left dome of the wart
  if (illum > -0.25) {
    brush.set("wart_sculpt", litCol, constrain(r * 0.14, 0.4, 1.25));
    brush.circle(x - r * 0.18, y - r * 0.18, r * 0.55, 0.15);
  }

  // 4. Fine illustrator's contour & central keratinized peak / satellite pores on larger warts
  if (r > 4.2) {
    brush.set("quill", PAL.inkSepia, 0.38);
    brush.arc(x, y, r * 0.98, 175, 340);

    // Dark russet-umber keratin tip at the crown of the wart
    brush.set("rotring", PAL.russetDark, 0.65);
    brush.circle(x - r * 0.08, y - r * 0.08, r * 0.16, 0.1);

    // Satellite micro-tubercles / pores on large warts (r > 7)
    if (r > 7.0) {
      for (let p = 0; p < 3; p++) {
        let pa = p * 120 + (x * 17) % 90;
        let px = x + cos(pa) * r * 0.48;
        let py = y + sin(pa) * r * 0.45;
        brush.set("rotring", PAL.inkDark, 0.45);
        brush.circle(px, py, 0.9, 0.1);
      }
    }
  }

  // 5. Wet Mucus Specular Catchlight on warts facing the upper-left light!
  if (illum > 0.12 && (r > 3.5 || hueType > 0.5)) {
    let gx = x - r * 0.32;
    let gy = y - r * 0.32;
    brush.set("specular_glint", illum > 0.38 ? PAL.specular : PAL.throatCream, constrain(r * 0.09, 0.35, 0.85));
    if (r > 6.0) {
      brush.arc(x - r * 0.1, y - r * 0.1, r * 0.58, 195, 265);
    } else {
      brush.circle(gx, gy, constrain(r * 0.18, 0.7, 1.6), 0.05);
    }
  }
}

