  brush.arc(fx - 3, fy - 2, 6.5, 195, 255);
  brush.circle(fx - 5, fy - 4, 2.2, 0.05);

  // --- 2. NEAR EYE (The Jewel-like Hyperreal Golden Iris with Horizontal Pupil at cx: 422, cy: 522) ---
  let ex = 422, ey = 522;
  let rx = 27, ry = 21;

  // A. Deep shadow socket & eyelid folds surrounding the globe
  brush.noStroke();
  brush.wash(PAL.inkDark, 245);
  drawPoly(makeBlob(ex, ey, rx + 4, ry + 3, 20, 0.03, -8), 0.35);

  // B. Outer copper-amber iris base -> mid metallic gold -> bright lemon-gold peripupillary ring
  brush.wash(PAL.irisCopper, 240);
  drawPoly(makeBlob(ex, ey, rx, ry, 24, 0.02, -8), 0.38);
  brush.wash(PAL.irisGoldMid, 235);
  drawPoly(makeBlob(ex, ey, rx * 0.86, ry * 0.86, 24, 0.02, -8), 0.38);
  brush.wash(PAL.irisGoldBright, 220);
  drawPoly(makeBlob(ex, ey, rx * 0.62, ry * 0.56, 20, 0.02, -8), 0.38);
  brush.noWash();

  // C. Intricate Vermiculated & Radial Vascular Striations in the Golden Iris!
  // Real toad irises have a dark web of branching melanin and blood vessels over metallic gold guanophores
  for (let i = 0; i < 76; i++) {
    let ang = (i / 76) * 360;
    let c = cos(-8), s = sin(-8);
    let rIn = random(0.32, 0.48);
    let rOut = random(0.82, 0.98);
    let lx1 = cos(ang) * rx * rIn, ly1 = sin(ang) * ry * rIn;
    let lxMid = cos(ang + random(-14, 14)) * rx * ((rIn + rOut) * 0.5);
    let lyMid = sin(ang + random(-14, 14)) * ry * ((rIn + rOut) * 0.5);
    let lx2 = cos(ang + random(-8, 8)) * rx * rOut, ly2 = sin(ang + random(-8, 8)) * ry * rOut;

    let p1 = [ex + lx1 * c - ly1 * s, ey + lx1 * s + ly1 * c];
    let pM = [ex + lxMid * c - lyMid * s, ey + lxMid * s + lyMid * c];
    let p2 = [ex + lx2 * c - ly2 * s, ey + lx2 * s + ly2 * c];

    brush.set("quill", (i % 3 === 0) ? PAL.inkDark : PAL.russetDark, random(0.28, 0.52));
    safeSpline([p1, pM, p2], 0.45);
  }

  // Sparkling metallic gold platelets (guanophore flecks) between the dark iris veins
  for (let g = 0; g < 48; g++) {
    let ang = random(360);
    let rad = random(0.38, 0.88);
    let lx = cos(ang) * rx * rad, ly = sin(ang) * ry * rad;
    let gx = ex + lx * cos(-8) - ly * sin(-8);
    let gy = ey + lx * sin(-8) + ly * cos(-8);
    brush.set("specular_glint", (g % 2 === 0) ? PAL.irisGoldBright : PAL.ochrePale, random(0.45, 0.75));
    brush.circle(gx, gy, random(0.8, 1.8), 0.1);
  }

  // D. The Horizontal Slit/Elliptical Pupil & Glowing Gold Sphincter Ring!
  // Compute tilted horizontal pupil polygon (pointed slightly at nasal and temporal ends)
  let pupilPts = [];
  let pRx = 18.5, pRy = 6.8;
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * 360;
    // Slight almond pinch at the horizontal tips
    let pinch = 1 - 0.18 * pow(abs(cos(a)), 3);
    let lx = cos(a) * pRx;
    let ly = sin(a) * pRy * pinch;
    let px = ex + lx * cos(-8) - ly * sin(-8);
    let py = ey + lx * sin(-8) + ly * cos(-8);
    pupilPts.push([px, py]);
  }

  // Glowing golden-white sphincter collar immediately around the horizontal pupil
  brush.set("specular_glint", PAL.irisGoldBright, 1.15);
  safeSpline(pupilPts.concat([pupilPts[0]]), 0.35);
  brush.set("specular_glint", PAL.specular, 0.65);
  safeSpline(pupilPts.slice(0, 13), 0.35);

  // Deep velvety black horizontal pupil fill
  brush.noStroke();
  brush.wash(PAL.pupilBlack, 255);
  drawPoly(pupilPts, 0.3);
  brush.noWash();

  // Crisp inner pupil rim & subtle deep indigo-blue depth inside the pupil
  brush.set("skin_glaze", "#161e2e", 0.9);
  brush.line(ex - 10, ey - 1, ex + 8, ey - 2);
  brush.set("rotring", PAL.pupilBlack, 0.85);
  safeSpline(pupilPts.concat([pupilPts[0]]), 0.35);

  // E. Limbal Ring (dark shadow under upper eyelid) & Palpebral Rim Tubercles
  brush.set("quill_bold", PAL.inkDark, 1.25);
  // Upper eyelid crease
  safeSpline([[ex - 29, ey + 3], [ex - 16, ey - 18], [ex + 6, ey - 21], [ex + 28, ey - 4]], 0.45);
  // Lower eyelid rim
  safeSpline([[ex - 28, ey + 4], [ex - 8, ey + 20], [ex + 14, ey + 19], [ex + 28, ey - 3]], 0.45);

  // Tiny bumpy eyelid tubercles along the upper and lower palpebral margins
  for (let b = 0; b < 9; b++) {
    let u = map(b, 0, 8, -22, 22);
    let bx = ex + u;
    let byTop = ey - 20 + (u * u) * 0.028;
    let byBot = ey + 20 - (u * u) * 0.025;
    brush.set("wart_sculpt", PAL.olivePale, 0.65);
    brush.circle(bx, byTop - 2, 2.2, 0.15);
    brush.set("wart_sculpt", PAL.russetSoft, 0.6);
    brush.circle(bx, byBot + 2, 2.0, 0.15);
  }

  // F. Razor-Sharp Wet Corneal Specular Highlights (Window Catchlight + Tear Meniscus)!
  // Primary curved window reflection across upper-left cornea & pupil edge
  brush.noStroke();
  brush.wash(PAL.specularBlue, 185);
  drawPoly([
    [ex - 16, ey - 9], [ex - 4, ey - 15], [ex + 5, ey - 13],
    [ex + 2, ey - 6], [ex - 6, ey - 5], [ex - 14, ey - 3]
  ], 0.25);
  brush.wash(PAL.specular, 250);
  drawPoly([
    [ex - 14, ey - 8], [ex - 4, ey - 13], [ex + 3, ey - 12],
    [ex + 1, ey - 7], [ex - 6, ey - 6], [ex - 12, ey - 4]
  ], 0.2);
  brush.noWash();

  // Crisp bright highlight strokes & secondary corneal glint
  brush.set("specular_glint", PAL.specular, 1.1);
  safeSpline([[ex - 15, ey - 7], [ex - 5, ey - 13], [ex + 4, ey - 12]], 0.4);
  brush.circle(ex - 18, ey - 3, 1.8, 0.05);

  // Wet tear-film meniscus beads along the lower eyelid margin
  brush.set("specular_glint", PAL.specular, 0.75);
  safeSpline([[ex - 14, ey + 17], [ex - 3, ey + 19], [ex + 8, ey + 18]], 0.45);
  brush.circle(ex + 13, ey + 15, 1.2, 0.05);
}

