// Crisp engraved vector lettering helper for Golden Age bookplate typography
function drawEngravedCaption(textStr, centerX, centerY, h, tracking) {
  let w = h * 0.62;
  let totalW = textStr.length * (w + tracking) - tracking;
  let startX = centerX - totalW * 0.5;

  brush.set("rotring", PAL.inkSepia, 0.62);
  for (let i = 0; i < textStr.length; i++) {
    let ch = textStr[i];
    let x = startX + i * (w + tracking);
    let y = centerY;
    drawSerifGlyph(ch, x, y, w, h);
  }
}

function drawSerifGlyph(ch, x, y, w, h) {
  if (ch === " ") return;
  let xm = x + w * 0.5;
  let ym = y + h * 0.48;
  let yb = y + h;
  let s = w * 0.18; // serif tick width

  switch (ch) {
    case "A":
      brush.line(xm, y, x, yb);
      brush.line(xm, y, x + w, yb);
      brush.line(x + w * 0.22, y + h * 0.62, x + w * 0.78, y + h * 0.62);
      brush.line(x - s, yb, x + s, yb);
      brush.line(x + w - s, yb, x + w + s, yb);
      break;
    case "B":
      brush.line(x, y, x, yb);
      safeSpline([[x - s, y], [xm, y], [x + w * 0.9, y + h * 0.24], [xm, ym], [x, ym]], 0.45);
      safeSpline([[x, ym], [xm + 2, ym], [x + w, y + h * 0.74], [xm + 1, yb], [x - s, yb]], 0.45);
      break;
    case "D":
      brush.line(x, y, x, yb);
      safeSpline([[x - s, y], [xm, y], [x + w, ym], [xm, yb], [x - s, yb]], 0.45);
      break;
    case "E":
      brush.line(x, y, x, yb);
      brush.line(x - s, y, x + w, y);
      brush.line(x, ym, x + w * 0.78, ym);
      brush.line(x - s, yb, x + w, yb);
      break;
    case "F":
      brush.line(x, y, x, yb);
      brush.line(x - s, y, x + w, y);
      brush.line(x, ym, x + w * 0.75, ym);
      brush.line(x - s, yb, x + s * 1.4, yb);
      break;
    case "H":
      brush.line(x, y, x, yb);
      brush.line(x + w, y, x + w, yb);
      brush.line(x, ym, x + w, ym);
      brush.line(x - s, y, x + s, y);
      brush.line(x + w - s, y, x + w + s, y);
      brush.line(x - s, yb, x + s, yb);
      brush.line(x + w - s, yb, x + w + s, yb);
      break;
    case "I":
      brush.line(xm, y, xm, yb);
      brush.line(xm - s * 1.4, y, xm + s * 1.4, y);
      brush.line(xm - s * 1.4, yb, xm + s * 1.4, yb);
      break;
    case "L":
      brush.line(x, y, x, yb);
      brush.line(x - s, y, x + s * 1.4, y);
      brush.line(x - s, yb, x + w, yb);
      brush.line(x + w, yb, x + w, yb - s * 1.6);
      break;
    case "N":
      brush.line(x, y, x, yb);
      brush.line(x, y, x + w, yb);
      brush.line(x + w, y, x + w, yb);
      brush.line(x - s, y, x + s, y);
      brush.line(x + w - s, y, x + w + s, y);
      brush.line(x - s, yb, x + s, yb);
      break;
    case "O":
      safeSpline([
        [xm, y], [x + w, ym], [xm, yb], [x, ym], [xm, y]
      ], 0.55);
      break;
    case "P":
      brush.line(x, y, x, yb);
      safeSpline([[x - s, y], [xm + 1, y], [x + w, y + h * 0.26], [xm + 1, ym + 1], [x, ym + 1]], 0.45);
      brush.line(x - s, yb, x + s * 1.4, yb);
      break;
    case "T":
      brush.line(xm, y, xm, yb);
      brush.line(x, y, x + w, y);
      brush.line(x, y, x, y + s * 1.5);
      brush.line(x + w, y, x + w, y + s * 1.5);
      brush.line(xm - s * 1.4, yb, xm + s * 1.4, yb);
      break;
    case "V":
      brush.line(x, y, xm, yb);
      brush.line(x + w, y, xm, yb);
      brush.line(x - s, y, x + s, y);
      brush.line(x + w - s, y, x + w + s, y);
      break;
  }
}

