  // 3. Back Structure of the Wooden Rack
  drawRackBackStructure();

  // 4. Back Wall of Glass Test Tubes & Etched Graduations
  drawGlassBackWalls();

  // 5. Luminous Layered Watercolor Liquids (Grouped/Layered for Richness)
  drawWatercolorLiquids();

  // 6. Refracted Label Text & Magnified Submerged Markings
  drawRefractedLabels();

