  drawSpectroscopicNotations();

  noLoop();
}

// =============================================================================
// GEOMETRY HELPERS
// =============================================================================

function tubeX(i) {
  return TUBE_START_X + i * TUBE_STEP_X;
}

function drawPoly(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function getTubePolygon(cx, yTop, yBot, r, inset = 0) {
  let rad = r - inset;
  let yArcCenter = yBot - rad;
  let pts = [];
  pts.push([cx - rad, yTop]);
  pts.push([cx + rad, yTop]);
  pts.push([cx + rad, yArcCenter]);
  let steps = 10;
  for (let s = 1; s < steps; s++) {
    let ang = map(s, 0, steps, 0, 180);
    let px = cx + cos(ang) * rad;
    let py = yArcCenter + sin(ang) * rad;
    pts.push([px, py]);
  }
  pts.push([cx - rad, yArcCenter]);
  return pts;
}

function getMeniscusPolygon(cx, yLiq, r, dip = 6.5, thickness = 7.5) {
  let pts = [];
  let steps = 10;
  for (let s = 0; s <= steps; s++) {
    let t = map(s, 0, steps, -1, 1);
    let px = cx + t * r;
    let py = yLiq - dip * (t * t * t * t);
    pts.push([px, py]);
  }
  for (let s = steps; s >= 0; s--) {
    let t = map(s, 0, steps, -1, 1);
    let px = cx + t * r;
    let py = yLiq + thickness - (dip + 2) * (t * t);
    pts.push([px, py]);
  }
  return pts;
}

