  brush.fill("#efe9dc", 52);
  drawPoly([[40, 40], [1160, 40], [1160, 1160], [40, 1160]]);

  brush.fill("#e8dfd0", 42);
  drawPoly([[30, 825], [1170, 825], [1170, 1170], [30, 1170]]);

  // Soft shadow cast by the wooden rack onto the laboratory bench
  brush.fillBleed(0.3, "out");
  brush.fill("#cfc5b6", 75);
  drawPoly([[50, 902], [1150, 902], [1165, 955], [35, 955]]);

  brush.noFill();

  // Subtle horizontal grain lines on the laboratory bench
  brush.set("2H", "#d4cab8", 0.45);
