function drawSpectralAuraAndCaustics() {
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.45, 0.18);

  // Soft continuous spectral wash behind/between the tubes so the 18 hues
  // bridge optically into an unbroken pastel spectrum strip
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let yTop = sp.liqY - 6;
    let yBot = 860;
    let wHalf = TUBE_STEP_X * 0.58;

    brush.fill(sp.glow, 48);
    drawPoly([
      [cx - wHalf, yTop],
      [cx + wHalf, yTop],
      [cx + wHalf, yBot],
      [cx - wHalf, yBot]
    ]);

    // Refracted pastel caustic pool on the tabletop in front of the rack
    brush.fill(sp.base, 36);
    drawPoly([
      [cx - wHalf * 0.85, 912],
      [cx + wHalf * 0.85, 912],
      [cx + wHalf * 0.95, 944],
      [cx - wHalf * 0.95, 944]
    ]);
  }
  brush.noFill();
}

