      // Portion submerged in liquid (laterally magnified & bowed by cylindrical refraction!)
      brush.wash("#f4efe2", 145);
      drawPoly([
        [cx - 18.5, sp.liqY + 2],
        [cx + 19.5, sp.liqY + 2],
        [cx + 19.5, lblY2],
