      brush.line(cx - 13, lblY1, cx + 13, lblY1);
      brush.line(cx - 13, lblY1, cx - 13, sp.liqY);
      brush.line(cx + 13, lblY1, cx + 13, sp.liqY);
      // Shifted/magnified submerged border
      brush.line(cx - 18.5, sp.liqY + 4, cx - 18.5, lblY2);
      brush.line(cx + 19.5, sp.liqY + 4, cx + 19.5, lblY2);
