// =============================================================================
// 5. LUMINOUS LAYERED WATERCOLOR LIQUIDS
// =============================================================================

function drawWatercolorLiquids() {
  brush.noStroke();

  // PASS A: Main luminous pastel body wash for all 18 tubes
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.58, 0.32);
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let poly = getTubePolygon(cx, sp.liqY, 862, TUBE_R, 1.5);
    brush.fill(sp.base, 118);
    drawPoly(poly);
  }

  // PASS B: Deeper saturated pigment glaze on the lower half & shaded right cylinder wall
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.62, 0.42);
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let yTop = sp.liqY;
    let yMid = lerp(yTop, 862, 0.42);
    let r = TUBE_R - 2;

    // Asymmetric watercolor glaze curving up the right side and pooling at the bottom
    let deepPoly = [
      [cx + 1, yTop + 6],
      [cx + r, yTop + 4],
      [cx + r, 838],
      [cx + r * 0.7, 858],
      [cx, 861],
      [cx - r * 0.7, 858],
      [cx - r, 838],
      [cx - r, yMid + 35],
      [cx - 3, yMid]
    ];
    brush.fill(sp.deep, 96);
    drawPoly(deepPoly);
  }
  brush.noFill();

  // PASS C: Sub-meniscus pigment ring, biphasic layer tint, and internal caustic lens glow
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let r = TUBE_R - 2.5;

    // Rich sub-meniscus band
    brush.wash(sp.deep, 85);
    drawPoly([
      [cx - r, sp.liqY + 2],
      [cx + r, sp.liqY + 2],
      [cx + r, sp.liqY + 24],
      [cx - r, sp.liqY + 20]
    ]);

    // If biphasic, deepen the lower immiscible phase below sp.biphasic
    if (sp.biphasic > 0) {
      let biPoly = getTubePolygon(cx, sp.biphasic, 862, TUBE_R, 2);
      brush.wash(sp.deep, 78);
      drawPoly(biPoly);
    }

    // Luminous internal caustic column on the left-center of each cylinder
    brush.wash(sp.glow, 92);
    drawPoly([
      [cx - r * 0.62, sp.liqY + 10],
      [cx - r * 0.12, sp.liqY + 10],
      [cx - r * 0.12, 836],
      [cx - r * 0.62, 836]
    ]);
  }
  brush.noWash();
}

// =============================================================================
// 6. REFRACTED LABEL TEXT & GRADUATION MARKINGS
// =============================================================================

function projectOnCylinder(cx, r, xOffset, y, isRefracted) {
  let normX = constrain(xOffset / r, -0.94, 0.94);
  if (isRefracted) {
    // Snell's law lateral magnification & curvature inside liquid cylinder
    let magX = sin(normX * 78) * r * 0.96 + 2.2;
    let curveY = y + (1 - cos(normX * 75)) * 5.5;
    return [cx + magX, curveY];
  } else {
    // Un-magnified surface curvature in air
    let surfX = sin(normX * 68) * r * 0.86;
    let curveY = y + (1 - cos(normX * 65)) * 3.0;
    return [cx + surfX, curveY];
  }
}

function drawCylinderText(str, cx, r, startXOffset, baseY, charW, charH, isRefracted, brushName, col, weight) {
  brush.set(brushName, col, weight);
  let cursorX = startXOffset;
  for (let cIdx = 0; cIdx < str.length; cIdx++) {
    let ch = str[cIdx];
    let paths = GLYPHS[ch];
    if (paths) {
      for (let p = 0; p < paths.length; p++) {
        let strokePts = paths[p];
        for (let s = 0; s < strokePts.length - 1; s++) {
          let x1 = cursorX + strokePts[s][0] * charW;
          let y1 = baseY + strokePts[s][1] * charH;
          let x2 = cursorX + strokePts[s + 1][0] * charW;
          let y2 = baseY + strokePts[s + 1][1] * charH;
          let pt1 = projectOnCylinder(cx, r, x1, y1, isRefracted);
          let pt2 = projectOnCylinder(cx, r, x2, y2, isRefracted);
          brush.line(pt1[0], pt1[1], pt2[0], pt2[1]);
        }
      }
    }
    cursorX += charW * 1.32;
  }
}

function drawRefractedLabels() {
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];

    // 1. Back-mounted labels (seen through the liquid lens, magnified & refracted!)
    if (i % 3 === 1 || i === 10) {
      // Upper line of text in air above meniscus (smaller, un-magnified)
      drawCylinderText(
        sp.label, cx, TUBE_R, -11, sp.liqY - 15,
        3.2, 5.5, false, "rotring", "#3a3542", 0.35
      );
      // Lower chemical formula submerged in liquid (magnified & laterally displaced!)
      drawCylinderText(
        sp.chem, cx, TUBE_R, -14.5, sp.liqY + 18,
        4.4, 8.0, true, "rotring", "#241f2c", 0.45
      );
      // Secondary refracted ruler lines on submerged label
      brush.set("rotring", "#4a4252", 0.32);
      let pL = projectOnCylinder(cx, TUBE_R, -15, sp.liqY + 34, true);
      let pR = projectOnCylinder(cx, TUBE_R, 14, sp.liqY + 34, true);
      brush.line(pL[0], pL[1], pR[0], pR[1]);
      let pL2 = projectOnCylinder(cx, TUBE_R, -15, sp.liqY + 42, true);
      let pR2 = projectOnCylinder(cx, TUBE_R, 9, sp.liqY + 42, true);
      brush.line(pL2[0], pL2[1], pR2[0], pR2[1]);
    }

    // 2. Front translucent laboratory paper labels on select tubes
    if (i % 4 === 2) {
      let ly = 545 + (i % 3) * 32;
      let lh = 36;
      brush.noStroke();
      brush.wash("#faf6ec", 215);
      let lPoly = [
        projectOnCylinder(cx, TUBE_R, -16, ly, false),
        projectOnCylinder(cx, TUBE_R, 16, ly, false),
        projectOnCylinder(cx, TUBE_R, 16, ly + lh, false),
        projectOnCylinder(cx, TUBE_R, -16, ly + lh, false)
      ];
      drawPoly(lPoly);
      brush.noWash();

      // Red/blue laboratory border rule on label
      brush.set("rotring", "#b85a52", 0.35);
      brush.line(lPoly[0][0], lPoly[0][1] + 3, lPoly[1][0], lPoly[1][1] + 3);
      brush.line(lPoly[3][0], lPoly[3][1] - 3, lPoly[2][0], lPoly[2][1] - 3);

      // Crisp ink text on front label
      drawCylinderText(
        sp.chem, cx, TUBE_R, -13, ly + 8,
        3.6, 6.5, false, "rotring", "#1e1b24", 0.42
      );
      drawCylinderText(
        sp.label, cx, TUBE_R, -12, ly + 20,
        3.2, 5.2, false, "rotring", "#3e3846", 0.35
      );
    }

    // 3. White/frost volumetric graduation ticks & numbers on the glass
    if (i % 2 === 0) {
      for (let yTick = 440; yTick <= 780; yTick += 20) {
        if (abs(yTick - sp.liqY) < 6) continue;
        let isMajor = (yTick % 60 === 0);
        let tickW = isMajor ? 8.5 : 4.5;
        let isSub = yTick > sp.liqY;
        // Back wall reflection of graduation tick (shifted & magnified by liquid)
        if (isSub) {
          brush.set("rotring", sp.deep, 0.35);
          let b1 = projectOnCylinder(cx, TUBE_R, -3, yTick - 2.5, true);
          let b2 = projectOnCylinder(cx, TUBE_R, -3 + tickW * 1.3, yTick - 2.5, true);
          brush.line(b1[0], b1[1], b2[0], b2[1]);
        }
        // Front etched white enamel graduation mark
        brush.set("rotring", "#ffffff", isMajor ? 0.48 : 0.34);
        let f1 = projectOnCylinder(cx, TUBE_R, 2, yTick, false);
        let f2 = projectOnCylinder(cx, TUBE_R, 2 + tickW, yTick, false);
        brush.line(f1[0], f1[1], f2[0], f2[1]);

        if (isMajor && yTick <= 740) {
          let mlNum = String(round(map(yTick, 780, 420, 5, 25)));
          drawCylinderText(
            mlNum, cx, TUBE_R, 11.5, yTick - 3,
            2.6, 4.5, false, "rotring", "#ffffff", 0.35
          );
        }
      }
    }
  }
}

// =============================================================================
// 7. CRISP PEN & DENSE INK ABSORPTION BANDS
// =============================================================================

function drawInkAbsorptionBands() {
  // ---------------------------------------------------------------------------
  // A. DARK RUBBER STOPPERS & VERTICAL CAPILLARY / SHADOW BANDS
  // ---------------------------------------------------------------------------
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let yMouth = 304 + (i % 3 - 1) * 1.5;

    if (sp.stopper) {
      let bTop = yMouth - 28;
      let bMid = yMouth;
      let bBot = yMouth + 26;
      let wTop = TUBE_R - 0.5;
      let wMid = TUBE_R - 2.5;
      let wBot = TUBE_R - 6.5;

      // Upper exposed dark rubber bung (above glass mouth)
      brush.noStroke();
      brush.wash("#17151e", 242);
      drawPoly([
        [cx - wTop, bTop],
        [cx + wTop, bTop],
        [cx + wMid, bMid],
        [cx - wMid, bMid]
      ]);

      // Lower compressed rubber bung inside the glass neck (refracted & dark)
      brush.wash("#221e2c", 220);
      drawPoly([
        [cx - wMid - 1, bMid + 1],
        [cx + wMid + 1, bMid + 1],
        [cx + wBot, bBot],
        [cx - wBot, bBot]
      ]);
      brush.noWash();

      // Dense ink cross-hatching on the rubber stopper
      brush.hatchStyle("rotring", "#0c0a10", 0.52);
      brush.hatch(2.2, 85, { rand: 0.04 });
      brush.noStroke();
      drawPoly([
        [cx - wTop, bTop],
        [cx + wTop, bTop],
        [cx + wBot, bBot],
        [cx - wBot, bBot]
      ]);
      brush.noHatch();

      // Matte highlight on left side of rubber stopper & crisp ink outline
      brush.set("cpencil", "#565064", 0.7);
      brush.line(cx - wTop * 0.62, bTop + 2, cx - wBot * 0.62, bBot - 2);
      brush.set("rotring", "#0c0a10", 0.65);
      brush.line(cx - wTop, bTop, cx + wTop, bTop);
      brush.line(cx - wTop, bTop, cx - wMid, bMid);
      brush.line(cx + wTop, bTop, cx + wMid, bMid);
      brush.line(cx - wBot, bBot, cx + wBot, bBot);

      // Vertical dark absorption band descending from the stopper through the tube!
      if (sp.rod) {
        // Crisp dark glass capillary / thermometer stem plunging down through the liquid
        let rodX = cx + 2.5;
        let rodW = 4.6;
        // Stem above rack bar
        brush.noStroke();
        brush.wash("#121018", 230);
        drawPoly([
          [rodX - rodW * 0.4, bTop - 16],
          [rodX + rodW * 0.4, bTop - 16],
          [rodX + rodW * 0.4, 832],
          [rodX - rodW * 0.4, 832]
        ]);
        // Submerged stem laterally magnified by the liquid cylinder
        brush.wash("#0e0c14", 245);
        drawPoly([
          [rodX - rodW * 0.65, sp.liqY],
          [rodX + rodW * 0.65, sp.liqY],
          [rodX + rodW * 0.65, 834],
          [rodX - rodW * 0.65, 834]
        ]);
        brush.noWash();

        // Crisp ink edges and central hairline reflection on the submerged rod
        brush.set("rotring", "#09080d", 0.65);
        brush.line(rodX - rodW * 0.65, sp.liqY, rodX - rodW * 0.65, 834);
        brush.line(rodX + rodW * 0.65, sp.liqY, rodX + rodW * 0.65, 834);
        brush.set("rotring", sp.glow, 0.35);
        brush.line(rodX - 0.6, sp.liqY + 8, rodX - 0.6, 828);
      } else {
        // Sharp vertical refractive shadow band cast down the tube by the opaque stopper
        let shX = cx + 4;
        let shW = 7.5;
        brush.noStroke();
        brush.wash("#161320", 155);
        drawPoly([
          [shX - shW * 0.5, sp.liqY],
          [shX + shW * 0.5, sp.liqY],
          [shX + shW * 0.5, 845],
          [shX - shW * 0.5, 845]
        ]);
        brush.noWash();

        brush.hatchStyle("rotring", "#14111c", 0.48);
        brush.hatch(2.0, 90, { rand: 0.03 });
        brush.noStroke();
        drawPoly([
          [shX - shW * 0.5, sp.liqY],
          [shX + shW * 0.5, sp.liqY],
          [shX + shW * 0.5, 845],
          [shX - shW * 0.5, 845]
        ]);
        brush.noHatch();
      }
    }
  }

  // ---------------------------------------------------------------------------
  // B. SHARP CONCAVE MENISCI & BIPHASIC INTERFACES
  // ---------------------------------------------------------------------------
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let r = TUBE_R - 1.5;

    // Primary surface meniscus
    let mPoly = getMeniscusPolygon(cx, sp.liqY, r, 6.8, 8.2);
    brush.noStroke();
    brush.wash("#14111c", 232);
    drawPoly(mPoly);
    brush.noWash();

    // Fine dense horizontal/curved ink hatching inside meniscus
    brush.hatchStyle("rotring", "#0c0a12", 0.55);
    brush.hatch(1.6, 4, { rand: 0.03 });
    brush.noStroke();
    drawPoly(mPoly);
    brush.noHatch();

    // Crisp pen upper & lower meniscus rims (total internal reflection)
    brush.set("rotring", "#0a0810", 0.72);
    brush.line(cx - r, sp.liqY - 6.5, cx - r * 0.45, sp.liqY - 0.5);
    brush.line(cx - r * 0.45, sp.liqY - 0.5, cx + r * 0.45, sp.liqY - 0.5);
    brush.line(cx + r * 0.45, sp.liqY - 0.5, cx + r, sp.liqY - 6.5);

    brush.set("rotring", "#0a0810", 0.62);
    brush.line(cx - r, sp.liqY + 1.5, cx - r * 0.45, sp.liqY + 7.8);
    brush.line(cx - r * 0.45, sp.liqY + 7.8, cx + r * 0.45, sp.liqY + 7.8);
    brush.line(cx + r * 0.45, sp.liqY + 7.8, cx + r, sp.liqY + 1.5);

    // Bright specular reflection belly inside the concave meniscus lens
    brush.set("rotring", "#ffffff", 0.55);
    brush.line(cx - r * 0.55, sp.liqY + 3.2, cx + r * 0.25, sp.liqY + 3.6);

    // Secondary biphasic meniscus (liquid-liquid phase boundary)
    if (sp.biphasic > 0) {
      let bPoly = getMeniscusPolygon(cx, sp.biphasic, r, 4.5, 5.8);
      brush.noStroke();
      brush.wash("#161320", 215);
      drawPoly(bPoly);
      brush.noWash();

      brush.set("rotring", "#0c0a12", 0.6);
      brush.line(cx - r, sp.biphasic - 4.2, cx, sp.biphasic);
      brush.line(cx, sp.biphasic, cx + r, sp.biphasic - 4.2);
      brush.line(cx - r, sp.biphasic + 1.2, cx, sp.biphasic + 5.5);
      brush.line(cx, sp.biphasic + 5.5, cx + r, sp.biphasic + 1.2);

      brush.set("rotring", sp.glow, 0.45);
      brush.line(cx - r * 0.5, sp.biphasic + 2.4, cx + r * 0.3, sp.biphasic + 2.4);
    }
  }

  // ---------------------------------------------------------------------------
  // C. DENSE INK SEDIMENT & CRYSTALLINE PRECIPITATE BANDS AT TUBE BOTTOMS
  // ---------------------------------------------------------------------------
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let r = TUBE_R - 2;
    // Varying sediment thickness across the sequence
    let sedTop = 816 + ((i * 7) % 19);
    let sedPoly = getTubePolygon(cx, sedTop, 861, TUBE_R, 2);

    // Opaque dark ink sediment bed
    brush.noStroke();
    brush.wash(sp.sediment, 238);
    drawPoly(sedPoly);
    brush.noWash();

    // Dense ink cross-hatching in the sediment
    brush.hatchStyle("rotring", "#0c0a10", 0.58);
    brush.hatch(1.8, 12, { rand: 0.06 });
    brush.noStroke();
    drawPoly(sedPoly);
    brush.noHatch();

    // Stratified horizontal precipitate rings just above the main sediment bed
    let numRings = 1 + (i % 3);
    for (let k = 1; k <= numRings; k++) {
      let ry = sedTop - k * 6.5;
      brush.set("rotring", "#120f18", 0.65 - k * 0.12);
      brush.line(cx - r + 1, ry - 1.5, cx, ry + 1.2);
      brush.line(cx, ry + 1.2, cx + r - 1, ry - 1.5);
    }

    // Fine speckled crystalline particles suspended above the sediment
    brush.set("spray", "#14111c", 0.45);
    brush.line(cx - r * 0.6, sedTop - 4, cx + r * 0.6, sedTop - 4);
  }

  // ---------------------------------------------------------------------------
  // D. VERTICAL DARK GLASS REFRACTION EDGES & INTER-TUBE SLIT LINES
  //    (Fine Fraunhofer Absorption Lines Across the Entire Spectrum)
  // ---------------------------------------------------------------------------
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let yMouth = 304 + (i % 3 - 1) * 1.5;

    // Total internal reflection dark bands along left & right walls of each cylinder
    let edgeWLeft = 2.8 + (i % 3) * 0.7;
    let edgeWRight = 3.4 + ((i + 1) % 3) * 0.8;

    brush.noStroke();
    brush.wash("#16131f", 205);
    drawPoly([
      [cx - TUBE_R, sp.liqY],
      [cx - TUBE_R + edgeWLeft, sp.liqY],
      [cx - TUBE_R + edgeWLeft, 845],
      [cx - TUBE_R, 845]
    ]);
    brush.wash("#120f1a", 225);
    drawPoly([
      [cx + TUBE_R - edgeWRight, sp.liqY],
      [cx + TUBE_R, sp.liqY],
      [cx + TUBE_R, 845],
      [cx + TUBE_R - edgeWRight, 845]
    ]);
    brush.noWash();

    // Crisp vertical pen lines defining the cylinder walls & internal reflection bands
    brush.set("rotring", "#0d0b12", 0.68);
    brush.line(cx - TUBE_R, yMouth, cx - TUBE_R, 842);
    brush.line(cx + TUBE_R, yMouth, cx + TUBE_R, 842);

    brush.set("rotring", "#1c1826", 0.45);
    brush.line(cx - TUBE_R + edgeWLeft, sp.liqY, cx - TUBE_R + edgeWLeft, 840);
    brush.line(cx + TUBE_R - edgeWRight, sp.liqY, cx + TUBE_R - edgeWRight, 840);

    // Narrow 9px inter-tube gaps: some carry crisp vertical shadow hatching
    // reading as fine secondary absorption lines across the spectrum
    if (i < NUM_TUBES - 1) {
      let gapLeft = cx + TUBE_R;
      let gapRight = tubeX(i + 1) - TUBE_R;
      let gapMid = (gapLeft + gapRight) * 0.5;

      // Subtle vertical shadow wash in the narrow slot between cylinders
      let slotAlpha = (i % 2 === 0) ? 135 : 75;
      brush.noStroke();
      brush.wash("#1c1826", slotAlpha);
      drawPoly([
        [gapLeft, 415],
        [gapRight, 415],
        [gapRight, 855],
        [gapLeft, 855]
      ]);
      brush.noWash();

      // Fine vertical ink line in select inter-tube gaps (like fine spectral lines)
      if (i % 2 === 0 || i === 5 || i === 7 || i === 12) {
        brush.set("rotring", "#14111c", 0.55);
        brush.line(gapMid, 415, gapMid, 855);
      }
    }
  }

  // ---------------------------------------------------------------------------
  // E. VERTICAL RACK POSTS & THEIR SHARP CAST SHADOWS (Major Absorption Lines)
  // ---------------------------------------------------------------------------
  for (let p = 0; p < RACK_POSTS.length; p++) {
    let post = RACK_POSTS[p];
    let px = post.x;
    let pw = post.w;
    let sw = post.shadowW;

    // 1. Sharp vertical cast shadow slicing right across the adjacent glowing tube!
    brush.noStroke();
    brush.wash("#110e18", 228);
    drawPoly([
      [px + pw * 0.5, 415],
      [px + pw * 0.5 + sw, 415],
      [px + pw * 0.5 + sw, 858],
      [px + pw * 0.5, 858]
    ]);
    brush.noWash();

    // Dense vertical pen hatching inside the cast shadow band
    brush.hatchStyle("rotring", "#09070d", 0.58);
    brush.hatch(1.7, 90, { rand: 0.02 });
    brush.noStroke();
    drawPoly([
      [px + pw * 0.5, 415],
      [px + pw * 0.5 + sw, 415],
      [px + pw * 0.5 + sw, 858],
      [px + pw * 0.5, 858]
    ]);
    brush.noHatch();

    // 2. The physical vertical rack post / tie-rod itself
    if (post.type === "wood") {
      // Darkened vertical wooden rack pillar in deep ink-stained oak
      brush.noStroke();
      brush.wash("#2a2224", 242);
      drawPoly([
        [px - pw * 0.5, 414],
        [px + pw * 0.5, 414],
        [px + pw * 0.5, 860],
        [px - pw * 0.5, 860]
      ]);
      brush.noWash();

      // Warm wood highlight edge on the left of the post
      brush.set("cpencil", "#8c7662", 0.65);
      brush.line(px - pw * 0.35, 416, px - pw * 0.35, 858);

      // Dense ink shading on the right half of the post
      brush.hatchStyle("rotring", "#0d0b12", 0.55);
      brush.hatch(1.6, 88, { rand: 0.03 });
      brush.noStroke();
      drawPoly([
        [px - 1, 414],
        [px + pw * 0.5, 414],
        [px + pw * 0.5, 860],
        [px - 1, 860]
      ]);
      brush.noHatch();
    } else {
      // Narrow blackened-brass doublet tie-rods (Sodium D1 & D2 lines in the yellow zone!)
      brush.noStroke();
      brush.wash("#121018", 248);
      drawPoly([
        [px - pw * 0.5, 414],
        [px + pw * 0.5, 414],
        [px + pw * 0.5, 860],
        [px - pw * 0.5, 860]
      ]);
      brush.noWash();

      // Faint metallic glint line on the tie-rod
      brush.set("rotring", "#7a7268", 0.38);
      brush.line(px - pw * 0.25, 416, px - pw * 0.25, 858);
    }

    // Razor-sharp ink vertical borders for both post and shadow band
    brush.set("rotring", "#08060c", 0.72);
    brush.line(px - pw * 0.5, 414, px - pw * 0.5, 860);
    brush.line(px + pw * 0.5, 414, px + pw * 0.5, 860);
    brush.line(px + pw * 0.5 + sw, 414, px + pw * 0.5 + sw, 860);

    // Shadow of the post continuing onto the tabletop caustic band below the rack
    brush.noStroke();
    brush.wash("#8a8076", 110);
    drawPoly([
      [px - pw * 0.5, 912],
      [px + pw * 0.5 + sw, 912],
      [px + pw * 0.5 + sw + 4, 946],
      [px - pw * 0.5 + 2, 946]
    ]);
    brush.noWash();
  }
}

// =============================================================================
// 8. FRONT WOODEN RACK ARCHITECTURE & CAST SHADOWS
// =============================================================================

function drawRackFrontStructure() {
  brush.noStroke();

  // Horizontal shadow cast by the upper rack bar across all 18 tubes just below y=415
  brush.wash("#1c1824", 115);
  drawPoly([
    [RACK_LEFT + 18, 415],
    [RACK_RIGHT - 18, 415],
    [RACK_RIGHT - 18, 427],
    [RACK_LEFT + 18, 427]
  ]);

  // 1. Upper Rack Shelf Front Face (y = 386 to 415)
  // Soft warm bleached laboratory oak watercolor + wash
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.5, 0.35);
  brush.fill("#d5c3ad", 195);
  drawPoly([
    [RACK_LEFT, 386],
    [RACK_RIGHT, 386],
    [RACK_RIGHT, 415],
    [RACK_LEFT, 415]
  ]);
  brush.noFill();

  // Lower shaded underside lip of upper rack bar
  brush.wash("#a8927a", 160);
  drawPoly([
    [RACK_LEFT, 408],
    [RACK_RIGHT, 408],
    [RACK_RIGHT, 415],
    [RACK_LEFT, 415]
  ]);

  // 2. Lower Rack Base Front Face (y = 860 to 908) with scalloped viewing arches
  // so the rounded bottoms & dark sediments of the tubes nestle visibly in their sockets
  let basePts = [];
  basePts.push([RACK_LEFT, 856]);
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    basePts.push([cx - TUBE_R + 1, 856]);
    basePts.push([cx - TUBE_R * 0.65, 865]);
    basePts.push([cx, 868]);
    basePts.push([cx + TUBE_R * 0.65, 865]);
    basePts.push([cx + TUBE_R - 1, 856]);
  }
  basePts.push([RACK_RIGHT, 856]);
  basePts.push([RACK_RIGHT, 908]);
  basePts.push([RACK_LEFT, 908]);

  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.52, 0.38);
  brush.fill("#cdb9a0", 215);
  drawPoly(basePts);
  brush.noFill();

  // Shaded lower bevel of base
  brush.wash("#9c866e", 170);
  drawPoly([
    [RACK_LEFT, 896],
    [RACK_RIGHT, 896],
    [RACK_RIGHT, 908],
    [RACK_LEFT, 908]
  ]);

  // 3. Sturdy Left and Right End Pillars of the Wooden Rack
  let endPillars = [
    [RACK_LEFT, RACK_LEFT + 24],
    [RACK_RIGHT - 24, RACK_RIGHT]
  ];
  for (let e = 0; e < endPillars.length; e++) {
    let x1 = endPillars[e][0];
    let x2 = endPillars[e][1];
    brush.wash("#c8b39a", 235);
    drawPoly([[x1, 358], [x2, 358], [x2, 912], [x1, 912]]);

    // Side shadow on inner/right face of end pillar
    brush.wash("#87715c", 185);
    drawPoly([[x2 - 6, 358], [x2, 358], [x2, 912], [x2 - 6, 912]]);

    // Dovetail / mortise-and-tenon joinery joints in dark wood
    let jointsY = [386, 402, 864, 882];
    for (let j = 0; j < jointsY.length; j++) {
      let jy = jointsY[j];
      brush.wash("#7d6752", 210);
      drawPoly([[x1 + 3, jy], [x2 - 3, jy], [x2 - 3, jy + 9], [x1 + 3, jy + 9]]);
    }
  }
  brush.noWash();

  // 4. Fine Wood Grain Hatching & Crisp Architectural Outlines on the Rack
  brush.hatchStyle("2B", "#8f7963", 0.45);
  brush.hatch(3.5, 1.5, { rand: 0.08 });
  brush.noStroke();
  drawPoly([[RACK_LEFT, 386], [RACK_RIGHT, 386], [RACK_RIGHT, 415], [RACK_LEFT, 415]]);
  drawPoly([[RACK_LEFT, 868], [RACK_RIGHT, 868], [RACK_RIGHT, 908], [RACK_LEFT, 908]]);
  brush.noHatch();

  // Brass manufacturer serial plaque on the lower right of the wooden rack
  brush.noStroke();
  brush.wash("#b89e68", 215);
  drawPoly([[1036, 875], [1102, 875], [1102, 893], [1036, 893]]);
  brush.noWash();
  brush.set("rotring", "#3a2e1e", 0.45);
  brush.rect(1036, 875, 66, 18, "corner");
  brush.line(1041, 884, 1097, 884);

  // Crisp pen & graphite structural lines for the rack
  brush.set("rotring", "#2b231d", 0.62);
  brush.line(RACK_LEFT, 386, RACK_RIGHT, 386);
  brush.line(RACK_LEFT, 415, RACK_RIGHT, 415);
  brush.line(RACK_LEFT, 908, RACK_RIGHT, 908);

  for (let e = 0; e < endPillars.length; e++) {
    let x1 = endPillars[e][0];
    let x2 = endPillars[e][1];
    brush.set("rotring", "#2b231d", 0.65);
    brush.line(x1, 358, x2, 358);
    brush.line(x1, 358, x1, 912);
    brush.line(x2, 358, x2, 912);
    brush.line(x1, 912, x2, 912);
  }
}

// =============================================================================
// 9. HYPERREAL FRONT GLASS HIGHLIGHTS, RIMS & CONDENSATION BEADS
// =============================================================================

function drawSingleDroplet(x, y, r, tintCol) {
  // 1. Dark upper-left internal refraction crescent (convex water lens inverts light)
  brush.set("rotring", "#1a1724", map(r, 1.2, 6.5, 0.32, 0.55));
  brush.arc(x, y, r, 195, 335);

  // 2. Luminous lower-right caustic belly inside the droplet
  if (r > 2.0) {
    brush.noStroke();
    brush.wash(tintCol, 155);
    drawPoly([
      [x - r * 0.65, y],
      [x + r * 0.75, y - r * 0.2],
      [x + r * 0.85, y + r * 0.65],
      [x, y + r * 0.9],
      [x - r * 0.65, y + r * 0.55]
    ]);
    brush.noWash();
  }

  // 3. Crisp dark cast shadow crescent immediately beneath the droplet
  brush.set("rotring", "#161320", map(r, 1.2, 6.5, 0.3, 0.52));
  brush.arc(x + 0.3, y + r * 0.25, r * 0.95, 15, 155);

  // 4. Pinpoint pure white primary specular glint (upper-left) & lower caustic spark
  brush.set("rotring", "#ffffff", map(r, 1.2, 6.5, 0.48, 0.85));
  brush.line(x - r * 0.38, y - r * 0.35, x - r * 0.12, y - r * 0.38);
  if (r > 2.8) {
    brush.set("rotring", "#ffffff", 0.45);
    brush.line(x + r * 0.22, y + r * 0.52, x + r * 0.45, y + r * 0.42);
  }
}

function drawHyperrealGlassAndCondensation() {
  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let yMouth = 304 + (i % 3 - 1) * 1.5;

    // -------------------------------------------------------------------------
    // A. DOUBLE-WALLED GLASS THICKNESS & ROUNDED BOTTOM LENS
    // -------------------------------------------------------------------------
    let innerWallL = cx - TUBE_R + 3.2;
    let innerWallR = cx + TUBE_R - 3.2;

    // Inner glass wall refractive white hairlines
    brush.set("2H", "#ffffff", 0.45);
    brush.line(innerWallL, yMouth + 4, innerWallL, 385);
    brush.line(innerWallL, 416, innerWallL, 838);
    brush.line(innerWallR, yMouth + 4, innerWallR, 385);
    brush.line(innerWallR, 416, innerWallR, 838);

    // Thick glass hemispherical base refraction at the bottom of the tube (y = 838..862)
    brush.set("rotring", "#120f1a", 0.68);
    brush.arc(cx, 838, TUBE_R, 12, 168);
    brush.set("rotring", "#ffffff", 0.62);
    brush.arc(cx, 838, TUBE_R - 3.2, 22, 158);
    brush.set("rotring", sp.glow, 0.5);
    brush.arc(cx, 838, TUBE_R - 5.5, 35, 145);

    // -------------------------------------------------------------------------
    // B. FLARED GLASS TOP RIM (ROLLED LIP)
    // -------------------------------------------------------------------------
    let rimW = TUBE_R + 3.2;
    // Dark ink undercut shadow beneath the rolled glass lip
    brush.set("rotring", "#14111c", 0.65);
    brush.line(cx - rimW, yMouth + 2.8, cx + rimW, yMouth + 2.8);
    brush.line(cx - rimW, yMouth - 2.2, cx - rimW, yMouth + 2.8);
    brush.line(cx + rimW, yMouth - 2.2, cx + rimW, yMouth + 2.8);

    if (!sp.stopper) {
      brush.set("rotring", "#3a3544", 0.48);
      brush.line(cx - rimW, yMouth - 2.2, cx + rimW, yMouth - 2.2);
    }

    // Brilliant white specular catchlight across the rolled glass lip
    brush.set("rotring", "#ffffff", 0.78);
    brush.line(cx - rimW + 2, yMouth - 0.5, cx - 2, yMouth - 0.5);
    brush.line(cx + 5, yMouth - 0.5, cx + rimW - 3, yMouth - 0.5);

    // -------------------------------------------------------------------------
    // C. PRIMARY & SECONDARY VERTICAL SPECULAR GLASS HIGHLIGHT RIBBONS
    // -------------------------------------------------------------------------
    let hlX1 = cx - TUBE_R * 0.52;
    let hlW1 = 4.4;

    brush.noStroke();
    // Upper highlight above rack bar (yMouth to 385)
    brush.wash("#ffffff", 145);
    drawPoly([
      [hlX1, yMouth + 4],
      [hlX1 + hlW1, yMouth + 4],
      [hlX1 + hlW1, 385],
      [hlX1, 385]
    ]);
    // Highlight between rack bar and meniscus (418 to sp.liqY - 3)
    brush.wash("#ffffff", 135);
    drawPoly([
      [hlX1, 418],
      [hlX1 + hlW1, 418],
      [hlX1 + hlW1, sp.liqY - 3],
      [hlX1, sp.liqY - 3]
    ]);
    // Main highlight over the liquid column (shifts 1px at meniscus due to index of refraction!)
    brush.wash("#ffffff", 160);
    drawPoly([
      [hlX1 - 0.8, sp.liqY + 9],
      [hlX1 + hlW1 - 0.5, sp.liqY + 9],
      [hlX1 + hlW1 - 0.5, 825],
      [hlX1 - 0.8, 825]
    ]);
    brush.noWash();

    // Razor-sharp white pen edge along the specular highlight ribbon
    brush.set("rotring", "#ffffff", 0.65);
    brush.line(hlX1, yMouth + 4, hlX1, 385);
    brush.line(hlX1, 418, hlX1, sp.liqY - 3);
    brush.line(hlX1 - 0.8, sp.liqY + 9, hlX1 - 0.8, 825);

    // Secondary thin rim reflection near the right wall
    let hlX2 = cx + TUBE_R * 0.66;
    brush.set("rotring", "#ffffff", 0.45);
    brush.line(hlX2, yMouth + 6, hlX2, 385);
    brush.line(hlX2, sp.liqY + 12, hlX2, 818);

    // -------------------------------------------------------------------------
    // D. HYPERREAL CONDENSATION MIST, WATER BEADS & RIVULET TRACKS
    // -------------------------------------------------------------------------
    // 1. Fine micro-condensation mist on the chilled glass
    if (sp.mist > 0.6) {
      brush.set("spray", "#ffffff", 0.38);
      brush.line(cx - TUBE_R * 0.4, sp.liqY + 15, cx + TUBE_R * 0.35, sp.liqY + 140);
      brush.set("spray", sp.glow, 0.35);
      brush.line(cx - TUBE_R * 0.3, sp.liqY + 80, cx + TUBE_R * 0.4, 720);
    }

    // 2. Vertical rivulet track on select tubes (where a heavy bead slid down)
    if (i === 1 || i === 5 || i === 10 || i === 15) {
      let rx = cx + random(-6, 7);
      let ry1 = sp.liqY + 35;
      let ry2 = ry1 + random(65, 115);
      brush.set("rotring", "#241f30", 0.32);
      brush.line(rx - 1.2, ry1, rx - 0.8, ry2);
      brush.set("rotring", "#ffffff", 0.42);
      brush.line(rx + 0.5, ry1, rx + 0.8, ry2);
      // Heavy teardrop bead at the bottom of the rivulet
      drawSingleDroplet(rx, ry2 + 3.5, 4.8, sp.glow);
    }

    // 3. Individual jewel-like condensation beads clinging to the glass cylinder
    let numDrops = floor(map(sp.mist, 0.5, 1.0, 9, 22));
    for (let d = 0; d < numDrops; d++) {
      let dx = cx + random(-TUBE_R * 0.76, TUBE_R * 0.72);
      // Avoid placing beads directly inside a solid wooden rack post
      let blocked = false;
      for (let p = 0; p < RACK_POSTS.length; p++) {
        if (abs(dx - RACK_POSTS[p].x) < RACK_POSTS[p].w * 0.6 + 3) blocked = true;
      }
      if (blocked) continue;

      // Most beads cluster on the cool liquid zone (435..770), a few above meniscus (330..380)
      let dy = (random() < 0.84)
        ? random(432, 775)
        : random(328, 380);

      // Power-law droplet radius: many micro-beads, several medium/large lenses
      let u = random();
      let dr = (u < 0.62)
        ? random(1.3, 2.3)
        : (u < 0.90 ? random(2.4, 3.8) : random(3.9, 5.6));

      drawSingleDroplet(dx, dy, dr, sp.glow);
    }
  }
}

