function drawSpectroscopicNotations() {
  // Subtle graphite wavelength calibration scale above the test-tube rack (y = 228)
  // linking the physical laboratory rack and its dark bands to an absorption spectrum
  let yScale = 232;
  brush.set("2H", "#aba294", 0.38);
  brush.line(TUBE_START_X, yScale, tubeX(NUM_TUBES - 1), yScale);

  for (let i = 0; i < NUM_TUBES; i++) {
    let cx = tubeX(i);
    let sp = SPECTRUM[i];
    let tickH = (i % 3 === 0) ? 7 : 3.5;
    brush.set("2H", "#9e9587", 0.38);
    brush.line(cx, yScale - tickH, cx, yScale + tickH);

    // Faint vertical hairline dropping toward the tube mouth on Fraunhofer reference tubes
    if (sp.stopper || i === 0 || i === 5 || i === 10 || i === 17) {
      brush.set("2H", "#c4bbb0", 0.3);
      brush.line(cx, yScale + 9, cx, 266);
      drawCylinderText(
        sp.label, cx, 60, -9, yScale - 16,
        2.8, 5.0, false, "2H", "#8c8376", 0.34
      );
    }
  }

  // Faint Fraunhofer absorption line markers above the vertical rack posts
  for (let p = 0; p < RACK_POSTS.length; p++) {
    let post = RACK_POSTS[p];
    brush.set("2H", "#7d7468", 0.42);
    brush.line(post.x, yScale - 10, post.x, yScale + 10);
    drawCylinderText(
      post.label, post.x, 40, -2.5, yScale - 20,
      3.2, 5.5, false, "2H", "#6e665b", 0.38
    );
  }

  // Subtle lower plate register line & specimen plate number on the cotton rag margin
  brush.set("2H", "#b8afa0", 0.35);
  brush.line(RACK_LEFT, 988, RACK_RIGHT, 988);
  drawCylinderText(
    "FIG. 18 - CONTINUOUS SPECTRUM & ABSORPTION SERIES",
    365, 500, 0, 1002, 3.0, 5.0, false, "2H", "#968d80", 0.34
  );
}

