// 1. TEAL VOID & FLOATING AMBIENT SHADOW
// ============================================================================
function drawTealVoidAndShadow() {
  background(PALETTE.tealVoid);

  // Subtle atmospheric paper variation in the flat teal void
  brush.noStroke();
  brush.wash(PALETTE.tealLight, 38);
  brush.circle(600, 520, 490, 0.08);
  brush. noWash();

  // Soft ambient shadow floating below the goat's beard
  const sx = 555;
  const sy = 1108;

  brush.noStroke();
  for (let i = 0; i < 5; i++) {
    const t = i / 4;
    const rx = lerp(240, 68, t);
    const ry = lerp(38, 12, t);
    const col = i < 2 ? PALETTE.tealDeep : PALETTE.shadowVoid;
    const alpha = lerp(42, 85, t);

    brush.fill(col, alpha);
    brush.fillBleed(0.42, "out");
    brush.fillTexture(0.45, 0.2);
    drawEllipsePoly(sx, sy, rx, ry, 24, 0.15);
  }
  brush.noFill();

  // Delicate charcoal/graphite shadow grain in the core of the floating shadow
  brush.hatchStyle("2B", "#0a1f24", 0.45);
  brush.hatch(7, 4, { rand: 0.12, gradient: 0.5 });
  brush.noStroke();
  drawEllipsePoly(sx, sy, 145, 20, 20, 0.1);
  brush.noHatch();
}

function drawEllipsePoly(cx, cy, rx, ry, steps = 20, curv = 0.2) {
  brush.beginShape(curv);
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * 360;
    brush.vertex(cx + cos(a) * rx, cy + sin(a) * ry);
  }
  brush.endShape(true);
}

function drawTriShape(v0, v1, v2, curv = 0) {
  brush.beginShape(curv);
  brush.vertex(v0.x, v0.y);
  brush.vertex(v1.x, v1.y);
  brush.vertex(v2.x, v2.y);
  brush.endShape(true);
}

// ============================================================================
// 2. 3D LOW-POLY GOAT HEAD MESH CONSTRUCTION & SUBDIVISION
// ============================================================================
function buildGoatHeadMesh() {
  const vertices = [];
  const triangles = [];

  function addV(x, y, z, region) {
    const id = vertices.length;
    vertices.push({ x, y, z, region });
    return id;
  }

  function addTri(a, b, c, regionOverride = null) {
    const vA = vertices[a];
    const vB = vertices[b];
    const vC = vertices[c];
    const region = regionOverride || vA.region || "head";
    // Enforce consistent screen-space winding
    const cross2D = (vB.x - vA.x) * (vC.y - vA.y) - (vB.y - vA.y) * (vC.x - vA.x);
    if (cross2D < 0) {
      triangles.push({ a, b: c, c: b, region, level: 0 });
    } else if (Math.abs(cross2D) > 0.5) {
      triangles.push({ a, b, c, region, level: 0 });
    }
  }

  // Helper to triangulate between two ordered vertex rows cleanly
  function connectRows(rowA, rowB, regionOverride = null) {
    let i = 0;
    let j = 0;
    const nA = rowA.length;
    const nB = rowB.length;
    while (i < nA - 1 || j < nB - 1) {
      if (i === nA - 1) {
        addTri(rowA[i], rowB[j], rowB[j + 1], regionOverride);
        j++;
      } else if (j === nB - 1) {
        addTri(rowA[i], rowB[j], rowA[i + 1], regionOverride);
        i++;
      } else {
        const pA1 = vertices[rowA[i]];
        const pA2 = vertices[rowA[i + 1]];
        const pB1 = vertices[rowB[j]];
        const pB2 = vertices[rowB[j + 1]];
        const d1 = Math.hypot(pA1.x - pB2.x, pA1.y - pB2.y);
        const d2 = Math.hypot(pA2.x - pB1.x, pA2.y - pB1.y);
        if (d1 < d2) {
          addTri(rowA[i], rowB[j], rowB[j + 1], regionOverride);
          j++;
        } else {
          addTri(rowA[i], rowB[j], rowA[i + 1], regionOverride);
          i++;
        }
      }
    }
  }

  // Helper to connect closed rings (for horns and ears)
  function connectClosedRings(ringA, ringB, regionOverride = null) {
    const n = ringA.length;
    for (let i = 0; i < n; i++) {
      const ni = (i + 1) % n;
      const a0 = ringA[i], a1 = ringA[ni];
      const b0 = ringB[i], b1 = ringB[ni];
      addTri(a0, b0, b1, regionOverride);
      addTri(a0, b1, a1, regionOverride);
    }
  }

  // --- MAIN CRANIUM, FACE, MUZZLE, JAW, NECK & BEARD ROWS ---
