    addV(768, 180, 22, "horn_L"),
    addV(832, 184, 0, "horn_L"),
    addV(854, 160, -52, "horn_L")
  ];
  const hL4 = [
    addV(826, 116, -50, "horn_L"),
    addV(816, 136, -6, "horn_L"),
    addV(864, 136, -20, "horn_L"),
    addV(882, 118, -66, "horn_L")
  ];
  const hLTip = addV(898, 88, -88, "horn_L");

  const hornLRings = [hL0, hL1, hL2, hL3, hL4];
  for (let k = 0; k < hornLRings.length - 1; k++) {
    connectClosedRings(hornLRings[k], hornLRings[k + 1], "horn_L");
  }
  for (let i = 0; i < 4; i++) {
    addTri(hL4[i], hLTip, hL4[(i + 1) % 4], "horn_L");
  }

  // --- FAR EAR (Goat's right ear, viewer's left) ---
  const eR0 = [r2[0], r3[0], r4[0]];
  const eR1 = [
    addV(314, 458, -52, "ear_outer"),
    addV(320, 500, -76, "ear_inner"),
    addV(328, 548, -42, "ear_outer")
  ];
  const eR2 = [
    addV(244, 472, -58, "ear_outer"),
    addV(252, 504, -78, "ear_inner"),
    addV(264, 538, -48, "ear_outer")
  ];
  const eRTip = [addV(180, 502, -64, "ear_outer")];
  connectRows(eR0, eR1);
  connectRows(eR1, eR2);
  connectRows(eR2, eRTip);

  // --- NEAR EAR (Goat's left ear, viewer's right) ---
  const eL0 = [r2[7], r3[8], r4[8]];
  const eL1 = [
    addV(886, 466, -22, "ear_outer"),
    addV(880, 515, -58, "ear_inner"),
    addV(874, 568, -12, "ear_outer")
  ];
  const eL2 = [
    addV(964, 480, -18, "ear_outer"),
    addV(956, 518, -46, "ear_inner"),
    addV(948, 554, -8, "ear_outer")
  ];
  const eLTip = [addV(1034, 518, -14, "ear_outer")];
  connectRows(eL0, eL1);
  connectRows(eL1, eL2);
  connectRows(eL2, eLTip);

  return { vertices, triangles };
}

// Adaptive edge-midpoint subdivision centered on the hyperreal left eye
function subdivideAroundEye(mesh, fx, fy, radius, jitterAmt, passLevel) {
  const { vertices, triangles } = mesh;
  const edgeMap = new Map();
  const newTriangles = [];

  function getMidVertex(i1, i2) {
    const a = Math.min(i1, i2);
    const b = Math.max(i1, i2);
    const key = a + "_" + b;
    if (edgeMap.has(key)) return edgeMap.get(key);

    const v1 = vertices[i1];
    const v2 = vertices[i2];
    const mx = 0.5 * (v1.x + v2.x);
    const my = 0.5 * (v1.y + v2.y);
    const d = Math.hypot(mx - fx, my - fy);

    if (d > radius) {
      edgeMap.set(key, -1);
      return -1;
    }

    const len = Math.hypot(v2.x - v1.x, v2.y - v1.y);
    const ang = noise(mx * 0.025, my * 0.025, passLevel * 3) * 360;
    const jx = cos(ang) * len * jitterAmt;
    const jy = sin(ang) * len * jitterAmt;

    // Sculpted 3D orbital dome relief + facet normal variation
    const domeBoost = Math.max(0, 1 - d / radius) * 5.5;
    const jz = (noise(mx * 0.03, my * 0.03, passLevel * 7) - 0.48) * len * 0.42 + domeBoost;

    const id = vertices.length;
    vertices.push({
      x: mx + jx,
      y: my + jy,
      z: 0.5 * (v1.z + v2.z) + jz,
      region: v1.region
    });
    edgeMap.set(key, id);
    return id;
  }

  function pushTri(a, b, c, region, level) {
    const vA = vertices[a], vB = vertices[b], vC = vertices[c];
    const cross2D = (vB.x - vA.x) * (vC.y - vA.y) - (vB.y - vA.y) * (vC.x - vA.x);
    if (cross2D < 0) {
      newTriangles.push({ a, b: c, c: b, region, level });
    } else if (Math.abs(cross2D) > 0.2) {
      newTriangles.push({ a, b, c, region, level });
    }
  }

  for (let t of triangles) {
    const mAB = getMidVertex(t.a, t.b);
    const mBC = getMidVertex(t.b, t.c);
    const mCA = getMidVertex(t.c, t.a);

    const sAB = mAB !== -1 ? 1 : 0;
    const sBC = mBC !== -1 ? 1 : 0;
    const sCA = mCA !== -1 ? 1 : 0;
    const count = sAB + sBC + sCA;
    const nextLv = Math.max(t.level, passLevel);

    if (count === 0) {
      newTriangles.push(t);
    } else if (count === 3) {
      pushTri(t.a, mAB, mCA, t.region, nextLv);
      pushTri(mAB, t.b, mBC, t.region, nextLv);
      pushTri(mCA, mBC, t.c, t.region, nextLv);
      pushTri(mAB, mBC, mCA, t.region, nextLv);
    } else if (count === 1) {
      let A, B, C, M;
      if (sAB) { A = t.a; B = t.b; C = t.c; M = mAB; }
      else if (sBC) { A = t.b; B = t.c; C = t.a; M = mBC; }
      else { A = t.c; B = t.a; C = t.b; M = mCA; }
      pushTri(A, M, C, t.region, nextLv);
      pushTri(M, B, C, t.region, nextLv);
    } else if (count === 2) {
      // Rotate so the unsplit edge is C -> A
      let A, B, C, M1, M2;
      if (!sCA) { A = t.a; B = t.b; C = t.c; M1 = mAB; M2 = mBC; }
      else if (!sAB) { A = t.b; B = t.c; C = t.a; M1 = mBC; M2 = mCA; }
      else { A = t.c; B = t.a; C = t.b; M1 = mCA; M2 = mAB; }

      pushTri(M1, B, M2, t.region, nextLv);
      const dA = Math.hypot(vertices[A].x - vertices[M2].x, vertices[A].y - vertices[M2].y);
      const dC = Math.hypot(vertices[C].x - vertices[M1].x, vertices[C].y - vertices[M1].y);
      if (dA < dC) {
        pushTri(A, M1, M2, t.region, nextLv);
        pushTri(A, M2, C, t.region, nextLv);
      } else {
        pushTri(A, M1, C, t.region, nextLv);
        pushTri(M1, M2, C, t.region, nextLv);
      }
    }
  }

  mesh.triangles = newTriangles;
}

// ============================================================================
// 3. LIGHTING & WATERCOLOR FACET PALETTE ASSIGNMENT
// ============================================================================
function assignFacetColors(mesh) {
  const { vertices, triangles } = mesh;
  // Warm directional key light from upper-right-front
  const lx = 0.56, ly = -0.46, lz = 0.69;

  for (let t of triangles) {
    const vA = vertices[t.a];
    const vB = vertices[t.b];
    const vC = vertices[t.c];

    const cx = (vA.x + vB.x + vC.x) / 3;
    const cy = (vA.y + vB.y + vC.y) / 3;
    t.cx = cx;
    t.cy = cy;
    t.distEye = Math.hypot(cx - EYE_L.x, cy - EYE_L.y);

    // 3D normal calculation
    const ux = vB.x - vA.x, uy = vB.y - vA.y, uz = vB.z - vA.z;
    const vx = vC.x - vA.x, vy = vC.y - vA.y, vz = vC.z - vA.z;
    let nx = uy * vz - uz * vy;
    let ny = uz * vx - ux * vz;
    let nz = ux * vy - uy * vx;
    const nLen = Math.hypot(nx, ny, nz) || 1;
    nx /= nLen; ny /= nLen; nz /= nLen;
    if (nz < 0) { nx = -nx; ny = -ny; nz = -nz; }

    // Screen-space triangle area
    t.area = 0.5 * Math.abs(ux * vy - uy * vx);

    const nJitter = (noise(cx * 0.018, cy * 0.018) - 0.5) * 0.22;
    const dot = Math.max(0, Math.min(1, nx * lx + ny * ly + nz * lz + nJitter));
    const reg = t.region;

    let colorIdx = 4; // default light honey fawn

    if (reg === "eye_R_pupil") {
      colorIdx = 16; // Charcoal slate
    } else if (reg === "eye_R_iris") {
      colorIdx = dot > 0.48 ? 17 : 6; // Amber ochre / camel fawn
    } else if (reg === "nostril" || reg === "mouth") {
      colorIdx = dot > 0.55 ? 14 : (dot > 0.32 ? 15 : 16);
    } else if (reg === "horn_L" || reg === "horn_R") {
      // Sculpted horn rings: slate, shadow violet, and sunlit buff cream ridges
      const ringBand = Math.sin(cy * 0.14 + cx * 0.05);
      if (dot > 0.68 && ringBand > 0) colorIdx = 2; // Golden biscuit cream ridge
      else if (dot > 0.55) colorIdx = 3; // Buff cream
      else if (dot > 0.42) colorIdx = 13; // Warm pale slate
      else if (dot > 0.28) colorIdx = ringBand > 0 ? 14 : 10; // Mid slate / mauve-violet
      else if (dot > 0.16) colorIdx = 15; // Deep horn slate
      else colorIdx = 12; // Deep dusk violet
    } else if (reg === "ear_inner") {
      if (dot > 0.52) colorIdx = 8; // Warm rose-fawn
      else if (dot > 0.34) colorIdx = 10; // Soft shadow mauve-violet
      else colorIdx = 11; // Muted plum-violet
    } else if (reg === "ear_outer") {
      if (dot > 0.65) colorIdx = 1; // Parchment cream
      else if (dot > 0.48) colorIdx = 4; // Honey fawn
      else if (dot > 0.32) colorIdx = 6; // Camel fawn
      else colorIdx = 11; // Plum-violet
    } else if (reg === "bridge" || reg === "forehead" || reg === "crown") {
      if (cx < 515) {
        // Far side slope of nose/forehead -> shadow violets & fawns
        if (dot > 0.55) colorIdx = 4;
        else if (dot > 0.40) colorIdx = 9;
        else if (dot > 0.26) colorIdx = 10;
        else colorIdx = 11;
      } else {
        // Sunlit dorsal ridge & near forehead -> warm creams & golden fawns
        if (dot > 0.72) colorIdx = 0;
        else if (dot > 0.58) colorIdx = 1;
        else if (dot > 0.46) colorIdx = 2;
        else if (dot > 0.34) colorIdx = 4;
        else colorIdx = 5;
      }
    } else if (reg === "beard") {
      if (dot > 0.66) colorIdx = 0;
      else if (dot > 0.52) colorIdx = 1;
      else if (dot > 0.40) colorIdx = 3;
      else if (dot > 0.28) colorIdx = 9;
      else if (dot > 0.18) colorIdx = 10;
      else colorIdx = 14;
    } else if (reg === "neck") {
      if (dot > 0.52) colorIdx = 6;
      else if (dot > 0.36) colorIdx = 11;
      else if (dot > 0.22) colorIdx = 14;
      else colorIdx = 15;
    } else {
      // Orbit, cheek, muzzle, jaw
      if (cx < 505) {
        // Far side of head in cool/warm violet-slate shadow
        if (dot > 0.52) colorIdx = 5;
        else if (dot > 0.38) colorIdx = 9;
        else if (dot > 0.26) colorIdx = 10;
        else if (dot > 0.16) colorIdx = 11;
        else colorIdx = 12;
      } else {
        // Near side of head (including subdivided left orbital patch)
        if (dot > 0.74) colorIdx = 0;
        else if (dot > 0.62) colorIdx = 1;
        else if (dot > 0.52) colorIdx = 3;
        else if (dot > 0.42) colorIdx = 4;
        else if (dot > 0.32) colorIdx = 5;
        else if (dot > 0.22) colorIdx = 6;
        else colorIdx = 10;
      }
    }

    t.colorIdx = colorIdx;
  }
}

// ============================================================================
// 4. RENDER WATERCOLOR MESH (OPAQUE PAPER RESERVE + BATCHED WATERCOLOR FILLS)
// ============================================================================
function renderWatercolorMesh(mesh) {
  const { vertices, triangles } = mesh;

  // Group triangles by palette color index for optimal batch performance
  const batches = Array.from({ length: PALETTE.facets.length }, () => []);
  for (let t of triangles) {
    // Skip triangles completely inside the hyperreal eye core
    if (t.distEye < 38) continue;
    batches[t.colorIdx].push(t);
  }

  // Pass A: Opaque under-wash so warm watercolor tones glow brightly on dark teal ground
  brush.noStroke();
  brush.noFill();
  for (let cIdx = 0; cIdx < batches.length; cIdx++) {
    const group = batches[cIdx];
    if (group.length === 0) continue;

    // Mix facet color with warm ivory paper (#fbf5e8) for the opaque base ground
    const baseCol = lerpHexColor(PALETTE.facets[cIdx], "#fbf5e8", 0.36);
    brush.wash(baseCol, 250);
    for (let t of group) {
      drawTriShape(vertices[t.a], vertices[t.b], vertices[t.c], 0);
    }
  }
  brush.noWash();

  // Pass B: Batched translucent watercolor fills with edge bleed & paper texture
  brush.noStroke();
  for (let cIdx = 0; cIdx < batches.length; cIdx++) {
    const group = batches[cIdx];
    if (group.length === 0) continue;

    const hex = PALETTE.facets[cIdx];
    brush.fill(hex, 148);
    brush.fillBleed(0.055, "in");
    brush.fillTexture(0.48, 0.34);

    for (let t of group) {
      // Micro-triangles under 130 sq px already have crisp wash; apply full watercolor shader to larger & mid facets
      if (t.area >= 130) {
        drawTriShape(vertices[t.a], vertices[t.b], vertices[t.c], 0);
      }
    }
  }
  brush.noFill();

  // Pass C: Subtle dry-media/graphite tonal hatching on deep shadow & horn facets
  brush.noStroke();
  brush.hatchStyle("2H", "#463c49", 0.32);
  for (let t of triangles) {
    if (t.distEye < 75) continue;
    if (t.colorIdx === 12 || t.colorIdx === 15 || t.colorIdx === 16) {
      brush.hatch(9, (t.cx + t.cy) * 0.7, { rand: 0.08 });
      drawTriShape(vertices[t.a], vertices[t.b], vertices[t.c], 0);
    }
  }
  brush.noHatch();
}

function renderOrbitalWatercolorBleeds() {
  // Soft watercolor blooms bleeding outward from the hyperreal left eye across the subdivided mesh
  const blooms = [
    { x: EYE_L.x - 18, y: EYE_L.y - 26, rx: 64, ry: 42, col: "#bd854f", alpha: 75 },
    { x: EYE_L.x + 22, y: EYE_L.y + 18, rx: 68, ry: 45, col: "#ce9c64", alpha: 70 },
    { x: EYE_L.x - 36, y: EYE_L.y + 14, rx: 52, ry: 38, col: "#9a839c", alpha: 68 },
    { x: EYE_L.x + 8,  y: EYE_L.y - 34, rx: 58, ry: 34, col: "#eed8b2", alpha: 80 },
    { x: EYE_L.x,      y: EYE_L.y,      rx: 62, ry: 44, col: "#a86f3e", alpha: 85 }
  ];

  brush.noStroke();
  for (let b of blooms) {
    brush.fill(b.col, b.alpha);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.52, 0.38);
    drawEllipsePoly(b.x, b.y, b.rx, b.ry, 18, 0.25);
  }
  brush.noFill();
}

// ============================================================================
// 5. FINE PEN EDGES OF THE LOW-POLY & SUBDIVIDED MESH
// ============================================================================
function renderMeshPenEdges(mesh) {
  const { vertices, triangles } = mesh;
  const edgeMap = new Map();

  for (let t of triangles) {
    const pairs = [
      [t.a, t.b],
      [t.b, t.c],
      [t.c, t.a]
    ];
    for (let [i1, i2] of pairs) {
      const a = Math.min(i1, i2);
      const b = Math.max(i1, i2);
      const key = a + "_" + b;
      if (!edgeMap.has(key)) {
        edgeMap.set(key, { a, b, count: 1, maxLevel: t.level });
      } else {
        const e = edgeMap.get(key);
        e.count++;
        e.maxLevel = Math.max(e.maxLevel, t.level);
      }
    }
  }

  for (let e of edgeMap.values()) {
    const v1 = vertices[e.a];
    const v2 = vertices[e.b];
    const mx = 0.5 * (v1.x + v2.x);
    const my = 0.5 * (v1.y + v2.y);

    // Elliptical distance to the hyperreal left eye
    const dx = (mx - EYE_L.x) / 1.18;
    const dy = (my - EYE_L.y) / 0.92;
    const dEye = Math.hypot(dx, dy);

    // Completely break the mesh inside the hyperreal eye & eyelids
    if (dEye < 54) continue;

    if (dEye < 88) {
      // Innermost micro-triangles: intermittent hairline graphite/pen edges dissolving into fur
      if (random() < 0.25) continue;
      brush.set("2H", "#5a4946", 0.26);
      brush.line(v1.x, v1.y, v2.x, v2.y);
    } else if (dEye < 142) {
      // Mid-subdivision transition: fine warm sepia technical pen
      brush.set("rotring", "#423638", 0.32);
      brush.line(v1.x, v1.y, v2.x, v2.y);
    } else {
      // Main low-poly head: crisp fine pen edges (slightly firmer on outer silhouette borders)
      const isSilhouette = e.count === 1;
      const weight = isSilhouette ? 0.58 : 0.42;
      const col = isSilhouette ? "#231f22" : "#322b2e";
      brush.set("rotring", col, weight);
      brush.line(v1.x, v1.y, v2.x, v2.y);
    }
  }
}

// ============================================================================
// 6. HYPERREAL LEFT EYE, WET LASHES, RADIATING FUR & FLY ON THE LID
// ============================================================================
function renderHyperrealEyeRegion() {
  const ex = EYE_L.x;
  const ey = EYE_L.y;

  // --- 6A. RADIATING INDIVIDUAL HAIRS (UNDERFUR & TRANSITION COAT) ---
  // Hairs bleed out from the orbital patch across the subdivided triangles
  drawRadiatingOrbitalFur(ex, ey);

  // --- 6B. ORBITAL SOCKET & EYELID SKIN FOLDS ---
  drawEyelidSculpture(ex, ey);

  // --- 6C. HYPERREAL GOAT EYE: SCLERA, LIMBUS, GOLDEN IRIS & HORIZONTAL PUPIL ---
  drawHyperrealGoatIrisAndPupil(ex, ey);

  // --- 6D. WET WATERLINE, TEAR MENISCUS & WET LASHES ---
  drawWetLashesAndTears(ex, ey);

  // --- 6E. CRISP TOP GUARD HAIRS OVERLAPPING LIDS & NEIGHBOURING TRIANGLES ---
  drawTopGuardHairs(ex, ey);

  // --- 6F. HYPERREAL FLY PERCHED ON THE UPPER EYELID ---
  drawFlyOnEyelid(ex - 38, ey - 48);
}

// Natural anatomical hair-flow angle around the goat's left eye
function getOrbitalHairAngle(x, y, ex, ey) {
  const dx = x - ex;
  const dy = y - ey;
  const baseAng = atan2(dy, dx);
  const n = (noise(x * 0.015, y * 0.015) - 0.5) * 28;

  // Sweep hairs over brow arch above, down nasal slope on left, and across zygoma below
  if (dy < -10 && dx < 0) {
    return baseAng - 18 + n;
  } else if (dy > 10) {
    return lerp(baseAng, 55, 0.25) + n;
  }
  return baseAng + n;
}

function drawRadiatingOrbitalFur(ex, ey) {
  const furColors = [
    { brush: "2B",      col: "#4e3a2d", w: 0.42, minR: 38, maxR: 135, count: 240 },
    { brush: "cpencil", col: "#7a5c48", w: 0.45, minR: 40, maxR: 155, count: 260 },
    { brush: "cpencil", col: "#856e88", w: 0.42, minR: 48, maxR: 165, count: 160 }, // soft shadow violet hairs
    { brush: "cpencil", col: "#616c78", w: 0.40, minR: 45, maxR: 160, count: 140 }, // slate hairs
    { brush: "cpencil", col: "#c99258", w: 0.46, minR: 40, maxR: 185, count: 320 }, // rich fawn hairs
    { brush: "cpencil", col: "#e6c38e", w: 0.44, minR: 42, maxR: 195, count: 280 }, // warm buff hairs
    { brush: "2H",      col: "#f8eed9", w: 0.38, minR: 40, maxR: 205, count: 260 }  // sunlit cream hairs
  ];

  for (let layer of furColors) {
    brush.set(layer.brush, layer.col, layer.w);
    for (let i = 0; i < layer.count; i++) {
      const a = random(360);
      // Bias radial distribution denser near the eye, thinning out into the triangles
      const t = pow(random(), 1.35);
      const r = lerp(layer.minR, layer.maxR, t);
      const sx = ex + cos(a) * r * 1.15;
      const sy = ey + sin(a) * r * 0.92;

      // Skip inside the eyeball opening itself
      const inEye = sq((sx - ex) / 48) + sq((sy - ey) / 30);
      if (inEye < 1.0) continue;

      const dir = getOrbitalHairAngle(sx, sy, ex, ey);
      const len = lerp(26, 11, t) * random(0.75, 1.25);
      const curveAng = dir + random(-14, 14);

      const mx = sx + cos(dir) * (len * 0.5);
      const my = sy + sin(dir) * (len * 0.5);
      const ex2 = sx + cos(curveAng) * len;
      const ey2 = sy + sin(curveAng) * len;

      brush.spline([
        [sx, sy, 0.35],
        [mx, my, 0.85],
        [ex2, ey2, 0.15]
      ], 0.35);
    }
  }
}

function drawEyelidSculpture(ex, ey) {
  // Dark recessed orbital fold washes around the upper & lower lids
  brush.noStroke();
  brush.wash("#362826", 185);
  drawEyeContourPoly(ex, ey, 54, 34, -6.5);
  brush.noWash();

  brush.noStroke();
  brush.fill("#4c3734", 145);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.4);
  drawEyeContourPoly(ex, ey - 3, 60, 39, -6.5);
  brush.noFill();

  // Sculpt the supratarsal upper eyelid fold and infraorbital lower lid bag
  const lidCreases = [
    { dy: -36, rx: 58, ry: 22, start: 195, end: 345, col: "#2b1e1c", w: 0.55 },
    { dy: -29, rx: 54, ry: 20, start: 190, end: 350, col: "#3d2c28", w: 0.48 },
    { dy: -22, rx: 51, ry: 16, start: 192, end: 348, col: "#f2dfc1", w: 0.38 }, // sunlit lid ridge highlight
    { dy:  26, rx: 52, ry: 18, start: 15,  end: 165, col: "#3b2b29", w: 0.45 },
    { dy:  34, rx: 56, ry: 20, start: 22,  end: 158, col: "#543f3c", w: 0.36 }
  ];

  for (let c of lidCreases) {
    brush.set("2B", c.col, c.w);
    const pts = [];
    for (let a = c.start; a <= c.end; a += 15) {
      const px = ex + cos(a) * c.rx;
      const py = ey + c.dy * 0.45 + sin(a) * c.ry;
      pts.push([px, py, 0.65]);
    }
    brush.spline(pts, 0.4);
  }

  // Fine radial skin wrinkles along the upper & lower eyelids
  brush.set("2H", "#332422", 0.28);
  for (let i = 0; i < 48; i++) {
    const a = random(360);
    const rx = random(47, 62);
    const ry = random(29, 41);
    const x1 = ex + cos(a) * rx;
    const y1 = ey + sin(a) * ry;
    const tang = a + 90 + random(-20, 20);
    const x2 = x1 + cos(tang) * random(6, 13);
    const y2 = y1 + sin(tang) * random(6, 13);
    brush.line(x1, y1, x2, y2);
  }
}

function drawEyeContourPoly(cx, cy, rx, ry, tiltDeg) {
  const steps = 28;
  brush.beginShape(0.25);
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * 360;
    // Almond/lemon eye opening with pointed medial and lateral canthi
    const pinch = 1 - 0.14 * pow(cos(a), 4);
    const lx = cos(a) * rx;
    const ly = sin(a) * ry * pinch;
    const wx = cx + lx * cos(tiltDeg) - ly * sin(tiltDeg);
    const wy = cy + lx * sin(tiltDeg) + ly * cos(tiltDeg);
    brush.vertex(wx, wy);
  }
  brush.endShape(true);
}

function drawHyperrealGoatIrisAndPupil(ex, ey) {
  const tilt = EYE_L.tilt;

  // 1. Dark Sclera/Limbal Cavity Base inside the Palpebral Fissure
  brush.noStroke();
  brush.wash("#1f1614", 255);
  drawEyeContourPoly(ex, ey, 46, 28, tilt);

  // Subtle warm pinkish-ivory sclera corners + medial lacrimal caruncle
  brush.wash("#d9b5ab", 210);
  drawEyeContourPoly(ex, ey, 43, 25, tilt);

  // Wet fleshy-rose lacrimal caruncle at medial canthus (inner left corner of eye)
  brush.wash("#9e5854", 235);
  drawEllipsePoly(ex - 41, ey + 5, 6.5, 4.5, 12, 0.2);

  // 2. Outer Dark Limbal Ring of the Iris
  brush.wash("#2c1b10", 250);
  drawEllipsePoly(ex + 1, ey, 39, 26, 28, 0.2);

  // 3. Luminous Golden-Amber Iris Base & Watercolor Pigmentation
  brush.wash("#d4871c", 250);
  drawEllipsePoly(ex + 1, ey, 35.5, 24, 28, 0.2);

  brush.wash("#eeb434", 235);
  drawEllipsePoly(ex + 1, ey, 31, 21, 26, 0.2);

  brush.noWash();
  brush.fill("#b86412", 130);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.55, 0.45);
  drawEllipsePoly(ex + 1, ey, 35, 23.5, 24, 0.2);
  brush.noFill();

  // 4. Intricate Radial Iris Stroma Fibers, Crypts & Collarette
  const irisStrokes = [
    { brush: "rotring", col: "#4a270b", w: 0.28, count: 120, rIn: 8,  rOut: 36 },
    { brush: "2H",      col: "#8c4a10", w: 0.30, count: 110, rIn: 9,  rOut: 35 },
    { brush: "rotring", col: "#f5c23b", w: 0.26, count: 130, rIn: 8,  rOut: 33 },
    { brush: "rotring", col: "#ffe999", w: 0.22, count: 95,  rIn: 7,  rOut: 25 },
    { brush: "rotring", col: "#291608", w: 0.30, count: 75,  rIn: 27, rOut: 37 } // dark limbal spokes
  ];

  for (let layer of irisStrokes) {
    brush.set(layer.brush, layer.col, layer.w);
    for (let i = 0; i < layer.count; i++) {
      const a = random(360);
      // Elliptical iris mapping around the horizontal slit pupil
      const r1 = random(layer.rIn, layer.rIn + 5);
      const r2 = random(layer.rOut - 6, layer.rOut);

      const x1Local = cos(a) * r1 * 1.18;
      const y1Local = sin(a) * r1 * 0.68;
      const x2Local = cos(a + random(-6, 6)) * r2 * 1.02;
      const y2Local = sin(a + random(-6, 6)) * r2 * 0.68;

      const x1 = ex + 1 + x1Local * cos(tilt) - y1Local * sin(tilt);
      const y1 = ey + x1Local * sin(tilt) + y1Local * cos(tilt);
      const x2 = ex + 1 + x2Local * cos(tilt) - y2Local * sin(tilt);
      const y2 = ey + x2Local * sin(tilt) + y2Local * cos(tilt);

      const mx = 0.5 * (x1 + x2) + random(-1.5, 1.5);
      const my = 0.5 * (y1 + y2) + random(-1.5, 1.5);

      brush.spline([
        [x1, y1, 0.6],
        [mx, my, 0.85],
        [x2, y2, 0.25]
      ], 0.3);
    }
  }

  // Glowing golden-cream pupillary ruff / collarette ring hugging the horizontal pupil
  brush.set("rotring", "#fff2b2", 0.32);
  for (let i = 0; i < 65; i++) {
    const tx = random(-25, 25);
    const side = random() < 0.5 ? -1 : 1;
    const ty = side * random(6.5, 10.5);
    const wx1 = ex + 1 + tx * cos(tilt) - ty * sin(tilt);
    const wy1 = ey + tx * sin(tilt) + ty * cos(tilt);
    const wx2 = wx1 + random(-2, 2);
    const wy2 = wy1 + side * random(2.5, 5.5);
    brush.line(wx1, wy1, wx2, wy2);
  }

  // 5. THE HORIZONTAL RECTANGULAR GOAT PUPIL (with Corpora Nigra undulations)
  drawHorizontalGoatPupil(ex + 1, ey, tilt);

  // 6. Upper Eyelid Cast Shadow Across Upper Dome of Cornea
  brush.noStroke();
  brush.wash("#1a110e", 95);
  brush.beginShape(0.2);
  for (let a = 185; a <= 355; a += 12) {
    const lx = cos(a) * 44;
    const ly = sin(a) * 26;
    brush.vertex(ex + lx * cos(tilt) - ly * sin(tilt), ey + lx * sin(tilt) + ly * cos(tilt));
  }
  for (let a = 355; a >= 185; a -= 12) {
    const lx = cos(a) * 42;
    const ly = sin(a) * 11 - 5;
    brush.vertex(ex + lx * cos(tilt) - ly * sin(tilt), ey + lx * sin(tilt) + ly * cos(tilt));
  }
  brush.endShape(true);
  brush.noWash();

  // 7. Wet Corneal Specular Window Reflection & Catchlights
  drawCornealReflections(ex + 1, ey, tilt);
}

function drawHorizontalGoatPupil(cx, cy, tiltDeg) {
  const pw = 25.5; // half-width of horizontal bar
  const ph = 7.2;  // half-height of horizontal bar

  // Warm dark-umber iris ruff border immediately around the slit pupil
  brush.noStroke();
  brush.wash("#331a0c", 245);
  drawPupilPolygon(cx, cy, pw + 1.8, ph + 1.6, tiltDeg);

  // Deep abyssal velvet black-indigo horizontal pupil core
  brush.wash("#0b0811", 255);
  drawPupilPolygon(cx, cy, pw, ph, tiltDeg);

  // Subtle internal optical depth & corpora nigra nodules along top pupil margin
  brush.wash("#191324", 180);
  drawPupilPolygon(cx, cy + 1, pw - 4, ph - 2.2, tiltDeg);
  brush.noWash();

  // Fine dark micro-texture along the pupil border
  brush.set("rotring", "#09060e", 0.35);
  for (let x = -pw; x <= pw; x += 1.8) {
    const topWave = -ph + sin(x * 16) * 1.1 + cos(x * 29) * 0.6;
    const botWave = ph + sin(x * 14 + 40) * 0.8;
    const wx1 = cx + x * cos(tiltDeg) - topWave * sin(tiltDeg);
    const wy1 = cy + x * sin(tiltDeg) + topWave * cos(tiltDeg);
    const wx2 = cx + x * cos(tiltDeg) - botWave * sin(tiltDeg);
    const wy2 = cy + x * sin(tiltDeg) + botWave * cos(tiltDeg);
    brush.line(wx1, wy1, wx1, wy1 + 1.5);
    brush.line(wx2, wy2, wx2, wy2 - 1.5);
  }
}

function drawPupilPolygon(cx, cy, hw, hh, tiltDeg) {
  const pts = [];
  // Top edge with organic corpora nigra undulations
  for (let i = 0; i <= 16; i++) {
    const t = i / 16;
    const x = lerp(-hw, hw, t);
    const endRound = Math.sqrt(Math.max(0, 1 - pow((t - 0.5) * 2, 6)));
    const nodule = Math.sin(t * Math.PI * 3) * 1.15;
    const y = (-hh + nodule) * endRound;
    pts.push([x, y]);
  }
  // Right rounded rectangular corner & bottom edge
  for (let i = 16; i >= 0; i--) {
    const t = i / 16;
    const x = lerp(-hw, hw, t);
    const endRound = Math.sqrt(Math.max(0, 1 - pow((t - 0.5) * 2, 6)));
    const nodule = Math.sin(t * Math.PI * 2 + 1.2) * 0.75;
    const y = (hh + nodule) * endRound;
    pts.push([x, y]);
  }

  brush.beginShape(0.22);
  for (let [lx, ly] of pts) {
    const wx = cx + lx * cos(tiltDeg) - ly * sin(tiltDeg);
    const wy = cy + lx * sin(tiltDeg) + ly * cos(tiltDeg);
    brush.vertex(wx, wy);
  }
  brush.endShape(true);
}

function drawCornealReflections(cx, cy, tiltDeg) {
  // Curved window/sky reflection sweeping across upper-left corneal dome
  brush.noStroke();
  brush.wash("#d8f0f8", 165);
  brush.beginShape(0.3);
  const arcPts = [
    [-24, -8], [-14, -14], [-1, -15], [10, -12],
    [8, -5], [-2, -7], [-13, -6], [-21, -2]
  ];
  for (let [lx, ly] of arcPts) {
    brush.vertex(cx + lx * cos(tiltDeg) - ly * sin(tiltDeg), cy + lx * sin(tiltDeg) + ly * cos(tiltDeg));
  }
  brush.endShape(true);

  // Razor-sharp pure white specular core inside the corneal reflection
  brush.wash("#ffffff", 240);
  brush.beginShape(0.25);
  const corePts = [
    [-19, -8], [-11, -12.5], [-2, -13], [5, -11],
    [3, -7], [-3, -8.5], [-11, -7.5], [-17, -4.5]
  ];
  for (let [lx, ly] of corePts) {
    brush.vertex(cx + lx * cos(tiltDeg) - ly * sin(tiltDeg), cy + lx * sin(tiltDeg) + ly * cos(tiltDeg));
  }
  brush.endShape(true);

  // Secondary pinpoint specular glint on right side of pupil margin
  brush.wash("#ffffff", 230);
  drawEllipsePoly(cx + 18, cy - 5, 3.2, 2.1, 10, 0.2);
  brush.noWash();
}

function drawWetLashesAndTears(ex, ey) {
  const tilt = EYE_L.tilt;

  // 1. Dark Wet Eyelid Margin Rims (Upper & Lower Palpebral Borders)
  brush.set("rotring", "#161010", 0.62);
  const upRim = [];
  for (let a = 184; a <= 356; a += 10) {
    const lx = cos(a) * 46;
    const ly = sin(a) * 26.5;
    upRim.push([ex + lx * cos(tilt) - ly * sin(tilt), ey + lx * sin(tilt) + ly * cos(tilt), 0.75]);
  }
  brush.spline(upRim, 0.35);

  // Lower wet pink-slate waterline rim
  brush.set("2B", "#6e4c4a", 0.55);
  const lowRim = [];
  for (let a = 8; a <= 172; a += 10) {
    const lx = cos(a) * 45.5;
    const ly = sin(a) * 26.5;
    lowRim.push([ex + lx * cos(tilt) - ly * sin(tilt), ey + lx * sin(tilt) + ly * cos(tilt), 0.7]);
  }
  brush.spline(lowRim, 0.35);

  // 2. Glistening Tear Meniscus Along Lower Waterline & Medial Canthus
  brush.set("rotring", "#ffffff", 0.36);
  for (let a = 22; a <= 158; a += 14) {
    if (random() < 0.25) continue;
    const lx1 = cos(a) * 44;
    const ly1 = sin(a) * 25;
    const lx2 = cos(a + 7) * 44;
    const ly2 = sin(a + 7) * 25;
    const x1 = ex + lx1 * cos(tilt) - ly1 * sin(tilt);
    const y1 = ey + lx1 * sin(tilt) + ly1 * cos(tilt);
    const x2 = ex + lx2 * cos(tilt) - ly2 * sin(tilt);
    const y2 = ey + lx2 * sin(tilt) + ly2 * cos(tilt);
    brush.line(x1, y1, x2, y2);
  }
  // Pinpoint tear glint on medial caruncle
  brush.line(ex - 42, ey + 4, ex - 39, ey + 3.5);

  // 3. WET UPPER EYELASHES (Clumped, Glistening, Sweeping Downward & Outward)
  // Goats have straight/slightly drooping upper lashes that overhang the upper iris
  const numClumps = 15;
  for (let c = 0; c < numClumps; c++) {
    const t = c / (numClumps - 1);
    const aBase = lerp(196, 344, t);
    const clumpTipAngle = lerp(135, 42, t) + random(-6, 6);
    const lashLen = lerp(18, 28, Math.sin(t * Math.PI)) * random(0.88, 1.15);

    const lxTip = cos(aBase) * 46 + cos(clumpTipAngle) * lashLen;
    const lyTip = sin(aBase) * 26.5 + sin(clumpTipAngle) * lashLen;
    const tipX = ex + lxTip * cos(tilt) - lyTip * sin(tilt);
    const tipY = ey + lxTip * sin(tilt) + lyTip * cos(tilt);

    // 4 hairs converging toward each wet lash clump tip
    for (let h = -2; h <= 2; h++) {
      const aRoot = aBase + h * 1.8;
      const lxRoot = cos(aRoot) * 46.5;
      const lyRoot = sin(aRoot) * 26.8;
      const rx = ex + lxRoot * cos(tilt) - lyRoot * sin(tilt);
      const ry = ey + lxRoot * sin(tilt) + lyRoot * cos(tilt);

      const mx = lerp(rx, tipX, 0.52) + h * 0.9;
      const my = lerp(ry, tipY, 0.52) + 2.5;
      const endX = tipX + h * 0.55;
      const endY = tipY + Math.abs(h) * 0.6;

      // Dark wet base stroke
      brush.set("rotring", h === 0 ? "#140f0e" : "#2e201b", h === 0 ? 0.42 : 0.30);
      brush.spline([
        [rx, ry, 0.85],
        [mx, my, 0.65],
        [endX, endY, 0.15]
      ], 0.35);

      // Sunlit golden-cream tips on outer wet lashes
      if (h === 1 && random() < 0.75) {
        brush.set("rotring", "#f3dcb3", 0.24);
        brush.line(mx, my, endX, endY);
      }
    }

    // Tiny wet specular droplet catching light on the clumped lash tip
    if (c % 2 === 1) {
      brush.set("rotring", "#ffffff", 0.34);
      brush.line(tipX - 0.8, tipY - 0.8, tipX + 0.8, tipY + 0.4);
    }
  }

  // 4. DELICATE WET LOWER LASHES
  for (let i = 0; i < 28; i++) {
    const t = i / 27;
    const aRoot = lerp(18, 162, t) + random(-2, 2);
    const lxRoot = cos(aRoot) * 46;
    const lyRoot = sin(aRoot) * 27.5;
    const rx = ex + lxRoot * cos(tilt) - lyRoot * sin(tilt);
    const ry = ey + lxRoot * sin(tilt) + lyRoot * cos(tilt);

    const outAng = lerp(65, 118, t) + random(-10, 10);
    const len = lerp(9, 16, Math.sin(t * Math.PI)) * random(0.8, 1.2);
    const mx = rx + cos(outAng) * (len * 0.5);
    const my = ry + sin(outAng) * (len * 0.5);
    const tx = rx + cos(outAng + random(-12, 12)) * len;
    const ty = ry + sin(outAng + random(-12, 12)) * len;

    brush.set("rotring", i % 3 === 0 ? "#e8cba0" : "#30221e", 0.24);
    brush.spline([
      [rx, ry, 0.65],
      [mx, my, 0.45],
      [tx, ty, 0.1]
    ], 0.3);
  }
}

function drawTopGuardHairs(ex, ey) {
  // Crisp individual hairs & sensory vibrissae bleeding across the subdivided triangles
  for (let i = 0; i < 420; i++) {
    const a = random(360);
    const t = pow(random(), 1.2);
    const r = lerp(44, 215, t);
    const sx = ex + cos(a) * r * 1.15;
    const sy = ey + sin(a) * r * 0.92;

    const inEye = sq((sx - ex) / 50) + sq((sy - ey) / 32);
    if (inEye < 1.0) continue;

    const dir = getOrbitalHairAngle(sx, sy, ex, ey);
    const len = lerp(24, 10, t) * random(0.8, 1.35);
    const mx = sx + cos(dir) * (len * 0.52);
    const my = sy + sin(dir) * (len * 0.52);
    const tx = sx + cos(dir + random(-12, 12)) * len;
    const ty = sy + sin(dir + random(-12, 12)) * len;

    const pick = random();
    if (pick < 0.42) {
      brush.set("rotring", "#fbf4e4", 0.22);
    } else if (pick < 0.75) {
      brush.set("2H", "#deb074", 0.28);
    } else {
      brush.set("rotring", "#332624", 0.22);
    }

    brush.spline([
      [sx, sy, 0.3],
      [mx, my, 0.75],
      [tx, ty, 0.1]
    ], 0.35);
  }

  // Long tactile brow & sub-orbital sensory whiskers (vibrissae)
  const whiskers = [
    [ex - 26, ey - 36, -125, 48],
    [ex - 10, ey - 39, -110, 54],
    [ex + 12, ey - 38, -75,  44],
    [ex - 18, ey + 34, 125,  42],
    [ex + 8,  ey + 36, 78,   46]
  ];
  for (let [wx, wy, ang, wLen] of whiskers) {
    const mx = wx + cos(ang) * (wLen * 0.5);
    const my = wy + sin(ang) * (wLen * 0.5);
    const tx = wx + cos(ang + 14) * wLen;
    const ty = wy + sin(ang + 14) * wLen;
    brush.set("rotring", "#fff8ea", 0.28);
    brush.spline([
      [wx, wy, 0.8],
      [mx, my, 0.5],
      [tx, ty, 0.1]
    ], 0.4);
  }
}

// ============================================================================
// 7. HYPERREAL FLY ON THE UPPER EYELID
// ============================================================================
function drawFlyOnEyelid(fx, fy) {
  // Fly is perched on the upper-left lid ridge, facing down-right (angle ~ 32 deg)
  const dir = 32;

  function toFly(lx, ly) {
    return [
      fx + lx * cos(dir) - ly * sin(dir),
      fy + lx * sin(dir) + ly * cos(dir)
    ];
  }

  // 1. Soft Contact Shadow on the Eyelid Skin & Hairs Below the Fly
  brush.noStroke();
  brush.fill("#1d1418", 115);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.4, 0.2);
  drawEllipsePoly(fx + 2, fy + 5.5, 16, 8.5, 16, 0.2);
  brush.noFill();

  // 2. Six Articulated Jointed Legs (Femur, Tibia, Tarsus + Tiny Claws)
  const legs = [
    // Front pair reaching forward toward the eye moisture
    [[4, -3],  [10, -10], [16, -9],  [19, -7]],
    [[4,  3],  [9,   11], [15,  12], [18,  10]],
    // Middle pair splayed outward gripping the lid hairs
    [[0, -4],  [1,  -14], [-3, -19], [-5, -21]],
    [[0,  4],  [0,   15], [-4,  20], [-6,  22]],
    // Hind pair bracing backward
    [[-5, -4], [-13, -12], [-20, -11], [-23, -9]],
    [[-5,  4], [-13,  13], [-21,  12], [-24,  10]]
  ];

  for (let leg of legs) {
    const wPts = leg.map(([lx, ly]) => toFly(lx, ly));
    // Subtle leg shadow on eyelid
    brush.set("2H", "#24191b", 0.26);
    brush.line(wPts[1][0] + 1, wPts[1][1] + 2.5, wPts[3][0] + 0.5, wPts[3][1] + 1);

    // Chitinous black-umber leg segments
    brush.set("rotring", "#141012", 0.36);
    brush.line(wPts[0][0], wPts[0][1], wPts[1][0], wPts[1][1]);
    brush.set("rotring", "#1e1718", 0.28);
    brush.line(wPts[1][0], wPts[1][1], wPts[2][0], wPts[2][1]);
    brush.set("rotring", "#2b2020", 0.22);
    brush.line(wPts[2][0], wPts[2][1], wPts[3][0], wPts[3][1]);

    // Specular glint on femur/tibia joint
    brush.set("rotring", "#dce6ec", 0.20);
    brush.line(wPts[1][0], wPts[1][1], lerp(wPts[1][0], wPts[2][0], 0.35), lerp(wPts[1][1], wPts[2][1], 0.35));
  }

  // 3. Abdomen (Segmented Dark Metallic Blue-Slate & Bronze)
  const [abX, abY] = toFly(-8.5, 0);
  brush.noStroke();
  brush.wash("#1c242b", 250);
  drawRotatedOval(abX, abY, 8.5, 6.2, dir);

  brush.wash("#2f3d47", 210);
  drawRotatedOval(abX + 1, abY - 1, 6.2, 4.2, dir);
  brush.noWash();

  // Abdomen tergite segment bands
  brush.set("rotring", "#0d1014", 0.28);
  for (let lx of [-12, -8.5, -5]) {
    const [p1x, p1y] = toFly(lx, -5.2);
    const [p2x, p2y] = toFly(lx + 1.2, 0);
    const [p3x, p3y] = toFly(lx, 5.2);
    brush.spline([[p1x, p1y, 0.3], [p2x, p2y, 0.7], [p3x, p3y, 0.3]], 0.35);
  }

  // 4. Thorax (Dark Metallic Charcoal-Bronze with Silver-Grey Scutum Stripes)
  const [thX, thY] = toFly(0.5, 0);
  brush.noStroke();
  brush.wash("#191d22", 255);
  drawRotatedOval(thX, thY, 6.5, 5.0, dir);
  brush.noWash();

  // Dusty silver-ash longitudinal stripes on thorax scutum
  brush.set("2H", "#98a4ad", 0.28);
  for (let ly of [-2.0, 0, 2.0]) {
    const [s1x, s1y] = toFly(-3.5, ly);
    const [s2x, s2y] = toFly(4.0, ly);
    brush.line(s1x, s1y, s2x, s2y);
  }

  // Crisp metallic specular highlight on thorax dome
  brush.set("rotring", "#f4fbff", 0.34);
  const [thH1x, thH1y] = toFly(-1.5, -1.6);
  const [thH2x, thH2y] = toFly(2.2, -1.2);
  brush.line(thH1x, thH1y, thH2x, thH2y);

  // 5. Head & Compound Brick-Red Eyes
  const [hdX, hdY] = toFly(6.8, 0);
  brush.noStroke();
  brush.wash("#181516", 255);
  drawRotatedOval(hdX, hdY, 3.6, 4.4, dir);

  // Left & Right Compound Eyes (Rich Burnt Sienna / Brick-Umber)
  const [ey1X, ey1Y] = toFly(7.4, -2.3);
  const [ey2X, ey2Y] = toFly(7.4,  2.3);
  brush.wash("#7d271e", 250);
  drawRotatedOval(ey1X, ey1Y, 2.5, 1.9, dir - 15);
  drawRotatedOval(ey2X, ey2Y, 2.5, 1.9, dir + 15);
  brush.noWash();

  // Pinpoint white specular highlights on both compound eyes
  brush.set("rotring", "#ffffff", 0.30);
  brush.line(ey1X - 0.5, ey1Y - 0.5, ey1X + 0.5, ey1Y - 0.2);
  brush.line(ey2X - 0.5, ey2Y - 0.5, ey2X + 0.5, ey2Y - 0.2);

  // Tiny bristles (setae) on thorax and abdomen tip
  brush.set("rotring", "#120e10", 0.20);
  for (let i = 0; i < 14; i++) {
    const lx = random(-15, 3);
    const ly = random(-4.5, 4.5);
    const [bx, by] = toFly(lx, ly);
    const [b2x, b2y] = toFly(lx - 2.8, ly * 1.25);
    brush.line(bx, by, b2x, b2y);
  }

  // 6. Two Translucent Iridescent Gossamer Wings (Swept Back Over Abdomen)
  const wingAngles = [-20, 22];
  for (let wAng of wingAngles) {
    const wDir = dir + 180 + wAng;
    const [wRootX, wRootY] = toFly(1.5, wAng < 0 ? -2.2 : 2.2);
    const wCx = wRootX + cos(wDir) * 9.5;
    const wCy = wRootY + sin(wDir) * 9.5;

    // Translucent pearlescent membrane
    brush.noStroke();
    brush.wash("#e6f2f7", 110);
    drawRotatedOval(wCx, wCy, 10.5, 4.1, wDir);

    // Subtle warm gold/cyan iridescence near wing tip
    brush.wash(wAng < 0 ? "#f7e6b5" : "#cdebf5", 85);
    drawRotatedOval(wCx + cos(wDir) * 3, wCy + sin(wDir) * 3, 5.5, 2.6, wDir);
    brush.noWash();

    // Crisp costal margin & fine wing venation
    brush.set("rotring", "#333940", 0.22);
    for (let v of [-0.65, -0.2, 0.25, 0.6]) {
      const vx1 = wRootX;
      const vy1 = wRootY;
      const vx2 = wRootX + cos(wDir + v * 16) * 18.5;
      const vy2 = wRootY + sin(wDir + v * 16) * 18.5;
      brush.line(vx1, vy1, vx2, vy2);
    }

    // Specular sheen along wing edge
    brush.set("rotring", "#ffffff", 0.24);
    brush.line(
      wRootX + cos(wDir - 8) * 5,
      wRootY + sin(wDir - 8) * 5,
      wRootX + cos(wDir - 8) * 15,
      wRootY + sin(wDir - 8) * 15
    );
  }
}

function drawRotatedOval(cx, cy, rx, ry, angleDeg) {
  const steps = 16;
  brush.beginShape(0.25);
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * 360;
    const lx = cos(a) * rx;
    const ly = sin(a) * ry;
    brush.vertex(
      cx + lx * cos(angleDeg) - ly * sin(angleDeg),
      cy + lx * sin(angleDeg) + ly * cos(angleDeg)
    );
  }
  brush.endShape(true);
}

// ============================================================================
// COLOR UTILITY
// ============================================================================
function lerpHexColor(hex1, hex2, t) {
  const c1 = parseInt(hex1.slice(1), 16);
  const c2 = parseInt(hex2.slice(1), 16);
  const r1 = (c1 >> 16) & 255, g1 = (c1 >> 8) & 255, b1 = c1 & 255;
  const r2 = (c2 >> 16) & 255, g2 = (c2 >> 8) & 255, b2 = c2 & 255;
  const r = Math.round(r1 + (r2 - r1) * t);
  const g = Math.round(g1 + (g2 - g1) * t);
  const b = Math.round(b1 + (b2 - b1) * t);
  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

