function draw() {
  translate(-width / 2, -height / 2);
  background("#DED2C1");

  // =========================================================================
  // HELPERS
  // =========================================================================
  function washPoly(pts, col, opacity = 220) {
    brush.noStroke();
    brush.noFill();
    brush.noHatch();
    let p = new brush.Polygon(pts);
    p.wash(col, opacity);
    brush.noWash();
  }

  function watercolorPoly(pts, col, opacity = 90, bleed = 0.04, tex = 0.35) {
    brush.noStroke();
    brush.noWash();
    brush.noHatch();
    let p = new brush.Polygon(pts);
    p.fill(col, opacity, bleed, tex);
    brush.noFill();
  }

  function hatchPoly(pts, bName, col, weight, dist, angle, opts = { rand: 0.03 }) {
    brush.noStroke();
    brush.noFill();
    brush.noWash();
    brush.hatchStyle(bName, col, weight);
    let p = new brush.Polygon(pts);
    p.hatch(dist, angle, opts);
    brush.noHatch();
  }

  function sprayField(xMin, yMin, xMax, yMax, count, col, wMin, wMax, clipPoly = null) {
    brush.noFill();
    brush.noWash();
    brush.noHatch();
    for (let i = 0; i < count; i++) {
      let x = random(xMin, xMax);
      let y = random(yMin, yMax);
      if (clipPoly && !pointInPoly(x, y, clipPoly)) continue;
      let len = random(8, 28);
      let ang = random(360);
      brush.set("spray", col, random(wMin, wMax));
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    }
  }

  function pointInPoly(x, y, vs) {
    let inside = false;
    for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
      let xi = vs[i][0], yi = vs[i][1];
      let xj = vs[j][0], yj = vs[j][1];
      let intersect = ((yi > y) !== (yj > y)) &&
        (x < (xj - xi) * (y - yi) / ((yj - yi) || 0.0001) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  }

  function lerpPt(a, b, t) {
    return [lerp(a[0], b[0], t), lerp(a[1], b[1], t)];
  }

  // Smooth anatomical hair-tract shading between two rails
  function drawCoatBand(railA, railB, steps, layers, bName, col, wMin, wMax, jitter = 4) {
    brush.noFill();
    brush.noWash();
    brush.noHatch();
    for (let s = 0; s < steps; s++) {
      let t = (s + random(-0.35, 0.35)) / steps;
      t = constrain(t, 0, 1);
      let idxF = t * (railA.length - 1);
      let i0 = floor(idxF);
      let i1 = min(railA.length - 1, i0 + 1);
      let f = idxF - i0;
      let pA = lerpPt(railA[i0], railA[i1], f);
      let pB = lerpPt(railB[i0], railB[i1], f);

      for (let l = 0; l < layers; l++) {
        let u0 = constrain(random(0, 0.65), 0, 1);
        let u1 = constrain(u0 + random(0.28, 0.55), 0, 1);
        let st = lerpPt(pA, pB, u0);
        let en = lerpPt(pA, pB, u1);
        let mid = lerpPt(st, en, 0.5);
        let dx = en[0] - st[0];
        let dy = en[1] - st[1];
        let nLen = sqrt(dx * dx + dy * dy) || 1;
        let nx = -dy / nLen;
        let ny = dx / nLen;
        let bend = random(-jitter, jitter);
        brush.set(bName, col, random(wMin, wMax));
        brush.spline([
          [st[0] + random(-2, 2), st[1] + random(-2, 2), random(0.4, 0.8)],
          [mid[0] + nx * bend, mid[1] + ny * bend, random(0.9, 1.3)],
          [en[0] + random(-2, 2), en[1] + random(-2, 2), random(0.3, 0.7)]
        ], 0.45);
      }
    }
  }

