    let col;
    let r = i % 7;
    if (r === 0 || r === 1) col = "#FFFFFF";
    else if (r === 2 || r === 3) col = "#C4E8F9";
    else if (r === 4) col = "#79AFC9";
    else if (r === 5) col = "#E3B368"; // faint warm marigold reflection in water sheet
