    ], 0.35);
  }

  // 4. Frothy Splash Line, Mist & Expanding Puddle Ripples at Base of Trough (y = 1020..1055)
  sprayField(spillLeftX - 15, 1005, spillRightX + 15, 1065, 160, "#DDF2FC", 0.3, 0.7);
  sprayField(spillLeftX, 1015, spillRightX, 1058, 95, "#FFFFFF", 0.25, 0.55);

  for (let i = 0; i < 65; i++) {
