    brush.set(i % 2 === 0 ? "rotring" : "cpencil", i % 3 === 0 ? "#FFFFFF" : "#AEE0F7", random(0.22, 0.45));
    brush.line(x, yBase, x + len, yBase - len * 0.05 + random(-2, 2));
  }

  // Horizontal puddle reflection lines on the wet courtyard ground below the trough
  for (let i = 0; i < 45; i++) {
    let x = random(30, 740);
    let y = random(1055, 1185);
    let len = random(25, 85);
    let col = i % 3 === 0 ? "#9AD2ED" : (i % 3 === 1 ? "#C78E38" : "#436E85");
    brush.set("cpencil", col, random(0.2, 0.38));
    brush.line(x, y, x + len, y - len * 0.03);
