  // Falling water droplets directly beneath the horse's wet chin and lower lip
  for (let i = 0; i < 12; i++) {
    let dx = random(465, 515);
    let dy = random(775, 812);
    brush.set("rotring", "#FFFFFF", random(0.22, 0.38));
    brush.line(dx, dy, dx - 0.5, dy + random(4, 9));
  }

  noLoop();
}

