// ============================================================================
// 3D COORDINATE & SIGNED DISTANCE FIELD (SDF) SCULPTURE ENGINE
// ============================================================================

function smin(a, b, k) {
  let h = Math.max(k - Math.abs(a - b), 0.0) / k;
  return Math.min(a, b) - h * h * k * 0.25;
}

function smax(a, b, k) {
  return -smin(-a, -b, k);
}

function sdEllipsoid(u, v, w, cu, cv, cw, ru, rv, rw) {
  let du = (u - cu) / ru;
  let dv = (v - cv) / rv;
  let dw = (w - cw) / rw;
  let k0 = Math.sqrt(du * du + dv * dv + dw * dw);
  if (k0 < 0.0001) return -Math.min(ru, rv, rw);
  let du2 = (u - cu) / (ru * ru);
  let dv2 = (v - cv) / (rv * rv);
  let dw2 = (w - cw) / (rw * rw);
  let k1 = Math.sqrt(du2 * du2 + dv2 * dv2 + dw2 * dw2);
  return (k0 * (k0 - 1.0)) / k1;
}

function sdSphere(u, v, w, cu, cv, cw, r) {
  let du = u - cu;
  let dv = v - cv;
  let dw = w - cw;
  return Math.sqrt(du * du + dv * dv + dw * dw) - r;
}

function sdCapsule(u, v, w, ax, ay, az, bx, by, bz, r1, r2) {
  let pax = u - ax, pay = v - ay, paz = w - az;
  let bax = bx - ax, bay = by - ay, baz = bz - az;
  let baba = bax * bax + bay * bay + baz * baz;
  let h = Math.max(0.0, Math.min(1.0, (pax * bax + pay * bay + paz * baz) / baba));
  let dx = pax - bax * h;
  let dy = pay - bay * h;
  let dz = paz - baz * h;
  let r = r1 + (r2 - r1) * h;
  return Math.sqrt(dx * dx + dy * dy + dz * dz) - r;
}

function screenRayToHead(px, py, rz) {
  let sx = (px - CX) / SCALE;
  let sy = -(py - CY) / SCALE;

  // Un-roll screen coordinates
  let rx = sx * cosR - sy * sinR;
  let ry = sx * sinR + sy * cosR;

  // Pitch and Yaw into local head frame (u, v, w)
  let y1 = ry * cosP - rz * sinP;
  let z1 = ry * sinP + rz * cosP;

  let u = rx * cosY + z1 * sinY;
  let v = y1;
  let w = -rx * sinY + z1 * cosY;
  return [u, v, w];
}

function headToScreen(u, v, w) {
  let rx = u * cosY - w * sinY;
  let z1 = u * sinY + w * cosY;
  let y1 = v;

  let ry = y1 * cosP + z1 * sinP;
  let rz = -y1 * sinP + z1 * cosP;

  let sx = rx * cosR + ry * sinR;
  let sy = -rx * sinR + ry * cosR;

  return [CX + sx * SCALE, CY - sy * SCALE, rz];
}

function headVecToScreen(nu, nv, nw) {
  let rx = nu * cosY - nw * sinY;
  let z1 = nu * sinY + nw * cosY;
  let y1 = nv;

  let ry = y1 * cosP + z1 * sinP;
  let rz = -y1 * sinP + z1 * cosP;

  let sx = rx * cosR + ry * sinR;
  let sy = -rx * sinR + ry * cosR;
  return [sx, sy, rz];
}

// Complete 3D SDF of the sleeping newborn's head, face, and curled fist
