  let dHand = sdEllipsoid(u, v, w, 0.16, -1.18, 0.56, 0.25, 0.24, 0.21);

  // Tucked thumb
  let dThumb = sdCapsule(u, v, w, -0.10, -1.04, 0.70, -0.01, -0.95, 0.80, 0.065, 0.058);
  dHand = smin(dHand, dThumb, 0.04);

  // Four curled chubby fingers (Index, Middle, Ring, Pinky)
  let dF1a = sdCapsule(u, v, w, 0.02, -1.02, 0.66, -0.07, -0.90, 0.79, 0.068, 0.060);
  let dF1b = sdCapsule(u, v, w, -0.07, -0.90, 0.79, -0.03, -0.98, 0.66, 0.058, 0.050);
  let dFinger1 = smin(dF1a, dF1b, 0.025);

  let dF2a = sdCapsule(u, v, w, 0.13, -1.06, 0.67, 0.04, -0.92, 0.80, 0.070, 0.062);
  let dF2b = sdCapsule(u, v, w, 0.04, -0.92, 0.80, 0.08, -1.01, 0.67, 0.060, 0.052);
  let dFinger2 = smin(dF2a, dF2b, 0.025);

  let dF3a = sdCapsule(u, v, w, 0.24, -1.12, 0.64, 0.15, -0.98, 0.76, 0.065, 0.058);
  let dF3b = sdCapsule(u, v, w, 0.15, -0.98, 0.76, 0.18, -1.06, 0.64, 0.056, 0.048);
  let dFinger3 = smin(dF3a, dF3b, 0.025);

  let dF4a = sdCapsule(u, v, w, 0.33, -1.19, 0.58, 0.25, -1.06, 0.69, 0.058, 0.050);
  let dFinger4 = dF4a;

  // Combine fingers with subtle inter-digital creases
  let dFingers = smin(smin(dFinger1, dFinger2, 0.018), smin(dFinger3, dFinger4, 0.018), 0.018);
  dHand = smin(dHand, dFingers, 0.045);

  // Chubby wrist roll below hand
  let dWrist = sdEllipsoid(u, v, w, 0.24, -1.42, 0.44, 0.26, 0.20, 0.22);
  dHand = smin(dHand, dWrist, 0.05);

  d = smin(d, dHand, 0.045);

  // Soft shoulder/swaddle mound in deep shadow
  let dShoulder = sdEllipsoid(u, v, w, 0.55, -1.05, 0.05, 0.55, 0.45, 0.45);
  d = smin(d, dShoulder, 0.18);

  return d;
}

function calcNormalHead(u, v, w) {
  const eps = 0.0035;
  let dx = sdfNewborn(u + eps, v, w) - sdfNewborn(u - eps, v, w);
  let dy = sdfNewborn(u, v + eps, w) - sdfNewborn(u, v - eps, w);
  let dz = sdfNewborn(u, v, w + eps) - sdfNewborn(u, v, w - eps);
  let len = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1.0;
  return [dx / len, dy / len, dz / len];
}

function buildSculptureField() {
  const N = GRID_W * GRID_H;
  hitBuf = new Uint8Array(N);
  uBuf = new Float32Array(N);
  vBuf = new Float32Array(N);
  wBuf = new Float32Array(N);
  nxBuf = new Float32Array(N);
  nyBuf = new Float32Array(N);
  nzBuf = new Float32Array(N);
  lightBuf = new Float32Array(N);
  sssBuf = new Float32Array(N);
  aoBuf = new Float32Array(N);
  specBuf = new Float32Array(N);
  rimBuf = new Float32Array(N);

  // Transform screen light vector (LX, LY, LZ) into head coordinates for shadow marching
  let lrx = LX * cosR - LY * sinR;
  let lry = LX * sinR + LY * cosR;
  let ly1 = lry * cosP - LZ * sinP;
  let lz1 = lry * sinP + LZ * cosP;
  let lu = lrx * cosY + lz1 * sinY;
  let lv = ly1;
  let lw = -lrx * sinY + lz1 * cosY;

  // Half-vector for wet specular highlights (view is (0, 0, 1))
  let hx = LX, hy = LY, hz = LZ + 1.0;
  let hLen = Math.sqrt(hx * hx + hy * hy + hz * hz);
  hx /= hLen; hy /= hLen; hz /= hLen;

  for (let gy = 0; gy < GRID_H; gy++) {
    let py = (gy + 0.5) * (1200 / GRID_H);
    for (let gx = 0; gx < GRID_W; gx++) {
      let px = (gx + 0.5) * (1200 / GRID_W);
      let idx = gy * GRID_W + gx;

      // Bounding circle check in screen space
      let dx = px - CX;
      let dy = py - (CY + 55);
      if (dx * dx + dy * dy > 560 * 560) continue;

      // Raymarch along rz from +1.35 down to -0.85
      let rz = 1.35;
      let hit = false;
      let u = 0, v = 0, w = 0;

      for (let step = 0; step < 22; step++) {
        let p = screenRayToHead(px, py, rz);
        u = p[0]; v = p[1]; w = p[2];
        let d = sdfNewborn(u, v, w);
        if (d < 0.0025) {
          hit = true;
          break;
        }
        rz -= d * 0.92;
        if (rz < -0.75) break;
      }

      if (!hit) continue;

      // Fade out back of skull/neck into deep shadow void
      if (u > 0.78 || v < -1.48 || (u > 0.45 && w < -0.15)) continue;

      hitBuf[idx] = 1;
      uBuf[idx] = u;
      vBuf[idx] = v;
      wBuf[idx] = w;

      let nHead = calcNormalHead(u, v, w);
      let nScr = headVecToScreen(nHead[0], nHead[1], nHead[2]);
      let nx = nScr[0], ny = nScr[1], nz = nScr[2];
      nxBuf[idx] = nx;
      nyBuf[idx] = ny;
      nzBuf[idx] = nz;

      // Ambient occlusion (2-step normal probe)
      let dAo1 = sdfNewborn(u + nHead[0] * 0.035, v + nHead[1] * 0.035, w + nHead[2] * 0.035);
      let dAo2 = sdfNewborn(u + nHead[0] * 0.085, v + nHead[1] * 0.085, w + nHead[2] * 0.085);
      let ao = Math.max(0.0, Math.min(1.0, 0.55 + 4.5 * (dAo1 - 0.035) + 2.2 * (dAo2 - 0.085)));

      // Soft raymarched cast shadow toward light
      let shadow = 1.0;
      let st = 0.025;
      for (let s = 0; s < 8; s++) {
        let sd = sdfNewborn(u + lu * st, v + lv * st, w + lw * st);
        if (sd < 0.001) {
          shadow = 0.08;
          break;
        }
        shadow = Math.min(shadow, 3.2 * sd / st);
        st += 0.045;
      }
      shadow = Math.max(0.08, Math.min(1.0, shadow));

      // Direct Lambertian + Sfumato wrap illumination
      let ndotl = nx * LX + ny * LY + nz * LZ;
      let diff = Math.max(0.0, ndotl) * shadow * ao;

      // Global chiaroscuro falloff (keeps lower-right and neck in deep smoky shadow)
      let globalMask = Math.max(0.0, Math.min(1.0, 1.12 - 0.55 * u + 0.25 * v + 0.35 * w));
      diff *= globalMask;

      // Subsurface scattering (sanguine glow in terminator & thin structures like nose/eyelids/fingers)
      let dBack = sdfNewborn(u - lu * 0.09, v - lv * 0.09, w - lw * 0.09);
      let thinness = Math.max(0.0, Math.min(1.0, 1.0 - Math.max(0.0, -dBack) * 8.0));
      let terminator = Math.exp(-Math.pow((ndotl - 0.12) / 0.38, 2.0));
      let sss = (terminator * 0.72 + thinness * 0.45) * ao * Math.max(0.25, shadow) * globalMask;

      // Specular highlight term
      let ndoth = Math.max(0.0, nx * hx + ny * hy + nz * hz);
      let spec = Math.pow(ndoth, 36.0) * shadow * ao * globalMask;

      // Edge dissolution factor (how close surface normal is to grazing)
      let rim = Math.max(0.0, Math.min(1.0, nz));

      lightBuf[idx] = diff;
      sssBuf[idx] = sss;
      aoBuf[idx] = ao;
      specBuf[idx] = spec;
      rimBuf[idx] = rim;
    }
  }
}

// Bilinear sampler for the precomputed 3D relief buffer
function sampleRelief(px, py) {
  let gx = (px / 1200) * GRID_W - 0.5;
  let gy = (py / 1200) * GRID_H - 0.5;
  let ix = Math.floor(gx);
  let iy = Math.floor(gy);
  if (ix < 0 || iy < 0 || ix >= GRID_W - 1 || iy >= GRID_H - 1) {
    return { hit: 0 };
  }
  let fx = gx - ix;
  let fy = gy - iy;

  let i00 = iy * GRID_W + ix;
  let i10 = i00 + 1;
  let i01 = i00 + GRID_W;
  let i11 = i01 + 1;

  let w00 = (1 - fx) * (1 - fy);
  let w10 = fx * (1 - fy);
  let w01 = (1 - fx) * fy;
  let w11 = fx * fy;

  let hit = hitBuf[i00] * w00 + hitBuf[i10] * w10 + hitBuf[i01] * w01 + hitBuf[i11] * w11;
  if (hit < 0.05) return { hit: 0 };

  // Find closest active corner for valid u, v, w interpolation
  let cIdx = hitBuf[i00] ? i00 : (hitBuf[i10] ? i10 : (hitBuf[i01] ? i01 : i11));

  let light = lightBuf[i00] * w00 + lightBuf[i10] * w10 + lightBuf[i01] * w01 + lightBuf[i11] * w11;
  let sss = sssBuf[i00] * w00 + sssBuf[i10] * w10 + sssBuf[i01] * w01 + sssBuf[i11] * w11;
  let ao = aoBuf[i00] * w00 + aoBuf[i10] * w10 + aoBuf[i01] * w01 + aoBuf[i11] * w11;
  let spec = specBuf[i00] * w00 + specBuf[i10] * w10 + specBuf[i01] * w01 + specBuf[i11] * w11;
  let rim = rimBuf[i00] * w00 + rimBuf[i10] * w10 + rimBuf[i01] * w01 + rimBuf[i11] * w11;
  let nx = nxBuf[cIdx];
  let ny = nyBuf[cIdx];
  let nz = nzBuf[cIdx];

  return {
    hit,
    u: uBuf[cIdx],
    v: vBuf[cIdx],
    w: wBuf[cIdx],
    nx,
    ny,
    nz,
    light,
    sss,
    ao,
    spec,
    rim
  };
}

// Helper to draw a soft organic watercolor polygon with brush.beginShape
function drawSoftBlob(cx, cy, rx, ry, rotDeg, ptsCount, irregularity, curvature = 0.85) {
  let rotRad = (rotDeg * Math.PI) / 180;
  let c = Math.cos(rotRad);
  let s = Math.sin(rotRad);
  brush.beginShape(curvature);
  for (let i = 0; i < ptsCount; i++) {
    let ang = (i / ptsCount) * Math.PI * 2;
    let radMod = 1.0 + random(-irregularity, irregularity);
    let lx = Math.cos(ang) * rx * radMod;
    let ly = Math.sin(ang) * ry * radMod;
    let px = cx + lx * c - ly * s;
    let py = cy + lx * s + ly * c;
    brush.vertex(px, py);
  }
  brush.endShape(true);
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Warm Tinted Paper Preparation & Distant Misty Grey-Blue Leonardo Landscape
  renderPaperAndLeonardoLandscape();

  // 2. Watercolor Underpainting: Deep Smoky Shadow Mass & Sanguine/Umber Washes
  renderUnderpaintingWashes();

  // 3. Broad Sfumato Charcoal & Stump Blending (Dissolving All Edges)
  renderBroadSfumato();

  // 4. Sanguine & Umber Glazes Floated in Cheeks, Nose, Eyelids, Lips & Fist
  renderSanguineAndUmberGlazes();

  // 5. Fine Cross-Contour Modeling & High-Contrast Chiaroscuro Depth
  renderFormModeling();

  // 6. HYPERREAL DETAILS IN THE LIGHT ONLY:
  //    6a. Translucent Eyelids with Fine Subdermal Veins & Delicate Lashes
  renderTranslucentEyelidsAndVeins();

  //    6b. Wet Lower Lip with Mucosal Sulci & Crisp Moisture Highlights
  renderWetLips();

  //    6c. Milk Spots (Milia) & Tactile Pore Micro-Relief on the Nose
  renderNoseMilkSpots();

  //    6d. Plump Curled Fist Knuckles, Creases & Soft Highlights
  renderCurledFistDetails();

  //    6e. Downy Hair (Lanugo) Swirling on the Illuminated Temple
  renderTempleLanugo();

  // 7. Final Atmospheric Sfumato Veil & Vignette Cohesion
  renderFinalSfumatoVeil();

  noLoop();
}

// ============================================================================
// STEP 1: WARM PAPER & HAZY GREY-BLUE LEONARDO LANDSCAPE
// ============================================================================
function renderPaperAndLeonardoLandscape() {
  brush.noStroke();

  // Batch 1: Warm antique paper tone variations
  brush.fill("#b89c7d", 38);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.15);
  drawSoftBlob(620, 580, 520, 480, -20, 14, 0.15);
  drawSoftBlob(480, 740, 380, 340, 15, 12, 0.18);

  // Batch 2: Hazy, misty grey-blue atmospheric sky & distance (Upper-Left & Top)
  brush.fill("#7b8e9b", 52);
  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.45, 0.12);
  drawSoftBlob(260, 210, 360, 250, -12, 14, 0.18);
  drawSoftBlob(540, 140, 340, 180, 8, 12, 0.18);

  brush.fill("#5f7280", 58);
  brush.fillBleed(0.48, "out");
  drawSoftBlob(190, 310, 290, 210, -8, 14, 0.2);
  drawSoftBlob(430, 230, 260, 160, -18, 12, 0.2);

  // Batch 3: Distant Leonardo Dolomitic crags & mountain silhouettes in misty blue-slate
  const cragColor1 = "#465763";
  brush.fill(cragColor1, 64);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.6, 0.2);

  // Far left jagged misty ridge
  brush.beginShape(0.35);
  brush.vertex(-20, 420);
  brush.vertex(45, 250);
  brush.vertex(95, 285);
  brush.vertex(155, 175);
  brush.vertex(210, 235);
  brush.vertex(275, 155);
  brush.vertex(340, 240);
  brush.vertex(420, 195);
  brush.vertex(490, 290);
  brush.vertex(440, 440);
  brush.vertex(-20, 460);
  brush.endShape(true);

  // Closer slate-blue crag emerging from valley mist
  brush.fill("#34434f", 68);
  brush.fillBleed(0.38, "out");
  brush.beginShape(0.4);
  brush.vertex(-20, 520);
  brush.vertex(60, 340);
  brush.vertex(130, 375);
  brush.vertex(195, 275);
  brush.vertex(260, 330);
  brush.vertex(345, 280);
  brush.vertex(430, 390);
  brush.vertex(310, 540);
  brush.endShape(true);

  // Batch 4: Drifting pale blue-grey mist bands across the mountain bases
  brush.fill("#95a6b0", 44);
  brush.fillBleed(0.5, "out");
  drawSoftBlob(220, 295, 260, 55, -4, 12, 0.15);
  drawSoftBlob(290, 385, 290, 68, -6, 12, 0.15);
  drawSoftBlob(160, 455, 240, 62, -2, 12, 0.15);

  brush.noFill();

  // Soft horizontal sfumato mist strokes blending the distant landscape
  const mistPalette = ["#7d8f9c", "#647684", "#8fa1ad", "#4c5d69", "#a3b1ba"];
  for (let i = 0; i < 240; i++) {
    let x = random(20, 680);
    let y = random(30, 580);
    let rInfo = sampleRelief(x, y);
    if (rInfo.hit > 0.25) continue;

    let col = random(mistPalette);
    let len = random(65, 160);
    let ang = random(-8, 6);
    brush.set("sfumato_clouds", col, random(0.65, 1.35));
    brush.line(
      x - (Math.cos((ang * Math.PI) / 180) * len) / 2,
      y - (Math.sin((ang * Math.PI) / 180) * len) / 2,
      x + (Math.cos((ang * Math.PI) / 180) * len) / 2,
      y + (Math.sin((ang * Math.PI) / 180) * len) / 2
    );
  }
}

// ============================================================================
// STEP 2: WATERCOLOR UNDERPAINTING (DEEP SHADOW MASS & WARM SKIN GLAZES)
// ============================================================================
function renderUnderpaintingWashes() {
  brush.noStroke();

  // Batch 1: Outer smoky charcoal-umber shadow washes enveloping the composition
  brush.fill("#231f21", 82);
  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.65, 0.18);
  drawSoftBlob(890, 740, 420, 480, 25, 14, 0.16);
  drawSoftBlob(640, 980, 520, 320, -10, 14, 0.16);
  drawSoftBlob(1020, 340, 340, 420, 12, 14, 0.18);
  drawSoftBlob(150, 880, 340, 380, -20, 14, 0.18);

  // Batch 2: Deeper velvety abyssal shadow behind the skull, neck, and below the fist
  brush.fill("#121013", 96);
  brush.fillBleed(0.48, "out");
  drawSoftBlob(880, 680, 330, 390, 28, 14, 0.15);
  drawSoftBlob(580, 980, 410, 240, -8, 14, 0.15);
  drawSoftBlob(980, 920, 340, 320, 15, 12, 0.15);
  drawSoftBlob(220, 960, 280, 280, -15, 12, 0.15);

  // Batch 3: Warm raw umber shadow transition around the face and fist
  brush.fill("#4f3524", 48);
  brush.fillBleed(0.45, "out");
  let pShadowCheek = headToScreen(0.48, -0.35, 0.35);
  drawSoftBlob(pShadowCheek[0], pShadowCheek[1], 190, 240, 26, 12, 0.14);
  let pFistShadow = headToScreen(0.22, -1.18, 0.48);
  drawSoftBlob(pFistShadow[0], pFistShadow[1], 165, 155, 20, 12, 0.14);

  // Batch 4: Sanguine (Venetian red chalk) floated glazes in cheeks, nose, lips & fist
  brush.fill("#9c3928", 38);
  brush.fillBleed(0.46, "out");
  brush.fillTexture(0.45, 0.1);

  // Near chubby cheek sanguine blush
  let pNearCheek = headToScreen(0.36, -0.28, 0.62);
  drawSoftBlob(pNearCheek[0], pNearCheek[1], 115, 98, 26, 12, 0.12);

  // Far cheek blush
  let pFarCheek = headToScreen(-0.32, -0.28, 0.58);
  drawSoftBlob(pFarCheek[0], pFarCheek[1], 68, 78, 26, 10, 0.12);

  // Nose tip & wings sanguine warmth
  let pNose = headToScreen(0.0, -0.20, 0.90);
  drawSoftBlob(pNose[0], pNose[1], 56, 48, 26, 10, 0.12);

  // Lips sanguine glaze
  let pLips = headToScreen(0.0, -0.49, 0.84);
  drawSoftBlob(pLips[0], pLips[1], 54, 38, 26, 10, 0.12);

  // Curled fingers sanguine warmth
  let pFingers = headToScreen(0.08, -0.98, 0.74);
  drawSoftBlob(pFingers[0], pFingers[1], 88, 68, 20, 12, 0.14);

  // Batch 5: Luminous warm ivory wash in the forehead & cheek highlights
  brush.fill("#f0dcc5", 42);
  brush.fillBleed(0.4, "out");
  let pForehead = headToScreen(-0.05, 0.42, 0.52);
  drawSoftBlob(pForehead[0], pForehead[1], 135, 105, 26, 12, 0.12);
  let pMalarLight = headToScreen(0.24, -0.14, 0.68);
  drawSoftBlob(pMalarLight[0], pMalarLight[1], 82, 65, 26, 10, 0.12);

  brush.noFill();
}

// ============================================================================
// STEP 3: BROAD SFUMATO CHARCOAL & STUMP BLENDING (NO HARD EDGES)
// ============================================================================
function renderBroadSfumato() {
  // Pass 1: Large smoky sfumato clouds enveloping the darks and dissolving head contours
  for (let i = 0; i < 1150; i++) {
    let px = random(30, 1170);
    let py = random(30, 1170);
    let r = sampleRelief(px, py);

    let col, weight, len, ang;

    if (r.hit < 0.15) {
      // Background: transition from misty grey-blue (upper-left) to deep smoky black (lower-right)
      let diag = (px * 0.68 + py * 0.73) / 1200;
      let distToFace = Math.hypot(px - 540, py - 540) / 600;

      if (px < 620 && py < 560 && diag < 0.62) {
        // Misty Leonardo background zone
        let bgCols = ["#4a5b66", "#394852", "#5d707d", "#2c3740", "#6f828f"];
        col = random(bgCols);
        weight = random(0.6, 1.25);
        len = random(60, 130);
        ang = random(-15, 15);
      } else {
        // Deep smoky charcoal shadow zone
        let darkCols = ["#110f12", "#181518", "#211c1f", "#2b2425", "#151215"];
        col = darkCols[Math.floor( constrain(diag * 4, 0, darkCols.length - 1) )];
        if (distToFace < 0.65 && random() < 0.4) col = "#2e2421";
        weight = random(0.8, 1.5);
        len = random(70, 150);
        ang = random(20, 75);
      }
      brush.set("sfumato_clouds", col, weight);
    } else {
      // On the newborn's head or fist
      // If near the silhouette rim, blur across the contour so NO edge exists!
      let L = r.light;
      let sss = r.sss;

      // Cross-contour angle from 3D surface normal
      ang = (Math.atan2(r.nx, -r.ny) * 180) / Math.PI + random(-18, 18);
      len = random(36, 78);

      if (r.rim < 0.34) {
        // Dissolve silhouette edge into background mist or smoky shadow
        px += random(-22, 22);
        py += random(-22, 22);
        col = L > 0.25 ? "#576268" : (L > 0.1 ? "#382c27" : "#1c181a");
        brush.set("sfumato_clouds", col, random(0.75, 1.35));
      } else if (L < 0.08) {
        col = random(["#161316", "#1f1a1c", "#292120", "#332622"]);
        brush.set("sfumato_clouds", col, random(0.65, 1.15));
      } else if (L < 0.24) {
        col = sss > 0.35 ? random(["#593426", "#693d2b", "#4a2e23"]) : random(["#47352b", "#574236", "#3b2c25"]);
        brush.set("charcoal_stump", col, random(0.7, 1.2));
      } else if (L < 0.48) {
        col = sss > 0.4 ? random(["#944935", "#a3573f", "#874835"]) : random(["#8f725b", "#a3856c", "#7a604c"]);
        brush.set("charcoal_stump", col, random(0.6, 1.05));
      } else {
        col = random(["#d4b89c", "#e3c9ae", "#edd6be", "#c7a98c"]);
        brush.set("charcoal_stump", col, random(0.55, 0.95));
      }
    }

    let rad = (ang * Math.PI) / 180;
    let dx = (Math.cos(rad) * len) / 2;
    let dy = (Math.sin(rad) * len) / 2;
    brush.line(px - dx, py - dy, px + dx, py + dy);
  }
}

// ============================================================================
// STEP 4: SANGUINE & UMBER GLAZES IN CHEEKS, NOSE, LIPS & FIST
// ============================================================================
function renderSanguineAndUmberGlazes() {
  // Targeted glaze passes over the sculpted anatomy
  for (let i = 0; i < 1100; i++) {
    // Sample preferentially across the face and fist region
    let px = random(240, 920);
    let py = random(220, 980);
    let r = sampleRelief(px, py);
    if (r.hit < 0.35) continue;

    let u = r.u, v = r.v, w = r.w;
    let L = r.light;
    let sss = r.sss;

    // Determine anatomical glaze affinity
    let isCheek = Math.hypot(Math.abs(u) - 0.36, v + 0.28) < 0.32;
    let isNose = Math.hypot(u, v + 0.19) < 0.20 && w > 0.72;
    let isLips = Math.hypot(u, v + 0.48) < 0.20 && w > 0.70;
    let isEyelid = Math.hypot(Math.abs(u) - 0.30, v - 0.02) < 0.19;
    let isFist = v < -0.82 && w > 0.45;

    let ang = (Math.atan2(r.nx, -r.ny) * 180) / Math.PI + random(-14, 14);
    let len = random(22, 48);
    let col = null;
    let weight = random(0.5, 0.95);

    if ((isCheek || isNose || isLips || isFist) && L > 0.06 && L < 0.62) {
      // Float rich sanguine & burnt umber glazes
      if (isLips) {
        col = L > 0.28 ? random(["#a83c30", "#ba4b3c", "#913026"]) : random(["#6e231c", "#541b16"]);
      } else if (sss > 0.32 || isCheek || isNose) {
        col = L > 0.32
          ? random(["#b5533e", "#c4644e", "#a14532", "#964b36"])
          : random(["#7d3526", "#662d20", "#8a3c2b", "#593224"]);
      } else {
        col = random(["#6e4732", "#5c3b28", "#7d533c", "#4a2f20"]);
      }
      brush.set("sanguine_glaze", col, weight);
    } else if (isEyelid && L > 0.08) {
      // Subtle warm umber-violet & rose-umber glaze over the translucent eyelids
      col = L > 0.35
        ? random(["#b07d6c", "#9e6b5c", "#c28e7c"])
        : random(["#6b483e", "#573931", "#785247"]);
      len = random(16, 32);
      brush.set("sanguine_glaze", col, weight * 0.75);
    } else if (L <= 0.14) {
      // Deep smoky umber-charcoal core shadow
      col = random(["#241c1b", "#1a1516", "#2e2320", "#141113"]);
      brush.set("charcoal_stump", col, weight * 0.9);
    }

    if (col) {
      let rad = (ang * Math.PI) / 180;
      let dx = (Math.cos(rad) * len) / 2;
      let dy = (Math.sin(rad) * len) / 2;
      brush.line(px - dx, py - dy, px + dx, py + dy);
    }
  }
}

// ============================================================================
// STEP 5: FINE CROSS-CONTOUR MODELING & CHIAROSCURO DEPTH
// ============================================================================
function renderFormModeling() {
  // Pass A: Medium-fine velvet charcoal and warm chalk modeling across the 3D surface
  for (let i = 0; i < 2400; i++) {
    let px = random(200, 960);
    let py = random(180, 1020);
    let r = sampleRelief(px, py);
    if (r.hit < 0.25) continue;

    let L = r.light;
    let sss = r.sss;
    let ao = r.ao;

    // Follow 3D cross-contour curvature
    let ang = (Math.atan2(r.nx, -r.ny) * 180) / Math.PI + random(-10, 10);
    let len = random(14, 34);
    let col, brushName, weight;

    if (r.rim < 0.28) {
      // Lost-edge sfumato whisper at the boundary
      col = L > 0.25 ? "#697378" : "#221d1e";
      brushName = "charcoal_stump";
      weight = random(0.45, 0.8);
      len = random(28, 52);
    } else if (ao < 0.42 || L < 0.07) {
      // Deep crevices: nostril, mouth corner, under chin, between curled fingers, shadow side
      col = random(["#120f11", "#1b1617", "#261d1c", "#0d0b0d"]);
      brushName = "velvet_charcoal";
      weight = random(0.55, 0.95);
      len = random(12, 26);
    } else if (L < 0.20) {
      col = sss > 0.35 ? random(["#5c2f22", "#4a261c", "#6e392a"]) : random(["#3d2d25", "#4c382e", "#2e221d"]);
      brushName = "velvet_charcoal";
      weight = random(0.45, 0.8);
    } else if (L < 0.38) {
      col = sss > 0.38 ? random(["#9e4f3b", "#b05e47", "#8a4331"]) : random(["#8f6e58", "#9e7c64", "#7a5c49"]);
      brushName = "velvet_charcoal";
      weight = random(0.4, 0.72);
    } else if (L < 0.56) {
      col = sss > 0.35 ? random(["#cf8872", "#d99882", "#c47c66"]) : random(["#cfa98c", "#dbb89b", "#bf997c"]);
      brushName = "skin_pore";
      weight = random(0.65, 1.05);
      len = random(10, 22);
    } else {
      // High light: luminous warm skin tones
      col = L > 0.72
        ? random(["#f7e7d4", "#fcf0e1", "#f0dbc3"])
        : random(["#e6cab0", "#edd4bc", "#dec0a4"]);
      brushName = "skin_pore";
      weight = random(0.6, 1.0);
      len = random(9, 19);
    }

    brush.set(brushName, col, weight);
    let rad = (ang * Math.PI) / 180;
    let dx = (Math.cos(rad) * len) / 2;
    let dy = (Math.sin(rad) * len) / 2;
    brush.line(px - dx, py - dy, px + dx, py + dy);
  }

  // Pass B: Reinforce the deep anatomical occlusion lines (nostril cavities, eyelid slits, mouth line, finger creases)
  renderAnatomicalCreases();
}

function renderAnatomicalCreases() {
  // 1. Nostril cavities (soft dark umber-black cores)
  for (let side of [-1, 1]) {
    for (let i = 0; i < 28; i++) {
      let u = side * random(0.055, 0.105);
      let v = random(-0.272, -0.242);
      let w = random(0.83, 0.87);
      let p = headToScreen(u, v, w);
      let col = random(["#170d0c", "#261411", "#381c17"]);
      brush.set("skin_pore", col, random(0.55, 0.95));
      brush.line(p[0] - 4, p[1] - 2, p[0] + 4, p[1] + 2);
    }
  }

  // 2. Closed Eyelid Slits (palpebral fissures) & Supratarsal Creases
  for (let side of [-1, 1]) {
    let steps = 26;
    let slitPts = [];
    let creasePts = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let au = 0.165 + t * 0.265;
      let u = side * au;
      let lidV = -0.038 + 0.32 * (au - 0.30) * (au - 0.30);
      // Project onto eyeball depth
      let du = au - 0.30;
      let dv = lidV - 0.02;
      let w = 0.61 + Math.sqrt(Math.max(0.01, 0.175 * 0.175 - du * du - dv * dv));
      let ps = headToScreen(u, lidV, w);
      slitPts.push([ps[0], ps[1], 0.4 + 0.6 * Math.sin(t * Math.PI)]);

      // Upper eyelid crease
      let creaseV = 0.088 - t * 0.032 + 0.018 * Math.sin(t * Math.PI);
      let pc = headToScreen(u, creaseV, w - 0.015);
      creasePts.push([pc[0], pc[1], 0.3 + 0.6 * Math.sin(t * Math.PI)]);
    }

    // Draw soft layered eyelid slit and crease
    brush.set("velvet_charcoal", "#3d221c", 0.55);
    brush.spline(slitPts, 0.5);
    brush.set("skin_pore", "#24120f", 0.65);
    brush.spline(slitPts, 0.5);

    brush.set("velvet_charcoal", "#59342a", 0.48);
    brush.spline(creasePts, 0.5);
    brush.set("skin_pore", "#3b2019", 0.45);
    brush.spline(creasePts, 0.5);
  }

  // 3. Mouth parting line (between pouting upper lip tubercle and wet lower lip)
  let mouthPts = [];
  for (let i = 0; i <= 28; i++) {
    let t = (i / 28) * 2 - 1; // -1 to 1
    let u = t * 0.168;
    let au = Math.abs(u);
    // Wavy Cupid's bow / central tubercle curve
    let v = -0.482 - 0.014 * Math.cos((au / 0.17) * Math.PI) - 0.012 * (au / 0.17);
    let w = 0.865 - 0.105 * (au / 0.17) * (au / 0.17);
    let p = headToScreen(u, v, w);
    mouthPts.push([p[0], p[1], 0.35 + 0.65 * (1 - au / 0.18)]);
  }
  brush.set("velvet_charcoal", "#451915", 0.55);
  brush.spline(mouthPts, 0.5);
  brush.set("skin_pore", "#260c0a", 0.65);
  brush.spline(mouthPts, 0.5);
}

// ============================================================================
// STEP 6a: HYPERREAL TRANSLUCENT EYELIDS WITH FINE VEINS & LASHES
// ============================================================================
function renderTranslucentEyelidsAndVeins() {
  // Helper to project a point on the upper eyelid dome
  function eyelidPoint(side, au, v) {
    let u = side * au;
    let du = au - 0.30;
    let dv = v - 0.02;
    let w = 0.612 + Math.sqrt(Math.max(0.005, 0.174 * 0.174 - du * du - dv * dv));
    return headToScreen(u, v, w);
  }

  // 1. Luminous translucent skin micro-strokes across the upper eyelid dome
  for (let side of [-1, 1]) {
    for (let i = 0; i < 160; i++) {
      let au = random(0.18, 0.42);
      let v = random(-0.03, 0.085);
      let p = eyelidPoint(side, au, v);
      let r = sampleRelief(p[0], p[1]);
      if (r.hit < 0.5 || r.light < 0.18) continue;

      let col = r.light > 0.52
        ? random(["#f5dfd0", "#ebd0be", "#fae8dc"])
        : random(["#cfa492", "#bf917e", "#dfb6a4"]);
      brush.set("skin_pore", col, random(0.45, 0.75));
      let ang = ROLL_DEG + side * 12 + random(-10, 10);
      let rad = (ang * Math.PI) / 180;
      let len = random(5, 11);
      brush.line(p[0] - Math.cos(rad) * len, p[1] - Math.sin(rad) * len, p[0] + Math.cos(rad) * len, p[1] + Math.sin(rad) * len);
    }
  }

  // 2. Fine branching subdermal veins (violet-blue & carmine capillaries) on the lit eyelids
  const veinRoots = [
    // Near eyelid (side = +1) main branching vessels
    { side: 1, au0: 0.23, v0: 0.075, au1: 0.28, v1: -0.015, col: "#545b78", w: 0.72 },
    { side: 1, au0: 0.33, v0: 0.080, au1: 0.30, v1: -0.020, col: "#4c5470", w: 0.78 },
    { side: 1, au0: 0.39, v0: 0.065, au1: 0.35, v1: -0.018, col: "#615975", w: 0.65 },
    { side: 1, au0: 0.26, v0: 0.068, au1: 0.22, v1: 0.005, col: "#854953", w: 0.58 },
    { side: 1, au0: 0.36, v0: 0.072, au1: 0.40, v1: 0.002, col: "#7a4652", w: 0.55 },
    // Far eyelid (side = -1) subtle vessels in light
    { side: -1, au0: 0.25, v0: 0.070, au1: 0.29, v1: -0.012, col: "#575d78", w: 0.62 },
    { side: -1, au0: 0.33, v0: 0.074, au1: 0.31, v1: -0.015, col: "#7d4852", w: 0.55 }
  ];

  for (let vr of veinRoots) {
    // Trace primary vessel with organic micro-meander
    let pts = [];
    let steps = 14;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let au = lerp(vr.au0, vr.au1, t) + 0.006 * Math.sin(t * Math.PI * 2.5 + vr.au0 * 30);
      let v = lerp(vr.v0, vr.v1, t) + 0.004 * Math.cos(t * Math.PI * 3.0);
      let p = eyelidPoint(vr.side, au, v);
      pts.push([p[0], p[1], 0.3 + 0.7 * Math.sin(t * Math.PI)]);

      // Spawn delicate bifurcating sub-capillaries at t = 0.35 and t = 0.65
      if (s === 5 || s === 9) {
        let branchPts = [];
        let bDir = s === 5 ? 1 : -1;
        for (let bs = 0; bs <= 7; bs++) {
          let bt = bs / 7;
          let bau = au + bDir * bt * 0.032 + 0.003 * Math.sin(bt * 4);
          let bv = v - bt * 0.028;
          let bp = eyelidPoint(vr.side, bau, bv);
          branchPts.push([bp[0], bp[1], (1 - bt) * 0.75]);
        }
        brush.set("subdermal_vein", "#8c4c56", vr.w * 0.68);
        brush.spline(branchPts, 0.55);
      }
    }
    brush.set("subdermal_vein", vr.col, vr.w);
    brush.spline(pts, 0.6);
  }

  // 3. Semi-translucent skin whisper over the veins so they read as subdermal
  for (let side of [-1, 1]) {
    for (let i = 0; i < 65; i++) {
      let au = random(0.20, 0.39);
      let v = random(-0.02, 0.07);
      let p = eyelidPoint(side, au, v);
      let r = sampleRelief(p[0], p[1]);
      if (r.light < 0.25) continue;
      let col = r.light > 0.5 ? "#f5dfd0" : "#d9b29e";
      brush.set("lanugo_silk", col, random(0.45, 0.75));
      let len = random(4, 8);
      brush.line(p[0] - len, p[1] - 1, p[0] + len, p[1] + 1);
    }
  }

  // 4. Gossamer-fine baby eyelashes resting along the closed palpebral slit
  for (let side of [-1, 1]) {
    let count = side === 1 ? 34 : 22;
    for (let i = 0; i < count; i++) {
      let t = (i + random(-0.25, 0.25)) / count;
      let au = 0.18 + t * 0.23;
      let u = side * au;
      let lidV = -0.038 + 0.32 * (au - 0.30) * (au - 0.30);
      let p0 = eyelidPoint(side, au, lidV);

      // Lashes curve gently downward and outward onto the lower lid puff
      let lashLenU = side * (t - 0.35) * 0.022;
      let lashLenV = -random(0.024, 0.042) * Math.sin(t * Math.PI);
      let pMid = eyelidPoint(side, au + lashLenU * 0.45, lidV + lashLenV * 0.55);
      let pTip = eyelidPoint(side, au + lashLenU, lidV + lashLenV);

      // Dark umber root, golden-brown tip catching the light
      let col = random() < 0.35 ? "#7a583e" : "#3b241a";
      brush.set("lanugo_silk", col, random(0.45, 0.72));
      brush.spline([
        [p0[0], p0[1], 0.9],
        [pMid[0], pMid[1], 0.6],
        [pTip[0], pTip[1], 0.08]
      ], 0.5);
    }
  }
}

// ============================================================================
// STEP 6b: HYPERREAL WET LOWER LIP WITH MUCOSAL SULCI & MOISTURE GLINTS
// ============================================================================
function renderWetLips() {
  // 1. Rich carmine-sanguine and rose modeling of upper and lower lip vermilion
  for (let i = 0; i < 220; i++) {
    let u = random(-0.155, 0.155);
    let au = Math.abs(u);
    let isUpper = random() < 0.42;
    let v = isUpper
      ? random(-0.48, -0.425 - 0.03 * (au / 0.16))
      : random(-0.565, -0.49);
    let w = 0.855 - 0.10 * (au / 0.16) * (au / 0.16);
    let p = headToScreen(u, v, w);
    let r = sampleRelief(p[0], p[1]);
    if (r.hit < 0.4 || r.light < 0.12) continue;

    let col;
    if (isUpper) {
      col = r.light > 0.42
        ? random(["#c76b5a", "#b55848", "#d67d6b"])
        : random(["#8a382c", "#732c22", "#9c4436"]);
    } else {
      // Wet lower lip catches stronger direct light
      col = r.light > 0.48
        ? random(["#e08575", "#eb9688", "#cf7261", "#f2aba0"])
        : random(["#a6463a", "#8f382d", "#ba5648"]);
    }

    // Vertical contour strokes following the curve of the lip cylinder
    let p2 = headToScreen(u, v - 0.022, w - 0.008);
    brush.set("skin_pore", col, random(0.45, 0.8));
    brush.line(p[0], p[1], p2[0], p2[1]);
  }

  // 2. Delicate vertical mucosal sulci (fine lip creases) across the lower lip
  for (let i = -9; i <= 9; i++) {
    let u = i * 0.015 + random(-0.003, 0.003);
    let au = Math.abs(u);
    let wBase = 0.852 - 0.095 * (au / 0.16) * (au / 0.16);
    let pTop = headToScreen(u * 0.92, -0.495, wBase);
    let pMid = headToScreen(u, -0.530, wBase + 0.012);
    let pBot = headToScreen(u * 1.06, -0.562, wBase - 0.010);

    let r = sampleRelief(pMid[0], pMid[1]);
    if (r.light < 0.15) continue;

    let col = r.light > 0.4 ? "#8f3228" : "#591b15";
    brush.set("subdermal_vein", col, random(0.55, 0.85));
    brush.spline([
      [pTop[0], pTop[1], 0.3],
      [pMid[0], pMid[1], 0.85],
      [pBot[0], pBot[1], 0.25]
    ], 0.5);
  }

  // 3. Glistening wet specular highlights along the lower lip roll & central sucking tubercle
  // Soft pre-glow sheen
  for (let i = 0; i < 45; i++) {
    let u = random(-0.11, 0.09);
    let au = Math.abs(u);
    let v = -0.522 + random(-0.012, 0.012);
    let w = 0.864 - 0.09 * (au / 0.16) * (au / 0.16);
    let p = headToScreen(u, v, w);
    brush.set("skin_pore", "#fce0d8", random(0.45, 0.75));
    brush.line(p[0] - 2.5, p[1] - 1, p[0] + 2.5, p[1] + 1);
  }

  // Razor-sharp wet moisture glints (broken micro-beads & streaks along the lip crest)
  for (let i = 0; i < 38; i++) {
    let u = random(-0.105, 0.085);
    let au = Math.abs(u);
    let v = -0.518 + 0.015 * (au / 0.12) + random(-0.006, 0.006);
    let w = 0.868 - 0.09 * (au / 0.16) * (au / 0.16);
    let p = headToScreen(u, v, w);

    // Slight moisture bead elongation along the lip contour or sulcus
    let isVerticalGlint = random() < 0.35;
    let dx = isVerticalGlint ? random(-1.2, 1.2) : random(1.8, 4.2);
    let dy = isVerticalGlint ? random(1.8, 3.8) : random(-1.5, 1.5);

    brush.set("chalk_specular", random() < 0.7 ? "#ffffff" : "#fff7f2", random(0.45, 0.9));
    brush.line(p[0] - dx * 0.5, p[1] - dy * 0.5, p[0] + dx * 0.5, p[1] + dy * 0.5);
  }

  // Subtle wet glint on the central upper lip sucking tubercle & philtrum crest
  for (let i = 0; i < 16; i++) {
    let u = random(-0.045, 0.035);
    let v = random(-0.445, -0.425);
    let p = headToScreen(u, v, 0.872);
    brush.set("chalk_specular", "#fff9f5", random(0.4, 0.7));
    brush.line(p[0] - 1.5, p[1] - 0.8, p[0] + 1.5, p[1] + 0.8);
  }
}

// ============================================================================
// STEP 6c: HYPERREAL MILK SPOTS (MILIA) ON THE NOSE & SKIN MICRO-RELIEF
// ============================================================================
function renderNoseMilkSpots() {
  // 1. Sculptural highlight & tactile pore texture on the bridge and tip of the button nose
  for (let i = 0; i < 240; i++) {
    let u = random(-0.13, 0.13);
    let v = random(-0.24, 0.04);
    // Snap to nose surface
    let w = 0.935 - 0.35 * u * u - 0.25 * (v + 0.18) * (v + 0.18);
    let p = headToScreen(u, v, w);
    let r = sampleRelief(p[0], p[1]);
    if (r.hit < 0.5 || r.light < 0.28) continue;

    let col = r.light > 0.62
      ? random(["#faecdc", "#fff5e8", "#f2dec8"])
      : random(["#e3c3a8", "#d6b296", "#ebd0b7"]);
    brush.set("skin_pore", col, random(0.4, 0.7));
    let ang = random(0, 180);
    let rad = (ang * Math.PI) / 180;
    let len = random(2.5, 5.5);
    brush.line(p[0] - Math.cos(rad) * len, p[1] - Math.sin(rad) * len, p[0] + Math.cos(rad) * len, p[1] + Math.sin(rad) * len);
  }

  // 2. Authentic Newborn Milk Spots (Milia) clustered on the nose tip, bridge, and alae
  // Each milium has: (1) a tiny warm-umber shadow crescent on the away-from-light side,
  // (2) a creamy-ivory dome, and (3) a crisp pearly-white pinpoint highlight on top.
  const miliaCount = 58;
  for (let i = 0; i < miliaCount; i++) {
    // Cluster most densely over the rounded bulb and lower bridge of the nose
    let u = randomGaussian(0.0, 0.058);
    let v = randomGaussian(-0.175, 0.052);
    u = constrain(u, -0.135, 0.135);
    v = constrain(v, -0.245, -0.03);

    // Compute exact surface depth w on the nose SDF
    let w = 0.80;
    for (let s = 0; s < 10; s++) {
      let d = sdfNewborn(u, v, w);
      w += d;
    }

    let p = headToScreen(u, v, w);
    let r = sampleRelief(p[0], p[1]);
    // Hyperreal detail lives ONLY in the light!
    if (r.hit < 0.5 || r.light < 0.26) continue;

    let spotSize = random(0.45, 0.92) * map(r.light, 0.26, 0.85, 0.7, 1.15, true);

    // Step A: Tiny micro-shadow crescent on the lower-right (away from upper-left light)
    brush.set("subdermal_vein", "#7a3e2e", spotSize * 0.85);
    brush.line(p[0] + 0.9, p[1] + 1.4, p[0] + 2.4 * spotSize, p[1] + 0.4);

    // Step B: Warm pearly-cream sebaceous dome
    brush.set("chalk_specular", "#f5e3ce", spotSize * 0.95);
    brush.line(p[0] - 0.8 * spotSize, p[1] - 0.4 * spotSize, p[0] + 0.8 * spotSize, p[1] + 0.4 * spotSize);

    // Step C: Crisp pearly-white apex glint facing the upper-left light
    brush.set("chalk_specular", "#fffdf9", spotSize * 0.78);
    brush.line(p[0] - 0.7 * spotSize, p[1] - 0.6 * spotSize, p[0] + 0.2 * spotSize, p[1] - 0.1 * spotSize);
  }

  // A few scattered milia onto the illuminated adjacent malar cheek & chin button
  for (let i = 0; i < 18; i++) {
    let u = random(0.14, 0.34);
    let v = random(-0.24, -0.10);
    let w = 0.65;
    for (let s = 0; s < 8; s++) w += sdfNewborn(u, v, w);
    let p = headToScreen(u, v, w);
    let r = sampleRelief(p[0], p[1]);
    if (r.hit < 0.5 || r.light < 0.42) continue;

    let sz = random(0.4, 0.72);
    brush.set("subdermal_vein", "#874a38", sz * 0.75);
    brush.line(p[0] + 0.8, p[1] + 1.1, p[0] + 1.8 * sz, p[1] + 0.3);
    brush.set("chalk_specular", "#fffaf2", sz * 0.75);
    brush.line(p[0] - 0.5 * sz, p[1] - 0.5 * sz, p[0] + 0.3 * sz, p[1]);
  }
}

// ============================================================================
// STEP 6d: PLUMP CURLED FIST KNUCKLES, CREASES & SOFT HIGHLIGHTS
// ============================================================================
function renderCurledFistDetails() {
  // 1. Deep warm sanguine-umber creases between the curled fingers and thumb
  const fingerCreases = [
    // Between thumb and index finger
    [[-0.08, -1.00, 0.74], [-0.04, -0.94, 0.79], [0.01, -0.98, 0.72]],
    // Between index and middle finger
    [[0.07, -1.04, 0.67], [-0.01, -0.91, 0.80], [0.02, -0.99, 0.67]],
    // Between middle and ring finger
    [[0.18, -1.09, 0.66], [0.09, -0.95, 0.78], [0.13, -1.03, 0.66]],
    // Between ring and pinky finger
    [[0.28, -1.15, 0.61], [0.20, -1.02, 0.73], [0.23, -1.09, 0.62]],
    // Chubby wrist fold
    [[0.04, -1.26, 0.56], [0.18, -1.30, 0.54], [0.32, -1.33, 0.46]]
  ];

  for (let crease of fingerCreases) {
    let pts = crease.map((c, idx) => {
      let p = headToScreen(c[0], c[1], c[2]);
      return [p[0], p[1], idx === 1 ? 0.95 : 0.4];
    });
    brush.set("velvet_charcoal", "#4f2119", 0.65);
    brush.spline(pts, 0.5);
    brush.set("skin_pore", "#2b100c", 0.6);
    brush.spline(pts, 0.5);
  }

  // 2. Luminous flesh highlights & knuckle dimples on the light-catching tops of the curled fingers
  for (let i = 0; i < 280; i++) {
    let u = random(-0.12, 0.34);
    let v = random(-1.26, -0.88);
    let w = 0.65;
    for (let s = 0; s < 10; s++) w += sdfNewborn(u, v, w);

    let p = headToScreen(u, v, w);
    let r = sampleRelief(p[0], p[1]);
    if (r.hit < 0.45 || r.light < 0.18) continue;

    let ang = (Math.atan2(r.nx, -r.ny) * 180) / Math.PI + random(-12, 12);
    let rad = (ang * Math.PI) / 180;
    let len = random(6, 14);

    let col;
    if (r.light > 0.52) {
      col = random(["#f7e6d2", "#edd5bc", "#fcf0e3"]);
    } else if (r.light > 0.32) {
      col = r.sss > 0.32 ? random(["#d98c75", "#cf7e67"]) : random(["#d6b396", "#c7a183"]);
    } else {
      col = random(["#8f4a38", "#783d2e", "#663528"]);
    }

    brush.set("skin_pore", col, random(0.45, 0.82));
    brush.line(p[0] - Math.cos(rad) * len * 0.5, p[1] - Math.sin(rad) * len * 0.5, p[0] + Math.cos(rad) * len * 0.5, p[1] + Math.sin(rad) * len * 0.5);
  }

  // 3. Tiny translucent newborn fingernail hints on the tucked thumb & index tip
  const nails = [
    { u: -0.02, v: -0.95, w: 0.81, ang: -15 },
    { u: -0.04, v: -0.96, w: 0.72, ang: 25 },
    { u: 0.06, v: -0.98, w: 0.73, ang: 28 }
  ];
  for (let n of nails) {
    let p = headToScreen(n.u, n.v, n.w);
    let r = sampleRelief(p[0], p[1]);
    if (r.light < 0.25) continue;
    brush.set("chalk_specular", "#faece0", 0.55);
    let rad = (n.ang * Math.PI) / 180;
    brush.line(p[0] - Math.cos(rad) * 3.5, p[1] - Math.sin(rad) * 3.5, p[0] + Math.cos(rad) * 3.5, p[1] + Math.sin(rad) * 3.5);
  }
}

// ============================================================================
// STEP 6e: HYPERREAL DOWNY HAIR (LANUGO) ON THE TEMPLE & FOREHEAD
// ============================================================================
function renderTempleLanugo() {
  // Natural swirling hairline & temporal lanugo stream field across the temple (u: 0.15..0.75, v: 0.05..0.75)
  const hairCount = 520;

  for (let i = 0; i < hairCount; i++) {
    // Concentrate on the temple, lateral forehead, and upper cheek border
    let u = random(0.08, 0.78);
    let v = random(-0.02, 0.78);

    // Exclude the immediate eye socket area
    if (Math.hypot(u - 0.30, v - 0.02) < 0.22) continue;

    // Snap to the 3D cranium/temple surface
    let w = 0.45;
    for (let s = 0; s < 10; s++) {
      let d = sdfNewborn(u, v, w);
      w += d;
    }

    let p0 = headToScreen(u, v, w);
    let r = sampleRelief(p0[0], p0[1]);
    if (r.hit < 0.2) continue;

    // Compute natural swirling lanugo direction in (u, v) space
    // Flows down from crown, sweeping around the temple in a gentle S-curve toward the upper cheek/ear
    let swirlAngle = -105 - 45 * Math.sin((u - 0.25) * 3.5) + 25 * (v - 0.35) + (noise(u * 6, v * 6) - 0.5) * 28;
    let stepLen = random(0.022, 0.048);

    let pts = [];
    let cu = u, cv = v, cw = w;
    let valid = true;

    for (let s = 0; s <= 4; s++) {
      let t = s / 4;
      let sp = headToScreen(cu, cv, cw);
      let press = s === 0 ? 0.2 : (s === 4 ? 0.05 : 0.85 * (1 - t * 0.4));
      pts.push([sp[0], sp[1], press]);

      let rad = ((swirlAngle + s * 6) * Math.PI) / 180;
      cu += Math.cos(rad) * stepLen;
      cv += Math.sin(rad) * stepLen;
      for (let k = 0; k < 4; k++) cw += sdfNewborn(cu, cv, cw);
    }

    let L = r.light;

    // Color depends on whether the downy hair is in shadow transition or catching raking light
    let col, weight;
    if (L > 0.48) {
      // Catching direct raking light on the temple: luminous pale champagne/flaxen silk!
      col = random() < 0.45
        ? random(["#faecd8", "#fff5e6", "#f2dfc4"])
        : random(["#dec29e", "#cfb08a", "#e8cfaecc"]);
      weight = random(0.45, 0.82);
    } else if (L > 0.22) {
      // Midtone temple & hairline transition: warm golden-ochre & raw umber down
      col = random(["#a68462", "#8f6e4f", "#ba9875", "#785a3f"]);
      weight = random(0.42, 0.75);
    } else if (L > 0.07) {
      // Melting into smoky shadow: soft dark umber-charcoal wisps
      col = random(["#4a382b", "#382a20", "#5c4636", "#291f19"]);
      weight = random(0.45, 0.85);
    } else {
      continue;
    }

    brush.set("lanugo_silk", col, weight);
    brush.spline(pts, 0.55);
  }

  // Also add ultra-delicate golden-white vellus down along the sunlit upper forehead contour
  // where the skin meets the hazy grey-blue Leonardo landscape!
  for (let i = 0; i < 95; i++) {
    let u = random(-0.42, 0.12);
    let v = random(0.35, 0.72);
    let w = 0.45;
    for (let s = 0; s < 10; s++) w += sdfNewborn(u, v, w);

    let p0 = headToScreen(u, v, w);
    let r = sampleRelief(p0[0], p0[1]);
    if (r.hit < 0.2 || r.rim > 0.48 || r.light < 0.35) continue;

    let ang = ROLL_DEG - 65 + random(-18, 18);
    let rad = (ang * Math.PI) / 180;
    let len = random(8, 18);
    let p1 = [p0[0] + Math.cos(rad) * len * 0.5, p0[1] + Math.sin(rad) * len * 0.5];
    let p2 = [p0[0] + Math.cos(rad) * len, p0[1] + Math.sin(rad) * len];

    brush.set("lanugo_silk", random(["#f7e7d2", "#e8d2b5", "#fff4e4"]), random(0.4, 0.68));
    brush.spline([
      [p0[0], p0[1], 0.75],
      [p1[0], p1[1], 0.45],
      [p2[0], p2[1], 0.05]
    ], 0.5);
  }
}

// ============================================================================
// STEP 7: FINAL ATMOSPHERIC SFUMATO VEIL & HIGH-CONTRAST COHESION
// ============================================================================
function renderFinalSfumatoVeil() {
  // 1. Crisp micro-highlights on the highest illuminated reliefs (forehead boss, upper cheek, brow ridge)
  for (let i = 0; i < 180; i++) {
    let px = random(320, 740);
    let py = random(260, 860);
    let r = sampleRelief(px, py);
    if (r.hit < 0.6 || r.light < 0.66) continue;

    let ang = (Math.atan2(r.nx, -r.ny) * 180) / Math.PI + random(-8, 8);
    let rad = (ang * Math.PI) / 180;
    let len = random(5, 11);
    let col = r.light > 0.76 ? "#fff8ef" : "#f5e4d0";
    brush.set("skin_pore", col, random(0.4, 0.7));
    brush.line(px - Math.cos(rad) * len * 0.5, py - Math.sin(rad) * len * 0.5, px + Math.cos(rad) * len * 0.5, py + Math.sin(rad) * len * 0.5);
  }

  // 2. Final smoky sfumato veil around the perimeter and shadow transitions so the entire image breathes
  for (let i = 0; i < 320; i++) {
    let px = random(20, 1180);
    let py = random(20, 1180);
    let r = sampleRelief(px, py);

    // Keep the brightly lit focal features completely crisp and untouched!
    if (r.hit > 0.3 && r.light > 0.18 && r.rim > 0.32) continue;

    let diag = (px * 0.68 + py * 0.73) / 1200;
    let col;
    if (px < 560 && py < 520 && r.hit < 0.2) {
      // Misty grey-blue atmospheric whisper in upper-left
      col = random(["#637582", "#4e5f6b", "#7a8c99"]);
    } else if (r.hit > 0.1 && r.rim <= 0.32) {
      // Dissolve contour edge
      col = r.light > 0.2 ? "#594c45" : "#211b1c";
    } else {
      // Deep velvety charcoal shadow
      col = diag > 0.65 ? random(["#0f0d10", "#161316", "#1d181b"]) : random(["#1f1a1c", "#292120"]);
    }

    let ang = random(-25, 65);
    let rad = (ang * Math.PI) / 180;
    let len = random(55, 125);
    brush.set("sfumato_clouds", col, random(0.55, 1.15));
    brush.line(px - Math.cos(rad) * len * 0.5, py - Math.sin(rad) * len * 0.5, px + Math.cos(rad) * len * 0.5, py + Math.sin(rad) * len * 0.5);
  }
}

