// ============================================================================
// GEOMETRY & BRUSH HELPERS
// ============================================================================

function fillShape(pts, col, opacity = 140, bleed = 0.12, tex = 0.45, border = 0.25, curv = 0.15) {
  brush.noStroke();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function washShape(pts, col, opacity = 180, curv = 0.1) {
  brush.noStroke();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function hatchShape(pts, brushName, col, weight, dist, angle, opts = { rand: 0.03 }, curv = 0.05) {
  brush.noStroke();
  brush.noFill();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

function strokeShape(pts, brushName, col, weight, close = true, curv = 0.15) {
  brush.noFill();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
}

// Draws Petra Sancta Or (Gold) tincture code: ochre washes + ink hatching + stipple dots
function renderOrTincture(pts, baseAngle = 35, density = 4.5, stippleCount = 90) {
  fillShape(pts, PAL.ochreBright, 150, 0.08, 0.35, 0.2, 0.12);
  hatchShape(pts, "engraver", PAL.ochreDeep, 0.45, density, baseAngle, { rand: 0.02, gradient: 0.35 });
  hatchShape(pts, "engraver", PAL.sableMid, 0.32, density * 1.4, baseAngle + 75, { rand: 0.02, gradient: 0.5 });

  // Bounding box for Petra Sancta pointillé (stipple dots for Gold)
  let minX = 9999, minY = 9999, maxX = -9999, maxY = -9999;
  for (let p of pts) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
  }
  brush.set("rotring", PAL.sableInk, 0.45);
  let tries = 0;
  let placed = 0;
  while (placed < stippleCount && tries < stippleCount * 4) {
    tries++;
    let rx = random(minX + 3, maxX - 3);
    let ry = random(minY + 3, maxY - 3);
    if (pointInPoly(rx, ry, pts)) {
      brush.line(rx, ry, rx + 0.8, ry + 0.8);
      placed++;
    }
  }
}

function pointInPoly(x, y, vs) {
  let inside = false;
  for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
    let xi = vs[i][0], yi = vs[i][1];
    let xj = vs[j][0], yj = vs[j][1];
    let intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi + 0.0001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

