  for (let side of [-1, 1]) {
    for (let lobe of lobes) {
      let pts = lobe.pts.map(p => [side === -1 ? p[0] : 1200 - p[0], p[1]]);

      if (lobe.type === "gold") {
        renderOrTincture(pts, side === -1 ? lobe.angle : 180 - lobe.angle, 4.2, 65);
        strokeShape(pts, "rotring", PAL.sableInk, 0.55, true, 0.08);
      } else if (lobe.type === "vellum") {
        // Bare vellum (Argent) with delicate bistre shadow hatching at base
        hatchShape(pts, "engraver", PAL.sableSoft, 0.32, 4.5, side === -1 ? lobe.angle : 180 - lobe.angle, {
          rand: 0.02,
          gradient: 0.65
        }, 0.08);
        strokeShape(pts, "rotring", PAL.sableInk, 0.5, true, 0.08);
      } else if (lobe.type === "crimson") {
        // 1. Deep crimson & vermilion watercolor base washes
        fillShape(pts, PAL.vermilionMid, 165, 0.1, 0.45, 0.3, 0.08);
        fillShape(pts, PAL.vermilionDeep, 95, 0.08, 0.5, 0.35, 0.08);

        // 2. Petra Sancta Gules vertical ink lines in shadow zones + diagonal form hatching
        hatchShape(pts, "engraver", PAL.vermilionDark, 0.36, 3.6, 90, { rand: 0.02, gradient: 0.45 }, 0.06);
        hatchShape(pts, "engraver", PAL.sableInk, 0.3, 5.2, side === -1 ? 25 : 155, { rand: 0.03, gradient: 0.6 }, 0.06);

        // 3. Crumpled silk ridge highlights (sharp angular specular facets on crimson taffeta)
        if (lobe.ridges) {
          for (let r of lobe.ridges) {
            let rPts = r.map(p => [side === -1 ? p[0] : 1200 - p[0], p[1]]);
            // Broad vermilion-coral highlight band
            brush.set("silkGlaze", PAL.vermilionLight, 1.35);
            brush.spline(rPts, 0.15);
            // Crisp sharp silk crease glint
            brush.set("cpencil", PAL.vermilionSilk, 0.75);
            brush.spline(rPts, 0.12);
            // Cross-facet crinkle ticks along the ridge
            brush.set("engraver", PAL.vermilionSilk, 0.38);
            for (let k = 0; k < rPts.length - 1; k++) {
              let mx = (rPts[k][0] + rPts[k + 1][0]) * 0.5;
              let my = (rPts[k][1] + rPts[k + 1][1]) * 0.5;
              brush.line(mx - side * 8, my - 5, mx + side * 6, my + 4);
              brush.line(rPts[k][0] - side * 6, rPts[k][1] - 3, rPts[k][0] + side * 5, rPts[k][1] + 4);
            }
          }
        }

        // 4. Deep garnet valley creases
        if (lobe.valleys) {
          for (let v of lobe.valleys) {
            let vPts = v.map(p => [side === -1 ? p[0] : 1200 - p[0], p[1]]);
            brush.set("silkGlaze", PAL.vermilionDark, 1.1);
            brush.spline(vPts, 0.15);
            brush.set("rotring", PAL.sableDeep, 0.55);
            brush.spline(vPts, 0.12);
          }
        }

        // 5. Crisp outline of silk fold
        strokeShape(pts, "rotring", PAL.sableInk, 0.6, true, 0.08);
      }
    }

    // Tassels & gilded silk cords hanging from mantling tips
    const tasselPts = [[95, 465], [145, 585], [92, 318]];
    for (let tp of tasselPts) {
      let tx = side === -1 ? tp[0] : 1200 - tp[0];
      let ty = tp[1];
      drawGoldTassel(tx, ty, side * 12);
    }
  }
}

function drawGoldTassel(x, y, tilt) {
  brush.set("rotring", PAL.ochreDeep, 0.6);
  brush.line(x, y, x + tilt * 0.5, y + 18);
  let knot = [
    [x + tilt * 0.5 - 6, y + 16],
    [x + tilt * 0.5 + 6, y + 16],
    [x + tilt * 0.8 + 10, y + 36],
    [x + tilt * 0.8 - 10, y + 36]
  ];
  renderOrTincture(knot, 45, 3.0, 18);
  brush.set("engraver", PAL.sableInk, 0.38);
  for (let i = -8; i <= 8; i += 2.5) {
    brush.line(x + tilt * 0.6 + i * 0.6, y + 20, x + tilt * 0.9 + i, y + 37);
  }
  brush.set("rotring", PAL.ochreLight, 0.45);
  brush.circle(x + tilt * 0.5, y + 16, 4.5, 0.1);
  brush.set("rotring", PAL.sableInk, 0.45);
  brush.circle(x + tilt * 0.5, y + 16, 4.5, 0.1);
}

// ============================================================================
// 3. SOVEREIGN BARRED HELM, TORSE & CREST
// ============================================================================

function drawHelmAndCrest() {
  // --- A. HERALDIC CREST (Fan of Iridescent Sickle Plumes + Golden Sunburst + Crowned Pomegranate) ---
  // Golden glory rays behind the crest (Or tincture hatching)
  for (let a = -155; a <= -25; a += 8) {
    let rad = (a * PI) / 180;
    let r1 = 42;
    let r2 = (a % 16 === 0) ? 102 : 78;
    let x1 = CX + cos(rad) * r1;
    let y1 = 152 + sin(rad) * r1;
    let x2 = CX + cos(rad) * r2;
    let y2 = 152 + sin(rad) * r2;
    brush.set("cpencil", PAL.ochreBright, 0.7);
    brush.line(x1, y1, x2, y2);
    brush.set("engraver", PAL.sableMid, 0.32);
    brush.line(x1 + 1.5, y1, x2 + 1.5, y2);
  }

  // Symmetrical crest fan of rooster sickle feathers
  for (let side of [-1, 1]) {
    const crestAngles = [
      { ang: -90 + side * 14, len: 96, w: 18, curv: side * 16, col: "bronze" },
      { ang: -90 + side * 28, len: 92, w: 19, curv: side * 24, col: "azure" },
      { ang: -90 + side * 44, len: 86, w: 18, curv: side * 30, col: "rust" },
      { ang: -90 + side * 60, len: 76, w: 17, curv: side * 34, col: "bronze" },
      { ang: -90 + side * 74, len: 64, w: 15, curv: side * 36, col: "rust" }
    ];
    for (let cf of crestAngles) {
      drawBarbedFeather(CX + side * 10, 192, cf.len, cf.w, cf.ang, cf.curv, cf.col, 1.0);
    }
  }

  // Central Crest Charge: Halved Garnet Pomegranate encircled by a golden coronet
  drawSlicedPomegranate(CX, 148, 36, 1, true);

  // --- B. TWISTED SILK TORSE (WREATH OF ARGENT & GULES) ---
  const torseY = 204;
  const torseW = 148;
  const numLinks = 6;
  const linkW = torseW / numLinks;
  for (let i = 0; i < numLinks; i++) {
    let lx = CX - torseW / 2 + i * linkW;
    let isGules = i % 2 === 1;
    let pts = [
      [lx + 2, torseY + 4],
      [lx + linkW * 0.45, torseY - 9],
      [lx + linkW + 2, torseY - 4],
      [lx + linkW - 2, torseY + 12],
      [lx + linkW * 0.55, torseY + 17],
      [lx - 2, torseY + 12]
    ];
    if (isGules) {
      fillShape(pts, PAL.vermilionMid, 175, 0.05, 0.4, 0.2, 0.2);
      hatchShape(pts, "engraver", PAL.vermilionDark, 0.35, 2.8, 90, { rand: 0.02 });
      brush.set("cpencil", PAL.vermilionSilk, 0.65);
      brush.line(lx + 6, torseY - 3, lx + linkW - 5, torseY + 2);
    } else {
      // Bare vellum (Argent) link with curved ink engraving
      hatchShape(pts, "engraver", PAL.sableMid, 0.32, 3.2, 55, { rand: 0.02, gradient: 0.65 });
      brush.set("cpencil", PAL.vellumSpec, 0.7);
      brush.line(lx + 6, torseY - 3, lx + linkW - 5, torseY + 2);
    }
    strokeShape(pts, "rotring", PAL.sableInk, 0.55, true, 0.2);
  }

  // --- C. FRONTAL SOVEREIGN BARRED HELM (ARGENT STEEL, SABLE OCULARIUM & OR GRILLE) ---
  // Skull & Gorget of the helm (Argent bare vellum + steel engraving hatch lines)
  const helmPts = [
    [CX - 64, 214],
    [CX + 64, 214],
    [CX + 78, 250],
    [CX + 72, 298],
    [CX + 96, 338],
    [CX + 52, 356],
    [CX, 362],
    [CX - 52, 356],
    [CX - 96, 338],
    [CX - 72, 298],
    [CX - 78, 250]
  ];
  // Leave skull center bare vellum (Argent), shade flanks with dense steel engraving
  const leftHelmShade = [
    [CX - 64, 214], [CX - 25, 214], [CX - 32, 358], [CX - 96, 338], [CX - 72, 298], [CX - 78, 250]
  ];
  const rightHelmShade = [
    [CX + 64, 214], [CX + 25, 214], [CX + 32, 358], [CX + 96, 338], [CX + 72, 298], [CX + 78, 250]
  ];
  fillShape(leftHelmShade, PAL.vellumDark, 85, 0.1, 0.4, 0.2, 0.15);
  fillShape(rightHelmShade, PAL.vellumDark, 85, 0.1, 0.4, 0.2, 0.15);
  hatchShape(leftHelmShade, "engraver", PAL.sableMid, 0.35, 3.4, 18, { rand: 0.02, gradient: 0.4 });
  hatchShape(rightHelmShade, "engraver", PAL.sableMid, 0.35, 3.4, 162, { rand: 0.02, gradient: 0.4 });

  // Deep Sable Visor Cavity (Ocularium)
  const visorPts = [
    [CX - 62, 252],
    [CX, 244],
    [CX + 62, 252],
    [CX + 56, 304],
    [CX, 316],
    [CX - 56, 304]
  ];
  washShape(visorPts, PAL.sableDeep, 235, 0.15);
  hatchShape(visorPts, "engraver", PAL.sableDeep, 0.45, 2.5, 0);
  hatchShape(visorPts, "engraver", PAL.sableDeep, 0.45, 2.5, 90);

  // Golden Shoulder Trim & Gorget Collar (Or tincture)
  const gorgetRim = [
    [CX - 96, 338], [CX - 52, 356], [CX, 362], [CX + 52, 356], [CX + 96, 338],
    [CX + 86, 324], [CX, 346], [CX - 86, 324]
  ];
  renderOrTincture(gorgetRim, 45, 3.5, 45);
  strokeShape(gorgetRim, "rotring", PAL.sableInk, 0.55, true, 0.12);

  // 7 Sovereign Golden Visor Bars (Or) curving vertically over the dark visor
  const barOffsets = [-48, -32, -16, 0, 16, 32, 48];
  for (let bo of barOffsets) {
    let bxTop = CX + bo * 0.92;
    let bxMid = CX + bo * 1.12;
    let bxBot = CX + bo * 0.85;
    let yTop = 244 + abs(bo) * 0.15;
    let yBot = 315 - abs(bo) * 0.22;

    brush.set("cpencil", PAL.ochreDeep, 2.2);
    brush.spline([[bxTop, yTop], [bxMid, (yTop + yBot) * 0.5], [bxBot, yBot]], 0.3);
    brush.set("cpencil", PAL.ochreLight, 1.1);
    brush.spline([[bxTop - 1, yTop], [bxMid - 1, (yTop + yBot) * 0.5], [bxBot - 1, yBot]], 0.3);
    brush.set("rotring", PAL.sableInk, 0.42);
    brush.spline([[bxTop - 2.5, yTop], [bxMid - 2.5, (yTop + yBot) * 0.5], [bxBot - 2.5, yBot]], 0.3);
    brush.spline([[bxTop + 2.5, yTop], [bxMid + 2.5, (yTop + yBot) * 0.5], [bxBot + 2.5, yBot]], 0.3);
    // Gold rivets at top and bottom of each bar
    brush.set("rotring", PAL.ochreSpec, 0.55);
    brush.circle(bxTop, yTop, 2.2, 0.05);
    brush.circle(bxBot, yBot, 2.2, 0.05);
  }

  // Helm outline & central medial ridge
  strokeShape(helmPts, "rotring", PAL.sableInk, 0.7, true, 0.15);
  brush.set("rotring", PAL.sableInk, 0.55);
  brush.line(CX, 214, CX, 362);
  brush.set("cpencil", PAL.vellumSpec, 0.8);
  brush.line(CX - 2, 216, CX - 2, 244);
  brush.line(CX - 2, 316, CX - 2, 344);
}

// ============================================================================
// 4. QUARTERED SHIELD (ESCUTCHEON) WITH HYPERREAL SLICED POMEGRANATES
// ============================================================================

function getShieldContour(inset = 0) {
  let L = 390 + inset;
  let R = 810 - inset;
  let T = 350 + inset;
  let B = 856 - inset * 1.15;
  return [
    [L, T],
    [CX, T + 6],
    [R, T],
    [R, 575],
    [R - 14, 658],
    [R - 58, 738],
    [R - 125, 805],
    [CX, B],
    [L + 125, 805],
    [L + 58, 738],
    [L + 14, 658],
    [L, 575]
  ];
}

function drawQuarteredShield() {
  const outerShield = getShieldContour(-14);
  const innerShield = getShieldContour(0);
  const midY = 584;

  // 1. Beveled Gold (Or) Outer Escutcheon Rim with Petra Sancta stippling & cross-hatching
  renderOrTincture(outerShield, 45, 4.2, 220);
  strokeShape(outerShield, "rotring", PAL.sableDeep, 0.85, true, 0.08);

  // 2. Define the 4 Quarters inside `innerShield`
  // Q1: Top-Left (Argent — Bare Vellum)
  const q1Pts = [
    [390, 350], [CX, 356], [CX, midY], [390, midY]
  ];
  // Q2: Top-Right (Azure — Muted Prussian Blue + Horizontal Petra Sancta Engraving)
  const q2Pts = [
    [CX, 356], [810, 350], [810, midY], [CX, midY]
  ];
  // Q3: Bottom-Left (Azure — Muted Prussian Blue + Horizontal Petra Sancta Engraving)
  const q3Pts = [
    [390, midY], [CX, midY], [CX, 856], [515, 805], [448, 738], [404, 658]
  ];
  // Q4: Bottom-Right (Argent — Bare Vellum)
  const q4Pts = [
    [CX, midY], [810, midY], [796, 658], [752, 738], [685, 805], [CX, 856]
  ];

  // Render Q1 & Q4 as Bare Vellum (Argent) — wipe clean to vellumBg, add only recessed border shadow
  washShape(q1Pts, PAL.vellumBg, 255, 0.02);
  washShape(q4Pts, PAL.vellumBg, 255, 0.02);

  // Subtle recessed cast shadow along top & left of Argent quarters
  hatchShape([
    [390, 350], [CX, 356], [CX, 372], [406, 368], [406, midY], [390, midY]
  ], "engraver", PAL.sableSoft, 0.32, 3.2, 45, { rand: 0.01 });
  hatchShape([
    [CX, midY], [810, midY], [808, midY + 15], [CX + 15, midY + 15], [CX + 15, 845], [CX, 856]
  ], "engraver", PAL.sableSoft, 0.32, 3.2, 45, { rand: 0.01 });

  // Render Q2 & Q3 as Heraldic Azure (Muted Prussian wash + strict Horizontal Petra Sancta lines)
  for (let qPts of [q2Pts, q3Pts]) {
    washShape(qPts, PAL.azureDeep, 225, 0.04);
    fillShape(qPts, PAL.azureMid, 120, 0.06, 0.45, 0.3, 0.04);
    // Petra Sancta code for Azure: strict horizontal parallel ink lines (angle = 0)
    hatchShape(qPts, "engraver", PAL.azureDark, 0.42, 3.4, 0, { rand: 0.01 }, 0.04);
    // Subtle inner golden fillet line inside the Azure quarters
    strokeShape(qPts, "cpencil", PAL.ochreBright, 0.55, true, 0.04);
  }

  // Quartering division cross-bars (Golden fillet fess & pale lines)
  const paleBar = [[CX - 4, 356], [CX + 4, 356], [CX + 4, 856], [CX - 4, 856]];
  const fessBar = [[390, midY - 4], [810, midY - 4], [810, midY + 4], [390, midY + 4]];
  renderOrTincture(paleBar, 45, 3.0, 25);
  renderOrTincture(fessBar, 45, 3.0, 25);
  strokeShape(paleBar, "rotring", PAL.sableInk, 0.45, true, 0.02);
  strokeShape(fessBar, "rotring", PAL.sableInk, 0.45, true, 0.02);
  strokeShape(innerShield, "rotring", PAL.sableDeep, 0.75, true, 0.08);

  // Rivets around the golden shield border
  const rimPts = getShieldContour(-7);
  for (let i = 0; i < rimPts.length; i++) {
    let p1 = rimPts[i];
    let p2 = rimPts[(i + 1) % rimPts.length];
    for (let t = 0.2; t <= 0.8; t += 0.3) {
      let rx = lerp(p1[0], p2[0], t);
      let ry = lerp(p1[1], p2[1], t);
      brush.set("rotring", PAL.sableInk, 0.4);
      brush.circle(rx, ry, 2.8, 0.05);
      brush.set("cpencil", PAL.ochreSpec, 0.5);
      brush.line(rx - 1, ry - 1, rx + 0.5, ry - 0.5);
    }
  }

  // 3. Draw the 4 Hyperreal Sliced Pomegranates in the 4 Quarters
  // Q1 (Top-Left on Bare Vellum)
  drawSlicedPomegranate(494, 472, 74, -1, false);
  // Q2 (Top-Right on Azure)
  drawSlicedPomegranate(706, 472, 74, 1, false);
  // Q3 (Bottom-Left on Azure)
  drawSlicedPomegranate(506, 692, 66, -1, false);
  // Q4 (Bottom-Right on Bare Vellum)
  drawSlicedPomegranate(694, 692, 66, 1, false);
}

// ============================================================================
// HYPERREAL SLICED POMEGRANATE ENGINE (GARNET ARILS, PITH, CALYX & LEAVES)
// ============================================================================

function drawSlicedPomegranate(cx, cy, r, dir = 1, isCrest = false) {
  // 1. Heraldic Pair of Stiff Leaves & Woody Twigs at the Base
  for (let s of [-1, 1]) {
    let lPts = [
      [cx, cy + r * 0.88],
      [cx + s * r * 0.45, cy + r * 0.78],
      [cx + s * r * 0.92, cy + r * 0.98],
      [cx + s * r * 0.52, cy + r * 1.12]
    ];
    fillShape(lPts, PAL.azureIridescent, 165, 0.05, 0.4, 0.2, 0.15);
    hatchShape(lPts, "engraver", PAL.sableInk, 0.35, 2.8, s === -1 ? 30 : 150);
    strokeShape(lPts, "rotring", PAL.sableInk, 0.45, true, 0.15);
    // Golden midrib vein
    brush.set("cpencil", PAL.ochreLight, 0.55);
    brush.line(cx, cy + r * 0.92, cx + s * r * 0.82, cy + r * 0.98);
  }

  // Drop shadow on shield beneath the fruit
  let shadowPts = [];
  for (let a = 0; a < 360; a += 20) {
    let rad = (a * PI) / 180;
    shadowPts.push([cx + 4 + cos(rad) * r * 0.98, cy + 6 + sin(rad) * r * 0.95]);
  }
  fillShape(shadowPts, PAL.sableMid, 55, 0.2, 0.4, 0.2, 0.2);

  // 2. Crowned Calyx at Top of Pomegranate (5 leathery rust-and-gold spikes + dry stamens)
  const calyxY = cy - r * 0.86;
  const calyxPts = [
    [cx - r * 0.26, calyxY + r * 0.14],
    [cx - r * 0.36, calyxY - r * 0.18],
    [cx - r * 0.18, calyxY - r * 0.04],
    [cx - r * 0.12, calyxY - r * 0.26],
    [cx, calyxY - r * 0.08],
    [cx + r * 0.12, calyxY - r * 0.26],
    [cx + r * 0.18, calyxY - r * 0.04],
    [cx + r * 0.36, calyxY - r * 0.18],
    [cx + r * 0.26, calyxY + r * 0.14]
  ];
  fillShape(calyxPts, PAL.rustMid, 185, 0.05, 0.4, 0.2, 0.05);
  renderOrTincture(calyxPts, 60, 3.0, 22);
  // Dry stamen threads inside the calyx crown
  brush.set("engraver", PAL.sableInk, 0.35);
  for (let i = -4; i <= 4; i++) {
    let sx = cx + i * r * 0.045;
    brush.line(sx, calyxY - r * 0.05, sx + i * 1.5, calyxY - r * 0.22);
    brush.circle(sx + i * 1.5, calyxY - r * 0.23, 1.1, 0.05);
  }
  strokeShape(calyxPts, "rotring", PAL.sableInk, 0.5, true, 0.05);

  // 3. Leathery Outer Rind (Exocarp) — Slightly lobed organic sphere
  let rindPts = [];
  for (let a = 0; a < 360; a += 15) {
    let rad = (a * PI) / 180;
    // Slight hexagonal/organic lobing characteristic of real pomegranates
    let lobeMod = 1.0 + 0.035 * cos(rad * 6) + 0.02 * sin(rad * 3);
    rindPts.push([cx + cos(rad) * r * lobeMod, cy + sin(rad) * r * 0.96 * lobeMod]);
  }
  fillShape(rindPts, PAL.vermilionMid, 195, 0.06, 0.5, 0.35, 0.2);
  fillShape(rindPts, PAL.ochreMid, 80, 0.08, 0.45, 0.2, 0.2);
  hatchShape(rindPts, "engraver", PAL.vermilionDark, 0.36, 3.2, 35, { rand: 0.03, gradient: 0.45 });

  // 4. Creamy Spongy Pith (Mesocarp — Bare Vellum / Ivory tone)
  let pithPts = [];
  for (let a = 0; a < 360; a += 15) {
    let rad = (a * PI) / 180;
    let lobeMod = 0.87 + 0.03 * cos(rad * 5 + dir);
    pithPts.push([cx + cos(rad) * r * lobeMod, cy + sin(rad) * r * 0.84 * lobeMod]);
  }
  washShape(pithPts, PAL.vellumBg, 250, 0.18);
  fillShape(pithPts, PAL.vellumWarm, 110, 0.06, 0.5, 0.3, 0.18);

  // Fine spongy stipple texture on the cut pith ring
  brush.set("engraver", PAL.ochreDeep, 0.32);
  for (let a = 0; a < 360; a += 5) {
    let rad = (a * PI) / 180;
    let pr = r * random(0.76, 0.86);
    let px = cx + cos(rad) * pr;
    let py = cy + sin(rad) * pr * 0.96;
    brush.line(px, py, px + 0.7, py + 0.7);
  }
  strokeShape(rindPts, "rotring", PAL.sableDeep, 0.6, true, 0.2);
  strokeShape(pithPts, "engraver", PAL.rustMid, 0.38, true, 0.18);

  // 5. Internal Seed Chambers (Locules) packed with Glistening Garnet Arils
  // 5 asymmetrical chambers separated by thin creamy pith septa membranes
  const chamberAngles = [
    [-82, -18],
    [-8, 56],
    [66, 130],
    [140, 204],
    [214, 268]
  ];

  // Dark garnet-cabernet cavity background inside each chamber
  for (let [aStart, aEnd] of chamberAngles) {
    let chPts = [[cx + cos(((aStart + aEnd) * 0.5 * PI) / 180) * r * 0.12, cy + sin(((aStart + aEnd) * 0.5 * PI) / 180) * r * 0.12]];
    for (let a = aStart; a <= aEnd; a += 12) {
      let rad = (a * PI) / 180;
      chPts.push([cx + cos(rad) * r * 0.77, cy + sin(rad) * r * 0.74]);
    }
    washShape(chPts, PAL.vermilionDark, 235, 0.15);
  }

  // Pack individual faceted garnet arils into each chamber!
  const rings = isCrest ? [0.22, 0.44, 0.64] : [0.19, 0.35, 0.51, 0.66];
  const arilSizeBase = isCrest ? r * 0.115 : r * 0.088;

  for (let cIdx = 0; cIdx < chamberAngles.length; cIdx++) {
    let [aStart, aEnd] = chamberAngles[cIdx];
    for (let rIdx = 0; rIdx < rings.length; rIdx++) {
      let ringFrac = rings[rIdx];
      let span = aEnd - aStart;
      let count = max(2, floor((span * ringFrac) / (isCrest ? 15 : 10.5)));
      for (let k = 0; k < count; k++) {
        let t = (k + 0.5) / count;
        let ang = aStart + 4 + t * (span - 8) + sin(k * 2.3 + rIdx) * 2.5;
        let rad = (ang * PI) / 180;
        let distR = r * (ringFrac + sin(k * 3.7 + cIdx) * 0.025);
        let ax = cx + cos(rad) * distR;
        let ay = cy + sin(rad) * distR * 0.96;
        let aRad = arilSizeBase * (0.88 + 0.22 * sin(k * 1.9 + rIdx));

        drawGarnetAril(ax, ay, aRad, ang);
      }
    }
  }

  // 6. Central Columella (spongy vellum core star) & Thin Septa Membranes
  let corePts = [];
  for (let i = 0; i < 10; i++) {
    let ang = i * 36 - 85;
    let rad = (ang * PI) / 180;
    let cr = (i % 2 === 0) ? r * 0.18 : r * 0.09;
    corePts.push([cx + cos(rad) * cr, cy + sin(rad) * cr]);
  }
  washShape(corePts, PAL.vellumBg, 245, 0.1);
  strokeShape(corePts, "engraver", PAL.ochreDeep, 0.35, true, 0.1);

  // Creamy radial membrane veins between chambers
  for (let [aStart, aEnd] of chamberAngles) {
    let sepAng = ((aStart - 5) * PI) / 180;
    let mPts = [
      [cx + cos(sepAng) * r * 0.12, cy + sin(sepAng) * r * 0.12],
      [cx + cos(sepAng + 0.08 * dir) * r * 0.45, cy + sin(sepAng + 0.08 * dir) * r * 0.43],
      [cx + cos(sepAng) * r * 0.78, cy + sin(sepAng) * r * 0.75]
    ];
    brush.set("cpencil", PAL.vellumBg, 1.15);
    brush.spline(mPts, 0.25);
    brush.set("engraver", PAL.ochreMid, 0.32);
    brush.spline(mPts, 0.25);
  }
}

// Renders a single glistening garnet pomegranate aril (seed)
function drawGarnetAril(x, y, sz, angleDeg) {
  let rot = (angleDeg * PI) / 180;
  // 5-sided faceted jewel shape pointing slightly toward center
  let pts = [];
  const angles = [0, 68, 142, 218, 292];
  for (let i = 0; i < 5; i++) {
    let a = rot + (angles[i] * PI) / 180;
    let m = (i === 2 || i === 3) ? sz * 1.15 : sz * 0.92;
    pts.push([x + cos(a) * m, y + sin(a) * m]);
  }

  // 1. Deep ruby-crimson body
  washShape(pts, PAL.vermilionMid, 235, 0.12);

  // 2. Translucent glowing vermilion lower facet (internal light refraction)
  brush.set("cpencil", PAL.vermilionLight, 0.75);
  brush.line(x - sz * 0.2, y + sz * 0.35, x + sz * 0.35, y + sz * 0.2);

  // 3. Faint pale internal seed kernel
  brush.set("engraver", PAL.vermilionSilk, 0.35);
  brush.line(x - sz * 0.1, y + sz * 0.05, x + sz * 0.15, y + sz * 0.15);

  // 4. Crisp dark garnet outline separating packed arils
  strokeShape(pts, "engraver", PAL.vermilionDark, 0.36, true, 0.1);

  // 5. Pinpoint wet vellum-white specular highlight on upper-left facet
  brush.set("rotring", PAL.vellumSpec, 0.62);
  brush.line(x - sz * 0.38, y - sz * 0.32, x - sz * 0.08, y - sz * 0.38);
  brush.set("rotring", "#ffffff", 0.48);
  brush.line(x - sz * 0.28, y - sz * 0.30, x - sz * 0.16, y - sz * 0.33);
}

