function drawMottoInscription() {
  // Engraved Roman capitals along the scroll arc
  const motto = "ARDET · IN · AURORA · GRANATUM";
  const n = motto.length;
  brush.set("rotring", PAL.sableDeep, 0.58);

  for (let i = 0; i < n; i++) {
    let ch = motto[i];
    let t = (i - (n - 1) / 2) / ((n - 1) / 2); // -1 to 1
    let x = CX + t * 242;
    let y = 991 - t * t * 18;
    drawRomanGlyph(ch, x, y, 7.5, 15);
  }
}

function drawRomanGlyph(ch, x, y, w, h) {
  let l = x - w * 0.45;
  let r = x + w * 0.45;
  let t = y - h * 0.5;
  let b = y + h * 0.5;
  let m = y;

  if (ch === " ") return;
  if (ch === "·") {
    brush.set("rotring", PAL.vermilionMid, 0.7);
    brush.circle(x, m, 2.0, 0.05);
    brush.set("rotring", PAL.sableDeep, 0.58);
    return;
  }

  switch (ch) {
    case "A":
      brush.line(l, b, x, t);
      brush.line(x, t, r, b);
      brush.line(l + 1.5, m + 2, r - 1.5, m + 2);
      break;
    case "R":
      brush.line(l, b, l, t);
      brush.line(l, t, r - 1, t + 2);
      brush.line(r - 1, t + 2, l, m);
      brush.line(l + 1, m, r, b);
      break;
    case "D":
      brush.line(l, b, l, t);
      brush.spline([[l, t], [r, m], [l, b]], 0.4);
      break;
    case "E":
      brush.line(l, b, l, t);
      brush.line(l, t, r, t);
      brush.line(l, m, r - 1.5, m);
      brush.line(l, b, r, b);
      break;
    case "T":
      brush.line(x, b, x, t);
      brush.line(l, t, r, t);
      break;
    case "I":
      brush.line(x, b, x, t);
      brush.line(x - 2, t, x + 2, t);
      brush.line(x - 2, b, x + 2, b);
      break;
    case "N":
      brush.line(l, b, l, t);
      brush.line(l, t, r, b);
      brush.line(r, b, r, t);
      break;
    case "U":
      brush.spline([[l, t], [l, b - 2], [x, b], [r, b - 2], [r, t]], 0.3);
      break;
    case "O":
      brush.circle(x, m, w * 0.52, 0.08);
      break;
    case "G":
      brush.arc(x, m, w * 0.52, 35, 330);
      brush.line(x, m, r, m);
      brush.line(r, m, r, b - 2);
      break;
    case "M":
      brush.line(l, b, l, t);
      brush.line(l, t, x, b - 2);
      brush.line(x, b - 2, r, t);
      brush.line(r, t, r, b);
      break;
  }
}

