  // --- STEP 1: SCALED GOLDEN LEGS, SPURS & TALONS ---
  drawRoosterLegs(side, X, A);

  // --- STEP 2: CORE BODY UNDER-WASH (DEEP SABLE, RUST & BRONZE) ---
  const bodyUnderPts = [
    [X(352), 325],
    [X(382), 415],
    [X(395), 515],
    [X(382), 615],
    [X(335), 675],
