    { x: 272, y: 610, len: 210, w: 28, ang: 142, curv: -35, col: "azure" },
    { x: 274, y: 602, len: 222, w: 28, ang: 130, curv: -38, col: "bronze" },

    // High arching greater & lesser sickle plumes (sweeping up and cascading down)
    { x: 276, y: 594, len: 235, w: 26, ang: 175, curv: -55, col: "azure" },
    { x: 275, y: 588, len: 250, w: 27, ang: 188, curv: -62, col: "bronze" },
    { x: 274, y: 582, len: 262, w: 27, ang: 202, curv: -68, col: "rust" },
    { x: 276, y: 576, len: 272, w: 28, ang: 215, curv: -72, col: "azure" },
    { x: 278, y: 572, len: 265, w: 26, ang: 228, curv: -75, col: "bronze" },
    { x: 280, y: 568, len: 245, w: 25, ang: 242, curv: -72, col: "rust" },
    { x: 282, y: 566, len: 215, w: 23, ang: 255, curv: -65, col: "bronze" },

    // Cascading lower lesser sickles (hanger plumes)
    { x: 272, y: 608, len: 168, w: 22, ang: 135, curv: -45, col: "rust" },
    { x: 276, y: 600, len: 176, w: 22, ang: 148, curv: -48, col: "gold" },
    { x: 280, y: 592, len: 182, w: 22, ang: 162, curv: -52, col: "rust" },
    { x: 284, y: 585, len: 175, w: 21, ang: 178, curv: -54, col: "gold" }
