  for (let tp of tailPlumes) {
    drawBarbedFeather(X(tp.x), tp.y, tp.len, tp.w, A(tp.ang), -side * tp.curv, tp.col, 1.15);
  }

  // --- STEP 4: CASCADING SADDLE FEATHERS (LOWER BACK / RUMP) ---
  // Fiery lance-shaped rust and ochre-gold feathers overlapping the tail base
  for (let row = 0; row < 4; row++) {
    let numInRow = 5 + row;
    for (let k = 0; k < numInRow; k++) {
      let t = k / (numInRow - 1);
      let sx = 272 + row * 10 + t * 28;
      let sy = 562 + row * 16 + t * 18;
      let sAng = 122 + t * 38 + sin(k * 2.1 + row) * 5;
      let sLen = 68 - row * 6;
      let col = (k + row) % 2 === 0 ? "gold" : "rust";
      drawBarbedFeather(X(sx), sy, sLen, 14, A(sAng), -side * 18, col, 0.85);
    }
  }

  // --- STEP 5: FEATHERED THIGH & FLUFFY VENT COVERT PLUMES ---
  for (let r = 0; r < 4; r++) {
    for (let k = 0; k < 5; k++) {
      let tx = 305 + k * 14 - r * 4;
      let ty = 625 + r * 18 + k * 4;
      let tAng = 82 + k * 12;
      let col = (r + k) % 2 === 0 ? "bronze" : "rust";
      drawBarbedFeather(X(tx), ty, 44, 15, A(tAng), -side * 8, col, 0.75);
    }
  }

  // --- STEP 6: PUFFED RAMPANT BREAST & UNDERPARTS (Laced Bronze, Sable & Ochre-Gold) ---
  // Layered from lower belly up to upper chest so feathers overlap naturally like armor scales
  for (let row = 8; row >= 0; row--) {
    let yBase = 435 + row * 22;
    let xChestEdge = 382 + sin((row / 8) * PI) * 18;
    let xInward = 335 - sin((row / 8) * PI) * 12;
    let count = 5;
    for (let k = 0; k < count; k++) {
      let t = k / (count - 1);
      let bx = lerp(xInward, xChestEdge, t);
      let by = yBase + (1 - t) * 8;
      let bAng = lerp(95, 52, t);
      let bLen = 40 + sin((row / 8) * PI) * 8;
      let col = (row + k) % 3 === 0 ? "gold" : ((row + k) % 2 === 0 ? "bronze" : "rust");
      drawBarbedFeather(X(bx), by, bLen, 16, A(bAng), side * 10, col, 0.8);
    }
  }

  // --- STEP 7: FOLDED CEREMONIAL WING (PRIMARIES, SPECULUM & SHOULDER COVERTS) ---
  // 7A. Long stiff Primary & Secondary Flight Quills (extending down toward the tail base)
  for (let p = 0; p < 9; p++) {
    let px = 285 + p * 6.5;
    let py = 568 + p * 5.5;
    let pLen = 128 - p * 6;
    let pAng = 118 - p * 3.5;
    drawBarbedFeather(X(px), py, pLen, 15, A(pAng), -side * 8, p % 2 === 0 ? "gold" : "bronze", 0.95);
  }

  // 7B. Greater Wing Coverts (Iridescent Azure-Sable Speculum Wing-Bar)
  for (let g = 0; g < 8; g++) {
    let gx = 288 + g * 7.5;
    let gy = 528 + g * 7.5;
    let gAng = 122 - g * 5;
    drawBarbedFeather(X(gx), gy, 64, 17, A(gAng), -side * 10, "azure", 0.9);
  }

  // 7C. Median & Lesser Wing Bow Coverts (Burnished Rust, Vermilion & Bronze Scales)
  for (let row = 3; row >= 0; row--) {
    for (let m = 0; m < 6; m++) {
      let mx = 296 + m * 8.5 + row * 3;
      let my = 468 + row * 16 + m * 6;
      let mAng = 125 - m * 7;
      let col = (row + m) % 2 === 0 ? "rust" : "gold";
      drawBarbedFeather(X(mx), my, 46, 16, A(mAng), -side * 8, col, 0.82);
    }
  }

  // --- STEP 8: CASCADING HACKLE CAPE (NECK PLUMES IN FIERY COPPER, RUST & GOLD) ---
  // Drawn from lower cape up to the nape of the head
  for (let row = 9; row >= 0; row--) {
    let frac = row / 9; // 1 at bottom of cape, 0 at top of neck
    let yRow = lerp(328, 472, frac);
    let xBack = lerp(332, 295, frac);
    let xFront = lerp(368, 376, frac);
    let count = floor(lerp(4, 7, frac));

    for (let k = 0; k < count; k++) {
      let t = k / (count - 1);
      let hx = lerp(xBack, xFront, t);
      let hy = yRow + abs(t - 0.5) * 8;
      let hAng = lerp(138, 65, t);
      let hLen = lerp(38, 76, frac) * (1.0 - 0.15 * abs(t - 0.4));
      let hCurv = lerp(-18, 12, t);
      let col = (row + k) % 3 === 0 ? "gold" : ((row + k) % 2 === 0 ? "rust" : "vermilion");
      drawBarbedFeather(X(hx), hy, hLen, 12.5, A(hAng), side * hCurv, col, 0.85);
    }
  }

  // --- STEP 9: ROYAL COMB, WATTLES, BEAK, BARE VELLUM EAR-LOBE & FIERCE EYE ---
  drawRoosterHead(side, X, A);
}

// ============================================================================
// HYPERREAL BARBED FEATHER GENERATOR
// ============================================================================

function drawBarbedFeather(x, y, len, w, angleDeg, curveDeg, paletteType, detailScale = 1.0) {
  // Select feather color triad: [baseShadow, midIridescent, tipHighlight, rachisCol]
  let cBase, cMid, cTip, cRachis;
  if (paletteType === "azure") {
    cBase = PAL.sableDeep;
    cMid = PAL.azureDeep;
    cTip = PAL.azureSheen;
    cRachis = PAL.ochreMid;
  } else if (paletteType === "bronze") {
    cBase = PAL.sableInk;
    cMid = PAL.ochreDeep;
    cTip = PAL.ochreLight;
    cRachis = PAL.ochreSpec;
  } else if (paletteType === "rust") {
    cBase = PAL.vermilionDark;
    cMid = PAL.rustMid;
    cTip = PAL.ochreBright;
    cRachis = PAL.ochreLight;
  } else if (paletteType === "vermilion") {
    cBase = PAL.vermilionDeep;
    cMid = PAL.vermilionBright;
    cTip = PAL.ochreLight;
    cRachis = PAL.ochreSpec;
  } else {
    // "gold"
    cBase = PAL.rustDeep;
    cMid = PAL.ochreMid;
    cTip = PAL.ochreSpec;
    cRachis = PAL.vellumSpec;
  }

  const steps = max(10, floor(16 * detailScale));
  let spine = [];

  // 1. Compute curved rachis (quill shaft) trajectory
  let cx = x;
  let cy = y;
  let stepLen = len / steps;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let curAng = angleDeg + curveDeg * t * t;
    let rad = (curAng * PI) / 180;
    spine.push({ x: cx, y: cy, ang: curAng, rad: rad, t: t });
    cx += cos(rad) * stepLen;
    cy += sin(rad) * stepLen;
  }

  // 2. Subtle dark under-wash along the feather vane so layered feathers have solid opacity
  let polyPts = [];
  for (let i = 0; i <= steps; i += 2) {
    let s = spine[i];
    let prof = sin(pow(s.t, 0.75) * PI) * w * 0.5;
    let nx = -sin(s.rad);
    let ny = cos(s.rad);
    polyPts.push([s.x + nx * prof, s.y + ny * prof]);
  }
  for (let i = steps; i >= 0; i -= 2) {
    let s = spine[i];
    let prof = sin(pow(s.t, 0.75) * PI) * w * 0.5;
    let nx = -sin(s.rad);
    let ny = cos(s.rad);
    polyPts.push([s.x - nx * prof, s.y - ny * prof]);
  }
  washShape(polyPts, cBase, 195, 0.1);

  // 3. Draw individual radiating barbs along both sides of the rachis!
  for (let i = 1; i < steps; i++) {
    let s = spine[i];
    let t = s.t;
    // Feather vane width profile (wider in middle/upper-middle, tapering to point)
    let vaneW = sin(pow(t, 0.7) * PI) * w * 0.62;
    if (vaneW < 1.2) continue;

    // Select barb color by position along shaft (base shadow -> mid iridescent -> lit golden tip)
    let barbCol = t < 0.35 ? cBase : (t < 0.74 ? cMid : cTip);
    brush.set("barb", barbCol, 0.38 * detailScale);

    // Barb angles branch forward toward the feather tip (~32 degrees off the shaft)
    for (let side of [-1, 1]) {
      // Slight natural separation/fraying in outer barbs
      let fray = (i % 4 === 0) ? side * 5 : 0;
      let bAngRad = ((s.ang + side * 34 + fray) * PI) / 180;
      let bx2 = s.x + cos(bAngRad) * vaneW;
      let by2 = s.y + sin(bAngRad) * vaneW;
      brush.line(s.x, s.y, bx2, by2);

      // Lit golden-ochre or iridescent sheen barb tips on the upper/outer web
      if (t > 0.45 && (side === -1 || t > 0.72)) {
        let mx = lerp(s.x, bx2, 0.52);
        let my = lerp(s.y, by2, 0.52);
        brush.set("engraver", cTip, 0.32 * detailScale);
        brush.line(mx, my, bx2, by2);
        brush.set("barb", barbCol, 0.38 * detailScale);
      }
    }
  }

  // 4. Central Rachis (Quill Shaft) catching the light
  let shaftPts = spine.map(s => [s.x, s.y]);
  brush.set("rotring", PAL.sableDeep, 0.48 * detailScale);
  brush.spline(shaftPts, 0.2);
  brush.set("engraver", cRachis, 0.34 * detailScale);
  brush.spline(shaftPts.slice(0, max(3, floor(shaftPts.length * 0.85))), 0.2);
}

