// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function roundedRectPoints(x, y, w, h, r, segs = 7) {
  let pts = [];
  let corners = [
    { cx: x + w - r, cy: y + r, start: -90, end: 0 },
    { cx: x + w - r, cy: y + h - r, start: 0, end: 90 },
    { cx: x + r, cy: y + h - r, start: 90, end: 180 },
    { cx: x + r, cy: y + r, start: 180, end: 270 }
  ];
  for (let c of corners) {
    for (let i = 0; i <= segs; i++) {
      let a = lerp(c.start, c.end, i / segs);
      pts.push([c.cx + cos(a) * r, c.cy + sin(a) * r]);
    }
  }
  return pts;
}

function drawShapePts(pts, curvature = 0.05, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    if (pts[i].length > 2) {
      brush.vertex(pts[i][0], pts[i][1], pts[i][2]);
    } else {
      brush.vertex(pts[i][0], pts[i][1]);
    }
  }
  brush.endShape(closed);
}

function washPoly(pts, col, alpha = 255, curvature = 0.08) {
  resetBrushState();
  brush.wash(col, alpha);
  drawShapePts(pts, curvature, true);
  resetBrushState();
}

function watercolorPoly(pts, col, alpha = 140, bleed = 0.04, tex = 0.25, curvature = 0.08) {
  resetBrushState();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "in");
  brush.fillTexture(tex, 0.18);
  drawShapePts(pts, curvature, true);
  resetBrushState();
}

function strokePoly(pts, brushName, col, weight = 1, curvature = 0.08, closed = true) {
  resetBrushState();
  brush.set(brushName, col, weight);
  drawShapePts(pts, curvature, closed);
  resetBrushState();
}

function airbrushBand(x1, y1, x2, y2, col, weight = 1.0, passes = 3, fine = false) {
  resetBrushState();
  brush.set(fine ? "fine_airbrush" : "airbrush", col, weight);
  for (let i = 0; i < passes; i++) {
    let ox = random(-2.5, 2.5);
    let oy = random(-2.5, 2.5);
    brush.line(x1 + ox, y1 + oy, x2 + ox, y2 + oy);
  }
  resetBrushState();
}

function airbrushSpline(pts, col, weight = 1.0, passes = 3, fine = false, curv = 0.5) {
  resetBrushState();
  brush.set(fine ? "fine_airbrush" : "airbrush", col, weight);
  for (let i = 0; i < passes; i++) {
    let jittered = pts.map(p => [
      p[0] + random(-2.0, 2.0),
      p[1] + random(-2.0, 2.0),
      p[2] !== undefined ? p[2] : 1.0
    ]);
    brush.spline(jittered, curv);
  }
  resetBrushState();
}

function dashedLine(x1, y1, x2, y2, dashLen, gapLen, brushName, col, weight) {
  resetBrushState();
  brush.set(brushName, col, weight);
  let d = dist(x1, y1, x2, y2);
  let step = dashLen + gapLen;
  let count = floor(d / step);
  for (let i = 0; i <= count; i++) {
    let t0 = (i * step) / d;
    let t1 = min(1, (i * step + dashLen) / d);
    if (t0 < 1 && t1 > t0) {
      brush.line(lerp(x1, x2, t0), lerp(y1, y2, t0), lerp(x1, x2, t1), lerp(y1, y2, t1));
    }
  }
  resetBrushState();
}

function dashedArc(cx, cy, rx, ry, aStart, aEnd, numDashes, brushName, col, weight) {
  resetBrushState();
  brush.set(brushName, col, weight);
  for (let i = 0; i < numDashes; i++) {
    let t0 = (i + 0.12) / numDashes;
    let t1 = (i + 0.68) / numDashes;
    let a0 = lerp(aStart, aEnd, t0);
    let a1 = lerp(aStart, aEnd, t1);
    let am = (a0 + a1) * 0.5;
    brush.spline([
      [cx + cos(a0) * rx, cy + sin(a0) * ry],
      [cx + cos(am) * rx, cy + sin(am) * ry],
      [cx + cos(a1) * rx, cy + sin(a1) * ry]
    ], 0.4);
  }
  resetBrushState();
}

