function draw() {
  translate(-width / 2, -height / 2);
  background("#08111f");

  const NAVY = "#091830";
  const NAVY_MID = "#173156";
  const CARD_BG = "#cfdbe5";
  const CARD_LIGHT = "#dfe8f0";
  const RED_BOLD = "#d9161f";
  const RED_BRIGHT = "#ff2b33";
  const RED_DARK = "#7a070d";

  // 1. Draw the physical laminated safety card stock
  drawCardStock(NAVY, CARD_BG, CARD_LIGHT);

  // 2. Draw top safety card header & typography
  drawCardHeader(NAVY, RED_BOLD);

  // 3. Draw the sequence of 3 rounded panels advancing left to right
  const panels = [
    { x: 54, y: 138, w: 342, h: 922, r: 28, step: 1 },
    { x: 429, y: 138, w: 342, h: 922, r: 28, step: 2 },
    { x: 804, y: 138, w: 342, h: 922, r: 28, step: 3 }
  ];

  for (let p of panels) {
    drawPanelBase(p, NAVY);
    drawPassengerTorso(p, NAVY, NAVY_MID);
    drawNylonWebbingAndBuckle(p, NAVY);
    drawLifeVest(p, NAVY);
    drawOralTubeAndCO2Hardware(p, NAVY, RED_BOLD, RED_BRIGHT, RED_DARK);
    drawHandsAndToggle(p, NAVY, RED_BOLD, RED_BRIGHT, RED_DARK);
    drawArrowsAndMotionLines(p, NAVY, RED_BOLD, RED_BRIGHT);
    drawPanelFrameAndBadge(p, NAVY, RED_BOLD);
  }

  // 4. Draw subtle inter-panel sequence connectors & bottom technical strip
  drawFooterStrip(panels, NAVY, RED_BOLD);

  // 5. Final subtle printing grain pass across the card margins
  drawFinalCardGrain();

  noLoop();
}

