function drawCardStock(NAVY, CARD_BG, CARD_LIGHT) {
  // Drop shadow of laminated card
  let shadowPts = roundedRectPoints(24, 24, 1158, 1158, 38, 8);
  washPoly(shadowPts, "#040811", 220, 0.02);

  // Main pale grey-blue card stock
  let cardPts = roundedRectPoints(18, 18, 1164, 1164, 36, 8);
  washPoly(cardPts, CARD_BG, 255, 0.02);

  // Subtle mottled watercolor tone on card stock
  watercolorPoly(roundedRectPoints(26, 26, 1148, 1148, 32, 6), CARD_LIGHT, 85, 0.06, 0.35, 0.02);
  watercolorPoly(roundedRectPoints(30, 820, 1140, 340, 28, 6), "#b7c8d6", 65, 0.08, 0.3, 0.02);

  // Laminated specular diagonal sheen on the card stock
  airbrushBand(80, 40, 520, 1150, "#eef5fa", 2.4, 4, false);
  airbrushBand(680, 40, 1120, 1150, "#b8cad8", 2.2, 3, false);

  // Faint spray of offset printing grain over the card stock
  resetBrushState();
  brush.set("card_grain", "#6f8699", 1.1);
  for (let y = 38; y < 1160; y += 34) {
    brush.line(42, y + random(-4, 4), 1158, y + random(-4, 4));
  }
  brush.set("card_grain", "#f4f8fb", 0.9);
  for (let y = 52; y < 1160; y += 42) {
    brush.line(42, y + random(-4, 4), 1158, y + random(-4, 4));
  }
  resetBrushState();

  // Outer card trim outline
  strokePoly(cardPts, "navy_marker", NAVY, 1.1, 0.02, true);
  let innerTrim = roundedRectPoints(30, 30, 1140, 1140, 28, 8);
  strokePoly(innerTrim, "fine_liner", "#6d8499", 0.65, 0.02, true);
}

function drawCardHeader(NAVY, RED_BOLD) {
  // Header navy banner strip
  let bannerPts = roundedRectPoints(54, 46, 1092, 68, 14, 5);
  washPoly(bannerPts, "#e5eef5", 240, 0.02);
  strokePoly(bannerPts, "navy_marker", NAVY, 0.95, 0.02, true);

  // Red safety accent bar along bottom of header
  let redStrip = [
    [56, 102], [1144, 102], [1144, 112], [56, 112]
  ];
  washPoly(redStrip, RED_BOLD, 245, 0.0);

