function drawTechTitle(x, y, NAVY, RED_BOLD) {
  resetBrushState();
  brush.set("navy_marker", NAVY, 1.05);
  let h = 22;
  let w = 13;
  let gap = 21;
  let cx = x;

  // L
  brush.line(cx, y, cx, y + h);
  brush.line(cx, y + h, cx + w, y + h);
  cx += gap;
  // I
  brush.line(cx + 4, y, cx + 4, y + h);
  cx += 14;
  // F
  brush.line(cx, y, cx, y + h);
  brush.line(cx, y, cx + w, y);
  brush.line(cx, y + h * 0.48, cx + w * 0.8, y + h * 0.48);
  cx += gap;
  // E
  brush.line(cx, y, cx, y + h);
  brush.line(cx, y, cx + w, y);
  brush.line(cx, y + h * 0.48, cx + w * 0.8, y + h * 0.48);
  brush.line(cx, y + h, cx + w, y + h);
  cx += gap + 14;

  // V
  brush.line(cx, y, cx + w * 0.5, y + h);
  brush.line(cx + w, y, cx + w * 0.5, y + h);
  cx += gap;
  // E
  brush.line(cx, y, cx, y + h);
  brush.line(cx, y, cx + w, y);
  brush.line(cx, y + h * 0.48, cx + w * 0.8, y + h * 0.48);
  brush.line(cx, y + h, cx + w, y + h);
  cx += gap;
  // S
  brush.spline([
    [cx + w, y + 3], [cx + w * 0.3, y], [cx, y + h * 0.25],
    [cx + w * 0.5, y + h * 0.5], [cx + w, y + h * 0.75],
    [cx + w * 0.7, y + h], [cx, y + h - 3]
  ], 0.45);
  cx += gap;
  // T
  brush.line(cx, y, cx + w + 2, y);
  brush.line(cx + (w + 2) * 0.5, y, cx + (w + 2) * 0.5, y + h);

  // Divider slash in red
  brush.set("navy_marker", RED_BOLD, 1.0);
  brush.line(cx + 32, y + h + 2, cx + 44, y - 2);

  // Secondary subtitle rule lines (representing multilingual caption bars)
  brush.set("fine_liner", "#355070", 0.85);
  let sx = cx + 62;
  let segWidths = [68, 22, 94, 52, 76, 44];
  for (let sw of segWidths) {
    brush.line(sx, y + 6, sx + sw, y + 6);
    brush.line(sx, y + 9, sx + sw * 0.85, y + 9);
    brush.line(sx, y + 17, sx + sw * 0.92, y + 17);
    sx += sw + 14;
  }
  resetBrushState();
}

function drawSmallNumeral(cx, cy, n, col, wt = 1.0) {
  resetBrushState();
  brush.set("navy_marker", col, wt);
  if (n === 1) {
    brush.line(cx - 3, cy - 4, cx + 1, cy - 7);
    brush.line(cx + 1, cy - 7, cx + 1, cy + 7);
    brush.line(cx - 4, cy + 7, cx + 5, cy + 7);
  } else if (n === 2) {
    brush.spline([
      [cx - 5, cy - 4], [cx, cy - 7], [cx + 5, cy - 3],
      [cx - 5, cy + 7], [cx + 6, cy + 7]
    ], 0.35);
  } else if (n === 3) {
    brush.spline([
      [cx - 5, cy - 5], [cx + 1, cy - 7], [cx + 5, cy - 3],
      [cx - 1, cy], [cx + 5, cy + 4], [cx, cy + 7], [cx - 5, cy + 5]
    ], 0.4);
  }
  resetBrushState();
}

