function drawNylonWebbingAndBuckle(p, NAVY) {
  let { x, y, w, step } = p;
  let cx = x + w * 0.5;
  let strapY = y + 584;
  let strapH = 34;

  // Drop shadow of webbing on suit
  let strapShadow = [
    [x + 12, strapY + 6], [x + w - 12, strapY + 6],
    [x + w - 12, strapY + strapH + 10], [x + 12, strapY + strapH + 10]
  ];
  washPoly(strapShadow, "#040914", 210, 0.02);

  // Main black/charcoal woven nylon strap across waist
  let strapPts = [
    [x + 10, strapY], [cx, strapY + 5], [x + w - 10, strapY],
    [x + w - 10, strapY + strapH], [cx, strapY + strapH + 5], [x + 10, strapY + strapH]
  ];
  washPoly(strapPts, "#182334", 255, 0.03);

  // Vertical suspension straps coming down from behind the vest lobes
  let vertStrapL = [
    [cx - 72, y + 480], [cx - 42, y + 480],
    [cx - 42, strapY + 12], [cx - 72, strapY + 12]
  ];
  let vertStrapR = [
    [cx + 42, y + 480], [cx + 72, y + 480],
    [cx + 72, strapY + 12], [cx + 42, strapY + 12]
  ];
  washPoly(vertStrapL, "#162030", 255, 0.02);
  washPoly(vertStrapR, "#162030", 255, 0.02);

  // Hyperreal herringbone nylon weave texture (fine diagonal ribs + beaded selvedge)
  resetBrushState();
  brush.set("fine_liner", "#3e5573", 0.65);
  for (let sx = x + 14; sx < x + w - 14; sx += 5.5) {
    let sy = strapY + map(abs(sx - cx), 0, w * 0.5, 5, 0);
    brush.line(sx, sy + 3, sx + 4, sy + strapH * 0.5);
    brush.line(sx + 4, sy + strapH * 0.5, sx, sy + strapH - 3);
  }
  // Vertical straps weave
  for (let sy = y + 490; sy < strapY + 6; sy += 6) {
    brush.line(cx - 70, sy, cx - 44, sy + 3);
    brush.line(cx + 44, sy, cx + 70, sy + 3);
  }

  // Crisp silver-grey selvedge stitch ticks along top & bottom edges of nylon webbing
  brush.set("fine_liner", "#b0c4d9", 0.6);
  for (let sx = x + 14; sx < x + w - 14; sx += 7) {
    let sy = strapY + map(abs(sx - cx), 0, w * 0.5, 5, 0);
    brush.line(sx, sy + 2, sx + 3.5, sy + 2);
    brush.line(sx, sy + strapH - 2, sx + 3.5, sy + strapH - 2);
  }

  strokePoly(strapPts, "navy_marker", NAVY, 0.95, 0.03, true);
  strokePoly(vertStrapL, "navy_marker", NAVY, 0.85, 0.02, true);
  strokePoly(vertStrapR, "navy_marker", NAVY, 0.85, 0.02, true);

  // Central Anodized Clasp Buckle
  let bx = cx - 28;
  let by = strapY - 3;
  let bw = 56;
  let bh = strapH + 11;
  let bucklePts = roundedRectPoints(bx, by, bw, bh, 5, 4);
  washPoly(bucklePts, "#2c3e54", 255, 0.02);

  // Inner metallic latch plate
  let latchPts = roundedRectPoints(bx + 7, by + 6, bw - 14, bh - 12, 3, 3);
  washPoly(latchPts, "#8aa1b8", 255, 0.02);
  washPoly([
    [bx + 10, by + 9], [bx + bw - 10, by + 9],
    [bx + bw - 16, by + 18], [bx + 10, by + 18]
  ], "#eef5fa", 240, 0.0);
  washPoly([
    [bx + 10, by + 19], [bx + bw - 10, by + 19],
    [bx + bw - 10, by + bh - 8], [bx + 10, by + bh - 8]
  ], "#162436", 230, 0.0);

  strokePoly(bucklePts, "navy_marker", NAVY, 0.95, 0.02, true);
  strokePoly(latchPts, "fine_liner", NAVY, 0.75, 0.02, true);
  resetBrushState();
  brush.set("specular", "#ffffff", 0.85);
  brush.line(bx + 6, by + 3, bx + bw - 8, by + 3);
  resetBrushState();
}

// ============================================================================
