// ============================================================================

function drawLifeVest(p, NAVY) {
  let { x, y, w, step } = p;
  let cx = x + w * 0.5;

  if (step === 1) {
    drawVestStage1Flat(x, y, w, cx, NAVY);
  } else if (step === 2) {
    drawVestStage2Swelling(x, y, w, cx, NAVY);
  } else {
    drawVestStage3Taut(x, y, w, cx, NAVY);
  }
}

