// ============================================================================
// ORAL INFLATION TUBE & CO2 HARDWARE
// ============================================================================

function drawOralTubeAndCO2Hardware(p, NAVY, RED_BOLD, RED_BRIGHT, RED_DARK) {
  let { x, y, w, step } = p;
  let cx = x + w * 0.5;

  // 1. Oral Inflation Tube on Upper Left Lobe (wearer's right / viewer's left)
  let baseTx = step === 1 ? cx - 64 : (step === 2 ? cx - 72 : cx - 78);
  let baseTy = step === 1 ? y + 278 : (step === 2 ? y + 268 : y + 258);
  let topTx = step === 3 ? cx - 50 : baseTx + 14;
  let topTy = step === 3 ? y + 162 : baseTy - 88;

  // Black rubber mounting grommet welded to yellow vest
  let grommetPts = roundedRectPoints(baseTx - 13, baseTy - 9, 26, 18, 8, 5);
  washPoly(grommetPts, "#182232", 255, 0.05);
  strokePoly(grommetPts, "navy_marker", NAVY, 0.85, 0.05, true);

  // Red rubber tube body
  let dx = topTx - baseTx;
  let dy = topTy - baseTy;
  let len = sqrt(dx * dx + dy * dy);
  let nx = (-dy / len) * 6.5;
  let ny = (dx / len) * 6.5;

  let tubePts = [
    [baseTx - nx, baseTy - ny],
    [topTx - nx * 0.85, topTy - ny * 0.85],
    [topTx + nx * 0.85, topTy + ny * 0.85],
    [baseTx + nx, baseTy + ny]
  ];
  washPoly(tubePts, RED_BOLD, 255, 0.02);
  // Dark crimson core shadow along right side of tube
  washPoly([
    [baseTx, baseTy], [topTx, topTy],
    [topTx + nx * 0.85, topTy + ny * 0.85], [baseTx + nx, baseTy + ny]
  ], RED_DARK, 190, 0.02);
  // Specular highlight along left side of red tube
  resetBrushState();
  brush.set("specular", "#ffccd0", 0.9);
  brush.line(baseTx - nx * 0.45, baseTy - ny * 0.45, topTx - nx * 0.45, topTy - ny * 0.45);
  strokePoly(tubePts, "navy_marker", NAVY, 0.8, 0.02, true);

  // Black mouthpiece valve cap at top of oral tube
  let capPts = [
    [topTx - nx * 1.15, topTy - ny * 1.15],
    [topTx - nx * 0.95 + dx * 0.16, topTy - ny * 0.95 + dy * 0.16],
    [topTx + nx * 0.95 + dx * 0.16, topTy + ny * 0.95 + dy * 0.16],
    [topTx + nx * 1.15, topTy + ny * 1.15]
  ];
  washPoly(capPts, "#162233", 255, 0.02);
  strokePoly(capPts, "navy_marker", NAVY, 0.8, 0.02, true);

  // 2. Shoulder Water-Activated Locator Light & Whistle (on viewer's right lobe)
  let lx = step === 1 ? cx + 74 : (step === 2 ? cx + 88 : cx + 98);
  let ly = step === 1 ? y + 195 : (step === 2 ? y + 185 : y + 175);
  let lightBox = roundedRectPoints(lx - 11, ly - 16, 22, 32, 4, 3);
  washPoly(lightBox, "#d8e4ed", 255, 0.02);
  let domePts = roundedRectPoints(lx - 7, ly - 24, 14, 10, 5, 4);
  washPoly(domePts, step === 3 ? "#ffffff" : "#9eb4c7", 255, 0.02);
  strokePoly(lightBox, "navy_marker", NAVY, 0.75, 0.02, true);
  strokePoly(domePts, "navy_marker", NAVY, 0.75, 0.02, true);
  if (step === 3) {
    // Glowing rays on locator light in Panel 3
    resetBrushState();
    brush.set("specular", "#ffffff", 1.0);
    for (let a = -150; a <= -30; a += 30) {
      brush.line(lx + cos(a) * 11, ly - 20 + sin(a) * 11, lx + cos(a) * 19, ly - 20 + sin(a) * 19);
    }
  }

  // 3. CO2 Inflator Manifold Grommet at Lower Right Lobe
  let mx = step === 1 ? cx + 52 : (step === 2 ? cx + 60 : cx + 66);
  let my = step === 1 ? y + 532 : (step === 2 ? y + 545 : y + 558);
  let manifoldPts = roundedRectPoints(mx - 12, my - 10, 24, 22, 4, 3);
  washPoly(manifoldPts, "#233247", 255, 0.02);
  strokePoly(manifoldPts, "navy_marker", NAVY, 0.85, 0.02, true);

  // In Panel 2, draw a crisp burst of CO2 gas/valve impulse ticks at the manifold!
  if (step === 2) {
    resetBrushState();
    brush.set("specular", "#ffffff", 1.1);
    for (let a = 20; a <= 160; a += 28) {
      brush.line(mx + cos(a) * 14, my + sin(a) * 12, mx + cos(a) * 28, my + sin(a) * 24);
    }
    brush.set("fine_liner", RED_BOLD, 0.85);
    for (let a = 35; a <= 145; a += 35) {
      brush.line(mx + cos(a) * 16, my + sin(a) * 14, mx + cos(a) * 25, my + sin(a) * 22);
    }
  }
  resetBrushState();
}

// ============================================================================
// HYPERREALIST HANDS, WEDDING BAND, LANYARD & RED TOGGLE
// ============================================================================

function drawHandsAndToggle(p, NAVY, RED_BOLD, RED_BRIGHT, RED_DARK) {
  let { x, y, w, step } = p;
  let cx = x + w * 0.5;

  // Manifold anchor point where lanyard originates
  let mx = step === 1 ? cx + 52 : (step === 2 ? cx + 60 : cx + 66);
  let my = step === 1 ? y + 542 : (step === 2 ? y + 555 : y + 568);

  // Toggle position advances downward across Panels 1 -> 2 -> 3
  let tx = step === 1 ? cx + 52 : (step === 2 ? cx + 58 : cx + 62);
  let ty = step === 1 ? y + 608 : (step === 2 ? y + 704 : y + 762);

  // 1. Braided White/Grey Nylon Lanyard Cord connecting manifold to toggle
  resetBrushState();
  // Shadow of cord
  brush.set("navy_marker", "#060e1c", 1.2);
  if (step === 1) {
    // Slightly slack S-curve before pull
    brush.spline([[mx + 2, my], [mx - 5, (my + ty) * 0.5], [tx + 2, ty]], 0.45);
  } else {
    // Drum-tight vertical line during and after pull
    brush.line(mx + 2, my, tx + 2, ty);
  }
  // White braided cord body
  brush.set("specular", "#f0f6fa", 1.55);
  if (step === 1) {
    brush.spline([[mx, my], [mx - 7, (my + ty) * 0.5], [tx, ty]], 0.45);
  } else {
    brush.line(mx, my, tx, ty);
  }
  // Bead texture ticks along lanyard cord
  brush.set("fine_liner", NAVY, 0.75);
  let cordSteps = floor((ty - my) / 7);
  for (let i = 1; i < cordSteps; i++) {
    let cy = lerp(my, ty, i / cordSteps);
    let cxOff = step === 1 ? sin((i / cordSteps) * 180) * -6 : 0;
    brush.line(mx + cxOff - 3, cy - 1, mx + cxOff + 3, cy + 1);
  }

  // 2. Red Plastic Pull-Tab Toggle (Twin-holed cylindrical grip)
  drawRedToggle(tx, ty, NAVY, RED_BOLD, RED_BRIGHT, RED_DARK);

  // 3. Draw LEFT HAND (Viewer's Left)
  if (step === 1) {
    // Steadies the nylon waist strap & lower left vest lobe
    drawLeftHandBrace(cx - 88, y + 612, 0.0, NAVY);
  } else if (step === 2) {
    // Braces higher against the swelling vest strap
    drawLeftHandBrace(cx - 94, y + 575, -8.0, NAVY);
  } else {
    // Reaches up beside the taut left bladder to hold/guide the oral inflation tube
    drawLeftHandAtTube(cx - 78, y + 318, NAVY);
  }

  // 4. Draw RIGHT HAND (Viewer's Right) with GOLD WEDDING BAND pulling the toggle
  drawRightHandPulling(tx, ty, step, x + w, y, NAVY);
}

function drawRedToggle(tx, ty, NAVY, RED_BOLD, RED_BRIGHT, RED_DARK) {
  let tw = 46;
  let th = 24;
  // Drop shadow of toggle
  let shPts = roundedRectPoints(tx - tw * 0.5 + 3, ty + 3, tw, th, 8, 4);
  washPoly(shPts, "#050b16", 210, 0.02);

  // Molded red plastic toggle body
  let togPts = roundedRectPoints(tx - tw * 0.5, ty, tw, th, 8, 5);
  washPoly(togPts, RED_BOLD, 255, 0.02);

  // Dark crimson bevel shadow at bottom of toggle
  let botBevel = [
    [tx - tw * 0.45, ty + th * 0.58], [tx + tw * 0.45, ty + th * 0.58],
    [tx + tw * 0.4, ty + th - 2], [tx - tw * 0.4, ty + th - 2]
  ];
  washPoly(botBevel, RED_DARK, 215, 0.02);

  // Twin circular finger-grip holes in the plastic toggle
  for (let side of [-1, 1]) {
    let hx = tx + side * 11;
    let hy = ty + th * 0.52;
    let holePts = roundedRectPoints(hx - 5, hy - 5, 10, 10, 5, 4);
    washPoly(holePts, "#101e33", 255, 0.02);
    strokePoly(holePts, "fine_liner", NAVY, 0.65, 0.02, true);
  }

  // Glossy white plastic specular ridge along top of toggle
  resetBrushState();
  brush.set("specular", "#ffffff", 1.15);
  brush.line(tx - tw * 0.36, ty + 4, tx + tw * 0.36, ty + 4);
  strokePoly(togPts, "navy_marker", NAVY, 0.95, 0.02, true);
  resetBrushState();
}

