    { dy: 6, len1: 30, len2: 23, w: 13.5 },
    { dy: 21, len1: 24, len2: 18, w: 12 }
  ];

  for (let i = 0; i < 4; i++) {
    let fd = fingerData[i];
    let fx0 = hx + 28 - i * 3;
    let fy0 = hy + fd.dy;
    let fx1 = fx0 + fd.len1;
    let fy1 = fy0 - 3;
    let fx2 = fx1 + fd.len2;
    let fy2 = fy1 + 6;

    let fPts = [
      [fx0, fy0 - fd.w * 0.5],
      [fx1, fy1 - fd.w * 0.48],
      [fx2, fy2 - fd.w * 0.42],
      [fx2 + 4, fy2],
      [fx2, fy2 + fd.w * 0.42],
      [fx1, fy1 + fd.w * 0.48],
      [fx0, fy0 + fd.w * 0.5]
    ];
    washPoly(fPts, "#ecc0a1", 255, 0.1);
    // Shaded lower edge of each finger cylinder
    watercolorPoly([
      [fx0, fy0], [fx1, fy1], [fx2, fy2],
      [fx2, fy2 + fd.w * 0.42], [fx1, fy1 + fd.w * 0.48], [fx0, fy0 + fd.w * 0.5]
    ], "#8f442b", 165, 0.04, 0.2, 0.08);
    // Coral knuckle warmth
    watercolorPoly(roundedRectPoints(fx1 - 6, fy1 - 5, 12, 10, 4, 3), "#d45d48", 95, 0.04, 0.2, 0.05);

    // Specular tendon & phalanx highlight
    airbrushBand(fx0 - 12, fy0 - 2, fx1 + 8, fy1 - 2, "#fff5eb", 0.65, 2, true);

    strokePoly(fPts, "navy_marker", NAVY, 0.82, 0.1, true);

    // Hyperreal elliptical knuckle creases at MCP & PIP joints
    drawKnuckleCreases(fx0 + 2, fy0, fd.w * 0.36, 85, NAVY);
    drawKnuckleCreases(fx1, fy1, fd.w * 0.34, 85, NAVY);
    // Fingernail at tip
    drawFingernail(fx2 - 4, fy2 - 1, 8, 6.5, 10, NAVY);
  }

  // Dorsum outer contour & wrist creases
  strokePoly(dorsumPts, "navy_marker", NAVY, 0.9, 0.08, false);
}

