// --- Right Hand with GOLD WEDDING BAND Pulling the Red Toggle ---
function drawRightHandPulling(tx, ty, step, panelRight, panelTop, NAVY) {
  // Hand anchor relative to the toggle (hand grips the toggle and lanyard)
  let hx = tx + 26;
  let hy = ty + 20;

  // 1. Dark Navy Suit Sleeve & Crisp White Shirt Cuff entering from bottom-right of panel
  let sleeveEndX = panelRight - 10;
  let sleeveEndY = min(panelTop + 905, hy + 175);

  let sleevePts = [
    [hx + 36, hy + 46], [sleeveEndX, sleeveEndY - 58],
    [sleeveEndX, sleeveEndY], [hx + 2, hy + 88]
  ];
  washPoly(sleevePts, "#0c1930", 255, 0.02);
  strokePoly(sleevePts, "navy_marker", NAVY, 1.0, 0.02, true);

  let cuffPts = [
    [hx + 22, hy + 26], [hx + 42, hy + 52],
    [hx + 8, hy + 88], [hx - 12, hy + 58]
  ];
  washPoly(cuffPts, "#f2f7fc", 255, 0.02);
  watercolorPoly([
    [hx + 2, hy + 52], [hx + 32, hy + 64],
    [hx + 8, hy + 88], [hx - 12, hy + 58]
  ], "#8ba8c2", 155, 0.04, 0.2, 0.02);
  strokePoly(cuffPts, "navy_marker", NAVY, 0.9, 0.02, true);

  // Shirt cuff button
  let btnPts = roundedRectPoints(hx + 12, hy + 60, 7, 7, 3.5, 4);
  washPoly(btnPts, "#ffffff", 255, 0.02);
  strokePoly(btnPts, "fine_liner", NAVY, 0.65, 0.02, true);

  // 2. Broad Dorsal Hand Block & Wrist (angled upward-left toward the toggle)
  let dorsumPts = [
    [hx + 20, hy + 28], [hx + 30, hy - 14],
    [hx - 2, hy - 30], [hx - 34, hy - 14],
    [hx - 26, hy + 42], [hx - 6, hy + 56]
  ];
  washPoly(dorsumPts, "#e8b08e", 255, 0.08);

  // Anatomical sculptural shading on back of hand (metacarpal valleys & ulnar shadow)
  watercolorPoly([
    [hx - 10, hy + 6], [hx + 26, hy - 6],
    [hx + 20, hy + 28], [hx - 6, hy + 56], [hx - 26, hy + 42]
  ], "#9e4d32", 165, 0.05, 0.25, 0.08);
  watercolorPoly([
    [hx - 24, hy + 20], [hx + 12, hy + 22],
    [hx - 6, hy + 56], [hx - 26, hy + 42]
  ], "#632a19", 150, 0.05, 0.22, 0.08);

  // Extensor tendon highlights radiating across the back of the hand
  airbrushBand(hx + 16, hy + 22, hx - 14, hy - 18, "#fff4e8", 0.85, 3, true);
  airbrushBand(hx + 10, hy + 30, hx - 22, hy - 2, "#fff4e8", 0.8, 3, true);
  airbrushBand(hx + 4, hy + 38, hx - 26, hy + 14, "#fff4e8", 0.75, 2, true);

  // 3. Thumb pressing firmly over the top/front of the red toggle
  let thumbPts = [
    [hx + 8, hy - 22], [hx - 12, hy - 36],
    [tx + 4, ty + 2], [tx - 6, ty + 8],
    [tx - 4, ty + 20], [hx - 14, hy - 12]
  ];
  washPoly(thumbPts, "#f2c2a2", 255, 0.1);
  watercolorPoly([
    [hx - 10, hy - 20], [tx - 4, ty + 14],
    [tx - 4, ty + 20], [hx - 14, hy - 12]
  ], "#99482e", 155, 0.04, 0.2, 0.08);
  strokePoly(thumbPts, "navy_marker", NAVY, 0.85, 0.1, true);
  drawKnuckleCreases(hx - 10, hy - 24, 5.5, -65, NAVY);
  drawFingernail(tx - 1, ty + 10, 8.5, 6, -155, NAVY);

  // 4. Four Curled Fingers Gripping the Toggle & Cord (Facing the Viewer!)
  // Index (0), Middle (1), Ring with GOLD WEDDING BAND (2), Little (3)
  let fSpecs = [
    { dy: -16, dxL: -52, dxR: -4, w: 14.5 },
    { dy: -1,  dxL: -56, dxR: -2, w: 14.5 },
    { dy: 14,  dxL: -52, dxR: 0,  w: 14.0 }, // Ring finger (wedding band!)
    { dy: 28,  dxL: -44, dxR: 2,  w: 12.5 }
  ];

  for (let i = 0; i < 4; i++) {
    let fs = fSpecs[i];
    let fy = hy + fs.dy;
    let fxRight = hx + fs.dxR; // MCP knuckle side (right)
    let fxMid = hx + (fs.dxL + fs.dxR) * 0.52; // PIP joint (center)
    let fxLeft = hx + fs.dxL; // Curled DIP joint side (left)

    let fPts = [
      [fxRight, fy - fs.w * 0.48],
      [fxMid, fy - fs.w * 0.52],
      [fxLeft, fy - fs.w * 0.42],
      [fxLeft - 4, fy],
      [fxLeft, fy + fs.w * 0.44],
      [fxMid, fy + fs.w * 0.52],
      [fxRight, fy + fs.w * 0.48]
    ];
    washPoly(fPts, "#f0c0a0", 255, 0.1);

    // Cylindrical core shadow along underside of each finger
    watercolorPoly([
      [fxRight, fy + 1], [fxMid, fy + 1], [fxLeft, fy + 1],
      [fxLeft, fy + fs.w * 0.44], [fxMid, fy + fs.w * 0.52], [fxRight, fy + fs.w * 0.48]
    ], "#8c3f27", 175, 0.04, 0.2, 0.08);

    // Warm subsurface coral flush over the bent PIP & MCP knuckles
    watercolorPoly(roundedRectPoints(fxMid - 7, fy - 5, 14, 10, 4, 3), "#d95b43", 105, 0.04, 0.2, 0.05);

    // Bright specular skin sheen along upper ridge of each phalanx
