    strokePoly(fPts, "navy_marker", NAVY, 0.85, 0.1, true);

    // Elliptical knuckle creases on MCP (right) and PIP (middle) and DIP (left) joints
    drawKnuckleCreases(fxRight - 3, fy, fs.w * 0.36, 90, NAVY);
    drawKnuckleCreases(fxMid + 3, fy, fs.w * 0.38, 90, NAVY);
