    // *** THE GOLD WEDDING BAND ON THE RING FINGER (i === 2) ***
    if (i === 2) {
      let ringX = lerp(fxRight, fxMid, 0.46);
      let ringY = fy;
      let ringW = 8.5;
      let ringH = fs.w + 2.2;
      drawGoldWeddingBand(ringX, ringY, ringW, ringH, NAVY);
    }
  }

  // Outer contour of hand dorsum
  strokePoly(dorsumPts, "navy_marker", NAVY, 0.92, 0.08, false);
}

function drawKnuckleCreases(kx, ky, rad, angleDeg, NAVY) {
  resetBrushState();
  // Two fine dark anatomical skin folds + a bright micro-ridge between them
  brush.set("fine_liner", "#4a1f14", 0.68);
  brush.arc(kx - 1.5, ky, rad, angleDeg - 55, angleDeg + 55);
  brush.arc(kx + 1.8, ky, rad * 0.92, angleDeg - 50, angleDeg + 50);
  brush.set("specular", "#fff2e6", 0.55);
  brush.arc(kx + 0.2, ky, rad * 0.95, angleDeg - 40, angleDeg + 40);
  resetBrushState();
}

function drawFingernail(nx, ny, nw, nh, rotDeg, NAVY) {
  push();
  translate(nx, ny);
  rotate(rotDeg);
  let nailPts = roundedRectPoints(-nw * 0.5, -nh * 0.5, nw, nh, 2.5, 3);
  washPoly(nailPts, "#f7c8be", 255, 0.02);
  // Pale half-moon lunula at base of nail
  let lunPts = roundedRectPoints(-nw * 0.45, -nh * 0.38, nw * 0.35, nh * 0.76, 1.5, 3);
  washPoly(lunPts, "#fff7f5", 250, 0.02);
  strokePoly(nailPts, "fine_liner", NAVY, 0.58, 0.02, true);
  resetBrushState();
  brush.set("specular", "#ffffff", 0.65);
  brush.line(-nw * 0.3, -nh * 0.22, nw * 0.35, -nh * 0.22);
  pop();
  resetBrushState();
}

function drawGoldWeddingBand(rx, ry, rw, rh, NAVY) {
  // Subtle skin indentation shadow beside the ring
  let shadowBand = roundedRectPoints(rx - rw * 0.5 - 1.5, ry - rh * 0.5, rw + 3, rh, 3, 4);
  watercolorPoly(shadowBand, "#4a1b0d", 170, 0.02, 0.15, 0.02);

  // Main 24k Gold Band Body
  let bandPts = roundedRectPoints(rx - rw * 0.5, ry - rh * 0.5, rw, rh, 3, 4);
  washPoly(bandPts, "#f5b800", 255, 0.02);

  // High-contrast metallic reflection bands across the curved gold cylinder:
  // 1. Deep espresso/navy core reflection in the middle-lower zone
  washPoly([
    [rx - rw * 0.45, ry + 0.5], [rx + rw * 0.45, ry + 0.5],
    [rx + rw * 0.45, ry + rh * 0.38], [rx - rw * 0.45, ry + rh * 0.38]
  ], "#2e1904", 240, 0.0);

  // 2. Warm amber-gold upper curvature
  washPoly([
    [rx - rw * 0.45, ry - rh * 0.44], [rx + rw * 0.45, ry - rh * 0.44],
    [rx + rw * 0.45, ry - 0.5], [rx - rw * 0.45, ry - 0.5]
  ], "#ffd93b", 250, 0.0);

  // 3. Blazing pure white specular glint across upper-center of gold band
  resetBrushState();
  brush.set("specular", "#ffffff", 1.15);
  brush.line(rx - rw * 0.42, ry - rh * 0.18, rx + rw * 0.42, ry - rh * 0.18);
  brush.set("specular", "#fff2a6", 0.75);
  brush.line(rx - rw * 0.38, ry + rh * 0.42, rx + rw * 0.38, ry + rh * 0.42);

  // Crisp navy outline around wedding band
  strokePoly(bandPts, "fine_liner", NAVY, 0.75, 0.02, true);
  resetBrushState();
}

