function drawArrowsAndMotionLines(p, NAVY, RED_BOLD, RED_BRIGHT) {
  let { x, y, w, step } = p;
  let cx = x + w * 0.5;

  if (step === 1) {
    // Dashed preparatory motion line above & below toggle
    dashedLine(cx + 12, y + 610, cx + 12, y + 790, 9, 7, "navy_marker", NAVY, 0.9);

    // Bold Red Arrow pointing straight DOWN beneath the toggle
    drawBoldRedArrow(cx + 52, y + 662, cx + 52, y + 812, 16, 34, 30, NAVY, RED_BOLD, RED_BRIGHT);

    // Secondary Red Arrow showing waist strap pull-tight action on the left
    drawBoldRedArrow(cx - 32, y + 602, cx - 105, y + 602, 11, 24, 22, NAVY, RED_BOLD, RED_BRIGHT);
    dashedLine(cx - 28, y + 628, cx - 110, y + 628, 7, 6, "navy_marker", RED_BOLD, 0.85);

  } else if (step === 2) {
    // Dynamic vertical dashed motion lines trailing the yanked hand & toggle
    dashedLine(cx + 16, y + 565, cx + 16, y + 785, 10, 7, "navy_marker", NAVY, 0.95);
    dashedLine(cx + 24, y + 575, cx + 24, y + 760, 8, 7, "fine_liner", RED_BOLD, 0.85);
    dashedLine(cx + 98, y + 565, cx + 98, y + 680, 9, 7, "navy_marker", NAVY, 0.9);

    // Powerful Downward Red Arrow below yanked toggle
    drawBoldRedArrow(cx + 58, y + 755, cx + 58, y + 892, 18, 36, 32, NAVY, RED_BOLD, RED_BRIGHT);

    // Outward Expansion Arrows + Dashed Swell Contours flanking the billowing lobes
    dashedArc(cx - 88, y + 325, 58, 175, 145, 215, 11, "navy_marker", NAVY, 0.85);
    dashedArc(cx + 88, y + 325, 58, 175, -35, 35, 11, "navy_marker", NAVY, 0.85);

    drawCurvedRedArrow(cx - 98, y + 295, cx - 152, y + 265, -18, 12, 24, NAVY, RED_BOLD, RED_BRIGHT);
    drawCurvedRedArrow(cx + 98, y + 295, cx + 152, y + 265, 18, 12, 24, NAVY, RED_BOLD, RED_BRIGHT);

  } else if (step === 3) {
    // Dashed motion trail showing completed full-stroke pull from manifold to bottom
    dashedLine(cx + 22, y + 575, cx + 22, y + 835, 10, 7, "navy_marker", NAVY, 0.9);

    // Bold Curved Arrows around the taut inflated bladders + Oral Tube backup arrow
    dashedArc(cx - 64, y + 145, 36, 48, 195, 315, 6, "navy_marker", RED_BOLD, 0.85);
    drawCurvedRedArrow(cx - 84, y + 155, cx - 36, y + 92, -16, 12, 24, NAVY, RED_BOLD, RED_BRIGHT);

    // Upward buoyancy / inflation completion arrows on right bladder
    drawCurvedRedArrow(cx + 128, y + 390, cx + 118, y + 250, 22, 13, 26, NAVY, RED_BOLD, RED_BRIGHT);
    dashedLine(cx + 146, y + 415, cx + 138, y + 260, 9, 7, "navy_marker", NAVY, 0.85);
  }
}

function drawBoldRedArrow(x1, y1, x2, y2, shaftW, headW, headL, NAVY, RED_BOLD, RED_BRIGHT) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  let ux = dx / len;
  let uy = dy / len;
  let nx = -uy;
  let ny = ux;

  let neckX = x2 - ux * headL;
  let neckY = y2 - uy * headL;

  // White high-contrast knockout halo around arrow
  let hw = shaftW * 0.5 + 3.5;
  let hhw = headW * 0.5 + 4.5;
  let haloPts = [
    [x1 - ux * 3 + nx * hw, y1 - uy * 3 + ny * hw],
    [neckX + nx * hw, neckY + ny * hw],
    [neckX + nx * hhw, neckY + ny * hhw],
    [x2 + ux * 4, y2 + uy * 4],
    [neckX - nx * hhw, neckY - ny * hhw],
    [neckX - nx * hw, neckY - ny * hw],
    [x1 - ux * 3 - nx * hw, y1 - uy * 3 - ny * hw]
  ];
  washPoly(haloPts, "#ffffff", 240, 0.01);

  // Crisp Red Arrow polygon
  let sw = shaftW * 0.5;
  let ahw = headW * 0.5;
  let arrowPts = [
    [x1 + nx * sw, y1 + ny * sw],
    [neckX + nx * sw, neckY + ny * sw],
    [neckX + nx * ahw, neckY + ny * ahw],
    [x2, y2],
    [neckX - nx * ahw, neckY - ny * ahw],
    [neckX - nx * sw, neckY - ny * sw],
    [x1 - nx * sw, y1 - ny * sw]
  ];
  washPoly(arrowPts, RED_BOLD, 255, 0.01);

  // Luminous vermilion highlight along one half of arrow
  let hiPts = [
    [x1 + nx * sw * 0.85, y1 + ny * sw * 0.85],
    [neckX + nx * sw * 0.85, neckY + ny * sw * 0.85],
    [neckX + nx * ahw * 0.8, neckY + ny * ahw * 0.8],
    [x2, y2],
    [x1, y1]
  ];
  washPoly(hiPts, RED_BRIGHT, 195, 0.01);

  strokePoly(arrowPts, "navy_marker", NAVY, 0.9, 0.01, true);
}

function drawCurvedRedArrow(x1, y1, x2, y2, bendOffset, shaftW, headW, NAVY, RED_BOLD, RED_BRIGHT) {
  let mx = (x1 + x2) * 0.5 + bendOffset;
  let my = (y1 + y2) * 0.5 - abs(bendOffset) * 0.4;

  // Tangent at tip
  let tx = x2 - mx;
  let ty = y2 - my;
  let tlen = sqrt(tx * tx + ty * ty);
  let ux = tx / tlen;
  let uy = ty / tlen;
  let nx = -uy;
  let ny = ux;

  let headL = headW * 1.05;
  let neckX = x2 - ux * headL;
  let neckY = y2 - uy * headL;

  // White halo
  resetBrushState();
  brush.set("navy_marker", "#ffffff", shaftW * 0.52);
  brush.spline([[x1, y1], [mx, my], [neckX, neckY]], 0.45);

  // Red curved shaft
  brush.set("navy_marker", RED_BOLD, shaftW * 0.38);
  brush.spline([[x1, y1], [mx, my], [neckX, neckY]], 0.45);

  // Arrowhead triangle
  let headPts = [
    [neckX + nx * headW * 0.5, neckY + ny * headW * 0.5],
    [x2, y2],
    [neckX - nx * headW * 0.5, neckY - ny * headW * 0.5]
  ];
  washPoly(headPts, RED_BOLD, 255, 0.01);
  strokePoly(headPts, "navy_marker", NAVY, 0.85, 0.01, true);
  resetBrushState();
}

// ============================================================================
// PANEL ROUNDED BORDERS, STEP BADGES & FOOTER STRIP
// ============================================================================

function drawPanelFrameAndBadge(p, NAVY, RED_BOLD) {
  let { x, y, w, h, r, step } = p;

  // Crisp inner white mat rim to keep rounded corners razor-clean
  let outerPts = roundedRectPoints(x, y, w, h, r, 8);
  let innerPts = roundedRectPoints(x + 3, y + 3, w - 6, h - 6, r - 2, 8);
  strokePoly(innerPts, "navy_marker", "#ffffff", 1.1, 0.02, true);

  // Clean double-pass navy marker rounded panel outline
  strokePoly(outerPts, "navy_marker", NAVY, 1.35, 0.02, true);

  // Step Number Badge in upper-left corner of panel
  let bx = x + 16;
  let by = y + 16;
  let bw = 44;
  let bh = 44;
  let badgePts = roundedRectPoints(bx, by, bw, bh, 11, 5);
  washPoly(badgePts, step === 3 ? RED_BOLD : NAVY, 255, 0.02);
  strokePoly(badgePts, "navy_marker", "#ffffff", 0.9, 0.02, true);
  strokePoly(badgePts, "fine_liner", NAVY, 0.7, 0.02, true);

  // Crisp white numeral 1, 2, 3 inside badge
  drawLargeBadgeNumeral(bx + bw * 0.5, by + bh * 0.5, step);
}

function drawLargeBadgeNumeral(cx, cy, step) {
  resetBrushState();
  brush.set("navy_marker", "#ffffff", 1.35);
  if (step === 1) {
    brush.line(cx - 5, cy - 6, cx + 2, cy - 12);
    brush.line(cx + 2, cy - 12, cx + 2, cy + 12);
    brush.line(cx - 6, cy + 12, cx + 8, cy + 12);
  } else if (step === 2) {
    brush.spline([
      [cx - 8, cy - 6], [cx, cy - 12], [cx + 8, cy - 5],
      [cx - 8, cy + 12], [cx + 9, cy + 12]
    ], 0.35);
  } else if (step === 3) {
    brush.spline([
      [cx - 8, cy - 8], [cx + 1, cy - 12], [cx + 8, cy - 5],
      [cx - 2, cy], [cx + 8, cy + 6], [cx, cy + 12], [cx - 8, cy + 8]
    ], 0.4);
  }
  resetBrushState();
}

function drawFooterStrip(panels, NAVY, RED_BOLD) {
  // Sequence chevrons between panels
  for (let i = 0; i < 2; i++) {
    let gx = panels[i].x + panels[i].w + 17.5;
    let gy = panels[i].y + panels[i].h * 0.5;
    let chevPts = [
      [gx - 7, gy - 14], [gx + 8, gy], [gx - 7, gy + 14]
    ];
    strokePoly(chevPts, "navy_marker", RED_BOLD, 1.25, 0.0, false);
  }

  // Bottom instruction strip aligned under the 3 panels (y = 1080..1146)
  for (let p of panels) {
    let fy = 1080;
    let fh = 64;
    let boxPts = roundedRectPoints(p.x, fy, p.w, fh, 14, 5);
    washPoly(boxPts, "#dde7f0", 240, 0.02);
    strokePoly(boxPts, "navy_marker", NAVY, 0.85, 0.02, true);

    // Icon circle on left of each footer box
    let icx = p.x + 36;
    let icy = fy + fh * 0.5;
    let cPts = roundedRectPoints(icx - 20, icy - 20, 40, 40, 20, 6);

    if (p.step === 1) {
      // Buckle click diagram icon
      washPoly(cPts, NAVY, 255, 0.02);
      resetBrushState();
      brush.set("specular", "#ffffff", 1.0);
      brush.line(icx - 14, icy, icx - 3, icy);
      brush.line(icx + 3, icy, icx + 14, icy);
      brush.set("navy_marker", "#ffd000", 0.9);
      brush.rect(icx, icy, 10, 10, "center");
    } else if (p.step === 2) {
      // Warning circle: Do Not Inflate Inside Cabin
      washPoly(cPts, "#ffffff", 255, 0.02);
      strokePoly(cPts, "navy_marker", RED_BOLD, 1.2, 0.02, true);
      resetBrushState();
      brush.set("fine_liner", NAVY, 0.8);
      brush.rect(icx, icy + 2, 14, 18, "center");
      brush.set("navy_marker", RED_BOLD, 1.2);
      brush.line(icx - 14, icy - 14, icx + 14, icy + 14);
    } else {
      // Water wave & Automatic Light indicator icon
      washPoly(cPts, NAVY, 255, 0.02);
      resetBrushState();
      brush.set("specular", "#ffd000", 1.1);
      brush.circle(icx, icy - 5, 5);
      for (let a = -150; a <= -30; a += 40) {
        brush.line(icx + cos(a) * 8, icy - 5 + sin(a) * 8, icx + cos(a) * 14, icy - 5 + sin(a) * 14);
      }
      brush.set("specular", "#7cc2ff", 0.9);
      brush.spline([[icx - 13, icy + 9], [icx - 4, icy + 5], [icx + 4, icy + 11], [icx + 13, icy + 7]], 0.5);
    }

    // Technical caption lines inside footer box
    resetBrushState();
    brush.set("navy_marker", NAVY, 0.75);
    brush.line(p.x + 72, fy + 20, p.x + 215, fy + 20);
    brush.set("fine_liner", "#314d6b", 0.75);
    brush.line(p.x + 72, fy + 33, p.x + 295, fy + 33);
    brush.line(p.x + 72, fy + 45, p.x + 255, fy + 45);

    // Small red accent tick on right of footer box
    let tickPts = roundedRectPoints(p.x + p.w - 26, fy + 18, 10, 28, 3, 3);
    washPoly(tickPts, p.step === 2 ? RED_BOLD : "#ffd000", 255, 0.02);
    strokePoly(tickPts, "fine_liner", NAVY, 0.65, 0.02, true);
  }
  resetBrushState();
}

function drawFinalCardGrain() {
  resetBrushState();
  brush.set("card_grain", "#5c748a", 0.85);
  for (let i = 0; i < 18; i++) {
    let y = random(30, 1170);
    brush.line(35, y, 1165, y + random(-8, 8));
  }
  resetBrushState();
}

