// Camera configuration: low three-quarter angle
const CAM = {
  pos: [-235, 535, 240],
  target: [0, 32, 118],
  focal: 1380,
  cx: 600,
  cy: 635
};

let camBasis = {};

function initCamera() {
  let fx = CAM.target[0] - CAM.pos[0];
  let fy = CAM.target[1] - CAM.pos[1];
  let fz = CAM.target[2] - CAM.pos[2];
  let flen = Math.hypot(fx, fy, fz);
  let F = [fx / flen, fy / flen, fz / flen];

  let upRef = [0, 0, 1];
  // R = normalize(cross(F, upRef))
  let rx = F[1] * upRef[2] - F[2] * upRef[1];
  let ry = F[2] * upRef[0] - F[0] * upRef[2];
  let rz = F[0] * upRef[1] - F[1] * upRef[0];
  let rlen = Math.hypot(rx, ry, rz);
  let R = [rx / rlen, ry / rlen, rz / rlen];

  // U = cross(R, F)
  let U = [
    R[1] * F[2] - R[2] * F[1],
    R[2] * F[0] - R[0] * F[2],
    R[0] * F[1] - R[1] * F[0]
  ];
  camBasis = { F, R, U };
}

function proj(x, y, z) {
  let vx = x - CAM.pos[0];
  let vy = y - CAM.pos[1];
  let vz = z - CAM.pos[2];
  let depth = vx * camBasis.F[0] + vy * camBasis.F[1] + vz * camBasis.F[2];
  let rx = vx * camBasis.R[0] + vy * camBasis.R[1] + vz * camBasis.R[2];
  let uy = vx * camBasis.U[0] + vy * camBasis.U[1] + vz * camBasis.U[2];
  let scale = CAM.focal / Math.max(depth, 10);
  return [CAM.cx + rx * scale, CAM.cy - uy * scale, depth];
}

function projPoly(pts3D) {
  return pts3D.map(p => proj(p[0], p[1], p[2]));
}

function lerp3D(a, b, t) {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  ];
}

function bilinear3D(p00, p10, p11, p01, u, v) {
  let a = lerp3D(p00, p10, u);
  let b = lerp3D(p01, p11, u);
  return lerp3D(a, b, v);
}

function polyAngle2D(p0, p1) {
  return atan2(p1[1] - p0[1], p1[0] - p0[0]);
}

