// ============================================================================
// CORE DRAWING HELPERS
// ============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawShape2D(pts, curvature = 0, closeShape = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

function drawPlane3D(pts3D, opts = {}) {
  let pts2D = projPoly(pts3D);
  resetBrushState();

  // Base solid wash or watercolor fill
  if (opts.washColor) {
    brush.wash(opts.washColor, opts.washOpacity ?? 235);
    drawShape2D(pts2D, 0, true);
    brush.noWash();
  }

  if (opts.fillColor) {
    brush.fill(opts.fillColor, opts.fillOpacity ?? 120);
    brush.fillBleed(opts.bleed ?? 0.04, "in");
    brush.fillTexture(opts.tex ?? 0.45, opts.border ?? 0.25);
    drawShape2D(pts2D, 0, true);
    brush.noFill();
  }

  // Primary graphite hatching
  if (opts.hatchDist) {
    let hAngle = opts.hatchAngle;
    if (hAngle === undefined && pts2D.length >= 2) {
      hAngle = polyAngle2D(pts2D[0], pts2D[1]);
    }
    brush.hatchStyle(
      opts.hatchBrush || "2H",
      opts.hatchColor || PALETTE.lead2H,
      opts.hatchWeight || 0.35
    );
    brush.hatch(opts.hatchDist, hAngle, {
      rand: opts.hatchRand ?? 0.03,
      gradient: opts.hatchGrad ?? 0
    });
    drawShape2D(pts2D, 0, true);
    brush.noHatch();
  }

  // Secondary cross-hatching
  if (opts.crossDist) {
    let cAngle = opts.crossAngle;
    if (cAngle === undefined && pts2D.length >= 3) {
      cAngle = polyAngle2D(pts2D[1], pts2D[2]);
    }
    brush.hatchStyle(
      opts.crossBrush || "HB",
      opts.crossColor || PALETTE.leadHB,
      opts.crossWeight || 0.32
    );
    brush.hatch(opts.crossDist, cAngle, {
      rand: opts.crossRand ?? 0.03,
      gradient: opts.crossGrad ?? 0
    });
    drawShape2D(pts2D, 0, true);
    brush.noHatch();
  }

  // Card edge thickness (simulated 1.8mm card thickness on exposed edges)
  if (opts.thicknessOffset) {
    let off = opts.thicknessOffset; // [dx, dy, dz]
    let edgeIndices = opts.thicknessEdges || [[0, 1], [1, 2]];
    for (let [i0, i1] of edgeIndices) {
      let a0 = pts3D[i0];
      let a1 = pts3D[i1];
      let b1 = [a1[0] + off[0], a1[1] + off[1], a1[2] + off[2]];
      let b0 = [a0[0] + off[0], a0[1] + off[1], a0[2] + off[2]];
      let rim2D = projPoly([a0, a1, b1, b0]);
      brush.wash(opts.thicknessColor || PALETTE.cardBright, 240);
      drawShape2D(rim2D, 0, true);
      brush.noWash();

      brush.set("micro_graphite", PALETTE.lead2H, 0.38);
      brush.line(rim2D[2][0], rim2D[2][1], rim2D[3][0], rim2D[3][1]);
      brush.noStroke();
    }
  }

  // Outline stroke
  if (opts.strokeColor !== null) {
    brush.set(
      opts.strokeBrush || "micro_graphite",
      opts.strokeColor || PALETTE.leadHB,
      opts.strokeWeight || 0.48
    );
    drawShape2D(pts2D, 0, true);
    brush.noStroke();
  }

  // Paper fuzz along cut edges
  if (opts.fuzzEdges) {
    brush.set("paper_fuzz", opts.fuzzColor || PALETTE.cardBright, 0.45);
    for (let [i0, i1] of opts.fuzzEdges) {
      let p0 = pts2D[i0];
      let p1 = pts2D[i1];
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
    brush.noStroke();
  }

  resetBrushState();
  return pts2D;
}

// Renders a scored fold line (debossed graphite line + adjacent cream highlight + subtle dash marks)
function drawScoreLine3D(p0, p1, type = "mountain", steps = 26) {
  let a = proj(p0[0], p0[1], p0[2]);
  let b = proj(p1[0], p1[1], p1[2]);
  let dx = b[0] - a[0];
  let dy = b[1] - a[1];
  let len = Math.hypot(dx, dy);
  if (len < 2) return;
  let nx = -dy / len;
  let ny = dx / len;

  // Soft graphite crease shadow along fold
  brush.set("stump_shade", PALETTE.cardShadow1, 0.42);
  brush.line(a[0], a[1], b[0], b[1]);

  // Crisp highlight on lit side of fold ridge
  brush.set("micro_graphite", PALETTE.cardBright, 0.55);
  brush.line(a[0] + nx * 1.3, a[1] + ny * 1.3, b[0] + nx * 1.3, b[1] + ny * 1.3);

  // Dashed/scored indentation marks
  brush.set("micro_graphite", type === "mountain" ? PALETTE.leadHB : PALETTE.lead2H, 0.45);
  for (let i = 0; i < steps; i++) {
    if (i % 2 === 0) {
      let t0 = (i + 0.15) / steps;
      let t1 = (i + 0.85) / steps;
      let x0 = a[0] + dx * t0;
      let y0 = a[1] + dy * t0;
      let x1 = a[0] + dx * t1;
      let y1 = a[1] + dy * t1;
      brush.line(x0, y0, x1, y1);
    }
  }
  brush.noStroke();
}

function drawLine3D(p0, p1, brushName, col, weight) {
  let a = proj(p0[0], p0[1], p0[2]);
  let b = proj(p1[0], p1[1], p1[2]);
  brush.set(brushName, col, weight);
  brush.line(a[0], a[1], b[0], b[1]);
  brush.noStroke();
}

// ============================================================================
// 1. COOL DRAFTING TABLE & PERSPECTIVE GRID
// ============================================================================

function drawDraftingSurface() {
  resetBrushState();

  // Cool indigo-slate atmospheric wash in center of table
  let tableCenter = [
    [80, 120],
    [1120, 120],
    [1120, 1100],
    [80, 1100]
  ];
  brush.fill(PALETTE.matMid, 150);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.6, 0.2);
  drawShape2D(tableCenter, 0, true);
  brush.noFill();

  // Subtle light pool across the table from upper-left
  let lightPool = projPoly([
    [-340, -260, 0],
    [280, -260, 0],
    [320, 340, 0],
    [-340, 340, 0]
  ]);
  brush.fill(PALETTE.matLight, 95);
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.5, 0.15);
  drawShape2D(lightPool, 0, true);
  brush.noFill();

  // Fine architectural cutting-mat grid on Z = 0
  for (let x = -360; x <= 360; x += 40) {
    let isMajor = x % 120 === 0;
    drawLine3D(
      [x, -320, 0],
      [x, 380, 0],
      "micro_graphite",
      isMajor ? PALETTE.matTick : PALETTE.matGrid,
      isMajor ? 0.38 : 0.22
    );
  }
  for (let y = -320; y <= 360; y += 40) {
    let isMajor = y % 120 === 0;
    drawLine3D(
      [-360, y, 0],
      [360, y, 0],
      "micro_graphite",
      isMajor ? PALETTE.matTick : PALETTE.matGrid,
      isMajor ? 0.38 : 0.22
    );
  }

  // Small ruler tick marks along Y = 320
  for (let x = -300; x <= 300; x += 10) {
    let tickLen = x % 50 === 0 ? 10 : 5;
    drawLine3D(
      [x, 320, 0],
      [x, 320 + tickLen, 0],
      "micro_graphite",
      PALETTE.matTick,
      0.3
    );
  }
}

// ============================================================================
// 2. OPEN CARD BASE, OUTER COVER & CUTOUT SLOTS
// ============================================================================

// Helper for height of the open card leaves (slightly tented to Z=14 at center spine Y=0)
function cardZ(y) {
  if (y >= 0) {
    return 14 - (y / 295) * 10; // slopes from Z=14 at spine down to Z=4 at front edge
  } else {
    return 14 - (Math.abs(y) / 235) * 8; // slopes from Z=14 at spine down to Z=6 at back edge
  }
}

function drawOpenCardBase() {
  // 1. Multi-layered ambient drop shadow under the tented card on Z=0
  for (let s = 3; s >= 0; s--) {
    let pad = s * 6;
    let shPts = [
      [-268 - pad + 12, -238 - pad - 8, 0],
      [268 + pad + 18, -238 - pad - 8, 0],
      [268 + pad + 18, 298 + pad - 4, 0],
      [-268 - pad + 12, 298 + pad - 4, 0]
    ];
    drawPlane3D(shPts, {
      washColor: s === 0 ? "#090d14" : "#101621",
      washOpacity: s === 0 ? 210 : 95,
      strokeColor: null
    });
  }

  // Cast shadow of the tall brownstone tower falling back-right onto the table & card
  let towerTableShadow = [
    [155, 0, 0],
    [295, -85, 0],
    [345, -245, 0],
    [140, -255, 0],
    [-40, -235, 0]
  ];
  drawPlane3D(towerTableShadow, {
    washColor: "#0e131d",
    washOpacity: 165,
    hatchDist: 5,
    hatchAngle: -28,
    hatchBrush: "2B",
    hatchColor: PALETTE.lead4B,
    hatchWeight: 0.35,
    strokeColor: null
  });

  // 2. Outer Card Cover (cool slate-indigo backing board extending 14 units past inner cream card)
  let coverBack = [
    [-266, -236, 3],
    [266, -236, 3],
    [266, 0, 11],
    [-266, 0, 11]
  ];
  let coverFront = [
    [-266, 0, 11],
    [266, 0, 11],
    [266, 296, 1.5],
    [-266, 296, 1.5]
  ];
  drawPlane3D(coverBack, {
    washColor: PALETTE.coverDark,
    hatchDist: 7,
    hatchAngle: 15,
    hatchColor: "#1b2330",
    thicknessOffset: [0, 0, -2],
    thicknessEdges: [[3, 0]],
    thicknessColor: PALETTE.coverEdge,
    strokeColor: PALETTE.lead4B
  });
  drawPlane3D(coverFront, {
    washColor: PALETTE.coverMid,
    hatchDist: 7,
    hatchAngle: 15,
    hatchColor: "#222c3c",
    thicknessOffset: [0, 0, -2],
    thicknessEdges: [[2, 3], [3, 0]],
    thicknessColor: PALETTE.coverEdge,
    strokeColor: PALETTE.lead4B
  });

  // 3. Inner Cream Card - Back Leaf (Y = -222 to 0)
  let backLeaf = [
    [-250, -222, cardZ(-222)],
    [250, -222, cardZ(-222)],
    [250, 0, cardZ(0)],
    [-250, 0, cardZ(0)]
  ];
  drawPlane3D(backLeaf, {
    washColor: PALETTE.cardMidLight,
    fillColor: PALETTE.cardCream,
    fillOpacity: 95,
    hatchDist: 9,
    hatchBrush: "2H",
    hatchColor: PALETTE.lead2H,
    hatchWeight: 0.25,
    thicknessOffset: [0, 0, 2.2],
    thicknessEdges: [[3, 0], [0, 1]],
    thicknessColor: PALETTE.cardBright,
