function drawDoorwayAlcove() {
  let yBack = -18;
  let zBase = 126;
  let zTop = 278;

  // Recessed back plane of the doorway
  let doorBack = [
    [-56, yBack, zBase],
    [56, yBack, zBase],
    [56, yBack, zTop],
    [-56, yBack, zTop]
  ];
  drawPlane3D(doorBack, {
    washColor: PALETTE.cardShadow2,
    hatchDist: 4,
    hatchAngle: 90,
    hatchBrush: "HB",
    hatchColor: PALETTE.lead2B,
    hatchWeight: 0.36,
    crossDist: 5.5,
    crossAngle: -30,
    crossBrush: "2H",
    crossColor: PALETTE.leadHB,
    strokeColor: PALETTE.lead2B
  });

  // Left inner jamb (at X = -56, Y = -18..0, lit indirectly)
  drawPlane3D(
    [
      [-56, yBack, zBase],
      [-56, 0, zBase],
      [-56, 0, zTop],
      [-56, yBack, zTop]
    ],
    {
      washColor: PALETTE.cardShadow3,
      hatchDist: 3.5,
      hatchAngle: -45,
      hatchBrush: "2B",
      hatchColor: PALETTE.lead4B,
      strokeColor: PALETTE.lead4B
    }
  );

  // Right inner jamb (at X = +56, Y = -18..0, catches angled light)
  drawPlane3D(
    [
      [56, yBack, zBase],
      [56, 0, zBase],
      [56, 0, zTop],
      [56, yBack, zTop]
    ],
    {
      washColor: PALETTE.cardMid,
      hatchDist: 5.5,
      hatchAngle: 45,
      hatchBrush: "2H",
      hatchColor: PALETTE.leadHB,
      strokeColor: PALETTE.leadHB
    }
  );

  // Double Brownstone Doors (X = -52..0 and 0..+52, Z = 126..218)
  let zTransom = 218;
  // Center seam between double doors
  drawLine3D([0, yBack + 0.5, zBase], [0, yBack + 0.5, zTransom], "micro_graphite", PALETTE.lead4B, 0.65);
  drawLine3D([1.2, yBack + 0.5, zBase], [1.2, yBack + 0.5, zTransom], "micro_graphite", PALETTE.cardCream, 0.45);

  // Recessed kirigami door panels (3 per door leaf)
  let panelZ = [
    [134, 154],
    [160, 188],
    [194, 211]
  ];
  for (let side of [-1, 1]) {
    let xA = side === -1 ? -46 : 8;
    let xB = side === -1 ? -8 : 46;
    for (let [za, zb] of panelZ) {
      let pPts = [
        [xA, yBack + 0.6, za],
        [xB, yBack + 0.6, za],
        [xB, yBack + 0.6, zb],
        [xA, yBack + 0.6, zb]
      ];
      drawPlane3D(pPts, {
        washColor: PALETTE.cardShadow3,
        hatchDist: 3.8,
        hatchAngle: -35,
        hatchBrush: "HB",
        hatchColor: PALETTE.lead4B,
        strokeColor: PALETTE.lead2B
      });
      // Highlight along bottom and right of recessed panel
      drawLine3D([xA, yBack + 0.8, za], [xB, yBack + 0.8, za], "micro_graphite", PALETTE.cardWarmCream, 0.5);
      drawLine3D([xB, yBack + 0.8, za], [xB, yBack + 0.8, zb], "micro_graphite", PALETTE.cardWarmCream, 0.5);
    }
  }

  // Folded Transom Bar at Z = 218..223
  drawPlane3D(
    [
      [-56, yBack, 218],
      [56, yBack, 218],
      [56, -4, 223],
      [-56, -4, 223]
    ],
    {
      washColor: PALETTE.cardCream,
      strokeColor: PALETTE.leadHB,
      thicknessOffset: [0, 0, -2.5],
      thicknessEdges: [[2, 3]],
      thicknessColor: PALETTE.cardMid
    }
  );

  // Kirigami Semicircular Fanlight above Transom (center [0, yBack, 223], radius 48)
  let fanR = 48;
  let fanCenter = [0, yBack + 1, 223];
  // Dark glass void behind fanlight spokes
  let fanVoid = [];
  for (let a = 0; a <= 180; a += 10) {
    fanVoid.push([
      fanCenter[0] + cos(a) * fanR,
      fanCenter[1],
      fanCenter[2] + sin(a) * fanR
    ]);
  }
  drawPlane3D(fanVoid, {
    washColor: PALETTE.cardDeepVoid,
    hatchDist: 3.5,
    hatchAngle: -45,
    hatchBrush: "2B",
    hatchColor: PALETTE.lead4B,
    strokeColor: PALETTE.lead2B
  });

  // Delicate cut cream paper spokes inside fanlight
  for (let a = 22.5; a < 180; a += 22.5) {
    let tip = [
      fanCenter[0] + cos(a) * fanR,
      fanCenter[1] + 0.8,
      fanCenter[2] + sin(a) * fanR
    ];
    drawLine3D(fanCenter, tip, "micro_graphite", PALETTE.cardBright, 0.75);
    drawLine3D(
      [fanCenter[0] + 1, fanCenter[1], fanCenter[2]],
      [tip[0] + 1, tip[1], tip[2]],
      "micro_graphite",
      PALETTE.leadHB,
      0.35
    );
  }
  // Inner paper arch ring in fanlight
  for (let r of [22, 46]) {
    let prev = null;
    for (let a = 0; a <= 180; a += 12) {
      let cur = [
        fanCenter[0] + cos(a) * r,
        fanCenter[1] + 1.0,
        fanCenter[2] + sin(a) * r
      ];
      if (prev) {
        drawLine3D(prev, cur, "micro_graphite", PALETTE.cardBright, 0.7);
      }
      prev = cur;
    }
  }
}

