// ============================================================================
// 6 & 8. KIRIGAMI BALUSTRADE CHEEK WALLS (Left side = -1, Right side = +1)
// ============================================================================

function drawBalustradeWall(side) {
  // side = -1: X in [-106, -82]; side = +1: X in [82, 106]
  let xIn = side === -1 ? -82 : 82;
  let xOut = side === -1 ? -106 : 106;
  let xLeft = Math.min(xIn, xOut);
  let xRight = Math.max(xIn, xOut);

  // The balustrade cheek wall steps down in 3 monumental kirigami box-tiers + a front newel post:
  // Tier 1 (Upper landing wall): Y = 0 to 96, Z_top = 166
  // Tier 2 (Mid-flight wall): Y = 96 to 176, Z_top = 118
  // Tier 3 (Lower-flight wall): Y = 176 to 224, Z_top = 74
  // Tier 4 (Square Newel Post at bottom of stoop): Y = 224 to 260, Z_top = 86
  let tiers = [
    { y0: 0, y1: 96, z0: cardZ(48), z1: 166, panel: [16, 80, 134, 156] },
    { y0: 96, y1: 176, z0: cardZ(136), z1: 118, panel: [110, 162, 74, 106] },
    { y0: 176, y1: 224, z0: cardZ(200), z1: 74, panel: [186, 214, 34, 62] },
    { y0: 224, y1: 260, z0: cardZ(242), z1: 86, isNewel: true, panel: [232, 252, 26, 72] }
  ];

  for (let t of tiers) {
    // 1. Inner face (X = xIn) - visible on the RIGHT balustrade (xIn = +82, facing -X toward camera)
    if (side === 1) {
      drawPlane3D(
        [
          [xIn, t.y0, t.z0],
          [xIn, t.y1, t.z0],
          [xIn, t.y1, t.z1],
          [xIn, t.y0, t.z1]
        ],
        {
          washColor: PALETTE.cardBright,
          fillColor: PALETTE.cardCream,
          fillOpacity: 85,
          hatchDist: 7,
          hatchAngle: 90,
          hatchBrush: "2H",
          hatchColor: PALETTE.lead2H,
          strokeColor: PALETTE.leadHB
        }
      );
    }

    // 2. Outer face (X = xOut) - visible on the LEFT balustrade (xOut = -106, facing -X toward camera)
    if (side === -1) {
      drawPlane3D(
        [
          [xOut, t.y0, t.z0],
          [xOut, t.y1, t.z0],
          [xOut, t.y1, t.z1],
          [xOut, t.y0, t.z1]
        ],
        {
          washColor: PALETTE.cardWarmCream,
          fillColor: PALETTE.cardBright,
          fillOpacity: 100,
          hatchDist: 6.5,
          hatchAngle: 90,
          hatchBrush: "2H",
          hatchColor: PALETTE.lead2H,
          hatchWeight: 0.26,
          strokeColor: PALETTE.leadHB,
          fuzzEdges: [[1, 2], [2, 3]]
        }
      );

      // Recessed kirigami panel cutout on the outer left cheek wall
      if (t.panel) {
        let [py0, py1, pz0, pz1] = t.panel;
        drawPlane3D(
          [
            [xOut + 2.5, py0, pz0],
            [xOut + 2.5, py1, pz0],
            [xOut + 2.5, py1, pz1],
            [xOut + 2.5, py0, pz1]
          ],
          {
            washColor: PALETTE.cardMid,
            hatchDist: 4.5,
            hatchAngle: -35,
            hatchBrush: "HB",
            hatchColor: PALETTE.leadHB,
            strokeColor: PALETTE.leadHB
          }
        );
        drawLine3D([xOut + 0.5, py0, pz0], [xOut + 0.5, py1, pz0], "micro_graphite", PALETTE.cardBright, 0.7);
        drawLine3D([xOut + 0.5, py1, pz0], [xOut + 0.5, py1, pz1], "micro_graphite", PALETTE.cardBright, 0.7);
      }

      // Score lines along vertical box-folds of left balustrade
      drawScoreLine3D([xOut, t.y1, t.z0], [xOut, t.y1, t.z1], "mountain", 14);
    }

    // 3. Front vertical riser face of this balustrade tier (at Y = t.y1)
    drawPlane3D(
      [
        [xLeft, t.y1, t.z0],
        [xRight, t.y1, t.z0],
        [xRight, t.y1, t.z1],
        [xLeft, t.y1, t.z1]
      ],
      {
        washColor: PALETTE.cardMid,
        fillColor: PALETTE.cardCoolMid,
        fillOpacity: 95,
        hatchDist: 5,
        hatchAngle: 90,
        hatchBrush: "HB",
        hatchColor: PALETTE.leadHB,
        crossDist: 7.5,
        crossAngle: 0,
        crossBrush: "2H",
        crossColor: PALETTE.lead2H,
        strokeColor: PALETTE.leadHB
      }
    );

    // 4. Overhanging Kirigami Coping Cap on top of this balustrade tier (Z = t.z1)
    let capPad = 2.5;
    let capPts = [
      [xLeft - capPad, t.y0, t.z1 + 3],
      [xRight + capPad, t.y0, t.z1 + 3],
      [xRight + capPad, t.y1 + capPad, t.z1 + 3],
      [xLeft - capPad, t.y1 + capPad, t.z1 + 3]
    ];
    drawPlane3D(capPts, {
      washColor: PALETTE.cardBright,
      hatchDist: 8,
      hatchAngle: 0,
      hatchBrush: "2H",
      hatchColor: PALETTE.lead2H,
      hatchWeight: 0.2,
      thicknessOffset: [0, 0, -3],
      thicknessEdges: [[1, 2], [2, 3], [3, 0]],
      thicknessColor: PALETTE.cardWarmCream,
      strokeColor: PALETTE.leadHB,
      fuzzEdges: [[2, 3], [3, 0]]
    });

    // If Newel Post, add a stepped pyramid finial cap in folded cream card
    if (t.isNewel) {
      let fx0 = xLeft + 2;
      let fx1 = xRight - 2;
      let fy0 = t.y0 + 5;
      let fy1 = t.y1 - 5;
      let fz = t.z1 + 3;
      drawPlane3D(
        [
          [fx0, fy1, fz],
          [fx1, fy1, fz],
          [fx1, fy1, fz + 8],
          [fx0, fy1, fz + 8]
        ],
        {
          washColor: PALETTE.cardMid,
          strokeColor: PALETTE.leadHB
        }
      );
      drawPlane3D(
        [
          [fx0, fy0, fz],
          [fx0, fy1, fz],
          [fx0, fy1, fz + 8],
          [fx0, fy0, fz + 8]
        ],
        {
          washColor: PALETTE.cardBright,
          strokeColor: PALETTE.leadHB
        }
      );
      drawPlane3D(
        [
          [fx0, fy0, fz + 8],
          [fx1, fy0, fz + 8],
          [fx1, fy1, fz + 8],
          [fx0, fy1, fz + 8]
        ],
        {
          washColor: PALETTE.cardBright,
          strokeColor: PALETTE.leadHB
        }
      );
    }
  }
}

