// 7. STOOP STEPS & LANDING (CASCADING KIRIGAMI TREADS, RISERS & SHADOWS)
// ============================================================================

function drawStoopSteps() {
  // 6 Tiers from Top Landing (Z = 126) down to Step 1 (Z = 21)
  // Built back-to-front so overhangs and shadows layer naturally
  let steps = [
    { zTop: 126, zBot: 105, yBack: 0, yFront: 92, isLanding: true },
    { zTop: 105, zBot: 84, yBack: 92, yFront: 124 },
    { zTop: 84, zBot: 63, yBack: 124, yFront: 156 },
    { zTop: 63, zBot: 42, yBack: 156, yFront: 188 },
    { zTop: 42, zBot: 21, yBack: 188, yFront: 220 },
    { zTop: 21, zBot: cardZ(252), yBack: 220, yFront: 252, isBottom: true }
  ];

  let xL = -82;
  let xR = 82;

  for (let i = 0; i < steps.length; i++) {
    let s = steps[i];

    // 1. Horizontal Step Tread (Z = s.zTop, Y = s.yBack to s.yFront + 2.5 nosing)
    let yNose = s.yFront + 2.5;
    let treadPts = [
      [xL, s.yBack, s.zTop],
      [xR, s.yBack, s.zTop],
      [xR, yNose, s.zTop],
      [xL, yNose, s.zTop]
    ];
    drawPlane3D(treadPts, {
      washColor: PALETTE.cardBright,
      fillColor: PALETTE.cardCream,
      fillOpacity: 95,
      hatchDist: s.isLanding ? 8.5 : 7.5,
      hatchAngle: 0,
      hatchBrush: "2H",
      hatchColor: PALETTE.lead2H,
      hatchWeight: 0.24,
      strokeColor: PALETTE.leadHB,
      fuzzEdges: [[2, 3]]
    });

    // Subtle stone slab joint score lines on the treads (3 slabs across X: -82..-28, -28..28, 28..82)
    for (let sx of [-28, 28]) {
      drawLine3D([sx, s.yBack + 1, s.zTop + 0.2], [sx, yNose - 1, s.zTop + 0.2], "micro_graphite", PALETTE.lead2H, 0.32);
      drawLine3D([sx + 1.2, s.yBack + 1, s.zTop + 0.2], [sx + 1.2, yNose - 1, s.zTop + 0.2], "micro_graphite", PALETTE.cardBright, 0.45);
    }

    // Cast shadow from the LEFT Balustrade Wall stepping diagonally across the left side of this tread!
    // Left wall height above this tread determines shadow width in +X
    let wallH = i === 0 ? 43 : i <= 2 ? 38 : 30;
    let shW = wallH * 0.85;
    let treadShadowPts = [
      [xL, s.yBack, s.zTop + 0.25],
      [xL + shW, s.yBack, s.zTop + 0.25],
      [xL + shW * 0.78, yNose, s.zTop + 0.25],
      [xL, yNose, s.zTop + 0.25]
    ];
    drawPlane3D(treadShadowPts, {
      washColor: PALETTE.cardShadow1,
      washOpacity: 155,
      hatchDist: 4,
      hatchAngle: -28,
      hatchBrush: "HB",
      hatchColor: PALETTE.leadHB,
      hatchWeight: 0.32,
      strokeColor: null
    });

    // Inside Valley Fold Score Line at the back of the tread (where riser meets tread)
    if (!s.isLanding) {
      drawScoreLine3D([xL, s.yBack, s.zTop], [xR, s.yBack, s.zTop], "valley", 22);
    } else {
      // Threshold score line at doorway (Y = 0, Z = 126)
      drawScoreLine3D([xL, 0, s.zTop], [xR, 0, s.zTop], "valley", 22);
    }

    // 2. Vertical Step Riser (at Y = s.yFront, from Z = s.zBot to s.zTop)
    let riserPts = [
      [xL, s.yFront, s.zBot],
      [xR, s.yFront, s.zBot],
      [xR, s.yFront, s.zTop],
      [xL, s.yFront, s.zTop]
    ];
    drawPlane3D(riserPts, {
      washColor: PALETTE.cardCoolMid,
      fillColor: PALETTE.cardShadow1,
      fillOpacity: 110,
      hatchDist: 4.5,
      hatchAngle: 90,
      hatchBrush: "HB",
      hatchColor: PALETTE.leadHB,
      hatchWeight: 0.34,
      crossDist: 7,
      crossAngle: -18,
      crossBrush: "2H",
      crossColor: PALETTE.lead2H,
      crossWeight: 0.26,
      strokeColor: PALETTE.leadHB
    });

    // Diagonal cast shadow of left balustrade continuing down the left side of the riser
    let riserShadowPts = [
      [xL, s.yFront + 0.3, s.zBot],
      [xL + shW * 0.9, s.yFront + 0.3, s.zBot],
      [xL + shW * 0.78, s.yFront + 0.3, s.zTop],
      [xL, s.yFront + 0.3, s.zTop]
    ];
    drawPlane3D(riserShadowPts, {
      washColor: PALETTE.cardShadow2,
      washOpacity: 175,
      hatchDist: 3.4,
      hatchAngle: -35,
      hatchBrush: "2B",
      hatchColor: PALETTE.lead2B,
      hatchWeight: 0.35,
      strokeColor: null
    });

    // Crisp Nosing Under-Shadow (directly under the 2.5mm overhanging lip of the tread)
    let lipShadowPts = [
      [xL, s.yFront + 0.4, s.zTop - 4.5],
      [xR, s.yFront + 0.4, s.zTop - 4.5],
      [xR, s.yFront + 0.4, s.zTop],
      [xL, s.yFront + 0.4, s.zTop]
    ];
    drawPlane3D(lipShadowPts, {
      washColor: PALETTE.cardShadow3,
      washOpacity: 205,
      strokeColor: null
    });

    // Exposed 2.2mm Cream Card Thickness Strip along the overhanging front lip (Y = yNose)
    let nosingRimPts = [
      [xL, yNose, s.zTop - 2.2],
      [xR, yNose, s.zTop - 2.2],
      [xR, yNose, s.zTop],
      [xL, yNose, s.zTop]
    ];
    drawPlane3D(nosingRimPts, {
      washColor: PALETTE.cardWarmCream,
      strokeColor: PALETTE.leadHB
    });

    // Mountain Fold Score Line along the front nosing edge
    drawScoreLine3D([xL, yNose, s.zTop], [xR, yNose, s.zTop], "mountain", 24);
  }
}

