// ============================================================================
// 10. THE SLEEPING BEAGLE (HYPERREAL COLORED PENCIL ON THE TOP STEP LANDING)
// ============================================================================

// Helper to draw an organic 2D polygon from 3D points with smooth curvature
function drawOrganic3D(pts3D, opts = {}) {
  let pts2D = projPoly(pts3D);
  resetBrushState();

  if (opts.washColor) {
    brush.wash(opts.washColor, opts.washOpacity ?? 225);
    drawShape2D(pts2D, opts.curvature ?? 0.55, true);
    brush.noWash();
  }

  if (opts.fillColor) {
    brush.fill(opts.fillColor, opts.fillOpacity ?? 125);
    brush.fillBleed(opts.bleed ?? 0.06, "in");
    brush.fillTexture(opts.tex ?? 0.5, opts.border ?? 0.2);
    drawShape2D(pts2D, opts.curvature ?? 0.55, true);
    brush.noFill();
  }

  if (opts.massColor) {
    brush.mass(opts.massBrush || "cpencil", opts.massColor, {
      precision: opts.massPrecision ?? 0.75,
      strength: opts.massStrength ?? 0.65,
      gradient: opts.massGradient ?? 0.2,
      outline: false
    });
    drawShape2D(pts2D, opts.curvature ?? 0.55, true);
    brush.noMass();
  }

  if (opts.strokeColor) {
    brush.set(opts.strokeBrush || "cpencil", opts.strokeColor, opts.strokeWeight || 0.45);
    drawShape2D(pts2D, opts.curvature ?? 0.55, true);
    brush.noStroke();
  }

  resetBrushState();
  return pts2D;
}

// Helper to render directional colored-pencil fur strands over a 3D patch
function renderFurFlow3D(patch00, patch10, patch11, patch01, opts) {
  let count = opts.count || 90;
  let lenU = opts.lenU ?? 0.14;
  let lenV = opts.lenV ?? 0.05;
  let archZ = opts.archZ ?? 1.2;
  let colors = opts.colors || [PALETTE.furTanMid];
  let brushName = opts.brush || "fur_fine";
  let weightRange = opts.weightRange || [0.35, 0.68];

  for (let i = 0; i < count; i++) {
    let u0 = random(0.03, 0.92);
    let v0 = random(0.04, 0.94);
    let du = lenU * random(0.75, 1.25);
    let dv = lenV * random(-0.8, 0.8);

    let pStart = bilinear3D(patch00, patch10, patch11, patch01, u0, v0);
    let pMid = bilinear3D(
      patch00,
      patch10,
      patch11,
      patch01,
      constrain(u0 + du * 0.5, 0, 1),
      constrain(v0 + dv * 0.5, 0, 1)
    );
    pMid[2] += archZ * random(0.6, 1.3);
    let pEnd = bilinear3D(
      patch00,
      patch10,
      patch11,
      patch01,
      constrain(u0 + du, 0, 1),
      constrain(v0 + dv, 0, 1)
    );

    let s0 = proj(pStart[0], pStart[1], pStart[2]);
    let s1 = proj(pMid[0], pMid[1], pMid[2]);
    let s2 = proj(pEnd[0], pEnd[1], pEnd[2]);

    let col = colors[floor(random(colors.length))];
    let w = random(weightRange[0], weightRange[1]);
    brush.set(brushName, col, w);
    brush.spline(
      [
        [s0[0], s0[1], 0.4],
        [s1[0], s1[1], 1.1],
        [s2[0], s2[1], 0.15]
      ],
      0.5
    );
  }
  brush.noStroke();
}

