    { start: [-23.0, 96.2, zL + 2.4], mid: [-14, 102, zL - 0.5], end: [-4, 105, zL - 7.5] },
    { start: [-21.2, 94.4, zL + 2.8], mid: [-11, 100, zL + 0.2], end: [1, 103, zL - 6.0] },
    // Supraorbital (brow) whiskers
    { start: [-21.5, 73.5, zL + 20.5], mid: [-15, 74, zL + 25], end: [-8, 72, zL + 26] },
    { start: [-19.5, 73.0, zL + 20.2], mid: [-12, 73, zL + 24], end: [-5, 71, zL + 24.5] }
  ];

  // Left-side whiskers (arching out toward -X over the front-left of the step)
  let leftWhiskers = [
    { start: [-36.5, 94.2, zL + 5.2], mid: [-47, 98, zL + 3.5], end: [-58, 99, zL - 2.5] },
    { start: [-38.0, 91.8, zL + 5.8], mid: [-49, 95, zL + 4.2], end: [-60, 95, zL - 1.0] },
    { start: [-39.2, 89.2, zL + 6.2], mid: [-50, 92, zL + 5.0], end: [-61, 91, zL + 0.5] },
    { start: [-37.2, 96.0, zL + 3.4], mid: [-48, 100, zL + 1.0], end: [-57, 101, zL - 5.5] },
    { start: [-38.8, 93.8, zL + 3.8], mid: [-50, 97, zL + 1.5], end: [-59, 98, zL - 4.0] }
  ];

  let allWhiskers = rightWhiskers.concat(leftWhiskers);
  for (let w of allWhiskers) {
    let p0 = proj(w.start[0], w.start[1], w.start[2]);
    let p1 = proj(w.mid[0], w.mid[1], w.mid[2]);
    let p2 = proj(w.end[0], w.end[1], w.end[2]);

    // Subtle dark shadow just beneath each whisker for hyperreal pop
    brush.set("micro_graphite", PALETTE.lead2B, 0.32);
    brush.spline(
      [
        [p0[0], p0[1] + 1.0, 0.5],
        [p1[0], p1[1] + 1.2, 0.7],
        [p2[0], p2[1] + 1.2, 0.1]
      ],
      0.5
    );

    // Crisp bright cream-white whisker shaft tapering to a fine tip
    brush.set("fur_fine", PALETTE.furWhiteBright, 0.52);
    brush.spline(
      [
        [p0[0], p0[1], 0.85],
        [p1[0], p1[1], 0.65],
        [p2[0], p2[1], 0.12]
      ],
      0.5
    );
  }

  // 2. Rim-Light Guard Hairs along the Beagle's Crown, Back, and Tail
  let rimCrown = [
    [-34, 54, zL + 29],
    [-20, 48, zL + 34],
    [-2, 36, zL + 35],
    [22, 29, zL + 39],
    [44, 38, zL + 31]
  ];
  for (let i = 0; i < rimCrown.length - 1; i++) {
    let a = rimCrown[i];
    let b = rimCrown[i + 1];
    for (let t = 0; t < 1; t += 0.12) {
      let p = lerp3D(a, b, t);
      let s0 = proj(p[0], p[1], p[2]);
      let s1 = proj(p[0] + random(-2, 3), p[1] - 2, p[2] + random(2.5, 4.5));
      brush.set("fur_fine", i < 2 ? PALETTE.furGold : PALETTE.furTanBright, 0.42);
      brush.line(s0[0], s0[1], s1[0], s1[1]);
    }
  }

  // 3. Tiny Paper Shavings / Knife-Cut Micro-Fibers on the Cream Card near the Pop-Up Cuts
  let shavings3D = [
    [-118, 258, cardZ(258)],
    [-76, 266, cardZ(266)],
    [88, 262, cardZ(262)],
    [-168, 18, cardZ(18)],
    [-142, -18, cardZ(-18)]
  ];
  for (let sh of shavings3D) {
    let sp = proj(sh[0], sh[1], sh[2]);
    brush.set("micro_graphite", PALETTE.leadHB, 0.35);
    brush.line(sp[0], sp[1] + 1, sp[0] + 5, sp[1] + 2);
    brush.set("fur_fine", PALETTE.cardBright, 0.55);
    brush.spline(
      [
        [sp[0], sp[1], 0.4],
        [sp[0] + 3, sp[1] - 1.5, 0.9],
        [sp[0] + 6, sp[1] + 0.5, 0.3]
      ],
      0.5
    );
  }

  resetBrushState();
}

// =============================================================================
// HYPERREALIST ANALYTIC CUBISM — SHATTERED BUTTON ACCORDION
// 1200 x 1200 WEBGL | p5.js 2.x + p5.brush
// =============================================================================

const PAL = {
  paper:        "#eae1cf",
  boneBright:   "#fbf8f0",
  boneLight:    "#efe8d8",
  boneMid:      "#d8ceba",
  boneDark:     "#bcb097",
  slatePale:    "#a3adb2",
  slateLight:   "#7d878c",
  slateMid:     "#566066",
  slateDark:    "#363d42",
  slateBlack:   "#1d2226",
  umberLight:   "#7c654d",
  umberMid:     "#584532",
  umberDark:    "#36291c",
  charcoal:     "#191512",
  ochreBright:  "#ebb64b", // Single warm accent family (golden ochre / amber)
  ochreMid:     "#c98922",
  ochreDeep:    "#8f5910"
};

// Geometric utilities: local-to-world transform & Sutherland-Hodgman clipping
function toWorld(u, v, cx, cy, angDeg, sc = 1) {
  const r = (angDeg * Math.PI) / 180;
  const c = Math.cos(r) * sc;
  const s = Math.sin(r) * sc;
  return [cx + u * c - v * s, cy + u * s + v * c];
}

function polyArea(pts) {
  if (!pts || pts.length < 3) return 0;
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    const j = (i + 1) % pts.length;
    a += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1];
  }
  return Math.abs(a) * 0.5;
}

function polyCentroid(pts) {
  let sx = 0, sy = 0;
  for (let i = 0; i < pts.length; i++) {
    sx += pts[i][0];
    sy += pts[i][1];
  }
  return [sx / pts.length, sy / pts.length];
}

// Ensure polygon vertices are ordered clockwise (screen space) for clipping
function ensureCW(pts) {
  let sum = 0;
  for (let i = 0; i < pts.length; i++) {
    const p1 = pts[i], p2 = pts[(i + 1) % pts.length];
    sum += (p2[0] - p1[0]) * (p2[1] + p1[1]);
  }
  return sum > 0 ? pts.slice().reverse() : pts;
}

// Sutherland-Hodgman polygon clipper against a convex shard polygon
function clipPolygon(subjectPts, clipPts) {
  if (!subjectPts || subjectPts.length < 3) return [];
  const clip = ensureCW(clipPts);
  let output = subjectPts.map(p => [p[0], p[1]]);

  for (let i = 0; i < clip.length; i++) {
    const A = clip[i];
    const B = clip[(i + 1) % clip.length];
    const input = output;
    output = [];
    if (input.length === 0) break;

    const isInside = (p) => (B[0] - A[0]) * (p[1] - A[1]) - (B[1] - A[1]) * (p[0] - A[0]) >= -1e-5;
    const intersect = (P, Q) => {
      const dx1 = Q[0] - P[0], dy1 = Q[1] - P[1];
      const dx2 = B[0] - A[0], dy2 = B[1] - A[1];
      const denom = dx1 * dy2 - dy1 * dx2;
      if (Math.abs(denom) < 1e-7) return [P[0], P[1]];
      const t = ((A[0] - P[0]) * dy2 - (A[1] - P[1]) * dx2) / denom;
      return [P[0] + t * dx1, P[1] + t * dy1];
    };

    let S = input[input.length - 1];
    for (let j = 0; j < input.length; j++) {
      const E = input[j];
      if (isInside(E)) {
        if (!isInside(S)) output.push(intersect(S, E));
        output.push(E);
      } else if (isInside(S)) {
        output.push(intersect(S, E));
      }
      S = E;
    }
  }

  // Deduplicate very close vertices to prevent p5.brush zero-length edge issues
  const cleaned = [];
  for (let i = 0; i < output.length; i++) {
    const prev = cleaned.length > 0 ? cleaned[cleaned.length - 1] : output[output.length - 1];
    if ( Math.hypot(output[i][0] - prev[0], output[i][1] - prev[1]) > 1.2 ) {
      cleaned.push(output[i]);
    }
  }
  return cleaned.length >= 3 && polyArea(cleaned) > 6 ? cleaned : [];
}

// Clip a 2D line segment [x1,y1]-[x2,y2] against a convex shard polygon
function clipSegment(x1, y1, x2, y2, clipPts) {
  const clip = ensureCW(clipPts);
  let t0 = 0, t1 = 1;
  const dx = x2 - x1, dy = y2 - y1;

  for (let i = 0; i < clip.length; i++) {
    const A = clip[i];
    const B = clip[(i + 1) % clip.length];
    // Inward normal for CW polygon in screen coords: [-(B.y - A.y), B.x - A.x]
    const nx = -(B[1] - A[1]);
    const ny = B[0] - A[0];
    const numer = nx * (x1 - A[0]) + ny * (y1 - A[1]);
    const denom = nx * dx + ny * dy;

    if (Math.abs(denom) < 1e-7) {
      if (numer < 0) return null;
    } else {
      const t = -numer / denom;
      if (denom < 0) {
        if (t < t1) t1 = t;
      } else {
        if (t > t0) t0 = t;
      }
      if (t0 > t1) return null;
    }
  }
  if (t0 > t1) return null;
  const cx1 = x1 + t0 * dx, cy1 = y1 + t0 * dy;
  const cx2 = x1 + t1 * dx, cy2 = y1 + t1 * dy;
  if (Math.hypot(cx2 - cx1, cy2 - cy1) < 1.2) return null;
  return [cx1, cy1, cx2, cy2];
}

function pointInConvexPoly(x, y, clipPts) {
  const clip = ensureCW(clipPts);
  for (let i = 0; i < clip.length; i++) {
    const A = clip[i], B = clip[(i + 1) % clip.length];
    if ((B[0] - A[0]) * (y - A[1]) - (B[1] - A[1]) * (x - A[0]) < 0) return false;
  }
  return true;
}

// Safe shape drawer for p5.brush
function drawPoly(pts, curvature = 0, close = true) {
  if (!pts || pts.length < 3 || polyArea(pts) <= 6) return false;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
  return true;
}

function drawClippedPoly(pts, shardPoly, curvature = 0) {
  const c = clipPolygon(pts, shardPoly);
  if (c.length >= 3) return drawPoly(c, curvature, true);
  return false;
}

function drawClippedLine(x1, y1, x2, y2, shardPoly) {
  const seg = clipSegment(x1, y1, x2, y2, shardPoly);
  if (seg) brush.line(seg[0], seg[1], seg[2], seg[3]);
}

function makeEllipsePoly(cx, cy, rx, ry, rotDeg = 0, steps = 20) {
  const pts = [];
  const rad = (rotDeg * Math.PI) / 180;
  const cr = Math.cos(rad), sr = Math.sin(rad);
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    const ux = Math.cos(a) * rx;
    const uy = Math.sin(a) * ry;
    pts.push([cx + ux * cr - uy * sr, cy + ux * sr + uy * cr]);
  }
  return pts;
}

