// 1. BELLOWS FOLDS WITH WORN LEATHER CORNERS & NICKEL CORNER PROTECTORS
function renderBellowsShard(shard, cfg) {
  const { poly } = shard;
  const {
    cx, cy, ang, sc = 1,
    pleatCount = 5,
    pleatH = 56,
    pleatW = 240,
    fanDeg = 3.5,
    cornerSide = "both", // "left", "right", "both"
    accentGusset = true
  } = cfg;

  const halfN = (pleatCount - 1) * 0.5;

  for (let i = 0; i < pleatCount; i++) {
    const idx = i - halfN;
    const y0 = idx * pleatH;
    const yMid = y0 + pleatH * 0.46;
    const y1 = y0 + pleatH;

    // Slight perspective fan per pleat
    const localAng = ang + idx * fanDeg;
    const W = (u, v) => toWorld(u, v, cx, cy, localAng, sc);

    const leftOuterTop = -pleatW * 0.5;
    const leftInnerVal = -pleatW * 0.5 + 36;
    const rightOuterTop = pleatW * 0.5;
    const rightInnerVal = pleatW * 0.5 - 36;

    // Upper lit face of pleat (bone/slate linen cloth)
    const upperFace = [
      W(leftOuterTop, y0),
      W(rightOuterTop, y0),
      W(rightInnerVal, yMid),
      W(leftInnerVal, yMid)
    ];

    // Lower shadowed face of pleat (deep raw umber / charcoal)
    const lowerFace = [
      W(leftInnerVal, yMid),
      W(rightInnerVal, yMid),
      W(rightOuterTop, y1),
      W(leftOuterTop, y1)
    ];

    // Draw Upper Lit Face
    brush.noStroke();
    brush.wash(i % 2 === 0 ? PAL.boneMid : PAL.slatePale, 210);
    drawClippedPoly(upperFace, poly);
    brush.noWash();

    // Linen weave hatching on upper face
    brush.hatchStyle("2H", PAL.umberMid, 0.45);
    brush.hatch(5.5, localAng + 18, { rand: 0.04 });
    drawClippedPoly(upperFace, poly);
    brush.noHatch();

    // Draw Lower Shadow Face
    brush.wash(PAL.umberDark, 235);
    drawClippedPoly(lowerFace, poly);
    brush.noWash();

    brush.mass("charcoal", PAL.charcoal, { precision: 0.75, strength: 0.65, gradient: 0.3, outline: false });
    drawClippedPoly(lowerFace, poly);
    brush.noMass();

    brush.hatchStyle("2B", PAL.charcoal, 0.55);
    brush.hatch(4, localAng - 8, { rand: 0.05 });
    drawClippedPoly(lowerFace, poly);
    brush.noHatch();

    // Left & Right Recessed Gusset Triangles (Golden Ochre Accent + Umber Shadow)
    const sides = [];
    if (cornerSide === "left" || cornerSide === "both") sides.push(-1);
    if (cornerSide === "right" || cornerSide === "both") sides.push(1);

    for (const sDir of sides) {
      const xPeak = sDir * (pleatW * 0.5 + 14);
      const xValley = sDir * (pleatW * 0.5 - 36);
      const xOuter = sDir * (pleatW * 0.5);

      // Recessed triangular gusset pocket
      const gussetUpper = [
        W(xOuter, y0),
        W(xValley, yMid),
        W(xOuter + sDir * 4, yMid - 4)
      ];
      const gussetLower = [
        W(xOuter + sDir * 4, yMid - 4),
        W(xValley, yMid),
        W(xOuter, y1)
      ];

      brush.noStroke();
      brush.wash(accentGusset ? PAL.ochreMid : PAL.umberLight, 225);
      drawClippedPoly(gussetUpper, poly);
      brush.wash(accentGusset ? PAL.ochreDeep : PAL.umberDark, 235);
      drawClippedPoly(gussetLower, poly);
      brush.noWash();

      // Gusset fold crease
      brush.set("rotring", PAL.charcoal, 0.55);
      const gCreaseA = W(xValley, yMid);
      const gCreaseB = W(xOuter + sDir * 4, yMid - 4);
      drawClippedLine(gCreaseA[0], gCreaseA[1], gCreaseB[0], gCreaseB[1], poly);

      // WORN LEATHER DIAMOND CORNER REINFORCEMENT around ridge y0
      const leatherDiamond = [
        W(xOuter - sDir * 30, y0),
        W(xOuter - sDir * 10, y0 - 15),
        W(xPeak, y0),
        W(xOuter - sDir * 10, y0 + 15)
      ];
      brush.noStroke();
      brush.wash(PAL.boneLight, 220);
      drawClippedPoly(leatherDiamond, poly);
      brush.noWash();

      // Scuffed suede wear & radial leather creases on the corner
      const scuffPatch = [
        W(xOuter - sDir * 22, y0 - 2),
        W(xOuter - sDir * 9, y0 - 9),
        W(xOuter - sDir * 4, y0 + 2),
        W(xOuter - sDir * 16, y0 + 7)
      ];
      brush.wash(PAL.umberLight, 155);
      drawClippedPoly(scuffPatch, poly);
      brush.noWash();

      // Tiny leather wrinkles and frayed suede edge hairs on corner
      brush.set("rotring", PAL.umberDark, 0.35);
      for (let w = -2; w <= 2; w++) {
        const pA = W(xOuter - sDir * 26, y0 + w * 2.2);
        const pB = W(xOuter - sDir * 8, y0 + w * 4.5);
        drawClippedLine(pA[0], pA[1], pB[0], pB[1], poly);
      }

      // STAMPED NICKEL / STEEL CORNER PROTECTOR (CALOTTE) on tip
      const calotteBase = [
        W(xOuter - sDir * 14, y0 - 10),
        W(xPeak + sDir * 3, y0 - 3),
        W(xPeak + sDir * 5, y0),
        W(xPeak + sDir * 3, y0 + 3),
        W(xOuter - sDir * 14, y0 + 10),
        W(xOuter - sDir * 18, y0)
      ];
      brush.noStroke();
      brush.wash(PAL.slateDark, 240);
      drawClippedPoly(calotteBase, poly);

      const calotteLit = [
        W(xOuter - sDir * 13, y0 - 8),
        W(xPeak + sDir * 3, y0 - 2),
        W(xPeak + sDir * 4, y0),
        W(xOuter - sDir * 15, y0)
      ];
      brush.wash(PAL.slatePale, 235);
      drawClippedPoly(calotteLit, poly);
      brush.noWash();

      // Specular metallic highlights & stamped crimp ribs on corner protector
      brush.set("rotring", PAL.boneBright, 0.65);
      const spec1 = W(xOuter - sDir * 12, y0 - 6);
      const spec2 = W(xPeak + sDir * 3, y0 - 1);
      drawClippedLine(spec1[0], spec1[1], spec2[0], spec2[1], poly);

      brush.set("rotring", PAL.charcoal, 0.5);
      const crimp1 = W(xOuter - sDir * 15, y0 + 2);
      const crimp2 = W(xPeak + sDir * 3, y0 + 1);
      drawClippedLine(crimp1[0], crimp1[1], crimp2[0], crimp2[1], poly);
    }

    // Outer Ridge Highlight (Bone Chalk + crisp Rotring edge)
    const rL = W(leftOuterTop, y0);
    const rR = W(rightOuterTop, y0);
    brush.set("cpencil", PAL.boneBright, 1.15);
    drawClippedLine(rL[0], rL[1], rR[0], rR[1], poly);
    brush.set("rotring", PAL.umberDark, 0.45);
    drawClippedLine(rL[0], rL[1] + 1.5, rR[0], rR[1] + 1.5, poly);

    // Inner Valley Deep Crevice Line
    const vL = W(leftInnerVal, yMid);
    const vR = W(rightInnerVal, yMid);
    brush.set("2B", PAL.charcoal, 1.1);
    drawClippedLine(vL[0], vL[1], vR[0], vR[1], poly);
  }
}

// 2. PEARL CELLULOID KEYS & STEPPED BUTTONBOARD RENDERER
function renderButtonShard(shard, cfg) {
  const { poly } = shard;
  const {
    cx, cy, ang, sc = 1,
    rows = 3,
    cols = 6,
    rowSpacing = 44,
    colSpacing = 48,
    btnRadius = 16.5,
    aspect = 0.72,
    isBass = false
  } = cfg;

  const W = (u, v) => toWorld(u, v, cx, cy, ang, sc);

  // Dark ebonized wood / slate fingerboard base with stepped terraces
  for (let r = 0; r < rows; r++) {
    const ry0 = (r - (rows - 1) * 0.5) * rowSpacing - rowSpacing * 0.55;
    const ry1 = ry0 + rowSpacing * 1.1;
    const strip = [
      W(-cols * colSpacing * 0.65, ry0),
      W(cols * colSpacing * 0.65, ry0),
      W(cols * colSpacing * 0.65, ry1),
      W(-cols * colSpacing * 0.65, ry1)
    ];
    brush.noStroke();
    brush.wash(r % 2 === 0 ? PAL.umberDark : PAL.slateBlack, 215);
    drawClippedPoly(strip, poly);
    brush.noWash();

    // Step riser bevel line between rows
    const stepA = W(-cols * colSpacing * 0.65, ry0);
    const stepB = W(cols * colSpacing * 0.65, ry0);
    brush.set("cpencil", PAL.slateLight, 0.7);
    drawClippedLine(stepA[0], stepA[1], stepB[0], stepB[1], poly);
    brush.set("rotring", PAL.charcoal, 0.75);
    drawClippedLine(stepA[0], stepA[1] + 2, stepB[0], stepB[1] + 2, poly);
  }

  // Fine woodgrain / brushed celluloid hatching on fingerboard
  brush.hatchStyle("2H", PAL.charcoal, 0.45);
  brush.hatch(5, ang + 2, { rand: 0.03 });
  brush.noStroke();
  drawPoly(poly);
  brush.noHatch();

  // Render each pearl button in 3D foreshortened relief
  const rx = btnRadius * sc;
  const ry = btnRadius * aspect * sc;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const stagger = (r % 2) * (colSpacing * 0.5);
      const u = (c - (cols - 1) * 0.5) * colSpacing + stagger;
      const v = (r - (rows - 1) * 0.5) * rowSpacing;

      // Depressed state variation for hyperreal liveliness
      const depressed = ((r + c * 2) % 5 === 0) ? 0.6 : 1.0;
      const liftU = -4.5 * depressed;
      const liftV = -6.5 * depressed;

      const socketC = W(u, v);
      const capC = W(u + liftU, v + liftV);

      // Skip if far outside shard
      if (!pointInConvexPoly(socketC[0], socketC[1], poly) &&
          !pointInConvexPoly(capC[0], capC[1], poly)) {
        // Still allow partial edge buttons if close to centroid
        const cent = polyCentroid(poly);
        if (Math.hypot(capC[0] - cent[0], capC[1] - cent[1]) > 260) continue;
      }

      // 1. Socket Well & Cast Shadow on Fingerboard
      const wellPoly = makeEllipsePoly(socketC[0] + 2.5, socketC[1] + 3.5, rx * 1.06, ry * 1.06, ang, 18);
      brush.noStroke();
      brush.wash(PAL.charcoal, 245);
      drawClippedPoly(wellPoly, poly);
      brush.noWash();

      // Metallic bushing collar around socket
      const collarArc = makeEllipsePoly(socketC[0], socketC[1], rx * 1.12, ry * 1.12, ang, 18);
      brush.set("rotring", PAL.slateLight, 0.55);
      for (let k = 2; k < 10; k++) {
        drawClippedLine(collarArc[k][0], collarArc[k][1], collarArc[k + 1][0], collarArc[k + 1][1], poly);
      }

      // 2. Cylindrical Metal Piston Stem under the button cap
      const stemW = rx * 0.38;
      const stemPoly = [
        [socketC[0] - stemW, socketC[1] + 1],
        [socketC[0] + stemW, socketC[1] + 1],
        [capC[0] + stemW, capC[1] + ry * 0.5],
        [capC[0] - stemW, capC[1] + ry * 0.5]
      ];
      brush.noStroke();
      brush.wash(PAL.slateLight, 230);
      drawClippedPoly(stemPoly, poly);
      brush.noWash();

      // 3. Button Side Cylinder Rim (Beveled Metal/Celluloid Collar)
      const rimPoly = makeEllipsePoly(
        (socketC[0] * 0.35 + capC[0] * 0.65),
        (socketC[1] * 0.35 + capC[1] * 0.65),
        rx * 1.01, ry * 1.01, ang, 20
      );
      brush.noStroke();
      brush.wash(isBass ? PAL.ochreDeep : PAL.umberMid, 240);
      drawClippedPoly(rimPoly, poly);
      brush.noWash();

      // 4. Mother-of-Pearl / Pearl Celluloid Top Cap
      const topPoly = makeEllipsePoly(capC[0], capC[1], rx, ry, ang, 22);
      brush.noStroke();
      brush.wash(PAL.boneLight, 248);
      drawClippedPoly(topPoly, poly);
      brush.noWash();

      // Nacreous Iridescent Swirls inside Pearl Key (Bone, Slate, Cream & Ochre Glint)
      const nacre1 = makeEllipsePoly(capC[0] - rx * 0.25, capC[1] - ry * 0.18, rx * 0.52, ry * 0.42, ang + 25, 12);
      const nacre2 = makeEllipsePoly(capC[0] + rx * 0.22, capC[1] + ry * 0.16, rx * 0.48, ry * 0.36, ang - 20, 12);
      const nacreOchre = makeEllipsePoly(capC[0] + rx * 0.1, capC[1] - ry * 0.22, rx * 0.32, ry * 0.22, ang + 10, 10);
      const concaveShadow = makeEllipsePoly(capC[0] - rx * 0.12, capC[1] - ry * 0.12, rx * 0.68, ry * 0.64, ang, 14);
      const concaveGlow = makeEllipsePoly(capC[0] + rx * 0.14, capC[1] + ry * 0.14, rx * 0.55, ry * 0.5, ang, 14);

      brush.noStroke();
      brush.wash(PAL.slatePale, 150);
      drawClippedPoly(concaveShadow, poly);
      brush.wash(PAL.boneMid, 185);
      drawClippedPoly(nacre2, poly);
      brush.wash(PAL.ochreBright, ((r + c) % 3 === 0) ? 145 : 75);
      drawClippedPoly(nacreOchre, poly);
      brush.wash(PAL.boneBright, 225);
      drawClippedPoly(nacre1, poly);
      brush.wash(PAL.boneBright, 210);
      drawClippedPoly(concaveGlow, poly);
      brush.noWash();

      // Tactile cross-hatched reference key (C / F marker button)
      if (!isBass && (r === 0 && (c === 1 || c === 4))) {
        for (let k = -2; k <= 2; k++) {
          const p1 = W(u + liftU - 7, v + liftV + k * 2.8);
          const p2 = W(u + liftU + 7, v + liftV + k * 2.8);
          brush.set("rotring", PAL.umberDark, 0.38);
          drawClippedLine(p1[0], p1[1], p2[0], p2[1], poly);
        }
      }

      // Crisp Specular Rim on Upper-Left & Dark Micro-Bevel on Lower-Right
      for (let k = 0; k < topPoly.length; k++) {
        const pA = topPoly[k];
        const pB = topPoly[(k + 1) % topPoly.length];
        if (k >= 10 && k <= 19) {
          brush.set("rotring", PAL.boneBright, 0.8);
        } else {
          brush.set("rotring", PAL.umberDark, 0.55);
        }
        drawClippedLine(pA[0], pA[1], pB[0], pB[1], poly);
      }
    }
  }
}

// 3. PERFORATED NICKEL GRILLE RENDERER (STAMPED FRETWORK & METALLIC SHEEN)
function renderGrilleShard(shard, cfg) {
  const { poly } = shard;
  const {
    cx, cy, ang, sc = 1,
    cols = 6,
    rows = 4,
    cellW = 42,
    cellH = 54
  } = cfg;

  const W = (u, v) => toWorld(u, v, cx, cy, ang, sc);

  // 1. Base Brushed Nickel-Silver Plate
  brush.noStroke();
  brush.wash(PAL.slateLight, 225);
  drawPoly(poly);
  brush.noWash();

  // Diagonal metallic specular sheen bands across the nickel sheet
  for (let b = -2; b <= 2; b++) {
    const bx = b * 68;
    const sheenStrip = [
      W(bx - 22, -220),
      W(bx + 18, -220),
      W(bx + 85, 220),
      W(bx + 45, 220)
    ];
    brush.noStroke();
    brush.wash(b % 2 === 0 ? PAL.boneLight : PAL.slateDark, b % 2 === 0 ? 150 : 140);
    drawClippedPoly(sheenStrip, poly);
    brush.noWash();
  }

  // Fine brushed metal grain
  brush.hatchStyle("2H", PAL.boneBright, 0.45);
  brush.hatch(4.5, ang + 32, { rand: 0.02 });
  brush.noStroke();
  drawPoly(poly);
  brush.noHatch();

  // Moulded Chrome / Nickel Border Ribs
  for (const ribY of [-rows * cellH * 0.52, rows * cellH * 0.52]) {
    const ribA = W(-220, ribY);
    const ribB = W(220, ribY);
    const ribC = W(-220, ribY + 6);
    const ribD = W(220, ribY + 6);
    brush.set("cpencil", PAL.boneBright, 1.3);
    drawClippedLine(ribA[0], ribA[1], ribB[0], ribB[1], poly);
    brush.set("rotring", PAL.slateBlack, 0.85);
    drawClippedLine(ribC[0], ribC[1], ribD[0], ribD[1], poly);
  }

  // 2. Stamped Geometric Fretwork Holes (Art-Deco Diamonds, Lyre Slots & Rosettes)
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const u = (c - (cols - 1) * 0.5) * cellW;
      const v = (r - (rows - 1) * 0.5) * cellH;

      let holeLocal = [];
      if ((r + c) % 2 === 0) {
        // Stepped Art-Deco Diamond Lozenge Cutout
        const hw = cellW * 0.34, hh = cellH * 0.39;
        holeLocal = [
          [u, v - hh],
          [u + hw * 0.65, v - hh * 0.35],
          [u + hw, v],
          [u + hw * 0.65, v + hh * 0.35],
          [u, v + hh],
          [u - hw * 0.65, v + hh * 0.35],
          [u - hw, v],
          [u - hw * 0.65, v - hh * 0.35]
        ];
      } else {
        // Elongated Slotted Lyre Cutout
        const hw = cellW * 0.22, hh = cellH * 0.41;
        holeLocal = [
          [u - hw * 0.5, v - hh],
          [u + hw * 0.5, v - hh],
          [u + hw, v - hh * 0.6],
          [u + hw, v + hh * 0.6],
          [u + hw * 0.5, v + hh],
          [u - hw * 0.5, v + hh],
          [u - hw, v + hh * 0.6],
          [u - hw, v - hh * 0.6]
        ];
      }

      const holeWorld = holeLocal.map(pt => W(pt[0], pt[1]));
      // Shifted inner edge to show physical thickness of stamped nickel sheet
      const thicknessWorld = holeLocal.map(pt => W(pt[0] + 2.6, pt[1] + 2.8));

      // Draw dark felt/reed interior void
      brush.noStroke();
      brush.wash(PAL.charcoal, 248);
      const drawn = drawClippedPoly(holeWorld, poly);
      brush.noWash();

      if (!drawn) continue;

      // Glimpse of warm ochre felt / pallet lever inside select grille holes
      if ((r * 3 + c) % 4 === 0) {
        const innerOchre = [
          W(u - 4, v - 10),
          W(u + 6, v - 10),
          W(u + 2, v + 12),
          W(u - 8, v + 12)
        ];
        brush.noStroke();
        brush.wash(PAL.ochreMid, 185);
        drawClippedPoly(innerOchre, poly);
        brush.noWash();
      }

      // Draw stamped sheet-metal thickness along top-left & bright specular bevel on bottom-right
      for (let k = 0; k < holeWorld.length; k++) {
        const pA = holeWorld[k];
        const pB = holeWorld[(k + 1) % holeWorld.length];
        const tA = thicknessWorld[k];
        const tB = thicknessWorld[(k + 1) % thicknessWorld.length];

        // Top/left inner thickness rim
        if (k === 0 || k === 5 || k === 6 || k === 7) {
          brush.set("rotring", PAL.slateMid, 0.65);
          drawClippedLine(tA[0], tA[1], tB[0], tB[1], poly);
          brush.set("rotring", PAL.charcoal, 0.55);
          drawClippedLine(pA[0], pA[1], pB[0], pB[1], poly);
        } else {
          // Bottom/right stamped edge catching gleaming bone-white highlight!
          brush.set("rotring", PAL.boneBright, 0.85);
          drawClippedLine(pA[0], pA[1], pB[0], pB[1], poly);
        }
      }
    }
  }
}

// 4. FRAYED LEATHER SHOULDER STRAP & TARNISHED BUCKLE RENDERER
function renderStrapShard(shard, cfg) {
  const { poly } = shard;
  const {
    cx, cy, ang, sc = 1,
    strapLen = 280,
    strapW = 54,
    curve = 26,
    hasBuckle = false
  } = cfg;

  const steps = 16;
  const leftEdge = [], rightEdge = [], midRight = [], suedeStrip = [];

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const u = (t - 0.5) * strapLen;
    const bend = Math.sin(t * Math.PI) * curve;
    const wHalf = strapW * 0.5 * (1 - 0.08 * Math.sin(t * Math.PI * 2));

    leftEdge.push(toWorld(u, bend - wHalf, cx, cy, ang, sc));
    rightEdge.push(toWorld(u, bend + wHalf, cx, cy, ang, sc));
    midRight.push(toWorld(u, bend + wHalf * 0.25, cx, cy, ang, sc));
    suedeStrip.push(toWorld(u, bend - wHalf * 0.55, cx, cy, ang, sc));
  }

  const fullStrapPoly = leftEdge.concat(rightEdge.slice().reverse());
  const shadowHalfPoly = midRight.concat(rightEdge.slice().reverse());
  const wornEdgePoly = leftEdge.concat(suedeStrip.slice().reverse());

  // 1. Base Raw Umber Leather Body
  brush.noStroke();
  brush.wash(PAL.umberMid, 235);
  drawClippedPoly(fullStrapPoly, poly);

  // Deep shadow along lower half of leather strap
  brush.wash(PAL.umberDark, 220);
  drawClippedPoly(shadowHalfPoly, poly);

  // Worn golden-ochre suede margin along upper edge
  brush.wash(PAL.ochreMid, 165);
  drawClippedPoly(wornEdgePoly, poly);
  brush.noWash();

  // Dry charcoal mass for rounded leather volume
  brush.mass("charcoal", PAL.charcoal, { precision: 0.7, strength: 0.55, gradient: 0.4, outline: false });
  drawClippedPoly(shadowHalfPoly, poly);
  brush.noMass();

  // 2. Transverse Leather Stress Cracks & Creases
  for (let i = 1; i < steps; i++) {
    const t = i / steps;
    const u = (t - 0.5) * strapLen;
    const bend = Math.sin(t * Math.PI) * curve;
    const wHalf = strapW * 0.46;

    const cA = toWorld(u - 3, bend - wHalf, cx, cy, ang, sc);
    const cM = toWorld(u + 2, bend, cx, cy, ang, sc);
    const cB = toWorld(u - 2, bend + wHalf, cx, cy, ang, sc);

    brush.set("rotring", PAL.charcoal, 0.5);
    drawClippedLine(cA[0], cA[1], cM[0], cM[1], poly);
    drawClippedLine(cM[0], cM[1], cB[0], cB[1], poly);

    // Pale suede lip beside main cracks
    if (i % 2 === 0) {
      brush.set("rotring", PAL.boneMid, 0.4);
      drawClippedLine(cA[0] + 1.5, cA[1] + 1.5, cM[0] + 1.5, cM[1] + 1.5, poly);
    }
  }

  // 3. Double Saddle-Stitching (Individual Waxed Bone/Ochre Thread Stitches + Needle Holes)
  for (const offsetRatio of [-0.36, 0.36]) {
    for (let i = 0; i < steps * 2; i++) {
      const t0 = i / (steps * 2);
      const t1 = (i + 0.58) / (steps * 2);
      const u0 = (t0 - 0.5) * strapLen;
      const u1 = (t1 - 0.5) * strapLen;
      const v0 = Math.sin(t0 * Math.PI) * curve + strapW * offsetRatio;
      const v1 = Math.sin(t1 * Math.PI) * curve + strapW * offsetRatio + 1.2;

      const p0 = toWorld(u0, v0, cx, cy, ang, sc);
      const p1 = toWorld(u1, v1, cx, cy, ang, sc);

      // Needle puncture shadow
      brush.set("rotring", PAL.charcoal, 0.9);
      drawClippedLine(p0[0], p0[1], p0[0] + 1.5, p0[1] + 1.5, poly);
      // Waxed thread stitch
      brush.set("rotring", i % 3 === 0 ? PAL.ochreBright : PAL.boneLight, 0.65);
      drawClippedLine(p0[0], p0[1], p1[0], p1[1], poly);
    }
  }

  // 4. Adjustment Punch Holes & Tarnished Steel Roller Buckle
  for (let h = -1; h <= 1; h++) {
    const hu = h * 34;
    const hv = Math.sin((0.5 + hu / strapLen) * Math.PI) * curve;
    const hp = toWorld(hu, hv, cx, cy, ang, sc);
    const holeP = makeEllipsePoly(hp[0], hp[1], 4.5 * sc, 3.2 * sc, ang, 10);
    brush.noStroke();
    brush.wash(PAL.charcoal, 245);
    drawClippedPoly(holeP, poly);
    brush.noWash();
    brush.set("rotring", PAL.ochreMid, 0.5);
    for (let k = 0; k < 5; k++) {
      drawClippedLine(holeP[k][0], holeP[k][1], holeP[k + 1][0], holeP[k + 1][1], poly);
    }
  }

  if (hasBuckle) {
    const bU = -18;
    const bV = Math.sin((0.5 + bU / strapLen) * Math.PI) * curve;
    const buckleOuter = [
      toWorld(bU - 20, bV - strapW * 0.62, cx, cy, ang, sc),
      toWorld(bU + 20, bV - strapW * 0.62, cx, cy, ang, sc),
      toWorld(bU + 20, bV + strapW * 0.62, cx, cy, ang, sc),
      toWorld(bU - 20, bV + strapW * 0.62, cx, cy, ang, sc)
    ];
    const buckleBar = [
      toWorld(bU - 14, bV - strapW * 0.52, cx, cy, ang, sc),
      toWorld(bU - 7, bV - strapW * 0.52, cx, cy, ang, sc),
      toWorld(bU - 7, bV + strapW * 0.52, cx, cy, ang, sc),
      toWorld(bU - 14, bV + strapW * 0.52, cx, cy, ang, sc)
    ];
    brush.noStroke();
    brush.wash(PAL.slateLight, 235);
    drawClippedPoly(buckleBar, poly);
    brush.noWash();

    brush.set("cpencil", PAL.boneBright, 1.3);
    drawClippedLine(buckleOuter[0][0], buckleOuter[0][1], buckleOuter[1][0], buckleOuter[1][1], poly);
    drawClippedLine(buckleOuter[1][0], buckleOuter[1][1], buckleOuter[2][0], buckleOuter[2][1], poly);
    brush.set("rotring", PAL.charcoal, 0.9);
    drawClippedLine(buckleOuter[2][0], buckleOuter[2][1], buckleOuter[3][0], buckleOuter[3][1], poly);

    // Buckle tongue pin
    const pinA = toWorld(bU + 14, bV, cx, cy, ang, sc);
    const pinB = toWorld(bU - 18, bV - 2, cx, cy, ang, sc);
    brush.set("cpencil", PAL.boneBright, 1.2);
    drawClippedLine(pinA[0], pinA[1], pinB[0], pinB[1], poly);
  }

  // 5. HYPERREAL FRAYED SUEDE FIBERS along the worn strap edges
  // Some clipped inside the shard, some spilling across the shard boundary for tactile Cubist passage!
  for (let i = 0; i <= steps * 3; i++) {
    const t = i / (steps * 3);
    const u = (t - 0.5) * strapLen;
    const bend = Math.sin(t * Math.PI) * curve;
    for (const side of [-1, 1]) {
      const baseV = bend + side * (strapW * 0.49);
      const fiberLen = 8 + ((i * 7) % 19);
      const flare = side * (6 + ((i * 5) % 14));
      const p0 = toWorld(u, baseV, cx, cy, ang, sc);
      const pMid = toWorld(u + 5, baseV + flare * 0.55, cx, cy, ang, sc);
      const p1 = toWorld(u + fiberLen, baseV + flare, cx, cy, ang, sc);

      if (!pointInConvexPoly(p0[0], p0[1], poly)) continue;

      const col = (i % 4 === 0) ? PAL.ochreBright : (i % 2 === 0 ? PAL.boneMid : PAL.umberLight);
      brush.set("rotring", col, 0.35 + (i % 3) * 0.12);
      // Allow every 3rd fiber to spill slightly out of the shard edge for hyperreal physical relief
      if (i % 3 === 0) {
        brush.spline([p0, pMid, p1], 0.5);
      } else {
        drawClippedLine(p0[0], p0[1], pMid[0], pMid[1], poly);
        drawClippedLine(pMid[0], pMid[1], p1[0], p1[1], poly);
      }
    }
  }
}

// 5. EXPOSED INTERIOR REED BLOCKS, WAX FILLETS & STEEL REED TONGUES (X-RAY SHARDS)
function renderReedBlockShard(shard, cfg) {
  const { poly } = shard;
  const { cx, cy, ang, sc = 1, count = 5 } = cfg;
  const W = (u, v) => toWorld(u, v, cx, cy, ang, sc);

  // Warm Ochre Pine / Alder Reed Block Base (The primary golden accent core!)
  brush.noStroke();
  brush.wash(PAL.ochreMid, 220);
  drawPoly(poly);
  brush.noWash();

  // Woodgrain hatching in burnt ochre & raw umber
  brush.hatchStyle("2H", PAL.ochreDeep, 0.5);
  brush.hatch(4.5, ang + 4, { rand: 0.04 });
  brush.noStroke();
  drawPoly(poly);
  brush.noHatch();

  const pitch = 38;
  for (let i = 0; i < count; i++) {
    const u = (i - (count - 1) * 0.5) * pitch;

    // Aluminum Reed Plate set in golden beeswax fillet
    const plate = [
      W(u - 13, -75),
      W(u + 13, -75),
      W(u + 13, 75),
      W(u - 13, 75)
    ];
    brush.noStroke();
    brush.wash(PAL.slatePale, 230);
    drawClippedPoly(plate, poly);

    // Golden beeswax seal along plate edges
    const waxStrip = [
      W(u - 16, -78),
      W(u - 12, -78),
      W(u - 12, 78),
      W(u - 16, 78)
    ];
    brush.wash(PAL.ochreBright, 220);
    drawClippedPoly(waxStrip, poly);

    // Dark air slot & blue-steel reed tongue
    const reedTongue = [
      W(u - 4.5, -58),
      W(u + 4.5, -58),
      W(u + 3.2, 48),
      W(u - 3.2, 48)
    ];
    brush.wash(PAL.slateDark, 245);
    drawClippedPoly(reedTongue, poly);

    // Curled cream-leather check valve beside the steel reed
    const valve = [
      W(u + 5.5, -54),
      W(u + 11, -54),
      W(u + 12, 42),
      W(u + 5.5, 44)
    ];
    brush.wash(PAL.boneLight, 235);
    drawClippedPoly(valve, poly);
    brush.noWash();

    // Rivet at top of reed tongue
    const rivC = W(u, -48);
    const rivPoly = makeEllipsePoly(rivC[0], rivC[1], 4.5 * sc, 4.5 * sc, 0, 10);
    brush.noStroke();
    brush.wash(PAL.ochreBright, 240);
    drawClippedPoly(rivPoly, poly);
    brush.noWash();

    // Crisp metallic highlights
    const hA = W(u - 3.2, -55);
    const hB = W(u - 2.2, 45);
    brush.set("rotring", PAL.boneBright, 0.65);
    drawClippedLine(hA[0], hA[1], hB[0], hB[1], poly);

    const bA = W(u + 13, -75);
    const bB = W(u + 13, 75);
    brush.set("rotring", PAL.charcoal, 0.65);
    drawClippedLine(bA[0], bA[1], bB[0], bB[1], poly);
  }
}

// 6. WOODEN CASING CROWN, INLAID PURFLING & BASS SLOTS RENDERER
function renderCasingShard(shard, cfg) {
  const { poly } = shard;
  const { cx, cy, ang, sc = 1, hasInlay = true } = cfg;
  const W = (u, v) => toWorld(u, v, cx, cy, ang, sc);

  // Polished Raw Umber Casing Plane
  brush.noStroke();
  brush.wash(PAL.umberMid, 225);
  drawPoly(poly);
  brush.noWash();

  brush.mass("charcoal", PAL.umberDark, { precision: 0.75, strength: 0.55, gradient: 0.45, outline: false });
  drawPoly(poly);
  brush.noMass();

  // Moulded bevel planes
  const moulding = [
    W(-160, -28),
    W(160, -28),
    W(160, 14),
    W(-160, 14)
  ];
  brush.noStroke();
  brush.wash(PAL.umberDark, 230);
  drawClippedPoly(moulding, poly);
  brush.noWash();

  // Inlaid Bone & Ochre Herringbone Purfling Strip
  if (hasInlay) {
    const purfA = W(-160, -34);
    const purfB = W(160, -34);
    const purfC = W(-160, -24);
    const purfD = W(160, -24);
    brush.set("cpencil", PAL.boneBright, 0.9);
    drawClippedLine(purfA[0], purfA[1], purfB[0], purfB[1], poly);
    brush.set("cpencil", PAL.ochreBright, 0.85);
    drawClippedLine(purfC[0], purfC[1], purfD[0], purfD[1], poly);

    for (let k = -14; k <= 14; k++) {
      const p1 = W(k * 11, -34);
      const p2 = W(k * 11 + 6, -24);
      brush.set("rotring", k % 2 === 0 ? PAL.boneLight : PAL.charcoal, 0.5);
      drawClippedLine(p1[0], p1[1], p2[0], p2[1], poly);
    }
  }

  // Specular Varnish Sheen on Moulded Edge
  const sheenA = W(-150, 15);
  const sheenB = W(150, 15);
  brush.set("cpencil", PAL.boneLight, 1.15);
  drawClippedLine(sheenA[0], sheenA[1], sheenB[0], sheenB[1], poly);
}

// =============================================================================
// CUBIST SHARD EDGE ARCHITECTURE, CHIAROSCURO & SCUTTLING HATCHING
// =============================================================================

function renderShardFrame(shard) {
  const { poly, litEdges = [0, 3], bleedEdges = [1, 2], shadowDir = 15 } = shard;
  const n = poly.length;

  // 1. Exterior drop-shadow hatching along non-lit edges to make shards project in 3D relief
  for (let i = 0; i < n; i++) {
    const A = poly[i];
    const B = poly[(i + 1) % n];
    const edgeLen = Math.hypot(B[0] - A[0], B[1] - A[1]);

    if (bleedEdges.includes(i)) {
      // Shallow-angle scuttling hatching crossing the shard border (Analytic Cubist passage)
      const steps = Math.floor(edgeLen / 5.5);
      for (let s = 0; s <= steps; s++) {
        const t = s / Math.max(1, steps);
        const px = A[0] + (B[0] - A[0]) * t;
        const py = A[1] + (B[1] - A[1]) * t;
        const hAng = (shadowDir + Math.sin(s * 0.7) * 6) * (Math.PI / 180);
        const hLen = 16 + (s % 4) * 7;
        const x1 = px - Math.cos(hAng) * hLen * 0.45;
        const y1 = py - Math.sin(hAng) * hLen * 0.45;
        const x2 = px + Math.cos(hAng) * hLen * 0.85;
        const y2 = py + Math.sin(hAng) * hLen * 0.85;

        brush.set(s % 3 === 0 ? "2B" : "HB", s % 2 === 0 ? PAL.charcoal : PAL.slateDark, 0.48);
        brush.line(x1, y1, x2, y2);
      }
    }

    if (litEdges.includes(i)) {
      // Incisive architectural edge extending slightly past the vertex + bone chalk highlight
      const dx = (B[0] - A[0]) / edgeLen;
      const dy = (B[1] - A[1]) / edgeLen;
      const ext = 18;

      brush.set("rotring", PAL.charcoal, 0.85);
      brush.line(A[0] - dx * ext, A[1] - dy * ext, B[0] + dx * ext, B[1] + dy * ext);

      // Bone chalk ridge highlight just inside the shard edge
      const nx = -dy * 2.2, ny = dx * 2.2;
      brush.set("cpencil", PAL.boneBright, 1.25);
      brush.line(A[0] + nx, A[1] + ny, B[0] + nx, B[1] + ny);
    } else {
      // Subtle graphite structural line
      brush.set("HB", PAL.umberDark, 0.6);
      brush.line(A[0], A[1], B[0], B[1]);
    }
  }
}

// Dedicated generator for shallow-angle hatching scuttling across the gaps between shards
function drawScuttlingGapHatching(zones) {
  for (const z of zones) {
    const { x, y, w, h, ang = -11, density = 26, col = PAL.charcoal, accent = false } = z;
    const rad = (ang * Math.PI) / 180;
    const ca = Math.cos(rad), sa = Math.sin(rad);
    const nx = -sa, ny = ca;

    for (let i = 0; i < density; i++) {
      const t = (i / (density - 1)) - 0.5;
      const spread = t * h;
      const jitterX = (random() - 0.5) * 14;
      const jitterY = (random() - 0.5) * 6;
      const curLen = w * (0.55 + 0.45 * Math.cos(t * Math.PI)) * (0.85 + 0.3 * random());

      const cx = x + nx * spread + jitterX;
      const cy = y + ny * spread + jitterY;

      const x1 = cx - ca * curLen * 0.5;
      const y1 = cy - sa * curLen * 0.5;
      const x2 = cx + ca * curLen * 0.5;
      const y2 = cy + sa * curLen * 0.5;

      const bName = (i % 4 === 0) ? "charcoal" : (i % 2 === 0 ? "2B" : "2H");
      const strokeCol = (accent && i % 5 === 0) ? PAL.ochreDeep : col;
      const wt = bName === "charcoal" ? 0.55 : 0.48;

      brush.set(bName, strokeCol, wt);
      brush.line(x1, y1, x2, y2);
    }
  }
}

