const COS_A = Math.cos(S_ANG);
const SIN_A = Math.sin(S_ANG);

// Precomputed spoon profile for exact Signed Distance Function (SDF)
let spoonProfile = [];

// Ebru vortices (Bülbül Yuvası - nightingale's nest swirls)
const VORTICES = [
  { x: 235, y: 265, r: 245, omega: 3.3 },
  { x: 955, y: 250, r: 260, omega: -3.7 },
  { x: 245, y: 935, r: 255, omega: -3.4 },
  { x: 960, y: 925, r: 245, omega: 3.5 },
  { x: 525, y: 195, r: 175, omega: -2.3 },
  { x: 695, y: 1005, r: 185, omega: 2.5 }
];

// Vivid & saturated Ebru harmonic palette: Indigo, Carmine, Saffron, Moss Green, Kitre Cream
const EBRU_BANDS = [
  { family: "indigo",  fill: "#10255C", core: "#183884", light: "#2954B2", rim: "#07112E", weight: 25 },
  { family: "indigo",  fill: "#1B4298", core: "#2455BD", light: "#3B73E0", rim: "#0B1D4A", weight: 21 },
  { family: "kitre",   fill: "#F4ECE0", core: "#FAF5EC", light: "#FFFFFF", rim: "#CFC2AE", weight: 8  },
  { family: "carmine", fill: "#940B2D", core: "#B81139", light: "#DC234E", rim: "#590419", weight: 24 },
  { family: "carmine", fill: "#CF1540", core: "#E6224F", light: "#FF476E", rim: "#7A0823", weight: 22 },
  { family: "saffron", fill: "#E08406", core: "#F59E0B", light: "#FFBF2E", rim: "#9E5302", weight: 23 },
  { family: "saffron", fill: "#F7AC0A", core: "#FFC21F", light: "#FFDC5E", rim: "#B56704", weight: 20 },
  { family: "kitre",   fill: "#F2E9DC", core: "#FAF4EA", light: "#FFFFFF", rim: "#C9BBA6", weight: 7  },
  { family: "moss",    fill: "#1D4D2B", core: "#296939", light: "#3D8C4D", rim: "#0E2916", weight: 23 },
  { family: "moss",    fill: "#38803B", core: "#4C9C48", light: "#6EC25A", rim: "#1B451F", weight: 24 },
  { family: "saffron", fill: "#E89208", core: "#FDB016", light: "#FFD147", rim: "#995203", weight: 16 },
  { family: "carmine", fill: "#B31037", core: "#D61B47", light: "#F23864", rim: "#69061E", weight: 19 }
];

// Spoon half-width profile in local spoon coordinates u in [-390, +390]
function spoonHalfWidth(u) {
  if (u < -390 || u > 390) return 0;
  if (u <= -65) {
    // Pointed oval antique bowl: u in [-390, -65]
    let t = (u + 390) / 325;
    let tipEnv = Math.pow(Math.sin(Math.PI * Math.pow(t, 0.67)), 0.86);
    return 112 * tipEnv * (1 - 0.15 * t * t) + 14.5 * Math.pow(t, 2.2);
  } else if (u <= 190) {
    // Slender waisted neck & stem: u in [-65, 190]
    let t = (u + 65) / 255;
    let dip = 2.6 * Math.sin(Math.PI * Math.min(1, t / 0.44));
    return 14.5 - dip + 8.5 * Math.pow(t, 1.65);
  } else {
    // Ornate Victorian/Ottoman fiddle-and-scroll terminal: u in [190, 390]
    let t = (u - 190) / 200;
    let closeEnv = 1 - Math.pow(t, 4.6);
    let swell = 31.5 * Math.pow(Math.sin(Math.PI * Math.pow(t, 0.76)), 1.12);
    let scallop = 3.8 * Math.sin(3 * Math.PI * t) * Math.sin(Math.PI * t);
    return closeEnv * (23.0 + swell + scallop);
  }
}

function initSpoonProfile() {
  spoonProfile = [];
  const N = 160;
  for (let i = 0; i <= N; i++) {
    let u = -390 + (780 * i) / N;
    let w = spoonHalfWidth(u);
    spoonProfile.push({ u, w });
  }
}

// Convert canvas (x, y) to spoon local (u, v)
function toSpoonLocal(x, y) {
  let dx = x - SCX;
  let dy = y - SCY;
  return {
    u: dx * COS_A + dy * SIN_A,
    v: -dx * SIN_A + dy * COS_A
  };
}

// Convert spoon local (u, v) to canvas (x, y)
function toCanvasXY(u, v) {
  return [
    SCX + u * COS_A - v * SIN_A,
    SCY + u * SIN_A + v * COS_A
  ];
}

// Exact Signed Distance & Outward Normal to the Spoon Silhouette
function sdSpoonInfo(x, y) {
  let loc = toSpoonLocal(x, y);
  let u = loc.u;
  let av = Math.abs(loc.v);
  let sgnV = loc.v >= 0 ? 1 : -1;

  let minD2 = 1e12;
  let bestU = 0;
  let bestW = 0;

  for (let i = 0; i < spoonProfile.length - 1; i++) {
    let p0 = spoonProfile[i];
    let p1 = spoonProfile[i + 1];
    let du = p1.u - p0.u;
    let dw = p1.w - p0.w;
    let len2 = du * du + dw * dw;
    let t = len2 > 0 ? ((u - p0.u) * du + (av - p0.w) * dw) / len2 : 0;
    t = Math.max(0, Math.min(1, t));
    let cu = p0.u + t * du;
    let cw = p0.w + t * dw;
    let d2 = (u - cu) * (u - cu) + (av - cw) * (av - cw);
    if (d2 < minD2) {
      minD2 = d2;
      bestU = cu;
      bestW = cw;
    }
  }

  let dist = Math.sqrt(minD2);
  let inside = u > -390 && u < 390 && av < spoonHalfWidth(u);
  let sd = inside ? -dist : dist;

  // Compute outward unit normal in local (u, v), then rotate to canvas (x, y)
  let nu = u - bestU;
  let nv = (av - bestW) * sgnV;
  if (inside) {
    nu = -nu;
    nv = -nv;
  }
  let nlen = Math.hypot(nu, nv);
  if (nlen < 1e-6) {
    nu = 0;
    nv = sgnV;
  } else {
    nu /= nlen;
    nv /= nlen;
  }

  let nx = nu * COS_A - nv * SIN_A;
  let ny = nu * SIN_A + nv * COS_A;
  return { sd, nx, ny, u, v: loc.v };
}

// Nonpareil feather waveform: pointed comb tips + graceful rounded arches
function featherWave(phase) {
  return (
    Math.sin(phase) -
    0.29 * Math.sin(2 * phase) +
    0.13 * Math.sin(3 * phase) -
    0.05 * Math.sin(4 * phase)
  );
}

// Forward Diffeomorphism from undisturbed Ebru bath (u0, v0) to Canvas (x, y)
// Includes: stylus river waves, fine nonpareil combing, 6 vortices, and spoon meniscus deflection
function mapEbruPoint(u0, v0) {
  // 1. Broad stylus undulations across the bath
  let v1 =
    v0 +
    52 * Math.sin(u0 * 0.0041 + 0.6) +
    28 * Math.cos(u0 * 0.0078 - v0 * 0.0024);
  let u1 = u0 + 26 * Math.sin(v0 * 0.0046 + 1.1);

  // 2. Fine Nonpareil Combing (Taraklı Ebru)
  let toothPitch = 84;
  let combPhase = (u1 + 28 * Math.sin(v1 * 0.0052 + 0.4)) * ((2 * Math.PI) / toothPitch);
  let combAmp = 92 + 24 * Math.sin(u1 * 0.0035 + v1 * 0.0031);
  let v2 = v1 + combAmp * featherWave(combPhase);
  let u2 = u1 + 10 * Math.cos(combPhase);

  // 3. Rotate rivers diagonally (+16 deg) to contrast with the -34 deg spoon
  let bathAng = (16 * Math.PI) / 180;
  let cb = Math.cos(bathAng);
  let sb = Math.sin(bathAng);
  let x = 600 + (u2 - 600) * cb - (v2 - 600) * sb;
  let y = 600 + (u2 - 600) * sb + (v2 - 600) * cb;

  // 4. Nightingale's Nest Swirls (Vortices)
  for (let i = 0; i < VORTICES.length; i++) {
    let vx = VORTICES[i];
    let dx = x - vx.x;
    let dy = y - vx.y;
    let r2 = dx * dx + dy * dy;
    let R2 = vx.r * vx.r;
    if (r2 < R2 * 4.5) {
      let theta = vx.omega * Math.exp(-r2 / R2);
      let ct = Math.cos(theta);
      let st = Math.sin(theta);
      x = vx.x + dx * ct - dy * st;
      y = vx.y + dx * st + dy * ct;
    }
  }

  // 5. Fluid Meniscus Deflection around the Half-Sunk Spoon
  // Strictly monotonic radial compression: derivative 1 + push'(sd) >= 0.23 > 0
  let info = sdSpoonInfo(x, y);
  let sd = info.sd;
  if (sd > -60 && sd < 145) {
    let s = (sd + 60) / 205;
    let push = 65 * Math.pow(1 - s, 2.35);
    x += push * info.nx;
    y += push * info.ny;
  }

  return [x, y, sd];
}

// Helper for safe spline rendering
function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 2.2) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

// Draw sub-paths of a curve that lie within canvas margin and outside deep spoon interior
function drawVisibleSubpaths(curvePts, curvature = 0.5) {
  let sub = [];
  for (let i = 0; i < curvePts.length; i++) {
    let p = curvePts[i];
    let onCanvas = p[0] >= -65 && p[0] <= W + 65 && p[1] >= -65 && p[1] <= H + 65;
    let visible = onCanvas && p[2] > -22; // p[2] is original sd before push
    if (visible) {
      sub.push([p[0], p[1]]);
    } else {
      if (sub.length >= 2) safeSpline(sub, curvature);
      sub = [];
    }
  }
  if (sub.length >= 2) safeSpline(sub, curvature);
}

