function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Warm Kitre (Tragacanth Gum Bath) Base Wash
  brush.noStroke();
  brush.wash("#F2E9DC", 255);
  brush.rect(0, 0, W, H, "corner");
  brush.noWash();

  // 2. Render the Turkish Ebru Marbling Bath (Nonpareil Feathers, Swirls & Meniscus Flow)
  renderEbruBath();

  // 3. Render the Meniscus Halo & Capillary Shadow Around the Half-Sunk Spoon
  renderMeniscusHalo();

  // 4. Render the Hyperreal Antique Silver Teaspoon (Bowl Reflection + Tarnished Engraved Handle)
  renderAntiqueSilverSpoon();

  // 5. Render the Glistening Beads of Water at the Spoon's Tips
  renderWaterBeads();

  noLoop();
}

// ============================================================================
// 1. TURKISH EBRU MARBLING BATH (Taraklı Ebru + Bülbül Yuvası)
// ============================================================================
function renderEbruBath() {
  // Generate ribbon boundaries v_0 ... v_M spanning [-420, 1620]
  let vEdges = [-420];
  let bandMeta = [];
  let idx = 0;
  while (vEdges[vEdges.length - 1] < 1620) {
    let spec = EBRU_BANDS[idx % EBRU_BANDS.length];
    let w = spec.weight * random(0.88, 1.14);
    vEdges.push(vEdges[vEdges.length - 1] + w);
    bandMeta.push(spec);
    idx++;
  }

  const U_MIN = -420;
  const U_MAX = 1620;
  const U_STEP = 14;
  const N_U = Math.floor((U_MAX - U_MIN) / U_STEP) + 1;

  // Precompute all mapped boundary curves and mid-curves
  let edgeCurves = [];
  for (let b = 0; b < vEdges.length; b++) {
    let v = vEdges[b];
    let pts = [];
    for (let j = 0; j < N_U; j++) {
      let u = U_MIN + j * U_STEP;
      pts.push(mapEbruPoint(u, v));
    }
    edgeCurves.push(pts);
  }

  // PASS A: Opaque Wash + Wet Watercolour Polygon Chunks batched by color family
  const chunkLen = 12;
  const families = ["indigo", "carmine", "saffron", "moss", "kitre"];

  // First lay down crisp, saturated base washes for every ribbon chunk
  brush.noStroke();
  for (let b = 0; b < bandMeta.length; b++) {
    let spec = bandMeta[b];
    let c0 = edgeCurves[b];
    let c1 = edgeCurves[b + 1];

    brush.wash(spec.fill, 225);
    for (let j = 0; j < N_U - 1; j += chunkLen) {
      let jEnd = Math.min(N_U - 1, j + chunkLen);
      // Check if chunk is on canvas and not completely under the spoon
      let midIdx = Math.floor((j + jEnd) / 2);
      let mp = c0[midIdx];
      if (mp[0] < -110 || mp[0] > W + 110 || mp[1] < -110 || mp[1] > H + 110) continue;
      if (mp[2] < -28) continue;

      brush.beginShape(0);
      for (let k = j; k <= jEnd; k++) brush.vertex(c0[k][0], c0[k][1]);
      for (let k = jEnd; k >= j; k--) brush.vertex(c1[k][0], c1[k][1]);
      brush.endShape(true);
    }
  }
  brush.noWash();

  // Second, layer authentic p5.brush watercolor bleed batches over the combed feathers
  brush.noStroke();
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.55, 0.38);

  for (let f = 0; f < families.length; f++) {
    let fam = families[f];
    if (fam === "kitre") continue; // Keep kitre veins crisp and luminous

    for (let b = 0; b < bandMeta.length; b++) {
      let spec = bandMeta[b];
      if (spec.family !== fam) continue;
      // Selectively apply watercolor granulation to every 2nd band for organic wet depth
      if (b % 2 !== 0) continue;

      let c0 = edgeCurves[b];
      let c1 = edgeCurves[b + 1];
      brush.fill(spec.core, 95);

      for (let j = 0; j < N_U - 1; j += chunkLen * 2) {
        let jEnd = Math.min(N_U - 1, j + chunkLen * 2);
        let midIdx = Math.floor((j + jEnd) / 2);
        let mp = c0[midIdx];
        if (mp[0] < -90 || mp[0] > W + 90 || mp[1] < -90 || mp[1] > H + 90) continue;
        if (mp[2] < -25) continue;

        brush.beginShape(0);
        for (let k = j; k <= jEnd; k += 2) brush.vertex(c0[k][0], c0[k][1]);
        for (let k = jEnd; k >= j; k -= 2) brush.vertex(c1[k][0], c1[k][1]);
        brush.endShape(true);
      }
    }
  }
  brush.noFill();

  // PASS B: Silky Combed Pigment Core & Luminous Crest Striations inside each river
  for (let b = 0; b < bandMeta.length; b++) {
    let spec = bandMeta[b];
    let v0 = vEdges[b];
    let v1 = vEdges[b + 1];
    let vm = 0.5 * (v0 + v1);

    // Midline core spline
    let midPts = [];
    for (let j = 0; j < N_U; j++) {
      let u = U_MIN + j * U_STEP;
      midPts.push(mapEbruPoint(u, vm));
    }

    let wMult = spec.family === "kitre" ? 0.65 : 1.15;
    brush.set("ebru_silk", spec.core, wMult);
    drawVisibleSubpaths(midPts, 0.5);

    // Secondary luminous highlight filament inside wider rivers
    if (spec.family !== "kitre") {
      let vLight = v0 + 0.33 * (v1 - v0);
      let lightPts = [];
      for (let j = 0; j < N_U; j++) {
        let u = U_MIN + j * U_STEP;
        lightPts.push(mapEbruPoint(u, vLight));
      }
      brush.set("ebru_silk", spec.light, 0.62);
      drawVisibleSubpaths(lightPts, 0.5);
    }
  }

  // PASS C: Crisp Ox-Gall (Öd) Boundary Veins between every combed feather
  for (let b = 0; b < bandMeta.length; b++) {
    let spec = bandMeta[b];
    let c0 = edgeCurves[b];
    brush.set("ebru_vein", spec.rim, spec.family === "kitre" ? 0.55 : 0.72);
    drawVisibleSubpaths(c0, 0.5);
  }
}

// ============================================================================
// 2. MENISCUS HALO & CAPILLARY TROUGH AROUND THE SPOON
// ============================================================================
function renderMeniscusHalo() {
  // Generate closed offset rings around the spoon perimeter at exact signed distances
  function buildOffsetLoop(offsetDist, numSamples = 180) {
    let upper = [];
    let lower = [];
    for (let i = 0; i <= numSamples; i++) {
      let u = -390 + (780 * i) / numSamples;
      let w = spoonHalfWidth(u);
      // Estimate local normal in (u, v)
      let du = 2.0;
      let wNext = spoonHalfWidth(Math.min(390, u + du));
      let wPrev = spoonHalfWidth(Math.max(-390, u - du));
      let dwdu = (wNext - wPrev) / (2 * du);
      let nu = -dwdu;
      let nv = 1.0;
      let len = Math.hypot(nu, nv);
      nu /= len;
      nv /= len;

      let uUp = u + offsetDist * nu;
      let vUp = w + offsetDist * nv;
      upper.push(toCanvasXY(uUp, vUp));

      let uLo = u + offsetDist * nu;
      let vLo = -w - offsetDist * nv;
      lower.push(toCanvasXY(uLo, vLo));
    }
    return { upper, lower };
  }

  // 1. Subtle darkened capillary trough where water curves down/up against the half-sunk metal
  let troughSteps = [18, 13, 9, 5, 2.5];
  for (let s = 0; s < troughSteps.length; s++) {
    let d = troughSteps[s];
    let loops = buildOffsetLoop(d, 160);
    // Shadow side (lower-left / bottom-right in canvas) is deeper
    brush.set("silver_shader", "#08132B", 1.15);
    safeSpline(loops.upper, 0.5);
    brush.set("ebru_silk", "#0B1B3D", 0.9);
    safeSpline(loops.lower, 0.5);
  }

  // 2. Luminous Meniscus Halo Ring (Surface-tension optical refraction & specular rim)
  let haloOuter = buildOffsetLoop(10.5, 180);
  let haloMid = buildOffsetLoop(6.5, 180);
  let haloInner = buildOffsetLoop(3.2, 180);

  // Translucent cyan-ivory meniscus glow
  brush.set("ebru_silk", "#D6F0FF", 0.95);
  safeSpline(haloOuter.lower, 0.5);
  safeSpline(haloOuter.upper, 0.5);

  brush.set("ebru_vein", "#F2FAFF", 1.1);
  safeSpline(haloMid.lower, 0.5);
  safeSpline(haloMid.upper, 0.5);

  // Razor-sharp discontinuous specular glints along the wet meniscus contact line
  brush.set("burin_cut", "#FFFFFF", 1.25);
  for (let k = 0; k < haloInner.lower.length - 12; k += 16) {
    if (k % 32 === 0) {
      safeSpline(haloInner.lower.slice(k, k + 11), 0.5);
    }
    if ((k + 8) % 32 === 0) {
      safeSpline(haloInner.upper.slice(k, k + 10), 0.5);
    }
  }

  brush.set("burin_cut", "#FFFFFF", 0.95);
  safeSpline(haloMid.lower.slice(8, 85), 0.5); // Strong meniscus catchlight around the bowl flank
  safeSpline(haloMid.upper.slice(10, 75), 0.5);
}

// ============================================================================
// 3. HYPERREAL ANTIQUE SILVER TEASPOON
// ============================================================================
function renderAntiqueSilverSpoon() {
  // Build full closed silhouette polygon of the spoon
  let silPts = [];
  const N_SIL = 180;
  for (let i = 0; i <= N_SIL; i++) {
    let u = -390 + (780 * i) / N_SIL;
    silPts.push(toCanvasXY(u, spoonHalfWidth(u)));
  }
  for (let i = N_SIL; i >= 0; i--) {
    let u = -390 + (780 * i) / N_SIL;
    silPts.push(toCanvasXY(u, -spoonHalfWidth(u)));
  }

  // A. Solid Opaque Base Sterling Silver Wash (Prevents any background bleed-through)
  brush.noStroke();
  brush.wash("#8F9BA9", 255);
  brush.beginShape(0);
  for (let i = 0; i < silPts.length; i++) brush.vertex(silPts[i][0], silPts[i][1]);
  brush.endShape(true);

  // Second pass cold metallic base tone
  brush.wash("#B2BDCA", 190);
  brush.beginShape(0);
  for (let i = 0; i < silPts.length; i++) brush.vertex(silPts[i][0], silPts[i][1]);
  brush.endShape(true);
  brush.noWash();

  // B. Render the Concave Bowl: Compressed, Curved Anamorphic Reflection of the Ebru Bath
  renderSpoonBowlReflection();

  // C. Render the Neck, Stem & Ornate Handle with Tarnish & Burin Engravings
  renderSpoonHandleAndEngravings();

  // D. Outer Perimeter Bevel & Cold Precision Rim of the Entire Spoon
  renderSpoonRimBevel();
}

// ============================================================================
// 3B. SPOON BOWL: ANAMORPHIC CURVED EBRU REFLECTION & METALLIC OPTICS
// ============================================================================
function renderSpoonBowlReflection() {
  const U_BOWL_START = -384;
  const U_BOWL_END = -68;
  const U_CENTER = -226;
  const U_HALF = 158;

  // 1. Deep Concave Metallic Base Shading inside the Bowl
  brush.noStroke();
  let bowlSteps = [0.94, 0.82, 0.68, 0.52, 0.35];
  let bowlShades = ["#28303D", "#465263", "#738194", "#9AA7B8", "#BAC6D4"];
  for (let s = 0; s < bowlSteps.length; s++) {
    let frac = bowlSteps[s];
    brush.wash(bowlShades[s], 180);
    brush.beginShape(0);
    for (let i = 0; i <= 60; i++) {
      let u = U_BOWL_START + ((U_BOWL_END - U_BOWL_START) * i) / 60;
      let w = spoonHalfWidth(u) * frac;
      let p = toCanvasXY(u, w);
      brush.vertex(p[0], p[1]);
    }
    for (let i = 60; i >= 0; i--) {
      let u = U_BOWL_START + ((U_BOWL_END - U_BOWL_START) * i) / 60;
      let w = -spoonHalfWidth(u) * frac;
      let p = toCanvasXY(u, w);
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 2. Anamorphic Curved & Compressed Reflection of the Ebru Pattern inside the Concave Bowl
  // A concave elliptical mirror compresses the surrounding ebru bath near the steep walls (|rn| -> 1)
  // and bends the nonpareil feathers into curved elliptical S-arcs across the bowl belly.
  const reflColors = [
    { col: "#142E6E", hi: "#284EA6", w: 0.95 }, // Reflected Indigo
    { col: "#A81739", hi: "#CF2B52", w: 0.9  }, // Reflected Carmine
    { col: "#D4880C", hi: "#F0A824", w: 0.9  }, // Reflected Saffron
    { col: "#2B6632", hi: "#468C4B", w: 0.9  }, // Reflected Moss Green
    { col: "#D9D6CE", hi: "#F0EDE6", w: 0.55 }, // Reflected Kitre Vein
    { col: "#1A3B85", hi: "#3460BA", w: 0.85 }, // Reflected Cobalt Indigo
    { col: "#B81B40", hi: "#E0365E", w: 0.85 }, // Reflected Ruby Carmine
    { col: "#E09612", hi: "#F7BA36", w: 0.85 }  // Reflected Gold Saffron
  ];

  // 2a. Concentric Compressed Rim Reflections (Steep wall curvature of the spoon bowl)
  const rimFracs = [0.91, 0.87, 0.83, 0.78, 0.73, 0.67, 0.61, 0.54];
  for (let r = 0; r < rimFracs.length; r++) {
    let baseFrac = rimFracs[r];
    let rc = reflColors[r % reflColors.length];

    let upperArc = [];
    let lowerArc = [];
    for (let i = 0; i <= 75; i++) {
      let t = i / 75;
      let u = U_BOWL_START + 6 + (U_BOWL_END - U_BOWL_START - 12) * t;
      let wMax = spoonHalfWidth(u) - 5.5;
      if (wMax <= 2) continue;

      // Add nonpareil feather wave modulation compressed along the elliptical wall
      let featherMod =
        0.045 *
        (1 - baseFrac * 0.5) *
        featherWave(t * Math.PI * 10 + r * 0.7);
      let fUp = Math.min(0.95, Math.max(0.1, baseFrac + featherMod));
      let fLo = Math.min(0.95, Math.max(0.1, baseFrac - featherMod));

      upperArc.push(toCanvasXY(u, wMax * fUp));
      lowerArc.push(toCanvasXY(u, -wMax * fLo));
    }

    brush.set("ebru_silk", rc.col, rc.w * 0.72);
    safeSpline(upperArc, 0.5);
    safeSpline(lowerArc, 0.5);

    brush.set("ebru_vein", rc.hi, 0.55);
    safeSpline(upperArc, 0.5);
  }

  // 2b. Interior Belly Anamorphic Nonpareil Feathers & Reflected Swirl
  const N_INT_BANDS = 26;
  for (let b = 0; b < N_INT_BANDS; b++) {
    let sNorm = -0.82 + (1.64 * b) / (N_INT_BANDS - 1);
    let rc = reflColors[b % reflColors.length];
    let pts = [];

    for (let i = 0; i <= 70; i++) {
      let t = i / 70; // 0 at bowl tip, 1 at bowl neck
      let u = U_BOWL_START + 10 + (U_BOWL_END - U_BOWL_START - 18) * t;
      let un = (u - U_CENTER) / U_HALF; // in [-1, 1]
      let wMax = spoonHalfWidth(u) - 6.5;
      if (wMax <= 2) continue;

      // Anamorphic S-curve + nonpareil comb feathering inside the concave mirror
      let combWave = 0.16 * (1 - un * un * 0.65) * featherWave(un * Math.PI * 4.5 + sNorm * 2.2);
      let swirlTwist = 0.14 * Math.sin(un * Math.PI * 1.5 + sNorm * 3.0) * Math.exp(-un * un * 1.8);
      let rn = sNorm + combWave + swirlTwist;

      // Radial optical compression near the rim of the concave bowl:
      let rnCompressed = Math.sign(rn) * Math.pow(Math.min(1, Math.abs(rn)), 0.72);
      let v = rnCompressed * wMax * 0.88;

      pts.push(toCanvasXY(u, v));
    }

    brush.set("ebru_silk", rc.col, rc.w * 0.68);
    safeSpline(pts, 0.5);
    if (b % 2 === 0) {
      brush.set("ebru_vein", "#101B30", 0.45);
      safeSpline(pts, 0.5);
    }
  }

  // 3. Cold Metallic Fresnel Glaze, Deep Chrome Shadow & Blinding Studio Speculars
  // 3a. Deep chrome-slate Fresnel shadow crescent on the lower-right inner bowl (+v side)
  for (let k = 0; k < 7; k++) {
    let f = 0.25 + k * 0.09;
    let shPts = [];
    for (let i = 5; i <= 58; i++) {
      let t = i / 65;
      let u = U_BOWL_START + (U_BOWL_END - U_BOWL_START) * t;
      let wMax = spoonHalfWidth(u) - 6;
      shPts.push(toCanvasXY(u, wMax * f));
    }
    brush.set("silver_shader", k < 3 ? "#1E2633" : "#2D384A", 1.15);
    safeSpline(shPts, 0.5);
  }

  // 3b. Dazzling cold silver studio highlight sweeping along the upper-left wall (-v side)
  let specFracs = [-0.66, -0.60, -0.54, -0.48, -0.42];
  let specCols = ["#CEDCEB", "#E6F1FA", "#FFFFFF", "#FFFFFF", "#DCE8F5"];
  let specWeights = [1.1, 1.35, 1.6, 1.35, 0.95];
  for (let s = 0; s < specFracs.length; s++) {
    let sf = specFracs[s];
    let spPts = [];
    for (let i = 6; i <= 54; i++) {
      let t = i / 62;
      let u = U_BOWL_START + (U_BOWL_END - U_BOWL_START) * t;
      let wMax = spoonHalfWidth(u) - 6;
      spPts.push(toCanvasXY(u, wMax * sf));
    }
    brush.set("silver_shader", specCols[s], specWeights[s]);
    safeSpline(spPts, 0.5);
  }

  // Razor-sharp core specular gleam inside the bowl
  for (let s = 0; s < 3; s++) {
    let sf = -0.57 + s * 0.03;
    let hiPts = [];
    for (let i = 8; i <= 48; i++) {
      let t = i / 60;
      let u = U_BOWL_START + (U_BOWL_END - U_BOWL_START) * t;
      let wMax = spoonHalfWidth(u) - 6;
      hiPts.push(toCanvasXY(u, wMax * sf));
    }
    brush.set("burin_cut", "#FFFFFF", 1.3);
    safeSpline(hiPts, 0.5);
  }

  // 3c. Secondary crisp caustic rim reflection on the opposite (+v) inner wall
  for (let s = 0; s < 2; s++) {
    let sf = 0.78 + s * 0.04;
    let secPts = [];
    for (let i = 10; i <= 52; i++) {
      let t = i / 62;
      let u = U_BOWL_START + (U_BOWL_END - U_BOWL_START) * t;
      let wMax = spoonHalfWidth(u) - 6;
      secPts.push(toCanvasXY(u, wMax * sf));
    }
    brush.set("burin_cut", "#E8F2FC", 0.95);
    safeSpline(secPts, 0.5);
  }

  // 3d. Fine Antique Silver Micro-Scratches (Patina of decades of polishing)
  for (let m = 0; m < 28; m++) {
    let tStart = random(0.08, 0.72);
    let tEnd = Math.min(0.92, tStart + random(0.12, 0.28));
    let rFrac = random(-0.82, 0.82);
    let scPts = [];
    for (let j = 0; j <= 8; j++) {
      let t = tStart + ((tEnd - tStart) * j) / 8;
      let u = U_BOWL_START + (U_BOWL_END - U_BOWL_START) * t;
      let wMax = spoonHalfWidth(u) - 7;
      scPts.push(toCanvasXY(u, wMax * (rFrac + 0.02 * Math.sin(j))));
    }
    let scCol = rFrac < -0.25 ? "#FFFFFF" : "#8D9AAB";
    brush.set("2H", scCol, 0.22);
    safeSpline(scPts, 0.4);
  }
}

// ============================================================================
// 3C. NECK, STEM & ORNATE HANDLE WITH OXIDIZED TARNISH IN ENGRAVINGS
// ============================================================================
function renderSpoonHandleAndEngravings() {
  const U_START = -72;
  const U_END = 388;

  // 1. 3D Cylindrical & Chamfered Facet Shading along the Neck & Handle
  // Sunlit side (-v, upper-right/top-left) is bright sterling; shadow side (+v) is cool dark slate
  const facetBands = [
    { f0: -0.95, f1: -0.55, col: "#E2EAF2" },
    { f0: -0.55, f1: -0.15, col: "#F2F7FC" },
    { f0: -0.15, f1: 0.20,  col: "#B8C4D4" },
    { f0: 0.20,  f1: 0.62,  col: "#596578" },
    { f0: 0.62,  f1: 0.95,  col: "#2D3542" }
  ];

  for (let b = 0; b < facetBands.length; b++) {
    let fb = facetBands[b];
    for (let s = 0; s <= 3; s++) {
      let frac = fb.f0 + ((fb.f1 - fb.f0) * s) / 3;
      let pts = [];
      for (let i = 0; i <= 75; i++) {
        let u = U_START + ((U_END - U_START) * i) / 75;
        let w = spoonHalfWidth(u);
        pts.push(toCanvasXY(u, w * frac));
      }
      brush.set("silver_shader", fb.col, 1.05);
      safeSpline(pts, 0.5);
    }
  }

  // Central architectural ridge (rib) running along u in [-65, 235]
  let ridgeLight = [];
  let ridgeShadow = [];
  for (let i = 0; i <= 50; i++) {
    let u = -65 + (300 * i) / 50;
    ridgeLight.push(toCanvasXY(u, -1.2));
    ridgeShadow.push(toCanvasXY(u, 1.2));
  }
  brush.set("burin_cut", "#FFFFFF", 1.15);
  safeSpline(ridgeLight, 0.5);
  brush.set("burin_cut", "#2C3442", 0.95);
  safeSpline(ridgeShadow, 0.5);

  // 2. Oxidized Sulfide Tarnish Base inside the Recessed Engraving Zones
  // Antique silver collects dark charcoal-sepia-slate tarnish (#1A1921, #2E2B36) in carved recesses
  brush.noStroke();
  brush.wash("#282630", 145);
  brush.beginShape(0);
  for (let i = 0; i <= 45; i++) {
    let u = 175 + (200 * i) / 45;
    let w = Math.max(0, spoonHalfWidth(u) - 6.5);
    let p = toCanvasXY(u, w);
    brush.vertex(p[0], p[1]);
  }
  for (let i = 45; i >= 0; i--) {
    let u = 175 + (200 * i) / 45;
    let w = -Math.max(0, spoonHalfWidth(u) - 6.5);
    let p = toCanvasXY(u, w);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Polished bright silver plateaus inside the handle (leaving tarnish around the engraved scrolls)
  for (let s = -0.55; s <= 0.45; s += 0.2) {
    let pPts = [];
    for (let i = 0; i <= 40; i++) {
      let u = 185 + (185 * i) / 40;
      let w = Math.max(0, spoonHalfWidth(u) - 9);
      pPts.push(toCanvasXY(u, w * s));
    }
    brush.set("silver_shader", s < 0 ? "#E6EEF7" : "#9BA8B8", 0.9);
    safeSpline(pPts, 0.5);
  }

  // Helper to incise an engraved curve with dark sulfide tarnish + bright sunlit burin lip
  function drawEngravedGroove(localPts, tarnishWeight = 0.95, highlightWeight = 0.75) {
    let cTarnish = [];
    let cLight = [];
    for (let i = 0; i < localPts.length; i++) {
      let u = localPts[i][0];
      let v = localPts[i][1];
      cTarnish.push(toCanvasXY(u, v));
      // Sunlit burin lip offset slightly toward (-u, -v)
      cLight.push(toCanvasXY(u - 0.8, v - 1.1));
    }
    // 1. Soft dark oxidized tarnish halo in the groove
    brush.set("tarnish_crevice", "#16151D", tarnishWeight);
    safeSpline(cTarnish, 0.5);
    // 2. Deep black-sepia core of the burin cut
    brush.set("burin_cut", "#0D0C12", tarnishWeight * 0.85);
    safeSpline(cTarnish, 0.5);
    // 3. Razor-sharp gleaming silver lip catching the light
    brush.set("burin_cut", "#F7FBFF", highlightWeight);
    safeSpline(cLight, 0.5);
  }

  // 3a. Recessed Perimeter Thread & Bead Border along the Handle (u in [-20, 382])
  let borderUp = [];
  let borderLo = [];
  for (let i = 0; i <= 80; i++) {
    let u = -20 + (402 * i) / 80;
    let w = Math.max(2.5, spoonHalfWidth(u) - 4.2);
    borderUp.push([u, w]);
    borderLo.push([u, -w]);
  }
  drawEngravedGroove(borderUp, 0.95, 0.8);
  drawEngravedGroove(borderLo, 0.95, 0.8);

  // Inner parallel thread line on the flared terminal (u in [180, 376])
  let innerUp = [];
  let innerLo = [];
  for (let i = 0; i <= 50; i++) {
    let u = 180 + (196 * i) / 50;
    let w = Math.max(1.5, spoonHalfWidth(u) - 7.8);
    innerUp.push([u, w]);
    innerLo.push([u, -w]);
  }
  drawEngravedGroove(innerUp, 0.75, 0.65);
  drawEngravedGroove(innerLo, 0.75, 0.65);

  // 3b. Intricate Acanthus Leaf & C-Scroll Engravings along the Stem & Terminal
  // Stem scrolls: u in [25, 185]
  for (let k = 0; k < 5; k++) {
    let uBase = 32 + k * 31;
    let scrollUp = [];
    let scrollLo = [];
    for (let j = 0; j <= 18; j++) {
      let t = j / 18;
      let u = uBase + t * 26;
      let wMax = Math.max(2, spoonHalfWidth(u) - 6.2);
      // Spiral C-scroll curve
      let r = wMax * (0.25 + 0.62 * Math.sin(Math.PI * t));
      let hook = 2.2 * Math.cos(2 * Math.PI * t) * t;
      scrollUp.push([u + hook, r]);
      scrollLo.push([u + hook, -r]);
    }
    drawEngravedGroove(scrollUp, 0.85, 0.65);
    drawEngravedGroove(scrollLo, 0.85, 0.65);
  }

  // 3c. Ornate Terminal Acanthus Scrolls, Foliate Volutes & Central Cartouche (u in [195, 372])
  // Symmetrical baroque volutes flanking the terminal
  const voluteSpecs = [
    { u0: 198, u1: 248, r0: 0.25, r1: 0.76, turns: 1.3 },
    { u0: 242, u1: 298, r0: 0.74, r1: 0.32, turns: -1.4 },
    { u0: 288, u1: 342, r0: 0.35, r1: 0.78, turns: 1.5 },
    { u0: 332, u1: 368, r0: 0.72, r1: 0.22, turns: -1.2 }
  ];

  for (let vIdx = 0; vIdx < voluteSpecs.length; vIdx++) {
    let vs = voluteSpecs[vIdx];
    let volUp = [];
    let volLo = [];
    for (let j = 0; j <= 24; j++) {
      let t = j / 24;
      let u = vs.u0 + (vs.u1 - vs.u0) * t;
      let wMax = Math.max(3, spoonHalfWidth(u) - 9.0);
      let env = vs.r0 + (vs.r1 - vs.r0) * t + 0.22 * Math.sin(Math.PI * t);
      let spiral = 0.16 * Math.sin(t * Math.PI * 2 * vs.turns) * (1 - 0.4 * t);
      let vCoord = wMax * Math.min(0.92, Math.max(0.12, env + spiral));
      let uSpiral = u + 4.5 * Math.cos(t * Math.PI * 2 * vs.turns) * Math.sin(Math.PI * t);
      volUp.push([uSpiral, vCoord]);
      volLo.push([uSpiral, -vCoord]);
    }
    drawEngravedGroove(volUp, 0.95, 0.75);
    drawEngravedGroove(volLo, 0.95, 0.75);

    // Tarnished cross-hatching inside the scroll recesses
    for (let h = 3; h <= 20; h += 3) {
      let pA = volUp[h];
      let cA = toCanvasXY(pA[0], pA[1]);
      let cB = toCanvasXY(pA[0] + 3.5, pA[1] * 0.72);
      brush.set("tarnish_crevice", "#1C1A24", 0.65);
      brush.line(cA[0], cA[1], cB[0], cB[1]);

      let pALo = volLo[h];
      let cALo = toCanvasXY(pALo[0], pALo[1]);
      let cBLo = toCanvasXY(pALo[0] + 3.5, pALo[1] * 0.72);
      brush.line(cALo[0], cALo[1], cBLo[0], cBLo[1]);
    }
  }

  // 3d. Central Oval Cartouche Shield (u in [268, 332]) with Engraved Monogram Flourish
  let cartUp = [];
  let cartLo = [];
  for (let j = 0; j <= 28; j++) {
    let t = j / 28;
    let ang = t * Math.PI;
    let u = 300 - 30 * Math.cos(ang);
    let v = 13.5 * Math.sin(ang);
    cartUp.push([u, v]);
    cartLo.push([u, -v]);
  }
  drawEngravedGroove(cartUp, 0.95, 0.8);
  drawEngravedGroove(cartLo, 0.95, 0.8);

  // Engraved calligraphic monogram / fleuron inside the cartouche
  let mono1 = [];
  let mono2 = [];
  for (let j = 0; j <= 20; j++) {
    let t = (j / 20) * 2 - 1; // [-1, 1]
    mono1.push([300 + t * 18, 7.5 * Math.sin(t * Math.PI) + 2.5 * Math.cos(t * 2.5)]);
    mono2.push([300 + t * 16, -6.5 * Math.sin(t * Math.PI) + 2.0 * t]);
  }
  drawEngravedGroove(mono1, 0.75, 0.65);
  drawEngravedGroove(mono2, 0.75, 0.65);

  // 3e. Scalloped Shell Crown at the Terminal Tip (u in [346, 380])
  for (let ray = -3; ray <= 3; ray++) {
    let rPts = [];
    for (let j = 0; j <= 10; j++) {
      let t = j / 10;
      let u = 345 + t * 31;
      let v = ray * (2.2 + t * 4.2);
      rPts.push([u, v]);
    }
    drawEngravedGroove(rPts, 0.8, 0.65);
  }

  // 4. Final High-Contrast Specular Polish Highlights on Raised Silver Surfaces of Handle
  let handleSpec = [];
  for (let i = 0; i <= 55; i++) {
    let u = -50 + (420 * i) / 55;
    let w = spoonHalfWidth(u);
    handleSpec.push(toCanvasXY(u, -w * 0.42));
  }
  brush.set("burin_cut", "#FFFFFF", 1.2);
  safeSpline(handleSpec, 0.5);
}

// ============================================================================
// 3D. EXACT METALLIC RIM BEVEL AROUND THE SPOON
// ============================================================================
function renderSpoonRimBevel() {
  const N = 160;
  let outerUp = [];
  let outerLo = [];
  let innerUp = [];
  let innerLo = [];
  let midUp = [];
  let midLo = [];

  for (let i = 0; i <= N; i++) {
    let u = -390 + (780 * i) / N;
    let w = spoonHalfWidth(u);
    let rimW = u < -65 ? 5.2 : 2.8;
    let wIn = Math.max(0, w - rimW);
    let wMid = Math.max(0, w - rimW * 0.5);

    outerUp.push(toCanvasXY(u, w));
    outerLo.push(toCanvasXY(u, -w));
    innerUp.push(toCanvasXY(u, wIn));
    innerLo.push(toCanvasXY(u, -wIn));
    midUp.push(toCanvasXY(u, wMid));
    midLo.push(toCanvasXY(u, -wMid));
  }

  // Dark crisp outer boundary and inner lip crease
  brush.set("burin_cut", "#1A222E", 1.15);
  safeSpline(outerUp, 0.5);
  safeSpline(outerLo, 0.5);

  brush.set("burin_cut", "#232B38", 0.95);
  safeSpline(innerUp.slice(0, 72), 0.5); // Bowl inner lip crease
  safeSpline(innerLo.slice(0, 72), 0.5);

  // Rounded sterling silver bevel ridge along the lip
  brush.set("silver_shader", "#DCE6F2", 0.85);
  safeSpline(midLo, 0.5);
  brush.set("silver_shader", "#7D8B9E", 0.85);
  safeSpline(midUp, 0.5);

  // Blinding white specular catchlight on the sunlit (-v) lip bevel and pointed tip
  brush.set("burin_cut", "#FFFFFF", 1.35);
  safeSpline(midLo.slice(0, 145), 0.5);
  safeSpline(outerUp.slice(5, 65), 0.5); // Secondary rim reflection on opposite bowl edge
}

// ============================================================================
// 4. HYPERREAL BEAD OF WATER AT THE SPOON'S TIP (AND COMPANION DROPLETS)
// ============================================================================
function renderWaterBeads() {
  // Primary jewel-like bead of water perched right at the pointed tip of the bowl
  let tipXY = toCanvasXY(-364, -2);
  drawHyperrealWaterDrop(tipXY[0], tipXY[1], 21, 16, -28);

  // Companion bead of water near the tip of the ornate handle
  let handleTipXY = toCanvasXY(362, -5);
  drawHyperrealWaterDrop(handleTipXY[0], handleTipXY[1], 11.5, 9.5, -20);

  // Three tiny micro-dewdrops clinging to the silver bowl rim
  let d1 = toCanvasXY(-318, -spoonHalfWidth(-318) + 3.5);
  drawHyperrealWaterDrop(d1[0], d1[1], 5.5, 4.5, -30);

  let d2 = toCanvasXY(-265, spoonHalfWidth(-265) - 3.5);
  drawHyperrealWaterDrop(d2[0], d2[1], 4.8, 4.0, -15);

  let d3 = toCanvasXY(-145, -spoonHalfWidth(-145) + 3.0);
  drawHyperrealWaterDrop(d3[0], d3[1], 4.2, 3.6, -25);
}

function drawHyperrealWaterDrop(cx, cy, rx, ry, rotDeg) {
  let rot = (rotDeg * Math.PI) / 180;
  let cr = Math.cos(rot);
  let sr = Math.sin(rot);

  function dropPt(localX, localY) {
    return [
      cx + localX * cr - localY * sr,
      cy + localX * sr + localY * cr
    ];
  }

  // 1. Cast Shadow on the cold silver beneath (shifted toward lower-right +x, +y)
  brush.noStroke();
  brush.wash("#0E1624", 185);
  brush.beginShape(0);
  for (let i = 0; i < 32; i++) {
    let a = (i / 32) * Math.PI * 2;
    let p = dropPt((rx * 1.05) * Math.cos(a) + rx * 0.22, (ry * 1.05) * Math.sin(a) + ry * 0.28);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // 2. Internal Focused Caustic Glow inside the shadow side of the droplet
  brush.wash("#C8EEFF", 170);
  brush.beginShape(0);
  for (let i = 0; i < 28; i++) {
    let a = (i / 28) * Math.PI * 2;
    let p = dropPt(rx * 0.55 * Math.cos(a) + rx * 0.28, ry * 0.52 * Math.sin(a) + ry * 0.26);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // 3. Droplet Dome Base (Dark refractive lens perimeter)
  brush.wash("#162844", 215);
  brush.beginShape(0);
  for (let i = 0; i < 36; i++) {
    let a = (i / 36) * Math.PI * 2;
    let p = dropPt(rx * Math.cos(a), ry * Math.sin(a));
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // 4. Inverted Micro-Refraction of the Vivid Ebru Bath inside the Convex Water Lens
  if (rx >= 8) {
    const lensBands = [
      { f: -0.45, col: "#D41742" }, // Carmine refraction
      { f: -0.15, col: "#F7A80B" }, // Saffron gold refraction
      { f: 0.15,  col: "#1B4298" }, // Indigo refraction
      { f: 0.42,  col: "#38803B" }, // Moss green refraction
      { f: 0.65,  col: "#DDF2FF" }  // Caustic cyan rim
    ];
    for (let b = 0; b < lensBands.length; b++) {
      let lb = lensBands[b];
      let arcPts = [];
      for (let j = -10; j <= 10; j++) {
        let t = j / 10;
        let lx = t * rx * 0.78 * Math.sqrt(Math.max(0.1, 1 - lb.f * lb.f * 0.7));
        let ly = lb.f * ry * 0.78 + 0.18 * ry * (1 - t * t);
        arcPts.push(dropPt(lx, ly));
      }
      brush.set("ebru_silk", lb.col, (rx / 21) * 0.75);
      safeSpline(arcPts, 0.5);
    }
  }
  brush.noWash();

  // 5. Crisp Surface-Tension Perimeter Ring & Lower-Right Reflected Rim Light
  let perimPts = [];
  let rimGlowPts = [];
  for (let i = 0; i <= 36; i++) {
    let a = (i / 36) * Math.PI * 2;
    perimPts.push(dropPt(rx * Math.cos(a), ry * Math.sin(a)));
    if (a > -0.3 && a < Math.PI * 0.85) {
      rimGlowPts.push(dropPt(rx * 0.88 * Math.cos(a), ry * 0.88 * Math.sin(a)));
    }
  }
  brush.set("burin_cut", "#0B1526", 0.9);
  safeSpline(perimPts, 0.5);

  brush.set("burin_cut", "#E0F6FF", 0.95);
  safeSpline(rimGlowPts, 0.5);

  // 6. Blinding Primary Specular Catchlight on the Upper-Left Dome + Secondary Dot
  brush.noStroke();
  brush.wash("#FFFFFF", 255);
  brush.beginShape(0);
  for (let i = 0; i < 20; i++) {
    let a = (i / 20) * Math.PI * 2;
    let p = dropPt(-rx * 0.36 + rx * 0.26 * Math.cos(a), -ry * 0.36 + ry * 0.16 * Math.sin(a));
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Crisp specular arc & secondary pinpoint glint
  let specArc = [];
  for (let i = 0; i <= 12; i++) {
    let a = Math.PI * 0.95 + (i / 12) * Math.PI * 0.65;
    specArc.push(dropPt(rx * 0.62 * Math.cos(a), ry * 0.62 * Math.sin(a)));
  }
  brush.set("burin_cut", "#FFFFFF", 1.35);
  safeSpline(specArc, 0.5);

  let dot1 = dropPt(-rx * 0.12, -ry * 0.52);
  let dot2 = dropPt(-rx * 0.05, -ry * 0.48);
  brush.line(dot1[0], dot1[1], dot2[0], dot2[1]);
}

