// =============================================================================
// GEOMETRY & SHADING HELPERS
// =============================================================================

function clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function lerpVal(a, b, t) {
  return a + (b - a) * t;
}

function norm3(x, y, z) {
  let m = Math.sqrt(x * x + y * y + z * z) || 1;
  return { x: x / m, y: y / m, z: z / m };
}

function dotLight(nx, ny, nz) {
  return clamp01(nx * LIGHT.x + ny * LIGHT.y + nz * LIGHT.z);
}

function dotRim(nx, ny, nz) {
  return clamp01(nx * RIM_LIGHT.x + ny * RIM_LIGHT.y + nz * RIM_LIGHT.z);
}

// Safe spline wrapper that avoids duplicate points or <2 point crashes
function safeSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 0.25) {
      clean.push(pts[i]);
    }
  }
  if (clean.length < 2) return;
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else {
    brush.spline(clean, curv);
  }
}

// Safe watercolor filled shape using beginShape/vertex/endShape
function fillShapePoly(pts, col, opacity, bleed = 0.12, tex = 0.55, border = 0.35, curv = 0.15) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// Fast solid wash polygon
function washShapePoly(pts, col, opacity, curv = 0.1) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

// Maps a 0..1 illumination value to our warm bronze palette
function bronzeToneColor(illum, verdBias = 0) {
  if (verdBias > 0.45 && illum < 0.35) {
    return verdBias > 0.7 ? PAL.verdBright : PAL.verdMid;
  }
  if (illum < 0.16) return PAL.soot;
  if (illum < 0.28) return PAL.oxideDeep;
  if (illum < 0.40) return PAL.bronzeShadow;
  if (illum < 0.52) return PAL.bronzeDark;
  if (illum < 0.64) return PAL.copperDeep;
  if (illum < 0.75) return PAL.copperMid;
  if (illum < 0.84) return PAL.copperWarm;
  if (illum < 0.91) return PAL.brassWarm;
  if (illum < 0.96) return PAL.goldRubbed;
  return PAL.goldGleam;
}

// Checks whether a background point (x,y) is deep inside the opaque core of the figure
function isDeepInsideFigure(x, y) {
  // Head & neck core
  let hx = (x - 600) / 130;
  let hy = (y - 305) / 150;
  if (hx * hx + hy * hy < 0.82) return true;

  // Coral collar core
  let cx = (x - 600) / 185;
  let cy = (y - 515) / 85;
  if (cx * cx + cy * cy < 0.85) return true;

  // Torso core
  if (x > 365 && x < 835 && y > 540 && y < 1095) return true;

  return false;
}

