// 2. STAMPED QUATREFOIL RIVER-LEAF BACKGROUND (EBE-AME)
// =============================================================================

function drawQuatrefoilBackground() {
  const leftX = 142;
  const rightX = 1058;
  const topY = 92;
  const botY = 1108;
  const cols = 7;
  const rows = 8;
  const cellW = (rightX - leftX) / cols;
  const cellH = (botY - topY) / rows;

  // Recessed grid divider grooves
  for (let c = 0; c <= cols; c++) {
    let gx = leftX + c * cellW;
    brush.set("rotring", PAL.soot, 0.9);
    brush.line(gx, topY, gx, botY);
    brush.set("chisel", PAL.copperDeep, 0.55);
    brush.line(gx + 2, topY, gx + 2, botY);
  }
  for (let r = 0; r <= rows; r++) {
    let gy = topY + r * cellH;
    brush.set("rotring", PAL.soot, 0.9);
    brush.line(leftX, gy, rightX, gy);
    brush.set("chisel", PAL.copperDeep, 0.55);
    brush.line(leftX, gy + 2, rightX, gy + 2);
  }

  // Draw each stamped Quatrefoil River-Leaf motif (Ebe-Ame)
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let cx = leftX + (c + 0.5) * cellW;
      let cy = topY + (r + 0.5) * cellH;

      // Skip cells completely buried beneath the solid core of the figure
      if (isDeepInsideFigure(cx, cy)) continue;

      drawSingleQuatrefoil(cx, cy, Math.min(cellW, cellH) * 0.44, r, c);
    }
  }
}

function drawSingleQuatrefoil(cx, cy, rad, rowIdx, colIdx) {
  // Subtle verdigris pocket in the recessed corners of the cell
  let hasVerd = ((rowIdx * 3 + colIdx * 5) % 3 === 0);
  if (hasVerd) {
    brush.set("punch", PAL.verdMid, 1.15);
    for (let a = 0; a < 360; a += 90) {
      let px = cx + cos(a) * rad * 0.72;
      let py = cy + sin(a) * rad * 0.72;
      brush.circle(px, py, 6, 0.2);
    }
  }

  // Ring-punch stippling in the 4 cardinal interstices (classic Benin ground chasing)
  const cardinalAngles = [0, 90, 180, 270];
  for (let ang of cardinalAngles) {
    let d1 = rad * 0.56;
    let d2 = rad * 0.80;
    for (let d = d1; d <= d2; d += 11) {
      for (let spread = -14; spread <= 14; spread += 14) {
        let px = cx + cos(ang + spread) * d;
        let py = cy + sin(ang + spread) * d;
        brush.set("rotring", PAL.soot, 0.65);
        brush.circle(px, py, 2.4, 0.1);
        brush.set("chisel", hasVerd ? PAL.verdBright : PAL.copperMid, 0.45);
        brush.arc(px, py, 2.4, 195, 345);
      }
    }
  }

  // 4 Diagonal River-Leaf Petals (45, 135, 225, 315 degrees)
  const leafAngles = [45, 135, 225, 315];
  for (let ang of leafAngles) {
    let tipR = rad * 0.96;
    let baseR = rad * 0.16;
    let midR = rad * 0.56;
    let halfW = rad * 0.25;

    let perp = ang + 90;
    let bx = cx + cos(ang) * baseR;
    let by = cy + sin(ang) * baseR;
    let tx = cx + cos(ang) * tipR;
    let ty = cy + sin(ang) * tipR;

    let l1x = cx + cos(ang) * (midR * 0.75) + cos(perp) * (halfW * 0.92);
    let l1y = cy + sin(ang) * (midR * 0.75) + sin(perp) * (halfW * 0.92);
    let l2x = cx + cos(ang) * (midR * 1.22) + cos(perp) * (halfW * 0.78);
    let l2y = cy + sin(ang) * (midR * 1.22) + sin(perp) * (halfW * 0.78);

    let r1x = cx + cos(ang) * (midR * 0.75) - cos(perp) * (halfW * 0.92);
    let r1y = cy + sin(ang) * (midR * 0.75) - sin(perp) * (halfW * 0.92);
    let r2x = cx + cos(ang) * (midR * 1.22) - cos(perp) * (halfW * 0.78);
    let r2y = cy + sin(ang) * (midR * 1.22) - sin(perp) * (halfW * 0.78);

    // Undercut shadow of the leaf petal
    brush.set("rotring", PAL.soot, 1.15);
    safeSpline([[bx + 2, by + 2], [r1x + 2, r1y + 2], [r2x + 2, r2y + 2], [tx + 2, ty + 2]], 0.45);
    safeSpline([[bx + 2, by + 2], [l1x + 2, l1y + 2], [l2x + 2, l2y + 2], [tx + 2, ty + 2]], 0.45);

    // Verdigris trace in the deep leaf margin
    if (hasVerd) {
      brush.set("cpencil", PAL.verdMid, 0.75);
      safeSpline([[bx + 3, by + 3], [r1x + 3, r1y + 3], [tx + 3, ty + 3]], 0.4);
    }

    // Raised bronze leaf outline
    let isUpperLeft = (ang === 225 || ang === 315 || ang === 135);
    brush.set("chisel", isUpperLeft ? PAL.copperLit : PAL.copperMid, 0.9);
    safeSpline([[bx, by], [l1x, l1y], [l2x, l2y], [tx, ty]], 0.45);
    brush.set("chisel", PAL.copperDeep, 0.85);
    safeSpline([[bx, by], [r1x, r1y], [r2x, r2y], [tx, ty]], 0.45);

    // Burnished brass rim on upper-left facing edges of the stamped leaf
    brush.set("chisel", PAL.brassWarm, 0.65);
    if (ang === 225 || ang === 135) {
      safeSpline([[bx, by], [l1x, l1y], [l2x, l2y], [tx, ty]], 0.45);
    } else {
      safeSpline([[bx, by], [r1x, r1y], [r2x, r2y], [tx, ty]], 0.45);
    }

    // Central incised midrib vein & herringbone hatch lines inside each leaf
    brush.set("rotring", PAL.oxideDark, 0.7);
    brush.line(bx, by, tx, ty);
    brush.set("chisel", PAL.brassWarm, 0.45);
    brush.line(bx - 1, by - 1, (bx + tx) * 0.5 - 1, (by + ty) * 0.5 - 1);

    for (let f = 0.28; f <= 0.78; f += 0.16) {
      let vx = lerpVal(bx, tx, f);
      let vy = lerpVal(by, ty, f);
      let vw = halfW * (1 - Math.abs(f - 0.52) * 1.45) * 0.68;
      let v1x = vx + cos(ang + 55) * vw;
      let v1y = vy + sin(ang + 55) * vw;
      let v2x = vx + cos(ang - 55) * vw;
      let v2y = vy + sin(ang - 55) * vw;
      brush.set("rotring", PAL.oxideDeep, 0.5);
      brush.line(vx, vy, v1x, v1y);
      brush.line(vx, vy, v2x, v2y);
    }
  }

  // Central Raised Boss of the Quatrefoil
  brush.set("rotring", PAL.soot, 1.3);
  brush.circle(cx + 2, cy + 2, rad * 0.15, 0.1);
  brush.set("cpencil", PAL.copperWarm, 1.1);
  brush.circle(cx, cy, rad * 0.14, 0.1);
  brush.set("chisel", PAL.goldRubbed, 0.85);
  brush.arc(cx, cy, rad * 0.12, 190, 330);
}

