    PAL.copperMid, 185, 0.18, 0.65, 0.35, 0.2
  );

  // Lit chest & left shoulder of the football jersey
  fillShapePoly(
    [[255, 555], [450, 495], [765, 520], [795, 980], [355, 1085], [335, 720], [220, 775]],
    PAL.copperMid, 175, 0.2, 0.68, 0.4, 0.15
  );

  // Batch 3: Coral Collar Terracotta-Red Bronze Base
  fillShapePoly(
    [[415, 455], [600, 475], [785, 455], [795, 560], [600, 608], [405, 560]],
    PAL.coralMid, 215, 0.15, 0.65, 0.45, 0.2
