  );
}

// =============================================================================
// 5. MODERN FOOTBALL JERSEY IN CAST BRONZE & HYPERREAL WEAVE
// =============================================================================

function getJerseyNormal(x, y) {
  // Base cylindrical torso curvature across x = 330..870
  let nx = (x - 585) / 310;
  let ny = (y - 740) / 480 - 0.12;

  // Pectoral & drapery fold modulations
  // Catenary drapery folds hanging across the chest from the shoulders/collar
  let foldPhase1 = Math.sin((y - 610) * 0.055 - Math.abs(x - 600) * 0.012);
  let foldPhase2 = Math.cos((x - 600) * 0.032 + (y - 650) * 0.025);
  nx += 0.18 * foldPhase2;
  ny += 0.22 * foldPhase1;

  // Shoulder & sleeve cylindrical curvature when outside torso
  if (x < 355) {
    nx = (x - 285) / 95;
    ny = (y - 680) / 220 - 0.2;
  } else if (x > 845) {
    nx = (x - 915) / 95;
    ny = (y - 680) / 220 - 0.2;
  }

  let nz = Math.sqrt(Math.max(0.12, 1 - nx * nx - ny * ny));
  return norm3(nx, ny, nz);
}

function drawFootballJersey() {
  // 1. Undercut shadow of the Coral Collar onto the upper jersey chest
  fillShapePoly(
    [[400, 555], [600, 605], [800, 555], [790, 630], [600, 650], [410, 630]],
    PAL.soot, 195, 0.18, 0.6, 0.4, 0.2
  );

  // Verdigris pooled right below the collar rim and in armpit creases
  fillShapePoly(
    [[425, 570], [600, 616], [775, 570], [765, 595], [600, 632], [435, 595]],
    PAL.verdMid, 140, 0.2, 0.7, 0.4, 0.2
  );

  // 2. Modern Jacquard Vertical Kit Stripes & Breathable Mesh Weave
  // We render the torso from y = 555 to 1108, x = 345 to 855
  const torsoTop = 555;
  const torsoBot = 1106;

  // Vertical jacquard kit bands (subtle raised chevron/stripe pattern of a Nigeria/club jersey)
  for (let x = 352; x <= 848; x += 6) {
    let bandIdx = Math.floor((x - 350) / 36);
    let isJacquardStripe = (bandIdx % 2 === 0);

    // Top bound follows the bottom of the coral collar
    let dx = (x - 600) / 210;
    let yStart = dx * dx < 1 ? 604 - dx * dx * 48 : 556;

    for (let y = yStart; y < torsoBot; y += 11) {
      // Skip where the mudfish or hands overlap the outer torso edges
      if (x < 395 && y < 740) continue;
      if (x > 805 && y < 740) continue;

      let N = getJerseyNormal(x, y);
      let illum = dotLight(N.x, N.y, N.z);
      if (isJacquardStripe) illum = clamp01(illum + 0.07);

      // Drapery wave offset
      let waveY = Math.sin((x - 600) * 0.025 + y * 0.015) * 4.5;
      let col = bronzeToneColor(illum, (illum < 0.28 && ((x + y) % 5 === 0)) ? 0.6 : 0);

      // Warp thread stroke
      brush.set("rotring", col, isJacquardStripe ? 0.68 : 0.52);
      brush.line(x, y + waveY, x, y + 8 + waveY);

      // Weft micro-mesh cross-stitch (gives hyperreal breathable polyester weave in bronze)
      if ((y % 22) < 11) {
        let weftAng = isJacquardStripe ? 22 : -22;
        let wx = cos(weftAng) * 5.5;
        let wy = sin(weftAng) * 5.5;
        brush.set("chisel", col, 0.48);
        brush.line(x - wx * 0.5, y + waveY - wy * 0.5, x + wx * 0.5, y + waveY + wy * 0.5);
      }

      // Burnished gold highlight on the crests of the jersey folds & jacquard stripes
      if (illum > 0.82 && isJacquardStripe) {
        brush.set("chisel", illum > 0.90 ? PAL.goldGleam : PAL.goldRubbed, 0.65);
        brush.line(x + 1, y + waveY, x + 1, y + 6 + waveY);
      }
    }
  }

  // 3. Raglan Sleeves (Left & Right) with Knit Weave & Triple Shoulder Stripes
  drawJerseySleeve(-1);
  drawJerseySleeve(1);

  // 4. Sculptural Drapery Folds Across the Chest & Abdomen
  const chestFolds = [
    [[385, 665], [495, 710], [610, 715], [735, 685], [815, 655]],
    [[375, 745], [485, 790], [605, 798], [720, 775], [820, 735]],
    [[365, 835], [490, 880], [615, 885], [735, 860], [830, 825]],
    [[360, 925], [495, 968], [610, 972], [730, 950], [835, 915]],
    [[360, 1015], [500, 1052], [615, 1056], [735, 1035], [835, 1005]]
  ];
  for (let fold of chestFolds) {
    // Deep fold trough
    let shadowPts = fold.map(p => [p[0], p[1] + 5]);
    brush.set("rotring", PAL.oxideDark, 1.15);
    safeSpline(shadowPts, 0.5);

    // Subtle verdigris inside deepest fold troughs on the shadow side
    brush.set("cpencil", PAL.verdMid, 0.75);
    safeSpline(shadowPts.slice(2), 0.5);

    // Warm copper midtone ridge
    brush.set("cpencil", PAL.copperWarm, 1.35);
    safeSpline(fold, 0.5);

    // Burnished brass highlight on the left/center crest of each drapery fold
    let litPts = fold.slice(0, 4).map(p => [p[0], p[1] - 3]);
    brush.set("burnish", PAL.goldRubbed, 0.9);
    safeSpline(litPts, 0.5);
  }

  // 5. Ribbed V-Neck Jersey Collar (peeking out just beneath the Coral Collar)
  const vNeckOuter = [[485, 582], [600, 646], [715, 582]];
  const vNeckInner = [[508, 590], [600, 626], [692, 590]];
  brush.set("rotring", PAL.soot, 1.35);
  safeSpline(vNeckOuter, 0.25);
  safeSpline(vNeckInner, 0.25);

  // Ribbed knit stitching along the V-neck trim
  for (let t = 0.08; t <= 0.92; t += 0.035) {
    let x1 = t < 0.5 ? lerpVal(485, 600, t * 2) : lerpVal(600, 715, (t - 0.5) * 2);
    let y1 = t < 0.5 ? lerpVal(582, 646, t * 2) : lerpVal(646, 582, (t - 0.5) * 2);
    let x2 = t < 0.5 ? lerpVal(508, 600, t * 2) : lerpVal(600, 692, (t - 0.5) * 2);
    let y2 = t < 0.5 ? lerpVal(590, 626, t * 2) : lerpVal(626, 590, (t - 0.5) * 2);
    brush.set("chisel", t < 0.55 ? PAL.goldRubbed : PAL.copperMid, 0.65);
    brush.line(x1, y1, x2, y2);
  }

  // 6. Embossed Federation Crest on Left Chest (Viewer's Right: x=712, y=682)
  drawJerseyCrest(712, 682, 36);

  // 7. Embossed Kit Maker Logo on Right Chest (Viewer's Left: x=488, y=682)
  drawKitMakerLogo(488, 682);

  // 8. Chased High-Relief Jersey Number "9" on Center Chest (x=600, y=805)
  drawJerseyNumberNine(600, 805);
}

function drawJerseySleeve(side) {
  // side = -1 (left), +1 (right)
  let shX = 600 + side * 195;
  let shY = 505;
  let capX = 600 + side * 345;
  let capY = 558;
  let elbX = 600 + side * 392;
  let elbY = 760;
  let pitX = 600 + side * 248;
  let pitY = 695;

  // Raglan seam line from collar to armpit
  let seamPts = [
    [shX, shY],
    [600 + side * 225, 595],
    [pitX, pitY]
  ];
  brush.set("rotring", PAL.soot, 1.25);
  safeSpline(seamPts, 0.4);
  brush.set("chisel", side < 0 ? PAL.goldRubbed : PAL.copperWarm, 0.75);
  safeSpline(seamPts.map(p => [p[0] - side * 2, p[1] - 2]), 0.4);

  // Sleeve fabric mesh hatching along the cylindrical arm axis
  for (let u = 0.08; u <= 0.94; u += 0.055) {
    let topPx = lerpVal(shX, capX, u);
    let topPy = lerpVal(shY, capY, u);
    let botPx = lerpVal(pitX, elbX, u);
    let botPy = lerpVal(pitY, elbY, u);

    let steps = 14;
    for (let s = 0; s < steps; s++) {
      let v = s / steps;
      let px = lerpVal(topPx, botPx, v);
      let py = lerpVal(topPy, botPy, v);
      let N = getJerseyNormal(px, py);
      let illum = dotLight(N.x, N.y, N.z);
      let col = bronzeToneColor(illum, illum < 0.25 ? 0.5 : 0);

      brush.set("rotring", col, 0.58);
      let ang = side < 0 ? 115 : 65;
      brush.line(px, py, px + cos(ang) * 9, py + sin(ang) * 9);
      brush.set("chisel", col, 0.42);
      brush.line(px - 4, py + 2, px + 4, py + 5);
    }
  }

  // Iconic Triple Shoulder Stripes in Raised Cast Bronze
  for (let st = -1; st <= 1; st++) {
    let off = st * 13;
    let s1x = shX + side * (12 + off * 0.4);
    let s1y = shY + 6 + Math.abs(off) * 0.5;
    let s2x = capX + side * (off * 0.3);
    let s2y = capY + off * 0.9;
    let s3x = lerpVal(capX, elbX, 0.58) + side * (off * 0.2);
    let s3y = lerpVal(capY, elbY, 0.58) + off * 0.8;

    // Undercut shadow of stripe
    brush.set("rotring", PAL.soot, 1.3);
    safeSpline([[s1x, s1y + 3], [s2x, s2y + 3], [s3x, s3y + 3]], 0.35);

    // Raised brass stripe body
    brush.set("cpencil", side < 0 ? PAL.goldRubbed : PAL.brassWarm, 1.6);
    safeSpline([[s1x, s1y], [s2x, s2y], [s3x, s3y]], 0.35);

    // Specular edge
    if (side < 0 || st === -1) {
      brush.set("chisel", PAL.goldGleam, 0.7);
      safeSpline([[s1x, s1y - 1.5], [s2x, s2y - 1.5], [s3x, s3y - 1.5]], 0.35);
    }
  }

  // Ribbed Sleeve Cuff Band at the elbow
  let c1x = pitX - side * 8;
  let c1y = pitY + 25;
  let c2x = elbX;
  let c2y = elbY;
  brush.set("rotring", PAL.soot, 1.5);
  brush.line(c1x, c1y, c2x, c2y);
  brush.line(c1x - side * 6, c1y + 16, c2x - side * 6, c2y + 16);

  for (let k = 0; k <= 1; k += 0.08) {
    let kx1 = lerpVal(c1x, c2x, k);
    let ky1 = lerpVal(c1y, c2y, k);
    let kx2 = lerpVal(c1x - side * 6, c2x - side * 6, k);
    let ky2 = lerpVal(c1y + 16, c2y + 16, k);
    brush.set("chisel", side < 0 ? PAL.brassBright : PAL.copperWarm, 0.7);
    brush.line(kx1, ky1, kx2, ky2);
  }
}

function drawJerseyCrest(cx, cy, rad) {
  // Cast shadow of raised circular badge
  brush.set("rotring", PAL.soot, 1.6);
  brush.circle(cx + 2.5, cy + 2.5, rad, 0.12);

  // Verdigris inside the recessed ring of the crest
  brush.set("punch", PAL.verdMid, 1.1);
  brush.circle(cx, cy, rad * 0.65, 0.2);

  // Outer & inner embossed bronze shield rings
  brush.set("cpencil", PAL.brassWarm, 1.3);
  brush.circle(cx, cy, rad, 0.08);
  brush.set("rotring", PAL.oxideDark, 0.85);
  brush.circle(cx, cy, rad * 0.76, 0.08);

  // Burnished gold highlight on upper-left arc of crest
  brush.set("chisel", PAL.goldGleam, 1.0);
  brush.arc(cx, cy, rad, 185, 325);
  brush.arc(cx, cy, rad * 0.76, 185, 325);

  // Miniature embossed royal eagle / mudfish totem inside the badge
  brush.set("chisel", PAL.goldRubbed, 0.95);
  safeSpline([[cx - 16, cy - 4], [cx, cy - 12], [cx + 16, cy - 4]], 0.4);
  safeSpline([[cx - 12, cy + 4], [cx, cy - 2], [cx + 12, cy + 4]], 0.4);
  brush.circle(cx, cy + 8, 7, 0.1);

  // Stitched border ticks around the crest
  for (let a = 0; a < 360; a += 18) {
    let x1 = cx + cos(a) * (rad * 0.78);
    let y1 = cy + sin(a) * (rad * 0.78);
    let x2 = cx + cos(a) * (rad * 0.98);
    let y2 = cy + sin(a) * (rad * 0.98);
    brush.set("rotring", PAL.oxideDark, 0.55);
    brush.line(x1, y1, x2, y2);
  }
}

function drawKitMakerLogo(cx, cy) {
  // Classic athletic wing/triangle emblem chased in high relief
  for (let i = 0; i < 3; i++) {
    let bx = cx - 18 + i * 13;
    let by = cy + 12;
    let h = 14 + i * 7;
    brush.set("rotring", PAL.soot, 1.1);
    brush.line(bx + 2, by + 2, bx + 10, by - h + 2);
    brush.set("cpencil", PAL.goldRubbed, 1.4);
    brush.line(bx, by, bx + 8, by - h);
    brush.set("chisel", PAL.goldGleam, 0.8);
    brush.line(bx - 1, by, bx + 7, by - h);
  }
}

function drawJerseyNumberNine(cx, cy) {
  // High-relief athletic block numeral "9" cast into the chest bronze
  const outerLoop = [
    [cx - 28, cy - 52],
    [cx + 28, cy - 52],
    [cx + 34, cy - 20],
    [cx + 32, cy + 32],
    [cx + 18, cy + 56],
    [cx - 24, cy + 56],
    [cx - 30, cy + 36],
    [cx + 12, cy + 36],
    [cx + 16, cy + 8],
    [cx - 26, cy + 8],
    [cx - 34, cy - 22]
  ];
  const innerHole = [
    [cx - 14, cy - 34],
    [cx + 14, cy - 34],
    [cx + 16, cy - 8],
    [cx - 14, cy - 8]
  ];

  // Cast shadow of the raised numeral
  brush.set("rotring", PAL.soot, 1.6);
  safeSpline([...outerLoop, outerLoop[0]].map(p => [p[0] + 3, p[1] + 3]), 0.15);
  safeSpline([...innerHole, innerHole[0]].map(p => [p[0] + 2, p[1] + 2]), 0.15);

  // Diagonal chased hatching inside the numeral "9"
  for (let y = cy - 50; y <= cy + 54; y += 5) {
    let xLeft = cx - 30;
    let xRight = cx + 30;
    if (y > cy + 10 && y < cy + 34) {
      xLeft = cx + 10; // stem of the 9
    }
    for (let x = xLeft; x <= xRight; x += 6) {
      // Skip inner counter hole
      if (x > cx - 15 && x < cx + 15 && y > cy - 35 && y < cy - 7) continue;
      let isLit = (x < cx + 10 && y < cy + 5);
      brush.set("chisel", isLit ? PAL.goldRubbed : PAL.brassWarm, 0.75);
      brush.line(x, y, x + 5, y - 4);
    }
  }

  // Crisp chased outline & rubbed gold highlight
  brush.set("rotring", PAL.oxideDark, 1.0);
  safeSpline([...outerLoop, outerLoop[0]], 0.12);
  safeSpline([...innerHole, innerHole[0]], 0.12);

  brush.set("chisel", PAL.goldGleam, 0.95);
  safeSpline(outerLoop.slice(0, 5), 0.12);
  safeSpline([outerLoop[9], outerLoop[10], outerLoop[0]], 0.12);
}

// =============================================================================
// 6. STACKED CORAL BEAD COLLAR (ODIGBA)
// =============================================================================

function drawCoralBeadCollar() {
  const numRows = 8;
  // Collar arches around neck center (600, 405)
  const archCx = 600;
  const archCy = 402;

  for (let r = numRows - 1; r >= 0; r--) {
    // Outer rows drawn first, inner/upper rows overlap slightly
    let tRow = r / (numRows - 1); // 0 = top row under chin, 1 = bottom row on chest
    let rx = lerpVal(128, 204, tRow);
    let ry = lerpVal(68, 198, tRow);
    let beadH = lerpVal(14, 18, tRow);

    let startAng = lerpVal(14, 8, tRow);
    let endAng = 180 - startAng;

    // Deep groove shadow and verdigris string line between stacked rows
    let groovePts = [];
    for (let a = startAng; a <= endAng; a += 6) {
      groovePts.push([archCx + cos(a) * rx, archCy + sin(a) * (ry + beadH * 0.55)]);
    }
    brush.set("rotring", PAL.soot, 1.65);
    safeSpline(groovePts, 0.4);

    if (r % 2 === 1) {
      brush.set("cpencil", PAL.verdMid, 0.95);
      safeSpline(groovePts.map(p => [p[0], p[1] + 1.5]), 0.4);
    }

    // Number of cylindrical coral beads in this row
    let numBeads = Math.floor(lerpVal(20, 32, tRow));
    let dAng = (endAng - startAng) / numBeads;

    for (let b = 0; b < numBeads; b++) {
      let a1 = startAng + b * dAng;
      let a2 = a1 + dAng * 0.88;
      let aMid = (a1 + a2) * 0.5;

      // Bead center & radial orientation
      let bx = archCx + cos(aMid) * rx;
      let by = archCy + sin(aMid) * ry;

      // 3D normal of the collar torus + individual bead cylinder
      let nx = cos(aMid) * 0.72;
      let ny = (sin(aMid) - 0.55) * 0.65;
      let nz = Math.sqrt(Math.max(0.15, 1 - nx * nx - ny * ny));
      let illum = dotLight(nx, ny, nz);

      // Radial vector along bead length
      let radX = cos(aMid);
      let radY = sin(aMid) * (ry / rx);
      let rMag = Math.sqrt(radX * radX + radY * radY) || 1;
      radX /= rMag;
      radY /= rMag;

      // Tangent vector across bead width
      let tanX = -radY;
      let tanY = radX;

      let bLen = beadH * 0.48;
      let bWid = (rx * radians(dAng)) * 0.44;

      // Draw cylindrical coral bead with 5 longitudinal facet strokes
      for (let s = -2; s <= 2; s++) {
        let frac = s / 2; // -1 to +1 across bead width
        let localIllum = clamp01(illum - frac * 0.18 + (s === -1 ? 0.15 : 0));

        let col = PAL.coralMid;
        if (localIllum < 0.25) col = PAL.coralDark;
        else if (localIllum < 0.42) col = PAL.coralShadow;
        else if (localIllum < 0.62) col = PAL.coralMid;
        else if (localIllum < 0.78) col = PAL.coralWarm;
        else if (localIllum < 0.90) col = PAL.coralLit;
        else col = PAL.coralGleam;

        let ox = bx + tanX * (frac * bWid);
        let oy = by + tanY * (frac * bWid);
        let x1 = ox - radX * bLen;
        let y1 = oy - radY * bLen;
        let x2 = ox + radX * bLen;
        let y2 = oy + radY * bLen;

        brush.set("cpencil", col, 1.15);
        brush.line(x1, y1, x2, y2);

        // Burnished golden-coral specular glint on the central/left swell of the collar
        if (s === -1 && localIllum > 0.76) {
          brush.set("chisel", localIllum > 0.88 ? PAL.goldGleam : PAL.coralGleam, 0.8);
          brush.line(
            lerpVal(x1, x2, 0.2),
            lerpVal(y1, y2, 0.2),
            lerpVal(x1, x2, 0.75),
            lerpVal(y1, y2, 0.75)
          );
        }
      }

      // Dark incised gap between adjacent beads
      let gx = archCx + cos(a2) * rx;
      let gy = archCy + sin(a2) * ry;
      brush.set("rotring", PAL.soot, 0.85);
      brush.line(gx - radX * bLen, gy - radY * bLen, gx + radX * bLen, gy + radY * bLen);
    }
  }

  // Braided Bronze Wire Rim along the bottom edge of the Coral Collar
  let rimPts = [];
  for (let a = 8; a <= 172; a += 4) {
    let px = archCx + cos(a) * 208;
    let py = archCy + sin(a) * 209;
    rimPts.push([px, py]);
  }
  brush.set("rotring", PAL.soot, 1.4);
  safeSpline(rimPts.map(p => [p[0], p[1] + 3]), 0.4);
  brush.set("cpencil", PAL.brassWarm, 1.3);
  safeSpline(rimPts, 0.4);
  brush.set("chisel", PAL.goldGleam, 0.85);
  safeSpline(rimPts.slice(12, 34), 0.4);
}

// =============================================================================
// 7. TWO WEST AFRICAN MUDFISH (EKHUE / CLARIAS) HELD BY THE GILLS
// =============================================================================

// Parametric S-curve spine of each mudfish (t = 0 at snout, t = 0.22 at gills, t = 1 at tail)
function getMudfishSpine(side, t) {
  let baseX = 600 + side * 295;
  let y = lerpVal(472, 1052, t);

  // Sinuous S-wave horizontal curve
  let wave = Math.sin(t * 360 * 1.15 - 25) * 38 * side;
  // Slightly narrower curve at the gill-grip zone (t ~ 0.22)
  let gripPinch = Math.exp(-Math.pow((t - 0.22) / 0.12, 2)) * 12 * (-side);
  let x = baseX + wave + gripPinch;

  // Body half-width profile:
  // Broad flattened catfish head (t=0..0.18), pinched gill neck (t=0.22), muscular body (t=0.35..0.7), tapered tail
  let radius = 32;
  if (t < 0.18) {
    // Broad rounded-triangle catfish head
    let ht = t / 0.18;
    radius = 18 + Math.sin(ht * 135) * 31;
  } else if (t < 0.27) {
    // Gill plate pinch where fingers clamp
    let gt = (t - 0.18) / 0.09;
    radius = lerpVal(38, 27, Math.sin(gt * 180));
  } else if (t < 0.86) {
    // Muscular cylindrical body tapering toward peduncle
    let bt = (t - 0.27) / 0.59;
    radius = lerpVal(36, 15, Math.pow(bt, 1.25));
  } else {
    // Rounded caudal fin fan (t=0.86..1.0)
    let ct = (t - 0.86) / 0.14;
    radius = 15 + Math.sin(ct * 155) * 24;
  }

  return { x, y, r: radius };
}

function drawMudfish(side) {
  // Sample spine & tangents
  const N_SAMPLES = 60;
  let spine = [];
  for (let i = 0; i <= N_SAMPLES; i++) {
    let t = i / N_SAMPLES;
    spine.push({ t, ...getMudfishSpine(side, t) });
  }
  for (let i = 0; i <= N_SAMPLES; i++) {
    let p0 = spine[Math.max(0, i - 1)];
    let p1 = spine[Math.min(N_SAMPLES, i + 1)];
    let dx = p1.x - p0.x;
    let dy = p1.y - p0.y;
    let m = Math.sqrt(dx * dx + dy * dy) || 1;
    // Normal pointing right of downward tangent
    spine[i].tx = dx / m;
    spine[i].ty = dy / m;
    spine[i].nx = -spine[i].ty;
    spine[i].ny = spine[i].tx;
  }

  // 1. Watercolor Base of the Mudfish Body
  let polyPts = [];
  for (let i = 0; i <= N_SAMPLES; i += 2) {
    let s = spine[i];
    polyPts.push([s.x - s.nx * s.r, s.y - s.ny * s.r]);
  }
  for (let i = N_SAMPLES; i >= 0; i -= 2) {
    let s = spine[i];
    polyPts.push([s.x + s.nx * s.r, s.y + s.ny * s.r]);
  }
  fillShapePoly(polyPts, PAL.copperDeep, 225, 0.12, 0.65, 0.4, 0.15);

  // 2. Dorsal, Anal & Pectoral Fins (drawn before body scales so scales overlap fin roots)
  drawMudfishFins(side, spine);

  // 3. Caudal (Tail) Fin with Radiating Bony Rays (t = 0.86..1.0)
  drawMudfishTailFin(side, spine);

  // 4. Overlapping Anatomical Scales along the Muscular Body (t = 0.23..0.86)
  const numRows = 27;
  for (let rIdx = numRows - 1; rIdx >= 0; rIdx--) {
    let t = lerpVal(0.23, 0.85, rIdx / (numRows - 1));
    let sIdx = Math.round(t * N_SAMPLES);
    let sp = spine[sIdx];

    let colsInRow = Math.max(5, Math.round(sp.r / 4.2));
    let rowShift = (rIdx % 2) * 0.5;

    for (let cIdx = 0; cIdx < colsInRow; cIdx++) {
      // u goes from -0.92 to +0.92 across the width of the fish cylinder
      let u = ((cIdx + rowShift + 0.25) / colsInRow) * 1.84 - 0.92;
      if (Math.abs(u) > 0.95) continue;

      let sx = sp.x + sp.nx * (u * sp.r);
      let sy = sp.y + sp.ny * (u * sp.r);

      // Foreshortened scale width near the cylinder edges
      let cylZ = Math.sqrt(Math.max(0.08, 1 - u * u));
      let scaleW = (sp.r / colsInRow) * 1.75 * cylZ;
      let scaleH = 12.5;

      // 3D normal of this scale on the curving cylindrical fish body
      let normX = sp.nx * u;
      let normY = sp.ny * u - 0.15;
      let normZ = cylZ * 0.88;
      let N = norm3(normX, normY, normZ);
      let illum = dotLight(N.x, N.y, N.z);

      // Scale arch points (pointing down toward tail)
      let pLeft = [sx - sp.nx * scaleW, sy - sp.ny * scaleW];
      let pTip = [sx + sp.tx * scaleH, sy + sp.ty * scaleH];
      let pRight = [sx + sp.nx * scaleW, sy + sp.ny * scaleW];

      // Dark incised scale pocket (with verdigris in deep shadow flank)
      let pocketCol = (illum < 0.28 && (rIdx + cIdx) % 2 === 0) ? PAL.verdMid : PAL.soot;
      brush.set("rotring", pocketCol, 0.85);
      safeSpline([pLeft, [pTip[0] + 1, pTip[1] + 1.5], pRight], 0.45);

      // Scale surface chasing lines
      let bodyCol = bronzeToneColor(illum);
      brush.set("chisel", bodyCol, 0.72);
      brush.line(sx - sp.nx * scaleW * 0.5, sy - sp.tx * 2, pTip[0], pTip[1]);
      brush.line(sx + sp.nx * scaleW * 0.5, sy - sp.tx * 2, pTip[0], pTip[1]);

      // Gleaming hand-rubbed brass-gold crescent along the lit ridge of the mudfish
      if (illum > 0.72) {
        brush.set("chisel", illum > 0.86 ? PAL.goldGleam : PAL.goldRubbed, illum > 0.86 ? 0.95 : 0.75);
        safeSpline([pLeft, pTip, pRight], 0.45);
        if (illum > 0.89) {
          brush.set("rotring", PAL.specular, 0.55);
          brush.line(sx, sy + 2, pTip[0], pTip[1] - 1);
        }
      }
    }
  }

  // 5. Armored Catfish Head, Eyes, Gill Opercula & Sweeping Barbels (t = 0..0.24)
  drawMudfishHeadAndBarbels(side, spine);
}

function drawMudfishFins(side, spine) {
  const N_SAMPLES = spine.length - 1;

  // Long Continuous Dorsal Fin along the outer flank (t = 0.28..0.83)
  let dorsalOutline = [];
  for (let i = Math.round(0.28 * N_SAMPLES); i <= Math.round(0.83 * N_SAMPLES); i++) {
    let s = spine[i];
    let finOut = side; // outer side of plaque
    let finW = 24 * Math.sin(((s.t - 0.28) / 0.55) * 180);
    let rx = s.x + s.nx * finOut * (s.r * 0.92);
    let ry = s.y + s.ny * finOut * (s.r * 0.92);
    let tx = rx + s.nx * finOut * finW + s.tx * 6;
    let ty = ry + s.ny * finOut * finW + s.ty * 6;
    dorsalOutline.push([tx, ty]);

    // Fin ray spine
    brush.set("rotring", PAL.oxideDark, 0.75);
    brush.line(rx, ry, tx, ty);
    brush.set("chisel", side < 0 ? PAL.goldRubbed : PAL.copperWarm, 0.55);
    brush.line(rx, ry - 1, tx, ty - 1);

    // Verdigris between fin rays
    if (i % 3 === 0) {
      brush.set("cpencil", PAL.verdMid, 0.65);
      brush.line(rx + s.nx * finOut * 4, ry + 3, lerpVal(rx, tx, 0.6), lerpVal(ry, ty, 0.6) + 3);
    }
  }
  brush.set("rotring", PAL.soot, 1.0);
  safeSpline(dorsalOutline, 0.4);

  // Inner Anal Fin (t = 0.52..0.82)
  let analOutline = [];
  for (let i = Math.round(0.52 * N_SAMPLES); i <= Math.round(0.82 * N_SAMPLES); i += 2) {
    let s = spine[i];
    let finIn = -side;
    let finW = 16 * Math.sin(((s.t - 0.52) / 0.30) * 180);
    let rx = s.x + s.nx * finIn * (s.r * 0.92);
    let ry = s.y + s.ny * finIn * (s.r * 0.92);
    let tx = rx + s.nx * finIn * finW + s.tx * 5;
    let ty = ry + s.ny * finIn * finW + s.ty * 5;
    analOutline.push([tx, ty]);

    brush.set("rotring", PAL.oxideDark, 0.65);
    brush.line(rx, ry, tx, ty);
    brush.set("chisel", side > 0 ? PAL.brassWarm : PAL.copperMid, 0.5);
    brush.line(rx, ry, lerpVal(rx, tx, 0.8), lerpVal(ry, ty, 0.8));
  }
  brush.set("rotring", PAL.soot, 0.9);
  safeSpline(analOutline, 0.4);

  // Spiny Pectoral Fins flaring out just below the gill-grip (t = 0.25)
  let pecS = spine[Math.round(0.25 * N_SAMPLES)];
  for (let fSide of [-1, 1]) {
    let bx = pecS.x + pecS.nx * fSide * (pecS.r * 0.88);
    let by = pecS.y + pecS.ny * fSide * (pecS.r * 0.88);
    for (let r = 0; r < 7; r++) {
      let ang = (fSide > 0 ? 25 : 155) + fSide * r * 11;
      let rayLen = 36 - r * 3.2;
      let ex = bx + cos(ang) * rayLen;
      let ey = by + sin(ang) * rayLen;
      brush.set("rotring", PAL.soot, 0.9);
      brush.line(bx, by + 2, ex, ey + 2);
      brush.set("chisel", r === 0 ? PAL.goldRubbed : PAL.copperWarm, r === 0 ? 0.95 : 0.6);
      brush.line(bx, by, ex, ey);
    }
  }
}

function drawMudfishTailFin(side, spine) {
  const N_SAMPLES = spine.length - 1;
  let baseS = spine[Math.round(0.86 * N_SAMPLES)];
  let tipS = spine[N_SAMPLES];
  let cx = lerpVal(baseS.x, tipS.x, 0.35);
  let cy = lerpVal(baseS.y, tipS.y, 0.35);

  let fanPts = [];
  for (let a = -75; a <= 75; a += 7.5) {
    let worldAng = 90 + a - side * 8;
    let rayLen = 48 * (0.78 + 0.22 * Math.cos(a * 1.5));
    let rx = cx + cos(worldAng) * rayLen;
    let ry = cy + sin(worldAng) * rayLen;
    fanPts.push([rx, ry]);

    // Shadow & verdigris web
    brush.set("rotring", PAL.soot, 0.85);
    brush.line(cx + 1.5, cy + 1.5, rx + 1.5, ry + 1.5);
    if (Math.abs(a) > 25) {
      brush.set("cpencil", PAL.verdMid, 0.6);
      brush.line(cx, cy, lerpVal(cx, rx, 0.65), lerpVal(cy, ry, 0.65));
    }

    // Raised bronze fin ray
    let isLit = (a * (-side) > 0 || a < -15);
    brush.set("chisel", isLit ? PAL.goldRubbed : PAL.copperWarm, 0.72);
    brush.line(cx, cy, rx, ry);
  }

  // Concentric growth striations across the tail fan
  brush.set("rotring", PAL.oxideDark, 0.9);
  safeSpline(fanPts, 0.45);
  brush.set("chisel", PAL.brassWarm, 0.65);
  safeSpline(fanPts.slice(2, fanPts.length - 2).map(p => [lerpVal(cx, p[0], 0.68), lerpVal(cy, p[1], 0.68)]), 0.45);
}

function drawMudfishHeadAndBarbels(side, spine) {
  const N_SAMPLES = spine.length - 1;

  // Armored cranial plate modeling (t = 0..0.22)
  for (let i = 0; i <= Math.round(0.22 * N_SAMPLES); i++) {
    let s = spine[i];
    let steps = 14;
    for (let k = 0; k <= steps; k++) {
      let u = (k / steps) * 2 - 1;
      let px = s.x + s.nx * u * s.r;
      let py = s.y + s.ny * u * s.r;
      let nz = Math.sqrt(Math.max(0.1, 1 - u * u));
      let N = norm3(s.nx * u, s.ny * u - 0.25, nz);
      let illum = dotLight(N.x, N.y, N.z);

      let col = bronzeToneColor(illum, illum < 0.25 ? 0.5 : 0);
      brush.set("chisel", col, 0.7);
      brush.line(px, py, px + s.tx * 7, py + s.ty * 7);

      // Granulated cranial bone bumps (authentic catfish skull texture)
      if ((i + k) % 2 === 0 && illum > 0.45) {
        brush.set("rotring", illum > 0.78 ? PAL.goldGleam : PAL.brassWarm, 0.65);
        brush.circle(px, py, 1.8, 0.1);
      }
    }
  }

  // Cranial median fontanelle groove & bone sutures
  let snout = spine[0];
  let nape = spine[Math.round(0.18 * N_SAMPLES)];
  brush.set("rotring", PAL.soot, 1.1);
  brush.line(snout.x, snout.y + 12, nape.x, nape.y);
  brush.set("chisel", PAL.goldRubbed, 0.75);
  brush.line(snout.x - 2, snout.y + 12, nape.x - 2, nape.y);

  // Gill Operculum Plates & Gill Slits (t = 0.16..0.23, where fingers grip!)
  let gillS = spine[Math.round(0.18 * N_SAMPLES)];
  for (let g = 0; g < 3; g++) {
    let gy = gillS.y - 6 + g * 8;
    let gArch = [
      [gillS.x - gillS.r * 0.88, gy + 8],
      [gillS.x, gy - 6],
      [gillS.x + gillS.r * 0.88, gy + 8]
    ];
    brush.set("rotring", PAL.soot, 1.25);
    safeSpline(gArch, 0.45);
    brush.set("cpencil", PAL.verdBright, 0.75);
    safeSpline(gArch.map(p => [p[0], p[1] + 2]), 0.45);
    brush.set("chisel", PAL.goldRubbed, 0.8);
    safeSpline(gArch.map(p => [p[0], p[1] - 1.5]), 0.45);
  }

  // Small Glistening Catfish Eyes (t = 0.07)
  let eyeS = spine[Math.round(0.07 * N_SAMPLES)];
  for (let eSide of [-0.55, 0.55]) {
    let ex = eyeS.x + eyeS.nx * eSide * eyeS.r;
    let ey = eyeS.y + eyeS.ny * eSide * eyeS.r;
    brush.set("rotring", PAL.soot, 1.3);
    brush.circle(ex, ey, 6.5, 0.1);
    brush.set("cpencil", PAL.brassWarm, 1.0);
    brush.circle(ex, ey, 5.2, 0.1);
    brush.set("rotring", PAL.soot, 1.2);
    brush.circle(ex, ey, 2.6, 0.05);
    brush.set("chisel", PAL.specular, 0.9);
    brush.circle(ex - 1.5, ey - 1.5, 1.4, 0.05);
  }

  // Broad Mouth & 3 Pairs of Sweeping Whisker Barbels
  let mouthL = [snout.x - 24, snout.y + 4];
  let mouthM = [snout.x, snout.y - 4];
  let mouthR = [snout.x + 24, snout.y + 4];
  brush.set("rotring", PAL.soot, 1.5);
  safeSpline([mouthL, mouthM, mouthR], 0.4);
  brush.set("chisel", PAL.goldGleam, 0.9);
  safeSpline([[mouthL[0], mouthL[1] - 2], [mouthM[0], mouthM[1] - 2], [mouthR[0], mouthR[1] - 2]], 0.4);

  // 6 Dynamic Barbels (3 on each side of the snout)
  const barbelPaths = [
    // Long maxillary outer barbel sweeping high and outward
    [
      [snout.x + side * 22, snout.y + 2],
      [snout.x + side * 78, snout.y - 38],
      [snout.x + side * 124, snout.y - 95],
      [snout.x + side * 95, snout.y - 148],
      [snout.x + side * 52, snout.y - 132]
    ],
    // Long inner barbel curling toward the head/collar
    [
      [snout.x - side * 20, snout.y + 2],
      [snout.x - side * 68, snout.y - 32],
      [snout.x - side * 98, snout.y - 82],
      [snout.x - side * 72, snout.y - 125]
    ],
    // Outer mandibular barbel sweeping outward & down
    [
      [snout.x + side * 20, snout.y + 10],
      [snout.x + side * 75, snout.y + 18],
      [snout.x + side * 112, snout.y + 68],
      [snout.x + side * 96, snout.y + 118]
    ],
    // Inner mandibular barbel
    [
      [snout.x - side * 18, snout.y + 10],
      [snout.x - side * 62, snout.y + 22],
      [snout.x - side * 84, snout.y + 65]
    ],
    // Short nasal barbels
    [
      [snout.x + side * 10, snout.y + 14],
      [snout.x + side * 34, snout.y - 26],
      [snout.x + side * 52, snout.y - 54]
    ],
    [
      [snout.x - side * 10, snout.y + 14],
      [snout.x - side * 32, snout.y - 24],
      [snout.x - side * 46, snout.y - 52]
    ]
  ];

  for (let bPts of barbelPaths) {
    // Cast shadow onto plaque
    brush.set("rotring", PAL.soot, 1.45);
    safeSpline(bPts.map(p => [p[0] + 3, p[1] + 4]), 0.5);
    // Warm copper barbel body
    brush.set("cpencil", PAL.copperWarm, 1.35);
    safeSpline(bPts, 0.5);
    // Burnished gold wire ridge
    brush.set("chisel", PAL.goldGleam, 0.85);
    safeSpline(bPts.map(p => [p[0] - 1, p[1] - 1]), 0.5);
  }
}

// =============================================================================
// 8. FOREARMS, CORAL WRISTBANDS & HANDS GRIPPING THE GILLS
// =============================================================================

function drawForearmsAndHands(side) {
  // Forearm rises from elbow inside sleeve cuff to the wrist below the mudfish gills
  let elbX = 600 + side * 382;
  let elbY = 768;
  let wristX = 600 + side * 322;
  let wristY = 656;

  // Gill grip center on the mudfish (t = 0.21)
  let gillPos = getMudfishSpine(side, 0.21);
  let handX = gillPos.x;
  let handY = gillPos.y;

  // 1. Forearm Watercolor Base & Cast Shadow
  let armAxisX = wristX - elbX;
  let armAxisY = wristY - elbY;
  let armLen = Math.sqrt(armAxisX * armAxisX + armAxisY * armAxisY) || 1;
  let nx = -armAxisY / armLen;
  let ny = armAxisX / armLen;
  if (ny > 0) { nx = -nx; ny = -ny; } // Ensure normal points toward upper-left light

  let armPoly = [
    [elbX - nx * 42, elbY - ny * 42],
    [wristX - nx * 30, wristY - ny * 30],
    [wristX + nx * 30, wristY + ny * 30],
    [elbX + nx * 42, elbY + ny * 42]
  ];
  fillShapePoly(armPoly.map(p => [p[0] + 5, p[1] + 6]), PAL.soot, 195, 0.15, 0.6, 0.4, 0.15);
  fillShapePoly(armPoly, PAL.copperDeep, 235, 0.12, 0.65, 0.4, 0.15);

  // 2. Sculptural Forearm Musculature, Cross-Hatching & Subcutaneous Veins
  const stepsU = 22;
  const stepsV = 14;
  for (let i = 0; i <= stepsU; i++) {
    let u = i / stepsU;
    let cx = lerpVal(elbX, wristX, u);
    let cy = lerpVal(elbY, wristY, u);
    let rad = lerpVal(41, 29, u) * (1 + 0.12 * Math.sin(u * 180));

    for (let j = 0; j <= stepsV; j++) {
      let v = (j / stepsV) * 2 - 1; // -1 to +1 across forearm cylinder
      let px = cx + nx * (v * rad);
      let py = cy + ny * (v * rad);
      let nz = Math.sqrt(Math.max(0.1, 1 - v * v));
      let N = norm3(nx * v, ny * v, nz);
      let illum = dotLight(N.x, N.y, N.z);

      let col = bronzeToneColor(illum);
      // Longitudinal muscle fiber stroke
      brush.set("chisel", col, 0.72);
      brush.line(px, py, px + (armAxisX / armLen) * 9, py + (armAxisY / armLen) * 9);

      // Bracelet-contour cross-hatch for metallic flesh volume
      if ((i + j) % 2 === 0) {
        brush.set("rotring", col, 0.5);
        brush.line(px - nx * 3.5, py - ny * 3.5, px + nx * 3.5, py + ny * 3.5);
      }

      // Rubbed golden-brass highlight along the forearm extensor ridge
      if (illum > 0.84) {
        brush.set("chisel", illum > 0.91 ? PAL.goldGleam : PAL.goldRubbed, 0.85);
        brush.line(px, py, px + (armAxisX / armLen) * 7, py + (armAxisY / armLen) * 7);
      }
    }
  }

  // Prominent forearm vein & tendon rising toward the wrist
  let veinPts = [
    [lerpVal(elbX, wristX, 0.15) + nx * 8, lerpVal(elbY, wristY, 0.15) + ny * 8],
    [lerpVal(elbX, wristX, 0.52) + nx * 12, lerpVal(elbY, wristY, 0.52) + ny * 12],
    [lerpVal(elbX, wristX, 0.85) + nx * 5, lerpVal(elbY, wristY, 0.85) + ny * 5]
  ];
  brush.set("rotring", PAL.oxideDark, 0.9);
  safeSpline(veinPts.map(p => [p[0] + 1.5, p[1] + 1.5]), 0.45);
  brush.set("chisel", PAL.goldRubbed, 0.9);
  safeSpline(veinPts, 0.45);

  // 3. Three-Row Coral Bead Wristband (Ivie) at the Wrist
  for (let r = 0; r < 3; r++) {
    let wu = 0.84 + r * 0.065;
    let wcx = lerpVal(elbX, wristX, wu);
    let wcy = lerpVal(elbY, wristY, wu);
    let wrad = 32;

    brush.set("rotring", PAL.soot, 1.25);
    brush.line(wcx - nx * wrad, wcy - ny * wrad + 2, wcx + nx * wrad, wcy + ny * wrad + 2);

    for (let b = -4; b <= 4; b++) {
      let bv = b / 4.5;
      let bx = wcx + nx * (bv * wrad);
      let by = wcy + ny * (bv * wrad);
      let bCol = bv > 0.1 ? PAL.coralLit : (bv > -0.4 ? PAL.coralMid : PAL.coralDark);
      brush.set("cpencil", bCol, 1.35);
      brush.line(bx, by, bx + (armAxisX / armLen) * 7, by + (armAxisY / armLen) * 7);
      if (bv > 0.25) {
        brush.set("chisel", PAL.coralGleam, 0.75);
        brush.line(bx, by, bx + (armAxisX / armLen) * 5, by + (armAxisY / armLen) * 5);
      }
    }
  }

  // 4. Powerful Hand & Fingers Clamping the Mudfish Gill Slits
  // 4 Fingers wrapping across the front of the gill neck (y = handY - 24 .. handY + 28)
  const fingerOffsets = [-22, -7, 8, 22];
  for (let f = 0; f < 4; f++) {
    let fy = handY + fingerOffsets[f];
    let fLen = (f === 1 || f === 2) ? 31 : 27;

    // Finger wraps from outer side across the gill plate toward the inner gill slit
    let knuckleX = handX + side * (fLen * 0.95);
    let knuckleY = fy + 5;
    let midPhalX = handX - side * (fLen * 0.15);
    let midPhalY = fy - 2;
    let tipX = handX - side * (fLen * 0.92);
    let tipY = fy + 2;

    // Deep inter-finger shadow & verdigris trace
    brush.set("rotring", PAL.soot, 1.5);
    safeSpline([[knuckleX, knuckleY + 6], [midPhalX, midPhalY + 6], [tipX, tipY + 5]], 0.4);
    if (f < 3) {
      brush.set("cpencil", PAL.verdMid, 0.7);
      safeSpline([[knuckleX, knuckleY + 7], [midPhalX, midPhalY + 7]], 0.4);
    }

    // 3D cylindrical finger shading (5 longitudinal strokes per finger)
    for (let s = -2; s <= 2; s++) {
      let syOff = s * 2.2;
      let fIllum = s === -1 ? 0.90 : (s === 0 ? 0.78 : (s === -2 ? 0.68 : (s === 1 ? 0.50 : 0.28)));
      if (side > 0 && s === -1) fIllum = 0.85;
      let col = bronzeToneColor(fIllum);

      brush.set("cpencil", col, 1.25);
      safeSpline([[knuckleX, knuckleY + syOff], [midPhalX, midPhalY + syOff], [tipX, tipY + syOff]], 0.4);
    }

    // Knuckle wrinkles & skin creases
    for (let k of [0.22, 0.58]) {
      let kx = lerpVal(knuckleX, tipX, k);
      let ky = lerpVal(knuckleY, tipY, k);
      brush.set("rotring", PAL.oxideDark, 0.7);
      brush.line(kx - 1, ky - 4, kx - 1, ky + 4);
      brush.line(kx + 1, ky - 3.5, kx + 1, ky + 3.5);
      // Burnished gold highlight on knuckle peak
      brush.set("chisel", PAL.goldGleam, 0.9);
      brush.circle(kx - side * 3, ky - 1.5, 2.8, 0.1);
    }

    // Fingernail digging into the gill slit
    brush.set("rotring", PAL.soot, 0.75);
    brush.circle(tipX, tipY, 3.8, 0.1);
    brush.set("chisel", PAL.goldRubbed, 0.75);
    brush.arc(tipX, tipY, 3.2, 0, 360);
  }

  // Opposing Thumb hooking firmly into the upper gill operculum
  let thumbBaseX = wristX - side * 12;
  let thumbBaseY = wristY - 12;
  let thumbMidX = handX - side * 28;
  let thumbMidY = handY - 14;
  let thumbTipX = handX - side * 12;
  let thumbTipY = handY - 34;

  brush.set("rotring", PAL.soot, 1.5);
  safeSpline([[thumbBaseX + 2, thumbBaseY + 4], [thumbMidX + 2, thumbMidY + 4], [thumbTipX + 2, thumbTipY + 4]], 0.4);

  for (let s = -2; s <= 2; s++) {
    let col = s <= 0 ? PAL.goldRubbed : (s === 1 ? PAL.copperMid : PAL.bronzeShadow);
    brush.set("cpencil", col, 1.3);
    safeSpline([[thumbBaseX + s * 2, thumbBaseY], [thumbMidX + s * 2, thumbMidY], [thumbTipX + s * 2, thumbTipY]], 0.4);
  }
  brush.set("chisel", PAL.goldGleam, 0.9);
  safeSpline([[thumbBaseX - 2, thumbBaseY - 2], [thumbMidX - 2, thumbMidY - 2], [thumbTipX - 2, thumbTipY - 2]], 0.4);
}

// =============================================================================
// 9. HIERARCHIC FRONTAL HEAD (LIVING FLESH + CAST BRONZE + BEARD STUBBLE)
// =============================================================================

// Analytical 3D facial heightfield & surface normal for hyperreal bronze modeling
function getFaceReliefNormal(x, y) {
  let u = (x - 600) / 138; // -1 to +1 across head width
  let v = (y - 305) / 155; // -1 to +1 from crown to chin

  // Base cranial ellipsoid normal
  let nx = u * 0.82;
  let ny = v * 0.65;

  // Brow ridge overhang (y ~ 268..286)
  let browBump = Math.exp(-Math.pow((y - 274) / 14, 2)) * Math.exp(-Math.pow(u / 0.78, 2));
  ny += ((y - 274) / 14) * browBump * 0.45;

  // Orbital sockets depression (x ~ 532 and 668, y ~ 296)
  for (let ex of [532, 668]) {
    let dx = (x - ex) / 38;
    let dy = (y - 296) / 22;
    let r2 = dx * dx + dy * dy;
    if (r2 < 1.6) {
      let eyeDep = Math.exp(-r2 * 1.4);
      // Eyeball convexity inside socket
      if (r2 < 0.55) {
        nx += dx * 0.55;
        ny += dy * 0.65;
      } else {
        nx -= dx * eyeDep * 0.35;
        ny -= dy * eyeDep * 0.45;
      }
    }
  }

  // Sculptural Nose Bridge & Bulbous Tip (x ~ 600, y = 285..376)
  if (y > 275 && y < 385 && Math.abs(x - 600) < 58) {
    let nw = lerpVal(22, 46, clamp01((y - 285) / 85));
    let ndx = (x - 600) / nw;
    if (Math.abs(ndx) < 1.1) {
      nx += ndx * 0.72;
      // Tip boss at y = 362
      let tipDist = (y - 362) / 16;
      if (Math.abs(tipDist) < 1.2) {
        ny += tipDist * 0.52;
      }
    }
  }

  // Malar cheekbones (x ~ 505 & 695, y ~ 342)
  for (let cx of [505, 695]) {
    let cdx = (x - cx) / 45;
    let cdy = (y - 342) / 35;
    let cb = Math.exp(-(cdx * cdx + cdy * cdy));
    nx += cdx * cb * 0.35;
    ny += cdy * cb * 0.38;
  }

  // Full Sculpted Lips (y = 398..438, x = 544..656)
  if (y > 395 && y < 442 && Math.abs(x - 600) < 58) {
    if (y < 417) {
      // Upper lip angles slightly downward into shadow
      ny += 0.38;
    } else {
      // Lower lip swells strongly outward toward light
      let ldy = (y - 427) / 11;
      ny += ldy * 0.65;
    }
  }

  let nz = Math.sqrt(Math.max(0.12, 1 - nx * nx - ny * ny));
  return norm3(nx, ny, nz);
}

function drawHeadAndFace() {
  // 1. Sculpted Ears (Left & Right) with Verdigris in the Concha
  drawSculptedEar(-1);
  drawSculptedEar(1);

  // 2. Neck Cylinder emerging above the Coral Collar (y = 430..475)
  for (let y = 432; y <= 468; y += 5) {
    for (let x = 515; x <= 685; x += 6) {
      let nx = (x - 600) / 95;
      let ny = 0.25;
      let nz = Math.sqrt(Math.max(0.15, 1 - nx * nx - ny * ny));
      let illum = dotLight(nx, ny, nz);
      brush.set("rotring", bronzeToneColor(illum), 0.65);
      brush.line(x, y, x + 5, y + 2);
    }
  }

  // 3. Continuous 3D Form-Following Facial Hatching & Skin/Bronze Modeling
  // Covers forehead, brow, temples, cheeks, nose, and jaw (y = 198..455)
  for (let y = 200; y <= 452; y += 4.5) {
    // Cranial contour width at this y
    let tY = (y - 200) / 252; // 0 at top of forehead, 1 at chin
    let halfW = 132;
    if (tY < 0.25) halfW = lerpVal(115, 134, tY / 0.25);
    else if (tY < 0.62) halfW = lerpVal(134, 126, (tY - 0.25) / 0.37);
    else halfW = lerpVal(126, 68, Math.pow((tY - 0.62) / 0.38, 1.15));

    for (let x = 600 - halfW; x <= 600 + halfW; x += 5.5) {
      // Skip interior of the eyes & parted mouth
      let dEyeL = Math.pow((x - 532) / 31, 2) + Math.pow((y - 296) / 14, 2);
      let dEyeR = Math.pow((x - 668) / 31, 2) + Math.pow((y - 296) / 14, 2);
      if (dEyeL < 0.92 || dEyeR < 0.92) continue;

      let N = getFaceReliefNormal(x, y);
      let illum = dotLight(N.x, N.y, N.z);
      let rim = dotRim(N.x, N.y, N.z);

      // Contour direction perpendicular to normal projection
      let cAng = atan2(N.x, -N.y) + 15;
      let col = bronzeToneColor(illum);
      if (illum < 0.28 && rim > 0.62) col = PAL.copperDeep; // Warm rim bounce on right jaw

      // Primary incised form-following contour hatch
      brush.set("chisel", col, 0.65);
      brush.line(x - cos(cAng) * 3.5, y - sin(cAng) * 3.5, x + cos(cAng) * 3.5, y + sin(cAng) * 3.5);

      // Secondary cross-hatch in midtones and shadows for dense sculptural metal feel
      if (illum < 0.68) {
        let xAng = cAng + 58;
        brush.set("rotring", illum < 0.32 ? PAL.oxideDark : PAL.bronzeDark, 0.52);
        brush.line(x - cos(xAng) * 3, y - sin(xAng) * 3, x + cos(xAng) * 3, y + sin(xAng) * 3);
      }

      // Burnished brass-gold glow on high-relief facial bosses
      if (illum > 0.82) {
        brush.set("chisel", illum > 0.91 ? PAL.goldGleam : PAL.goldRubbed, 0.78);
        brush.line(x - cos(cAng) * 3, y - sin(cAng) * 3, x + cos(cAng) * 3, y + sin(cAng) * 3);
      }
    }
  }

  // 4. Forehead Expression Lines & Classic Benin Supraorbital Chased Marks (Ikharo)
  // Horizontal forehead life lines
  for (let fy of [226, 238, 250]) {
    let fCurve = [
      [505, fy + 6],
      [555, fy],
      [600, fy + 2],
      [645, fy],
      [695, fy + 6]
    ];
    brush.set("rotring", PAL.oxideDark, 0.75);
    safeSpline(fCurve, 0.45);
    brush.set("chisel", PAL.goldRubbed, 0.6);
    safeSpline(fCurve.slice(0, 4).map(p => [p[0], p[1] - 1.5]), 0.45);
  }

  // Subtle vertical Benin court brow marks (4 raised chased bars above each brow)
  for (let bx of [518, 542, 576, 624, 658, 682]) {
    brush.set("rotring", PAL.oxideDark, 0.85);
    brush.line(bx + 1.5, 232, bx + 1.5, 258);
    brush.set("chisel", bx < 600 ? PAL.goldRubbed : PAL.copperLit, 0.8);
    brush.line(bx, 232, bx, 258);
  }

  // Heavy Sculpted Brow Ridges & Glabella Furrow
  for (let bSide of [-1, 1]) {
    let bPts = [
      [600 + bSide * 10, 278],
      [600 + bSide * 48, 266],
      [600 + bSide * 88, 270],
      [600 + bSide * 112, 284]
    ];
    // Deep orbital shadow below brow
    brush.set("rotring", PAL.soot, 1.35);
    safeSpline(bPts.map(p => [p[0], p[1] + 5]), 0.45);

    // Chased eyebrow hairs (registering as both cast bronze notches and coarse brow hairs)
    for (let t = 0; t <= 1; t += 0.045) {
      let px = lerpVal(600 + bSide * 12, 600 + bSide * 108, t);
      let py = 270 - Math.sin(t * 180) * 8 + t * 8;
      let hAng = bSide < 0 ? 215 - t * 25 : -35 + t * 25;
      brush.set("rotring", PAL.soot, 0.8);
      brush.line(px, py, px + cos(hAng) * 11, py + sin(hAng) * 11);
      brush.set("chisel", bSide < 0 ? PAL.goldRubbed : PAL.copperWarm, 0.65);
      brush.line(px, py - 1, px + cos(hAng) * 9, py + sin(hAng) * 9 - 1);
    }
  }

  // 5. Hyperreal Eyes with Cast-Bronze Double Rims & Iron-Inlaid Striated Irises
  drawHyperrealEye(532, 296, -1);
  drawHyperrealEye(668, 296, 1);

  // 6. Sculptural Nose with Hand-Rubbed Molten Gold Bridge & Tip
  drawSculptedNose();

  // 7. Full Articulated Lips with Vertical Chasing & Rubbed Lower Lip Highlight
  drawSculptedMouth();

  // 8. High-Top Coiled Hair & Dense Beard/Mustache Stubble (Cast Metal + Living Hair)
  drawHairAndBeardStubble();
}

function drawSculptedEar(side) {
  let ex = 600 + side * 144;
  let ey = 328;

  // Outer helix C-curve
  let helixPts = [
    [ex - side * 8, ey - 44],
    [ex + side * 14, ey - 46],
    [ex + side * 22, ey - 18],
    [ex + side * 18, ey + 18],
    [ex + side * 6, ey + 42],
    [ex - side * 10, ey + 36]
  ];

  // Cast shadow behind ear
  brush.set("rotring", PAL.soot, 1.8);
  safeSpline(helixPts.map(p => [p[0] + 3, p[1] + 3]), 0.45);

  // Verdigris inside the recessed concha & antihelix groove
  brush.set("punch", PAL.verdMid, 1.15);
  brush.circle(ex + side * 2, ey, 11, 0.25);

  // Bronze ear helix modeling
  for (let s = -2; s <= 2; s++) {
    let col = (side < 0 && s <= 0) ? PAL.goldRubbed : (s <= 0 ? PAL.copperWarm : PAL.bronzeShadow);
    brush.set("cpencil", col, 1.2);
    safeSpline(helixPts.map(p => [p[0] + s * 1.8, p[1]]), 0.45);
  }

  // Inner antihelix & tragus
  brush.set("rotring", PAL.soot, 1.25);
  safeSpline([
    [ex - side * 2, ey - 26],
    [ex + side * 10, ey - 10],
    [ex + side * 6, ey + 18]
  ], 0.45);
  brush.set("chisel", side < 0 ? PAL.goldGleam : PAL.brassWarm, 0.85);
  safeSpline([
    [ex - side * 3, ey - 27],
    [ex + side * 9, ey - 11],
    [ex + side * 5, ey + 17]
  ], 0.45);
}

function drawHyperrealEye(cx, cy, side) {
  let innerX = cx - side * 31;
  let innerY = cy + 3;
  let outerX = cx + side * 32;
  let outerY = cy - 1;

  // Upper & Lower Eyelid Creases & Benin Double-Rimmed Bronze Lids
  let upperCrease = [
    [innerX - side * 3, innerY - 8],
    [cx - side * 8, cy - 21],
    [cx + side * 10, cy - 20],
    [outerX + side * 4, outerY - 7]
  ];
  let upperRim = [
    [innerX, innerY],
    [cx - side * 8, cy - 14],
    [cx + side * 10, cy - 13],
    [outerX, outerY]
  ];
  let lowerRim = [
    [innerX, innerY],
    [cx - side * 6, cy + 12],
    [cx + side * 10, cy + 11],
    [outerX, outerY]
  ];
  let lowerBag = [
    [innerX - side * 2, innerY + 8],
    [cx, cy + 21],
    [outerX + side * 3, outerY + 9]
  ];

  // Sclera (Eyeball) spherical shading in warm antique brass
  for (let sx = -26; sx <= 26; sx += 2.5) {
    let x = cx + sx;
    let h = 12 * (1 - (sx / 29) * (sx / 29));
    let sIllum = clamp01(0.75 - (sx / 50) - 0.15);
    brush.set("chisel", sIllum > 0.62 ? PAL.brassBright : PAL.copperWarm, 0.85);
    brush.line(x, cy - h * 0.85, x, cy + h * 0.85);
  }
  // Shadow cast by upper eyelid across top of eyeball
  brush.set("rotring", PAL.bronzeShadow, 1.2);
  safeSpline(upperRim.map(p => [p[0], p[1] + 2.5]), 0.45);

  // Large Piercing Iris (Iron-Inlaid Benin Tradition + Hyperreal Radial Fibers)
  let irisR = 12.2;
  brush.set("rotring", PAL.soot, 1.5);
  brush.circle(cx, cy - 1, irisR, 0.05);

  for (let a = 0; a < 360; a += 8) {
    let r1 = 4.2;
    let r2 = irisR * 0.94;
    let isLitSide = (a > 120 && a < 310);
    brush.set("chisel", isLitSide ? PAL.copperLit : PAL.oxideDeep, 0.65);
    brush.line(cx + cos(a) * r1, cy - 1 + sin(a) * r1, cx + cos(a) * r2, cy - 1 + sin(a) * r2);
  }

  // Concentric gold-amber iris ring
  brush.set("chisel", PAL.goldRubbed, 0.7);
  brush.arc(cx, cy - 1, irisR * 0.68, 130, 310);

  // Deep Inlaid Iron Pupil
  brush.set("rotring", PAL.soot, 2.2);
  brush.circle(cx, cy - 1, 4.2, 0.02);
  brush.circle(cx, cy - 1, 2.2, 0.02);

  // Electric Specular Catchlights on Cornea (upper-left primary + lower-right wet glint)
  brush.set("chisel", PAL.specular, 1.3);
  brush.circle(cx - 4.2, cy - 4.8, 2.2, 0.02);
  brush.circle(cx - 3.8, cy - 4.5, 1.1, 0.02);
  brush.set("chisel", PAL.goldGleam, 0.85);
  brush.arc(cx, cy - 1, irisR * 0.75, 25, 75);

  // Tear duct caruncle at inner corner
  brush.set("cpencil", PAL.coralLit, 1.1);
  brush.circle(innerX + side * 3, innerY - 0.5, 2.5, 0.1);

  // Sculpted Upper & Lower Eyelid Rims (Thick Cast Bronze Edges)
  brush.set("rotring", PAL.soot, 1.45);
  safeSpline(upperCrease, 0.45);
  safeSpline(upperRim, 0.45);
  safeSpline(lowerRim, 0.45);
  brush.set("rotring", PAL.oxideDark, 0.9);
  safeSpline(lowerBag, 0.45);

  // Burnished brass highlight on the upper lid fold and lower lid wet rim
  brush.set("cpencil", PAL.goldRubbed, 1.2);
  safeSpline(upperCrease.map(p => [p[0], p[1] + 2.5]), 0.45);
  brush.set("chisel", PAL.goldGleam, 0.9);
  safeSpline(lowerRim.slice(0, 3).map(p => [p[0], p[1] + 1.8]), 0.45);

  // Incised Benin eyelash notches along upper and lower lid rims
  for (let t = 0.12; t <= 0.88; t += 0.065) {
    let ux = lerpVal(innerX, outerX, t);
    let uy = cy - Math.sin(t * 180) * 14;
    brush.set("rotring", PAL.soot, 0.75);
    brush.line(ux, uy, ux + side * 2, uy - 5);

    let ly = cy + Math.sin(t * 180) * 12;
    brush.set("rotring", PAL.oxideDark, 0.6);
    brush.line(ux, ly + 2, ux + side * 1.5, ly + 5.5);
  }
}

function drawSculptedNose() {
  // Deep cast shadow beneath nose tip, septum & nostrils
  fillShapePoly(
    [[548, 372], [600, 384], [652, 372], [646, 392], [600, 398], [554, 392]],
    PAL.soot, 215, 0.12, 0.5, 0.4, 0.2
  );

  // Verdigris tucked into the left & right alar creases (around nostril wings)
  for (let side of [-1, 1]) {
    let alarPts = [
      [600 + side * 34, 344],
      [600 + side * 52, 358],
      [600 + side * 48, 376],
      [600 + side * 32, 380]
    ];
    brush.set("rotring", PAL.soot, 1.35);
    safeSpline(alarPts, 0.45);
    brush.set("cpencil", PAL.verdBright, 0.9);
    safeSpline(alarPts.map(p => [p[0] + side * 2, p[1]]), 0.45);
  }

  // Deep Nostril Cavities
  for (let side of [-1, 1]) {
    let nx = 600 + side * 24;
    let ny = 374;
    brush.set("rotring", PAL.soot, 2.2);
    safeSpline([[nx - side * 10, ny + 2], [nx, ny - 4], [nx + side * 12, ny + 3]], 0.4);
  }

  // Nasolabial Folds curving from nostrils around the mouth corners
  for (let side of [-1, 1]) {
    let nlPts = [
      [600 + side * 48, 366],
      [600 + side * 64, 395],
      [600 + side * 68, 428]
    ];
    brush.set("rotring", PAL.oxideDark, 1.15);
    safeSpline(nlPts, 0.45);
    brush.set("chisel", side < 0 ? PAL.goldRubbed : PAL.copperWarm, 0.8);
    safeSpline(nlPts.map(p => [p[0] + side * 2.5, p[1] - 1]), 0.45);
  }

  // Hand-Rubbed Molten Brass-Gold Polish on the Nose Bridge, Bulbous Tip & Left Alar Wing
  // (The highest relief point on the plaque, rubbed bare by touch!)
  for (let y = 284; y <= 368; y += 2.5) {
    let t = (y - 284) / 84;
    let w = t < 0.7 ? lerpVal(7, 11, t / 0.7) : lerpVal(11, 22, (t - 0.7) / 0.3);
    let xCenter = 596; // Shifted slightly toward upper-left light
    brush.set("burnish", PAL.goldRubbed, 1.1);
    brush.line(xCenter - w, y, xCenter + w * 0.75, y);
    brush.set("chisel", PAL.goldGleam, 0.95);
    brush.line(xCenter - w * 0.65, y, xCenter + w * 0.35, y);
  }

  // Specular hotspot on nose tip & left nostril wing
  brush.set("chisel", PAL.specular, 1.15);
  brush.circle(594, 358, 7.5, 0.15);
  brush.circle(593, 357, 3.5, 0.1);
  brush.set("chisel", PAL.goldGleam, 0.95);
  brush.arc(566, 364, 9, 160, 310);
}

function drawSculptedMouth() {
  // Philtrum columns between nose and Cupid's bow
  for (let side of [-1, 1]) {
    brush.set("rotring", PAL.oxideDark, 0.85);
    brush.line(600 + side * 9, 382, 600 + side * 12, 399);
    brush.set("chisel", side < 0 ? PAL.goldRubbed : PAL.copperLit, 0.75);
    brush.line(600 + side * 7, 382, 600 + side * 10, 399);
  }

  // Lip Contour Geometry
  let topBow = [
    [542, 416],
    [568, 402],
    [587, 398],
    [600, 403],
    [613, 398],
    [632, 402],
    [658, 416]
  ];
  let mouthPart = [
    [542, 416],
    [572, 415],
    [600, 418],
    [628, 415],
    [658, 416]
  ];
  let botLip = [
    [542, 416],
    [568, 434],
    [600, 439],
    [632, 434],
    [658, 416]
  ];

  // Undercut shadow beneath the full lower lip (mentolabial sulcus)
  fillShapePoly(
    [[556, 436], [600, 442], [644, 436], [634, 450], [600, 454], [566, 450]],
    PAL.soot, 210, 0.12, 0.5, 0.4, 0.2
  );

  // Upper Lip Modeling (angled downward into warm dark copper-umber)
  for (let x = 545; x <= 655; x += 2.5) {
    let t = Math.abs(x - 600) / 55;
    let yTop = lerpVal(399, 415, Math.pow(t, 1.35)) + (Math.abs(x - 600) < 10 ? 3 : 0);
    let yMid = 416;
    let isLeft = x < 598;
    brush.set("chisel", isLeft ? PAL.copperMid : PAL.bronzeDark, 0.85);
    brush.line(x, yTop, x, yMid);
  }

  // Lower Lip Modeling (swelling outward into warm copper and rubbed gold!)
  for (let x = 546; x <= 654; x += 2.5) {
    let t = (x - 600) / 54;
    let yMid = 417;
    let yBot = 439 - t * t * 22;
    let lIllum = clamp01(0.88 - (t + 0.18) * (t + 0.18) * 0.65);

    // Base lower lip tone
    brush.set("cpencil", bronzeToneColor(lIllum), 1.05);
    brush.line(x, yMid, x, yBot);

    // Fine vertical anatomical lip creases (living flesh + chased metal)
    if (Math.round(x) % 5 === 0) {
      brush.set("rotring", PAL.oxideDeep, 0.55);
      brush.line(x, yMid + 2, x + t * 3, yBot - 2);
    }

    // Bright hand-rubbed golden highlight across the swell of the lower lip
    if (lIllum > 0.78) {
      brush.set("chisel", lIllum > 0.85 ? PAL.goldGleam : PAL.goldRubbed, 0.9);
      brush.line(x, yMid + 4, x, yMid + 12);
    }
  }

  // Crisp Cupid's bow highlight & dark parted mouth line
  brush.set("chisel", PAL.goldGleam, 0.95);
  safeSpline(topBow.slice(0, 5).map(p => [p[0], p[1] - 1.5]), 0.35);

  brush.set("rotring", PAL.soot, 1.65);
  safeSpline(mouthPart, 0.35);
  brush.set("rotring", PAL.oxideDark, 1.15);
  safeSpline(botLip, 0.4);
}

function drawHairAndBeardStubble() {
  // 1. High-Top Fade Coiled Hair Crown (y = 140..215, x = 456..744)
  // Built from hundreds of tightly coiled bronze ring-punches & spiral curls
  for (let y = 142; y <= 214; y += 6.5) {
    let tY = (y - 142) / 72;
    // Rounded flat-top fade silhouette
    let halfW = tY < 0.25 ? lerpVal(98, 136, tY / 0.25) : lerpVal(136, 140, (tY - 0.25) / 0.75);
    // Arching hairline at the bottom of the hair crown
    let hairlineArch = 200 + Math.pow((Math.abs(0) / 140), 2) * 18;

    for (let x = 600 - halfW; x <= 600 + halfW; x += 6.5) {
      let u = (x - 600) / 140;
      let localHairline = 198 + u * u * 22;
      if (y > localHairline) continue;

      let nx = u * 0.78;
      let ny = (y - 185) / 65 - 0.25;
      let nz = Math.sqrt(Math.max(0.15, 1 - nx * nx - ny * ny));
      let illum = dotLight(nx, ny, nz);

      let jx = x + (noise(x * 0.1, y * 0.1) - 0.5) * 4;
      let jy = y + (noise(y * 0.1, x * 0.1) - 0.5) * 4;

      // Dark incised coil base
      brush.set("rotring", PAL.soot, 1.05);
      brush.circle(jx, jy, 3.6, 0.25);

      // Verdigris trapped in the deep hair coils on the shadow side
      if (illum < 0.30 && ((Math.round(x + y)) % 3 === 0)) {
        brush.set("chisel", PAL.verdBright, 0.65);
        brush.arc(jx, jy, 2.8, 0, 180);
      }

      // Raised copper/gold coil highlight (reads as both Benin ring-punch and coiled hair!)
      let curlCol = bronzeToneColor(illum);
      brush.set("chisel", curlCol, 0.85);
      brush.arc(jx, jy, 3.2, 175, 340);

      if (illum > 0.82) {
        brush.set("chisel", PAL.goldGleam, 0.75);
        brush.arc(jx, jy, 2.6, 200, 315);
      }
    }
  }

  // Crisp Temple Fade Transition (stippled follicles grading into forehead skin)
  for (let side of [-1, 1]) {
    for (let y = 196; y <= 282; y += 5) {
      for (let k = 0; k < 5; k++) {
        let px = 600 + side * (112 + k * 5.5) + (noise(k, y) - 0.5) * 3;
        let py = y + (noise(y, k) - 0.5) * 3;
        brush.set("rotring", PAL.oxideDark, 0.65);
        brush.line(px, py, px + side * 2.5, py + 2.5);
      }
    }
  }

  // 2. Mustache, Goatee & Full Jawline Beard Stubble (y = 365..468)
  // Registers simultaneously as chased bronze punch-work and living beard follicles!
  for (let y = 362; y <= 466; y += 4.5) {
    let tY = clamp01((y - 362) / 104);
    let jawHalfW = lerpVal(128, 72, Math.pow(tY, 1.15));

    for (let x = 600 - jawHalfW; x <= 600 + jawHalfW; x += 4.8) {
      let dx = Math.abs(x - 600);

      // Skip upper cheek inside the beard line, and skip the lips themselves
      let onMustache = (y >= 384 && y <= 415 && dx > 7 && dx < 62 && y < 397 + (dx / 62) * 18);
      let onSoulPatch = (y >= 440 && y <= 452 && dx < 18);
      let onChinAndJaw = (y >= 446) || (dx > lerpVal(64, 24, tY) && y > 362 + (1 - dx / 128) * 55);

      // Skip the mouth/lip area
      if (y >= 397 && y <= 440 && dx < 58 && !onMustache) continue;
      if (!onMustache && !onSoulPatch && !onChinAndJaw) {
        // Sparse 5-o'clock pore stubble along the cheek transition zone
        if (dx > 56 && dx < 95 && y > 370 && y < 435 && ((Math.round(x * 3 + y * 5)) % 4 === 0)) {
          brush.set("rotring", PAL.oxideDark, 0.55);
          brush.line(x, y, x + (x < 600 ? -1.5 : 1.5), y + 2);
        }
        continue;
      }

      let N = getFaceReliefNormal(x, y);
      let illum = dotLight(N.x, N.y, N.z);

      let jx = x + (noise(x * 0.15, y * 0.15) - 0.5) * 3;
      let jy = y + (noise(y * 0.15, x * 0.15) - 0.5) * 3;

      // Hair growth direction along mustache and jaw
      let hAng = 90 + ((x - 600) / 120) * 42;
      if (onMustache) hAng = 90 + ((x - 600) / 55) * 55;

      // Dark incised follicle root & short beard hair
      brush.set("rotring", PAL.soot, 0.9);
      brush.line(jx, jy, jx + cos(hAng) * 5.5, jy + sin(hAng) * 5.5);

      // Chased metallic beard hair glint
      let bCol = bronzeToneColor(illum, illum < 0.25 ? 0.55 : 0);
      brush.set("chisel", bCol, 0.72);
      brush.line(jx - 0.8, jy - 0.8, jx + cos(hAng) * 4.5 - 0.8, jy + sin(hAng) * 4.5 - 0.8);

      // Coiled curl and rubbed gold highlight on the left chin boss & mustache ridge
      if (illum > 0.78) {
        brush.set("chisel", illum > 0.88 ? PAL.goldGleam : PAL.goldRubbed, 0.78);
        brush.arc(jx, jy, 2.4, 180, 330);
      }
    }
  }
}

