function drawGuillocheLink(cx, cy, w, h, isHoriz, isLitBorder) {
  // Interlocking figure-8 bronze braid segment
  brush.set("rotring", PAL.soot, 1.35);
  if (isHoriz) {
    safeSpline([[cx - w * 0.5, cy - h * 0.4], [cx, cy + h * 0.45], [cx + w * 0.5, cy - h * 0.4]], 0.45);
    safeSpline([[cx - w * 0.5, cy + h * 0.4], [cx, cy - h * 0.45], [cx + w * 0.5, cy + h * 0.4]], 0.45);
  } else {
    safeSpline([[cx - w * 0.4, cy - h * 0.5], [cx + w * 0.45, cy], [cx - w * 0.4, cy + h * 0.5]], 0.45);
    safeSpline([[cx + w * 0.4, cy - h * 0.5], [cx - w * 0.45, cy], [cx + w * 0.4, cy + h * 0.5]], 0.45);
  }

  // Verdigris in the braid interstices
  if ((Math.round(cx + cy) % 3) === 0) {
    brush.set("cpencil", PAL.verdMid, 0.8);
    brush.circle(cx, cy, 3.2, 0.2);
  }

  // Raised bronze strand & rubbed golden crest
  let strandCol = isLitBorder ? PAL.brassBright : PAL.copperWarm;
  brush.set("cpencil", strandCol, 1.3);
  if (isHoriz) {
    safeSpline([[cx - w * 0.45, cy - h * 0.35], [cx, cy + h * 0.35], [cx + w * 0.45, cy - h * 0.35]], 0.45);
  } else {
    safeSpline([[cx - w * 0.35, cy - h * 0.45], [cx + w * 0.35, cy], [cx - w * 0.35, cy + h * 0.45]], 0.45);
  }

  if (isLitBorder) {
    brush.set("chisel", PAL.goldGleam, 0.85);
    brush.circle(cx - 2, cy - 2, 3.5, 0.15);
  }
}

function drawRaggedCastEdge(x1, y1, x2, y2, isHoriz, isLit) {
  let pts = [];
  let steps = 55;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerpVal(x1, x2, t);
    let y = lerpVal(y1, y2, t);
    let jag = (noise(x * 0.05, y * 0.05) - 0.5) * 6;
    if (isHoriz) y += jag;
    else x += jag;
    pts.push([x, y]);
  }
  brush.set("rotring", PAL.soot, 1.8);
  safeSpline(pts.map(p => [p[0] + 2, p[1] + 2]), 0.35);
  brush.set("cpencil", isLit ? PAL.goldRubbed : PAL.copperDeep, 1.45);
  safeSpline(pts, 0.35);
}

