// ============================================================================
// GEOMETRY & URBAN NOLLI-MAP DOMINO LAYOUT GENERATOR
// ============================================================================

function toWorld(cx, cy, lx, ly, ang) {
  let c = cos(ang);
  let s = sin(ang);
  return [cx + lx * c - ly * s, cy + lx * s + ly * c];
}

function toLocal(cx, cy, gx, gy, ang) {
  let dx = gx - cx;
  let dy = gy - cy;
  let c = cos(-ang);
  let s = sin(-ang);
  return [dx * c - dy * s, dx * s + dy * c];
}

function getDominoCorners(d, pad = 0) {
  let hw = d.w / 2 + pad;
  let hh = d.h / 2 + pad;
  return [
    toWorld(d.x, d.y, -hw, -hh, d.ang),
    toWorld(d.x, d.y, hw, -hh, d.ang),
    toWorld(d.x, d.y, hw, hh, d.ang),
    toWorld(d.x, d.y, -hw, hh, d.ang)
  ];
}

function polygonsOverlap(polyA, polyB) {
  let polys = [polyA, polyB];
  for (let p = 0; p < 2; p++) {
    let poly = polys[p];
    for (let i = 0; i < poly.length; i++) {
      let p1 = poly[i];
      let p2 = poly[(i + 1) % poly.length];
      let nx = -(p2[1] - p1[1]);
      let ny = p2[0] - p1[0];
      let minA = Infinity, maxA = -Infinity;
      for (let j = 0; j < polyA.length; j++) {
        let proj = polyA[j][0] * nx + polyA[j][1] * ny;
        if (proj < minA) minA = proj;
        if (proj > maxA) maxA = proj;
      }
      let minB = Infinity, maxB = -Infinity;
      for (let j = 0; j < polyB.length; j++) {
        let proj = polyB[j][0] * nx + polyB[j][1] * ny;
        if (proj < minB) minB = proj;
        if (proj > maxB) maxB = proj;
      }
      if (maxA <= minB || maxB <= minA) return false;
    }
  }
  return true;
}

function canPlaceDomino(x, y, w, h, ang, minGap = 6.5) {
  let cand = { x, y, w, h, ang };
  let corners = getDominoCorners(cand, minGap * 0.5);
  for (let i = 0; i < dominoes.length; i++) {
    let other = dominoes[i];
    let distSq = (x - other.x) * (x - other.x) + (y - other.y) * (y - other.y);
    if (distSq > 165 * 165) continue;
    let otherCorners = getDominoCorners(other, minGap * 0.5);
    if (polygonsOverlap(corners, otherCorners)) return false;
  }
  return true;
}

function inPlazaInterior(x, y) {
  let dx = (x - PLAZA_CX) / 195;
  let dy = (y - PLAZA_CY) / 155;
  if (dx * dx + dy * dy < 0.92) return true;
  if (abs(x - PLAZA_CX) < 170 && abs(y - PLAZA_CY) < 130) return true;
  return false;
}

function addDomino(x, y, w, h, ang, valA, valB, force = false) {
  if (!force && !canPlaceDomino(x, y, w, h, ang, 6.2)) return false;
  let bonePalette = [
    "#fcf5df", "#faecc7", "#f6e2b3", "#f2d89c",
    "#f9edd0", "#eed18e", "#fdf7e6", "#f4dfad"
  ];
  let patPalette = [
    "#e0a441", "#cf8824", "#e8b65a", "#c47919", "#d99632"
  ];
  dominoes.push({
    x, y, w, h, ang,
    valA: valA !== undefined ? valA : floor(random(0, 7)),
    valB: valB !== undefined ? valB : floor(random(0, 7)),
    baseCol: random(bonePalette),
    patinaCol: random(patPalette),
    seed: floor(random(10000, 99999)),
    hasFingerprint: random() < 0.58,
    fpSide: random() < 0.5 ? -1 : 1,
    fpAng: random(-35, 35)
  });
  return true;
}

