  addDomino(528, 668, TW, TH, 18, 2, 6, true);   // South-west plaza rim, crossed by coffee stain
  addDomino(762, 456, TW, TH, -19, 5, 1, true);  // North-east plaza colonnade
  addDomino(778, 566, TH, TW, 12, 4, 4, true);   // East plaza edge
  addDomino(736, 682, TW, TH, -11, 1, 0, true);  // South-east plaza edge
  addDomino(642, 712, TW, TH, 4, 3, 2, true);    // South plaza step

  // 2. CONNECTED DOMINO GAME CHAINS ALONG ARTERIAL AVENUES
  // West avenue chain running horizontally toward the plaza
  addDomino(352, 548, TW, TH, 1.5, 5, 3);
  addDomino(234, 546, TW, TH, -1, 3, 3);
  addDomino(142, 546, TH, TW, 0.5, 3, 1); // Double-three cross-tile!
  addDomino(52, 546, TW, TH, -1.5, 1, 6);

  // North avenue vertical chain descending toward the plaza
  addDomino(578, 304, TH, TW, -1.5, 6, 2);
  addDomino(578, 214, TW, TH, 1, 2, 2);   // Double-two crossbar!
  addDomino(578, 122, TH, TW, 0.5, 2, 5);
  addDomino(578, 6, TH, TW, -1, 5, 4);

  // South avenue chain descending from the plaza
  addDomino(644, 804, TH, TW, 1, 2, 4);
