  addDomino(644, 1012, TW, TH, 0.5, 1, 1); // Double-one crossbar!
  addDomino(644, 1104, TH, TW, 2, 1, 5);

  // East avenue chain exiting the plaza
  addDomino(902, 572, TW, TH, -2, 4, 6);
  addDomino(1020, 570, TW, TH, 1.5, 6, 0);
  addDomino(1138, 572, TW, TH, -1, 0, 3);

  // 3. DENSE URBAN BLOCKS (INSULAE) WITH 8PX ALLEYS & 28-36PX STREETS
  // Each block is a grid of 108x108 urban modules (2 tiles per module: either H2 or V2)
  const blocks = [
    // Northwest District
    { x0: -20, y0: -18, cols: 4, rows: 4, streetX: 28, streetY: 26, splitCol: 2, splitRow: 2 },
    // Northeast District
    { x0: 668, y0: -18, cols: 5, rows: 3, streetX: 28, streetY: 26, splitCol: 2, splitRow: 1 },
    // East-North Mid District
    { x0: 874, y0: 360, cols: 3, rows: 1, streetX: 24, streetY: 24, splitCol: 2, splitRow: 1 },
    // Southwest District
    { x0: -20, y0: 628, cols: 5, rows: 5, streetX: 28, streetY: 26, splitCol: 2, splitRow: 2 },
    // Southeast District
    { x0: 726, y0: 648, cols: 4, rows: 5, streetX: 28, streetY: 26, splitCol: 2, splitRow: 2 },
    // Mid-North Flanking Block (between NW and NE)
    { x0: 446, y0: -18, cols: 1, rows: 3, streetX: 20, streetY: 22, splitCol: 1, splitRow: 2 }
  ];

  const MOD = 108;
  const ALLEY = 8;

  for (let b = 0; b < blocks.length; b++) {
    let blk = blocks[b];
    for (let r = 0; r < blk.rows; r++) {
      for (let c = 0; c < blk.cols; c++) {
        let extraX = c >= blk.splitCol ? blk.streetX : 0;
        let extraY = r >= blk.splitRow ? blk.streetY : 0;
        let mx = blk.x0 + c * (MOD + ALLEY) + extraX + MOD / 2;
        let my = blk.y0 + r * (MOD + ALLEY) + extraY + MOD / 2;

        if (inPlazaInterior(mx, my)) continue;

        // Leave a few intentional small courtyard pockets (cortili) inside dense blocks
        if ((b === 0 && r === 1 && c === 1) ||
            (b === 1 && r === 1 && c === 2) ||
            (b === 3 && r === 2 && c === 1) ||
            (b === 4 && r === 2 && c === 2)) {
          pockets.push({ x: mx, y: my, r: 44 });
          // Place just one domino on the edge of the courtyard
          let jitter = random(-1.2, 1.2);
          addDomino(mx, my - 29, TW, TH, jitter);
          continue;
        }

        let orientHoriz = (r + c + b) % 2 === 0;
        if (random() < 0.25) orientHoriz = !orientHoriz;

        let j1 = random(-1.1, 1.1);
        let j2 = random(-1.1, 1.1);
        let ox = random(-1.2, 1.2);
        let oy = random(-1.2, 1.2);

        if (orientHoriz) {
          if (!inPlazaInterior(mx, my - 29)) {
            addDomino(mx + ox, my - 29 + oy, TW, TH, j1);
          }
          if (!inPlazaInterior(mx, my + 29)) {
            addDomino(mx - ox, my + 29 - oy, TW, TH, j2);
          }
        } else {
          if (!inPlazaInterior(mx - 29, my)) {
            addDomino(mx - 29 + ox, my + oy, TH, TW, j1);
          }
          if (!inPlazaInterior(mx + 29, my)) {
            addDomino(mx + 29 - ox, my - oy, TH, TW, j2);
          }
        }
      }
    }
  }

  // 4. FILL PERIMETER CORRIDORS & DIAGONAL BOULEVARD SEGMENTS
  const infillCandidates = [
    [352, 464, TW, TH, -1],
    [352, 632, TW, TH, 1.5],
    [458, 362, TW, TH, -2],
    [828, 362, TW, TH, 1],
    [886, 486, TW, TH, -1.5],
    [886, 656, TW, TH, 2],
    [544, 782, TH, TW, 1],
    [544, 904, TH, TW, -1],
    [544, 1026, TH, TW, 0.8],
    [544, 1146, TH, TW, -0.5],
    [736, 782, TH, TW, -1],
    [1168, 486, TH, TW, 0.5],
    [1168, 656, TH, TW, -1]
  ];
  for (let item of infillCandidates) {
    addDomino(item[0], item[1], item[2], item[3], item[4]);
  }
}

function drawPolyShape(pts, curv = 0) {
