  brush.fill("#00cc72", 145);
  brush.circle(PLAZA_CX - 15, PLAZA_CY - 10, 185, 0.3);

  brush.fill("#008248", 160);
  brush.circle(PLAZA_CX + 40, PLAZA_CY + 30, 220, 0.25);

  // Vivid emerald washes in the block courtyards (cortili)
  for (let p of pockets) {
    brush.fill("#00b866", 185);
    brush.circle(p.x, p.y, p.r + 18, 0.2);
  }
  brush.noFill();

  // Tactile woolen baize felt cross-hatching across the plaza and courtyards
  brush.hatchStyle("2H", "#00eb84", 0.55);
  brush.hatch(7, 35, { rand: 0.15 });
  brush.circle(PLAZA_CX, PLAZA_CY, 240, 0.1);
  brush.noHatch();

  brush.hatchStyle("2H", "#003d21", 0.6);
  brush.hatch(6, 125, { rand: 0.15 });
  brush.circle(PLAZA_CX, PLAZA_CY, 250, 0.1);
  brush.noHatch();

  // Baize fiber grain & stipple in the plaza
  brush.set("spray", "#00ff90", 0.65);
  for (let i = 0; i < 45; i++) {
    let a = random(360);
    let r = random(20, 235);
    brush.line(
      PLAZA_CX + cos(a) * r,
      PLAZA_CY + sin(a) * r,
      PLAZA_CX + cos(a) * (r + 18),
      PLAZA_CY + sin(a) * (r + 18)
    );
  }
  brush.set("spray", "#002915", 0.8);
  for (let i = 0; i < 45; i++) {
    let a = random(360);
    let r = random(10, 245);
    brush.line(
      PLAZA_CX + cos(a) * r,
      PLAZA_CY + sin(a) * r,
      PLAZA_CX + cos(a) * (r + 16),
      PLAZA_CY + sin(a) * (r + 16)
    );
  }
}

// ============================================================================
// 2. FLOODED SOLID BLACK INK POCHÉ (NOLLI MAP)
// ============================================================================

function getPlazaShoreline(radOffset = 0, nPts = 64) {
  let pts = [];
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * 360;
    // Irregular organic ink-flood contour around the Open Plaza
    let n1 = noise(cos(a) * 1.4 + 10, sin(a) * 1.4 + 10);
    let n2 = noise(cos(a) * 3.2 + 25, sin(a) * 3.2 + 25);
    // Street mouths where black ink tongues push slightly inward
    let streetLobe = 18 * cos(a * 4) + 12 * sin(a * 3 - 25);
    let rx = 205 + (n1 - 0.5) * 65 + (n2 - 0.5) * 28 + streetLobe + radOffset;
    let ry = 168 + (n1 - 0.5) * 55 + (n2 - 0.5) * 24 + streetLobe * 0.8 + radOffset;
    pts.push([PLAZA_CX + cos(a) * rx, PLAZA_CY + sin(a) * ry]);
  }
  return pts;
}

function drawFloodedBlackInkPoche() {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();

  let shoreOuter = getPlazaShoreline(14, 64);
  let shoreMid = getPlazaShoreline(5, 64);
  let shoreInner = getPlazaShoreline(0, 64);

  // Dark viridian-black ink bleed rim where the black ink flood meets the green baize
  drawFrameWithHole(shoreInner, "#002614", 230);
  drawFrameWithHole(shoreMid, "#03120b", 250);

  // Solid, velvety India black ink flooding all streets and alleys outside the plaza
  drawFrameWithHole(shoreOuter, "#05070a", 255);

  // Re-open small vivid emerald baize apertures inside the block courtyards (cortili)
  // so you see the green baize peering through the ink flood in the dense districts
  for (let p of pockets) {
    let pts = [];
    for (let i = 0; i < 24; i++) {
      let a = (i / 24) * 360;
      let rr = p.r * (0.65 + 0.45 * noise(p.x * 0.02 + cos(a), p.y * 0.02 + sin(a)));
      pts.push([p.x + cos(a) * rr, p.y + sin(a) * rr]);
    }
    brush.wash("#00381e", 255);
    drawPolyShape(pts, 0.25);

    let ptsInner = pts.map(pt => [
      p.x + (pt[0] - p.x) * 0.78,
      p.y + (pt[1] - p.y) * 0.78
    ]);
    brush.wash("#009c56", 245);
    drawPolyShape(ptsInner, 0.25);

    // Ink meniscus contour around the courtyard aperture
    brush.noWash();
    brush.set("rotring", "#00d474", 0.55);
    drawPolyShape(ptsInner, 0.25);
    brush.set("pen", "#020406", 1.2);
    drawPolyShape(pts, 0.25);
  }

  // Glossy black ink meniscus & pooled ink droplets around the plaza shoreline
  brush.noWash();
  brush.set("pen", "#004d29", 1.3);
  drawPolyShape(shoreInner, 0.25);

  brush.set("rotring", "#00c46c", 0.5);
  for (let i = 0; i < shoreInner.length; i += 2) {
    let p1 = shoreInner[i];
    let p2 = shoreInner[(i + 1) % shoreInner.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  brush.set("marker", "#05070a", 1.2);
  drawPolyShape(shoreMid, 0.25);

  // Isolated pooled black ink splatters/beads on the emerald plaza edge
  for (let i = 0; i < 28; i++) {
    let idx = floor(random(shoreInner.length));
    let pt = shoreInner[idx];
    let inward = random(6, 28);
    let ang = atan2(PLAZA_CY - pt[1], PLAZA_CX - pt[0]) + random(-25, 25);
    let bx = pt[0] + cos(ang) * inward;
    let by = pt[1] + sin(ang) * inward;
    let br = random(2.2, 6.5);
    brush.noStroke();
    brush.wash("#05070a", 250);
    brush.circle(bx, by, br, 0.2);
    brush.noWash();
    brush.set("rotring", "#00b865", 0.4);
    brush.arc(bx, by, br + 0.8, -45, 110);
  }

  // Subtle emerald-teal sheen in the narrow alleys so the baize under-glow is felt
  brush.set("2H", "#004f2b", 0.55);
  for (let i = 0; i < 95; i++) {
    let sx = random(30, 1170);
    let sy = random(30, 1170);
    if (inPlazaInterior(sx, sy)) continue;
    if (random() < 0.5) {
      brush.line(sx, sy, sx + random(15, 45), sy);
    } else {
      brush.line(sx, sy, sx, sy + random(15, 45));
    }
  }
}

function drawFrameWithHole(holePts, col, alphaVal) {
  let N = holePts.length;
  let q1 = Math.floor(N * 0.25);
  let q2 = Math.floor(N * 0.5);
  let q3 = Math.floor(N * 0.75);

  brush.noStroke();
  brush.wash(col, alphaVal);

  // East quadrant polygon
  let polyE = [[1240, -40], [1240, 1240]];
  for (let i = q1; i >= 0; i--) polyE.push(holePts[i]);
  for (let i = N - 1; i >= q3; i--) polyE.push(holePts[i]);
  drawPolyShape(polyE, 0);

  // South quadrant polygon
  let polyS = [[1240, 1240], [-40, 1240]];
  for (let i = q2; i >= q1; i--) polyS.push(holePts[i]);
  drawPolyShape(polyS, 0);

  // West quadrant polygon
  let polyW = [[-40, 1240], [-40, -40]];
  for (let i = q3; i >= q2; i--) polyW.push(holePts[i]);
  drawPolyShape(polyW, 0);

  // North quadrant polygon
  let polyN = [[-40, -40], [1240, -40]];
  for (let i = q3; i < N; i++) polyN.push(holePts[i]);
  polyN.push(holePts[0]);
  drawPolyShape(polyN, 0);

  brush.noWash();
}

// ============================================================================
// 3. COFFEE RING STAIN ON THE BAIZE PLAZA FLOOR
// ============================================================================

function getCoffeeRingPoint(ang, rBase, seedOff = 0) {
  let n = noise(cos(ang) * 2.1 + seedOff, sin(ang) * 2.1 + seedOff);
  let wobble = (n - 0.5) * 14 + 3.5 * sin(ang * 6 + seedOff * 40);
  let r = rBase + wobble;
  return [COFFEE_CX + cos(ang) * r, COFFEE_CY + sin(ang) * r];
}

function drawCoffeeStainOnBaize() {
  // Warm espresso-mahogany interior wash on the green baize
  brush.noStroke();
  brush.noWash();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.75, 0.65);
  brush.fill("#3d1604", 110);
  brush.circle(COFFEE_CX, COFFEE_CY, COFFEE_R, 0.22);

  brush.fill("#5e2408", 85);
  brush.circle(COFFEE_CX + 12, COFFEE_CY - 8, COFFEE_R * 0.94, 0.25);
  brush.noFill();

  // Concentric capillary coffee rings on the baize
  const ringConfigs = [
    { r: COFFEE_R - 4, col: "#240b01", brush: "marker", w: 1.6, seed: 1.1 },
    { r: COFFEE_R,     col: "#4f1d05", brush: "pen",    w: 1.8, seed: 1.1 },
    { r: COFFEE_R + 2, col: "#8c380c", brush: "rotring",w: 1.1, seed: 1.1 },
    { r: COFFEE_R - 9, col: "#6e2a08", brush: "2B",     w: 0.9, seed: 2.3 },
    // Secondary faint offset ring where the cup was shifted
    { r: COFFEE_R - 2, col: "#3b1503", brush: "2B",     w: 1.0, seed: 4.7, ox: 16, oy: -11 }
  ];

  for (let rc of ringConfigs) {
    let ox = rc.ox || 0;
    let oy = rc.oy || 0;
    let pts = [];
    for (let a = 0; a <= 360; a += 5) {
      let pt = getCoffeeRingPoint(a, rc.r, rc.seed);
      pts.push([pt[0] + ox, pt[1] + oy]);
    }
    brush.set(rc.brush, rc.col, rc.w);
    brush.spline(pts, 0.4);
  }

  // Thick caramelized coffee puddle crescent on the lower-right rim
  brush.set("marker", "#2b0e02", 2.4);
  let puddlePts = [];
  for (let a = 15; a <= 115; a += 5) {
    puddlePts.push(getCoffeeRingPoint(a, COFFEE_R - 2, 1.1));
  }
  brush.spline(puddlePts, 0.4);

  // Espresso splatter droplets around the plaza
  for (let i = 0; i < 24; i++) {
    let a = random(360);
    let dist = COFFEE_R + random(-22, 48);
    let sx = COFFEE_CX + cos(a) * dist;
    let sy = COFFEE_CY + sin(a) * dist;
    let sr = random(1.2, 4.2);
    brush.noStroke();
    brush.wash("#331203", 215);
    brush.circle(sx, sy, sr, 0.25);
    brush.noWash();
    brush.set("rotring", "#7a2f09", 0.45);
    brush.circle(sx, sy, sr, 0.2);
  }
}

// ============================================================================
// 4. EXACT CUT CARTOGRAPHIC SHADOWS
// ============================================================================

function drawDominoShadows() {
  const SX = 9.5;
  const SY = 9.5;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();

  for (let i = 0; i < dominoes.length; i++) {
    let d = dominoes[i];
    let corners = getDominoCorners(d, 0.4);
    let shadowPts = corners.map(p => [p[0] + SX, p[1] + SY]);
    brush.wash("#010203", 255);
    drawPolyShape(shadowPts, 0);
  }
  brush.noWash();
}

// ============================================================================
// 5. HYPERREAL DOMINO TILE RENDERER
// ============================================================================

function drawDominoTile(d) {
  randomSeed(d.seed);

  let hw = d.w / 2;
  let hh = d.h / 2;

  // A. Ebony / dark vulcanite backing rim (+2.4px offset on shadow side)
  let corners = getDominoCorners(d, 0);
  let ebonyPts = corners.map(p => [p[0] + 2.4, p[1] + 2.4]);
  brush.noStroke();
  brush.wash("#140f0c", 255);
  drawPolyShape(ebonyPts, 0);

  // B. Warm ivory / yellowed bone base surface
  brush.wash(d.baseCol, 255);
  drawPolyShape(corners, 0);

  // C. Aged bone yellowing & oxidized amber corner/edge patina
  let patStrip1 = [
    toWorld(d.x, d.y, -hw, hh - 9, d.ang),
    toWorld(d.x, d.y, hw, hh - 13, d.ang),
    toWorld(d.x, d.y, hw, hh, d.ang),
    toWorld(d.x, d.y, -hw, hh, d.ang)
  ];
  brush.wash(d.patinaCol, 95);
  drawPolyShape(patStrip1, 0);

  let patStrip2 = [
    toWorld(d.x, d.y, hw - 12, -hh, d.ang),
    toWorld(d.x, d.y, hw, -hh, d.ang),
    toWorld(d.x, d.y, hw, hh, d.ang),
    toWorld(d.x, d.y, hw - 8, hh, d.ang)
  ];
  brush.wash("#d69330", 85);
  drawPolyShape(patStrip2, 0);
  brush.noWash();

  // D. Longitudinal Bone Grain (Haversian canal micro-striations & pores)
  let isHoriz = d.w >= d.h;
  let grainCount = 11;
  for (let g = 0; g < grainCount; g++) {
    let frac = map(g, 0, grainCount - 1, -0.84, 0.84) + random(-0.04, 0.04);
    let col = g % 3 === 0 ? "#c9a870" : (g % 2 === 0 ? "#dec492" : "#fffcf2");
    brush.set("2H", col, random(0.35, 0.55));
    if (isHoriz) {
      let ly = frac * hh;
      let p1 = toWorld(d.x, d.y, -hw + random(3, 14), ly, d.ang);
      let p2 = toWorld(d.x, d.y, hw - random(3, 14), ly + random(-1.2, 1.2), d.ang);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    } else {
      let lx = frac * hw;
      let p1 = toWorld(d.x, d.y, lx, -hh + random(3, 14), d.ang);
      let p2 = toWorld(d.x, d.y, lx + random(-1.2, 1.2), hh - random(3, 14), d.ang);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Bone pore micro-ticks
  brush.set("rotring", "#8c6535", 0.4);
  for (let p = 0; p < 6; p++) {
    let lx = random(-hw + 6, hw - 6);
    let ly = random(-hh + 6, hh - 6);
    let gp1 = toWorld(d.x, d.y, lx, ly, d.ang);
    let gp2 = toWorld(d.x, d.y, lx + (isHoriz ? 3.5 : 0.4), ly + (isHoriz ? 0.4 : 3.5), d.ang);
    brush.line(gp1[0], gp1[1], gp2[0], gp2[1]);
  }

  // E. Warm golden-ochre dry-brush edge scuffing
  brush.set("cpencil", d.patinaCol, 0.65);
  for (let s = 0; s < 5; s++) {
    let yEdge = (s % 2 === 0 ? -1 : 1) * (hh - random(1.5, 5.5));
    let p1 = toWorld(d.x, d.y, random(-hw + 4, 0), yEdge, d.ang);
    let p2 = toWorld(d.x, d.y, random(0, hw - 4), yEdge, d.ang);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // F. Crisp Bevel Highlight (Top & Left) and Dark Chamfer (Bottom & Right)
  let cTL = corners[0], cTR = corners[1], cBR = corners[2], cBL = corners[3];
  brush.set("rotring", "#fffef7", 0.75);
  brush.line(cBL[0], cBL[1], cTL[0], cTL[1]);
  brush.line(cTL[0], cTL[1], cTR[0], cTR[1]);

  brush.set("rotring", "#3d2814", 0.65);
  brush.line(cTR[0], cTR[1], cBR[0], cBR[1]);
  brush.line(cBR[0], cBR[1], cBL[0], cBL[1]);

  // G. Chipped Edges & Worn Corners
  drawDominoChips(d, hw, hh);

  // H. Central Dividing Groove & Brass Spinner Pin
  drawDividerAndSpinner(d, hw, hh, isHoriz);

  // I. Drilled Pips Holding Dust (Vivid & Saturated Enamel Pips)
  if (isHoriz) {
    drawHalfPips(d, -hw * 0.5, 0, d.valA);
    drawHalfPips(d, hw * 0.5, 0, d.valB);
  } else {
    drawHalfPips(d, 0, -hh * 0.5, d.valA);
    drawHalfPips(d, 0, hh * 0.5, d.valB);
  }

  // J. Fingerprints of Grease
  if (d.hasFingerprint) {
    drawGreaseFingerprint(d, hw, hh, isHoriz);
  }
}

function drawDominoChips(d, hw, hh) {
  let numChips = floor(random(3, 6));
  for (let c = 0; c < numChips; c++) {
    let side = floor(random(4));
    let clen = random(4.5, 10.5);
    let cdep = random(2.4, 4.8);
    let localPts = [];
    let hiPt1, hiPt2;

    if (side === 0) {
      // Top edge chip
      let pos = random(-hw + 10, hw - 10);
      localPts = [[pos - clen / 2, -hh - 0.4], [pos + clen / 2, -hh - 0.4], [pos + random(-1.5, 1.5), -hh + cdep]];
      hiPt1 = [pos - clen / 2, -hh + cdep * 0.4];
      hiPt2 = [pos + clen / 2, -hh + cdep];
    } else if (side === 1) {
      // Bottom edge chip
      let pos = random(-hw + 10, hw - 10);
      localPts = [[pos - clen / 2, hh + 0.4], [pos + clen / 2, hh + 0.4], [pos + random(-1.5, 1.5), hh - cdep]];
      hiPt1 = [pos - clen / 2, hh - cdep];
      hiPt2 = [pos + clen / 2, hh - cdep * 0.4];
    } else if (side === 2) {
      // Left edge chip
      let pos = random(-hh + 8, hh - 8);
      localPts = [[-hw - 0.4, pos - clen / 2], [-hw - 0.4, pos + clen / 2], [-hw + cdep, pos + random(-1.5, 1.5)]];
      hiPt1 = [-hw + cdep, pos - clen / 2];
      hiPt2 = [-hw + cdep * 0.4, pos + clen / 2];
    } else {
      // Corner chip
      let sx = random() < 0.5 ? -1 : 1;
      let sy = random() < 0.5 ? -1 : 1;
      let cw = random(4.5, 7.5);
      localPts = [
        [sx * (hw + 0.4), sy * (hh + 0.4)],
        [sx * (hw - cw), sy * (hh + 0.4)],
        [sx * (hw + 0.4), sy * (hh - cw)]
      ];
      hiPt1 = [sx * (hw - cw), sy * hh];
      hiPt2 = [sx * hw, sy * (hh - cw)];
    }

    let worldChip = localPts.map(pt => toWorld(d.x, d.y, pt[0], pt[1], d.ang));
    brush.noStroke();
    brush.wash("#21150d", 250);
    drawPolyShape(worldChip, 0);
    brush.noWash();

    // Crisp pale fracture catch-light next to chip
    let wH1 = toWorld(d.x, d.y, hiPt1[0], hiPt1[1], d.ang);
    let wH2 = toWorld(d.x, d.y, hiPt2[0], hiPt2[1], d.ang);
    brush.set("rotring", "#fffdf5", 0.55);
    brush.line(wH1[0], wH1[1], wH2[0], wH2[1]);
  }
}

function drawDividerAndSpinner(d, hw, hh, isHoriz) {
  let g1, g2, h1, h2;
  if (isHoriz) {
    g1 = toWorld(d.x, d.y, 0, -hh + 3.5, d.ang);
    g2 = toWorld(d.x, d.y, 0, hh - 3.5, d.ang);
    h1 = toWorld(d.x, d.y, 1.3, -hh + 3.5, d.ang);
    h2 = toWorld(d.x, d.y, 1.3, hh - 3.5, d.ang);
  } else {
    g1 = toWorld(d.x, d.y, -hw + 3.5, 0, d.ang);
    g2 = toWorld(d.x, d.y, hw - 3.5, 0, d.ang);
    h1 = toWorld(d.x, d.y, -hw + 3.5, 1.3, d.ang);
    h2 = toWorld(d.x, d.y, hw - 3.5, 1.3, d.ang);
  }

  // Warm ochre stain along the central groove
  brush.set("cpencil", "#bd7b20", 1.1);
  brush.line(g1[0], g1[1], g2[0], g2[1]);

  // Deeply incised ebony-brown groove
  brush.set("rotring", "#1c110a", 1.15);
  brush.line(g1[0], g1[1], g2[0], g2[1]);

  // Razor-sharp bevel highlight on the sunlit side of the groove
  brush.set("rotring", "#fffef7", 0.55);
  brush.line(h1[0], h1[1], h2[0], h2[1]);

  // Gleaming metallic brass spinner pin at exact center (d.x, d.y)
  brush.noStroke();
  brush.wash("#241508", 255);
  brush.circle(d.x, d.y, 4.1, 0.05);

  brush.wash("#d9860b", 255);
  brush.circle(d.x, d.y, 3.2, 0.05);

  brush.wash("#ffd452", 255);
  brush.circle(d.x - 0.6, d.y - 0.6, 2.0, 0.05);
  brush.noWash();

  // Tiny white-gold specular glint on spinner
  brush.set("rotring", "#ffffff", 0.65);
  brush.line(d.x - 1.3, d.y - 1.3, d.x - 0.3, d.y - 0.3);
}

const PIP_LAYOUTS = {
  0: [],
  1: [[0, 0]],
  2: [[-1, -1], [1, 1]],
  3: [[-1, -1], [0, 0], [1, 1]],
  4: [[-1, -1], [1, -1], [-1, 1], [1, 1]],
  5: [[-1, -1], [1, -1], [0, 0], [-1, 1], [1, 1]],
  6: [[-1, -1], [0, -1], [1, -1], [-1, 1], [0, 1], [1, 1]]
};

// Vivid, saturated enamel pip pigments by value
const PIP_COLORS = {
  1: "#e6172b", // Vivid Vermilion Crimson
  2: "#124ce0", // Vivid Cobalt Blue
  3: "#00964b", // Vivid Emerald Green
  4: "#e06000", // Vivid Cadmium Orange-Gold
  5: "#5817d4", // Vivid Royal Indigo-Violet
  6: "#9c0b3b"  // Vivid Deep Carmine
};

function drawHalfPips(d, offX, offY, val) {
  let coords = PIP_LAYOUTS[val] || [];
  if (coords.length === 0) return;

  let isHoriz = d.w >= d.h;
  let spreadX = isHoriz ? 13.5 : 12.8;
  let spreadY = isHoriz ? 12.8 : 13.5;
  let pipColor = PIP_COLORS[val] || "#1a1412";
  let pipR = 4.65;

  for (let i = 0; i < coords.length; i++) {
    let c = coords[i];
    let lx = offX + (isHoriz ? c[0] * spreadX : c[1] * spreadX);
    let ly = offY + (isHoriz ? c[1] * spreadY : c[0] * spreadY);
    let wp = toWorld(d.x, d.y, lx, ly, d.ang);
    let px = wp[0];
    let py = wp[1];

    // 1. Deep drilled concavity shadow (top-left inner wall)
    brush.noStroke();
    brush.wash("#120b07", 255);
    brush.circle(px, py, pipR, 0.08);

    // 2. Vivid, saturated enamel pigment inside the drilled pit
    brush.wash(pipColor, 255);
    brush.circle(px + 0.55, py + 0.55, pipR - 0.55, 0.08);

    // 3. Chalky bone dust & table talc settled in the bottom-right of the drilled cavity
    brush.wash("#f0e2c0", 215);
    brush.circle(px + 1.15, py + 1.15, pipR * 0.42, 0.25);
    brush.noWash();

    brush.set("cpencil", "#fff6de", 0.55);
    brush.line(px + 0.4, py + 1.3, px + 1.9, py + 0.6);

    // 4. Crisp bottom-right rim highlight where overhead light catches the drilled edge
    brush.set("rotring", "#fffef7", 0.55);
    brush.arc(px, py, pipR + 0.25, -15, 115);
  }
}

function drawGreaseFingerprint(d, hw, hh, isHoriz) {
  let lx = isHoriz ? d.fpSide * hw * 0.42 : random(-5, 5);
  let ly = isHoriz ? random(-5, 5) : d.fpSide * hh * 0.42;
  let wp = toWorld(d.x, d.y, lx, ly, d.ang);
  let fx = wp[0];
  let fy = wp[1];

  // Concentric elliptical fingerprint ridges in warm translucent grease-amber
  for (let r = 3.2; r <= 14.5; r += 2.2) {
    let col = r % 4 < 2 ? "#c78626" : "#deb05d";
    brush.set("2H", col, 0.42);
    let pts = [];
    let aStart = random(-40, 20);
    let aEnd = aStart + random(110, 190);
    for (let a = aStart; a <= aEnd; a += 18) {
      let rad = a + d.ang + d.fpAng;
      let ex = fx + cos(a) * r * 1.25 * cos(d.fpAng) - sin(a) * r * 0.85 * sin(d.fpAng);
      let ey = fy + cos(a) * r * 1.25 * sin(d.fpAng) + sin(a) * r * 0.85 * cos(d.fpAng);
      pts.push([ex, ey]);
    }
    if (pts.length >= 3) {
      brush.spline(pts, 0.5);
    }
  }
}

// ============================================================================
// 6. COFFEE RING STAIN CROSSING ONTO ADJACENT DOMINO TILES
// ============================================================================

function findDominoAtPoint(gx, gy) {
  for (let i = 0; i < dominoes.length; i++) {
    let d = dominoes[i];
    if (abs(gx - d.x) > 80 || abs(gy - d.y) > 80) continue;
    let loc = toLocal(d.x, d.y, gx, gy, d.ang);
    if (abs(loc[0]) <= d.w / 2 - 0.8 && abs(loc[1]) <= d.h / 2 - 0.8) {
      return d;
    }
  }
  return null;
}

function drawCoffeeStainOnDominoes() {
  // Trace the coffee ring circumference and render vivid burnt-sienna / caramel-espresso
  // staining wherever the coffee ring crosses onto the ivory bone dominoes
  const stainPasses = [
    { r: COFFEE_R - 5, col: "#d97318", brush: "cpencil", w: 1.35, seed: 1.1 },
    { r: COFFEE_R - 2, col: "#9e3b06", brush: "pen",     w: 1.5,  seed: 1.1 },
    { r: COFFEE_R + 1, col: "#591c02", brush: "rotring", w: 1.05, seed: 1.1 },
    { r: COFFEE_R + 3, col: "#c7580e", brush: "2B",      w: 0.9,  seed: 1.1 },
    { r: COFFEE_R - 9, col: "#e08524", brush: "cpencil", w: 1.1,  seed: 2.3 }
  ];

  for (let sp of stainPasses) {
    let currentSeg = [];
    for (let a = 0; a <= 360; a += 2) {
      let pt = getCoffeeRingPoint(a, sp.r, sp.seed);
      let hit = findDominoAtPoint(pt[0], pt[1]);
      if (hit) {
        currentSeg.push(pt);
      } else {
        if (currentSeg.length >= 3) {
          brush.set(sp.brush, sp.col, sp.w);
          brush.spline(currentSeg, 0.4);
        }
        currentSeg = [];
      }
    }
    if (currentSeg.length >= 3) {
      brush.set(sp.brush, sp.col, sp.w);
      brush.spline(currentSeg, 0.4);
    }
  }

  // Interior amber-espresso bone tint on the portions of dominoes inside the coffee ring
  brush.set("cpencil", "#d9822b", 0.65);
  for (let r = COFFEE_R - 36; r < COFFEE_R - 6; r += 4.5) {
    for (let a = 0; a < 360; a += 4) {
      let pt = getCoffeeRingPoint(a, r, 1.1);
      if (findDominoAtPoint(pt[0], pt[1])) {
        let pt2 = getCoffeeRingPoint(a + 3, r, 1.1);
        if (findDominoAtPoint(pt2[0], pt2[1])) {
          brush.line(pt[0], pt[1], pt2[0], pt2[1]);
        }
      }
    }
  }
}

