function drawFallenCoin() {
  const cx = COIN_CX;
  const cy = COIN_CY;
  const r = COIN_R;

  // 1. Crisp, exact cartographic drop shadow
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash("#010203", 255);
  brush.circle(cx + 7.5, cy + 7.5, r, 0.03);

  // 2. Bronze-gold outer metallic rim
  brush.wash("#592b04", 255);
  brush.circle(cx + 1.2, cy + 1.2, r, 0.03);

  brush.wash("#d97706", 255);
  brush.circle(cx, cy, r, 0.03);

  // 3. Recessed dark antique patina field
  brush.wash("#853d07", 255);
  brush.circle(cx, cy, r - 4.2, 0.03);

  // 4. Inner burnished gold disk
  brush.wash("#f59e0b", 240);
  brush.circle(cx - 0.8, cy - 0.8, r - 5.2, 0.03);

  // 5. Embossed classical head profile & laurel relief in center
  let headPts = [];
  const profileOffsets = [
    [-4, -14], [4, -15], [10, -11], [12, -5], [15, -1],
    [12, 2], [13, 6], [10, 10], [4, 12], [-2, 16],
    [-10, 15], [-12, 8], [-14, 0], [-11, -9]
  ];
  for (let p of profileOffsets) {
    headPts.push([cx + p[0], cy + p[1]]);
  }
  // Relief dark shadow
  let headShadow = headPts.map(p => [p[0] + 1.6, p[1] + 1.6]);
  brush.wash("#5c2804", 255);
  drawPolyShape(headShadow, 0.3);

  // Relief bright gold body
  brush.wash("#fcd34d", 255);
  drawPolyShape(headPts, 0.3);
  brush.noWash();

  // 6. Milled / reeded edge serrations around the coin circumference
  for (let a = 0; a < 360; a += 6) {
    let r1 = r - 3.6;
    let r2 = r + 0.2;
    let col = (a > 120 && a < 310) ? "#fef08a" : "#451a03";
    brush.set("rotring", col, 0.55);
    brush.line(
      cx + cos(a) * r1, cy + sin(a) * r1,
      cx + cos(a) * r2, cy + sin(a) * r2
    );
  }

  // 7. Stamped micro-lettering ticks along the inner rim
  for (let a = 20; a < 340; a += 11) {
    if (a > 155 && a < 205) continue;
    let rm = r - 7.5;
    brush.set("rotring", "#78350f", 0.5);
    brush.line(
      cx + cos(a) * (rm - 1.5), cy + sin(a) * (rm - 1.5),
      cx + cos(a + 4) * (rm + 1.2), cy + sin(a + 4) * (rm + 1.2)
    );
    brush.set("rotring", "#fef9c3", 0.45);
    brush.line(
      cx + cos(a) * (rm - 1.8), cy + sin(a) * (rm - 1.8),
      cx + cos(a) * (rm + 1.0), cy + sin(a) * (rm + 1.0)
    );
  }

  // 8. Sharp diagonal metallic specular gleam & rim catch-lights
  brush.set("pen", "#fef08a", 0.9);
  brush.arc(cx, cy, r - 3.8, 135, 295);

  brush.set("rotring", "#ffffff", 0.75);
  brush.arc(cx, cy, r - 0.5, 145, 265);
  brush.line(cx - 11, cy - 13, cx + 7, cy + 5);
  brush.line(cx - 6, cy - 14, cx + 10, cy + 2);
}

