// ============================================================================
// GEOMETRY & SYMMETRY ENGINE
// ============================================================================

function cubicBezier(p0, p1, p2, p3, t) {
  const mt = 1 - t;
  const mt2 = mt * mt;
  const t2 = t * t;
  return [
    mt2 * mt * p0[0] + 3 * mt2 * t * p1[0] + 3 * mt * t2 * p2[0] + t2 * t * p3[0],
    mt2 * mt * p0[1] + 3 * mt2 * t * p1[1] + 3 * mt * t2 * p2[1] + t2 * t * p3[1]
  ];
}

// Segments format: [[p0, p1, p2, p3], [p1_0, p1_1, p1_2, p1_3], ...]
function sampleBeziers(segments, stepsPerSeg = 14) {
  const pts = [];
  for (let s = 0; s < segments.length; s++) {
    const seg = segments[s];
    const startStep = s === 0 ? 0 : 1;
    for (let i = startStep; i <= stepsPerSeg; i++) {
      pts.push(cubicBezier(seg[0], seg[1], seg[2], seg[3], i / stepsPerSeg));
    }
  }
  return pts;
}

// Converts (dx, y) offset from center CX into [x, y] on side (-1 = left, +1 = right)
function toAbs(dx, y, side) {
  return [CX + side * dx, y];
}

function mapPtsSide(ptsDx, side) {
  const out = new Array(ptsDx.length);
  for (let i = 0; i < ptsDx.length; i++) {
    out[i] = [CX + side * ptsDx[i][0], ptsDx[i][1]];
  }
  return out;
}

// Builds a variable-width swelling/tapering polygon from a centerline in (dx, y) coordinates
function buildSwellingRibbon(centerPts, widthFn) {
  const n = centerPts.length;
  const leftSide = [];
  const rightSide = [];

  for (let i = 0; i < n; i++) {
    const t = i / (n - 1);
    const w = widthFn(t) * 0.5;
    let tx, ty;
    if (i === 0) {
      tx = centerPts[1][0] - centerPts[0][0];
      ty = centerPts[1][1] - centerPts[0][1];
    } else if (i === n - 1) {
      tx = centerPts[n - 1][0] - centerPts[n - 2][0];
      ty = centerPts[n - 1][1] - centerPts[n - 2][1];
    } else {
      tx = centerPts[i + 1][0] - centerPts[i - 1][0];
      ty = centerPts[i + 1][1] - centerPts[i - 1][1];
    }
    const len = Math.hypot(tx, ty) || 1;
    const nx = -ty / len;
    const ny = tx / len;

    leftSide.push([centerPts[i][0] + nx * w, centerPts[i][1] + ny * w]);
    rightSide.push([centerPts[i][0] - nx * w, centerPts[i][1] - ny * w]);
  }

  return leftSide.concat(rightSide.reverse());
}

// Generates a classic Northwest Coast Ovoid contour in (dx, y) coordinates
function buildOvoidContour(cx, cy, w, h, tiltDeg = 0, bottomDish = 0.12, topArch = 0.18, steps = 64) {
  const pts = [];
  const rad = (tiltDeg * Math.PI) / 180;
  const cosA = Math.cos(rad);
  const sinA = Math.sin(rad);

  for (let i = 0; i < steps; i++) {
    const theta = (i / steps) * Math.PI * 2;
    const cosT = Math.cos(theta);
    const sinT = Math.sin(theta);

    // Superellipse exponent (~2.35 gives classic squared-off ovoid corners)
    const exp = 2.35;
    let rx = Math.sign(cosT) * Math.pow(Math.abs(cosT), 2 / exp) * (w * 0.5);
    let ry = Math.sign(sinT) * Math.pow(Math.abs(sinT), 2 / exp) * (h * 0.5);

    // Top is slightly broader and arched; bottom is slightly narrower and concave (dished)
    if (sinT < 0) {
      rx *= 1.0 - 0.06 * sinT;
      ry -= Math.pow(cosT, 2) * h * topArch * (-sinT);
    } else {
      rx *= 1.0 - 0.08 * sinT;
      ry -= (1 - Math.pow(cosT, 2)) * h * bottomDish * Math.pow(sinT, 1.5);
    }

    const rotX = rx * cosA - ry * sinA;
    const rotY = rx * sinA + ry * cosA;
    pts.push([cx + rotX, cy + rotY]);
  }
  return pts;
}

// Splits an outer/inner ring into two seamless closed polygons so hollow ovoid frames
// can be rendered cleanly on top of underlying hyperreal fur
function splitRingIntoTwoPolys(outerPts, innerPts) {
  const n = outerPts.length;
  const half = Math.floor(n / 2);

  const poly1 = [];
  for (let i = 0; i <= half; i++) poly1.push(outerPts[i]);
  for (let i = half; i >= 0; i--) poly1.push(innerPts[i]);

  const poly2 = [];
  for (let i = half; i < n; i++) poly2.push(outerPts[i]);
  poly2.push(outerPts[0]);
  poly2.push(innerPts[0]);
  for (let i = n - 1; i >= half; i--) poly2.push(innerPts[i]);

  return [poly1, poly2];
}

// Builds a 3-pointed concave Northwest Coast Trigon
function buildTrigon(p1, p2, p3, pull = 0.42, steps = 10) {
  const cx = (p1[0] + p2[0] + p3[0]) / 3;
  const cy = (p1[1] + p2[1] + p3[1]) / 3;

  function arcPts(a, b) {
    const mx = (a[0] + b[0]) * 0.5;
    const my = (a[1] + b[1]) * 0.5;
    const ctrl = [mx + (cx - mx) * pull * 2, my + (cy - my) * pull * 2];
    const seg = [];
    for (let i = 0; i < steps; i++) {
      seg.push(cubicBezier(a, ctrl, ctrl, b, i / steps));
    }
    return seg;
  }

  return [...arcPts(p1, p2), ...arcPts(p2, p3), ...arcPts(p3, p1)];
}

// Renders a polygon on both left (-1) and right (+1) sides of CX
function drawSymPoly(ptsDx, opts = {}) {
  const sides = opts.sides || [-1, 1];
  for (const side of sides) {
    const absPts = mapPtsSide(ptsDx, side);
    if ( side === -1 ) absPts.reverse();
    const p = new brush.Polygon(absPts);

    if (opts.washCol) {
      p.wash(opts.washCol, opts.washAlpha !== undefined ? opts.washAlpha : 255);
    }
    if (opts.fillCol) {
      p.fill(
        opts.fillCol,
        opts.fillAlpha !== undefined ? opts.fillAlpha : 120,
        opts.bleed !== undefined ? opts.bleed : 0.05,
        opts.texture !== undefined ? opts.texture : 0.35
      );
    }
    if (opts.hatchDist) {
      brush.hatchStyle(
        opts.hatchBrush || "rotring",
        opts.hatchCol || PALETTE.inkBlack,
        opts.hatchWeight || 0.6
      );
      p.hatch(opts.hatchDist, side === 1 ? opts.hatchAngle || 45 : 180 - (opts.hatchAngle || 45), {
        rand: opts.hatchRand || 0.04
      });
      brush.noHatch();
    }
    if (opts.strokeCol) {
      const bName = opts.strokeBrush || "rotring";
      const bWeight = opts.strokeWeight || 0.85;
      brush.set(bName, opts.strokeCol, bWeight);
      p.draw(bName, opts.strokeCol, bWeight);
    }
  }
}

// Renders a symmetric spline on both sides (with optional organic pulse jitter)
function drawSymSpline(ptsDx, brushName, col, weight, curvature = 0.5, jitter = 0) {
  for (const side of [-1, 1]) {
    const absPts = [];
    for (let i = 0; i < ptsDx.length; i++) {
      const jx = jitter > 0 ? random(-jitter, jitter) : 0;
      const jy = jitter > 0 ? random(-jitter, jitter) : 0;
      const pt = [CX + side * ptsDx[i][0] + jx, ptsDx[i][1] + jy];
      if (ptsDx[i].length > 2) pt.push(ptsDx[i][2]);
      absPts.push(pt);
    }
    brush.set(brushName, col, weight);
    brush.spline(absPts, curvature);
  }
}

// ============================================================================
// 1. PALE CEDAR-PLANK GROUND WITH VISIBLE GRAIN
// ============================================================================

function drawCedarPlankGround() {
  background(PALETTE.cedarBase);

  // Four vertical hand-adzed cedar planks meeting cleanly at x = 230, 600 (center split), 970
  const plankBounds = [
    [0, 230, PALETTE.cedarWarm, 90],
    [230, 600, PALETTE.cedarLight, 85],
    [600, 970, PALETTE.cedarWarm, 75],
    [970, 1200, PALETTE.cedarBase, 95]
  ];

  for (const [x1, x2, col, alpha] of plankBounds) {
    const p = new brush.Polygon([
      [x1, 0],
      [x2, 0],
      [x2, 1200],
      [x1, 1200]
    ]);
    p.wash(col, alpha);
    p.fill(col, 45, 0.08, 0.45);
  }

  // Horizontal subtle adze-mark bands (traditional carved Northwest Coast plank texture)
  for (let y = 35; y < 1200; y += 52) {
    const bandPts = [
      [0, y - 14],
      [1200, y - 10],
      [1200, y + 14],
      [0, y + 10]
    ];
    const bp = new brush.Polygon(bandPts);
    bp.wash(y % 104 === 35 ? PALETTE.cedarLight : PALETTE.cedarWarm, 22);
  }

  // Cathedral wood grain arches and vertical tracheid fibers per plank
  const plankCenters = [
    { xMin: 4, xMax: 226, knotX: 115, knotY: 340 },
    { xMin: 234, xMax: 596, knotX: 415, knotY: 880 },
    { xMin: 604, xMax: 966, knotX: 785, knotY: 880 },
    { xMin: 974, xMax: 1196, knotX: 1085, knotY: 340 }
  ];

  for (let pIdx = 0; pIdx < plankCenters.length; pIdx++) {
    const pl = plankCenters[pIdx];
    const numLines = 85;

    for (let i = 0; i < numLines; i++) {
      const frac = i / (numLines - 1);
      const baseX = lerp(pl.xMin, pl.xMax, frac);
      const distFromHeart = baseX - pl.knotX;

      const pts = [];
      const steps = 14;
      for (let s = 0; s <= steps; s++) {
        const y = (s / steps) * 1200;
        const dy = (y - pl.knotY) / 320;
        // Parabolic deflection around growth heart
        const archPush = distFromHeart * 0.22 * Math.exp(-dy * dy * 1.4);
        const wave = Math.sin(y * 0.018 + i * 0.35 + pIdx) * 3.5;
        const x = constrain(baseX + archPush + wave, pl.xMin, pl.xMax);
        const pressure = 0.4 + 0.6 * Math.exp(-dy * dy * 2.0);
        pts.push([x, y, pressure]);
      }

      const isDarkRing = i % 5 === 0;
      const isHighlight = i % 7 === 2;
      const col = isDarkRing
        ? PALETTE.cedarGrain2
        : isHighlight
        ? PALETTE.cedarLight
        : PALETTE.cedarGrain1;
      const bName = isDarkRing ? "cpencil" : "2H";
      const w = isDarkRing ? random(0.45, 0.75) : random(0.28, 0.5);

      brush.set(bName, col, w);
      brush.spline(pts, 0.5);
    }

    // Concentric cathedral heart-grain ellipses at knot centers
    for (let r = 1; r <= 7; r++) {
      const rx = r * 7.5;
      const ry = r * 42;
      const ringPts = [];
      for (let a = 0; a <= 16; a++) {
        const ang = (a / 16) * 360;
        const px = pl.knotX + Math.cos((ang * Math.PI) / 180) * rx;
        const py = pl.knotY + Math.sin((ang * Math.PI) / 180) * ry;
        if (px > pl.xMin && px < pl.xMax) {
          ringPts.push([px, py, 0.5 + 0.4 * Math.sin((ang * Math.PI) / 180)]);
        }
      }
      if (ringPts.length > 3) {
        brush.set("cpencil", r % 2 === 0 ? PALETTE.cedarKnot : PALETTE.cedarGrain2, 0.45);
        brush.spline(ringPts, 0.6);
      }
    }
  }

  // Plank join seams at x = 230, x = 600 (central split axis), x = 970
  for (const sx of [230, 600, 970]) {
    // Shadow bevel
    brush.set("charcoal", PALETTE.cedarSeam, sx === 600 ? 1.1 : 0.75);
    brush.line(sx, 0, sx, 1200);
    // Razor seam crack
    brush.set("rotring", "#42270d", sx === 600 ? 0.9 : 0.65);
    brush.line(sx, 0, sx, 1200);
    // Warm sunlit plank bevel edge next to seam
    brush.set("cpencil", PALETTE.cedarLight, 0.7);
    brush.line(sx + 2.5, 0, sx + 2.5, 1200);
  }
}

