// ============================================================================
// 3. HYPERREAL BEAR FUR ENCLOSURES
// ============================================================================

function drawHyperrealBearFur() {
  // ---- A. BASE UNDERCOAT WASHES FOR ALL FUR ENCLOSURES ----

  // 1. Ear Enclosure Base (dx: 165..475, y: 72..325)
  const earEnclosure = buildOvoidContour(320, 195, 290, 230, -16, 0.08, 0.22, 48);
  drawSymPoly(earEnclosure, {
    washCol: PALETTE.furPitch,
    fillCol: PALETTE.furEspresso,
    fillAlpha: 150,
    bleed: 0.05
  });

  // Inner ear concha warm cinnamon-umber shadow
  const innerEarConcha = buildOvoidContour(325, 212, 190, 145, -16, 0.1, 0.18, 40);
  drawSymPoly(innerEarConcha, {
    washCol: PALETTE.furEspresso,
    fillCol: PALETTE.furCinnamon,
    fillAlpha: 130,
    bleed: 0.08
  });

  // 2. Main Cranium, Forehead & Cheek Fur Enclosure (dx: 0..515, y: 170..835)
  const headFurPoly = [
    [0, 175],
    [130, 165],
    [275, 195],
    [435, 285],
    [505, 430],
    [515, 620],
    [495, 815],
    [390, 825],
    [200, 780],
    [0, 780]
  ];
  drawSymPoly(headFurPoly, {
    washCol: PALETTE.furPitch,
    fillCol: PALETTE.furCharcoal,
    fillAlpha: 180,
    bleed: 0.04
  });

  // Specular blue-slate sheen dome on upper forehead/brow crown
  const browSheenPoly = [
    [25, 195],
    [185, 185],
    [340, 235],
    [430, 330],
    [370, 375],
    [210, 325],
    [30, 345]
  ];
  drawSymPoly(browSheenPoly, {
    washCol: PALETTE.furBlueSheen,
    washAlpha: 170,
    fillCol: PALETTE.furSlateSheen,
    fillAlpha: 95,
    bleed: 0.12
  });

  // 3. Classic American Black Bear Tan/Cinnamon Muzzle Enclosure (dx: 0..220, y: 430..795)
  const muzzleBasePoly = [
    [0, 420],
    [95, 435],
    [195, 515],
    [225, 645],
    [215, 785],
    [0, 795]
  ];
  drawSymPoly(muzzleBasePoly, {
    washCol: PALETTE.furEspresso,
    fillCol: PALETTE.furCinnamon,
    fillAlpha: 190,
    bleed: 0.08
  });

  const muzzleBrightPoly = [
    [18, 470],
    [115, 485],
    [188, 555],
    [208, 675],
    [190, 775],
    [85, 780],
    [18, 630]
  ];
  drawSymPoly(muzzleBrightPoly, {
    washCol: PALETTE.furTanDark,
    washAlpha: 210,
    fillCol: PALETTE.furTanMid,
    fillAlpha: 150,
    bleed: 0.1
  });

  // 4. Lower Jaw & Chin Beard Enclosure (dx: 0..420, y: 1020..1138)
  const chinPoly = [
    [0, 1025],
    [230, 1025],
    [410, 1045],
    [365, 1132],
    [180, 1138],
    [0, 1138]
  ];
  drawSymPoly(chinPoly, {
    washCol: PALETTE.furPitch,
    fillCol: PALETTE.furEspresso,
    fillAlpha: 160,
    bleed: 0.05
  });

  // ---- B. LAYERED HYPERREAL FUR PELAGE (UNDERFUR, MIDCOAT, GUARD HAIRS) ----

  // Helper to render directional fur tracts with 3-point curved splines & pressure taper
  function renderFurClump(dx, y, angleDeg, len, curveDeg, brushName, col, weight, jitter = 1.6) {
    const a1 = (angleDeg * Math.PI) / 180;
    const a2 = ((angleDeg + curveDeg) * Math.PI) / 180;
    const mx = dx + Math.cos(a1) * (len * 0.52);
    const my = y + Math.sin(a1) * (len * 0.52);
    const ex = mx + Math.cos(a2) * (len * 0.48);
    const ey = my + Math.sin(a2) * (len * 0.48);

    drawSymSpline(
      [
        [dx, y, 0.3],
        [mx, my, 1.15],
        [ex, ey, 0.12]
      ],
      brushName,
      col,
      weight,
      0.45,
      jitter
    );
  }

  // 1. EAR FUR TRACTS (Radiating outward from ear concha)
  for (let i = 0; i < 155; i++) {
    const t = i / 155;
    const ang = lerp(-155, 25, (i * 0.6180339) % 1);
    const rad = lerp(22, 115, Math.sqrt(t));
    const radAngle = (ang * Math.PI) / 180;
    const dx = 322 + Math.cos(radAngle) * rad * 1.15;
    const y = 205 + Math.sin(radAngle) * rad * 0.85;

    if (dx > 175 && dx < 465 && y > 82 && y < 315) {
      const len = map(rad, 20, 115, 18, 38);
      // Dark underfur
      if (i % 2 === 0) {
        renderFurClump(dx, y, ang, len, 12, "charcoal", PALETTE.furPitch, 0.9, 1.5);
      }
      // Warm cinnamon & espresso midcoat inside pinna
      const midCol =
        rad < 72
          ? i % 3 === 0
            ? PALETTE.furTanMid
            : PALETTE.furCinnamon
          : i % 3 === 0
          ? PALETTE.furSlateSheen
          : PALETTE.furEspresso;
      renderFurClump(dx, y, ang + random(-6, 6), len * 0.9, 10, "cpencil", midCol, 0.55, 1.8);

      // Coarse silver/buff guard hairs catching rim light
      if (i % 3 === 0) {
        const gCol = rad < 68 ? PALETTE.furTanCream : PALETTE.guardSilver;
        renderFurClump(dx, y, ang, len * 1.08, 15, "rotring", gCol, 0.32, 2.2);
      }
    }
  }

  // 2. CRANIUM & SUPRA-ORBITAL BROW FUR TRACTS (Sweeping from midline up and over the brow)
  for (let i = 0; i < 260; i++) {
    const u = (i * 0.381966) % 1;
    const v = i / 260;
    const dx = lerp(14, 465, u);
    const archY = 205 + Math.pow((dx - 170) / 280, 2) * 145;
    const y = archY + lerp(-28, 125, v);

    // Avoid inside the eye ovoid center (handled in eye orbital pass)
    const distEye = Math.hypot((dx - 255) / 155, (y - 468) / 98);
    if (distEye > 0.88 && y > 175 && y < 445) {
      // Hair direction flows outward and arches over the brow
      const baseAngle = map(dx, 14, 465, -62, 28) + map(y, 180, 420, -15, 22);
      const len = random(24, 44);

      // Dense charcoal & 2B undercoat
      renderFurClump(
        dx,
        y,
        baseAngle,
        len,
        14,
        i % 2 === 0 ? "charcoal" : "2B",
        i % 3 === 0 ? PALETTE.furEspresso : PALETTE.furPitch,
        0.85,
        1.8
      );

      // Specular slate-blue sheen hairs on top of skull curve
      const inLightZone = y < archY + 52 && dx > 45 && dx < 410;
      const midCol = inLightZone
        ? i % 2 === 0
          ? PALETTE.furSlateSheen
          : PALETTE.furBlueSheen
        : PALETTE.furMahogany;
      renderFurClump(dx, y, baseAngle + 4, len * 0.88, 12, "cpencil", midCol, 0.55, 1.5);

      // Coarse silver-tipped guard hairs ("with a pulse")
      if (i % 3 === 0 || (inLightZone && i % 2 === 0)) {
        const gCol = inLightZone
          ? i % 4 === 0
            ? PALETTE.guardWhite
            : PALETTE.guardSilver
          : PALETTE.guardBuff;
        renderFurClump(dx, y, baseAngle - 3, len * 1.05, 16, "rotring", gCol, 0.34, 2.4);
      }
    }
  }

  // 3. LATERAL CHEEK RUFF & ZYGOMATIC FLANK FUR (dx: 265..505, y: 420..810)
  for (let i = 0; i < 210; i++) {
    const u = (i * 0.6180339) % 1;
    const v = i / 210;
    const dx = lerp(245, 502, u);
    const y = lerp(420, 805, v);

    const distEye = Math.hypot((dx - 255) / 160, (y - 468) / 102);
    if (distEye > 0.92) {
      // Flows outward and downward along the cheek ruff
      const baseAngle = map(y, 420, 805, 18, 68) + map(dx, 245, 502, 12, -10);
      const len = random(28, 52);

      renderFurClump(dx, y, baseAngle, len, 16, "charcoal", PALETTE.furPitch, 0.9, 1.6);
      renderFurClump(
        dx,
        y,
        baseAngle + 3,
        len * 0.9,
        14,
        "2B",
        i % 2 === 0 ? PALETTE.furEspresso : PALETTE.furBlueSheen,
        0.65,
        1.8
      );

      // Prominent coarse silver & buff guard hairs along the cheek ruff
      if (i % 2 === 0) {
        const gCol = dx > 360 ? PALETTE.guardSilver : PALETTE.guardBuff;
        renderFurClump(dx, y, baseAngle - 4, len * 1.12, 18, "rotring", gCol, 0.36, 2.5);
      }
    }
  }

  // 4. TAN / CINNAMON MUZZLE & SNOUT BRIDGE FUR (dx: 12..218, y: 390..780)
  for (let i = 0; i < 240; i++) {
    const u = (i * 0.4472136) % 1;
    const v = i / 240;
    const dx = lerp(12, 215, u);
    const y = lerp(395, 778, v);

    // Exclude the damp nose pad region (dx < 192, y > 602) and eye ovoid
    const inNose = dx < 194 && y > 602;
    const distEye = Math.hypot((dx - 255) / 155, (y - 468) / 98);

    if (!inNose && distEye > 0.94) {
      // Short, stiff velvety muzzle hairs curving downward and outward around the snout
      const baseAngle = map(dx, 12, 215, 78, 32) + map(y, 395, 778, -22, 25);
      const len = map(y, 395, 778, 22, 15);

      // Rich transition from dark brown bridge to glowing golden-tan flanks
      const tanFactor = constrain(map(dx, 18, 175, 0.15, 1.0) * map(y, 405, 680, 0.2, 1.1), 0, 1);

      let col1 = PALETTE.furEspresso;
      let col2 = PALETTE.furCinnamon;
      let col3 = PALETTE.furTanLight;

      if (tanFactor > 0.65) {
        col1 = PALETTE.furCinnamon;
        col2 = PALETTE.furTanMid;
        col3 = i % 3 === 0 ? PALETTE.furTanCream : PALETTE.furTanLight;
      } else if (tanFactor > 0.35) {
        col1 = PALETTE.furEspresso;
        col2 = PALETTE.furTanDark;
        col3 = PALETTE.furTanMid;
      }

      renderFurClump(dx, y, baseAngle, len, 10, "2B", col1, 0.7, 1.2);
      renderFurClump(dx, y, baseAngle + 3, len * 0.88, 8, "cpencil", col2, 0.52, 1.4);
      if (i % 2 === 0) {
        renderFurClump(dx, y, baseAngle - 2, len * 0.95, 10, "rotring", col3, 0.32, 1.6);
      }
    }
  }

  // 5. CHIN & LOWER JAW BEARD FUR (dx: 12..390, y: 1035..1130)
  for (let i = 0; i < 95; i++) {
    const u = (i * 0.6180339) % 1;
    const v = i / 95;
    const dx = lerp(12, 385, u);
    const y = lerp(1038, 1125, v);
    const baseAngle = map(dx, 12, 385, 86, 38);
    const len = random(18, 30);

    renderFurClump(dx, y, baseAngle, len, 8, "charcoal", PALETTE.furPitch, 0.85, 1.4);
    if (i % 2 === 0) {
      const gCol = i % 4 === 0 ? PALETTE.guardWhite : PALETTE.guardBuff;
      renderFurClump(dx, y, baseAngle, len * 0.95, 10, "rotring", gCol, 0.34, 1.8);
    }
  }
}

