      0.5,
      0.8
    );
  }

  // 3. Upper & Lower Gingiva (Crimson-Vermilion Gums wrapping tooth sockets)
  const upperGum = [
    [0, 790],
    [160, 788],
    [310, 802],
    [420, 835],
    [405, 868],
    [305, 845],
    [245, 835],
    [165, 838],
    [0, 836]
  ];
  drawSymPoly(upperGum, {
