    fillAlpha: 185,
    bleed: 0.06,
    strokeCol: PALETTE.gumShadow,
    strokeBrush: "cpencil",
    strokeWeight: 0.7
  });

  const lowerGum = [
    [0, 992],
    [155, 994],
    [245, 982],
    [325, 988],
    [412, 965],
    [425, 1005],
    [325, 1035],
    [165, 1044],
    [0, 1044]
  ];
  drawSymPoly(lowerGum, {
    washCol: PALETTE.gumMid,
    fillCol: PALETTE.gumVivid,
    fillAlpha: 185,
    bleed: 0.06,
    strokeCol: PALETTE.gumShadow,
    strokeBrush: "cpencil",
    strokeWeight: 0.7
  });

  // Gum festoons (curved gingival collars around each tooth root) and wet mucosal glints
  for (let gx = 20; gx < 395; gx += 26) {
    drawSymSpline(
      [
        [gx - 10, 812, 0.3],
        [gx, 802, 1.0],
        [gx + 10, 814, 0.3]
      ],
      "rotring",
      PALETTE.gumWet,
      0.42,
      0.5,
      0.6
    );
    drawSymSpline(
      [
        [gx - 10, 1016, 0.3],
        [gx, 1026, 1.0],
        [gx + 10, 1014, 0.3]
      ],
      "rotring",
      PALETTE.gumWet,
      0.42,
      0.5,
      0.6
    );
  }

  // ---- 4. HYPERREAL YELLOWED TEETH RENDERING ----

  // Helper to paint a hyperreal 3D tooth with root tartar, yellowed dentin, ivory crown, and wet enamel glint
  function renderTooth(crownPts, rootZonePts, highlightSpinePts, isUpper = true) {
    // Base yellowed bone wash
    drawSymPoly(crownPts, {
      washCol: PALETTE.toothYellow,
      fillCol: PALETTE.toothIvory,
      fillAlpha: 170,
      bleed: 0.03,
      strokeCol: "#4a2c0a",
      strokeBrush: "rotring",
      strokeWeight: 0.65
    });

    // Root tartar / brown-ochre staining near gumline
    if (rootZonePts) {
      drawSymPoly(rootZonePts, {
        washCol: PALETTE.toothTartar,
        washAlpha: 195,
        fillCol: PALETTE.toothRoot,
        fillAlpha: 155,
        bleed: 0.08
      });
    }

    // Longitudinal enamel developmental grooves & cylindrical shading
    if (highlightSpinePts && highlightSpinePts.length >= 3) {
      // Shadow flank along outer edge of tooth
      const shadowSpine = highlightSpinePts.map((pt) => [pt[0] + 6, pt[1], pt[2] || 0.7]);
      drawSymSpline(shadowSpine, "cpencil", PALETTE.toothTartar, 0.75, 0.45, 0.4);

      // Creamy ivory crown highlight
      drawSymSpline(highlightSpinePts, "cpencil", PALETTE.toothTip, 1.05, 0.45, 0.3);

      // Razor-crisp wet saliva/enamel specular streak
      drawSymSpline(highlightSpinePts, "rotring", "#ffffff", 0.42, 0.45, 0.2);

      // Fine brown craze line (enamel crack)
      const craze = highlightSpinePts.map((pt, idx) => [
        pt[0] - 3 + idx * 1.2,
        pt[1] + (isUpper ? -2 : 2),
        0.5
      ]);
      drawSymSpline(craze, "rotring", PALETTE.toothRoot, 0.28, 0.4, 0.5);
    }
  }

  // A. UPPER INCISORS (I1, I2, I3 from midline dx = 10 to dx = 148)
  const upperIncisors = [
    { x1: 11, x2: 50, yTop: 822, yBot: 878 },
    { x1: 53, x2: 96, yTop: 820, yBot: 882 },
    { x1: 99, x2: 148, yTop: 816, yBot: 890 }
  ];
  for (const inc of upperIncisors) {
    const xm = (inc.x1 + inc.x2) * 0.5;
    const crown = [
      [inc.x1 + 2, inc.yTop],
      [xm, inc.yTop - 5],
      [inc.x2 - 2, inc.yTop + 2],
      [inc.x2, (inc.yTop + inc.yBot) * 0.55],
      [inc.x2 - 5, inc.yBot],
      [xm, inc.yBot + 3],
      [inc.x1 + 4, inc.yBot - 2],
      [inc.x1, (inc.yTop + inc.yBot) * 0.5]
    ];
    const root = [
      [inc.x1 + 2, inc.yTop],
      [xm, inc.yTop - 5],
      [inc.x2 - 2, inc.yTop + 2],
      [inc.x2 - 1, inc.yTop + 22],
      [xm, inc.yTop + 16],
      [inc.x1 + 1, inc.yTop + 20]
    ];
    const spine = [
      [xm - 3, inc.yTop + 10, 0.4],
      [xm - 2, (inc.yTop + inc.yBot) * 0.55, 1.1],
      [xm - 1, inc.yBot - 5, 0.5]
    ];
    renderTooth(crown, root, spine, true);
  }

  // B. LOWER INCISORS (I1, I2, I3 from dx = 11 to dx = 138, with worn dentin occlusal tips)
  const lowerIncisors = [
    { x1: 11, x2: 48, yBot: 1004, yTop: 954 },
    { x1: 51, x2: 92, yBot: 1006, yTop: 950 },
    { x1: 95, x2: 138, yBot: 1008, yTop: 944 }
  ];
  for (const inc of lowerIncisors) {
    const xm = (inc.x1 + inc.x2) * 0.5;
    const crown = [
      [inc.x1 + 3, inc.yTop + 2],
      [xm, inc.yTop - 2],
      [inc.x2 - 3, inc.yTop + 3],
      [inc.x2, (inc.yTop + inc.yBot) * 0.5],
      [inc.x2 - 2, inc.yBot],
      [xm, inc.yBot + 4],
      [inc.x1 + 2, inc.yBot],
      [inc.x1, (inc.yTop + inc.yBot) * 0.5]
    ];
    const root = [
      [inc.x1 + 2, inc.yBot - 18],
      [xm, inc.yBot - 14],
      [inc.x2 - 2, inc.yBot - 18],
      [inc.x2 - 2, inc.yBot],
      [xm, inc.yBot + 4],
      [inc.x1 + 2, inc.yBot]
    ];
    const spine = [
      [xm - 2, inc.yTop + 6, 0.5],
      [xm - 2, (inc.yTop + inc.yBot) * 0.5, 1.0],
      [xm - 3, inc.yBot - 10, 0.4]
    ];
    renderTooth(crown, root, spine, false);

    // Dark worn dentin spot on incisor tip
    drawSymSpline(
      [
        [inc.x1 + 8, inc.yTop + 4, 0.6],
        [inc.x2 - 8, inc.yTop + 5, 0.6]
