// ============================================================================
// 6. HYPERREAL GLINTING AMBER EYES IN ORBITAL ENCLOSURES
// ============================================================================

function drawHyperrealEyes() {
  const eyeX = 255;
  const eyeY = 468;

  // 1. Orbital Fur & Dark Wrinkled Eyelid Socket inside the Eye Ovoid
  const orbitalSocket = buildOvoidContour(eyeX, eyeY, 276, 166, 7, 0.1, 0.16, 48);
  drawSymPoly(orbitalSocket, {
    washCol: PALETTE.furPitch,
    fillCol: PALETTE.furEspresso,
    fillAlpha: 190,
    bleed: 0.04
  });

  // Short radial velvety eyelid hairs around the eye opening
  for (let i = 0; i < 88; i++) {
    const ang = (i / 88) * 360;
    const rad = (ang * Math.PI) / 180;
    const rIn = 64;
    const rOut = 96 + 18 * Math.abs(Math.cos(rad));
    const x1 = eyeX + Math.cos(rad) * rIn * 1.12;
    const y1 = eyeY + Math.sin(rad) * rIn * 0.85;
    const x2 = eyeX + Math.cos(rad) * rOut * 1.18;
    const y2 = eyeY + Math.sin(rad) * rOut * 0.88;

    const col =
      i % 3 === 0
        ? PALETTE.furSlateSheen
        : i % 4 === 1
        ? PALETTE.guardBuff
        : PALETTE.furEspresso;
    drawSymSpline(
      [
        [x1, y1, 0.8],
        [(x1 + x2) * 0.5, (y1 + y2) * 0.5 - 3, 1.0],
        [x2, y2, 0.2]
      ],
      "cpencil",
      col,
      0.5,
      0.4,
      0.9
    );
  }

  // 2. Leathery Slate Palpebral Rim (Eyelids & Tear Ducts)
  const eyelidOpening = sampleBeziers(
    [
      [
        [eyeX - 82, eyeY + 6],
        [eyeX - 48, eyeY - 62],
        [eyeX + 38, eyeY - 66],
        [eyeX + 86, eyeY - 8]
      ],
      [
        [eyeX + 86, eyeY - 8],
        [eyeX + 42, eyeY + 58],
        [eyeX - 38, eyeY + 62],
        [eyeX - 82, eyeY + 6]
      ]
    ],
    14
  );
  drawSymPoly(eyelidOpening, {
    washCol: PALETTE.noseBase,
    fillCol: PALETTE.noseSlate,
    fillAlpha: 210,
    bleed: 0.03,
    strokeCol: PALETTE.inkBlack,
    strokeBrush: "rotring",
    strokeWeight: 0.95
  });

  // Medial caruncle (wet pink-red tear duct corner at inner eye angle)
  const tearDuct = [
    [eyeX - 78, eyeY + 5],
    [eyeX - 62, eyeY - 8],
    [eyeX - 56, eyeY + 6],
    [eyeX - 64, eyeY + 14]
  ];
  drawSymPoly(tearDuct, {
    washCol: PALETTE.gumMid,
    fillCol: PALETTE.gumWet,
    fillAlpha: 160,
    bleed: 0.05
  });

  // 3. The Eyeball Sphere: Dark Limbus & Sclera Shadow
  const irisR = 54;
  const limbusPts = [];
  for (let i = 0; i < 48; i++) {
    const a = (i / 48) * Math.PI * 2;
    limbusPts.push([eyeX + Math.cos(a) * irisR, eyeY + Math.sin(a) * irisR]);
  }
  drawSymPoly(limbusPts, {
    washCol: PALETTE.eyeLimbus,
    fillCol: PALETTE.eyeUmber,
    fillAlpha: 220,
    bleed: 0.02,
    strokeCol: PALETTE.inkBlack,
    strokeBrush: "rotring",
    strokeWeight: 1.0
  });

  // 4. Blazing Amber-Gold Iris Concentric Zones
  const irisOuterPts = [];
  const irisMidPts = [];
  const irisCollarettePts = [];
  for (let i = 0; i < 44; i++) {
    const a = (i / 44) * Math.PI * 2;
    irisOuterPts.push([eyeX + Math.cos(a) * (irisR * 0.88), eyeY + Math.sin(a) * (irisR * 0.88)]);
    irisMidPts.push([eyeX + Math.cos(a) * (irisR * 0.72), eyeY + Math.sin(a) * (irisR * 0.72)]);
    irisCollarettePts.push([
      eyeX + Math.cos(a) * (irisR * 0.52),
      eyeY + Math.sin(a) * (irisR * 0.52)
    ]);
  }
  drawSymPoly(irisOuterPts, {
    washCol: PALETTE.eyeAmberDeep,
    fillCol: PALETTE.eyeAmberVivid,
    fillAlpha: 195,
    bleed: 0.06
  });
  drawSymPoly(irisMidPts, {
    washCol: PALETTE.eyeAmberVivid,
    fillCol: PALETTE.eyeAmberGold,
    fillAlpha: 200,
    bleed: 0.08
  });
  drawSymPoly(irisCollarettePts, {
    washCol: PALETTE.eyeAmberGold,
    fillCol: PALETTE.eyeGoldBright,
    fillAlpha: 185,
    bleed: 0.08
  });

  // Lower-inner Refracted Caustic Glow (where overhead light passes through cornea onto opposite iris)
  const causticPts = [];
  for (let i = 0; i <= 18; i++) {
    const a = lerp(0.15 * Math.PI, 0.88 * Math.PI, i / 18);
    causticPts.push([eyeX + Math.cos(a) * (irisR * 0.78), eyeY + Math.sin(a) * (irisR * 0.78)]);
  }
  for (let i = 18; i >= 0; i--) {
    const a = lerp(0.15 * Math.PI, 0.88 * Math.PI, i / 18);
    causticPts.push([eyeX + Math.cos(a) * (irisR * 0.38), eyeY + Math.sin(a) * (irisR * 0.38)]);
  }
  drawSymPoly(causticPts, {
    washCol: PALETTE.eyeGoldBright,
    washAlpha: 210,
    fillCol: PALETTE.eyeCaustic,
    fillAlpha: 180,
    bleed: 0.1
  });

  // 5. Radial Iris Stroma Fibers, Trabeculae & Crypts (130 detailed fibers per eye)
  for (let i = 0; i < 130; i++) {
    const a = (i / 130) * Math.PI * 2;
    const r1 = irisR * random(0.36, 0.44);
    const r2 = irisR * random(0.84, 0.94);
    const rm = (r1 + r2) * 0.5;
    const wave = random(-0.08, 0.08);

    const p1 = [eyeX + Math.cos(a) * r1, eyeY + Math.sin(a) * r1, 0.4];
    const pm = [eyeX + Math.cos(a + wave) * rm, eyeY + Math.sin(a + wave) * rm, 1.1];
    const p2 = [eyeX + Math.cos(a) * r2, eyeY + Math.sin(a) * r2, 0.3];

    const isLowerCaustic = Math.sin(a) > 0.2;
    let fCol = PALETTE.eyeAmberGold;
    if (i % 3 === 0) fCol = PALETTE.eyeUmber;
    else if (i % 4 === 1) fCol = isLowerCaustic ? PALETTE.eyeCaustic : PALETTE.eyeGoldBright;
    else if (i % 5 === 2) fCol = PALETTE.eyeLimbus;

    drawSymSpline([p1, pm, p2], "rotring", fCol, i % 3 === 0 ? 0.38 : 0.3, 0.45, 0.3);
  }

  // 6. Deep Obsidian Pupil & Golden Pupillary Ruff
  const pupilR = 21;
  const pupilPts = [];
  const ruffPts = [];
  for (let i = 0; i < 36; i++) {
    const a = (i / 36) * Math.PI * 2;
    ruffPts.push([eyeX + Math.cos(a) * (pupilR + 2.5), eyeY + Math.sin(a) * (pupilR + 2.5)]);
    pupilPts.push([eyeX + Math.cos(a) * pupilR, eyeY + Math.sin(a) * pupilR]);
  }
  drawSymPoly(ruffPts, {
    washCol: PALETTE.eyeGoldBright,
    strokeCol: PALETTE.eyeAmberDeep,
    strokeBrush: "rotring",
    strokeWeight: 0.4
  });
  drawSymPoly(pupilPts, {
    washCol: "#040406",
    fillCol: "#000000",
    fillAlpha: 255,
    bleed: 0.01,
    strokeCol: PALETTE.eyeLimbus,
    strokeBrush: "rotring",
    strokeWeight: 0.6
  });

  // Upper Corneal Shadow cast by the heavy brow ridge
  const browShadowPts = [
    [eyeX - 52, eyeY - 12],
    [eyeX - 36, eyeY - 48],
    [eyeX + 36, eyeY - 50],
    [eyeX + 52, eyeY - 14],
    [eyeX + 18, eyeY - 26],
    [eyeX - 18, eyeY - 24]
  ];
  drawSymPoly(browShadowPts, {
    washCol: PALETTE.eyeLimbus,
    washAlpha: 135
  });

  // 7. Razor-Crisp Corneal Window Glint & Tear-Film Pinpoints
  const glintPane1 = [
    [eyeX + 10, eyeY - 36],
    [eyeX + 32, eyeY - 28],
    [eyeX + 24, eyeY - 10],
    [eyeX + 4, eyeY - 18]
  ];
  const glintPane2 = [
    [eyeX + 36, eyeY - 25],
    [eyeX + 44, eyeY - 18],
    [eyeX + 36, eyeY - 4],
    [eyeX + 28, eyeY - 8]
  ];
  drawSymPoly(glintPane1, {
    washCol: PALETTE.eyeSkyReflect,
    washAlpha: 230
  });
  drawSymPoly(glintPane1.map((p) => [p[0] - 1, p[1] + 1]), {
    washCol: "#ffffff",
    washAlpha: 255,
    strokeCol: "#ffffff",
    strokeBrush: "rotring",
    strokeWeight: 0.4
  });
  drawSymPoly(glintPane2, {
    washCol: "#ffffff",
    washAlpha: 245
  });

  // Secondary pinpoint glint on opposite side of pupil & wet tear-film line along lower lid
  const glintDot = [
    [eyeX - 20, eyeY + 14],
    [eyeX - 14, eyeY + 13],
    [eyeX - 15, eyeY + 19],
    [eyeX - 21, eyeY + 18]
  ];
  drawSymPoly(glintDot, { washCol: "#ffffff", washAlpha: 255 });

  drawSymSpline(
    [
      [eyeX - 64, eyeY + 18, 0.3],
      [eyeX - 22, eyeY + 46, 1.2],
      [eyeX + 26, eyeY + 44, 1.1],
      [eyeX + 66, eyeY + 12, 0.3]
    ],
    "rotring",
    "#ffffff",
    0.58,
    0.5,
    0.2
  );
}

