// ============================================================================
// SAFE BRUSH STATE & GEOMETRY HELPERS
// ============================================================================

function resetState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function washPoly(pts, col, alpha = 180, curv = 0.12) {
  if (!pts || pts.length < 3) return;
  resetState();
  brush.wash(col, alpha);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetState();
}

function fillGlaze(pts, col, alpha = 85, bleed = 0.16, tex = 0.52, border = 0.42, curv = 0.15, dir = "out") {
  if (!pts || pts.length < 3) return;
  resetState();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, dir);
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetState();
}

function hatchPoly(pts, bName, col, weight, dist, angle, opts = { rand: 0.04 }, curv = 0.1) {
  if (!pts || pts.length < 3) return;
  resetState();
  brush.hatchStyle(bName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetState();
}

function massPoly(pts, bName, col, opts = { precision: 0.8, strength: 0.65, gradient: 0.3, outline: false }, curv = 0.12) {
  if (!pts || pts.length < 3) return;
  resetState();
  brush.mass(bName, col, opts);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetState();
}

function strokeLine(x1, y1, x2, y2, bName, col, weight = 1) {
  resetState();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
  resetState();
}

function strokeSpline(pts, bName, col, weight = 1, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  resetState();
  brush.set(bName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curv);
  }
  resetState();
}

function ptLerp(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function evalQuad(p0, p1, p2, t) {
  let u = 1 - t;
  return [
    u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0],
    u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1]
  ];
}

function evalCubic(p0, p1, p2, p3, t) {
  let u = 1 - t;
  return [
    u * u * u * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t * t * t * p3[0],
    u * u * u * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t * t * t * p3[1]
  ];
}

function buildRibbon(fnTop, fnBot, v0, v1, tStart = 0, tEnd = 1, steps = 14, warpAmp = 0, warpFreq = 3) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let s = i / steps;
    let t = tStart + (tEnd - tStart) * s;
    let topP = fnTop(t);
    let botP = fnBot(t);
    let w = warpAmp * sin(s * 180 * warpFreq + v0 * 90);
    pts.push(ptLerp(topP, botP, constrain(v0 + w, 0, 1)));
  }
  for (let i = steps; i >= 0; i--) {
    let s = i / steps;
    let t = tStart + (tEnd - tStart) * s;
    let topP = fnTop(t);
    let botP = fnBot(t);
    let w = warpAmp * sin(s * 180 * warpFreq + v1 * 90);
    pts.push(ptLerp(topP, botP, constrain(v1 + w, 0, 1)));
  }
  return pts;
}

function ellipsePoly(cx, cy, rx, ry, rotDeg = 0, steps = 20, noiseAmt = 0) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let nr = 1 + (noiseAmt > 0 ? (noise(cx * 0.01 + cos(ang), cy * 0.01 + sin(ang)) - 0.5) * noiseAmt : 0);
    let lx = cos(ang) * rx * nr;
    let ly = sin(ang) * ry * nr;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

