  // Slight snapshot tilt: horizon runs from (0, 276) to (1200, 256)
  const skyBands = [
    { y0: -10, y1: 55, col: "#070e22", alpha: 235 },
    { y0: 40, y1: 95, col: "#0d1a38", alpha: 220 },
    { y0: 80, y1: 135, col: "#1b2448", alpha: 210 },
    { y0: 120, y1: 168, col: "#3c2342", alpha: 205 },
    { y0: 152, y1: 196, col: "#6e2733", alpha: 205 },
    { y0: 180, y1: 222, col: "#a83c24", alpha: 210 },
    { y0: 206, y1: 248, col: "#db6c1e", alpha: 215 },
    { y0: 230, y1: 278, col: "#f7a42d", alpha: 225 },
    { y0: 248, y1: 282, col: "#ffd66b", alpha: 200 }
  ];

  for (let b of skyBands) {
    let tilt0 = 10;
    let tilt1 = -10;
    washPoly([
      [-10, b.y0 + tilt0],
      [1210, b.y0 + tilt1],
      [1210, b.y1 + tilt1],
      [-10, b.y1 + tilt0]
    ], b.col, b.alpha, 0.05);
  }

  // Deep watercolor bleeds across the twilight transition
  fillGlaze([[-10, -10], [1210, -10], [1210, 110], [-10, 125]], "#08122b", 115, 0.28, 0.6, 0.35, 0.08);
  fillGlaze([[-10, 110], [1210, 95], [1210, 185], [-10, 200]], "#591d33", 95, 0.32, 0.55, 0.4, 0.1);
  fillGlaze([[-10, 175], [1210, 160], [1210, 245], [-10, 260]], "#d95b1c", 105, 0.3, 0.5, 0.35, 0.1);
  fillGlaze([[320, 215], [1210, 200], [1210, 272], [320, 282]], "#ffbe45", 110, 0.25, 0.45, 0.3, 0.1);

  // Low dusk stratocumulus cloud bands with oxblood undersides and molten gold rims
  const clouds = [
    { cx: 260, cy: 135, rx: 220, ry: 22, col: "#241730", rim: "#d95f25" },
    { cx: 680, cy: 118, rx: 290, ry: 25, col: "#1f152e", rim: "#e07026" },
    { cx: 1020, cy: 148, rx: 210, ry: 18, col: "#38192a", rim: "#f5932c" },
    { cx: 510, cy: 178, rx: 250, ry: 15, col: "#4f1d28", rim: "#ffad3b" },
    { cx: 910, cy: 192, rx: 230, ry: 14, col: "#632226", rim: "#ffc952" }
  ];

  for (let c of clouds) {
    let pts = ellipsePoly(c.cx, c.cy, c.rx, c.ry, -1.2, 16, 0.25);
    fillGlaze(pts, c.col, 95, 0.26, 0.55, 0.4, 0.25);
    strokeSpline([
      [c.cx - c.rx * 0.85, c.cy + c.ry * 0.55],
      [c.cx, c.cy + c.ry * 0.72],
      [c.cx + c.rx * 0.85, c.cy + c.ry * 0.42]
    ], "lacquer", c.rim, 1.4, 0.5);
  }

  // Fine horizontal dye-transfer sky grain
  for (let y = 15; y < 255; y += 9) {
    let t = y / 255;
    let col = t < 0.45 ? "#121f42" : (t < 0.75 ? "#8a2f2b" : "#f59d2a");
    strokeLine(0, y + 8 * (1 - t), 1200, y - 8 * t, "lacquer", col, 0.9);
  }
}

