    [-10, 800], [360, 785], [715, 775], [925, 672],
    [955, 702], [840, 860], [645, 935], [240, 965], [-10, 958]
  ];
  washPoly(carShadowCore, "#0d0205", 242, 0.14);
  washPoly([
    [-10, 815], [690, 795], [895, 688], [805, 835], [595, 905], [-10, 930]
  ], "#050103", 250, 0.12);

  // Cherry-red taillight bounce glow on the dark asphalt beneath the rear corner
