  fillGlaze(ellipsePoly(725, 875, 92, 34, -10, 16), "#c4121f", 95, 0.3, 0.45, 0.3, 0.25);
  fillGlaze(ellipsePoly(720, 868, 52, 18, -10, 14), "#ff2e38", 75, 0.25, 0.4, 0.25, 0.25);

  // --------------------------------------------------------------------------
  // IRIDESCENT OIL STAIN WITH FAINT RAINBOW SHEEN (Foreground Right)
  // --------------------------------------------------------------------------
  const oilCx = 835;
  const oilCy = 985;

  // Outer wet damp asphalt halo
  const oilOuter = ellipsePoly(oilCx, oilCy, 195, 98, -8, 24, 0.32);
  washPoly(oilOuter, "#09040b", 230, 0.22);
  fillGlaze(oilOuter, "#17091c", 95, 0.22, 0.55, 0.5, 0.22);

  // Concentric thin-film rainbow interference bands (amber -> magenta -> violet -> peacock teal -> viridian)
  const rainbowRings = [
    { rx: 168, ry: 82, ox: -6, oy: 4, col: "#8c6218", alpha: 115 },
    { rx: 148, ry: 72, ox: 4, oy: -2, col: "#b57e22", alpha: 95 },
    { rx: 132, ry: 63, ox: -4, oy: 2, col: "#7a1c4b", alpha: 115 },
    { rx: 114, ry: 54, ox: 6, oy: -3, col: "#9e2868", alpha: 95 },
    { rx: 98, ry: 46, ox: 2, oy: 2, col: "#421c5e", alpha: 120 },
    { rx: 84, ry: 39, ox: -3, oy: -1, col: "#0d6673", alpha: 125 },
    { rx: 68, ry: 31, ox: 4, oy: 2, col: "#1aa39e", alpha: 105 },
    { rx: 52, ry: 24, ox: 2, oy: -1, col: "#1d7a4c", alpha: 100 },
    { rx: 36, ry: 16, ox: 0, oy: 0, col: "#070309", alpha: 235 }
  ];

  for (let r of rainbowRings) {
    let rPts = ellipsePoly(oilCx + r.ox, oilCy + r.oy, r.rx, r.ry, -8, 22, 0.28);
    washPoly(rPts, r.col, r.alpha, 0.25);
  }

  // Delicate swirling iridescent oil filaments
  for (let i = 0; i < 18; i++) {
    let ang0 = i * 20;
    let radX = map(i % 5, 0, 4, 42, 155);
    let radY = radX * 0.46;
    let swPts = [];
    for (let s = 0; s <= 6; s++) {
      let a = ang0 + s * 22;
      let wob = sin(s * 60 + i * 35) * 6;
      swPts.push([
        oilCx + cos(a) * (radX + wob),
        oilCy + sin(a) * (radY + wob * 0.5)
      ]);
    }
    let cols = ["#22b8b0", "#c43b82", "#e09f2d", "#33855c", "#6c308c"];
    strokeSpline(swPts, "lacquer", cols[i % cols.length], 0.85, 0.6);
  }

  // Glossy dark puddle core & sky specular glint inside the oil slick
  washPoly(ellipsePoly(oilCx - 12, oilCy + 3, 44, 19, -6, 16, 0.2), "#060208", 220, 0.25);
  strokeSpline([
    [oilCx - 95, oilCy - 18],
