    [oilCx + 20, oilCy + 18],
    [oilCx + 78, oilCy + 12],
    [oilCx + 125, oilCy - 4]
  ], "precision", "#d98c36", 0.85, 0.5);

  // --------------------------------------------------------------------------
  // JAGGED ASPHALT CRACKS RUNNING PAST THE OIL STAIN
  // --------------------------------------------------------------------------
  const mainCracks = [
    // Primary fissure from bottom foreground right past the left edge of the oil stain up toward the lot
