      [520, 1205], [568, 1142], [612, 1088], [648, 1032], [662, 982],
      [698, 934], [748, 882], [795, 825], [855, 755], [912, 682], [975, 595], [1045, 510]
    ],
    // Secondary branch splitting across the lower edge of the oil stain to bottom-right
    [
      [648, 1032], [715, 1048], [788, 1068], [865, 1062], [945, 1085], [1035, 1125], [1155, 1185]
    ],
    // Branch cutting toward the car's rear tire shadow
    [
      [662, 982], [585, 965], [495, 958], [395, 972], [285, 1015], [155, 1085], [35, 1165]
    ],
    // Upper branch cutting right across the mid-ground asphalt
    [
      [795, 825], [875, 818], [965, 828], [1065, 812], [1195, 832]
    ],
    // Fine foreground fissure network
    [
      [285, 1015], [312, 1078], [305, 1145], [335, 1205]
    ],
    [
      [865, 1062], [892, 1118], [882, 1168], [908, 1205]
    ]
  ];

  for (let cr of mainCracks) {
    // Dark glossy tar-sealer halo along the crack
    strokeSpline(cr, "lacquer", "#080306", 2.2, 0.25);
    // Warm bevel highlight on the broken upper-left lip catching the dusk sky
    let bevelPts = cr.map(p => [p[0] - 2.2, p[1] - 1.8]);
    strokeSpline(bevelPts, "precision", "#523238", 0.9, 0.25);
    // Razor-sharp black crack abyss
    strokeSpline(cr, "rotring", "#020003", 1.35, 0.25);
  }

  // Asphalt aggregate pebble stippling & specular glints
  resetState();
  brush.set("spray", "#3d2228", 1.1);
  for (let i = 0; i < 28; i++) {
    let y = map(i, 0, 27, 420, 1180);
    brush.line(40, y, 1160, y - 12);
  }
  resetState();

  // Tiny warm sodium pebble glints across the foreground pavement
  for (let i = 0; i < 95; i++) {
    let px = random(40, 1180);
    let py = random(520, 1190);
    // Skip inside the deep car body region
    if (px < 880 && py < 830) continue;
    let glintCol = random() < 0.65 ? "#6e4238" : (random() < 0.5 ? "#b86b2e" : "#385e68");
    strokeLine(px, py, px + random(2, 5), py + random(-1, 1), "precision", glintCol, 0.75);
  }
}

