// Parametric curves defining the sculpted 1960s left quarter panel & tailfin
function curveFinSpine(t) {
  return evalCubic([-10, 308], [235, 316], [485, 332], [718, 354], t);
}

function curveTrunkTrough(t) {
  return evalCubic([-10, 320], [220, 344], [455, 392], [668, 442], t);
}

function curveCoveBot(t) {
  return evalCubic([-10, 394], [225, 412], [455, 434], [650, 456], t);
}

function curveSideSpear(t) {
  return evalCubic([-10, 536], [220, 556], [445, 576], [644, 594], t);
}

function curveLowerFender(t) {
  return evalCubic([-10, 742], [225, 762], [445, 782], [652, 795], t);
}

function drawTurquoiseFinAndQuarter() {
