  const hubcapPts = ellipsePoly(84, 815, 58, 72, -14, 20);
  washPoly(hubcapPts, "#0b2830", 245, 0.25);
  // Upper hubcap reflects turquoise body & amber sky; lower half reflects oxblood asphalt
  washPoly([
    [35, 785], [84, 745], [135, 775], [138, 815], [32, 818]
  ], "#188694", 210, 0.2);
  washPoly([
    [42, 795], [95, 768], [136, 792], [136, 814], [40, 814]
  ], "#f09835", 215, 0.2);
  washPoly([
    [32, 814], [138, 814], [128, 868], [78, 884], [38, 862]
