  }
  // Watercolor glaze & warm sodium reflection near the fin peak
  fillGlaze(buildRibbon(curveFinSpine, curveTrunkTrough, 0, 1, 0, 1, 14), "#149aa8", 95, 0.16, 0.45, 0.35, 0.1);
  fillGlaze(buildRibbon(curveFinSpine, curveTrunkTrough, 0, 0.75, 0.55, 1.0, 10), "#f29d38", 90, 0.2, 0.4, 0.3, 0.1);

  // --------------------------------------------------------------------------
  // C. FACET 2: OUTER FIN CONCAVE COVE (Between Fin Spine and Cove Crease)
  // Curves inward/downward, creating a deep abyssal teal & oxblood contrast band
  // --------------------------------------------------------------------------
  const coveBands = [
    { v0: 0.0, v1: 0.28, col: "#041d24", alpha: 250 },
    { v0: 0.22, v1: 0.58, col: "#07303b", alpha: 245 },
    { v0: 0.50, v1: 0.82, col: "#260b13", alpha: 225 },
    { v0: 0.74, v1: 1.0, col: "#0c525e", alpha: 235 }
  ];
  for (let b of coveBands) {
    let rib = buildRibbon(curveFinSpine, curveCoveBot, b.v0, b.v1, 0, 1, 16);
    washPoly(rib, b.col, b.alpha, 0.1);
