  fillGlaze(buildRibbon(curveFinSpine, curveCoveBot, 0.05, 0.85, 0, 1, 14), "#04222b", 115, 0.18, 0.52, 0.4, 0.1);
  hatchPoly(buildRibbon(curveFinSpine, curveCoveBot, 0.1, 0.75, 0, 1, 12), "cpencil", "#1c060c", 0.85, 6, 5, { rand: 0.04 }, 0.08);

