  strokeSpline(sodiumStreak, "lacquer", "#ffd470", 2.1, 0.4);

  // --------------------------------------------------------------------------
  // E. FACET 4: LOWER QUARTER PANEL & FENDER SKIRT (Below Side Chrome Spear)
  // Curves inward toward the dark pavement: deep peacock-teal & oxblood lacquer
  // --------------------------------------------------------------------------
  const lowerPanel = [
    [-10, 536], [220, 556], [445, 576], [644, 594],
    [655, 645], [342, 662], [335, 782], [268, 788],
    [248, 712], [145, 654], [-10, 652]
