  strokeSpline(archChrome.map(p => [p[0] - 2, p[1] - 2]), "precision", "#8cf2fa", 1.0, 0.35);

  // --------------------------------------------------------------------------
  // F. RAZOR-SHARP CHROME FIN SPINE & FULL-LENGTH SIDE CHROME SPEAR
  // --------------------------------------------------------------------------
  // 1. Fin Top Chrome Spear (from (0, 308) to Fin Peak (718, 354))
  let spinePts = [];
  for (let i = 0; i <= 18; i++) spinePts.push(curveFinSpine(i / 18));
  strokeSpline(spinePts.map(p => [p[0], p[1] + 3.5]), "rotring", "#0c0306", 2.0, 0.3);
