// ============================================================================
// 7. MASSIVE WRAP-AROUND CHROME REAR BUMPER (x: 335..938, y: 555..845)
// "sodium-amber sky reflected in the chrome. Bumper reflections are crisp but slightly warped."
// ============================================================================

// Parametric top & bottom contours of the wrap-around bumper:
// t in [0, 0.45]: Side wrap-around wing from (342, 662) to near corner (708, 638)
// t in [0.45, 1.0]: Rear main blade from near corner (708, 638) to far right corner (930, 552)
function bumperTopEdge(t) {
  if (t <= 0.45) {
    let u = t / 0.45;
    return evalQuad([342, 662], [525, 654], [708, 638], u);
  } else {
    let u = (t - 0.45) / 0.55;
    return evalQuad([708, 638], [828, 598], [930, 552], u);
  }
}

function bumperBotEdge(t) {
  if (t <= 0.45) {
    let u = t / 0.45;
    return evalQuad([334, 782], [515, 816], [698, 838], u);
  } else {
    let u = (t - 0.45) / 0.55;
    return evalQuad([698, 838], [822, 764], [922, 688], u);
  }
}

