// Synthetic Cubist Papier Collé — Trompe-l'oeil Hyperrealism
// p5.js 2.x + p5.brush (WEBGL, 1200x1200)

let fauxBoisPoly = [];
let fauxBoisCurlFlap = [];
let fauxBoisShadowPoly = [];

let newspaperPoly = [];
let newspaperCurlPoly = [];

let menuPoly = [];
let menuDogEarPoly = [];

let blueTissuePoly = [];

// Geometry & Math Helpers
function rotPt(x, y, cx, cy, deg) {
  let rad = (deg * Math.PI) / 180;
  let c = Math.cos(rad);
  let s = Math.sin(rad);
  let dx = x - cx;
  let dy = y - cy;
  return [cx + dx * c - dy * s, cy + dx * s + dy * c];
}

function transformPoly(localPts, cx, cy, deg) {
  return localPts.map((p) => rotPt(p[0] + cx, p[1] + cy, cx, cy, deg));
}

function offsetPoly(poly, dx, dy) {
  return poly.map((p) => [p[0] + dx, p[1] + dy]);
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect =
      yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

function segIntersectT(x1, y1, x2, y2, x3, y3, x4, y4) {
  let den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  if (Math.abs(den) < 1e-7) return null;
  let t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / den;
  let u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / den;
  if (t > 0.0001 && t < 0.9999 && u >= -0.0001 && u <= 1.0001) {
    return t;
  }
  return null;
}

// Clips a segment [x1,y1]->[x2,y2] to inside of `poly`, and optionally splits at `splitPoly`
function clipSegmentToPoly(x1, y1, x2, y2, poly, splitPoly = null) {
  let ts = [0, 1];
  let polys = splitPoly ? [poly, splitPoly] : [poly];
  for (let pl of polys) {
    for (let i = 0; i < pl.length; i++) {
      let a = pl[i];
      let b = pl[(i + 1) % pl.length];
      let t = segIntersectT(x1, y1, x2, y2, a[0], a[1], b[0], b[1]);
      if (t !== null) ts.push(t);
    }
  }
  ts.sort((a, b) => a - b);
  let out = [];
  for (let i = 0; i < ts.length - 1; i++) {
    let t0 = ts[i];
    let t1 = ts[i + 1];
    if (t1 - t0 < 0.002) continue;
    let tm = 0.5 * (t0 + t1);
    let mx = x1 + (x2 - x1) * tm;
    let my = y1 + (y2 - y1) * tm;
    if (pointInPoly(mx, my, poly)) {
      let ax = x1 + (x2 - x1) * t0;
      let ay = y1 + (y2 - y1) * t0;
      let bx = x1 + (x2 - x1) * t1;
      let by = y1 + (y2 - y1) * t1;
      if (Math.hypot(bx - ax, by - ay) > 1.6) {
        let inSplit = splitPoly ? pointInPoly(mx, my, splitPoly) : false;
        out.push({ ax, ay, bx, by, inSplit });
      }
    }
  }
  return out;
}

function drawClippedLine(x1, y1, x2, y2, poly, brushName, col, weight) {
  let segs = clipSegmentToPoly(x1, y1, x2, y2, poly);
  if (segs.length === 0) return;
  brush.set(brushName, col, weight);
  for (let s of segs) {
    brush.line(s.ax, s.ay, s.bx, s.by);
  }
}

function fillShapePts(pts, col, opacity, bleed = 0.08, tex = 0.4, border = 0.25) {
  let p = new brush.Polygon(pts);
  p.fill(col, opacity, bleed, tex);
  brush.noFill();
}

function washShapePts(pts, col, opacity) {
  let p = new brush.Polygon(pts);
  p.wash(col, opacity);
  brush.noWash();
}

function hatchShapePts(pts, brushName, col, weight, dist, angle, opts = { rand: 0.05 }) {
  let p = new brush.Polygon(pts);
  brush.hatchStyle(brushName, col, weight);
  p.hatch(dist, angle, opts);
  brush.noHatch();
}

function strokeShapePts(pts, brushName, col, weight, close = true) {
  brush.set(brushName, col, weight);
  for (let i = 0; i < pts.length - (close ? 0 : 1); i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    if (Math.hypot(b[0] - a[0], b[1] - a[1]) > 1.2) {
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }
}

// Draws realistic paper thickness: lit bevel on top/left edges, subtle shadow on bottom/right
function drawPaperBevelAndFibres(poly, lightCol, darkCol, tornStartIdx = -1, tornEndIdx = -1) {
  let lx = -0.707, ly = -0.707; // top-left raking light vector
  for (let i = 0; i < poly.length; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % poly.length];
    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    let len = Math.hypot(dx, dy);
    if (len < 2) continue;
    // Outward normal (assuming clockwise polygon)
    let nx = dy / len;
    let ny = -dx / len;
    let dot = nx * lx + ny * ly;
    if (dot > 0.15) {
      brush.set("2H", lightCol, 0.9);
      brush.line(a[0], a[1], b[0], b[1]);
    } else if (dot < -0.2) {
      brush.set("2H", darkCol, 0.7);
      brush.line(a[0], a[1], b[0], b[1]);
    }

    // If this edge is in the torn range, sprout delicate torn paper fibres
    if (tornStartIdx >= 0 && i >= tornStartIdx && i <= tornEndIdx) {
      let steps = Math.max(2, Math.floor(len / 4.5));
      for (let k = 0; k <= steps; k++) {
        let t = k / steps;
        let px = a[0] + dx * t;
        let py = a[1] + dy * t;
        let fLen = random(4, 13);
        let fAng = Math.atan2(ny, nx) + random(-0.55, 0.55);
        let fx = px + Math.cos(fAng) * fLen;
        let fy = py + Math.sin(fAng) * fLen;
        brush.set("fine_hair", k % 2 === 0 ? "#f4ecdc" : "#dfd3bc", random(0.45, 0.85));
        brush.line(px, py, fx, fy);
      }
    }
  }
}

// Renders a trompe-l'oeil glue wrinkle / damp-paste blister inside a polygon
function drawGlueWrinkle(x1, y1, x2, y2, bow, poly, lightCol, shadowCol) {
  let segs = 18;
  let mx = (x1 + x2) * 0.5;
  let my = (y1 + y2) * 0.5;
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = Math.hypot(dx, dy);
  let nx = -dy / len;
  let ny = dx / len;

  for (let i = 0; i < segs; i++) {
    let t0 = i / segs;
    let t1 = (i + 1) / segs;
    let env0 = Math.sin(t0 * Math.PI);
    let env1 = Math.sin(t1 * Math.PI);
    let ax = x1 + dx * t0 + nx * bow * env0;
    let ay = y1 + dy * t0 + ny * bow * env0;
    let bx = x1 + dx * t1 + nx * bow * env1;
    let by = y1 + dy * t1 + ny * bow * env1;

    if (!pointInPoly(ax, ay, poly) || !pointInPoly(bx, by, poly)) continue;

    let w = (0.35 + 0.75 * env0);
    // Shadow trough on bottom-right side of ridge
    brush.set("HB", shadowCol, w * 1.15);
    brush.line(ax + 1.8, ay + 2.0, bx + 1.8, by + 2.0);
    brush.set("2B", shadowCol, w * 0.7);
    brush.line(ax + 3.2, ay + 3.5, bx + 3.2, by + 3.5);
    // Specular paper ridge on top-left side
    brush.set("2H", lightCol, w * 1.1);
    brush.line(ax - 0.8, ay - 0.8, bx - 0.8, by - 0.8);
  }
}

// Soft layered contact + penumbra shadow for pasted scraps
function drawTrompeLoeilShadow(poly, dx, dy, layers = 4, darkCol = "#211b14", midCol = "#4f4232") {
  for (let i = layers; i >= 1; i--) {
    let frac = i / layers;
    let sPoly = offsetPoly(poly, dx * frac, dy * frac);
    let op = Math.floor(22 + (1 - frac) * 34);
    washShapePts(sPoly, i <= 2 ? darkCol : midCol, op);
  }
  let tightPoly = offsetPoly(poly, dx * 0.32, dy * 0.32);
  hatchShapePts(tightPoly, "2B", darkCol, 0.55, 5, 38, { rand: 0.08 });
}

