function draw() {
  translate(-width / 2, -height / 2);

  // 1. Aged Buff Ground & Synthetic Cubist Graphite Armature
  drawBuffGround();

  // 2. Flat Gouache Planes of Ochre, Olive, and Black
  drawAnchoredPlanes();

  // 3. Scrap 1: Faux-Bois Wallpaper (with lifting corner, glue blisters, torn fibres & tack)
  drawFauxBoisScrap();

  // 4. Scrap 2: Yellowed Newspaper ("LE JOURNAL", 4 columns, ad box, glue wrinkles, lifting corner)
  drawNewspaperScrap();

  // 5. Scrap 3: Striped Café Menu ("CAFÉ DU COMMERCE", stripes, cartouche, dog-eared corner)
  drawCafeMenuScrap();

  // 6. Scrap 4: Translucent Blue Tissue Paper (showing ghosted layers beneath + tissue crinkles)
  drawBlueTissueScrap();

  // 7. Stemmed Glass Outlined in Loose Charcoal & White Chalk
  drawCharcoalGlass();

  // 8. Hyperreal Crumpled Matchbook & Loose Half-Burnt Match
  drawCrumpledMatchbook();

  // 9. Hyperreal Half-Smoked Cigar with a Curl of Ash, Fallen Flakes & Wisp of Smoke
  drawHyperrealCigar();

  // 10. Final Trompe-l'oeil Details (Frame Vignette, Glue Droplets, Surface Grain)
  drawFinalTrompeLoeilTouches();

  noLoop();
}

// ============================================================================
// 1. BUFF GROUND & CUBIST ARMATURE
// ============================================================================
function drawBuffGround() {
  background("#ded1b8");

  // Warm tonal variations on the aged buff support board
  fillShapePts([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], "#d6c6a9", 55, 0.25, 0.65);
  fillShapePts([[80, 70], [1120, 70], [1120, 1130], [80, 1130]], "#e6dac4", 65, 0.35, 0.5);
  fillShapePts([[0, 0], [420, 0], [260, 480], [0, 520]], "#c9b694", 45, 0.4, 0.6);
  fillShapePts([[780, 680], [1200, 620], [1200, 1200], [680, 1200]], "#c4b08e", 55, 0.4, 0.6);

  // Subtle laid-paper horizontal wire lines and vertical chain lines
  brush.set("2H", "#cbbba0", 0.35);
  for (let y = 30; y < 1170; y += 14) {
    if (random() < 0.7) {
      brush.line(random(20, 90), y + random(-1, 1), random(1110, 1180), y + random(-1, 1));
    }
  }
  brush.set("2H", "#c2b092", 0.4);
  for (let x = 95; x < 1140; x += 95) {
    brush.line(x, 30, x + random(-2, 2), 1170);
  }

  // Aged foxing spots & natural board speckles
  for (let i = 0; i < 110; i++) {
    let fx = random(40, 1160);
    let fy = random(40, 1160);
    brush.set("spray", i % 3 === 0 ? "#9e8562" : "#b8a280", random(0.4, 1.1));
    brush.circle(fx, fy, random(2, 9), 0.3);
  }

  // Juan Gris / Georges Braque style Cubist graphite construction armature extending into margins
  let armatureLines = [
    [110, 290, 1090, 165],
    [165, 110, 485, 1085],
    [740, 85, 595, 1105],
    [95, 650, 1110, 465],
    [220, 985, 1060, 845],
    [320, 95, 980, 995],
    [140, 840, 870, 115]
  ];
  for (let l of armatureLines) {
    brush.set("2H", "#8f8370", 0.48);
    brush.line(l[0], l[1], l[2], l[3]);
    // Tiny registration ticks along construction lines
    let mx = (l[0] + l[2]) * 0.5;
    let my = (l[1] + l[3]) * 0.5;
    brush.set("HB", "#786d5c", 0.42);
    brush.line(mx - 6, my - 6, mx + 6, my + 6);
  }

  // Subtle compass construction arcs in upper-right and lower-left buff margins
  brush.set("2H", "#877b68", 0.45);
  brush.arc(765, 195, 115, -35, 110);
  brush.arc(765, 195, 145, -15, 75);
  brush.arc(215, 645, 95, 110, 255);
}

