// ============================================================================
// 3. SCRAP 1: FAUX-BOIS WALLPAPER
// ============================================================================
function drawFauxBoisScrap() {
  let cx = 390, cy = 520, ang = -7.5;

  // 1. Cast shadow on board & planes beneath
  drawTrompeLoeilShadow(fauxBoisPoly, 9, 11, 4, "#1c1610", "#453728");

  // Extra deep shadow under the torn bottom edge
  let bottomEdgeShadow = fauxBoisPoly.slice(5, 16).map((p) => [p[0] + 6, p[1] + 10]);
  strokeShapePts(bottomEdgeShadow, "charcoal", "#1f1912", 1.4, false);

  // 2. Warm sienna-ochre wallpaper ground
  washShapePts(fauxBoisPoly, "#c98b4e", 245);
  fillShapePts(fauxBoisPoly, "#b57438", 110, 0.04, 0.45);

  // Darker vertical graining glaze bands in local coordinates
  let bandXs = [-115, -55, 15, 80];
  for (let bx of bandXs) {
    let bPoly = transformPoly(
      [[bx - 18, -310], [bx + 18, -310], [bx + 18, 295], [bx - 18, 295]],
      cx, cy, ang
    );
    hatchShapePts(bPoly, "wood_comb", "#9e5c25", 0.55, 4.5, 82.5, { rand: 0.03 });
  }

  // 3. Exposed white-buff paper core along the hand-torn bottom edge
  let tornStripLocal = [
    [122, 276], [95, 286], [68, 275], [40, 289], [12, 281],
    [-18, 297], [-46, 287], [-75, 303], [-105, 293], [-128, 307], [-142, 296],
    [-142, 305], [-128, 316], [-105, 302], [-75, 312], [-46, 296],
    [-18, 306], [12, 290], [40, 298], [68, 284], [95, 294], [122, 285]
  ];
  let tornStripGlobal = transformPoly(tornStripLocal, cx, cy, ang);
  washShapePts(tornStripGlobal, "#efe5d0", 245);
  strokeShapePts(tornStripGlobal.slice(0, 11), "2H", "#c4a882", 0.65, false);

  // 4. Hyperreal Faux-Bois Wood-Graining (Peigne / Graining Comb + Cathedral Knots)
  let knot1 = { x: -22, y: -95, rx: 48, ry: 125 };
  let knot2 = { x: 35, y: 125, rx: 44, ry: 110 };

  for (let lx = -138; lx <= 138; lx += 3.6) {
    let isDarkGrain = Math.floor((lx + 140) / 3.6) % 3 === 0;
    let col = isDarkGrain ? "#5e2c0e" : "#7d4119";
    let wt = isDarkGrain ? 0.65 : 0.45;

    let prevPt = null;
    for (let ly = -312; ly <= 284; ly += 12) {
      // Displace x around the two heartwood knots + comb wave
      let d1x = lx - knot1.x;
      let d1y = (ly - knot1.y) * 0.42;
      let r1 = Math.hypot(d1x, d1y);
      let push1 = d1x * Math.exp(- (r1 * r1) / 1450) * 1.15;

      let d2x = lx - knot2.x;
      let d2y = (ly - knot2.y) * 0.45;
      let r2 = Math.hypot(d2x, d2y);
      let push2 = d2x * Math.exp(- (r2 * r2) / 1250) * 1.1;

      let wave = Math.sin(ly * 0.045 + lx * 0.08) * 3.2 + (noise(lx * 0.05, ly * 0.03) - 0.5) * 4.5;
      let gx = lx + push1 + push2 + wave;
      let gy = ly;

      let gp = rotPt(gx + cx, gy + cy, cx, cy, ang);
      if (prevPt) {
        drawClippedLine(prevPt[0], prevPt[1], gp[0], gp[1], fauxBoisPoly, "wood_comb", col, wt);
      }
      prevPt = gp;
    }
  }

  // Concentric cathedral heartwood loops around knot1 and knot2
  for (let k of [knot1, knot2]) {
    for (let ring = 1; ring <= 7; ring++) {
      let rx = ring * 6.2;
      let ry = ring * 18.5;
      let prev = null;
      for (let a = 0; a <= 360; a += 15) {
        let rad = (a * Math.PI) / 180;
        // Pointed cathedral arch at top & bottom of loop
        let pinch = Math.pow(Math.abs(Math.sin(rad)), 0.65) * Math.sign(Math.sin(rad));
        let lx = k.x + Math.cos(rad) * rx + Math.sin(rad * 3) * 1.2;
        let ly = k.y + pinch * ry;
        let gp = rotPt(lx + cx, ly + cy, cx, cy, ang);
        if (prev) {
          drawClippedLine(
            prev[0], prev[1], gp[0], gp[1],
            fauxBoisPoly, "wood_comb",
            ring % 2 === 0 ? "#4f2209" : "#6e3514",
            ring <= 3 ? 0.72 : 0.52
          );
        }
        prev = gp;
      }
    }
    // Dark heartwood eye at knot center
    let kp = rotPt(k.x + cx, k.y + cy, cx, cy, ang);
    brush.set("2B", "#3b1705", 0.9);
    brush.circle(kp[0], kp[1], 4.5, 0.25);
  }

  // Fine pale wood pore highlights
  for (let i = 0; i < 65; i++) {
    let lx = random(-130, 130);
    let ly = random(-295, 260);
    let p1 = rotPt(lx + cx, ly + cy, cx, cy, ang);
    let p2 = rotPt(lx + cx, ly + random(12, 28) + cy, cx, cy, ang);
    drawClippedLine(p1[0], p1[1], p2[0], p2[1], fauxBoisPoly, "2H", "#dfa66c", 0.45);
  }

  // 5. Glue Wrinkles / Damp-Paste Blisters on the Faux-Bois Scrap
  let w1a = rotPt(-110 + cx, -190 + cy, cx, cy, ang);
  let w1b = rotPt(65 + cx, -60 + cy, cx, cy, ang);
  drawGlueWrinkle(w1a[0], w1a[1], w1b[0], w1b[1], 9, fauxBoisPoly, "#ebba83", "#703913");

  let w2a = rotPt(-120 + cx, 45 + cy, cx, cy, ang);
  let w2b = rotPt(85 + cx, 195 + cy, cx, cy, ang);
  drawGlueWrinkle(w2a[0], w2a[1], w2b[0], w2b[1], -11, fauxBoisPoly, "#ebba83", "#703913");

  // 6. Paper Bevel & Torn Bottom Fibres
  drawPaperBevelAndFibres(fauxBoisPoly, "#f7e7ce", "#4a270f", 6, 15);

  // 7. Lifting / Curled Top-Right Corner Flap
  // First: deep triangular cast shadow beneath the curled flap
  let flapShadowLocal = [
    [55, -315],
    [142, -215],
    [18, -162]
  ];
  let flapShadowGlobal = transformPoly(flapShadowLocal, cx, cy, ang);
  washShapePts(flapShadowGlobal, "#26160a", 165);
  hatchShapePts(flapShadowGlobal, "2B", "#1a0e05", 0.6, 3.5, 42, { rand: 0.06 });

  // Second: unprinted buff-white underside of the curled wallpaper flap
  washShapePts(fauxBoisCurlFlap, "#eadec7", 252);
  hatchShapePts(fauxBoisCurlFlap, "2H", "#cbbba0", 0.45, 4, -35, { rand: 0.04 });
  strokeShapePts(fauxBoisCurlFlap, "HB", "#8c7a60", 0.65);
  // Bright highlight along the diagonal fold line
  brush.set("pastel_chalk", "#fbf4e6", 0.85);
  brush.line(
    fauxBoisCurlFlap[0][0], fauxBoisCurlFlap[0][1],
    fauxBoisCurlFlap[1][0], fauxBoisCurlFlap[1][1]
  );

  // 8. Trompe-l'oeil Rusty Iron Tack at Top-Left of Faux-Bois Scrap
  let tackPt = rotPt(-92 + cx, -278 + cy, cx, cy, ang);
  let tx = tackPt[0], ty = tackPt[1];
  // Sharp needle shadow cast by tack head
  brush.set("2B", "#1a120b", 1.1);
  brush.line(tx + 2, ty + 2, tx + 16, ty + 18);
  brush.set("charcoal", "#1a120b", 0.9);
  brush.circle(tx + 5, ty + 6, 6.5, 0.15);
  // Oxidized iron tack head
  let tackPoly = [];
  for (let a = 0; a < 360; a += 30) {
    let r = 6.5;
    tackPoly.push([tx + Math.cos((a * Math.PI) / 180) * r, ty + Math.sin((a * Math.PI) / 180) * r]);
  }
  washShapePts(tackPoly, "#4a2e22", 250);
  brush.set("cpencil", "#7d4f3a", 0.8);
  brush.circle(tx, ty, 6.5, 0.2);
  // Specular glint on top-left of tack head
  brush.set("pastel_chalk", "#e8cfc0", 0.75);
  brush.arc(tx, ty, 4.5, 195, 295);
}

// ============================================================================
// 4. SCRAP 2: YELLOWED NEWSPAPER ("LE JOURNAL")
// ============================================================================
function drawNewspaperScrap() {
  let cx = 660, cy = 485, ang = 13.5;

  // 1. Drop shadow onto black plane, faux-bois, and ochre plane
  drawTrompeLoeilShadow(newspaperPoly, 11, 13, 4, "#1a150f", "#473b2a");

  // Deep crescent shadow under the lifting lower-right corner
  let liftShadowLocal = [
    [195, 130],
    [222, 238],
    [95, 226],
    [145, 198]
  ];
  let liftShadowGlobal = transformPoly(liftShadowLocal, cx, cy, ang);
  washShapePts(liftShadowGlobal, "#1c160e", 185);
  hatchShapePts(liftShadowGlobal, "charcoal", "#14100a", 0.65, 3.8, 25, { rand: 0.08 });

  // 2. Acid-yellowed aged newsprint base
  washShapePts(newspaperPoly, "#dec88e", 248);
  fillShapePts(newspaperPoly, "#cfb472", 115, 0.06, 0.55);

  // Darker oxidized yellow-brown edges & damp paste stains
  let stain1 = transformPoly([[-190, -225], [-85, -225], [-110, -90], [-190, -110]], cx, cy, ang);
  fillShapePts(stain1, "#b8964c", 95, 0.25, 0.6);
  let stain2 = transformPoly([[65, -45], [185, -35], [175, 95], [50, 75]], cx, cy, ang);
  fillShapePts(stain2, "#bf9d54", 85, 0.3, 0.55);

  // Exposed pale fibrous tear strip along bottom ragged edge
  let npTornLocal = [
    [95, 217], [60, 211], [28, 223], [-8, 212], [-42, 227],
    [-78, 215], [-115, 230], [-152, 218], [-182, 231], [-196, 216],
    [-196, 225], [-182, 240], [-152, 227], [-115, 239], [-78, 224],
    [-42, 236], [-8, 221], [28, 232], [60, 220], [95, 226]
  ];
  washShapePts(transformPoly(npTornLocal, cx, cy, ang), "#f0e4c6", 240);

  // 3. Masthead ("LE JOURNAL" sliced along top cut edge)
  let inkDark = "#29241e";
  let inkMid = "#3d362d";
  let inkFaint = "#544a3d";

  // Helper to draw a line in local newspaper coords, clipped to newspaperPoly
  const npLine = (lx1, ly1, lx2, ly2, br, col, wt) => {
    let p1 = rotPt(lx1 + cx, ly1 + cy, cx, cy, ang);
    let p2 = rotPt(lx2 + cx, ly2 + cy, cx, cy, ang);
    drawClippedLine(p1[0], p1[1], p2[0], p2[1], newspaperPoly, br, col, wt);
  };

  // Masthead double rule lines & date bar
  npLine(-185, -162, 182, -162, "rotring", inkDark, 0.95);
  npLine(-185, -156, 182, -156, "rotring", inkMid, 0.55);
  npLine(-185, -136, 182, -136, "rotring", inkDark, 0.75);

  // Tiny date/price text between masthead rules
  for (let lx = -175; lx <= 165; lx += 8) {
    if (Math.abs(lx) > 25 && Math.abs(lx) < 42) continue;
    npLine(lx, -146, lx + random(3, 5.5), -146, "rotring", inkMid, 0.55);
  }

  // Bold Serif Masthead Letters "LE JOURNAL" (top clipped by -230 cut edge!)
  drawMastheadLetters(npLine, inkDark);

  // 4. Four Vertical Columns Separated by Hairline Rules
  let colBounds = [
    [-182, -96],
    [-90, -4],
    [2, 88],
    [94, 180]
  ];
  let ruleXs = [-93, -1, 91];
  for (let rx of ruleXs) {
    npLine(rx, -134, rx, 225, "rotring", inkMid, 0.5);
  }

  // Render dense trompe-l'oeil newsprint typography in each column
  for (let c = 0; c < 4; c++) {
    let xL = colBounds[c][0];
    let xR = colBounds[c][1];
    let y = -126;

    while (y < 228) {
      // Column 0 Headline at top
      if (c === 0 && y < -95) {
        drawBlockHeadline(npLine, xL + 4, y, xR - 4, 9, inkDark);
        y += 14;
        drawBlockHeadline(npLine, xL + 12, y, xR - 12, 6, inkMid);
        y += 10;
        npLine(xL + 24, y, xR - 24, y, "rotring", inkDark, 0.6);
        y += 7;
        continue;
      }

      // Column 1 Framed Display Advertisement Box ("APÉRITIF BYRRH")
      if (c === 1 && y > -45 && y < 52) {
        let adTop = -42, adBot = 48;
        // Double outer frame
        npLine(xL + 2, adTop, xR - 2, adTop, "rotring", inkDark, 0.85);
        npLine(xL + 2, adBot, xR - 2, adBot, "rotring", inkDark, 0.85);
        npLine(xL + 2, adTop, xL + 2, adBot, "rotring", inkDark, 0.85);
        npLine(xR - 2, adTop, xR - 2, adBot, "rotring", inkDark, 0.85);

        npLine(xL + 5, adTop + 3, xR - 5, adTop + 3, "rotring", inkMid, 0.45);
        npLine(xL + 5, adBot - 3, xR - 5, adBot - 3, "rotring", inkMid, 0.45);
        npLine(xL + 5, adTop + 3, xL + 5, adBot - 3, "rotring", inkMid, 0.45);
        npLine(xR - 5, adTop + 3, xR - 5, adBot - 3, "rotring", inkMid, 0.45);

        // Bold display words inside ad
        drawBlockHeadline(npLine, xL + 10, adTop + 10, xR - 10, 8, inkDark);
        drawBlockHeadline(npLine, xL + 16, adTop + 25, xR - 16, 11, inkDark);
        // Ornamental bottle/glass vignette in ad
        for (let vy = adTop + 44; vy <= adBot - 18; vy += 2.5) {
          let hw = 14 + Math.sin((vy - adTop) * 0.15) * 6;
          npLine((xL + xR) * 0.5 - hw, vy, (xL + xR) * 0.5 + hw, vy, "rotring", inkMid, 0.45);
        }
        drawBlockHeadline(npLine, xL + 12, adBot - 12, xR - 12, 5, inkDark);
        y = adBot + 8;
        continue;
      }

      // Column 2 Subheader in middle
      if (c === 2 && Math.abs(y - 12) < 4) {
        npLine(xL + 18, y, xR - 18, y, "rotring", inkMid, 0.5);
        y += 6;
        drawBlockHeadline(npLine, xL + 8, y, xR - 8, 7, inkDark);
        y += 12;
        continue;
      }

      // Standard justified newsprint line broken into words
      let isParaStart = random() < 0.16;
      let isParaEnd = !isParaStart && random() < 0.14;
      let curX = xL + (isParaStart ? 9 : 1.5);
      let maxLineX = isParaEnd ? xR - random(18, 48) : xR - 1.5;

      // Slight distortion along glue wrinkle path
      let wrinkleShift = 0;
      if (Math.abs((curX * 0.6 + y) + 45) < 22) {
        wrinkleShift = 1.6;
      }

      while (curX < maxLineX - 4) {
        let wordLen = random(5, 19);
        if (curX + wordLen > maxLineX) wordLen = maxLineX - curX;
        let wy = y + wrinkleShift;
        npLine(curX, wy, curX + wordLen, wy, "rotring", random() < 0.35 ? inkDark : inkMid, random(0.42, 0.62));
        // Tiny ascenders/descenders ticks for hyperreal print texture
        if (wordLen > 7 && random() < 0.55) {
          let tx = curX + random(1.5, wordLen - 1.5);
          npLine(tx, wy - 1.4, tx + 0.6, wy + 1.2, "rotring", inkFaint, 0.38);
        }
        curX += wordLen + random(2.5, 4.5);
      }

      y += 4.6;
    }
  }

  // 5. Glue Wrinkles / Damp-Paste Ripples across the Newsprint
  let nw1a = rotPt(-175 + cx, -95 + cy, cx, cy, ang);
  let nw1b = rotPt(95 + cx, 75 + cy, cx, cy, ang);
  drawGlueWrinkle(nw1a[0], nw1a[1], nw1b[0], nw1b[1], 11, newspaperPoly, "#f5e8c4", "#9c8043");

  let nw2a = rotPt(-65 + cx, -210 + cy, cx, cy, ang);
  let nw2b = rotPt(165 + cx, -25 + cy, cx, cy, ang);
  drawGlueWrinkle(nw2a[0], nw2a[1], nw2b[0], nw2b[1], -8, newspaperPoly, "#f5e8c4", "#9c8043");

  // 6. Curled / Lifting Bottom-Right Corner Highlights & Shading
  let curlShadePoly = transformPoly(
    [[195, 130], [145, 198], [95, 226], [82, 185], [155, 118]],
    cx, cy, ang
  );
  fillShapePts(curlShadePoly, "#f5e7c1", 110, 0.15, 0.3);
  let cEdge1 = rotPt(195 + cx, 130 + cy, cx, cy, ang);
  let cEdge2 = rotPt(145 + cx, 198 + cy, cx, cy, ang);
  let cEdge3 = rotPt(95 + cx, 226 + cy, cx, cy, ang);
  brush.set("pastel_chalk", "#fcf3dc", 0.95);
  brush.line(cEdge1[0], cEdge1[1], cEdge2[0], cEdge2[1]);
  brush.line(cEdge2[0], cEdge2[1], cEdge3[0], cEdge3[1]);

  // 7. Paper Bevel & Torn Bottom Newsprint Fibres
  drawPaperBevelAndFibres(newspaperPoly, "#faefd4", "#6e582c", 5, 13);
}

// Helper to draw bold Didot/Bodoni serif masthead "LE JOURNAL" clipped at top (-230)
function drawMastheadLetters(npLine, col) {
  let topY = -232; // extends past -230 top cut so scissors slice the letters
  let botY = -170;

  const fillStem = (x1, y1, x2, y2) => {
    for (let x = x1; x <= x2; x += 1.6) {
      npLine(x, y1, x, y2, "rotring", col, 0.85);
    }
  };

  // 'L'
  fillStem(-172, topY, -162, botY);
  npLine(-172, botY, -142, botY, "rotring", col, 1.3);
  npLine(-142, botY, -140, botY - 12, "rotring", col, 0.9);

  // 'E'
  fillStem(-130, topY, -120, botY);
  npLine(-130, -201, -104, -201, "rotring", col, 1.1);
  npLine(-104, -208, -104, -194, "rotring", col, 0.8);
  npLine(-130, botY, -98, botY, "rotring", col, 1.3);
  npLine(-98, botY, -96, botY - 12, "rotring", col, 0.9);

  // 'J'
  fillStem(-58, topY, -48, botY - 10);
  npLine(-74, botY - 12, -66, botY, "rotring", col, 1.2);
  npLine(-66, botY, -50, botY, "rotring", col, 1.2);
  npLine(-50, botY, -48, botY - 10, "rotring", col, 1.2);

  // 'O'
  fillStem(-32, topY + 6, -22, botY - 6);
  fillStem(-2, topY + 6, 8, botY - 6);
  npLine(-28, botY, 4, botY, "rotring", col, 1.2);

  // 'U'
  fillStem(22, topY, 32, botY - 8);
  fillStem(50, topY, 60, botY - 8);
  npLine(25, botY, 57, botY, "rotring", col, 1.2);

  // 'R'
  fillStem(74, topY, 84, botY);
  npLine(84, -200, 104, -200, "rotring", col, 1.1);
  fillStem(98, topY + 5, 106, -200);
  for (let s = 0; s <= 6; s += 1.5) {
    npLine(86 + s, -200, 104 + s, botY, "rotring", col, 0.85);
  }

  // 'N'
  fillStem(122, topY, 130, botY);
  for (let s = 0; s <= 7; s += 1.5) {
    npLine(126 + s, topY, 152 + s, botY, "rotring", col, 0.85);
  }
  fillStem(154, topY, 160, botY);

  // 'A' (partially on right edge)
  for (let s = 0; s <= 5; s += 1.5) {
    npLine(178 + s, topY, 166 + s, botY, "rotring", col, 0.8);
  }
  npLine(170, -192, 188, -192, "rotring", col, 1.0);
}

function drawBlockHeadline(npLine, x1, y, x2, h, col) {
  let x = x1;
  while (x < x2 - 5) {
    let w = random(4, 9);
    if (x + w > x2) break;
    // Vertical strokes simulating condensed headline capitals
    npLine(x, y, x, y + h, "rotring", col, 0.78);
    npLine(x + w * 0.65, y, x + w * 0.65, y + h, "rotring", col, 0.65);
    npLine(x, y, x + w * 0.65, y, "rotring", col, 0.6);
    if (random() < 0.6) {
      npLine(x, y + h * 0.5, x + w * 0.55, y + h * 0.5, "rotring", col, 0.55);
    }
    if (random() < 0.5) {
      npLine(x, y + h, x + w * 0.65, y + h, "rotring", col, 0.6);
    }
    x += w + random(2.5, 4.5);
  }
}

// ============================================================================
// 5. SCRAP 3: STRIPED CAFÉ MENU ("CAFÉ DU COMMERCE")
// ============================================================================
function drawCafeMenuScrap() {
  let cx = 790, cy = 765, ang = -17.5;

  // 1. Thick cardstock cast shadow
  drawTrompeLoeilShadow(menuPoly, 12, 14, 5, "#19140e", "#453828");

  // 2. Heavy woven cream cardstock base
  washShapePts(menuPoly, "#ece1cc", 252);
  fillShapePts(menuPoly, "#dfd1b6", 95, 0.04, 0.45);

  const menuLine = (lx1, ly1, lx2, ly2, br, col, wt) => {
    let p1 = rotPt(lx1 + cx, ly1 + cy, cx, cy, ang);
    let p2 = rotPt(lx2 + cx, ly2 + cy, cx, cy, ang);
    drawClippedLine(p1[0], p1[1], p2[0], p2[1], menuPoly, br, col, wt);
  };

  // 3. Regimental Café Menu Stripes (Faded Bordeaux-Rust & Slate-Olive)
  let stripeIdx = 0;
  for (let lx = -156; lx <= 156; lx += 22) {
    let isBordeaux = stripeIdx % 2 === 0;
    let sCol = isBordeaux ? "#7d352a" : "#615c4e";
    let w = isBordeaux ? 9.5 : 6.5;

    for (let sx = lx; sx <= lx + w; sx += 2.1) {
      // Leave central rectangular cartouche unstriped (`x: -102..102, y: -118..112`)
      if (sx > -102 && sx < 102) {
        menuLine(sx, -188, sx, -118, "cpencil", sCol, 0.72);
        menuLine(sx, 112, sx, 188, "cpencil", sCol, 0.72);
      } else {
        menuLine(sx, -188, sx, 188, "cpencil", sCol, 0.72);
      }
    }
    // Fine flanking hairline pin-stripes
    if (lx - 3.5 < -102 || lx - 3.5 > 102) {
      menuLine(lx - 3.5, -188, lx - 3.5, 188, "rotring", sCol, 0.42);
      menuLine(lx + w + 3.5, -188, lx + w + 3.5, 188, "rotring", sCol, 0.42);
    } else {
      menuLine(lx - 3.5, -188, lx - 3.5, -118, "rotring", sCol, 0.42);
      menuLine(lx - 3.5, 112, lx - 3.5, 188, "rotring", sCol, 0.42);
      menuLine(lx + w + 3.5, -188, lx + w + 3.5, -118, "rotring", sCol, 0.42);
      menuLine(lx + w + 3.5, 112, lx + w + 3.5, 188, "rotring", sCol, 0.42);
    }
    stripeIdx++;
  }

  // 4. Central Framed Menu Cartouche
  let cartLocal = [[-102, -118], [102, -118], [102, 112], [-102, 112]];
  let cartGlobal = transformPoly(cartLocal, cx, cy, ang);
  washShapePts(cartGlobal, "#f2e8d5", 248);

  // Double ornamental border in bordeaux-brown ink
  let bInk = "#54221a";
  let vInk = "#3b262e"; // vintage violet-brown café ink
  menuLine(-102, -118, 102, -118, "rotring", bInk, 0.9);
  menuLine(-102, 112, 102, 112, "rotring", bInk, 0.9);
  menuLine(-102, -118, -102, 112, "rotring", bInk, 0.9);
  menuLine(102, -118, 102, 112, "rotring", bInk, 0.9);

  menuLine(-96, -112, 96, -112, "rotring", bInk, 0.5);
  menuLine(-96, 106, 96, 106, "rotring", bInk, 0.5);
  menuLine(-96, -112, -96, 106, "rotring", bInk, 0.5);
  menuLine(96, -112, 96, 106, "rotring", bInk, 0.5);

  // Corner rosettes
  for (let cxr of [-90, 90]) {
    for (let cyr of [-106, 100]) {
      let rp = rotPt(cxr + cx, cyr + cy, cx, cy, ang);
      brush.set("rotring", bInk, 0.65);
      brush.circle(rp[0], rp[1], 3.5, 0.2);
    }
  }

  // Cartouche Title: "CAFÉ DU COMMERCE" & "VINS & LIQUEURS"
  drawBlockHeadline(menuLine, -78, -94, 78, 10, bInk);
  drawBlockHeadline(menuLine, -52, -74, 52, 6, vInk);
  menuLine(-65, -58, 65, -58, "rotring", bInk, 0.6);
  let dm = rotPt(cx, -58 + cy, cx, cy, ang);
  brush.set("rotring", bInk, 0.7);
  brush.circle(dm[0], dm[1], 3, 0.1);

  // Menu items with dotted leader lines and prices on the right
  let menuYs = [-38, -14, 10, 34, 58, 82];
  for (let i = 0; i < menuYs.length; i++) {
    let my = menuYs[i];
    let nameEnd = -82 + random(52, 85);
    drawBlockHeadline(menuLine, -84, my - 5, nameEnd, 5.5, vInk);
    // Dotted leaders
    for (let dx = nameEnd + 6; dx < 52; dx += 6) {
      menuLine(dx, my, dx + 1.5, my, "rotring", vInk, 0.55);
    }
    // Price figures (e.g. "0.60", "1.25")
    menuLine(58, my - 5, 63, my, "rotring", bInk, 0.7);
    menuLine(63, my, 58, my, "rotring", bInk, 0.7);
    menuLine(67, my - 1, 68.5, my, "rotring", bInk, 0.7);
    menuLine(73, my - 5, 79, my - 5, "rotring", bInk, 0.7);
    menuLine(74, my - 5, 74, my, "rotring", bInk, 0.7);
    menuLine(74, my, 79, my, "rotring", bInk, 0.7);
  }

  // Waiter's handwritten pencil addition in lower-right margin of menu
  menuLine(38, 128, 78, 125, "HB", "#403c36", 0.65);
  menuLine(42, 138, 72, 136, "HB", "#403c36", 0.65);
  menuLine(34, 145, 82, 143, "HB", "#403c36", 0.75);
  menuLine(45, 155, 76, 152, "HB", "#403c36", 0.8);

  // 5. Dog-Eared Top-Left Corner Flap & Shadow
  let dogShadow = offsetPoly(menuDogEarPoly, 5, 6);
  washShapePts(dogShadow, "#2e2419", 145);
  washShapePts(menuDogEarPoly, "#e3d6bc", 250);
  strokeShapePts(menuDogEarPoly, "HB", "#8a7b62", 0.65);
  brush.set("pastel_chalk", "#fbf4e6", 0.9);
  brush.line(menuDogEarPoly[0][0], menuDogEarPoly[0][1], menuDogEarPoly[2][0], menuDogEarPoly[2][1]);

  // 6. Heavy Cardstock Bevel & Torn Bottom Fibres
  drawPaperBevelAndFibres(menuPoly, "#fcf6e8", "#4d3c2b", 3, 8);
}

// ============================================================================
// 6. SCRAP 4: TRANSLUCENT BLUE TISSUE PAPER (PAPIER DE SOIE BLEU)
// ============================================================================
function drawBlueTissueScrap() {
  let cx = 515, cy = 585, ang = 5.5;

  // 1. Subtle delicate shadow around the perimeter of thin tissue
  drawTrompeLoeilShadow(blueTissuePoly, 4, 5, 2, "#1c2630", "#3b4c5e");

  // 2. Semi-transparent Prussian / Cerulean-Slate Tissue Washes
  washShapePts(blueTissuePoly, "#476985", 168);
  fillShapePts(blueTissuePoly, "#395770", 110, 0.08, 0.55);
  fillShapePts(blueTissuePoly, "#5c809e", 65, 0.12, 0.45);

  // 3. TROMPE-L'OEIL TRANSLUCENCY: Re-render ghosted continuations of underlying layers
  //    inside the blue tissue polygon so it genuinely reads as semi-transparent!

  // (a) Ghosted continuation of the Black Plane's bottom & right edges inside tissue
  let bp1 = [315, 650], bp2 = [725, 695], bp3 = [775, 212];
  drawClippedLine(bp1[0], bp1[1], bp2[0], bp2[1], blueTissuePoly, "charcoal", "#1f3345", 0.9);
  drawClippedLine(bp2[0], bp2[1], bp3[0], bp3[1], blueTissuePoly, "charcoal", "#1f3345", 0.9);

  // (b) Ghosted Faux-Bois right edge & vertical woodgrain lines showing through left side of tissue
  let fbCx = 390, fbCy = 520, fbAng = -7.5;
  let fbEdgeA = rotPt(122 + fbCx, 46 + fbCy, fbCx, fbCy, fbAng);
  let fbEdgeB = rotPt(122 + fbCx, 285 + fbCy, fbCx, fbCy, fbAng);
  drawClippedLine(fbEdgeA[0], fbEdgeA[1], fbEdgeB[0], fbEdgeB[1], blueTissuePoly, "HB", "#284359", 0.85);

  for (let lx = -20; lx <= 118; lx += 8.5) {
    let pA = rotPt(lx + fbCx, -90 + fbCy, fbCx, fbCy, fbAng);
    let pB = rotPt(lx + fbCx, 280 + fbCy, fbCx, fbCy, fbAng);
    drawClippedLine(pA[0], pA[1], pB[0], pB[1], blueTissuePoly, "wood_comb", "#2a475e", 0.48);
  }

  // (c) Ghosted Newspaper left edge, column rule, and text lines showing through right side of tissue
  let npCx = 660, npCy = 485, npAng = 13.5;
  let npLeftA = rotPt(-190 + npCx, -40 + npCy, npCx, npCy, npAng);
  let npLeftB = rotPt(-196 + npCx, 225 + npCy, npCx, npCy, npAng);
  drawClippedLine(npLeftA[0], npLeftA[1], npLeftB[0], npLeftB[1], blueTissuePoly, "HB", "#6889a6", 0.85);

  let npRuleA = rotPt(-93 + npCx, -40 + npCy, npCx, npCy, npAng);
  let npRuleB = rotPt(-93 + npCx, 225 + npCy, npCx, npCy, npAng);
  drawClippedLine(npRuleA[0], npRuleA[1], npRuleB[0], npRuleB[1], blueTissuePoly, "rotring", "#263f54", 0.5);

  for (let ly = -10; ly <= 215; ly += 6.5) {
    let tA = rotPt(-180 + npCx, ly + npCy, npCx, npCy, npAng);
    let tB = rotPt(-98 + npCx, ly + npCy, npCx, npCy, npAng);
    drawClippedLine(tA[0], tA[1], tB[0], tB[1], blueTissuePoly, "rotring", "#2b465c", 0.42);
  }

  // 4. Crinkled Tissue Paper Crease Network & Paste Blisters
  let creases = [
    [-145, -95, 125, 65, 14],
    [-120, 85, 140, -75, -16],
    [-45, -120, 35, 115, 11],
    [-150, 10, 45, -95, -9],
    [-15, 20, 145, 95, 12],
    [-95, -115, -25, 105, -10],
    [30, -110, 135, 25, 8]
  ];
  for (let cr of creases) {
    let p1 = rotPt(cr[0] + cx, cr[1] + cy, cx, cy, ang);
    let p2 = rotPt(cr[2] + cx, cr[3] + cy, cx, cy, ang);
    drawGlueWrinkle(p1[0], p1[1], p2[0], p2[1], cr[4], blueTissuePoly, "#b8d2e8", "#1d3245");
  }

  // Fine branching micro-crinkles in pale sky-blue and deep indigo
  for (let i = 0; i < 42; i++) {
    let lx1 = random(-145, 135);
    let ly1 = random(-115, 110);
    let len = random(18, 52);
    let a = random(0, 360);
    let lx2 = lx1 + Math.cos((a * Math.PI) / 180) * len;
    let ly2 = ly1 + Math.sin((a * Math.PI) / 180) * len;
    let p1 = rotPt(lx1 + cx, ly1 + cy, cx, cy, ang);
    let p2 = rotPt(lx2 + cx, ly2 + cy, cx, cy, ang);
    drawClippedLine(p1[0], p1[1], p2[0], p2[1], blueTissuePoly, "2H", i % 2 === 0 ? "#a9c7e0" : "#223a4f", 0.55);
  }

  // 5. Feathered Translucent Blue & White Tissue Fibres Along Torn Edges
  for (let i = 0; i < blueTissuePoly.length; i++) {
    let a = blueTissuePoly[i];
    let b = blueTissuePoly[(i + 1) % blueTissuePoly.length];
    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    let len = Math.hypot(dx, dy);
    let nx = dy / len;
    let ny = -dx / len;
    let steps = Math.floor(len / 4);
    for (let k = 0; k <= steps; k++) {
      let t = k / steps;
      let px = a[0] + dx * t;
      let py = a[1] + dy * t;
      let fl = random(3, 10);
      let fa = Math.atan2(ny, nx) + random(-0.6, 0.6);
      brush.set("fine_hair", k % 3 === 0 ? "#c2d9ed" : "#567b99", random(0.4, 0.75));
      brush.line(px, py, px + Math.cos(fa) * fl, py + Math.sin(fa) * fl);
    }
  }
}

// ============================================================================
// 7. STEMMED GLASS OUTLINED IN LOOSE CHARCOAL & WHITE CHALK
// ============================================================================
function drawCharcoalGlass() {
  // Centered around (615, 375), bridging the black plane, newspaper, faux-bois, and blue tissue
  let gx = 615, gy = 375;

  // 1. Soft smudged charcoal & white chalk tonal planes inside the Cubist glass
  let glassHighlightLeft = [
    [gx - 78, gy - 155],
    [gx - 22, gy - 150],
    [gx - 15, gy - 12],
    [gx - 52, gy - 18]
  ];
  fillShapePts(glassHighlightLeft, "#f7f1e3", 75, 0.25, 0.5);
  hatchShapePts(glassHighlightLeft, "pastel_chalk", "#f5eedf", 0.65, 6.5, 84, { rand: 0.08 });

  let glassShadowRight = [
    [gx + 8, gy - 148],
    [gx + 82, gy - 140],
    [gx + 48, gy - 8],
    [gx + 5, gy - 12]
  ];
  fillShapePts(glassShadowRight, "#1c1a17", 70, 0.25, 0.6);
  hatchShapePts(glassShadowRight, "charcoal", "#1f1d1a", 0.65, 6, 75, { rand: 0.1 });

  let footShade = [
    [gx - 68, gy + 178],
    [gx + 75, gy + 185],
    [gx + 58, gy + 206],
    [gx - 55, gy + 198]
  ];
  fillShapePts(footShade, "#24211e", 65, 0.2, 0.5);

  // 2. Loose, Expressive Vine Charcoal Outlines (Multi-pass Cubist + Observational)
  const charcoalEllipse = (cx, cy, rx, ry, tiltDeg, passes = 2, weight = 1.15) => {
    for (let p = 0; p < passes; p++) {
      let pts = [];
      let startA = random(-15, 15);
      for (let a = startA; a <= startA + 370; a += 18) {
        let rad = (a * Math.PI) / 180;
        let lx = Math.cos(rad) * rx + random(-1.8, 1.8);
        let ly = Math.sin(rad) * ry + random(-1.4, 1.4);
        pts.push(rotPt(lx + cx, ly + cy, cx, cy, tiltDeg));
      }
      brush.set("charcoal", p === 0 ? "#141311" : "#292623", weight * (p === 0 ? 1.0 : 0.72));
      brush.spline(pts, 0.5);
    }
  };

  // Top Rim Ellipse (tilted slightly, bold double charcoal pass + white chalk lip)
  charcoalEllipse(gx + 2, gy - 152, 84, 24, -3.5, 3, 1.25);
  brush.set("pastel_chalk", "#fbf6ea", 1.1);
  brush.arc(gx + 2, gy - 152, 78, 165, 295);

  // Inner Liquid / Absinthe Meniscus Ellipse & Cubist Displaced Rim Line
  charcoalEllipse(gx - 4, gy - 78, 66, 16, -2, 2, 0.9);
  brush.set("pastel_chalk", "#f5efe2", 0.85);
  brush.line(gx - 68, gy - 80, gx + 15, gy - 72);

  // Bowl Sides (Left curve & Right faceted Cubist curve)
  let leftBowl1 = [
    [gx - 82, gy - 154],
    [gx - 72, gy - 85],
    [gx - 54, gy - 22],
    [gx - 18, gy + 12]
  ];
  let leftBowl2 = [
    [gx - 78, gy - 150],
    [gx - 66, gy - 82],
    [gx - 48, gy - 18],
    [gx - 12, gy + 15]
  ];
  brush.set("charcoal", "#121110", 1.45);
  brush.spline(leftBowl1, 0.45);
  brush.set("charcoal", "#2b2824", 0.9);
  brush.spline(leftBowl2, 0.45);

  let rightBowl1 = [
    [gx + 85, gy - 146],
    [gx + 72, gy - 78],
    [gx + 50, gy - 16],
    [gx + 16, gy + 14]
  ];
  brush.set("charcoal", "#121110", 1.35);
  brush.spline(rightBowl1, 0.45);
  // Analytical/Synthetic Cubist vertical & diagonal facet lines cutting through the bowl
  brush.set("charcoal", "#1f1d1a", 1.05);
  brush.line(gx - 28, gy - 174, gx - 16, gy + 162);
  brush.line(gx + 26, gy - 168, gx + 12, gy + 155);
  brush.set("2B", "#2e2b27", 0.75);
  brush.line(gx - 95, gy - 78, gx + 92, gy - 88);

  // Fluted Bistro Glass Ribs at Bottom of Bowl
  for (let fx = -42; fx <= 42; fx += 16) {
    brush.set("charcoal", "#211f1c", 0.85);
    brush.line(gx + fx * 1.15, gy - 58, gx + fx * 0.45, gy + 8);
    if (fx < 0) {
      brush.set("pastel_chalk", "#f5eedf", 0.75);
      brush.line(gx + fx * 1.15 + 3, gy - 54, gx + fx * 0.45 + 2, gy + 4);
    }
  }

  // Stem & Faceted Baluster Knop
  charcoalEllipse(gx, gy + 36, 25, 9, -2, 2, 1.1);
  charcoalEllipse(gx + 1, gy + 54, 21, 7, -2, 2, 0.95);
  brush.set("pastel_chalk", "#faf4e6", 0.95);
  brush.circle(gx - 9, gy + 35, 6, 0.3);

  brush.set("charcoal", "#141311", 1.35);
  brush.line(gx - 14, gy + 12, gx - 12, gy + 168);
  brush.line(gx + 15, gy + 14, gx + 14, gy + 170);
  brush.set("pastel_chalk", "#f7f0e1", 1.0);
  brush.line(gx - 9, gy + 58, gx - 8, gy + 162);

  // Conical Foot & Base Rim Ellipse
  brush.set("charcoal", "#171513", 1.25);
  brush.line(gx - 12, gy + 148, gx - 68, gy + 184);
  brush.line(gx + 14, gy + 150, gx + 72, gy + 188);
  charcoalEllipse(gx + 2, gy + 188, 72, 21, -2, 3, 1.3);
  brush.set("pastel_chalk", "#fbf5e8", 1.05);
  brush.arc(gx + 2, gy + 188, 68, 150, 275);

  // 3. Crumbling Charcoal Dust Specks around heavy strokes
  for (let i = 0; i < 55; i++) {
    let sx = gx + random(-95, 95);
    let sy = gy + random(-175, 205);
    brush.set("spray", "#171513", random(0.35, 0.8));
    brush.circle(sx, sy, random(1.5, 4.5), 0.3);
  }
}

// ============================================================================
// 8. HYPERREAL CRUMPLED MATCHBOOK & LOOSE HALF-BURNT MATCHSTICK
// ============================================================================
function drawCrumpledMatchbook() {
  let mx = 375, my = 815, mang = 21;

  // 1. Deep 3D Contact Shadow & Soft Penumbra under the Bent Matchbook
  let mbShadowOuter = transformPoly(
    [[-65, -75], [68, -68], [82, 85], [-55, 92]],
    mx + 14, my + 18, mang
  );
  drawTrompeLoeilShadow(mbShadowOuter, 6, 8, 4, "#17130d", "#3d3325");

  let mbContactShadow = transformPoly(
    [[-58, -65], [58, -58], [66, 72], [-48, 78]],
    mx + 5, my + 7, mang
  );
  washShapePts(mbContactShadow, "#14100b", 215);

  // 2. Open Back Cover Flap (Bent in 3D perspective with a center crease)
  let backCoverUpper = transformPoly(
    [[-58, -82], [52, -76], [56, -12], [-54, -18]],
    mx, my, mang
  );
  let backCoverLower = transformPoly(
    [[-54, -18], [56, -12], [62, 55], [-50, 62]],
    mx, my, mang
  );
  // Outer red-ochre and buff cover peeking at top crest
  let topCrest = transformPoly(
    [[-56, -92], [50, -86], [52, -76], [-58, -82]],
    mx, my, mang
  );
  washShapePts(topCrest, "#8c2f20", 245);

  // Inner cardboard of open matchbook
  washShapePts(backCoverUpper, "#dfd0b4", 248);
  fillShapePts(backCoverUpper, "#c9b796", 95, 0.05, 0.45);
  washShapePts(backCoverLower, "#c7b595", 248);
  fillShapePts(backCoverLower, "#ad9b7a", 110, 0.05, 0.5);

  // Sharp crimp crease across the open back flap
  let crA = rotPt(-54 + mx, -18 + my, mx, my, mang);
  let crB = rotPt(56 + mx, -12 + my, mx, my, mang);
  drawGlueWrinkle(crA[0], crA[1], crB[0], crB[1], -5, backCoverUpper.concat(backCoverLower), "#f7ebd2", "#756449");

  strokeShapePts(backCoverUpper, "HB", "#6e5d44", 0.7);
  strokeShapePts(backCoverLower, "HB", "#594a34", 0.75);

  // 3. Inside Cardboard Match Comb (3 Torn Stubs on Left, 4 Full Matchsticks on Right)
  let combBase = transformPoly(
    [[-48, 18], [50, 22], [52, 52], [-46, 48]],
    mx, my, mang
  );
  washShapePts(combBase, "#e6d2a8", 248);
  strokeShapePts(combBase, "2H", "#9e8962", 0.6);

  let slotXs = [-40, -26, -12, 2, 16, 30, 43];
  for (let i = 0; i < slotXs.length; i++) {
    let sx = slotXs[i];
    if (i < 3) {
      // Torn match stub with ragged white paper fibres
      let stub = transformPoly(
        [[sx - 4.5, 20], [sx + 4.5, 16 + (i % 2) * 4], [sx + 4.5, 32], [sx - 4.5, 32]],
        mx, my, mang
      );
      washShapePts(stub, "#efe3c7", 245);
      let stTop = rotPt(sx + mx, 18 + my, mx, my, mang);
      for (let f = 0; f < 4; f++) {
        brush.set("fine_hair", "#fbf3e1", 0.65);
        brush.line(stTop[0] + random(-3, 3), stTop[1], stTop[0] + random(-4, 4), stTop[1] - random(4, 8));
      }
    } else {
      // Standing cardboard matchstick angled slightly and casting a shadow onto the back flap
      let tilt = (i - 4.5) * 2.2;
      let topY = -46 + (i % 2) * 5;
      let mShadow = transformPoly(
        [[sx - 2 + tilt, topY + 3], [sx + 6 + tilt, topY + 3], [sx + 6, 24], [sx - 2, 24]],
        mx, my, mang
      );
      washShapePts(mShadow, "#7d6b4f", 145);

      let stick = transformPoly(
        [[sx - 4 + tilt, topY], [sx + 4 + tilt, topY], [sx + 4.2, 24], [sx - 4.2, 24]],
        mx, my, mang
      );
      washShapePts(stick, "#ebd7ad", 252);
      // Shaded right edge & lit left edge of cardboard stem
      let sL1 = rotPt(sx - 4 + tilt + mx, topY + my, mx, my, mang);
      let sL2 = rotPt(sx - 4.2 + mx, 24 + my, mx, my, mang);
      let sR1 = rotPt(sx + 4 + tilt + mx, topY + my, mx, my, mang);
      let sR2 = rotPt(sx + 4.2 + mx, 24 + my, mx, my, mang);
      brush.set("2H", "#fbf1dc", 0.75);
      brush.line(sL1[0], sL1[1], sL2[0], sL2[1]);
      brush.set("HB", "#a89167", 0.7);
      brush.line(sR1[0], sR1[1], sR2[0], sR2[1]);

      // Bulbous sulfur-red phosphorus match head
      let headPt = rotPt(sx + tilt + mx, topY - 3 + my, mx, my, mang);
      let headPoly = transformPoly(
        [
          [sx - 5.2 + tilt, topY + 2],
          [sx - 5.8 + tilt, topY - 6],
          [sx + tilt, topY - 11],
          [sx + 5.8 + tilt, topY - 6],
          [sx + 5.2 + tilt, topY + 2]
        ],
        mx, my, mang
      );
      washShapePts(headPoly, "#9c281c", 252);
      fillShapePts(headPoly, "#6e160d", 110, 0.04, 0.35);
      brush.set("cpencil", "#c94636", 0.8);
      brush.circle(headPt[0] - 1.5, headPt[1] - 1.5, 3.8, 0.2);
      brush.set("pastel_chalk", "#f5a090", 0.65);
      brush.circle(headPt[0] - 2.2, headPt[1] - 2.5, 1.8, 0.1);
    }
  }

  // 4. Crumpled Front Flap & Gritty Phosphorus Striker Strip at Bottom
  let frontFlap = transformPoly(
    [[-52, 34], [54, 38], [60, 76], [-48, 72]],
    mx, my, mang
  );
  washShapePts(frontFlap, "#9e3625", 250);
  fillShapePts(frontFlap, "#782316", 115, 0.05, 0.45);

  // Diagonal crumple crease across the red front flap
  let fc1 = rotPt(-48 + mx, 58 + my, mx, my, mang);
  let fc2 = rotPt(52 + mx, 42 + my, mx, my, mang);
  drawGlueWrinkle(fc1[0], fc1[1], fc2[0], fc2[1], 4, frontFlap, "#d46a57", "#4a120a");

  // Metal staple pinning the matchbook base
  let st1 = rotPt(-6 + mx, 44 + my, mx, my, mang);
  let st2 = rotPt(8 + mx, 45 + my, mx, my, mang);
  brush.set("rotring", "#2b241e", 1.1);
  brush.line(st1[0], st1[1] + 1.5, st2[0], st2[1] + 1.5);
  brush.set("pastel_chalk", "#d8d2c5", 0.85);
  brush.line(st1[0], st1[1], st2[0], st2[1]);

  // Dark Gritty Phosphorus Striker Strip with Spark Scratches
  let strikerPoly = transformPoly(
    [[-49, 58], [57, 62], [59, 75], [-47, 71]],
    mx, my, mang
  );
  washShapePts(strikerPoly, "#2b1d1a", 252);
  hatchShapePts(strikerPoly, "charcoal", "#1c1210", 0.6, 3.2, 15, { rand: 0.12 });
  // Diagonal white/buff friction strike marks across the striker strip
  for (let s = -32; s <= 36; s += 14) {
    let sc1 = rotPt(s + mx, 61 + my, mx, my, mang);
    let sc2 = rotPt(s + 14 + mx, 71 + my, mx, my, mang);
    brush.set("2H", "#c4b299", 0.55);
    brush.line(sc1[0], sc1[1], sc2[0], sc2[1]);
  }

  // 5. Loose Half-Burnt Matchstick Lying Nearby on the Olive Plane
  let lmx = 485, lmy = 905, lmang = -32;
  // Tiny cast shadow beneath the loose match
  let lmShadow = transformPoly([[-42, 3], [36, 5], [36, 11], [-42, 9]], lmx, lmy, lmang);
  washShapePts(lmShadow, "#17140e", 195);

  // Unburned cardboard half (left)
  let lmWood = transformPoly([[-42, -3.5], [4, -3.5], [4, 3.5], [-42, 3.5]], lmx, lmy, lmang);
  washShapePts(lmWood, "#e6d1a5", 252);
  let lwA = rotPt(-42 + lmx, -3.5 + lmy, lmx, lmy, lmang);
  let lwB = rotPt(4 + lmx, -3.5 + lmy, lmx, lmy, lmang);
  brush.set("2H", "#fbf1dc", 0.75);
  brush.line(lwA[0], lwA[1], lwB[0], lwB[1]);

  // Scorched amber transition zone
  let lmScorch = transformPoly([[0, -3.5], [16, -3.2], [16, 3.2], [0, 3.5]], lmx, lmy, lmang);
  washShapePts(lmScorch, "#7d451b", 235);

  // Curled blackened char end & burnt bulbous head (right)
  let lmChar = transformPoly(
    [[14, -3.2], [28, -5.5], [39, -9.5], [41, -3.5], [29, 0.5], [14, 3.2]],
    lmx, lmy, lmang
  );
  washShapePts(lmChar, "#171514", 252);
  strokeShapePts(lmChar, "charcoal", "#0f0e0d", 0.75);
  let burntHead = rotPt(39 + lmx, -6.5 + lmy, lmx, lmy, lmang);
  brush.set("charcoal", "#12100f", 0.95);
  brush.circle(burntHead[0], burntHead[1], 4.8, 0.3);
  brush.set("pastel_chalk", "#9e988e", 0.65);
  brush.circle(burntHead[0] - 1, burntHead[1] - 1, 2.2, 0.2);
}

// ============================================================================
// 9. HYPERREAL HALF-SMOKED CIGAR WITH A CURL OF ASH
// ============================================================================
function drawHyperrealCigar() {
  // Cigar spans from burning tip at left (~515, 765) to clipped cap at right (~890, 710)
  // Centerline function for the unburned tobacco barrel (t in [0, 1], x: 612..888)
  const barrelPt = (t, rOffset = 0) => {
    let x = 612 + t * 276;
    let y = 762 - t * 52;
    // Slight natural taper at the right cap (t > 0.82)
    let radius = 28.5;
    if (t > 0.82) {
      let u = (t - 0.82) / 0.18;
      radius = 28.5 * Math.sqrt(Math.max(0.04, 1 - u * u * 0.92));
    }
    // Normal vector to barrel axis (-52, -276) normalized
    let nx = -0.185;
    let ny = -0.983;
    return [x + nx * rOffset * radius, y + ny * rOffset * radius, radius];
  };

  // Centerline function for the upward-curling ash (s in [0, 1], from char line s=0 leftward to s=1)
  const ashPt = (s, rOffset = 0) => {
    // Curves leftward and distinctly UPWARD in a precarious cigar-ash curl
    let x = 612 - s * 92 + s * s * 14;
    let y = 762 - s * 12 - Math.pow(s, 1.85) * 34;
    // Tangent & normal
    let dx = -92 + 28 * s;
    let dy = -12 - 1.85 * Math.pow(Math.max(0.01, s), 0.85) * 34;
    let len = Math.hypot(dx, dy);
    let nx = dy / len;  // points upward-right
    let ny = -dx / len; // points upward
    let radius = 27.5 * (1 - s * 0.22) + Math.sin(s * 18) * 1.4;
    return [x + nx * rOffset * radius, y + ny * rOffset * radius, radius, nx, ny];
  };

  // --- 1. MULTI-LAYERED 3D CAST SHADOW ONTO MENU, NEWSPAPER & BLUE TISSUE ---
  let fullShadowPoly = [];
  for (let s = 1; s >= 0; s -= 0.12) {
    let p = ashPt(s, -1.0);
    fullShadowPoly.push([p[0] + 15, p[1] + 24]);
  }
  for (let t = 0; t <= 1; t += 0.08) {
    let p = barrelPt(t, -1.0);
    fullShadowPoly.push([p[0] + 14, p[1] + 21]);
  }
  for (let t = 1; t >= 0; t -= 0.08) {
    let p = barrelPt(t, 0.75);
    fullShadowPoly.push([p[0] + 14, p[1] + 21]);
  }
  for (let s = 0; s <= 1; s += 0.12) {
    let p = ashPt(s, 0.7);
    fullShadowPoly.push([p[0] + 15, p[1] + 24]);
  }

  // Soft outer penumbra layers
  drawTrompeLoeilShadow(fullShadowPoly, 6, 8, 5, "#17120c", "#423424");
  washShapePts(fullShadowPoly, "#1f1810", 165);

  // Tight dark umber-black contact shadow directly under the cigar belly
  let contactShadowPoly = [];
  for (let t = 0; t <= 0.96; t += 0.08) {
    let p = barrelPt(t, -0.55);
    contactShadowPoly.push([p[0] + 4, p[1] + 6]);
  }
  for (let t = 0.96; t >= 0; t -= 0.08) {
    let p = barrelPt(t, -1.08);
    contactShadowPoly.push([p[0] + 7, p[1] + 11]);
  }
  washShapePts(contactShadowPoly, "#120d08", 238);
  hatchShapePts(contactShadowPoly, "charcoal", "#0d0905", 0.7, 3.5, -11, { rand: 0.05 });

  // --- 2. FALLEN ASH FLAKES ON THE BLUE TISSUE & NEWSPAPER BELOW ---
  for (let i = 0; i < 28; i++) {
    let fx = random(505, 625);
    let fy = random(765, 835);
    let r = random(1.8, 5.5);
    // Tiny shadow under flake
    brush.set("2B", "#1c2229", 0.65);
    brush.circle(fx + 1.5, fy + 1.8, r, 0.35);
    // Chalky grey-white ash crumb
    brush.set("pastel_chalk", i % 2 === 0 ? "#d9d4ca" : "#9e988e", random(0.55, 0.95));
    brush.circle(fx, fy, r, 0.4);
  }

  // --- 3. CIGAR BARREL (VOLUMETRIC HAVANA MADURO TOBACCO WRAPPER) ---
  let barrelOutline = [];
  for (let t = 0; t <= 1; t += 0.05) {
    let p = barrelPt(t, 1.0);
    barrelOutline.push([p[0], p[1]]);
  }
  for (let t = 1; t >= 0; t -= 0.05) {
    let p = barrelPt(t, -1.0);
    barrelOutline.push([p[0], p[1]]);
  }
  washShapePts(barrelOutline, "#59331a", 252);
  fillShapePts(barrelOutline, "#472611", 130, 0.03, 0.5);

  // Longitudinal cylindrical shading passes from top edge (+1.0) to bottom edge (-1.0)
  let rBands = [
    { r: 0.94, col: "#7a4d2b", wt: 0.85, br: "cpencil" },     // top rim reflected light
    { r: 0.80, col: "#9c673f", wt: 1.05, br: "cpencil" },     // upper highlight shoulder
    { r: 0.64, col: "#c28b5e", wt: 1.15, br: "pastel_chalk" },// warm tobacco-oil specular ridge
    { r: 0.50, col: "#ab7448", wt: 1.0, br: "cpencil" },
    { r: 0.32, col: "#7d4b27", wt: 1.1, br: "cpencil" },      // rich mahogany midtone
    { r: 0.12, col: "#663a1c", wt: 1.15, br: "cpencil" },
    { r: -0.08, col: "#4f2a12", wt: 1.2, br: "cpencil" },
    { r: -0.28, col: "#3b1e0b", wt: 1.25, br: "2B" },         // upper core shadow
    { r: -0.48, col: "#261206", wt: 1.35, br: "charcoal" },   // deepest core shadow
    { r: -0.68, col: "#1f0e04", wt: 1.25, br: "charcoal" },
    { r: -0.84, col: "#3d2210", wt: 0.95, br: "cpencil" },    // warm bounce light from cream menu
    { r: -0.95, col: "#57341b", wt: 0.75, br: "cpencil" }
  ];

  for (let b of rBands) {
    let pts = [];
    for (let t = 0; t <= 0.98; t += 0.06) {
      let p = barrelPt(t, b.r + (noise(t * 6, b.r * 4) - 0.5) * 0.06);
      pts.push([p[0], p[1]]);
    }
    brush.set(b.br, b.col, b.wt);
    brush.spline(pts, 0.45);
  }

  // Helical Tobacco Leaf Wrapper Seams & Delicate Branching Veins
  let seamStarts = [0.08, 0.34, 0.64, 0.84];
  for (let t0 of seamStarts) {
    let seamPts = [];
    let highlightPts = [];
    for (let u = 0; u <= 1; u += 0.12) {
      let t = Math.min(0.97, t0 + u * 0.22);
      let r = 0.95 - u * 1.9;
      let p = barrelPt(t, r);
      seamPts.push([p[0], p[1]]);
      highlightPts.push([p[0] + 1.2, p[1] - 0.8]);
    }
    brush.set("fine_hair", "#291306", 0.8);
    brush.spline(seamPts, 0.4);
    brush.set("fine_hair", "#b88256", 0.6);
    brush.spline(highlightPts, 0.4);
  }

  // Branching organic leaf veins along the barrel
  for (let i = 0; i < 26; i++) {
    let t1 = random(0.03, 0.92);
    let r1 = random(-0.75, 0.85);
    let t2 = Math.min(0.96, t1 + random(0.05, 0.14));
    let r2 = constrain(r1 + random(-0.45, 0.45), -0.9, 0.9);
    let p1 = barrelPt(t1, r1);
    let p2 = barrelPt((t1 + t2) * 0.5, (r1 + r2) * 0.5 + random(-0.12, 0.12));
    let p3 = barrelPt(t2, r2);
    brush.set("fine_hair", r1 > 0.15 ? "#c99366" : "#331808", 0.55);
    brush.spline([[p1[0], p1[1]], [p2[0], p2[1]], [p3[0], p3[1]]], 0.5);
  }

  // Clipped Parejo Head Cap Lines on the Right End
  for (let tc of [0.90, 0.94, 0.97]) {
    let capPts = [];
    for (let r = -0.95; r <= 0.95; r += 0.25) {
      let curveT = tc + (1 - r * r) * 0.025;
      let p = barrelPt(Math.min(0.995, curveT), r);
      capPts.push([p[0], p[1]]);
    }
    brush.set("fine_hair", "#2b1407", 0.7);
    brush.spline(capPts, 0.5);
  }

  // --- 4. EMBOSSED RED & GOLD CIGAR BAND (at t = 0.50 .. 0.66) ---
  let bandPoly = [];
  let tBandL = 0.50, tBandR = 0.65;
  for (let r = -1.03; r <= 1.03; r += 0.15) {
    let curveL = tBandL + (1 - r * r) * 0.032; // cylindrical perspective curve!
    let p = barrelPt(curveL, r);
    bandPoly.push([p[0], p[1]]);
  }
  for (let r = 1.03; r >= -1.03; r -= 0.15) {
    let curveR = tBandR + (1 - r * r) * 0.032;
    let p = barrelPt(curveR, r);
    bandPoly.push([p[0], p[1]]);
  }
  washShapePts(bandPoly, "#8c1e16", 252);
  fillShapePts(bandPoly, "#5e100a", 125, 0.02, 0.35);

  // Shaded lower half of red band
  let bandDarkPoly = [];
  for (let r = -1.03; r <= -0.15; r += 0.2) {
    let p = barrelPt(tBandL + (1 - r * r) * 0.032, r);
    bandDarkPoly.push([p[0], p[1]]);
  }
  for (let r = -0.15; r >= -1.03; r -= 0.2) {
    let p = barrelPt(tBandR + (1 - r * r) * 0.032, r);
    bandDarkPoly.push([p[0], p[1]]);
  }
  washShapePts(bandDarkPoly, "#3d0905", 195);

  // Embossed Gold Borders on Left & Right of Band
  for (let tb of [tBandL, tBandL + 0.015, tBandR - 0.015, tBandR]) {
    let gPts = [];
    for (let r = -1.02; r <= 1.02; r += 0.18) {
      let p = barrelPt(tb + (1 - r * r) * 0.032, r);
      gPts.push([p[0], p[1]]);
    }
    brush.set("cpencil", "#c99b38", 0.85);
    brush.spline(gPts, 0.5);
  }

  // Central Oval Medallion on the Cigar Band (Cream, Crimson & Embossed Gold)
  let medCenter = barrelPt((tBandL + tBandR) * 0.5 + 0.028, 0.18);
  let mx0 = medCenter[0], my0 = medCenter[1];
  let medPoly = [];
  for (let a = 0; a < 360; a += 30) {
    let rad = (a * Math.PI) / 180;
    medPoly.push([mx0 + Math.cos(rad) * 14, my0 + Math.sin(rad) * 17]);
  }
  washShapePts(medPoly, "#f5e8c8", 248);
  brush.set("cpencil", "#b88928", 0.95);
  brush.circle(mx0, my0, 15, 0.15);
  brush.set("rotring", "#7a1811", 0.7);
  brush.circle(mx0, my0, 9.5, 0.15);
  // Specular gold leaf glints right along the upper cylindrical ridge (r ~ 0.6)
  let glint1 = barrelPt(tBandL + 0.02, 0.58);
  let glint2 = barrelPt((tBandL + tBandR) * 0.5 + 0.02, 0.58);
  let glint3 = barrelPt(tBandR + 0.01, 0.58);
  brush.set("pastel_chalk", "#fff3b8", 1.05);
  brush.line(glint1[0], glint1[1], glint2[0], glint2[1]);
  brush.line(glint2[0], glint2[1], glint3[0], glint3[1]);

  // --- 5. BLACKENED CHAR LINE & GLOWING ORANGE EMBER ---
  let charPoly = [];
  for (let r = -1.02; r <= 1.02; r += 0.14) {
    let p = barrelPt((noise(r * 5) - 0.5) * 0.02, r);
    charPoly.push([p[0] - 4, p[1]]);
  }
  for (let r = 1.02; r >= -1.02; r -= 0.14) {
    let p = barrelPt(0.035 + (noise(r * 5 + 10) - 0.5) * 0.02, r);
    charPoly.push([p[0], p[1]]);
  }
  washShapePts(charPoly, "#141110", 252);
  strokeShapePts(charPoly, "charcoal", "#0d0b0a", 0.95);

  // Subtle glowing orange-red ember peeking through the char crevices
  let ember1 = barrelPt(0.0, 0.15);
  let ember2 = barrelPt(0.0, -0.25);
  brush.set("cpencil", "#b82d12", 1.15);
  brush.line(ember1[0] - 3, ember1[1] - 4, ember2[0] - 2, ember2[1] + 4);
  brush.set("pastel_chalk", "#f26422", 0.95);
  brush.line(ember1[0] - 2, ember1[1] - 2, ember2[0] - 1, ember2[1] + 2);
  brush.set("pastel_chalk", "#ffb85c", 0.7);
  brush.circle((ember1[0] + ember2[0]) * 0.5 - 2, (ember1[1] + ember2[1]) * 0.5, 2.5, 0.2);

  // --- 6. THE CURL OF ASH (STRATIFIED, FLAKY ANNULAR RINGS) ---
  let ashOutline = [];
  for (let s = 0; s <= 1.0; s += 0.07) {
    let p = ashPt(s, 1.0 + (noise(s * 8, 1) - 0.5) * 0.14);
    ashOutline.push([p[0], p[1]]);
  }
  for (let s = 1.0; s >= 0; s -= 0.07) {
    let p = ashPt(s, -1.0 + (noise(s * 8, 2) - 0.5) * 0.14);
    ashOutline.push([p[0], p[1]]);
  }
  washShapePts(ashOutline, "#8c867c", 252);
  fillShapePts(ashOutline, "#706b62", 120, 0.04, 0.65);

  // Volumetric shading along the curving ash cylinder
  let ashBands = [
    { r: 0.85, col: "#e8e3d9", wt: 1.15, br: "pastel_chalk" }, // chalky bone-white top ridge
    { r: 0.60, col: "#d4cfc5", wt: 1.1, br: "pastel_chalk" },
    { r: 0.30, col: "#b5afa4", wt: 1.05, br: "cpencil" },
    { r: 0.0, col: "#918b80", wt: 1.1, br: "cpencil" },
    { r: -0.35, col: "#666158", wt: 1.15, br: "2B" },
    { r: -0.68, col: "#45413a", wt: 1.2, br: "charcoal" },     // dark ash underside
    { r: -0.90, col: "#2e2b26", wt: 1.0, br: "charcoal" }
  ];
  for (let ab of ashBands) {
    let pts = [];
    for (let s = 0.02; s <= 0.98; s += 0.08) {
      let p = ashPt(s, ab.r + (noise(s * 10, ab.r * 3) - 0.5) * 0.1);
      pts.push([p[0], p[1]]);
    }
    brush.set(ab.br, ab.col, ab.wt);
    brush.spline(pts, 0.45);
  }

  // Stratified Annular Flake Rings & Deep Radial Ash Cracks
  for (let s = 0.08; s <= 0.96; s += 0.095) {
    let ringDark = [];
    let ringLight = [];
    for (let r = -0.98; r <= 0.98; r += 0.24) {
      let jag = (noise(s * 15, r * 6) - 0.5) * 0.045;
      let pD = ashPt(s + jag, r);
      let pL = ashPt(s + jag + 0.018, r);
      ringDark.push([pD[0], pD[1]]);
      ringLight.push([pL[0], pL[1]]);
    }
    brush.set("2B", "#2b2824", 0.78);
    brush.spline(ringDark, 0.45);
    brush.set("pastel_chalk", "#f0ece2", 0.72);
    brush.spline(ringLight, 0.45);
  }

  // Crusty ash texture spray & longitudinal splits
  for (let i = 0; i < 36; i++) {
    let s = random(0.05, 0.95);
    let r = random(-0.8, 0.85);
    let p = ashPt(s, r);
    brush.set("ash_crust", r > 0 ? "#ebe6dc" : "#38342e", random(0.5, 0.95));
    brush.circle(p[0], p[1], random(2, 5), 0.35);
  }

  // Jagged hollow end crater at tip of curled ash (s = 1.0)
  let tipCenter = ashPt(0.98, 0.0);
  brush.set("charcoal", "#292622", 1.1);
  brush.circle(tipCenter[0], tipCenter[1], 11, 0.45);
  brush.set("pastel_chalk", "#f2ede4", 0.85);
  brush.arc(tipCenter[0], tipCenter[1], 13, 140, 290);

  // --- 7. DELICATE TRANSLUCENT WISP OF SMOKE ---
  let smokeRibbons = [
    [[602, 732], [584, 665], [614, 585], [588, 495], [612, 405], [595, 315]],
    [[608, 735], [594, 672], [622, 592], [596, 502], [620, 412], [602, 325]]
  ];
  for (let sr of smokeRibbons) {
    brush.set("pastel_chalk", "#d6dde3", 0.65);
    brush.spline(sr, 0.6);
    let shifted = sr.map((p) => [p[0] - 3, p[1] - 2]);
    brush.set("2H", "#ebeae4", 0.45);
    brush.spline(shifted, 0.6);
  }
}

// ============================================================================
// 10. FINAL TROMPE-L'OEIL TOUCHES (GLUE DROPLETS, PINHOLES, VIGNETTE)
// ============================================================================
function drawFinalTrompeLoeilTouches() {
  // Dried glossy gum-arabic / paste droplets squeezed out near scrap edges
  let glueDrops = [
    [548, 305, 5.5],
    [825, 425, 4.2],
    [495, 705, 4.8],
    [640, 885, 5.0]
  ];
  for (let gd of glueDrops) {
    let gx = gd[0], gy = gd[1], gr = gd[2];
    // Warm amber translucent shadow on bottom-right of droplet
    brush.set("cpencil", "#7d5b2e", 0.75);
    brush.arc(gx + 1, gy + 1, gr, -35, 135);
    // Bright white specular pinpoint on top-left of droplet
    brush.set("pastel_chalk", "#fcf7eb", 0.8);
    brush.circle(gx - gr * 0.35, gy - gr * 0.35, 1.6, 0.1);
  }

  // Tiny registration pinholes at Cubist vertices
  let pinholes = [
    [350, 175],
    [775, 212],
    [182, 975],
    [1015, 910]
  ];
  for (let ph of pinholes) {
    brush.set("rotring", "#1a1612", 0.9);
    brush.circle(ph[0], ph[1], 1.8, 0.1);
    brush.set("pastel_chalk", "#f5ebd6", 0.65);
    brush.arc(ph[0] + 0.8, ph[1] + 0.8, 2.4, -45, 135);
  }

  // Subtle double-ruled French mount border around the outer buff board
  brush.set("2H", "#9e8e74", 0.6);
  brush.rect(42, 42, 1116, 1116, "corner");
  brush.set("2H", "#b5a489", 0.42);
  brush.rect(50, 50, 1100, 1100, "corner");
}
